package com.golemsdontdie;

import java.util.*;
import java.util.function.*;

/**
 * Hands out craft numbers: which golem each was to be crafted, the number an ordinal name is made
 * of.
 *
 * <p>A number is given once and kept, saved with the golem. A new golem takes the one after the
 * highest in the roster. Golems saved before numbers were kept are numbered on their first restore,
 * oldest first, by when each was first known; one saved before even that is older than any that
 * has a date, and among themselves they keep the order of the save, which is the order they joined.
 */
final class CraftNumbers
{
	private CraftNumbers()
	{
	}

	/**
	 * Numbers every golem in the roster that has no number yet.
	 *
	 * @param age when each golem was first known, in epoch milliseconds, or 0 if that was never kept;
	 *            only the order matters
	 * @return how many golems were numbered
	 */
	static int number(List<Golem> roster, ToLongFunction<Golem> age)
	{
		int highest = 0;
		List<Golem> unnumbered = new ArrayList<>();
		for (Golem golem : roster)
		{
			if (golem.getCraftNumber() > 0)
			{
				highest = Math.max(highest, golem.getCraftNumber());
			}
			else
			{
				unnumbered.add(golem);
			}
		}
		// A stable sort: golems of the same age keep the roster's order.
		unnumbered.sort(Comparator.comparingLong(age));
		for (Golem golem : unnumbered)
		{
			golem.setCraftNumber(++highest);
		}
		return unnumbered.size();
	}
}

package com.golemsdontdie;

import java.awt.*;
import java.util.function.*;
import net.runelite.api.*;
import net.runelite.api.coords.*;

/**
 * Draws a {@link Golem} while it is inside the loaded scene.
 *
 * <p>Deliberately thin: it decides nothing about where the golem goes, only reading the
 * simulation's position each frame, and a golem that leaves the scene loses its renderer but
 * keeps walking. The pose is applied here rather than copied from a real NPC, which would need
 * an original still alive and posed every frame; the base model is the cache's rest pose, driven
 * by an {@link AnimationController} of our own.
 */
class FakeGolem extends RuneLiteObjectController
{
	/** 128ths of a tile per tile, for scene-to-local conversion. */
	private static final int TILE = Golem.TILE;

	private final Client client;
	private final Golem golem;
	private final Model baseModel;

	/** Source of the shared model and animation definitions. */
	private final GolemModelFactory shared;

	/**
	 * Drives the walk or idle loop. One controller, not the client's active-plus-pose pair:
	 * a wandering golem only ever plays one thing at a time.
	 */
	private final AnimationController animation;

	/** Which animation ID the controller currently holds, to avoid resetting it every frame. */
	private int loadedAnimationId = Integer.MIN_VALUE;

	/** How tall the golem is drawn, in the client's height units, for putting things above its head. */
	int getModelHeight()
	{
		return baseModel.getModelHeight();
	}

	FakeGolem(Client client, Golem golem, Model baseModel, GolemModelFactory shared)
	{
		this.client = client;
		this.golem = golem;
		this.baseModel = baseModel;
		this.shared = shared;
		this.animation = new AnimationController(client, -1);
		this.animation.setOnFinished(this::poseFinished);

		syncTransform();
		applyPose();
	}

	/**
	 * Called by the client once per frame while registered. Only the animation is advanced here;
	 * position is advanced centrally for every golem, including those off screen, or one would
	 * freeze on leaving the scene.
	 */
	@Override
	public void tick(int ticksSinceLastFrame)
	{
		syncTransform();
		applyPose();

		// A recording drives its own keyframes, so the client's clock must not also
		// advance them - that was the drift.
		if (golem.getMotionFrame() < 0)
		{
			animation.tick(ticksSinceLastFrame);
		}
	}

	@Override
	public Model getModel()
	{
		Model drawn = baseModel;
		if (animation.getAnimation() != null)
		{
			Model posed = animation.animate(baseModel);
			drawn = posed == null ? baseModel : posed;
		}
		measure(drawn);
		return drawn;
	}

	/**
	 * The pose last drawn, as far out from the golem's middle as it reaches and from its lowest point
	 * to its highest, in model units. Read as the client draws it: the box these make holds the pose
	 * whichever way the golem faces, so the mouse outside it is not over the golem.
	 */
	private int reach = -1;
	private int lowest;
	private int highest;

	/** The rest pose's measurement, which never changes, so it is taken once. */
	private boolean restMeasured;

	private void measure(Model model)
	{
		if (model == baseModel && restMeasured)
		{
			return;
		}
		float[] xs = model.getVerticesX();
		float[] ys = model.getVerticesY();
		float[] zs = model.getVerticesZ();
		float far = 0;
		float low = 0;
		float high = 0;
		for (int i = 0; i < model.getVerticesCount(); i++)
		{
			far = Math.max(far, xs[i] * xs[i] + zs[i] * zs[i]);
			low = Math.min(low, ys[i]);
			high = Math.max(high, ys[i]);
		}
		reach = (int) Math.ceil(Math.sqrt(far));
		lowest = (int) Math.floor(low);
		highest = (int) Math.ceil(high);
		restMeasured = model == baseModel;
	}

	/**
	 * Whether the mouse is over this golem, tested as the game tests a model it draws: inside the
	 * bounds, then inside the faces drawn this frame, by RuneLite's own reproduction of the game's
	 * picking (Perspective.getClickbox). A {@link RuneLiteObjectController} is drawn but not picked,
	 * the client building its menu from real entities, so it is done here.
	 *
	 * <p>The pose is only struck again for a golem whose bounds hold the mouse: striking every golem
	 * near the cursor each tick stalled the client. The model it returns is a shared buffer, used
	 * here at once and not kept.
	 */
	boolean isUnder(int mouseX, int mouseY)
	{
		// The world it is drawn in: aboard the player's ship, the ship's own.
		WorldView wv = golem.isAboard() ? client.getWorldView(golem.getAboardView()) : client.getTopLevelWorldView();
		if (wv == null || reach < 0)
		{
			return false;
		}
		float[] across = BOX_ACROSS;
		float[] along = BOX_ALONG;
		float[] up = BOX_UP;
		int[] screenX = BOX_X;
		int[] screenY = BOX_Y;
		for (int i = 0; i < 8; i++)
		{
			across[i] = (i & 1) == 0 ? -reach : reach;
			along[i] = (i & 2) == 0 ? -reach : reach;
			up[i] = i < 4 ? lowest : highest;
		}
		Perspective.modelToCanvas(client, wv, 8, getX(), getY(), getZ(), 0, across, along, up, screenX, screenY);
		int left = Integer.MAX_VALUE;
		int right = Integer.MIN_VALUE;
		int top = Integer.MAX_VALUE;
		int bottom = Integer.MIN_VALUE;
		boolean whole = true;
		for (int i = 0; i < 8; i++)
		{
			whole &= screenX[i] != Integer.MIN_VALUE && screenY[i] != Integer.MIN_VALUE;
			left = Math.min(left, screenX[i]);
			right = Math.max(right, screenX[i]);
			top = Math.min(top, screenY[i]);
			bottom = Math.max(bottom, screenY[i]);
		}
		// The game lets a face out by this many pixels each way; a corner behind the camera bounds
		// nothing, so the faces are asked.
		if (whole && (mouseX < left - FACE_MARGIN || mouseX > right + FACE_MARGIN
			|| mouseY < top - FACE_MARGIN || mouseY > bottom + FACE_MARGIN))
		{
			return false;
		}
		try
		{
			Shape box = Perspective.getClickbox(client, wv, getModel(), getOrientation(), getX(), getY(), getZ());
			return box != null && box.contains(mouseX, mouseY);
		}
		catch (RuntimeException e)
		{
			// Degenerate geometry; not being hoverable for a frame is not worth propagating.
			return false;
		}
	}

	/** The bounds' corners and where they are drawn, shared: every golem is tested on the client thread. */
	private static final float[] BOX_ACROSS = new float[8];
	private static final float[] BOX_ALONG = new float[8];
	private static final float[] BOX_UP = new float[8];
	private static final int[] BOX_X = new int[8];
	private static final int[] BOX_Y = new int[8];

	/** Pixels the game lets each face out by when picking. See Perspective.getClickbox. */
	private static final int FACE_MARGIN = 5;

	/** Copies the simulation's position and heading onto the drawn object. */
	private void syncTransform()
	{
		if (golem.isAboard())
		{
			syncAboard();
			return;
		}
		WorldView wv = client.getTopLevelWorldView();
		if (wv == null)
		{
			return;
		}

		// Drawn where the golem appears to the player, which inside an instance is not where
		// it is simulated. See Golem.setDrawOffset.
		int localX = golem.getDrawFineX() - wv.getBaseX() * TILE;
		int localY = golem.getDrawFineY() - wv.getBaseY() * TILE;

		setX(localX);
		setY(localY);
		setWorldView(wv.getId());
		setLevel(golem.getDrawPlane());
		// A golem in a crew looks out over the side it stands on; everyone else faces where it is
		// going. See Golem.drawOrientation.
		setOrientation(golem.drawOrientation());

		// Ground height is re-read as the golem moves: Wyrmscraig is not flat, and a golem
		// holding its spawn height would sink into a rise.
		if (Golem.isInScene(wv, localX, localY))
		{
			// Terrain height plus whatever the golem is doing above it - mid-jump an arc, so
			// a hop leaves the ground instead of sliding at ankle height.
			// And at sea, riding the swell with the boat under it, as golems on the player's ship
			// ride that ship.
			int swell = golem.isAfloat() || golem.isCrewed() ? FakeRaft.bob(client.getGameCycle(), golem.getBoatSeed()) : 0;
			setZ(Perspective.getTileHeight(client, new LocalPoint(localX, localY, wv), golem.getDrawPlane())
				- golem.jumpArc() - golem.deckLift() + swell);
		}
	}

	/**
	 * Aboard the player's ship: on the deck, in the ship's own world, which the client moves and
	 * turns with the boat. Height is the deck's, which that world knows.
	 */
	private void syncAboard()
	{
		LocalPoint deck = golem.drawnPoint(client);
		if (deck == null)
		{
			return;
		}
		setX(deck.getX());
		setY(deck.getY());
		setWorldView(deck.getWorldView());
		setLevel(golem.drawnLevel());
		setOrientation(golem.drawOrientation());
		setZ(Perspective.getTileHeight(client, deck, golem.drawnLevel()));
	}

	/**
	 * The next dance move, when one finishes.
	 *
	 * <p>Set here rather than left to {@link #applyPose()}, which only acts when the wanted
	 * animation changes: the next move may be the one that just finished, and the golem would
	 * stop on its last frame.
	 *
	 * <p>Only when what finished was the move itself. A golem dancing when it starts to crumble
	 * is playing its death animation, and that ending is not a cue to dance again. When the dance
	 * is over, the move's end is where the golem stops dancing: see Golem.danceMoveEnded.
	 */
	private void poseFinished(AnimationController controller)
	{
		GolemDance move = golem.getDanceMove();
		if (move == null || loadedAnimationId != move.getAnimationId())
		{
			controller.loop();
			return;
		}

		// The move has ended. The dance being over, the golem is free to go; until now it held
		// still to finish what it had started.
		if (!golem.isDancing())
		{
			golem.danceMoveEnded();
			loadedAnimationId = golem.currentPoseAnimation();
			controller.setAnimation(shared.animationFor(loadedAnimationId));
			return;
		}

		golem.nextDanceMove();
		loadedAnimationId = golem.currentPoseAnimation();
		controller.setAnimation(shared.animationFor(loadedAnimationId));
	}

	/** Switches between the walk and idle loops as the simulation changes its mind. */
	private void applyPose()
	{
		int wanted = golem.currentPoseAnimation();
		if (wanted != loadedAnimationId || animation.getAnimation() == null)
		{
			loadedAnimationId = wanted;
			animation.setAnimation(shared.animationFor(wanted));
		}

		// While performing a recording, the keyframe is the player's own, set directly.
		// Advancing the clip by elapsed cycles at its authored speed is wrong: on a basalt
		// stone the player holds keyframe one for about twenty-five cycles then runs the other
		// seven during the jump, where the authored clip takes forty - golems finished hopping
		// before leaving the ground.
		//
		// Never past the last keyframe: the controller nulls a completed one-shot, and the
		// next frame would load and play it again.
		int frame = golem.getMotionFrame();
		Animation loaded = animation.getAnimation();
		if (frame >= 0 && loaded != null && loaded.getNumFrames() > 0)
		{
			animation.setFrame(Math.min(frame, loaded.getNumFrames() - 1));
		}
	}
}

package com.golemsdontdie;

import lombok.*;
import net.runelite.api.*;

/**
 * A one-shot animated object played beside a golem that is using something.
 *
 * <p>Some transport animations belong to the scenery, not the person: {@code DOCK_GANGPLANK01}
 * is on framemap 2503 and the fairy ring's spin is the ring's own, so neither can play on the
 * golem's human rig. A copy of the object can, which is what this is.
 *
 * <p>Fire-and-forget and never reused; keeping props alive would mean tracking scenery state
 * across a scene reload for under a second of animation. The real object is untouched; the
 * copy is drawn over it, visible only to this player.
 */
class FakeProp extends RuneLiteObjectController
{
	private final Client client;
	private final Model model;
	private final AnimationController animation;

	/** World position in 128ths of a tile, as for golems. */
	private final int fineX;
	private final int fineY;
	private final int plane;
	private final int height;

	/** Cycles left before the prop is dropped. */
	private int remaining;

	/**
	 * Which way the prop faces, asked each frame: the golem's way for one the game plays on an actor,
	 * such as the air guitar's notes, which turned with the golem where the game plays them and
	 * stood facing south here, behind or beside the golem by turns.
	 */
	@lombok.Setter
	private java.util.function.IntSupplier facing = () -> 0;

	@Getter
	private final int animationId;

	FakeProp(Client client, Model model, Animation clip, int animationId,
		int fineX, int fineY, int plane, int height, int cycles)
	{
		this.client = client;
		this.model = model;
		this.animationId = animationId;
		this.fineX = fineX;
		this.fineY = fineY;
		this.plane = plane;
		this.height = height;
		this.remaining = cycles;

		this.animation = new AnimationController(client, -1);
		this.animation.setAnimation(clip);

		syncTransform();
	}

	@Override
	public void tick(int ticksSinceLastFrame)
	{
		remaining -= ticksSinceLastFrame;
		syncTransform();
		animation.tick(ticksSinceLastFrame);
	}

	@Override
	public Model getModel()
	{
		if (animation.getAnimation() == null)
		{
			return model;
		}
		Model posed = animation.animate(model);
		return posed == null ? model : posed;
	}

	/** True once the clip has run out and the prop should be unregistered. */
	boolean isFinished()
	{
		return remaining <= 0;
	}

	private void syncTransform()
	{
		WorldView wv = client.getTopLevelWorldView();
		if (wv == null)
		{
			return;
		}
		setX(fineX - wv.getBaseX() * Golem.TILE);
		setY(fineY - wv.getBaseY() * Golem.TILE);
		setWorldView(wv.getId());
		setLevel(plane);
		setZ(height);
		setOrientation(facing.getAsInt());
	}
}

package com.golemsdontdie;

import java.util.*;
import net.runelite.api.*;
import net.runelite.api.coords.*;

/**
 * Draws the boat a golem crosses the ocean in.
 *
 * <p>{@code WorldEntity} - what the game's own boats are - is read-only to a plugin, so this
 * is a drawn model at a position, as a fake golem is. It turns at a third of a golem's rate,
 * because a boat pivoting at a golem's rate reads as a sliding crate, and its heading leads
 * its motion.
 */
class FakeRaft extends RuneLiteObjectController
{
	/** Orientation units per cycle; a third of a golem's. */
	private static final int TURN_PER_CYCLE = 8;

	private final Client client;
	private final Model model;
	private final AnimationController animation;

	/** Where the boat is, in 128ths of a tile, as for golems. */
	private int fineX;
	private int fineY;

	private int orientation;
	private int targetOrientation;

	/**
	 * The ground height the boat sits at: the golem's, not the ground under the boat's own middle.
	 *
	 * <p>The raft's middle is a tile ahead of the golem and at sea the ground under water is
	 * seabed, so a raft on its own tile sank out of sight where that drops away, leaving the
	 * golem on nothing at the helm; one whose middle lay outside the scene got no height at all.
	 */
	private int groundZ = Integer.MIN_VALUE;

	/** The mast and the sail, drawn apart so each can play its own animation; see FakeRigPart. */
	private final List<FakeRigPart> parts = new ArrayList<>();

	/** How far the boat rises and falls on the swell, in height units, and how long a swell takes. */
	private static final int BOB_HEIGHT = 4;

	/**
	 * A swell's length, in client cycles: the game's own boats ride a 240 frame loop (its
	 * SAILING_WORLDENTITY_BOAT_*_IDLE_01 animations). That motion is a skeletal animation on the
	 * boat's whole world view, which a plugin cannot play on an object of its own and which pitches
	 * and rolls as well; an object can only rise and fall, so this rises and falls in its time.
	 */
	private static final int BOB_CYCLES = 240;

	/** Which boat this is on the swell, so a fleet does not rise and fall as one. See bob. */
	private final long seed;

	/**
	 * How far a boat is lifted by the swell this cycle, for the boat and for everyone standing on it,
	 * who ride it by asking with the same seed: the golem at the helm's id.
	 */
	static int bob(int gameCycle, long seed)
	{
		int phase = (int) Math.floorMod(seed * 0x9E3779B1L, (long) BOB_CYCLES);
		return (int) Math.round(Math.sin((gameCycle + phase) * 2 * Math.PI / BOB_CYCLES) * BOB_HEIGHT);
	}

	FakeRaft(Client client, Model model, GolemModelFactory shared, int fineX, int fineY,
		int orientation, long seed)
	{
		this.client = client;
		this.model = model;
		this.fineX = fineX;
		this.fineY = fineY;
		this.orientation = orientation;
		this.targetOrientation = orientation;
		this.seed = seed;

		// The raft's models carry no rig, so it plays nothing; the golem at the helm does.
		this.animation = new AnimationController(client, -1);
		syncTransform();
	}

	/**
	 * Adds a part of the rig: a model drawn at an offset from the middle of the hull, across then
	 * along, turning with the boat and playing an animation of its own.
	 */
	void addPart(Model model, int animation, int acrossOffset, int alongOffset)
	{
		if (model != null)
		{
			parts.add(new FakeRigPart(client, this, model, animation, acrossOffset, alongOffset));
		}
	}

	/** Puts the boat and its rig in the scene. */
	void attach()
	{
		client.registerRuneLiteObject(this);
		for (FakeRigPart part : parts)
		{
			client.registerRuneLiteObject(part);
		}
	}

	/** Takes the boat and its rig out of the scene. */
	void detach()
	{
		client.removeRuneLiteObject(this);
		for (FakeRigPart part : parts)
		{
			client.removeRuneLiteObject(part);
		}
	}

	int getBoatOrientation()
	{
		return orientation;
	}

	/** Moves the boat to a world position, easing the heading round. */
	void steer(int worldFineX, int worldFineY, int heading)
	{
		this.fineX = worldFineX;
		this.fineY = worldFineY;
		this.targetOrientation = heading & 2047;
	}

	/** As {@link #steer(int, int, int)}, at this ground height. */
	void steer(int worldFineX, int worldFineY, int heading, int groundZ)
	{
		steer(worldFineX, worldFineY, heading);
		this.groundZ = groundZ;
	}

	@Override
	public void tick(int ticksSinceLastFrame)
	{
		turn(ticksSinceLastFrame);
		syncTransform();
		animation.tick(ticksSinceLastFrame);
	}

	@Override
	public Model getModel()
	{
		if (animation.getAnimation() == null)
		{
			return model;
		}
		Model posed = animation.animate(model);
		return posed == null ? model : posed;
	}

	/** Eases the heading round the short way, at a boat's rate. */
	private void turn(int cycles)
	{
		if (orientation == targetOrientation || cycles <= 0)
		{
			return;
		}
		int delta = ((targetOrientation - orientation + 1024) & 2047) - 1024;
		int step = Math.min(Math.abs(delta), TURN_PER_CYCLE * cycles);
		orientation = (orientation + Integer.signum(delta) * step) & 2047;
	}

	private void syncTransform()
	{
		WorldView wv = client.getTopLevelWorldView();
		if (wv == null)
		{
			return;
		}

		int localX = fineX - wv.getBaseX() * Golem.TILE;
		int localY = fineY - wv.getBaseY() * Golem.TILE;
		setX(localX);
		setY(localY);
		setWorldView(wv.getId());
		setLevel(0);
		setOrientation(orientation);
		// A little up and down on the swell, as the game's own boats sit on the water.
		int bob = bob(client.getGameCycle(), seed);
		if (groundZ != Integer.MIN_VALUE)
		{
			setZ(groundZ + bob);
		}
		else if (Golem.isInScene(wv, localX, localY))
		{
			setZ(Perspective.getTileHeight(client, new LocalPoint(localX, localY, wv), 0) + bob);
		}
	}
}

package com.golemsdontdie;

import net.runelite.api.*;

/**
 * A part of a golem boat's rig, the mast or the sail, drawn apart from the hull and following it.
 *
 * <p>Apart because each plays an animation of its own, the sail full and moving in the wind, and an
 * animation is a set of transforms about the model's own groups: played on a hull merged with it, it
 * would bend the hull. Placed each frame at its offset from the hull's middle, turned with the boat,
 * at the hull's height.
 */
class FakeRigPart extends RuneLiteObjectController
{
	private final Client client;
	private final FakeRaft boat;
	private final Model model;
	private final AnimationController animation;
	private final int across;
	private final int along;

	FakeRigPart(Client client, FakeRaft boat, Model model, int animation, int across, int along)
	{
		this.client = client;
		this.boat = boat;
		this.model = model;
		this.animation = new AnimationController(client, animation);
		this.across = across;
		this.along = along;
	}

	@Override
	public void tick(int ticksSinceLastFrame)
	{
		follow();
		animation.tick(ticksSinceLastFrame);
	}

	@Override
	public Model getModel()
	{
		if (animation.getAnimation() == null)
		{
			return model;
		}
		Model posed = animation.animate(model);
		return posed == null ? model : posed;
	}

	/**
	 * Takes the boat's place, moved by the part's offset turned the way the boat is. The model is
	 * turned by the client as the hull is: x along x, z along y, both turned by the orientation.
	 */
	private void follow()
	{
		int orientation = boat.getBoatOrientation();
		double angle = orientation * Math.PI / 1024;
		double cos = Math.cos(angle);
		double sin = Math.sin(angle);
		setX(boat.getX() + (int) Math.round(across * cos + along * sin));
		setY(boat.getY() + (int) Math.round(along * cos - across * sin));
		setZ(boat.getZ());
		setWorldView(boat.getWorldView());
		setLevel(boat.getLevel());
		setOrientation(orientation);
	}
}

package com.golemsdontdie;

import java.util.*;
import java.util.Deque;
import java.util.function.*;
import lombok.*;
import net.runelite.api.*;
import net.runelite.api.coords.*;
import static com.golemsdontdie.RouteGeometry.span;

/**
 * One golem, simulated in world coordinates whether or not it is on screen.
 *
 * <p>A golem is a position, a heading and an intention; drawing it is a view attached only
 * while it is inside the loaded scene, so one that wanders off the edge keeps walking.
 * Positions are integer 128ths of a tile, the unit the client's local coordinates use;
 * floats would accumulate error over a golem that walks for hours.
 */
class Golem
{
	/** 128 units of position per tile, matching {@link net.runelite.api.coords.LocalPoint}. */
	static final int TILE = 128;

	/** Client cycles (20ms) per tile walked. One game tick, i.e. normal NPC walking pace. */
	private static final int CYCLES_PER_TILE = 30;

	/** Orientation units turned per cycle. 2048 is a full circle. */
	private static final int TURN_PER_CYCLE = 24;

	/** Angle units: 0 south, 512 west, 1024 north, 1536 east. */
	private static final int SOUTH = 0, WEST = 512, NORTH = 1024, EAST = 1536;

	/** Cycles a golem stands still between walks, before and after a random spread. */
	private static final int DWELL_MIN = 20;
	private static final int DWELL_SPREAD = 130;

	@Getter
	private final GolemSnapshot snapshot;

	/** Where it was made. The penned roam area is measured from here. */
	@Getter
	private final WorldPoint home;

	/**
	 * Which floor the golem is on. Fixed in the island-only plugin; mutable now because the
	 * transport network is mostly vertical - 2,262 of the 5,168 plain rows change plane.
	 * Only {@link #relocate} may change it, and never mid-step.
	 */
	@Getter
	private int plane;

	/**
	 * Seeded per golem so two made on the same tile do not walk in lockstep, and a restored
	 * golem carries on with its own gait.
	 */
	private final Random random;

	/** Position in 128ths of a tile, world-absolute. */
	@Getter
	private int fineX;
	@Getter
	private int fineY;

	@Getter
	private int orientation;
	private int targetOrientation;

	/** Remaining tiles of the current walk, as world tile pairs. */
	private final Deque<int[]> path = new ArrayDeque<>();

	/** The step in progress, interpolated between two tile centres. */
	private int stepFromX, stepFromY, stepToX, stepToY;
	private int stepElapsed;
	private boolean stepping;

	/** Cycles left standing still before choosing somewhere new to go. */
	private int dwellRemaining;

	/** Whether this golem used a path search on the current frame. */
	private boolean searched;

	/**
	 * What this golem has used recently, so it does not pace through the same door. Per
	 * golem rather than shared: two golems meeting at a ladder should both be able to climb.
	 */
	private final TransportMemory transportMemory = new TransportMemory();

	/**
	 * The route this golem is on while nobody can see it, or null if it is being simulated
	 * properly. Set when it drops out of range, cleared when it comes back; while set the
	 * golem is not stepped, and its position is whatever the route says at this tick.
	 */
	private Itinerary itinerary;

	/** The tier the golem was in last frame, so crossings can be acted on once. */
	@Getter
	private GolemTier tier = GolemTier.SCENE;

	// ---------------------------------------------------------------- watchdog

	/**
	 * Consecutive destination searches that found nowhere to go.
	 *
	 * <p>One failure is ordinary; a run of them means the golem cannot walk out of where it
	 * is, which is a death in all but name.
	 */
	private int failedSearches;

	/** Where the golem was when it last actually got somewhere, and when that was. */
	private int progressX;
	private int progressY;
	private int progressTick;

	/** Failed searches in a row before the golem is treated as stuck. */
	private static final int STUCK_SEARCHES = 12;

	/** Game ticks without meaningful movement before the golem is treated as stuck. */
	private static final int STUCK_TICKS = 500;

	/** How far the golem must get for it to count as having moved at all. */
	private static final int PROGRESS_TILES = 3;

	/**
	 * True if this golem has stopped getting anywhere and should be relocated. Two signals:
	 * failed searches catch a golem walled in on ground the map says is walkable, and no net
	 * movement catches searches that succeed but leave it shuffling between two tiles. Slow
	 * to fire, since standing still a few minutes is normal.
	 */
	boolean isStuck(int tick)
	{
		if (isDying() || inTransition())
		{
			return false;
		}

		// A golem on a route is travelling, not stuck; a passage holds it at the first
		// waypoint for the whole crossing, so the watchdog hauled golems off boats.
		if (itinerary != null && !itinerary.isFinished(tick))
		{
			return false;
		}
		if (failedSearches >= STUCK_SEARCHES)
		{
			return true;
		}

		int tileX = fineX / TILE;
		int tileY = fineY / TILE;
		if (progressTick == 0
			|| Math.abs(tileX - progressX) + Math.abs(tileY - progressY) >= PROGRESS_TILES)
		{
			progressX = tileX;
			progressY = tileY;
			progressTick = tick;
			return false;
		}
		return tick - progressTick > STUCK_TICKS;
	}

	/** When this golem may next sail, in real time; 0 if it may now. For the save. */
	long getShoreLeaveUntil()
	{
		return transportMemory.getShoreLeaveUntil();
	}

	void setShoreLeaveUntil(long until)
	{
		transportMemory.setShoreLeaveUntil(until);
	}

	/**
	 * True while the golem is drawn at a raft's helm on the open sea. Set as a crossing is
	 * followed in view, cleared when it ends or the golem moves.
	 */
	@Getter
	private boolean afloat;

	/** How far above the water a golem at the helm stands: on the deck, not in the sea. */
	private static final int DECK_HEIGHT = 30;

	/** Height to lift the golem by, in the client's height units: the deck, while afloat. */
	int deckLift()
	{
		return afloat ? DECK_HEIGHT : 0;
	}

	/**
	 * True while the golem is out of view partway along a route, where its position is only an
	 * estimate: a point on a straight line between two of the route's tiles, drawn without looking
	 * at the map. Nothing should judge where the golem is from it. The cut-off sweep did, and carried
	 * a golem home from the middle of a sealed room its line merely passed over; the journal did, and
	 * wrote that a golem walking from the Wilderness had explored the Castle Wars tunnels.
	 */
	boolean isEstimated(int tick)
	{
		if (tier != GolemTier.FAR || itinerary == null || itinerary.isStationary())
		{
			// Standing still is exactly where it stands.
			return false;
		}
		if (!itinerary.isFinished(tick))
		{
			return true;
		}
		// Finished, but not yet put on its destination: that happens at the next frame, and until
		// then the position is the last estimate, up to a few tiles back along the line - the very
		// case of the golem carried home from a sealed room its line passed over.
		WorldPoint end = itinerary.destination();
		return fineX / TILE != end.getX() || fineY / TILE != end.getY() || plane != end.getPlane();
	}

	/** True while the golem is on a crossing: afloat, or waiting out a passage. */
	boolean isSailing(int tick)
	{
		return itinerary != null && itinerary.isVoyage() && !itinerary.isFinished(tick);
	}

	/**
	 * Where to write this golem down in a save: the end of whatever route it is on. On a crossing,
	 * since a golem restored onto water is moved to whatever land is nearest; out of view on foot,
	 * since a route there is drawn straight without looking at the map, and partway along one a
	 * golem can be inside a wall or a sealed room beside it. Saved there, it came back there, and
	 * was carried off to the plinth in front of the player. The end is ground the planner chose.
	 */
	WorldPoint saveTile()
	{
		// Aboard the player's ship it is at sea, and the quay it boarded from is where it goes if
		// the voyage ends without it stepping off.
		if (isAboard() && aboardFrom != null)
		{
			return aboardFrom;
		}
		return itinerary != null ? itinerary.destination() : currentTile();
	}

	/**
	 * Where a golem on a crossing has got to, or null if it is not on one. Its own tile is the
	 * port it is bound for - see {@link #saveTile} - so anything that wants the raft rather than
	 * the landfall, such as the world map, asks the crossing itself.
	 */
	WorldPoint seaPosition(int tick)
	{
		return isSailing(tick) ? itinerary.positionAt(tick) : null;
	}

	/** Clears the watchdog after the golem has been moved somewhere it can walk. */
	void noteUnstuck(int tick)
	{
		failedSearches = 0;
		progressTick = tick;
		progressX = fineX / TILE;
		progressY = fineY / TILE;
		eddyCycles = 0;
		reversed = false;
	}

	// ------------------------------------------------------- getting off a rock

	/** Cycles left spinning in place. The first and cheapest thing a grounded raft does. */
	private int eddyCycles;

	/** Whether this golem has already tried backing out of where it is. */
	private boolean reversed;

	/** Cycles a stuck raft turns on the spot before trying something with a cost. */
	private static final int EDDY_CYCLES = 100;

	/**
	 * Works a grounded raft free, cheapest first: back along the stored waypoints, turning on the
	 * spot a moment before it sets off; re-plan from where the boat is; snap to valid water. Only the snap is a
	 * cheat, and a grounded golem is unwatched almost by definition, since a watched one
	 * would be on live collision, not the shipped mesh.
	 *
	 * @return true if this handled it and nothing further should be done
	 */
	boolean workFree(RoamContext context, RoamPlanner planner)
	{
		int tick = context.getTick();

		if (eddyCycles > 0)
		{
			// Rung one is still running.
			eddyCycles = Math.max(0, eddyCycles - 1);
			targetOrientation = (orientation + 512) & 2047;
			return true;
		}

		// Not a route already through its transport: reversed, the walk back starts on the
		// far side of the ladder while the golem is at the top, and it would be put back.
		if (!reversed && itinerary != null && !(itinerary.transport() != null && itinerary.isFinished(tick)))
		{
			Itinerary back = itinerary.reversed(tick, tick);
			if (back != null)
			{
				reversed = true;
				itinerary = back;
				eddyCycles = EDDY_CYCLES;
				return true;
			}
		}

		// Rung three: a fresh plan from here. Only a golem nobody can see may be given a
		// route, because a roaming route is a straight line that ignores the map; handing a
		// visible golem one sent them sliding across the water. In view, a path search.
		if (tier == GolemTier.FAR)
		{
			Itinerary replanned = planner.plan(currentTile(), tick, random, transportMemory,
				context);
			if (replanned != null)
			{
				itinerary = replanned;
				if (replanned.isVoyage())
				{
					leave(replanned);
				}
				noteUnstuck(tick);
				return true;
			}
		}
		else
		{
			chooseDestination(context);
			if (!path.isEmpty())
			{
				noteUnstuck(tick);
				return true;
			}
		}

		// Nothing left but rung four, which the caller owns because only it has the mesh.
		return false;
	}

	/**
	 * Cycles left of the crumble, or -1 if this golem is not dying. A retired golem plays
	 * the game's own death animation; vanishing on the spot would look like a bug.
	 */
	private int dyingCycles = -1;

	/**
	 * Set while the real golem this copy took over is still alive. The real one is hidden, but the
	 * game still dots it on the minimap, and a copy walking off on its own left two dots going two
	 * ways. So the copy stands in for it - where it is, which way it faces, walking or not - until
	 * it is gone. See GolemsDontDiePlugin.followRealGolems.
	 */
	private boolean shadowing;

	boolean isShadowing()
	{
		return shadowing;
	}

	/** Stands where the real golem is this frame, facing its way, walking if it is. */
	void shadow(int fineX, int fineY, int orientation, boolean moving)
	{
		shadowing = true;
		this.fineX = fineX;
		this.fineY = fineY;
		this.orientation = orientation;
		targetOrientation = orientation;
		walking = moving;
		path.clear();
		stepping = false;
	}

	/** The real golem is gone: carry on from where it was, after a moment. */
	void stopShadowing()
	{
		if (!shadowing)
		{
			return;
		}
		shadowing = false;
		walking = false;
		dwellRemaining = DWELL_MIN + random.nextInt(DWELL_SPREAD);
	}

	/** True once the crumble has been started. The golem stops walking and cannot path. */
	boolean isDying()
	{
		return dyingCycles >= 0;
	}

	/** True when the crumble has played out and the golem should be dropped. */
	boolean isCrumbled()
	{
		return dyingCycles == 0;
	}

	/**
	 * Begins the crumble. Idempotent, so asking twice does not restart it.
	 */
	void startDying()
	{
		if (dyingCycles < 0)
		{
			dyingCycles = GolemContent.GOLEM_DEATH_CYCLES;
			path.clear();
			stepping = false;
			walking = false;
		}
	}

	/** True while the golem is moving, which selects the walk animation over the idle. */
	@Getter
	private boolean walking;

	/**
	 * Set while the golems are celebrating something. A dancing golem stands where it is until it
	 * is over: it finishes the step it is on, then dances rather than looking for anywhere to go.
	 */
	@Getter
	@Setter
	private boolean dancing;

	/** The move it is on, or null before the first. */
	@Getter
	private GolemDance danceMove;

	/**
	 * Set while a dance move is being played and has not reached its end. A celebration or a party
	 * ends on a tick, and the golem walked off that moment, cut off halfway through a spin: it
	 * finishes the move first. Cleared by the renderer when the move ends, and whenever there is
	 * no renderer to end it.
	 */
	private boolean midMove;

	/** The tick the move began, and the longest one may take before it is taken as over. */
	private int midMoveTick;
	private static final int MOVE_MOST_TICKS = 20;

	/** True while a dance move is still playing out: nothing should break into it. */
	boolean isMidMove()
	{
		return midMove;
	}

	/** The move being played has reached its end. See midMove. */
	void danceMoveEnded()
	{
		midMove = false;
	}

	/**
	 * The moves' own generator, seeded from the golem but separate from it: drawn from the golem's
	 * own, dancing would change where it walked afterwards, and two golems that danced the same
	 * number of moves would then walk in step.
	 */
	private Random danceRandom;

	/** Set when a move wants something drawn beside the golem, such as the air guitar's guitar. */
	private boolean propPending;

	/** The tick a golem dancing of its own accord stops; 0 when it is not. See GolemTrait. */
	private int partyUntil;

	/** The tick a golem waving at the player puts its hand down; 0 when it is not. */
	private int greetUntil;

	/** Set when the golem is inside the loaded scene and should be drawn. */
	@Getter
	@Setter
	private FakeGolem renderer;

	/**
	 * A name the player has given this golem, or null for none.
	 *
	 * <p>Bookkeeping for the side panel: the world calls every one of them "Golem", so a
	 * nickname on right-click gives the copy away.
	 */
	@Getter
	@Setter
	private String nickname;

	/**
	 * Starred by the player, which keeps it at the top of the sidebar. Set on the client thread and
	 * read by the sidebar's own, to draw the star.
	 */
	@Getter
	@Setter
	private volatile boolean favourite;

	/**
	 * Which golem this was to be crafted, counting from one: what an ordinal name is made of. 0 until
	 * it is numbered, which a golem is as it joins the roster. Read by the sidebar's thread for the
	 * name, so volatile like the star.
	 */
	@Getter
	@Setter
	private volatile int craftNumber;

	/**
	 * True while the golem is inside an instance - through the pew, in the Mad Angel's room.
	 * Golems are simulated in the instance's template, ordinary world coordinates, so
	 * coordinates alone cannot say who is inside; without this, golems near the cathedral
	 * were drawn inside the player's instance.
	 */
	@Getter
	@Setter
	private boolean inInstance;

	/** What a transport will make {@link #inInstance} on landing: 1, 0, or -1 for no change. */
	private int landingInstance = -1;

	private void landInInstance()
	{
		if (landingInstance >= 0)
		{
			inInstance = landingInstance == 1;
			landingInstance = -1;
		}
	}

	/** The same, for a golem out of view that has already arrived through a transport. */
	private void noteInstance(GolemTransport transport)
	{
		if (transport.entersInstance())
		{
			inInstance = true;
		}
		else if (transport.leavesInstance())
		{
			inInstance = false;
		}
	}

	/** Stable identity for the side panel and the save file, assigned on creation. */
	@Getter
	private final long id;

	/** What this golem is like, drawn from its seed and kept for life. See GolemTrait. */
	@Getter
	private int traits;

	/** What it has done since it was made. See GolemHistory. */
	@Getter
	private final GolemHistory history = new GolemHistory();

	Golem(GolemSnapshot snapshot, WorldPoint home, long seed, int startFineX, int startFineY)
	{
		this.snapshot = snapshot;
		this.home = home;
		this.plane = home.getPlane();
		this.random = new Random(seed);
		this.id = seed;
		this.traits = GolemTrait.of(seed);
		transportMemory.setTraits(traits);

		this.fineX = startFineX;
		this.fineY = startFineY;
		this.orientation = snapshot.getOrientation() & 2047;
		this.targetOrientation = this.orientation;
		this.dwellRemaining = DWELL_MIN + random.nextInt(DWELL_SPREAD);
	}

	/**
	 * Creates a golem on the centre of a tile, for restoring a save where only the tile was
	 * written down. Taking over from a live golem uses the other constructor with its exact
	 * sub-tile position; snapping to a tile centre there made the copy look teleported.
	 */
	static Golem onTile(GolemSnapshot snapshot, WorldPoint home, long seed, WorldPoint at)
	{
		return new Golem(snapshot, home, seed,
			at.getX() * TILE + TILE / 2,
			at.getY() * TILE + TILE / 2);
	}

	/**
	 * True if a scene-local position is inside the loaded scene. Replaces
	 * {@link net.runelite.api.coords.LocalPoint#isInScene()}, deprecated for assuming every
	 * scene is 104 tiles square; the world view's own size is correct for instances too.
	 */
	static boolean isInScene(WorldView wv, int localX, int localY)
	{
		return localX >= 0 && localY >= 0
			&& localX < wv.getSizeX() * TILE
			&& localY < wv.getSizeY() * TILE;
	}

	/**
	 * Stands the golem at the quayside for a while instead of casting off, while a crew is made
	 * up around it. The crossing it had planned is given up - the crew's is planned when the crew
	 * is, and a golem let go without one plans afresh - so the tally gives that one back too.
	 */
	void waitAshore(int tick, int ticks, WorldPoint quayside)
	{
		// Only a crossing under way is being given up. One already sailed is still the plan of a
		// golem out of view that has just come ashore here, and it was sailed.
		if (itinerary != null && itinerary.isVoyage() && !itinerary.isFinished(tick))
		{
			history.unsailed();
			if (itinerary.getLeftPort() >= 0)
			{
				transportMemory.setBlockedPort(blockedBefore);
			}
		}
		path.clear();
		walking = false;
		relocate(quayside);
		itinerary = RoamPlanner.stayPut(quayside, tick, ticks);
		waiting = itinerary;
	}

	/**
	 * As {@link #waitAshore(int, int, WorldPoint)}, but a golem in view already on the quay walks
	 * the few tiles to its place there rather than being put on it, which was a jump of a tile.
	 */
	void waitAshore(int tick, int ticks, WorldPoint quayside, RoamContext context)
	{
		// Where it will stand once the step it is partway through is done. Told to wait mid-step, it
		// stopped walking but not moving: it finished the step in its standing pose, a slide, or stood
		// frozen between two tiles for the whole wait.
		WorldPoint at = stepping ? new WorldPoint(stepToX / TILE, stepToY / TILE, plane) : currentTile();
		if (context != null && renderer != null && !inTransition() && at.getPlane() == quayside.getPlane()
			&& span(quayside.getX() - at.getX(), quayside.getY() - at.getY()) <= WALK_TO_WAIT
			&& (at.equals(quayside) ? clearPath() : walkTo(quayside.getX(), quayside.getY(), context)))
		{
			walking = stepping || !path.isEmpty();
			// Whatever it was walking to use is given up with the crossing.
			queuedTransport = null;
			wayOffDeadEnd = null;
			queuedDock = null;
			itinerary = RoamPlanner.stayPut(quayside, tick, ticks);
			waiting = itinerary;
			return;
		}
		waitAshore(tick, ticks, quayside);
	}

	/**
	 * Keeps a golem waiting at its place at a quayside until this tick, if it is waiting there and
	 * would stop sooner: a crew whose crossing is still being worked out waits past the muster, and
	 * the golems in it whose own waits ran out walked off while still counted as its crew.
	 */
	void holdWaitUntil(int tick, int until)
	{
		if (waiting == null || itinerary != waiting || waiting.getStartTick() + waiting.getDuration() >= until
			|| until <= tick)
		{
			return;
		}
		itinerary = RoamPlanner.stayPut(waiting.destination(), tick, until - tick);
		waiting = itinerary;
	}

	/** Drops the walk ahead, keeping the step under way. True, for use in a condition. */
	private boolean clearPath()
	{
		path.clear();
		return true;
	}

	/** True while the golem is on a wait at a quayside, for a crew to make up around it. */
	private boolean isWaiting(int tick)
	{
		return itinerary != null && itinerary == waiting && tick >= itinerary.getStartTick()
			&& !itinerary.isFinished(tick);
	}

	/** How far a golem walks to its place at a quayside rather than being put there. */
	private static final int WALK_TO_WAIT = 4;

	/**
	 * The wait at a quayside this golem is on, if any. In view a route that is not a crossing is
	 * dropped, and a wait is not one, so without this a golem in sight wandered off the quay the
	 * frame after it was stood there, and never sailed while anyone watched.
	 */
	private Itinerary waiting;

	/**
	 * True for a golem in view standing on its wait at a quayside with nothing else in hand: not
	 * stepping, waving, dancing, climbing or crumbling. Only then is it given anything to do there,
	 * since a wave begun mid-walk dropped the rest of the walk.
	 */
	boolean isIdleOnQuay(int tick)
	{
		return renderer != null && isWaiting(tick) && path.isEmpty() && !stepping && !isDying() && !dancing
			&& !isGreeting(tick) && !isPartying(tick) && !inTransition();
	}

	/** The place at a quayside this golem is waiting at, or null if it is not waiting. */
	WorldPoint waitingSpot()
	{
		return waiting == null ? null : waiting.destination();
	}

	/** The tile the golem is walking to, or the one it stands on. */
	WorldPoint goalTile()
	{
		int[] last = path.peekLast();
		return last == null ? currentTile() : new WorldPoint(last[0], last[1], plane);
	}

	/** Most tiles a golem waiting at a quay walks to stretch its legs; further is a wander. */
	private static final int MILL_STEPS = 4;

	/**
	 * Walks a golem waiting at a quay to a tile near its place there, still waiting. Nothing it
	 * passes is taken, since no transport is rolled for while it waits.
	 *
	 * @return true if it set off
	 */
	boolean millTo(WorldPoint to, RoamContext context)
	{
		if (to.getPlane() != plane || !walkTo(to.getX(), to.getY(), context) || path.size() > MILL_STEPS)
		{
			path.clear();
			return false;
		}
		return true;
	}

	/** Turns the golem, at its own pace, to look toward something this far east and north. */
	void faceToward(int dx, int dy)
	{
		// Not while turning to an obstacle: a wave or a look took the turn over, and the golem went
		// over the stile facing the player.
		if ((dx != 0 || dy != 0) && facingObstacle == null)
		{
			targetOrientation = headingFor(dx, dy);
		}
	}

	/**
	 * Turns the golem to a heading at once, without turning through it: a golem on a boat is
	 * carried round with the boat rather than steering itself.
	 */
	void faceAs(int heading)
	{
		orientation = heading & 2047;
		targetOrientation = orientation;
	}

	/** Takes the crossing its crew has planned. Counted, as any other voyage is. */
	void boardCrossing(Itinerary crossing)
	{
		path.clear();
		walking = false;
		adopt(crossing);
	}

	TransportMemory getTransportMemory()
	{
		return transportMemory;
	}

	/** Puts back the traits a golem was saved with, which win over the ones its seed deals now. */
	void restoreTraits(int saved)
	{
		traits = saved;
		transportMemory.setTraits(saved);
	}

	/**
	 * Takes a route, unless it is a crossing and the crews want the golem waiting at the quayside
	 * for company first. Asked before casting off rather than after: held once it had, a golem in
	 * view got into its raft and was pulled back out of it onto the quay. Keeps the tally with it:
	 * a voyage is only ever known about here, the planner having worked it out for a golem it was
	 * handed the memory of and not the golem.
	 */
	private void embark(Itinerary plan, RoamContext context)
	{
		if (plan != null && plan.isVoyage() && !crewed && context != null && context.getMuster() != null
			&& context.getMuster().test(this, context))
		{
			return;
		}
		adopt(plan);
	}

	private void adopt(Itinerary plan)
	{
		itinerary = plan;
		if (plan != null && plan.isVoyage())
		{
			history.sailed();
			leave(plan);
		}
	}

	/**
	 * Keeps the golem from sailing straight back to the port a crossing it is taking leaves. Done
	 * as it takes the crossing rather than as it is planned: one held for a crew's muster instead
	 * had moved the block to a port the golem never left.
	 */
	private void leave(Itinerary crossing)
	{
		if (crossing.getLeftPort() >= 0)
		{
			blockedBefore = transportMemory.getBlockedPort();
			transportMemory.setBlockedPort(crossing.getLeftPort());
		}
	}

	/** The port blocked before the crossing it is on, put back if that crossing is given up at the quay. */
	private int blockedBefore = -1;

	/** The tile the golem is standing on or walking out of. */
	WorldPoint currentTile()
	{
		return new WorldPoint(fineX / TILE, fineY / TILE, plane);
	}

	/** The tick this golem is next looked at while it is out of view. See {@link #scheduleFarCheck}. */
	private int nextFarCheck = Integer.MIN_VALUE;

	boolean farCheckDue(int tick)
	{
		return tick >= nextFarCheck;
	}

	/**
	 * Decides when a golem out of view is next looked at. Its position is a function of
	 * time, so nothing need happen between the moments something could change: the route
	 * running out, or the player coming near. Each golem takes its own tick in the cycle,
	 * spread by its id, so a few thousand share the work.
	 */
	void scheduleFarCheck(int tick, int interval)
	{
		if (itinerary == null || itinerary.isFinished(tick))
		{
			nextFarCheck = tick;
			return;
		}
		int slot = (int) ((id ^ (id >>> 32)) & 0x7fffffff) % interval;
		int next = tick + interval - (tick + slot) % interval;
		nextFarCheck = Math.min(next, itinerary.getStartTick() + itinerary.getDuration());
	}

	/**
	 * Puts a golem out of view where its route says it is now, before its tier is judged.
	 * Looked at only every few ticks, its last position can be a few ticks old.
	 */
	void catchUpFar(int tick)
	{
		if (itinerary != null && !itinerary.isFinished(tick))
		{
			this.fineX = itinerary.fineXAt(tick);
			this.fineY = itinerary.fineYAt(tick);
			this.plane = itinerary.planeAt(tick);
		}
	}

	/**
	 * Moves the golem between tiers, doing the one-off work each crossing needs.
	 *
	 * <p>Called every frame; most frames the tier is unchanged. Inward, the route resolves to
	 * a tile snapped onto real walkable ground - which is what makes the straight-line far
	 * routes safe, correcting them exactly when the error would show. Outward, the renderer
	 * is dropped and a route is planned.
	 *
	 * @return true if the golem changed tier
	 */
	boolean setTier(GolemTier now, RoamContext context, RoamPlanner planner)
	{
		if (now == tier)
		{
			return false;
		}

		boolean wasFar = tier == GolemTier.FAR;
		tier = now;
		// Out of view a crossing is not drawn, so there is nothing to trace.
		if (now != GolemTier.SCENE)
		{
			tracing = null;
		}

		if (now == GolemTier.FAR)
		{
			// Nothing plays the rest of an obstacle out of view. Left standing, it froze until the
			// golem came back into view minutes later and then finished, dragging the golem back
			// to the far side of an obstacle it had long since walked away from.
			if (inTransition())
			{
				landNow();
			}
			// Walking to a shortcut or a dock is something only a golem in view does.
			queuedTransport = null;
			wayOffDeadEnd = null;
			queuedDock = null;
			facingObstacle = null;
			// A crossing keeps going, out of view as into it. Planning afresh from the open
			// sea found nowhere to walk, so the golem idled on the water for good.
			if (itinerary != null && itinerary.isVoyage() && !itinerary.isFinished(context.getTick()))
			{
				return true;
			}
			embark(planner.plan(currentTile(), context.getTick(), random, transportMemory, context), context);
			return true;
		}

		if (wasFar)
		{
			// A crossing keeps going: it was searched over the ocean mesh, so a player who
			// sails out to meet one finds it where the route says, still sailing.
			if (itinerary != null && itinerary.isVoyage()
				&& !itinerary.isFinished(context.getTick()))
			{
				return true;
			}

			if (itinerary != null && itinerary != arrived && itinerary.isFinished(context.getTick()))
			{
				arrived = itinerary;
				if (itinerary.transport() != null)
				{
					noteInstance(itinerary.transport());
					history.tookTransport(itinerary.transport());
				}
				else if (itinerary.isVoyage())
				{
					history.cameAshore(itinerary.destination());
				}
			}
			WorldPoint resolved = itinerary != null
				? itinerary.positionAt(context.getTick())
				: currentTile();
			relocate(planner.snapToMesh(resolved));
			itinerary = null;
		}
		return true;
	}

	/**
	 * Moves the golem along its route, and tidies up when the route runs out. Position comes
	 * from the route rather than being stepped toward it, so the mechanism is the same
	 * watched or not; only the ending differs.
	 */
	private void followItinerary(int cycles, RoamContext context)
	{
		int tick = context.getTick();

		// Sub-tile, interpolated along the route by distance. Reading the waypoint index
		// instead made a golem jump a whole straightened leg at a time.
		int[] at = itinerary.fineAt(tick, context.getTickFraction());

		// Face along the leg being travelled: the route's own answer, not dependent on
		// having moved since last frame.
		int facing = itinerary.facingAt(tick, context.getTickFraction());
		if (facing >= 0)
		{
			// At sea the raft's own heading, which already turns at a raft's pace. The
			// walking turn on top of it lagged the raft round every bend.
			orientation = facing;
			targetOrientation = facing;
		}
		else
		{
			int[] heading = itinerary.headingAt(tick);
			if (heading[0] != 0 || heading[1] != 0)
			{
				targetOrientation = headingFor(heading[0], heading[1]);
			}
			turnToward(cycles);
		}

		this.fineX = at[0];
		this.fineY = at[1];
		this.plane = itinerary.planeAt(tick);

		// At sea the golem holds the helm: it played its walk the whole crossing, which read
		// as a golem running on the spot in a boat. A passage from the cave dock is not sea.
		walking = false;
		afloat = itinerary.isSailed() && !itinerary.isFinished(tick);

		if (itinerary.isFinished(tick) && tier != GolemTier.FAR)
		{
			boolean wasVoyage = itinerary.isVoyage();
			itinerary = null;
			walking = false;
			afloat = false;
			dwellRemaining = DWELL_MIN + random.nextInt(DWELL_SPREAD);

			// A voyage ends at a mooring, which is water: left there the golem would stand
				// on the sea with nowhere to walk, so it is put ashore.
			if (wasVoyage)
			{
				history.cameAshore(currentTile());
				transportMemory.beginShoreLeaveOnArrival(tick, tick, random);
				RoamPlanner planner = context.getPlanner();
				if (planner != null)
				{
					relocate(planner.snapToMesh(currentTile()));
				}
			}
		}
	}

	/**
	 * Advances a golem nobody can see, almost always nothing at all: the only work is
	 * replanning when a route runs out, once a minute or so per golem.
	 *
	 * @param mayPlan false once this frame's planning is spent, so a golem whose route ran
	 *                out stands where it arrived and plans on a later frame rather than a
	 *                thousand of them searching in the same one.
	 * @return true if a route was planned
	 */
	boolean advanceFar(RoamContext context, RoamPlanner planner, boolean mayPlan)
	{
		// Nobody sees a golem out of view crumble, so it is simply done. The crumble only
		// counted down in view, and a golem told to go while out of it stayed in the roster,
		// still walking, for the rest of the session.
		if (isDying())
		{
			dyingCycles = 0;
			return false;
		}
		if (shadowing)
		{
			return false;
		}
		// Out of view no move is being played, so none is left to finish.
		midMove = false;

		int tick = context.getTick();

		if (itinerary != null && !itinerary.isFinished(tick))
		{
			// Read the route's position rather than stepping toward it: a binary search and
			// a lerp, so "costs nothing" means no search, no allocation and no drift. Live
			// position lets the tier check notice a golem sailing toward the player, and
			// stops one mid-ocean saving the port it left. Cached per tick.
			this.fineX = itinerary.fineXAt(tick);
			this.fineY = itinerary.fineYAt(tick);
			this.plane = itinerary.planeAt(tick);
			return false;
		}

		// Once per route: a golem that cannot plan yet comes back here every frame until it can,
		// and counting each time made one ladder a hundred shortcuts.
		if (itinerary != null && itinerary != arrived)
		{
			arrived = itinerary;
			if (itinerary.transport() != null)
			{
				noteInstance(itinerary.transport());
				history.tookTransport(itinerary.transport());
			}
			else if (itinerary.isVoyage())
			{
				// Out of view, a crossing ends here rather than at a landing anyone watched: the
				// journal hears it came ashore all the same, or it would say the golem walked there.
				history.cameAshore(itinerary.destination());
			}
		}
		WorldPoint at = itinerary == null ? currentTile() : itinerary.destination();
		this.fineX = at.getX() * TILE + TILE / 2;
		this.fineY = at.getY() * TILE + TILE / 2;
		this.plane = at.getPlane();
		if (!mayPlan)
		{
			return false;
		}

		embark(planner.plan(at, tick, random, transportMemory, context), context);
		if (itinerary == null)
		{
			// Nowhere found: stand a moment before looking again. See RoamPlanner.idle.
			itinerary = RoamPlanner.idle(at, tick, random, farFailures++);
		}
		else
		{
			farFailures = 0;
		}
		return true;
	}

	/** Plans in a row that found nowhere to go; lengthens the pause before the next. */
	private int farFailures;

	/** The route whose arrival has been noted in the history, so it is noted once. */
	private Itinerary arrived;

	/**
	 * Puts the golem down somewhere else entirely - the far end of a ladder, a dock it has
	 * just sailed to, or a valid tile after it was found somewhere it cannot stand.
	 *
	 * <p>Everything mid-flight has to go: a queued path found on the old plane would walk
	 * the golem through the new floor, and a half-finished step would interpolate it across
	 * the map. Identity is untouched.
	 */
	void relocate(WorldPoint to)
	{
		this.plane = to.getPlane();
		this.fineX = to.getX() * TILE + TILE / 2;
		this.fineY = to.getY() * TILE + TILE / 2;

		// Any obstacle it was partway through is over: finished later, it would put the golem
		// back where the obstacle leads.
		transitionCycles = 0;
		transitionAnimation = -1;
		transitionGlide = false;
		transitionDestination = null;
		phaseClips = new int[0];
		phaseCycles = new int[0];
		phase = 0;
		motionFrame = -1;
		path.clear();
		gaitWalk = -1;
		gaitIdle = -1;
		gaitFinish = -1;
		motion = null;
		stepping = false;
		stepElapsed = 0;
		walking = false;
		afloat = false;

		// The route goes too: a kept itinerary would resolve against the new position next
		// frame and drag the golem straight back, making a rescue look like a rubber band.
		itinerary = null;
		queuedTransport = null;
		queuedDock = null;
		facingObstacle = null;
		wayOffDeadEnd = null;
		transportMemory.clearPending();
		// A crossing interrupted by being put somewhere else is not one worth recording.
		tracing = null;

		// Arriving somewhere new is a moment to stand and look around, and it keeps a golem
		// from immediately pathing back out of a doorway it just used.
		dwellRemaining = DWELL_MIN + random.nextInt(DWELL_SPREAD);
	}

	/**
	 * Advances the simulation.
	 *
	 * @param cycles client cycles (20ms each) since the last advance
	 * @param bounds where it may walk, re-derived each time so flipping the free roam
	 *               setting takes effect on the golem's next decision
	 */
	boolean advance(int cycles, RoamContext context)
	{
		if (cycles <= 0)
		{
			return false;
		}
		this.searched = false;

		if (isDying())
		{
			// Stands where it is and crumbles. No turning, no walking, no pathing.
			dyingCycles = Math.max(0, dyingCycles - cycles);
			return false;
		}

		// Standing in for the real golem, which moves it.
		if (shadowing)
		{
			return false;
		}

		// Nothing drawn, nothing to finish: only the renderer can say a move has ended. Nor one
		// that has run far past any move's length, whose end was never heard.
		int now = context.getTick();
		if (renderer == null || now < midMoveTick || now - midMoveTick > MOVE_MOST_TICKS)
		{
			midMove = false;
		}

		sampleTrace(cycles);

		// Mid-obstacle: playing a climb or a squeeze, so it must not walk, turn or path
		// until it has finished and landed.
		if (advanceTransition(cycles))
		{
			return false;
		}

		// Turning to face an obstacle, then using it. See take.
		if (facingObstacle != null)
		{
			turnToward(cycles);
			facingCycles -= cycles;
			if (orientation != targetOrientation && facingCycles > 0)
			{
				return false;
			}
			GolemTransport transport = facingObstacle;
			facingObstacle = null;
			startObstacle(transport, context);
			return false;
		}

		// A route carries the golem only if it is a crossing. Roaming routes are straight
		// lines drawn without consulting the map, safe only while nobody can see: following
		// one in view put golems sliding through the sea and the cliffs, so one found here
		// is discarded.
		if (itinerary != null)
		{
			if (itinerary.isVoyage())
			{
				followItinerary(cycles, context);
				return false;
			}
			if (!isWaiting(context.getTick()))
			{
				itinerary = null;
			}
			else if (path.isEmpty() && !stepping)
			{
				walking = false;
				turnToward(cycles);
				return false;
			}
		}

		turnToward(cycles);

		// Movement is resolved a step at a time rather than by advancing a distance, so a
		// large `cycles` - after a stutter or a tab-out - carries the golem through several
		// whole tiles instead of teleporting it past a wall.
		int remaining = cycles;
		while (remaining > 0)
		{
			if (!stepping)
			{
				// Dancing, or waving at the player: it finishes the step it is on and drops the
				// rest of the walk. A leg is up to fifty tiles, so a golem that only stopped at the
				// end of one would still be walking when the celebration was over. Never partway up
				// a climb, though: dropping the rest of that left the golem on the cliff face, in its
				// climbing gait, with no step left to finish the climb on.
				boolean stopping = (dancing || midMove || isGreeting(context.getTick())) && gaitWalk == -1;
				if (stopping && !path.isEmpty())
				{
					path.clear();
				}
				if (path.isEmpty())
				{
					walking = false;
					// And it goes nowhere else until it is done: not even a shortcut under its nose.
					// Nor does a golem that has walked to its place at a quayside to wait for a crew.
					if (stopping || isWaiting(context.getTick()))
					{
						return searched;
					}
					dwellRemaining -= remaining;
					if (dwellRemaining > 0)
					{
						return searched;
					}
					// Hopping off a stepping stone is not a search and must not wait on the
					// budget: a golem mid-crossing has nowhere to walk, so being told to
					// try next frame left it in a river until the watchdog came.
					if (takeQueuedTransport(context) || takeQueuedDock(context) || considerTransport(context))
					{
						return searched;
					}
					// Standing where it cannot walk off, nothing fresh to take: go back the
					// way it came rather than wait for the watchdog.
					if (!context.getMemory().isKnownWalkable(fineX / TILE, fineY / TILE, plane)
						&& takeWayOut(context, true))
					{
						return searched;
					}

					if (!context.isMayPath())
					{
						// This frame's search budget is spent: stand still rather than join
						// a stampede of path searches.
						return searched;
					}
					// Overshoot is discarded rather than carried forward.
					remaining = 0;
					searched = true;
					// Somewhere it knows no way out of: back the way it came in, now and then.
					if (headHome(context))
					{
						return searched;
					}
					// Sometimes the dock nearby, otherwise anywhere. One search a frame is
					// the budget, so a dock it could not reach is left for a pause.
					boolean toDock = headForDock(context);
					if (toDock && path.isEmpty())
					{
						dwellRemaining = DWELL_MIN + random.nextInt(DWELL_SPREAD);
						return searched;
					}
					if (!toDock)
					{
						chooseDestination(context);
					}
					if (path.isEmpty())
					{
						// Nowhere to go - usually a golem boxed in by scenery. Counted,
						// because the difference between briefly hemmed in and
						// permanently trapped is only how often this happens.
						failedSearches++;
						// Twice in a row with nowhere to walk is a dead end, not bad luck -
						// but on ground it can stand on, only a fresh way out is taken.
						// Going back is how golems ping-ponged up and down the tower ladder
						// a hundred and sixty times, each shut-in floor sending them back.
						// Only on a floor too small to walk, though: in a crowd, or anywhere a search
						// happens to fail, it took any row in reach and walked golems into pockets.
						if (failedSearches >= 2
							&& context.enclosedArea(fineX / TILE, fineY / TILE, plane) < PENNED_TILES
							&& (takeWayOut(context, false) || walkToWayOut(context)))
						{
							failedSearches = 0;
							return searched;
						}
						dwellRemaining = DWELL_MIN + random.nextInt(DWELL_SPREAD);
						return searched;
					}
					failedSearches = 0;
					continue;
				}

				// Checked again at the moment of stepping, not only when the path was planned:
				// a door open when the golem chose its route can be shut by the time it gets
				// there. A climb is exempt, walking up a cliff never walkable to begin with.
				int[] next = path.peek();
				int fromX = fineX / TILE;
				int fromY = fineY / TILE;
				int stepX = next[0] - fromX;
				int stepY = next[1] - fromY;
				if (gaitWalk == -1 && Math.abs(stepX) <= 1 && Math.abs(stepY) <= 1
					&& (stepX != 0 || stepY != 0)
					&& !context.getMemory().canStep(fromX, fromY, plane, stepX, stepY))
				{
					path.clear();
					walking = false;
					dwellRemaining = DWELL_MIN;
					return searched;
				}
				beginStep(path.poll());
			}

			int left = CYCLES_PER_TILE - stepElapsed;
			if (remaining < left)
			{
				stepElapsed += remaining;
				remaining = 0;
			}
			else
			{
				remaining -= left;
				stepElapsed = CYCLES_PER_TILE;
			}

			interpolateStep();

			if (stepElapsed >= CYCLES_PER_TILE)
			{
				stepping = false;

				// A climb ends the moment its last tile is reached, before anything else
				// looks at this golem: leaving the gait on would walk it around the world
				// in a climbing pose, and rolling again would abandon the obstacle.
				if (gaitWalk != -1 && path.isEmpty())
				{
					finishTrace();
					endClimb();
					// Walked across, it has landed like any other crossing, instance change
					// included. Only animated crossings applied that, so a golem that
					// climbed the pew was drawn on the wrong side of it.
					landInInstance();
					walking = false;
					dwellRemaining = DWELL_MIN + random.nextInt(DWELL_SPREAD);
					return searched;
				}

				// A tile has just been entered, the one moment a transport roll may happen:
				// rolling per frame would tie the behaviour to framerate, and a golem
				// loitering near a ladder would eventually always take it. A shortcut it
				// walked here to use comes first, having already decided. Never on the way to a place
				// at a quayside, or about it: a ladder taken there left a crew waiting on a golem
				// that had wandered off.
				if (!isWaiting(context.getTick()) && (takeQueuedTransport(context) || takeQueuedDock(context)
					|| considerBoarding(context) || considerTransport(context)))
				{
					return searched;
				}

				if (path.isEmpty())
				{
					walking = false;
					dwellRemaining = DWELL_MIN + random.nextInt(DWELL_SPREAD);
					return searched;
				}
			}
		}
		return searched;
	}

	/**
	 * How far from a transport's origin a golem will consider using it, in tiles. Three, not
	 * one: only 3.2% of walkable ground is within three tiles of a transport origin at all,
	 * so insisting on an exact hit makes the network effectively invisible.
	 */
	private static final int TRANSPORT_REACH = 3;

	/**
	 * Chance of taking a transport the golem is standing on, falling off with distance.
	 * Deliberately well under certainty: a forced "use what you are next to" rule turns a
	 * ladder in a corridor into a wall. A failed roll just means it carries on.
	 */
	private static final float TRANSPORT_CHANCE = 0.3f;

	/**
	 * Rolls for a voyage, for a golem standing at a dock where the player can see it.
	 * Sailing was once planned only out of range, so boats appeared and vanished at the edge
	 * of what was loaded; with crossings cached per pair of ports and searches rationed to
	 * one a frame, a golem in view goes if the route is known and otherwise stays put.
	 *
	 * @return true if the golem set off, stopping this frame's movement
	 */
	private boolean considerBoarding(RoamContext context)
	{
		RoamPlanner planner = context.getPlanner();
		if (planner == null)
		{
			return false;
		}

		Itinerary crossing = planner.planVoyage(currentTile(), context.getTick(),
			random, transportMemory, context);
		if (crossing == null)
		{
			return false;
		}

		// The step under way is finished, not dropped: held at the quayside for a crew instead of
		// sailing, a golem stopped mid-step stood between two tiles for the whole wait.
		path.clear();
		embark(crossing, context);
		return true;
	}

	/**
	 * Rolls for a transport near the tile just entered, and takes one if it wins.
	 *
	 * @return true if it used something, stopping this frame's movement
	 */
	private boolean considerTransport(RoamContext context)
	{
		TransportNetwork network = context.getTransports();
		if (network == null || network.size() == 0)
		{
			return false;
		}

		int tileX = fineX / TILE;
		int tileY = fineY / TILE;

		// True when the golem cannot walk out of where it is but the network can: halfway
		// across a river, on a stone. The next hop then happens without a roll.
		boolean stranded = !context.getMemory().isKnownWalkable(tileX, tileY, plane)
			&& (network.isStone(tileX, tileY, plane) || !walkableBeside(tileX, tileY, context));

		// Mid-crossing, the hop back is a last resort. A stone mid-river starts a hop both
		// ways, and taking whichever was found first had golems turn round on the middle
		// stone and hop back where they began.
		GolemTransport wayBack = null;

		// The spaces it recently left, asked for once something has won its roll. See below.
		Set<Integer> cameFrom = null;

		// Scanned as a box rather than by asking for neighbours, because the index is by
		// exact origin tile and most tiles have nothing on them: 49 cheap lookups that
		// almost always all miss.
		for (int dx = -TRANSPORT_REACH; dx <= TRANSPORT_REACH; dx++)
		{
			for (int dy = -TRANSPORT_REACH; dy <= TRANSPORT_REACH; dy++)
			{
				int x = tileX + dx;
				int y = tileY + dy;
				if (!network.hasOrigin(x, y))
				{
					continue;
				}

				int distance = Math.abs(dx) + Math.abs(dy);
				if (distance > TRANSPORT_REACH)
				{
					continue;
				}

				for (GolemTransport transport : network.from(x, y))
				{
					if (transport.getFromPlane() != plane
						|| transportMemory.onCooldown(transport, context.getTick())
						|| context.crowded(transport.getToX(), transport.getToY(), transport.getToPlane())
						|| !arrivesSomewhereKnown(transport, context)
						|| !context.getAbilities().canUse(transport))
					{
						continue;
					}

					// Somewhere that cannot be walked off - mid-crossing, on a stepping
					// stone - the next hop is not a choice: rolling for it would strand
					// the golem on a rock until the watchdog came.
					if (!stranded)
					{
						// Not straight after the last one, unless looking for a way out of a
						// crowd or out of a pen. See TransportMemory.TRANSPORT_REST_TICKS.
						if (transportMemory.restingFromTransports(context.getTick())
							&& !mayGoBack(tileX, tileY, context))
						{
							continue;
						}
						// A quarter less for each tile away, three tiles away a quarter of it,
						// and more or less again by where it leads. See RoamContext.appeal.
						float chance = TRANSPORT_CHANCE
							* (TRANSPORT_REACH + 1 - distance) / (TRANSPORT_REACH + 1)
							* context.appeal(tileX, tileY, plane,
								transport.getToX(), transport.getToY(), transport.getToPlane(), transportMemory)
							* context.desire(transportMemory, tileX, tileY, transport.getToX(), transport.getToY())
							* transportMemory.tasteFor(transport);
						if (random.nextFloat() >= chance)
						{
							continue;
						}
						// Nowhere with no way back, by choice. Asked after the roll, which turns most
						// down for less; mid-crossing the next hop is no choice and is not asked.
						if (!context.mayEnter(transport))
						{
							continue;
						}
						// Not straight back into a space it just left, as golems out of view are
						// not: in view, a golem between two rooms went back and forth through
						// their doors and ladders, a different one each time, for as long as it
						// was watched. Unless penned or in a crowd, where back may be the way out.
						if (!mayGoBack(tileX, tileY, context))
						{
							if (cameFrom == null)
							{
								cameFrom = context.spacesLeft(tileX, tileY, plane, transportMemory);
							}
							if (context.leadsInto(cameFrom, transport))
							{
								continue;
							}
						}
						// A dead end now and then, not as often as anywhere that leads on.
						float onward = context.wayOnAppeal(transport);
						if (onward < 1f && random.nextFloat() >= onward)
						{
							continue;
						}
					}

					// Only ever taken from the tile it actually starts on: the radius exists
					// so a golem notices a shortcut it walks past, not so it can use one
					// from across the clearing. Letting a stranded golem take any row in
					// range had golems on the extra slippery stone hop nowhere, the row
					// having started on the far bank.
					if (tileX != transport.getFromX() || tileY != transport.getFromY())
					{
						if (stranded)
						{
							// Mid-crossing there is nowhere to walk to, so a row starting
							// elsewhere is no use: wait for one that starts here.
							continue;
						}
						if (walkTo(transport.getFromX(), transport.getFromY(), context))
						{
							queuedTransport = transport;
							wayOffDeadEnd = null;
							return true;
						}
						continue;
					}

					if (stranded && reversesLastHop(transport, context.getTick()))
					{
						if (wayBack == null)
						{
							wayBack = transport;
						}
						continue;
					}

					take(transport, context);
					return true;
				}
			}
		}
		if (wayBack != null)
		{
			// Nothing onward from this stone: back is still better than standing in the river.
			take(wayBack, context);
			return true;
		}
		return false;
	}

	/**
	 * True if a tile beside this one is ground the golem knows it can walk. A golem on a
	 * fairy ring is not stranded the way one on a stone is. See RoamPlanner.plan.
	 */
	private boolean walkableBeside(int tileX, int tileY, RoamContext context)
	{
		for (int dx = -1; dx <= 1; dx++)
		{
			for (int dy = -1; dy <= 1; dy++)
			{
				if ((dx != 0 || dy != 0) && context.getMemory().isKnownWalkable(tileX + dx, tileY + dy, plane))
				{
					return true;
				}
			}
		}
		return false;
	}

	/** Shortest wait before going back, however small the space beyond: about 15 seconds. */
	private static final int MIN_COOLDOWN_TICKS = 25;

	/** And in a pen, five seconds: there is nowhere else to go, so there is nothing to wait for. */
	private static final int PENNED_COOLDOWN_TICKS = 8;

	/**
	 * Walkable tiles around a golem below which it counts as penned in.
	 *
	 * <p>A golem that hops a stile into a paddock has nowhere to walk off its three minutes of
	 * shore leave from shortcuts, so it paced the paddock until something else moved it. Penned,
	 * it may take the stile straight back.
	 */
	static final int PENNED_TILES = 80;

	/**
	 * How long before a golem may go back the way a transport just took it, scaled by the
	 * room on the far side. The full wait suits open ground; behind the stile is a pen of a
	 * few dozen tiles, where two minutes let arrivals outnumber departures until it could
	 * not be drawn. Unwalkable landings keep the full wait, being crossings rather than
	 * small spaces.
	 */
	private int cooldownFor(GolemTransport transport, RoamContext context)
	{
		int x = transport.getToX();
		int y = transport.getToY();
		int toPlane = transport.getToPlane();
		if (!context.getMemory().isKnownWalkable(x, y, toPlane))
		{
			return TransportMemory.COOLDOWN_TICKS;
		}
		// The smaller of the two ends: a golem in a pen is as stuck as one that hopped into it,
		// and the way back out is the only way there is.
		int room = Math.min(context.enclosedArea(x, y, toPlane),
			context.enclosedArea(fineX / TILE, fineY / TILE, plane));
		float share = Math.min(1f, room / (float) RoamContext.OPEN_AREA);
		int floor = room < PENNED_TILES ? PENNED_COOLDOWN_TICKS : MIN_COOLDOWN_TICKS;
		return Math.max(floor, Math.round(TransportMemory.COOLDOWN_TICKS * share));
	}

	/**
	 * Leaves a dead end by whatever starts here, even the way the golem just came. The
	 * reverse cooldown stops a golem pacing through a door, but at the top of a ladder with
	 * no floor to walk on it was the only thing keeping the golem there, re-planning until
	 * the watchdog lifted it. A fresh way out is preferred; the way back is the fallback.
	 *
	 * @return true if a transport was taken
	 */
	private boolean takeWayOut(RoamContext context, boolean evenBack)
	{
		TransportNetwork network = context.getTransports();
		if (network == null)
		{
			return false;
		}
		// A fresh way that leads somewhere with a way back, by preference; then any fresh way.
		GolemTransport fresh = null;
		GolemTransport back = null;
		for (GolemTransport transport : network.from(fineX / TILE, fineY / TILE))
		{
			if (transport.getFromPlane() != plane
				|| !arrivesSomewhereKnown(transport, context)
				|| !context.getAbilities().canUse(transport))
			{
				continue;
			}
			if (!transportMemory.onCooldown(transport, context.getTick()))
			{
				if (context.mayEnter(transport))
				{
					take(transport, context);
					return true;
				}
				if (fresh == null)
				{
					fresh = transport;
				}
				continue;
			}
			if (back == null)
			{
				back = transport;
			}
		}
		if (fresh != null)
		{
			take(fresh, context);
			return true;
		}
		if (back == null || !evenBack)
		{
			return false;
		}
		take(back, context);
		return true;
	}

	/**
	 * True if this is a door whose two sides are a step or two apart and every step between them is
	 * open now: the door is open. Two, for a door in a wall a tile thick, or a gate with a tile between.
	 */
	private boolean standsOpen(GolemTransport transport, RoamContext context)
	{
		int x = transport.getFromX();
		int y = transport.getFromY();
		int toX = transport.getToX();
		int toY = transport.getToY();
		if (transport.getArchetype() != GolemTransport.ARCHETYPE_DOOR || transport.getFromPlane() != transport.getToPlane()
			|| Math.max(Math.abs(toX - x), Math.abs(toY - y)) > OPEN_DOOR_SPAN || x == toX && y == toY)
		{
			return false;
		}
		while (x != toX || y != toY)
		{
			int dx = Integer.signum(toX - x);
			int dy = Integer.signum(toY - y);
			if (!context.getMemory().canStep(x, y, transport.getFromPlane(), dx, dy))
			{
				return false;
			}
			x += dx;
			y += dy;
		}
		return true;
	}

	/** The furthest apart, in tiles, a door's two sides are walked between when it stands open. */
	private static final int OPEN_DOOR_SPAN = 2;

	/**
	 * Whether a golem here may go back the way it came, or rest less: in a crowd, or penned in, where
	 * back is often the only way out. Asked only once something is otherwise to be taken, since
	 * measuring a pen floods the ground around it.
	 */
	private boolean mayGoBack(int tileX, int tileY, RoamContext context)
	{
		return context.crowdedRegion(tileX, tileY, plane) || context.enclosedArea(tileX, tileY, plane) < PENNED_TILES;
	}

	/** How far a golem stuck on a small floor looks for the way off it, in tiles. */
	private static final int WAY_OUT_REACH = 10;

	/**
	 * Walks to the nearest way off a floor it can find nowhere to walk on, and takes it, even the
	 * way it came. A golem that climbed onto a lookout the size of a room found nowhere to go,
	 * over and over, until the watchdog carried it to the plinth - which, from the ground, looked
	 * like a golem crafted out of nothing. It goes back down, and the ladder is then on its long
	 * cooldown both ways, so it does not climb straight back up.
	 *
	 * @return true if it set off for one
	 */
	private boolean walkToWayOut(RoamContext context)
	{
		TransportNetwork network = context.getTransports();
		if (network == null)
		{
			return false;
		}
		int tileX = fineX / TILE;
		int tileY = fineY / TILE;
		// The nearest that leads somewhere with a way back and is not on its cooldown, by preference;
		// failing that the nearest of any, since a golem on a lookout must get down somehow.
		GolemTransport best = null;
		int bestSpan = Integer.MAX_VALUE;
		GolemTransport fallback = null;
		int fallbackSpan = Integer.MAX_VALUE;
		for (int dx = -WAY_OUT_REACH; dx <= WAY_OUT_REACH; dx++)
		{
			for (int dy = -WAY_OUT_REACH; dy <= WAY_OUT_REACH; dy++)
			{
				int span = Math.max(Math.abs(dx), Math.abs(dy));
				if (span >= bestSpan)
				{
					continue;
				}
				for (GolemTransport transport : network.from(tileX + dx, tileY + dy))
				{
					if (transport.getFromPlane() != plane || !arrivesSomewhereKnown(transport, context)
						|| !context.getAbilities().canUse(transport))
					{
						continue;
					}
					if (!transportMemory.onCooldown(transport, context.getTick()) && context.mayEnter(transport))
					{
						best = transport;
						bestSpan = span;
						break;
					}
					if (span < fallbackSpan)
					{
						fallback = transport;
						fallbackSpan = span;
					}
				}
			}
		}
		if (best == null)
		{
			best = fallback;
			bestSpan = fallbackSpan;
		}
		if (best == null)
		{
			return false;
		}
		if (bestSpan == 0)
		{
			leaveDeadEnd(best, context);
			return true;
		}
		if (walkTo(best.getFromX(), best.getFromY(), context))
		{
			queuedTransport = best;
			wayOffDeadEnd = best;
			return true;
		}
		return false;
	}

	/** The way off a dead end the golem is walking to, taken whatever its cooldown; or null. */
	private GolemTransport wayOffDeadEnd;

	private void leaveDeadEnd(GolemTransport transport, RoamContext context)
	{
		wayOffDeadEnd = null;
		take(transport, context);
		transportMemory.used(transport, context.getTick());
	}

	/**
	 * True if the far end of a transport is ground the golem could actually walk on.
	 *
	 * <p>The transport table covers the whole game; the passability map, for now, covers
	 * Wyrmscraig. A row leading somewhere unmapped would land a golem on ground the
	 * pathfinder cannot route out of. The network is allowed to be larger than the map, and
	 * this is the seam: as the mesh grows, more of the table becomes reachable.
	 */
	private boolean arrivesSomewhereKnown(GolemTransport transport, RoamContext context)
	{
		if (context.getMemory().isKnownWalkable(
			transport.getToX(), transport.getToY(), transport.getToPlane()))
		{
			return true;
		}

		// A stepping stone is blocked ground - that is why crossing it is a transport - but
		// it is somewhere you can stand, the proof being that another transport starts
		// there. So a transport origin is accepted as a destination, but only if it goes on
		// somewhere: golems hopped back and forth across the extra-slippery crossing forty
		// times each. "Goes on" means eventually reaches ground, followed hop by hop, since
		// one hop ahead passed every stone of a crossing that never reached a bank.
		return context.getTransports().leadsToGround(transport.getToX(), transport.getToY(), transport.getToPlane(),
			transport.getFromX(), transport.getFromY(), transport.getFromPlane(), TransportNetwork.CHAIN_HOPS,
			context.getAbilities()::canUse, context.getMemory()::isKnownWalkable);
	}

	/**
	 * A transport the golem is walking toward and will use on arrival. Held rather than
	 * taken at once so the golem uses it from the tile it starts on, as a player does.
	 */
	private GolemTransport queuedTransport;

	/** A dock the golem is walking up to, to consider sailing from. See dockToVisit. */
	private SailingDocks.Dock queuedDock;

	/** How long it stands between asking whether the crossing is ready, in client cycles. */
	private static final int DOCK_WAIT_CYCLES = 20;

	/**
	 * Sets off for a dock nearby, if the golem chooses to.
	 *
	 * @return true if it is on its way, with a path to the quayside
	 */
	private boolean headForDock(RoamContext context)
	{
		RoamPlanner planner = context.getPlanner();
		if (planner == null)
		{
			return false;
		}
		SailingDocks.Dock dock = planner.dockToVisit(currentTile(), transportMemory, context, random);
		if (dock == null)
		{
			return false;
		}
		// True once it has searched, found or not. See the caller.
		if (walkTo(dock.getShore().getX(), dock.getShore().getY(), context))
		{
			queuedDock = dock;
		}
		return true;
	}

	/**
	 * Rolls to sail once the golem has walked up to the dock it chose.
	 *
	 * @return true if it set sail, stopping this frame's movement
	 */
	private boolean takeQueuedDock(RoamContext context)
	{
		if (queuedDock == null)
		{
			return false;
		}
		RoamPlanner planner = context.getPlanner();
		WorldPoint here = currentTile();
		if (planner == null || !planner.atDock(here, queuedDock))
		{
			// Still on the way; or the path ran out short of it, and the plan is stale.
			if (planner == null || path.isEmpty() && !stepping)
			{
				queuedDock = null;
			}
			return false;
		}
		queuedDock = null;

		Itinerary crossing = planner.planVoyageAtDock(here, context.getTick(), random, transportMemory, context);
		if (crossing == null)
		{
			if (transportMemory.getPendingPort() >= 0)
			{
				// Decided to go and the crossing is still being worked out: wait at the dock
				// rather than walk away. How long is TransportMemory's business.
				queuedDock = planner.dockAt(here);
				dwellRemaining = DOCK_WAIT_CYCLES;
				return queuedDock != null;
			}
			// Thought better of it, or no crossing to be had: it wanders off, and may
			// come back.
			return false;
		}
		path.clear();
		stepping = false;
		embark(crossing, context);
		return true;
	}

	/**
	 * Paths the golem to a nearby tile.
	 *
	 * @return true if a route was found
	 */
	private boolean walkTo(int goalX, int goalY, RoamContext context)
	{
		// From where it will stand next: a step under way is finished first, and the walk goes on from
		// its end. Planned from the tile being left, the first step could double back.
		int tileX = (stepping ? stepToX : fineX) / TILE;
		int tileY = (stepping ? stepToY : fineY) / TILE;
		if (tileX == goalX && tileY == goalY)
		{
			// There already, or arriving with the step under way: a walk of nothing, not no way there.
			// Taken for none, a shortcut starting where the step ends was passed over.
			path.clear();
			return true;
		}

		path.clear();
		path.addAll(context.getPathfinder().findPath(tileX, tileY, plane, goalX, goalY,
			new RoamBounds(context.getMemory(), plane, tileX, tileY)));
		return !path.isEmpty();
	}

	/**
	 * Heads back out the way it came in, if it is somewhere it knows no other way out of.
	 * See RoamPlanner.wayHome.
	 *
	 * @return true if it set off, or went
	 */
	private boolean headHome(RoamContext context)
	{
		RoamPlanner planner = context.getPlanner();
		if (planner == null || random.nextFloat() >= RoamPlanner.HOMEWARD_CHANCE)
		{
			return false;
		}
		int tileX = fineX / TILE;
		int tileY = fineY / TILE;
		GolemTransport home = planner.wayHome(tileX, tileY, plane, context.getTick(), transportMemory, random);
		if (home == null)
		{
			return false;
		}
		if (tileX == home.getFromX() && tileY == home.getFromY())
		{
			take(home, context);
			return true;
		}
		if (walkTo(home.getFromX(), home.getFromY(), context))
		{
			queuedTransport = home;
			// Taken on arrival as the way off a dead end is, whatever its lock: the way back through
			// what it came in by, which a learned-first row turned round would otherwise refuse, and
			// the golem stood at it until another roll.
			wayOffDeadEnd = home;
		}
		else
		{
			// Searched and found no way: that was this frame's search. Look again after a pause.
			dwellRemaining = DWELL_MIN + random.nextInt(DWELL_SPREAD);
		}
		return true;
	}

	/**
	 * Takes the queued transport once the golem has arrived at its starting tile.
	 *
	 * @return true if it was used, stopping this frame's movement
	 */
	private boolean takeQueuedTransport(RoamContext context)
	{
		if (queuedTransport == null)
		{
			return false;
		}

		int tileX = fineX / TILE;
		int tileY = fineY / TILE;
		if (tileX != queuedTransport.getFromX() || tileY != queuedTransport.getFromY())
		{
			// Still on the way. If the path ran out without arriving, the plan is stale:
			// drop it rather than hold out for a tile the golem is no longer heading to.
			if (path.isEmpty() && !stepping)
			{
				queuedTransport = null;
				wayOffDeadEnd = null;
			}
			return false;
		}

		GolemTransport transport = queuedTransport;
		queuedTransport = null;

		if (transport == wayOffDeadEnd)
		{
			leaveDeadEnd(transport, context);
			return true;
		}
		// Any other: the way out belonged to a plan since dropped, and must not excuse a later one.
		wayOffDeadEnd = null;
		if (transportMemory.onCooldown(transport, context.getTick())
			|| !context.getAbilities().canUse(transport))
		{
			return false;
		}

		take(transport, context);
		return true;
	}

	/** Which way, and when, the golem last used a transport on one plane. See reversesLastHop. */
	private int lastHopX;
	private int lastHopY;
	private int lastHopTick = Integer.MIN_VALUE;

	/** How long after a hop the next one is still part of the same crossing, in ticks. */
	private static final int CROSSING_TICKS = 20;

	/** True if this transport would take the golem back against the hop it has just made. */
	private boolean reversesLastHop(GolemTransport transport, int tick)
	{
		if (tick - lastHopTick > CROSSING_TICKS || transport.getFromPlane() != transport.getToPlane())
		{
			return false;
		}
		int dx = transport.getToX() - transport.getFromX();
		int dy = transport.getToY() - transport.getFromY();
		return dx * lastHopX + dy * lastHopY < 0;
	}

	/**
	 * Uses a transport.
	 *
	 * <p>Anything with an animation is played before the golem arrives, since arriving
	 * instantly would look like a teleport. Doors and teleport-like rows have no animation
	 * and land immediately, which is correct rather than a shortcut: a door animates itself.
	 */
	private void take(GolemTransport transport, RoamContext context)
	{
		// A door standing open is a doorway, walked through as anything else is. The push through on
		// the spot is for a shut door; played in an open one, the golem looked to teleport across it.
		// Still remembered, so it is not turned straight back through.
		if (standsOpen(transport, context) && walkTo(transport.getToX(), transport.getToY(), context))
		{
			transportMemory.walkedThrough(transport, context.getTick());
			return;
		}
		// Turned to face it first, where anyone can see: a golem that arrived at a stile walking
		// the other way climbed it backwards, snapping round only as it went over. Not between the
		// hops of a crossing, whose timing was measured stone to stone, and not a ladder or a
		// trapdoor, which goes nowhere a heading could point at.
		int dx = transport.getToX() - transport.getFromX();
		int dy = transport.getToY() - transport.getFromY();
		int tick = context.getTick();
		boolean hopping = lastHopTick != Integer.MIN_VALUE && tick >= lastHopTick && tick - lastHopTick <= CROSSING_TICKS;
		// Only a crossing: the same floor and a few tiles. A dungeon ladder's far end is 6,400 tiles
		// north and a fairy ring's anywhere, and golems turned to face those before climbing.
		boolean crossing = transport.getFromPlane() == transport.getToPlane()
			&& Math.max(Math.abs(dx), Math.abs(dy)) <= FACE_REACH;
		if (tier == GolemTier.SCENE && (dx != 0 || dy != 0) && crossing && !hopping)
		{
			int heading = headingFor(dx, dy);
			if (Math.abs(((heading - orientation + 1024) & 2047) - 1024) > FACE_FIRST_OFF)
			{
				facingObstacle = transport;
				targetOrientation = heading;
				facingCycles = FACE_MOST_CYCLES;
				path.clear();
				stepping = false;
				walking = false;
				return;
			}
		}
		startObstacle(transport, context);
	}

	/** An obstacle the golem is turning to face before it uses it, or null. See take. */
	private GolemTransport facingObstacle;
	private int facingCycles;

	/** The furthest an obstacle's far side can be and still be faced first, in tiles. */
	private static final int FACE_REACH = 12;

	/** How far off facing an obstacle a golem turns first, and the longest it takes to. */
	private static final int FACE_FIRST_OFF = 256;
	private static final int FACE_MOST_CYCLES = 50;

	/** Uses a transport, facing whichever way the golem already does. */
	private void startObstacle(GolemTransport transport, RoamContext context)
	{
		if (transport.getFromPlane() == transport.getToPlane())
		{
			lastHopX = transport.getToX() - transport.getFromX();
			lastHopY = transport.getToY() - transport.getFromY();
			lastHopTick = context.getTick();
		}
		transportMemory.used(transport, context.getTick(), cooldownFor(transport, context));
		history.tookTransport(transport);
		// On landing, not now: a golem climbing into the pew is still in the cathedral.
		landingInstance = transport.entersInstance() ? 1 : transport.leavesInstance() ? 0 : -1;

		// A recording beats anything reconstructed, the silent case included: a staircase
		// plays nothing but still has a shape. A plane change may be performed from one
		// only if it barely moves, since a travelling recording would slide the golem
		// across a floor it has left.
		MotionCurve recorded = context.getKnowledge() == null ? null
			: context.getKnowledge().curveFor(transport);
		boolean samePlane = transport.getFromPlane() == transport.getToPlane();
		if (recorded != null && !recorded.isEmpty() && (samePlane || recorded.reach() < TILE))
		{
			beginTrace(transport, context);
			beginRecordedMotion(transport, recorded);
			return;
		}

		int animation = transport.animation();
		if (animation < 0 || animation == snapshot.getWalkAnimation())
		{
			relocate(transport.destination());
			landInInstance();
			return;
		}

		beginTrace(transport, context);

		// Stop where it is and play the clip. The path is dropped now rather than on
		// landing so the golem does not keep walking under its own animation.
		path.clear();
		stepping = false;
		walking = false;
		transitionAnimation = animation;
		// The whole clip set, in order - mount, cross, dismount - each phase running exactly
		// as long as its clip does; a fixed length made a cliff take the same two thirds of
		// a second as a doorway. What the player was seen doing beats what was shipped,
		// which beats the archetype's guess from menu text.
		int[] clips = context.getKnowledge() == null
			? transport.animations()
			: context.getKnowledge().clipsFor(transport);
		phaseClips = clips;
		phaseCycles = new int[clips.length];

		int total = 0;
		for (int i = 0; i < clips.length; i++)
		{
			int length = context.getModels() == null ? 0
				: context.getModels().animationCycles(clips[i]);
			phaseCycles[i] = Math.max(1, length);
			total += phaseCycles[i];
		}

		// How long the obstacle takes, in order of how much the answer is worth: a measured
		// tick count, then this row's authored duration, then the clip's own length. The
		// middle term used to be last, and it matters: a clip length is per obstacle *type*
		// - every rock climb plays 4435 - so ranking it above the row gave them all one
		// duration, where the tables author eight to fifteen ticks across the climbing-rock
		// rows and three to six across the stiles.
		int measuredTicks = context.getKnowledge() == null
			? MeasuredShortcuts.ticksFor(transport.getObjectId())
			: context.getKnowledge().ticksFor(transport);
		int authored = transport.getDuration() * CYCLES_PER_TICK;
		// Whether this is walked or performed follows from how long it takes and how far it
		// goes, not whether its clip loops: human_climbing (737) is a one-shot and yet is
		// the walk animation of a climb, while hole_squeeze (3835) loops and is not walked.
		// Duration does separate them - stepping stones read one or two ticks, log balances
		// and slopes six to eight.
		int obstacleTicks = measuredTicks > 0 ? measuredTicks
			: context.getObstacles() != null
				&& context.getObstacles().ticksFor(transport.getObjectId()) > 0
				? context.getObstacles().ticksFor(transport.getObjectId())
				: transport.getDuration();

		// Whether a clip may be stretched is still the clip's own business - a one-shot
		// restarted halfway through looks broken however long the obstacle takes.
		int stretchIndex = phaseCycles.length > 2 ? 1 : phaseCycles.length - 1;
		boolean stretchable = total == 0 || stretchIndex < 0
			|| context.getModels() == null
			|| context.getModels().loops(clips[stretchIndex]);

		int wanted;
		if (!stretchable)
		{
			wanted = total;
		}
		else
		{
			wanted = measuredTicks > 0 ? measuredTicks * CYCLES_PER_TICK
				: authored > 0 ? authored
				: total;
		}
		wanted = Math.max(TRANSITION_MIN_CYCLES, wanted);


		// Several ticks over several tiles is a walk, whatever the clip does.
		if (obstacleTicks >= WALKED_TICKS && total > 0)
		{
			if (beginClimb(transport, clips, context))
			{
				return;
			}
		}

		// Nothing to play: a ladder down, whose shipped clip is not trusted, or an obstacle the
		// player was seen to cross without one. The golem stands for as long as it takes. A
		// transition of no cycles never finished, and the golem stayed at the top of the ladder.
		if (clips.length == 0)
		{
			clips = new int[]{snapshot.getIdlePoseAnimation()};
			phaseClips = clips;
			phaseCycles = new int[]{wanted};
			total = wanted;
		}

		if (phaseCycles.length > 0 && total != wanted)
		{
			int loop = phaseCycles.length > 2 ? 1 : phaseCycles.length - 1;
			phaseCycles[loop] = Math.max(1, phaseCycles[loop] + (wanted - total));

			total = 0;
			for (int length : phaseCycles)
			{
				total += length;
			}
		}

		phase = 0;
		transitionAnimation = clips.length > 0 ? clips[0] : animation;
		transitionTotal = total;
		transitionCycles = total;
		phaseRemaining = phaseCycles.length > 0 ? phaseCycles[0] : total;
		transitionDestination = transport.destination();

		// A hop or a vault carries the golem across and is drawn doing so. A ladder or cave
		// mouth ends up elsewhere, often another plane thousands of tiles away, where
		// interpolating would slide the golem across the world.
		int span = Math.abs(transport.getToX() - transport.getFromX())
			+ Math.abs(transport.getToY() - transport.getFromY());
		// Not a door, which the golem is pushed through on the spot and comes out beyond.
		transitionGlide = transport.getFromPlane() == transport.getToPlane() && span <= 8
			&& transport.getArchetype() != GolemTransport.ARCHETYPE_DOOR;

		// Movement is whole game ticks while the clip is whatever length it was drawn at:
		// the measured hop covers its gap in one tick under a clip of nearly one and a
		// third. The measured window wins - how long it stands still, then how long it
		// moves - which a single duration cannot express.
		int learnedDelay = context.getKnowledge() == null ? 0
			: context.getKnowledge().moveDelayFor(transport);
		int learnedSpan = context.getKnowledge() == null ? 0
			: context.getKnowledge().moveSpanFor(transport);

		if (learnedSpan > 0)
		{
			// Never longer than the clip. A chained crossing recorded a 72-cycle span for a
			// 38-cycle hop, and a window wider than the transition left the golem partway
			// through its glide when it was dropped at the far side - the
			// jump-in-place-then-teleport.
			int moveCycles = Math.max(1, Math.min(learnedSpan, total));

			// The movement has to finish with the animation; the observed delay is otherwise
			// taken as given. Clamping it to the first half of the clip broke the cathedral
			// door, which measures a 30-cycle delay against a 30-cycle clip because the
			// player plays the whole animation and *then* teleports. The double jump came
			// from the tail instead: a one-shot clip completing inside a longer transition
			// is nulled by the animation controller and set again by the renderer.
			int latest = Math.max(0, total - moveCycles);
			transitionGlideDelay = Math.min(learnedDelay, latest);
			transitionGlideCycles = moveCycles;
			transitionCycles = total;
			transitionTotal = transitionCycles;
		}
		else
		{
			int movementTicks = Math.max(1, measuredTicks > 0 ? measuredTicks
				: transport.getDuration() > 0 ? transport.getDuration() : 1);
			transitionGlideDelay = 0;
			transitionGlideCycles = Math.min(total, movementTicks * CYCLES_PER_TICK);
		}

		if (transitionGlide)
		{
			transitionFromX = fineX;
			transitionFromY = fineY;
			transitionToX = transport.getToX() * TILE + TILE / 2;
			transitionToY = transport.getToY() * TILE + TILE / 2;

			// Face the way it is going, instantly: a golem that jumps sideways because it
			// had not finished turning looks worse than one that snaps round first.
			orientation = headingFor(transitionToX - transitionFromX,
				transitionToY - transitionFromY);
			targetOrientation = orientation;
		}

		if (transport.wantsPropAnimation())
		{
			pendingProp = transport;
		}
	}

	/**
	 * A transport whose scenery should be animated, claimed once by the plugin. The golem
	 * knows nothing about models or the scene: it decides a plank should lower, and the
	 * plugin decides whether anyone can see it.
	 */
	private GolemTransport pendingProp;

	/** Takes the pending prop request, if any. Returns null once it has been claimed. */
	GolemTransport claimPendingProp()
	{
		GolemTransport claimed = pendingProp;
		pendingProp = null;
		return claimed;
	}

	/**
	 * Walks the golem through an obstacle wearing the obstacle's gait, as the game does:
	 * tile-by-tile movement with the walk and idle animations swapped for climbing ones.
	 * The loop clip is the walk cycle, so a three-tile scramble takes three ticks with
	 * nobody choosing a duration. Only for obstacles on one plane over ground the golem can
	 * be drawn crossing.
	 *
	 * @return true if the golem is now climbing, false to fall back to a played clip
	 */
	private boolean beginClimb(GolemTransport transport, int[] clips, RoamContext context)
	{
		if (transport.getFromPlane() != transport.getToPlane())
		{
			return false;
		}

		int span = span(transport.getToX() - fineX / TILE, transport.getToY() - fineY / TILE);
		if (span < 1 || span > CLIMB_MAX_TILES)
		{
			return false;
		}

		path.clear();
		int x = fineX / TILE;
		int y = fineY / TILE;
		while (x != transport.getToX() || y != transport.getToY())
		{
			x += Integer.signum(transport.getToX() - x);
			y += Integer.signum(transport.getToY() - y);
			path.add(new int[]{x, y});
		}

		// Three clips is ready, loop, merge - the idle, the walk, and a one-shot on
		// arrival. Fewer than three and the one clip is the walk.
		gaitWalk = clips.length > 2 ? clips[1] : clips[clips.length - 1];
		gaitIdle = clips.length > 2 ? clips[0] : gaitWalk;
		gaitFinish = clips.length > 2 ? clips[2] : -1;
		gaitFinishCycles = gaitFinish == -1 || context.getModels() == null ? 0
			: context.getModels().animationCycles(gaitFinish);

		transitionCycles = 0;
		transitionAnimation = -1;
		beginStep(path.poll());
		return true;
	}

	/** Clears the climbing gait, playing the step-off if the obstacle had one. */
	private void endClimb()
	{
		gaitWalk = -1;
		gaitIdle = -1;

		if (gaitFinish != -1)
		{
			transitionAnimation = gaitFinish;
			transitionTotal = Math.max(TRANSITION_MIN_CYCLES, gaitFinishCycles);
			transitionCycles = transitionTotal;
			phaseClips = new int[0];
			phaseCycles = new int[0];
			phaseRemaining = transitionTotal;
			transitionGlide = false;
			transitionDestination = null;
			gaitFinish = -1;
		}
	}

	/** Tiles a golem will climb across rather than be carried over. */
	private static final int CLIMB_MAX_TILES = 12;

	/**
	 * Ticks above which a traversal is walked rather than performed. Four: the cache's own
	 * durations cluster either side - one or two for stepping stones and broken walls, six
	 * to eight for log balances and slopes - with nothing on it.
	 */
	private static final int WALKED_TICKS = 4;

	/**
	 * Where to draw the golem relative to where it is, in fine units, and on which plane.
	 * Zero everywhere but an instance, where the golem is simulated at the room's template -
	 * the only address it keeps between visits - and the player inside sees it elsewhere.
	 */
	private int drawOffsetX;
	private int drawOffsetY;
	private int drawPlane = -1;

	/**
	 * Where this golem stands on its crew's boat, in model units: across to starboard, and forward
	 * of the helm. The helm's own berth is 0,0. A crew shares one crossing, so every golem in it is
	 * at the same place by the route's reckoning and would stand in one heap without this.
	 */
	private int deckAcross;
	private int deckAlong;

	/** Set while this golem is one of a crew rather than alone on a raft. */
	@Getter
	private boolean crewed;

	/** The pose this golem steers in if it has the helm: its boat's. A raft's when sailing alone. */
	private int helmPose = GolemContent.ANIM_GOLEM_HELM;

	/** Which rail this golem looks out over on its crew's boat: 1 starboard, -1 port, 0 forward. */
	private int lookOut;

	/** Takes a berth on a boat, and the side of the hull it is on. See GolemCrew, which hands them out. */
	void board(int across, int along, int helmPose, int side)
	{
		deckAcross = across;
		deckAlong = along;
		this.helmPose = helmPose;
		lookOut = side;
		crewed = true;
	}

	/** Steps off, back to sailing alone. */
	void disembark()
	{
		deckAcross = 0;
		deckAlong = 0;
		lookOut = 0;
		helmPose = GolemContent.ANIM_GOLEM_HELM;
		crewed = false;
		boatSeed = 0;
	}

	/** True for a golem sailing alone, or at its crew's helm, whose berth is the boat's 0,0. */
	boolean isAtHelm()
	{
		return !crewed || deckAcross == 0 && deckAlong == 0;
	}

	/**
	 * The boat this golem is on, for riding its swell: the helm's id for a crew, this golem's own for
	 * a raft of its own. See FakeRaft.bob.
	 */
	private long boatSeed;

	void setBoatSeed(long seed)
	{
		boatSeed = seed;
	}

	long getBoatSeed()
	{
		return boatSeed != 0 ? boatSeed : id;
	}

	/**
	 * The way the golem is drawn facing.
	 *
	 * <p>A golem at the helm faces the way the boat is going. Everyone else looks out over the
	 * side they are standing on, which is what people on a boat do and what keeps a crew from
	 * reading as a rank of soldiers.
	 */
	int drawOrientation()
	{
		if (isAboard())
		{
			// Out over the rail, in the ship's own frame: the client turns the ship.
			return deckFacing;
		}
		if (!crewed || isAtHelm() || lookOut == 0)
		{
			// In a turned instance chunk, turned with it: a quarter turn takes east to south, and
			// south (0) round to west (512) is a quarter of the way round.
			return orientation + 512 * drawQuarters & 2047;
		}
		// Right of a golem facing south is west, which is 512 further round.
		return orientation + (lookOut > 0 ? 512 : -512) & 2047;
	}

	// ------------------------------------------------------------------ aboard the player's ship

	/** The world view of the player's ship this golem stands on, or -1 ashore. See GolemShipmates. */
	@Getter
	private int aboardView = -1;

	/** Where on the deck, in the ship's own local units, the floor it is on, and the way it faces. */
	@Getter
	private int deckX;
	@Getter
	private int deckY;
	private int deckPlane;
	private int deckFacing;

	/** The quay it stepped aboard from, which it goes back to if the voyage ends without it. */
	@Getter
	private WorldPoint aboardFrom;

	boolean isAboard()
	{
		return aboardView >= 0;
	}

	/**
	 * Steps onto the player's ship, at a place on its deck. Whatever the golem was about is dropped:
	 * it goes where the ship goes now.
	 */
	void boardShip(int view, int x, int y, int plane, int facing)
	{
		aboardFrom = currentTile();
		// Everything a walk or a route leaves behind, cleared the way a rescue clears it.
		relocate(aboardFrom);
		aboardView = view;
		deckX = x;
		deckY = y;
		deckPlane = plane;
		deckFacing = facing;
	}

	/** Keeps the golem's own position at the ship's place in the main world, in fine units. */
	void followShip(int fineX, int fineY, int plane)
	{
		this.fineX = fineX;
		this.fineY = fineY;
		this.plane = plane;
	}

	/** Steps off the ship onto the given tile, and remembers having sailed there. */
	void leaveShip(WorldPoint at, int tick)
	{
		WorldPoint ashore = at == null ? currentTile() : at;
		// Sailed, if it came ashore somewhere else. Stepping straight back off at the quay it
		// boarded from, or being sent back there, is not a voyage for the journal.
		boolean sailed = aboardFrom == null || regionOf(ashore) != regionOf(aboardFrom);
		aboardView = -1;
		// Nothing is drawn beside a golem aboard, so a guitar asked for by a dance on deck was
		// still owed when it stepped off, and was played on the quay beside a golem long done.
		propPending = false;
		relocate(ashore);
		if (sailed)
		{
			history.cameAshore(ashore);
			// A trip on the player's ship is a voyage on the golem's page as well as in its journal.
			history.sailed();
		}
		noteUnstuck(tick);
	}

	private static int regionOf(WorldPoint at)
	{
		return (at.getX() >> 6) << 8 | at.getY() >> 6;
	}

	/**
	 * Where this golem is drawn, in whichever world it is drawn in: the ship's own if it is aboard,
	 * the scene otherwise. Null if that world is not loaded, or the golem is outside the scene.
	 */
	LocalPoint drawnPoint(Client client)
	{
		if (isAboard())
		{
			WorldView ship = client.getWorldView(aboardView);
			return ship == null ? null : new LocalPoint(deckX, deckY, ship);
		}
		WorldView wv = client.getTopLevelWorldView();
		if (wv == null)
		{
			return null;
		}
		int localX = getDrawFineX() - wv.getBaseX() * TILE;
		int localY = getDrawFineY() - wv.getBaseY() * TILE;
		return isInScene(wv, localX, localY) ? new LocalPoint(localX, localY, wv) : null;
	}

	/** The floor this golem is drawn on, in the world it is drawn in. */
	int drawnLevel()
	{
		return isAboard() ? deckPlane : getDrawPlane();
	}

	void setDrawOffset(int x, int y, int plane)
	{
		setDrawOffset(x, y, plane, 0);
	}

	/**
	 * Where the golem is drawn, against where it is simulated: in an instance, from the template
	 * chunk's corner to the scene chunk's, and the quarter turns the chunk was built with.
	 */
	void setDrawOffset(int x, int y, int plane, int quarters)
	{
		drawOffsetX = x;
		drawOffsetY = y;
		drawPlane = plane;
		drawQuarters = quarters & 3;
	}

	/** Quarter turns the instance chunk this golem is drawn in was built with. See InstanceMap.turn. */
	private int drawQuarters;

	/** An eight-tile chunk, in fine units. */
	private static final int CHUNK_FINE = 8 * TILE;

	int getDrawFineX()
	{
		return drawnInChunk(true) + drawOffsetX + deckOffset(true);
	}

	int getDrawFineY()
	{
		return drawnInChunk(false) + drawOffsetY + deckOffset(false);
	}

	/**
	 * The golem's position with its place in the chunk turned as the chunk was, the continuous
	 * form of InstanceMap.turn: a quarter turn takes (u, v) to (v, S - u), S the chunk's width.
	 */
	private int drawnInChunk(boolean acrossX)
	{
		if (drawQuarters == 0)
		{
			return acrossX ? fineX : fineY;
		}
		int u = fineX & (CHUNK_FINE - 1);
		int v = fineY & (CHUNK_FINE - 1);
		for (int i = 0; i < drawQuarters; i++)
		{
			int turned = v;
			v = CHUNK_FINE - u;
			u = turned;
		}
		return acrossX ? (fineX & ~(CHUNK_FINE - 1)) + u : (fineY & ~(CHUNK_FINE - 1)) + v;
	}

	/**
	 * How far a berth lies from the boat's helm, along the world's axes. Model units and the
	 * golem's own hundred-and-twenty-eighths of a tile are the same size, so the deck's numbers
	 * need no scaling - only turning, to wherever the boat is pointing.
	 */
	private int deckOffset(boolean acrossX)
	{
		if (!crewed || deckAcross == 0 && deckAlong == 0)
		{
			return 0;
		}
		double facing = orientation * Math.PI / 1024;
		double sin = Math.sin(facing);
		double cos = Math.cos(facing);
		// Forward is where the boat points; starboard is a quarter turn right of it.
		return (int) Math.round(acrossX
			? deckAlong * -sin + deckAcross * -cos
			: deckAlong * -cos + deckAcross * sin);
	}

	int getDrawPlane()
	{
		return drawPlane >= 0 ? drawPlane : plane;
	}
	private void beginStep(int[] tile)
	{
		stepFromX = fineX;
		stepFromY = fineY;
		stepToX = tile[0] * TILE + TILE / 2;
		stepToY = tile[1] * TILE + TILE / 2;
		stepElapsed = 0;
		stepping = true;
		walking = true;
		targetOrientation = headingFor(stepToX - stepFromX, stepToY - stepFromY);
	}

	private void interpolateStep()
	{
		fineX = stepFromX + (stepToX - stepFromX) * stepElapsed / CYCLES_PER_TILE;
		fineY = stepFromY + (stepToY - stepFromY) * stepElapsed / CYCLES_PER_TILE;
	}

	/**
	 * Picks somewhere new to walk. The roam bounds are built here rather than passed in:
	 * they describe a window around where the golem is, so building one per golem per frame
	 * meant hundreds of throwaway objects for the few golems actually choosing anything.
	 */
	private void chooseDestination(RoamContext context)
	{
		int tileX = fineX / TILE;
		int tileY = fineY / TILE;
		path.clear();
		path.addAll(context.getPathfinder().wanderPath(tileX, tileY, plane,
			new RoamBounds(context.getMemory(), plane, tileX, tileY,
				(x, y) -> context.crowded(x, y, plane)), random));
	}

	/** Eases the heading toward where the golem is walking, the short way round. */
	private void turnToward(int cycles)
	{
		if (orientation == targetOrientation)
		{
			return;
		}
		int delta = ((targetOrientation - orientation + 1024) & 2047) - 1024;
		int maxTurn = TURN_PER_CYCLE * cycles;
		if (Math.abs(delta) <= maxTurn)
		{
			orientation = targetOrientation;
		}
		else
		{
			orientation = (orientation + Integer.signum(delta) * maxTurn) & 2047;
		}
	}

	/**
	 * The orientation for a direction of travel, to the nearest angle rather than the
	 * nearest cardinal. Picking the nearest cardinal was exact while the pathfinder only
	 * stepped north, south, east and west; once diagonals were added a golem walking
	 * north-east faced north and crabbed sideways.
	 *
	 * <p>Angles run 0 south, 512 west, 1024 north, 1536 east, so north is the zero of the
	 * arc-tangent and east a quarter turn on.
	 */
	private static int headingFor(int dx, int dy)
	{
		if (dx == 0 && dy == 0)
		{
			return NORTH;
		}
		return (int) (1024 + Math.round(Math.atan2(dx, dy) / Math.PI * 1024)) & 2047;
	}

	/**
	 * Performs a traversal exactly as it was observed. No delay, span, stretch or
	 * walked-versus-glided decision is taken: the recording holds the position at every
	 * other cycle and the animation at every change, and both are read back.
	 */
	private void beginRecordedMotion(GolemTransport transport, MotionCurve recorded)
	{
		path.clear();
		stepping = false;
		walking = false;
		gaitWalk = -1;
		gaitIdle = -1;
		gaitFinish = -1;

		motion = recorded;
		transitionTotal = Math.max(1, recorded.cycles());
		transitionCycles = transitionTotal;
		transitionGlide = false;
		transitionGlideDelay = 0;
		transitionGlideCycles = 0;
		phaseClips = new int[0];
		phaseCycles = new int[0];
		phase = 0;
		transitionDestination = transport.destination();
		int opening = recorded.animationAt(0);
		transitionAnimation = opening != -1 ? opening : snapshot.getIdlePoseAnimation();

		// The axis and the distance, both in fine units from exactly where the golem is.
		// These used to come from its *tile* while the offsets were added to its exact
		// position, so the fraction of a tile it stood off centre was added to the distance
		// and the golem slid past the far side before the arrival snapped it back.
		motionFrame = recorded.frameAt(0);
		motionFromX = fineX;
		motionFromY = fineY;

		float dx = transport.getToX() * TILE + TILE / 2f - fineX;
		float dy = transport.getToY() * TILE + TILE / 2f - fineY;
		float needed = (float) Math.sqrt(dx * dx + dy * dy);
		motionAxisX = needed < 1f ? 0f : dx / needed;
		motionAxisY = needed < 1f ? 1f : dy / needed;

		// The recording covered the player's distance; this golem may have a different one.
		// Scale the forward part so it arrives exactly.
		int reach = recorded.reach();
		motionScale = reach <= TILE / 2 || needed < 1f ? 1f : needed / reach;

		// Face the way it is about to go, immediately: a golem still turning as a recording
		// starts performs the whole thing at the wrong angle. Turned by the player's facing
		// relative to their travel - on the rockslide they face the rock and move away from
		// it, and a golem facing its travel climbed off the cliff. Only where the traversal
		// goes somewhere; a ladder has no direction to be relative to.
		int heading = headingFor(Math.round(dx), Math.round(dy));
		targetOrientation = recorded.hasFacing() && needed >= TILE / 2f
			? (heading + recorded.facing()) & 2047
			: heading;
		orientation = targetOrientation;
	}

	/** Where the recording started from, in fine units. */
	private int motionFromX;
	private int motionFromY;

	/** Forward scaling, so a recording made from one tile away still lands correctly. */
	private float motionScale = 1f;

	/**
	 * Which frame the recording says the animation should be on, or -1. Read by the renderer
	 * so animation and movement share one clock; without it the clip advances at the draw
	 * rate while the position advances on cycle count, and the drift looks like skipping.
	 */
	@Getter
	private int motionFrame = -1;

	/**
	 * Starts this golem dancing where it stands, for its own reasons rather than a celebration:
	 * the life of the party, with a crowd around it. No fireworks - those are for the occasions.
	 */
	void startParty(int untilTick)
	{
		partyUntil = untilTick;
		nextDanceMove();
	}

	boolean isPartying(int tick)
	{
		return tick < partyUntil && partyUntil - tick <= MOST_MOMENT_TICKS;
	}

	/**
	 * Longest a wave, a look or a dance may still have to run, in ticks. Every one is a few seconds;
	 * a deadline further off than this was set against a clock that has since gone backwards, and
	 * believing it would hold the golem still for as long as the old clock had been running.
	 */
	private static final int MOST_MOMENT_TICKS = 30;

	/**
	 * Forgets anything the golem was in the middle of for the player's benefit - a wave, a look, a
	 * dance of its own - on a log out or a world hop, where the moment is over whatever the clock
	 * says.
	 */
	void forgetMoments()
	{
		greetUntil = 0;
		partyUntil = 0;
		wavedAtGolem = -1;
		playerWaves = 0;
		nearPlayerTick = Integer.MIN_VALUE;
	}

	/** Waves at the player since they last came by, and the last tick they were near. */
	private int playerWaves;
	private int nearPlayerTick = Integer.MIN_VALUE;

	/**
	 * Notes the player is near, and says how long this golem leaves between waves at them: the
	 * gap given after the first wave, doubling with each one after, up to sixteen times as long.
	 * Counted afresh once the player has been away, or the tick has gone backwards after a hop.
	 */
	int playerWaveGap(int tick, int gap, int awayTicks)
	{
		if (tick < nearPlayerTick || tick - nearPlayerTick > awayTicks)
		{
			playerWaves = 0;
		}
		nearPlayerTick = tick;
		return gap << Math.min(Math.max(0, playerWaves - 1), 4);
	}

	boolean hasWavedAtPlayer()
	{
		return playerWaves > 0;
	}

	/** Waves at the player, and counts it. See playerWaveGap. */
	void greetPlayer(int untilTick, int dx, int dy)
	{
		greet(untilTick, dx, dy);
		playerWaves++;
	}

	/** Gives up waiting at a quay for a crew, and plans for itself again. */
	void stopWaiting()
	{
		relocate(currentTile());
	}

	/**
	 * Done waiting at a quay, let go by the crew it was waiting for: it plans for itself from here,
	 * finishing any step it is on rather than being stood on its tile.
	 */
	void endWait()
	{
		if (itinerary != null && itinerary == waiting)
		{
			itinerary = null;
		}
		waiting = null;
	}

	/**
	 * Turns the golem to face something and waves at it, for as long as the wave takes.
	 *
	 * @param dx how far east the thing being waved at is
	 * @param dy how far north it is
	 */
	void greet(int untilTick, int dx, int dy)
	{
		attend(untilTick, dx, dy, GolemContent.ANIM_EMOTE_WAVE);
	}

	/** The tick this golem last waved at another golem, or -1 if it never has. */
	private int wavedAtGolem = -1;

	/**
	 * Whether it has been long enough since this golem last waved at another. Also true if the
	 * tick has gone backwards, which is the counter starting again after a world hop.
	 */
	boolean mayWaveAtGolem(int tick, int cooldown)
	{
		return wavedAtGolem < 0 || tick < wavedAtGolem || tick - wavedAtGolem >= cooldown;
	}

	/** Waves at another golem where it stands, and remembers having done so. */
	void waveAtGolem(int untilTick, int dx, int dy, int tick)
	{
		greet(untilTick, dx, dy);
		wavedAtGolem = tick;
	}

	/** Stops and looks at something, playing nothing: a golem that finds the player interesting. */
	void watch(int untilTick, int dx, int dy)
	{
		attend(untilTick, dx, dy, -1);
	}

	/** Stops, looks, and copies what it saw. The animation is the player's own. */
	void mimic(int untilTick, int dx, int dy, int animation)
	{
		attend(untilTick, dx, dy, animation);
	}

	/**
	 * Turns to face something and holds there, playing a clip or nothing at all.
	 *
	 * @param animation what to play while it does, or -1 to stand and look
	 */
	private void attend(int untilTick, int dx, int dy, int animation)
	{
		greetUntil = untilTick;
		greetAnimation = animation;
		// headingFor, because an orientation worked out by hand faced the golem the other way.
		targetOrientation = headingFor(dx, dy);
	}

	/** What the golem plays while it is attending to something; -1 to stand and look. */
	private int greetAnimation = GolemContent.ANIM_EMOTE_WAVE;

	boolean isGreeting(int tick)
	{
		return tick < greetUntil && greetUntil - tick <= MOST_MOMENT_TICKS;
	}

	/**
	 * True if the last wave ended at least {@code gap} ticks ago, or there was none. A friendly
	 * golem rolls to wave every tick the player is near, and without a gap it waved, stopped for a
	 * tick and waved again. Read against a clock that went backwards, the gap is simply over.
	 */
	boolean mayGreetAgain(int tick, int gap)
	{
		return greetUntil == 0 || tick < greetUntil - MOST_MOMENT_TICKS || tick - greetUntil >= gap;
	}

	void nextDanceMove()
	{
		if (danceRandom == null)
		{
			danceRandom = new Random(id * 0x2545F4914F6CDD1DL);
		}
		danceMove = GolemDance.random(danceRandom);
		propPending = danceMove.getSpotanim() != -1;
		midMove = true;
		midMoveTick = tickNow;
	}

	/**
	 * Whether the move just started needs something drawn beside the golem, clearing the ask.
	 * Called once per move by whoever can draw it; see GolemsDontDiePlugin.spawnDanceProp.
	 */
	boolean takeDanceProp()
	{
		boolean wanted = propPending;
		propPending = false;
		return wanted;
	}

	/**
	 * The tick as the last frame saw it, so the pose can be asked about without one: the renderer
	 * asks what to play from its own callback, which has no tick to hand.
	 */
	private int tickNow;

	void setTickNow(int tick)
	{
		tickNow = tick;
	}

	/** The animation this golem should be playing right now. -1 if it has none. */
	int currentPoseAnimation()
	{
		if (isDying())
		{
			return GolemContent.GOLEM_DEATH_ANIMATION;
		}
		if (transitionCycles > 0)
		{
			return transitionAnimation;
		}
		if (afloat)
		{
			// One pair of hands on the wheel. The rest of a crew stands on deck: every one of them
			// steering read as eight helmsmen and no helm.
			return isAtHelm() ? helmPose : snapshot.getIdlePoseAnimation();
		}
		if (gaitWalk != -1)
		{
			return walking ? gaitWalk : gaitIdle;
		}
		// Attending to the player - a wave, a copied emote, or simply looking - which stops for
		// nothing except the things above: a golem halfway up a ladder has its hands full. A
		// golem that is only watching plays nothing and falls through to standing still.
		if (!walking && isGreeting(tickNow) && greetAnimation != -1)
		{
			return greetAnimation;
		}
		// Last of all, and never over anything else: a golem climbing, crossing or at the helm has
		// a pose already, and one halfway through a recorded motion is having its frames set by
		// hand. Dancing is what a golem does when it is doing nothing.
		if ((dancing || isPartying(tickNow) || midMove) && !walking)
		{
			if (danceMove == null)
			{
				nextDanceMove();
			}
			return danceMove.getAnimationId();
		}
		return walking ? snapshot.getWalkAnimation() : snapshot.getIdlePoseAnimation();
	}

	/**
	 * The gait a golem climbs with, replacing its own for the length of the obstacle; -1
	 * when it uses its own, which is nearly always. A long climb is not a long animation:
	 * the game swaps the base animation set and walks the player up the cliff a tile at a
	 * time, which is why {@code human_climbing_loop} loops - it is a walk animation, and
	 * walk animations repeat once per tile.
	 */
	private int gaitWalk = -1;
	private int gaitIdle = -1;

	/** Played once on arrival, or -1. The step-off at the top of a climb. */
	private int gaitFinish = -1;

	/** Its length, measured when the climb began while the models were to hand. */
	private int gaitFinishCycles;

	// ------------------------------------------------------- using a transport

	/**
	 * The clip playing while the golem climbs, jumps or squeezes through something. All are
	 * the game's own human animations, playable because the golem shares the human rig -
	 * see {@link GolemContent#GOLEM_FRAMEMAP}. Nothing is authored or deformed.
	 */
	private int transitionAnimation = -1;

	/**
	 * Cycles of the transition the golem is actually moving for. Movement and animation do
	 * not last the same time: a stepping-stone hop covers the gap in <b>30 cycles, one game
	 * tick, while the clip runs for 38</b>. Gliding across the whole clip leaves the golem
	 * drifting when it should have landed.
	 */
	private int transitionGlideCycles;

	/**
	 * Cycles the golem holds still at the start of a traversal before moving. Measured, not
	 * assumed: four consecutive basalt hops each held 33 cycles and then crossed in 12, and
	 * the game's own script uses a 12-cycle window inside a longer action. Without it the
	 * golem slides on the animation's first frame.
	 */
	private int transitionGlideDelay;

	/**
	 * The recorded motion being performed, or null when none was available. While it is set
	 * nothing is calculated: position and animation both come from the recording, so a hop's
	 * wind-up, a climb's rise and a door's animate-then-teleport are all just recordings.
	 */
	private MotionCurve motion;

	/** The unit vector toward this traversal's destination, for orienting the recording. */
	private float motionAxisX;
	private float motionAxisY;

	/** Scratch for the curve's offset, to avoid allocating one every cycle per golem. */
	private final int[] motionOffset = new int[2];

	/** Cycles left of the transition, after which the golem arrives at the far end. */
	private int transitionCycles;

	/** Where the golem lands once the transition finishes. */
	private WorldPoint transitionDestination;

	/**
	 * Shortest a transport may take, in client cycles. A floor rather than the duration
	 * itself: every transport runs for as long as its own table row says, where a fixed
	 * length made a rock climb take the same two thirds of a second as a doorway.
	 */
	private static final int TRANSITION_MIN_CYCLES = 20;

	/** Client cycles in one game tick, which is the unit the tables give durations in. */
	private static final int CYCLES_PER_TICK = 30;

	/** How long the transition in progress runs for, so the glide and arc can be paced. */
	private int transitionTotal = TRANSITION_MIN_CYCLES;

	/** The clip set being played, its per-phase lengths, and where in it the golem is. */
	private int[] phaseClips = new int[0];
	private int[] phaseCycles = new int[0];
	private int phase;
	private int phaseRemaining;

	/** True while the golem is mid-obstacle and should not be walking or pathing. */
	boolean inTransition()
	{
		// A climb is walked rather than played, so it has no transition cycles, but it is as
		// much mid-obstacle as a hop: without this the watchdog called a golem on a cliff
		// face unwalkable ground and relocated it halfway up.
		// Turning to face one is part of it too.
		return transitionCycles > 0 || gaitWalk != -1 || facingObstacle != null;
	}

	/**
	 * Advances an in-progress transition, landing the golem when it completes.
	 *
	 * @return true while still mid-transition, when the golem must not move
	 */
	private boolean advanceTransition(int cycles)
	{
		if (transitionCycles <= 0)
		{
			return false;
		}

		transitionCycles -= cycles;

		if (motion != null)
		{
			int elapsed = transitionTotal - transitionCycles;
			int beforeX = fineX;
			int beforeY = fineY;
			motion.offsetAt(elapsed, motionAxisX, motionAxisY, motionScale, motionOffset);
			fineX = motionFromX + motionOffset[0];
			fineY = motionFromY + motionOffset[1];

			// Between clips - before the first starts, or after the last ends - the golem is
			// itself: idle, or walking if the recording is moving it. Keeping the last value
			// left golems in their bare model waiting to hop, and frozen after the stile.
			int playing = motion.animationAt(elapsed);
			transitionAnimation = playing != -1 ? playing
				: fineX != beforeX || fineY != beforeY ? snapshot.getWalkAnimation()
				: snapshot.getIdlePoseAnimation();
			motionFrame = motion.frameAt(elapsed);

			if (transitionCycles > 0)
			{
				return true;
			}
			motion = null;
			motionFrame = -1;
		}

		// Step through the clip set as each phase runs out, so the golem takes hold, hauls
		// itself up and steps off rather than looping one clip for the whole obstacle.
		phaseRemaining -= cycles;
		while (phaseRemaining <= 0 && phase + 1 < phaseClips.length)
		{
			phase++;
			phaseRemaining += phaseCycles[phase];
			transitionAnimation = phaseClips[phase];
		}

		if (transitionCycles > 0)
		{
			// Carry the golem across while the clip plays: a jump with the golem in two
			// places and nothing in between reads as a teleport with an animation on it.
			if (transitionGlide)
			{
				// Against the movement window, not the whole transition, so the golem
				// arrives when it should and holds still for the rest of the clip.
				int window = transitionGlideCycles > 0 ? transitionGlideCycles : transitionTotal;
				int elapsed = transitionTotal - transitionCycles - transitionGlideDelay;
				float done = elapsed <= 0 ? 0f : Math.min(1f, elapsed / (float) window);
				fineX = transitionFromX + Math.round((transitionToX - transitionFromX) * done);
				fineY = transitionFromY + Math.round((transitionToY - transitionFromY) * done);
			}
			return true;
		}

		transitionCycles = 0;
		transitionAnimation = -1;
		transitionGlide = false;
		motion = null;
		phaseClips = new int[0];
		phaseCycles = new int[0];
		phase = 0;
		if (transitionDestination != null)
		{
			finishTrace();
			relocate(transitionDestination);
			transitionDestination = null;
			landInInstance();
		}
		return false;
	}

	/** Puts a golem partway through an obstacle where the obstacle leads, at once. */
	private void landNow()
	{
		WorldPoint landing = transitionDestination;
		if (landing == null && gaitWalk != -1 && !path.isEmpty())
		{
			// A climb is walked, and ends at the last tile of its path.
			int[] last = path.peekLast();
			landing = new WorldPoint(last[0], last[1], plane);
		}
		gaitFinish = -1;
		relocate(landing != null ? landing : currentTile());
		if (landing != null)
		{
			landInInstance();
		}
		landingInstance = -1;
	}

	/** Frames kept of one traced crossing: ten seconds of them at fifty a second. */
	private static final int TRACE_SAMPLES = 500;

	/** Longest crossing traced, in tiles. Further is a teleport, with no path to get wrong. */
	private static final int TRACE_REACH = 8;

	/** The crossing being traced, or null. See GolemTraversal. */
	private GolemTransport tracing;
	private Consumer<GolemTraversal> traceSink;
	private int traceStartX;
	private int traceStartY;
	private int traceElapsed;
	private java.util.List<int[]> traceSamples;

	/** Starts tracing a crossing, if it is one worth tracing and somebody keeps the record. */
	private void beginTrace(GolemTransport transport, RoamContext context)
	{
		tracing = null;
		if (tier != GolemTier.SCENE || context.getTraversals() == null
			|| transport.getFromPlane() != transport.getToPlane()
			|| span(transport.getToX() - transport.getFromX(), transport.getToY() - transport.getFromY()) > TRACE_REACH)
		{
			return;
		}
		tracing = transport;
		traceSink = context.getTraversals();
		traceStartX = fineX;
		traceStartY = fineY;
		traceElapsed = 0;
		traceSamples = new ArrayList<>();
		traceSamples.add(new int[]{0, fineX, fineY});
	}

	private void sampleTrace(int cycles)
	{
		if (tracing == null)
		{
			return;
		}
		traceElapsed += cycles;
		if (traceSamples.size() < TRACE_SAMPLES)
		{
			traceSamples.add(new int[]{traceElapsed, fineX, fineY});
		}
	}

	/** Hands the finished crossing over, from where the golem is before it lands on the tile. */
	private void finishTrace()
	{
		if (tracing == null)
		{
			return;
		}
		if (traceSamples.size() < TRACE_SAMPLES)
		{
			traceSamples.add(new int[]{traceElapsed, fineX, fineY});
		}
		GolemTraversal done = new GolemTraversal(tracing, traceStartX, traceStartY, fineX, fineY, traceSamples);
		tracing = null;
		traceSamples = null;
		traceSink.accept(done);
	}

	/** Where the glide started and ends, in the same 128ths of a tile as everything else. */
	private int transitionFromX;
	private int transitionFromY;
	private int transitionToX;
	private int transitionToY;

	/** Whether this transition moves the golem, or is played on the spot. */
	private boolean transitionGlide;

	/**
	 * How high the golem is lifted mid-jump, in client units at the peak. A stepping-stone
	 * hop is an arc, not a slide: without this the golem crosses the water at ground level
	 * looking dragged.
	 */
	private static final int JUMP_ARC_HEIGHT = 26;

	/**
	 * Extra height for the drawn model this frame, or zero. Read by {@link FakeGolem} and
	 * added to the terrain height: a parabola across the transition, so the golem leaves
	 * the ground, peaks halfway and lands.
	 */
	int jumpArc()
	{
		if (!transitionGlide || transitionCycles <= 0)
		{
			return 0;
		}

		// You can only be in the air while you are moving. Arcing across the whole
		// transition made the golem rise and hang there for the cathedral door, which holds
		// still for thirty cycles and then teleports.
		int window = transitionGlideCycles > 0 ? transitionGlideCycles : transitionTotal;
		int elapsed = transitionTotal - transitionCycles - transitionGlideDelay;
		if (elapsed <= 0 || elapsed >= window)
		{
			return 0;
		}

		// And only for a leap. A door's single tile is a step through a doorway; lifting the
		// golem off the ground for it is a hover, not a jump.
		if (Math.abs(transitionToX - transitionFromX)
			+ Math.abs(transitionToY - transitionFromY) <= TILE)
		{
			return 0;
		}

		float done = elapsed / (float) window;
		// 4t(1-t) peaks at 1 when t is a half, and is zero at both ends.
		return Math.round(JUMP_ARC_HEIGHT * 4f * done * (1f - done));
	}
}

package com.golemsdontdie;

import java.util.*;
import javax.inject.*;
import lombok.extern.slf4j.*;
import net.runelite.api.*;

/**
 * What a golem is allowed to do - the player's account, minus an inventory.
 *
 * <p>A golem made by a player who has done Plague City can use the Ardougne shortcuts that
 * quest opens: a door locked to a golem that the player walks through freely would read as
 * a bug. Three deliberate departures:
 *
 * <ul>
 *   <li><b>Real levels, never boosted.</b> A golem cannot drink a potion, and a shortcut
 *       open only while the player was boosted would strand golems an hour later.</li>
 *   <li><b>No inventory, but a fixed purse.</b> Coins up to 500,000 and a dramen staff,
 *       never tracked. The dearest fare is 10,000, so the check always passes; it says a
 *       golem may take a ferry but not chop a canoe.</li>
 *   <li><b>No timers.</b> Conditions of the countdown form are never satisfied.</li>
 * </ul>
 *
 * <p>Read live each time: the lookups are cheap, and a cached answer would go stale
 * whenever the player levels up or flips a lever - §12 of the plan calls that the likeliest
 * way to strand a golem mid-journey.
 */
@Slf4j
@Singleton
class GolemAbilities
{
	@Inject
	private Client client;

	@Inject
	private ObstacleKnowledge knowledge;

	private static final Skill[] SKILLS = Skill.values();
	private static final Quest[] QUESTS = Quest.values();

	/**
	 * True if a golem may use this transport right now. Cheapest test first: most of the
	 * network is unconditional, so the common case returns early.
	 */
	boolean canUse(GolemTransport transport)
	{
		// Not whether the golem is permitted through, but whether the plugin knows what
		// using it looks like. The shipped animation for most obstacles is a guess from
		// menu text that measuring has overturned every time, so a golem routes around
		// anything unproven.
		if (!knowledge.isUnlocked(transport))
		{
			return false;
		}

		if (transport.isUnconditional())
		{
			return true;
		}
		return hasSkills(transport.skills())
			&& hasQuests(transport.quests())
			&& conditionsMet(transport.varbits(), true)
			&& conditionsMet(transport.varps(), false);
	}

	private boolean hasSkills(int[] requirements)
	{
		for (int i = 0; i + 1 < requirements.length; i += 2)
		{
			int level = requirements[i];
			int ordinal = requirements[i + 1];
			if (ordinal < 0 || ordinal >= SKILLS.length)
			{
				continue;
			}
			if (client.getRealSkillLevel(SKILLS[ordinal]) < level)
			{
				return false;
			}
		}
		return true;
	}

	private boolean hasQuests(int[] requirements)
	{
		for (int ordinal : requirements)
		{
			if (ordinal == TransportNetwork.QUEST_UNKNOWN)
			{
				// A quest the plugin cannot name cannot be checked, so it is not done.
				return false;
			}
			if (ordinal < 0 || ordinal >= QUESTS.length)
			{
				continue;
			}
			if (!questFinished(ordinal))
			{
				return false;
			}
		}
		return true;
	}

	/**
	 * How long a quest's state is trusted before it is asked again, as SailingDocks does.
	 * Asking runs a client script, once per candidate transport per tile a golem entered.
	 * A quest opening its shortcut a few minutes late goes unnoticed.
	 */
	private static final long QUEST_RECHECK_MILLIS = 5 * 60 * 1000L;

	/** Per quest ordinal: when it was last asked, and whether it was finished. */
	private final long[] questAskedAt = new long[QUESTS.length];
	private final boolean[] questDone = new boolean[QUESTS.length];

	private boolean questFinished(int ordinal)
	{
		long now = System.currentTimeMillis();
		if (questAskedAt[ordinal] == 0 || now - questAskedAt[ordinal] >= QUEST_RECHECK_MILLIS)
		{
			questDone[ordinal] = QUESTS[ordinal].getState(client) == QuestState.FINISHED;
			questAskedAt[ordinal] = now;
		}
		return questDone[ordinal];
	}

	/** Forgets every quest state, for a login that may be another account. */
	void forgetQuests()
	{
		Arrays.fill(questAskedAt, 0);
	}

	/**
	 * Evaluates varbit or varp conditions, stored as triples of (id, operator, value).
	 *
	 * @param varbit true to read varbits, false for varplayers
	 */
	private boolean conditionsMet(int[] conditions, boolean varbit)
	{
		for (int i = 0; i + 2 < conditions.length; i += 3)
		{
			int id = conditions[i];
			int op = conditions[i + 1];
			int wanted = conditions[i + 2];

			if (op == TransportNetwork.OP_UNKNOWN)
			{
				// A requirement that could not be read is not a requirement met.
				return false;
			}
			if (op == TransportNetwork.OP_AT)
			{
				// A wall-clock countdown, a home teleport cooling down say: a golem is
				// never waiting for one, so it never passes.
				return false;
			}

			int actual = varbit ? client.getVarbitValue(id) : client.getVarpValue(id);
			switch (op)
			{
				case TransportNetwork.OP_EQ:
					if (actual != wanted)
					{
						return false;
					}
					break;
				case TransportNetwork.OP_GT:
					if (actual <= wanted)
					{
						return false;
					}
					break;
				case TransportNetwork.OP_LT:
					if (actual >= wanted)
					{
						return false;
					}
					break;
				case TransportNetwork.OP_AND:
					if ((actual & wanted) == 0)
					{
						return false;
					}
					break;
				default:
					return false;
			}
		}
		return true;
	}
}

package com.golemsdontdie;

import lombok.*;

/**
 * The boats golems sail, and what each is made of.
 *
 * <p>Sailing's boats are scene objects, so their models live only in the cache and are read there
 * rather than named by the client. Every object built from a model in the boat family sorts into
 * three sizes, seven variants apiece. The raft is
 * the one a golem takes alone; the other two carry a crew.
 *
 * <p>Every hull is painted over a place-holder palette of purple arrows, as the raft's was, and the
 * two larger ones share a palette with each other.
 */
@Getter
@AllArgsConstructor
enum GolemBoat
{
	/**
	 * Sailing's 1x3 raft: one golem at the helm, hull 58216 from object 59494. The boat golems
	 * have sailed since sailing was added, and still what one leaving on its own takes.
	 */
	RAFT(58216, 58248, 60445, GolemContent.RAFT_HULL_RECOLOUR_FROM, GolemContent.RAFT_HULL_RECOLOUR_TO,
		128, -90, 94, -221, 228, 1, new int[][]{{0, 0}}, -1, 0, 0, 0, 0, 0, 256, -1, 13373, 13881,
		GolemContent.RAFT_HELM_MODEL, GolemContent.RAFT_HELM_RECOLOUR_FROM, GolemContent.RAFT_HELM_RECOLOUR_TO, 128,
		GolemContent.ANIM_GOLEM_HELM, 0),

	/**
	 * The 2x6 boat, hull 58218 from object 59501: three or four golems, one at the helm and the
	 * rest along a deck 324 units across and 714 long.
	 */
	SKIFF(58218, 58257, 60457, Palette.LARGE_FROM, Palette.LARGE_TO, 320, -162, 162, -438, 276, 4,
		new int[][]{{0, 0}, {-80, 142}, {80, 272}, {-40, 402}}, 58227, -192, -320, 64, 64, 64, 192, 58209, 13382, 13890,
		58204, Palette.HELM_FROM, Palette.HELM_TO, 192, 13352, 0),

	/**
	 * The 3x8 boat, hull 58220 from object 59508: up to eight, on a deck 480 units across and
	 * 1,090 long.
	 */
	SLOOP(58220, 58267, 60470, Palette.LARGE_FROM, Palette.LARGE_TO, 576, -240, 240, -554, 536, 8,
		new int[][]{{0, 0}, {8, 168}, {248, 168}, {8, 388}, {248, 388}, {8, 608},
			{248, 608}, {128, 818}}, 58228, -256, -448, 128, 448, 128, 576, 58210, 13391, 13899,
		58206, Palette.HELM_FROM, Palette.HELM_TO, 448, 13363, 128);

	/**
	 * The palette both larger hulls are painted from. Held in a class of its own because a
	 * constant of the enum may not name a field of it: the constants are built first.
	 *
	 * <p>The raft has a palette of its own, in {@link GolemContent}, where it was read before
	 * these two were known about.
	 */
	private static final class Palette
	{
		static final short[] LARGE_FROM = {-11372, -11362, -11353, -11343, -11333, -11322};
		static final short[] LARGE_TO = {6558, 6563, 6565, 6569, 6573, 6577};

		/** The bronze keel's own swap, from its object: the lowest keel a boat is built with. */
		static final short[] KEEL_FROM = {21435, 21464};
		static final short[] KEEL_TO = {5652, 5656};

		/** The Merchants' trim, the gold one: the same model as the wooden trim, painted gold. */
		static final short[] TRIM_FROM = {-31833, -31813, -31784};
		static final short[] TRIM_TO = {7104, 7104, 7114};

		/** The larger helms' own swap, as their basic wood objects paint them: wood, bronze fittings. */
		static final short[] HELM_FROM = {-11322, -11333, -11343, 21464, 21435, -31784, -31813, -31833};
		static final short[] HELM_TO = {6581, 6573, 6569, 5656, 5652, 6581, 6573, 6569};
	}

	/** The hull, the mast, and the sail's cloth, which is a separate object from the mast. */
	private final int hullModel;
	private final int mastModel;
	private final int clothModel;

	/** The place-holder colours the hull's object swaps out, and what it swaps in. */
	private final short[] hullFrom;
	private final short[] hullTo;

	/**
	 * Where the helm sits from the middle of the hull, along its length, in model units. Behind is
	 * +z, a model facing -z. As the game lays it: on the last row of a raft's or a skiff's tiles,
	 * half a tile short of half its length, and on a sloop the row past them, off the end of its
	 * hull. Either way the rudder hangs off the back. Only a raft's is stood on; see steerOffset.
	 */
	private final int helmOffset;

	/**
	 * How far the hull reaches, in its own model units: across, then along, bow first. Read out of
	 * the cache offline, and here so that a berth can be checked
	 * against the deck it is meant to be standing on rather than guessed at.
	 */
	private final int hullMinX;
	private final int hullMaxX;
	private final int hullMinZ;
	private final int hullMaxZ;

	/** How many golems this boat carries, the one at the helm included. */
	private final int berths;

	/**
	 * Where each of them stands, across then along, measured from the helm: the first of them, at
	 * nothing. The boat is drawn under the golem at the helm, so a crew placed from it rides where
	 * the boat is rather than beside it.
	 */
	private final int[][] deck;

	/**
	 * The keel under the larger hulls, with the bowsprit at its front, or -1 for the raft, which has
	 * none: without it a skiff and a sloop sailed with no spar at the bow. The bronze keel's model.
	 *
	 * <p>A keel is an object of its own on the boat, a tile off the hull, so its model is moved by
	 * that much to sit under the hull. The sloop's is as a sloop's world lays its parts out (keel
	 * on tile 1,3, the 3x8 hull from 2,3; a skiff's keel on 2,1, its 2x6 hull from 3,1).
	 */
	private final int keelModel;
	private final int keelX;
	private final int keelZ;

	/**
	 * Where the mast and the sail's cloth stand from the middle of the hull, across then along. Each
	 * is an object of its own on a tile of its own; on the raft that is the middle tile, but a
	 * sloop's rig stands three and a half tiles along and one across, and drawn at the middle it
	 * stood out over the sea beside its own hull. Both as the game lays its own boats out.
	 */
	private final int mastX;
	private final int mastZ;
	private final int clothX;
	private final int clothZ;

	/**
	 * The trim round the edge of the hull, or -1 for the raft, which has none: the Merchants'
	 * trim, which golem boats wear. A player's own boat wears whichever they chose.
	 */
	private final int trimModel;

	/**
	 * What the mast and the cloth play while the boat is under way: the sail full. Unanimated, a
	 * sail stood in its bind pose, which is neither up nor down and in the wrong place, and a skiff's
	 * foresail was not there at all. The cloth's is an _OFFSET animation, made for cloth standing
	 * along from its mast as it does on every boat - on a raft two tiles, past the helm: drawn at
	 * the mast, a raft's sail flew off the raft.
	 */
	private final int mastAnimation;
	private final int clothAnimation;

	/**
	 * The helm, and the colours its object swaps in. A raft's is a stub at the stern; a skiff's and
	 * a sloop's are tillers whose pole reaches a tile forward, to whoever is steering. Drawn with the
	 * raft's stub, a skiff's helmsman stood on the stern holding nothing.
	 */
	private final int helmModel;
	private final short[] helmFrom;
	private final short[] helmTo;

	/**
	 * Where the golem steering stands from the middle of the hull, along its length: on a raft's
	 * helm, and a tile before a tiller, toward the bow, where a player stands to steer one. The rest
	 * of the deck is measured from here.
	 */
	private final int steerOffset;

	/** The pose a player steers this boat in, which the golem at the helm takes: one per helm. */
	private final int helmPose;

	/**
	 * How far across the hull the golem steering stands, in model x: beside the tiller with its hands
	 * on it. A sloop's pose reaches its hands a column's width to one side, so its helmsman stands in
	 * the next column over from the tiller, which runs up the middle; stood on the middle line, the
	 * golem held nothing, the pole on the wrong side of it. Deck berths are measured across from
	 * here, a starboard berth being model -x.
	 */
	private final int steerAcross;

	static short[] trimFrom()
	{
		return Palette.TRIM_FROM;
	}

	static short[] trimTo()
	{
		return Palette.TRIM_TO;
	}

	static short[] keelFrom()
	{
		return Palette.KEEL_FROM;
	}

	static short[] keelTo()
	{
		return Palette.KEEL_TO;
	}

	/** The smallest boat that carries this many golems; the raft for one. */
	static GolemBoat forCrew(int golems)
	{
		if (golems <= RAFT.berths)
		{
			return RAFT;
		}
		return golems <= SKIFF.berths ? SKIFF : SLOOP;
	}
}

package com.golemsdontdie;

import java.util.*;
import java.util.regex.*;
import javax.inject.*;
import lombok.extern.slf4j.*;
import net.runelite.api.*;
import net.runelite.api.gameval.*;
import net.runelite.client.util.*;

/**
 * What the golems think is worth celebrating, and for how long.
 *
 * <p>Kept apart from the plugin because it is a set of small judgements rather than plumbing: a
 * level that went up is not a level first heard about at login, a collection log line is a
 * particular sentence, and a golem count that changed is only worth dancing about when it went up.
 * The plugin hands this the events and asks it, once a frame, whether the golems are dancing.
 *
 * <p>Client thread throughout.
 */
@Slf4j
@Singleton
class GolemCelebration
{
	/** How long the golems dance for, in game ticks. About ten seconds. */
	private static final int DANCE_TICKS = 17;

	/** The line the game prints when something is added to the collection log. */
	private static final String COLLECTION_LOG = "new item added to your collection log";

	/*
	 * The rest of the game's lines worth dancing about, worded as the game words them. Taken from
	 * RuneLite's own Screenshot and Chat Commands plugins, which recognise the same moments.
	 */

	/** A clue scroll finished: "You have completed 12 medium Treasure Trails." */
	private static final String CLUE_DONE = "You have completed";
	private static final String CLUE_TRAILS = "Treasure";

	/** A combat achievement, in chat: "Congratulations, you've completed an easy combat task: …". */
	private static final Pattern COMBAT_TASK =
		Pattern.compile("Congratulations, you've completed an? \\w+ combat task");

	/** Every way the game tells a player a pet has found them, in their backpack or not. */
	private static final String[] PET = {
		"You have a funny feeling like you're being followed",
		"You feel something weird sneaking into your backpack",
		"You have a funny feeling like you would have been followed",
	};

	/** Any timed kill or lap that beat the last: every such line ends the same way. */
	private static final String PERSONAL_BEST = "(new personal best)";

	/** The game's pop-up titles for the same moments, for a player who has the chat lines off. */
	private static final String POPUP_COLLECTION_LOG = "Collection log";
	private static final String POPUP_COMBAT_TASK = "Combat Task Completed!";

	/**
	 * Each achievement diary tier's own "complete" flag, as the game names them. Watched rather
	 * than read out of chat: the flag is exact, and the wording of the chat line is not settled.
	 */
	static final int[] DIARY_TIERS = {
		VarbitID.ARDOUGNE_DIARY_EASY_COMPLETE, VarbitID.ARDOUGNE_DIARY_MEDIUM_COMPLETE,
		VarbitID.ARDOUGNE_DIARY_HARD_COMPLETE, VarbitID.ARDOUGNE_DIARY_ELITE_COMPLETE,
		VarbitID.DESERT_DIARY_EASY_COMPLETE, VarbitID.DESERT_DIARY_MEDIUM_COMPLETE,
		VarbitID.DESERT_DIARY_HARD_COMPLETE, VarbitID.DESERT_DIARY_ELITE_COMPLETE,
		VarbitID.FALADOR_DIARY_EASY_COMPLETE, VarbitID.FALADOR_DIARY_MEDIUM_COMPLETE,
		VarbitID.FALADOR_DIARY_HARD_COMPLETE, VarbitID.FALADOR_DIARY_ELITE_COMPLETE,
		VarbitID.FREMENNIK_DIARY_EASY_COMPLETE, VarbitID.FREMENNIK_DIARY_MEDIUM_COMPLETE,
		VarbitID.FREMENNIK_DIARY_HARD_COMPLETE, VarbitID.FREMENNIK_DIARY_ELITE_COMPLETE,
		VarbitID.KANDARIN_DIARY_EASY_COMPLETE, VarbitID.KANDARIN_DIARY_MEDIUM_COMPLETE,
		VarbitID.KANDARIN_DIARY_HARD_COMPLETE, VarbitID.KANDARIN_DIARY_ELITE_COMPLETE,
		VarbitID.ATJUN_EASY_DONE, VarbitID.ATJUN_MED_DONE,
		VarbitID.ATJUN_HARD_DONE, VarbitID.KARAMJA_DIARY_ELITE_COMPLETE,
		VarbitID.KOUREND_DIARY_EASY_COMPLETE, VarbitID.KOUREND_DIARY_MEDIUM_COMPLETE,
		VarbitID.KOUREND_DIARY_HARD_COMPLETE, VarbitID.KOUREND_DIARY_ELITE_COMPLETE,
		VarbitID.LUMBRIDGE_DIARY_EASY_COMPLETE, VarbitID.LUMBRIDGE_DIARY_MEDIUM_COMPLETE,
		VarbitID.LUMBRIDGE_DIARY_HARD_COMPLETE, VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE,
		VarbitID.MORYTANIA_DIARY_EASY_COMPLETE, VarbitID.MORYTANIA_DIARY_MEDIUM_COMPLETE,
		VarbitID.MORYTANIA_DIARY_HARD_COMPLETE, VarbitID.MORYTANIA_DIARY_ELITE_COMPLETE,
		VarbitID.VARROCK_DIARY_EASY_COMPLETE, VarbitID.VARROCK_DIARY_MEDIUM_COMPLETE,
		VarbitID.VARROCK_DIARY_HARD_COMPLETE, VarbitID.VARROCK_DIARY_ELITE_COMPLETE,
		VarbitID.WESTERN_DIARY_EASY_COMPLETE, VarbitID.WESTERN_DIARY_MEDIUM_COMPLETE,
		VarbitID.WESTERN_DIARY_HARD_COMPLETE, VarbitID.WESTERN_DIARY_ELITE_COMPLETE,
		VarbitID.WILDERNESS_DIARY_EASY_COMPLETE, VarbitID.WILDERNESS_DIARY_MEDIUM_COMPLETE,
		VarbitID.WILDERNESS_DIARY_HARD_COMPLETE, VarbitID.WILDERNESS_DIARY_ELITE_COMPLETE,
	};

	/**
	 * Diary reads to take as the starting point before any is compared. A tier never finished
	 * sends nothing at login, so its first change is the real one and cannot be told from the
	 * login's own by watching changes; the flags are read instead, and the first couple of reads
	 * after login are only where the player already stood.
	 */
	private static final int DIARY_SETTLING_READS = 2;

	/** The diary flags as last read, in the order of {@link #DIARY_TIERS}; null before the first. */
	private int[] diaries;
	private int diaryReads;

	@Inject
	private GolemsDontDieConfig config;

	/** The tick the dancing ends at; 0 when nothing is being celebrated. */
	private int until;

	/**
	 * The last level seen in each skill, or 0 for one not seen yet.
	 *
	 * <p>Every skill reports its level at login, and again on every experience drop. Only a level
	 * that has been seen before and has gone up is a level-up; the first sighting is the golems
	 * being told what the player already was.
	 */
	private final int[] levels = new int[Skill.values().length];

	/** The last golem count read from the varbit, or -1 before the first. */
	private int golems = -1;

	/** A level went up. */
	void statChanged(Skill skill, int level, int tick)
	{
		int at = skill.ordinal();
		if (at < 0 || at >= levels.length)
		{
			return;
		}
		int was = levels[at];
		levels[at] = level;
		if (was > 0 && level > was && config.danceOnLevelUp())
		{
			log.debug("Golems celebrating {} level {}", skill, level);
			begin(tick);
		}
	}

	/** A game message, which might be any of the things worth dancing about. */
	void chatMessage(String message, int tick)
	{
		if (message == null)
		{
			return;
		}
		String plain = Text.removeTags(message);
		if (config.danceOnCollectionLog() && plain.toLowerCase().contains(COLLECTION_LOG))
		{
			celebrate("a collection log entry", tick);
		}
		else if (config.danceOnClue() && plain.contains(CLUE_DONE) && plain.contains(CLUE_TRAILS))
		{
			celebrate("a clue", tick);
		}
		else if (config.danceOnCombatTask() && COMBAT_TASK.matcher(plain).find())
		{
			celebrate("a combat task", tick);
		}
		else if (config.danceOnPersonalBest() && plain.contains(PERSONAL_BEST))
		{
			celebrate("a personal best", tick);
		}
		else if (config.danceOnPet())
		{
			for (String pet : PET)
			{
				if (plain.contains(pet))
				{
					celebrate("a pet", tick);
					return;
				}
			}
		}
	}

	/**
	 * One of the game's pop-up notifications, by its title. The same moments as the chat lines,
	 * for a player who turned those off: the pop-up comes either way.
	 */
	void popup(String title, int tick)
	{
		if (title == null)
		{
			return;
		}
		if (config.danceOnCollectionLog() && title.equalsIgnoreCase(POPUP_COLLECTION_LOG))
		{
			celebrate("a collection log entry", tick);
		}
		else if (config.danceOnCombatTask() && title.equalsIgnoreCase(POPUP_COMBAT_TASK))
		{
			celebrate("a combat task", tick);
		}
	}

	/** The quest reward scroll opened: a quest or a miniquest is done. */
	void questCompleted(int tick)
	{
		if (config.danceOnQuest())
		{
			celebrate("a quest", tick);
		}
	}

	/**
	 * The diary flags as they stand, in the order of {@link #DIARY_TIERS}. Any tier that has gone
	 * from not done to done since the last read is a diary finished.
	 */
	void diaries(int[] done, int tick)
	{
		if (diaries == null || diaries.length != done.length || diaryReads < DIARY_SETTLING_READS)
		{
			diaries = done.clone();
			diaryReads++;
			return;
		}
		boolean finished = false;
		for (int i = 0; i < done.length; i++)
		{
			finished |= diaries[i] == 0 && done[i] > 0;
		}
		diaries = done.clone();
		if (finished && config.danceOnDiary())
		{
			celebrate("an achievement diary", tick);
		}
	}

	private void celebrate(String what, int tick)
	{
		log.debug("Golems celebrating {}", what);
		begin(tick);
	}

	/**
	 * The number of golems ever crafted, from the varbit rather than the chat line: the count is
	 * what the game itself keeps, and it is right whether or not the player has the message
	 * filtered, is standing in a busy chat, or crafted the golem while the plugin was off.
	 */
	void golemCount(int count, int tick)
	{
		int was = golems;
		golems = count;
		if (was >= 0 && count > was && config.danceOnGolemCrafted())
		{
			log.debug("Golems celebrating golem {}", count);
			begin(tick);
		}
	}

	/** Whether the golems are dancing at this tick. */
	boolean isDancing(int tick)
	{
		return until > 0 && tick < until;
	}

	/** How long the golems have been at it, in ticks, so the fireworks can open loudly. */
	int startedAt(int tick)
	{
		return until <= 0 ? Integer.MAX_VALUE : tick - (until - DANCE_TICKS);
	}

	/** Forgotten on login and on a world hop: the tick counter starts again on the other side. */
	void reset()
	{
		until = 0;
		golems = -1;
		Arrays.fill(levels, 0);
		diaries = null;
		diaryReads = 0;
	}

	/**
	 * Starts the golems dancing, or keeps them at it: two levels at once is one celebration, not
	 * a dance cut short by the second.
	 */
	private void begin(int tick)
	{
		until = Math.max(until, tick + DANCE_TICKS);
	}
}

package com.golemsdontdie;

import java.util.*;
import javax.inject.*;
import lombok.extern.slf4j.*;

/**
 * How many golems are in each part of the world, so that they spread out rather than gather.
 *
 * <p>Each golem's choice among nearby shortcuts is purely local, so golems settle where the map's
 * shape sends them: a simulated year put a third of every golem in Meiyerditch, a walled maze with
 * a dozen ladders and no way out on foot. This count is all golems know of each other.
 *
 * <p>Counted by map region and floor - 64 tiles square, about one leg of a walk - and recounted
 * every few ticks: it need only be roughly right, and a golem's move must stay one write.
 */
@Slf4j
@Singleton
class GolemCensus
{
	/** Golems in one region and floor that nobody minds. */
	static final int ROOMY = 5;

	/** Region ids are 16 bits and floors two, so everywhere has a slot. */
	private final int[] counts = new int[1 << 18];

	void recount(Iterable<Golem> golems)
	{
		begin();
		for (Golem golem : golems)
		{
			add(golem.getFineX() / Golem.TILE, golem.getFineY() / Golem.TILE, golem.getPlane());
		}
	}

	/** Starts a count, filled with {@link #add}. */
	void begin()
	{
		Arrays.fill(counts, 0);
	}

	void add(int x, int y, int plane)
	{
		counts[key(x, y, plane)]++;
	}

	void clear()
	{
		Arrays.fill(counts, 0);
	}

	/** Golems in the region and floor this tile is in. */
	int at(int x, int y, int plane)
	{
		return counts[key(x, y, plane)];
	}

	/**
	 * How willing a golem should be to go here: 1 where there is room, towards 0 where packed. A
	 * multiplier, never a bar - a golem with one way on takes it.
	 */
	float roominess(int x, int y, int plane)
	{
		int crowd = counts[key(x, y, plane)] - ROOMY;
		return crowd <= 0 ? 1f : 1f / (1f + crowd);
	}

	private static int key(int x, int y, int plane)
	{
		return ((x >> 6) << 10) | ((y >> 6) << 2) | (plane & 3);
	}
}

package com.golemsdontdie;

import java.util.*;
import javax.inject.*;
import lombok.extern.slf4j.*;

/**
 * Where it is cold, where it is hot, and where home is, so that a golem with a taste for one of
 * them can be found there.
 *
 * <p>Curated by name against the place names the plugin already ships: every entry below is a name
 * the map or the region list gives that place, and the names are resolved to regions on load, so a
 * name that no longer exists costs nothing but a debug line. Places are marked a whole region at a
 * time, which is as fine as this needs to be - a taste in weather is not a taste in tiles.
 *
 * <p>From those regions a distance field is spread across the world in region steps, and that is
 * the whole of it: a golem likes somewhere in proportion to how near it is to the nearest place of
 * its kind. {@link #liking} is that, and {@link #desire} is what a golem makes of moving from one
 * place to another - never above 1, so a taste can only ever hold a golem back, not send it
 * somewhere the rest of its plan did not offer.
 */
@Slf4j
@Singleton
class GolemClimate
{
	/**
	 * Snow and ice.
	 *
	 * <p>Underground places are named separately where they are cold in their own right; a cave
	 * under a glacier is not, being a cave. Nothing here is a name two places share.
	 */
	private static final String[] COLD = {
		"Weiss", "Weissmere", "Weiss Melt", "Trollweiss Mountain", "Ice Path", "Trollheim",
		"Death Plateau", "Troll Stronghold", "Mountain Camp", "White Wolf Mountain", "Ice Mountain",
		"Ice Queen's Lair", "Asgarnian Ice Dungeon", "Polar Eagle Cave", "Ghorrock Dungeon",
		"Rellekka", "Neitiznot", "Jatizso", "Iceberg", "Ungael", "Waterbirth Island",
		"Wintertodt", "The Wintertodt", "Northern Tundras", "The Darkfrost", "Mount Quidamortem",
		"Winttumber Island", "Settlement Ruins", "Fishing Hamlet", "Lunar Isle",
		"Mons Gratia", "The Teomat", "The Proudspire", "Ralos Rise", "Cam Torum Entrance", "Custodia Mountains",
		"God Wars Dungeon", "Wilderness God Wars Dungeon",
	};

	/**
	 * Desert and lava, which a golem that likes the heat makes no distinction between.
	 *
	 * <p>"Bandit Camp" is deliberately absent: the desert has one and so does the Wilderness, and
	 * a name that means two places would mark them both.
	 */
	private static final String[] HOT = {
		"Al Kharid", "Shantay Pass", "Kharidian Desert", "Bedabin Camp", "Desert Mining Camp",
		"Quarry", "Pollnivneach", "Nardah", "Uzer", "Emir's Arena", "Desert Eagle Cave",
		"Kalphite Lair", "Kalphite Cave", "Agility Pyramid", "Pyramid", "Sophanem", "Menaphos",
		"Necropolis", "Ruins of Ullek", "Ruins of Unkah", "Smoke Dungeon",
		"Karamja", "Musa Point", "Mor Ul Rek", "Mount Karuulm", "Volcanic Mine", "Chasm of Fire",
		"Lava Maze", "Lava Dragon Isle", "Avium Savannah", "Locus Oasis",
		"Tombs of Amascut Lobby", "Lovakengj", "Lovakengj Assembly", "Fight Pits", "The Inferno", "Corsair Cove",
		"Gu'Tanoth", "Ourania Cave", "Callisto's Den", "Mage Arena", "Deserted Keep", "Blighted Volcano",
	};

	/**
	 * Hot places with no name of their own, or one another place shares, by region: the Wilderness's
	 * Chaos Temple (the other is by Goblin Village), the ruined chaos temple over the Ourania Cave west
	 * of Ardougne, and the Tombs of Amascut's raid, whose rooms are an instance a golem in it is
	 * simulated at the template of (the regions are RuneLite's own, from its Discord plugin).
	 */
	private static final int[] HOT_REGIONS = {12856, 9778,
		14160, 14162, 14164, 14674, 14676, 15184, 15186, 15188, 15696, 15698, 15700};

	/** Regions across the world, each side. A region ID is {@code x >> 6 << 8 | y >> 6}. */
	private static final int SIDE = 256;

	/** Distance in regions given to somewhere nothing of the kind was reached from. */
	private static final int UNREACHED = 127;

	/**
	 * How far a taste is felt, in regions: most of the world, so that a golem always has some idea
	 * which way the snow is. The slope this far out is very shallow and only its order is used -
	 * which of the ways on offer leads nearer - never as a chance in itself.
	 */
	private static final int REACH = 64;

	/** How much somewhere just outside appeals, against being in the place itself. */
	private static final float NEAR = 0.6f;

	/** How little somewhere out of reach appeals, against being in the place itself. */
	private static final float FLOOR = 0.35f;

	/** Region steps to the nearest cold place, the nearest hot one, and home, or {@link #UNREACHED}. */
	private byte[] toCold;
	private byte[] toHot;
	private byte[] toHome;

	/** Resolves the curated names and spreads the distance fields. Call once, after the names load. */
	void learn(PlaceNames names)
	{
		Set<Integer> cold = names.regionsNamed(COLD);
		Set<Integer> hot = names.regionsNamed(HOT);
		for (int region : HOT_REGIONS)
		{
			hot.add(region);
		}
		Set<Integer> home = new HashSet<>();
		for (int region : GolemContent.ISLAND_REGIONS)
		{
			home.add(region);
		}
		toCold = spread(cold);
		toHot = spread(hot);
		toHome = spread(home);
		log.debug("Climate: {} cold regions, {} hot", cold.size(), hot.size());
	}

	/** Chebyshev distance in regions from every region to the nearest of the given ones. */
	private static byte[] spread(Set<Integer> seeds)
	{
		byte[] grid = new byte[SIDE * SIDE];
		Arrays.fill(grid, (byte) UNREACHED);
		int[] queue = new int[SIDE * SIDE];
		int tail = 0;
		for (int region : seeds)
		{
			grid[region] = 0;
			queue[tail++] = region;
		}
		for (int head = 0; head < tail; head++)
		{
			int region = queue[head];
			int step = grid[region] + 1;
			if (step >= UNREACHED)
			{
				continue;
			}
			for (int dx = -1; dx <= 1; dx++)
			{
				for (int dy = -1; dy <= 1; dy++)
				{
					int x = (region >> 8) + dx;
					int y = (region & 255) + dy;
					if (x < 0 || y < 0 || x >= SIDE || y >= SIDE || grid[x << 8 | y] <= step)
					{
						continue;
					}
					grid[x << 8 | y] = (byte) step;
					queue[tail++] = x << 8 | y;
				}
			}
		}
		return grid;
	}

	/**
	 * Whether a golem cares where it is at all. Most do not, and pay nothing for any of this.
	 */
	boolean cares(TransportMemory memory)
	{
		return toCold != null && memory != null
			&& (memory.is(GolemTrait.LIKES_THE_COLD) || memory.is(GolemTrait.LIKES_THE_HEAT)
			|| memory.is(GolemTrait.TEMPERATE) || memory.is(GolemTrait.HOMESICK));
	}

	/**
	 * How much a golem likes being at a tile, from {@link #FLOOR} to 1.
	 *
	 * <p>A golem picking where to walk takes the leg it likes best of the few it found, which over
	 * a few hours is what carries it to the snow and, once there, keeps it in it.
	 */
	float liking(TransportMemory memory, int x, int y)
	{
		if (!cares(memory))
		{
			return 1f;
		}
		float liking = 1f;
		if (memory.is(GolemTrait.LIKES_THE_COLD))
		{
			liking *= nearness(toCold, x, y, false);
		}
		if (memory.is(GolemTrait.LIKES_THE_HEAT))
		{
			liking *= nearness(toHot, x, y, false);
		}
		if (memory.is(GolemTrait.TEMPERATE))
		{
			liking *= farness(toCold, x, y) * farness(toHot, x, y);
		}
		if (memory.is(GolemTrait.HOMESICK))
		{
			liking *= nearness(toHome, x, y, true);
		}
		return liking;
	}

	/**
	 * How much a golem would rather be at the far tile than the near one, from 0 to 1: 1 unless it
	 * is somewhere it likes and the offer is somewhere it likes less.
	 *
	 * <p>The shortfall counts twice over, which is deliberate: {@link #liking} decides which way a
	 * golem goes out of what its plan found, and this is what it makes of one particular offer -
	 * turning down the shortcut out of the snow it came for.
	 */
	float desire(TransportMemory memory, int fromX, int fromY, int toX, int toY)
	{
		if (!cares(memory))
		{
			return 1f;
		}
		float here = liking(memory, fromX, fromY);
		float there = liking(memory, toX, toY);
		return there >= here ? 1f : there * there / (here * here);
	}

	/** How ready a golem that likes where it is remains to go anywhere else. */
	private static final float SETTLED = 0.25f;

	/**
	 * How ready a golem is to leave where it is at all, as a multiplier on the chances of looking
	 * for a shortcut or a boat: a golem standing in the snow it came for is in no hurry to be
	 * anywhere.
	 *
	 * <p>Wanted as well as {@link #desire}, and not instead of it, because turning shortcuts down
	 * one at a time does not keep a golem anywhere: a town offers a dozen, each rolled for
	 * separately, and one of them always wins. This is the roll that keeps it still.
	 */
	float wanderlust(TransportMemory memory, int x, int y)
	{
		if (!cares(memory))
		{
			return 1f;
		}
		// Only a golem that went somewhere settles there. A temperate golem is not looking for
		// anywhere in particular - it is avoiding two - so it never stops travelling.
		boolean arrived = memory.is(GolemTrait.LIKES_THE_COLD) && isCold(x, y)
			|| memory.is(GolemTrait.LIKES_THE_HEAT) && isHot(x, y)
			|| memory.is(GolemTrait.HOMESICK) && nearness(toHome, x, y, true) >= 1f;
		return arrived ? SETTLED : 1f;
	}

	/**
	 * @param underAsAbove whether a tile underground counts as being where it is underneath.
	 *                     True of home, which a golem is near or is not - the island's own cave is
	 *                     part of it. False of weather, which a cave has none of.
	 */
	private static float nearness(byte[] grid, int x, int y, boolean underAsAbove)
	{
		// Only a cave has ground above it to count as; somewhere laid out apart from the map is
		// taken as itself.
		int above = WorldLayout.groundAbove(y);
		int region = x >> 6 << 8 | (underAsAbove && above >= 0 ? above : y) >> 6;
		if (region < 0 || region >= grid.length)
		{
			return FLOOR;
		}
		int away = grid[region];
		if (away == 0)
		{
			return 1f;
		}
		// Being in the place is worth a step down from anywhere outside it, which is what keeps a
		// golem in the snow once it is there; past that the slope is gentle, and only wanted for
		// its direction - it is what tells a golem which way the snow is.
		return NEAR - (NEAR - FLOOR) * Math.min(1f, (away - 1) / (float) (REACH - 1));
	}

	/**
	 * The mirror of {@link #nearness}, for the golem that wants none of it: being in the place is
	 * as bad as it gets, just outside is little better, and a long way off is all it asks.
	 */
	private static float farness(byte[] grid, int x, int y)
	{
		int region = x >> 6 << 8 | y >> 6;
		if (region < 0 || region >= grid.length)
		{
			return 1f;
		}
		int away = grid[region];
		if (away == 0)
		{
			return FLOOR;
		}
		return NEAR + (1f - NEAR) * Math.min(1f, (away - 1) / (float) (REACH - 1));
	}

	/** Whether a tile is one of the cold places. */
	boolean isCold(int x, int y)
	{
		return toCold != null && toCold[x >> 6 << 8 | y >> 6] == 0;
	}

	/** Whether a tile is one of the hot places. */
	boolean isHot(int x, int y)
	{
		return toHot != null && toHot[x >> 6 << 8 | y >> 6] == 0;
	}
}

