	/**
	 * Scenery animations belong to the scenery's own framemaps, 2503 and 2486 against the golem's
	 * 0, so only {@link FakeProp} can draw them.
	 *
	 * <p>Kept for the record rather than used: {@link PropFactory} reads each object's own
	 * {@code animationID} from the cache, so a plank, a gate and a fairy ring each get their own.
	 */
	static final int ANIM_PROP_GANGPLANK = 13562;
	static final int PROP_GANGPLANK_FRAMEMAP = 2503;

	/** How long a scenery animation is drawn for, in client cycles. */
	static final int PROP_CYCLES = 60;

	// ---------------------------------------------------------------------------
	// Celebrations
	// ---------------------------------------------------------------------------

	/** EMOTE_WAVE, which a friendly golem gives the player. Framemap 0, as the dances are. */
	static final int ANIM_EMOTE_WAVE = 863;

	/**
	 * The emote tab's own animations, which a golem may copy off the player.
	 *
	 * <p>Two runs of ids, and every one of them checked against the cache: all are framemap 0, the human rig the golem is built on, so they play against it untouched.
	 * Anything outside these runs is left alone - a combat or skilling clip on the wrong framemap
	 * folds a golem through itself rather than looking merely wrong.
	 */
	private static final int EMOTES_FROM = 855;
	private static final int EMOTES_TO = 868;
	private static final int LATER_EMOTES_FROM = 2105;
	private static final int LATER_EMOTES_TO = 2113;

	/**
	 * The one id in the first run that is not an emote: chopping with a rune axe, which sits between
	 * the dance and running on the spot. Copied, a golem would chop the air beside a woodcutter.
	 */
	private static final int RUNE_AXE_CHOP = 867;

	static boolean isEmote(int animation)
	{
		return animation >= EMOTES_FROM && animation <= EMOTES_TO && animation != RUNE_AXE_CHOP
			|| animation >= LATER_EMOTES_FROM && animation <= LATER_EMOTES_TO;
	}

	/**
	 * The fireworks that go off over a levelling player, drawn over a dancing golem instead.
	 *
	 * <p>Spot animation 199, which the client plays on an actor: golems are not actors, so its
	 * model and sequence are drawn as scenery like any other prop. Read from the cache: the
	 * sequence is framemap 877, the spot
	 * animation's own rig, which is why it is played against its own model and not the golem.
	 *
	 * <p>The three fireworks Death Party offers are 199, 1388 (the 99) and 1389 (max total).
	 * This is the first of them, being the one a player sees most.
	 */
	static final int SPOTANIM_FIREWORK = 199;
	static final int FIREWORK_MODEL = 411;
	static final int FIREWORK_ANIMATION = 913;

	/** How long the fireworks are drawn for, in client cycles: the sequence is 1.8 seconds. */
	static final int FIREWORK_CYCLES = 90;

	/**
	 * The guitar an air guitar is played on. Spot animation 1239, whose sequence runs the same
	 * three seconds as the emote, so the two start together and strum together.
	 */
	static final int SPOTANIM_AIR_GUITAR = 1239;
	static final int AIR_GUITAR_MODEL = 29315;
	static final int AIR_GUITAR_ANIMATION = 4752;

	/** How long a dance prop is drawn for, in client cycles: the guitar's sequence is 3 seconds. */
	static final int DANCE_PROP_CYCLES = 150;

	static boolean isGolem(int npcId)
	{
		return npcId == GOLEM_NPC_ID;
	}

}

package com.golemsdontdie;

import java.util.*;
import lombok.*;

/**
 * Golems crossing together on one boat.
 *
 * <p>They share a single crossing rather than each sailing its own, so they leave together, move as
 * one and land at the same moment; the berths they take keep them from standing in a heap, since by
 * the route's reckoning every one of them is at the same place. One is at the helm and the rest
 * stand along the deck.
 */
class GolemCrew
{
	/**
	 * The smallest crew that is worth a boat: two, as a skiff takes. At three, a pair waiting together
	 * waited out the muster and walked off, and every crew sailed at three, the moment the third came.
	 */
	static final int LEAST = 2;

	@Getter
	private final GolemBoat boat;

	/** The crossing every member is on, and the tick it ends. */
	@Getter
	private final Itinerary crossing;

	private final List<Golem> members = new ArrayList<>();

	/** The tiles members have already stepped off onto, so each lands on one of its own. */
	@Getter
	private final Set<Long> ashore = new HashSet<>();

	GolemCrew(GolemBoat boat, Itinerary crossing)
	{
		this.boat = boat;
		this.crossing = crossing;
	}

	/**
	 * Signs a golem on and gives it a berth, the helm first. Returns false if the boat is full.
	 */
	boolean sign(Golem golem)
	{
		int berth = members.size();
		if (berth >= boat.getBerths())
		{
			return false;
		}
		members.add(golem);
		// Which rail it looks out over is the side of the hull its berth is on, not of the helmsman,
		// which on a sloop stands to one side: judged from that, the whole crew looked out the one way.
		golem.board(boat.getDeck()[berth][0], boat.getDeck()[berth][1], boat.getHelmPose(),
			Integer.signum(boat.getDeck()[berth][0] - boat.getSteerAcross()));
		// One boat, one swell: everyone aboard rides it as the helm's boat does.
		golem.setBoatSeed(members.get(0).getId());
		return true;
	}

	/**
	 * The golem at the helm, which is the one the boat itself is drawn under: the first of the crew
	 * still standing. Fixed as the first, a helm crumbling mid-crossing took the boat with it, and
	 * the rest finished the crossing on open water.
	 */
	Golem helm()
	{
		for (Golem member : members)
		{
			if (!member.isDying())
			{
				return member;
			}
		}
		return null;
	}

	boolean isHelm(Golem golem)
	{
		return golem != null && helm() == golem;
	}

	int size()
	{
		return members.size();
	}

	/** Puts everyone ashore: berths given up, and the crew is done with. */
	void payOff()
	{
		for (Golem golem : members)
		{
			golem.disembark();
		}
		members.clear();
		ashore.clear();
	}
}

package com.golemsdontdie;

import java.util.*;
import javax.inject.*;
import lombok.extern.slf4j.*;
import net.runelite.api.coords.*;

/**
 * Golems that leave a dock together sail together.
 *
 * <p>A golem about to cast off alone is held at the quayside for a few seconds first, in case
 * anyone else is coming. Two or more and they take a boat instead of a raft each: the route is
 * chosen after the crew is, so it is one they all suit rather than whichever port the first of them
 * happened to pick, and the crossing itself is shared, so they leave, cross and land as one.
 *
 * <p>Plugin side rather than in the planner, which is handed a golem's memory and never the golem:
 * a crew is the one thing about sailing that cannot be worked out one golem at a time.
 */
@Slf4j
@Singleton
class GolemCrews
{
	/** How long a golem waits at the quayside for company before sailing alone, in ticks. */
	private static final int MUSTER_TICKS = 30;

	/** How long a crew enough to sail waits after the last of them came, for anyone else, in ticks. */
	private static final int SETTLE_TICKS = 8;

	/** How near the dock a golem must still be to count as waiting at it. */
	private static final int QUAYSIDE = 4;

	@Inject
	private Voyage voyage;

	@Inject
	private RoamPlanner planner;

	/** Crews being made up, by the dock they are waiting at. */
	private final Map<Integer, Muster> mustering = new HashMap<>();

	/** The crew each golem at sea belongs to, for drawing and for putting them ashore. */
	private final Map<Golem, GolemCrew> crews = new IdentityHashMap<>();

	/** Golems already known to be at sea, so a crossing is noticed the tick it begins. */
	private final Map<Golem, Boolean> sailing = new IdentityHashMap<>();

	/** Golems that have just waited and been let go, so they are not held twice over. */
	private final Map<Golem, Integer> released = new IdentityHashMap<>();

	private final Random random = new Random();

	/** A crew being made up at one dock. */
	private static final class Muster
	{
		final SailingDocks.Dock dock;
		final List<Golem> waiting = new ArrayList<>();
		final int since;

		/**
		 * The port chosen for the crew, or null, kept while its crossing is worked out: chosen afresh
		 * every tick, a crew asked for a new sea field each time and sailed only if one happened to
		 * be built already. Chosen again whenever someone joins, for them too.
		 */
		SailingDocks.Dock port;

		/** The last tick the crew waits on that port's crossing, as a lone golem waits on its own. */
		int portUntil;

		/** When each golem in view next moves about the quay while it waits. */
		final Map<Golem, Integer> nextMove = new IdentityHashMap<>();

		/** Golems that have just come to wait, to be waved at. */
		final Map<Golem, Newcomer> newcomers = new IdentityHashMap<>();

		/** When the last of them came, so a crew enough to sail still waits a moment for more. */
		int lastJoined;

		Muster(SailingDocks.Dock dock, int since)
		{
			this.dock = dock;
			this.since = since;
		}

		/** Signs a golem onto the wait, as a newcomer to be waved at. */
		void join(Golem golem, int tick)
		{
			if (!waiting.contains(golem))
			{
				waiting.add(golem);
				newcomers.put(golem, new Newcomer(tick));
				port = null;
				lastJoined = tick;
			}
		}
	}

	/** A golem that has just come to wait at a quay: when it came, and who waved first. */
	private static final class Newcomer
	{
		final int came;
		Golem wavedBy;
		int wavedOn;

		Newcomer(int came)
		{
			this.came = came;
		}
	}

	/**
	 * Looks over every golem once a tick: who has just cast off, who is still waiting, and who has
	 * landed.
	 */
	void update(List<Golem> golems, int tick, RoamContext context)
	{
		for (Golem golem : golems)
		{
			// Aboard the player's ship, it is the player's crew and not one of these.
			if (golem.isAboard())
			{
				continue;
			}
			boolean atSea = golem.isSailing(tick);
			Boolean was = sailing.put(golem, atSea);
			if (atSea && !Boolean.TRUE.equals(was) && !golem.isCrewed())
			{
				hold(golem, tick);
			}
			// Ashore and still signed on: landed this tick, or carried off its boat by a rescue
			// and never noticed. Either way it is done sailing.
			if (!atSea && (Boolean.TRUE.equals(was) || crews.containsKey(golem)))
			{
				land(golem);
			}
			else if (atSea && golem.isCrewed())
			{
				steer(golem);
			}
		}
		sail(tick, context);
		if (sailing.size() > golems.size())
		{
			forget(golems);
		}
	}

	/**
	 * Drops everything remembered about golems that are no longer on the roster. Golems do not
	 * die, but reviving one builds it afresh, and the old object would be held here for ever.
	 */
	private void forget(List<Golem> golems)
	{
		Set<Golem> alive = Collections.newSetFromMap(new IdentityHashMap<>());
		alive.addAll(golems);
		sailing.keySet().retainAll(alive);
		released.keySet().retainAll(alive);
		crews.keySet().retainAll(alive);
	}

	/**
	 * Takes a golem that has just begun a crossing and stands it back on the quayside, waiting.
	 * Its own crossing is dropped: the crew's is planned when the crew is made up, and a golem
	 * that waits alone plans a fresh one when it is let go.
	 */
	private void hold(Golem golem, int tick)
	{
		Integer let = released.get(golem);
		if (let != null && tick >= let && tick - let < MUSTER_TICKS)
		{
			// Waited once already and found nobody; it goes now.
			return;
		}

		WorldPoint at = golem.currentTile();
		SailingDocks.Dock dock = voyage == null ? null : voyage.dockAt(at, QUAYSIDE);
		if (dock == null || dock.getShore() == null)
		{
			return;
		}

		Muster muster = mustering.computeIfAbsent(dock.getRowId(), id -> new Muster(dock, tick));
		// Already on the list and sailing again: its wait ran out, it planned afresh and cast off
		// while the crew was still making up. Held again rather than left under way on a list it
		// could be signed off, which would have carried it back to the dock it had left.
		muster.join(golem, tick);
		// Put back on the quayside rather than left where it stands. Crossings begin between game
		// ticks and this runs on one, so by now the golem is a tile or two out on the water, and
		// standing it there would leave it on the sea until the watchdog fetched it back.
		golem.waitAshore(tick, MUSTER_TICKS, placeFor(golem, muster));
		// The crossing it gave up booked shore leave for its whole length; without this the golem
		// could not sail again for as long as the voyage it is not taking would have lasted.
		golem.getTransportMemory().clearShoreLeave();
		sailing.put(golem, false);
	}

	/**
	 * A golem about to cast off alone, asked first: kept at the quayside to wait for company
	 * instead, unless it has only just waited here and nobody came. Asked before it sails rather
	 * than caught after, when a golem in view was already in its raft and was pulled out of it.
	 * {@link #hold} still catches a crossing begun some way this does not see.
	 *
	 * @return true if the golem is waiting now, its own crossing given up
	 */
	boolean offer(Golem golem, RoamContext context)
	{
		int tick = context.getTick();
		Integer let = released.get(golem);
		if (golem.isAboard() || let != null && tick >= let && tick - let < MUSTER_TICKS)
		{
			return false;
		}
		SailingDocks.Dock dock = voyage == null ? null : voyage.dockAt(golem.currentTile(), QUAYSIDE);
		if (dock == null || dock.getShore() == null)
		{
			return false;
		}
		Muster muster = mustering.computeIfAbsent(dock.getRowId(), id -> new Muster(dock, tick));
		muster.join(golem, tick);
		golem.waitAshore(tick, MUSTER_TICKS, placeFor(golem, muster), context);
		// Planning the crossing booked shore leave for its whole length.
		golem.getTransportMemory().clearShoreLeave();
		sailing.put(golem, false);
		return true;
	}

	/**
	 * Where on the quayside a golem waits: a tile of its own, near the dock's. The whole crew stood
	 * on the one quayside tile, one inside another.
	 */
	private WorldPoint placeFor(Golem golem, Muster muster)
	{
		Set<Long> taken = new HashSet<>();
		for (Golem other : muster.waiting)
		{
			if (other != golem)
			{
				WorldPoint there = other.currentTile();
				taken.add(RoamContext.tileKey(there.getX(), there.getY(), there.getPlane()));
			}
		}
		return planner.freeTileNear(muster.dock.getShore(), taken);
	}

	/** Makes up the crews that are ready, and lets go of the ones nobody joined. */
	private void sail(int tick, RoamContext context)
	{
		for (Iterator<Map.Entry<Integer, Muster>> it = mustering.entrySet().iterator(); it.hasNext(); )
		{
			Muster muster = it.next().getValue();
			// Anyone who wandered off, died or was carried away is no longer waiting, nor held to the
			// crew's wait: kept, one set down elsewhere stood idle wherever it was put.
			muster.waiting.removeIf(golem -> (golem.isDying() || golem.isAboard()
				|| golem.currentTile().distanceTo2D(muster.dock.getShore()) > QUAYSIDE) && endWait(golem));

			boolean over = isOver(tick, muster.since);
			// Everyone waiting waits as long as the crew does: to the end of the muster, and past it
			// while the crew's crossing is still being worked out.
			int until = Math.max(muster.since + MUSTER_TICKS, muster.port == null ? 0 : muster.portUntil) + 1;
			for (Golem golem : muster.waiting)
			{
				golem.holdWaitUntil(tick, until);
			}
			if (isReady(muster.waiting.size(), tick, muster.since, muster.lastJoined) && cast(muster, tick, context))
			{
				it.remove();
				continue;
			}
			// However many are waiting: a crew no crossing can be planned for waited the same as one
			// nobody joined, and then went its separate ways. Left to wait until one could be, it
			// never could, and they stood at the quay for good. But not while its crossing is still
			// being worked out, which it waits on as a lone golem waits on its own: let go then, a crew
			// whose first try came as the muster ran out cast off on a raft apiece.
			if (over && (muster.port == null || tick > muster.portUntil))
			{
				release(muster.waiting, tick, context, true);
				it.remove();
				continue;
			}
			mill(muster, tick, context);
		}
	}

	/** Ends a golem's wait at the quay. True, for use in a condition. */
	private static boolean endWait(Golem golem)
	{
		golem.endWait();
		return true;
	}

	/** Whether a muster's time is up, or the tick count has started again since it began. */
	static boolean isOver(int tick, int since)
	{
		return tick - since >= MUSTER_TICKS || tick < since;
	}

	/**
	 * Whether a muster may cast off now: enough of them to sail, and the boat full, or nobody new for
	 * a few seconds, or its time up. Cast the moment there were enough, every crew was the least
	 * there could be, and no sloop ever sailed.
	 */
	static boolean isReady(int waiting, int tick, int since, int lastJoined)
	{
		return waiting >= GolemCrew.LEAST && (waiting >= GolemBoat.SLOOP.getBerths()
			|| tick - lastJoined >= SETTLE_TICKS || tick < lastJoined || isOver(tick, since));
	}

	/** Ticks between one move about the quay and a waiting golem's next: three to seven seconds. */
	private static final int MOVE_MIN_TICKS = 5;
	private static final int MOVE_SPREAD_TICKS = 7;

	/** The chance a move is a look out at the water rather than a few steps. */
	private static final float LOOK_CHANCE = 0.4f;

	/** How long after a golem comes to wait the others wave at it, and it may wave back. */
	private static final int WELCOME_TICKS = 5;
	private static final int WAVE_BACK_TICKS = 12;

	/** The chance a golem waiting waves at a newcomer on a given tick, so they do not all at once. */
	private static final float WELCOME_CHANCE = 0.5f;

	/** How long a wave takes, and how long before a golem at a quay waves at another again. */
	private static final int WAVE_TICKS = 4;
	private static final int WAVE_COOLDOWN_TICKS = 100;

	/**
	 * Golems waiting at a quay in view of the player, kept from standing frozen for as long as the
	 * muster lasts, facing wherever their last step pointed: now and then each wanders a tile or two
	 * about its place, or turns to look out at the water, each on its own clock so they do not move
	 * as one. Whoever is waiting waves at a golem coming to join them, and it waves back once it is
	 * in its place. Nothing is given to a golem still walking: a wave would stop it where it was.
	 */
	private void mill(Muster muster, int tick, RoamContext context)
	{
		muster.newcomers.values().removeIf(newcomer -> tick - newcomer.came > WAVE_BACK_TICKS || tick < newcomer.came);
		for (Golem golem : muster.waiting)
		{
			if (!golem.isIdleOnQuay(tick) || welcome(muster, golem, tick))
			{
				continue;
			}
			Integer due = muster.nextMove.get(golem);
			if (due != null && tick < due && due - tick <= MOVE_MIN_TICKS + MOVE_SPREAD_TICKS)
			{
				continue;
			}
			muster.nextMove.put(golem, tick + MOVE_MIN_TICKS + random.nextInt(MOVE_SPREAD_TICKS));
			if (due == null)
			{
				// Only just settled: it stands a moment first.
				continue;
			}
			WorldPoint at = golem.currentTile();
			WorldPoint water = muster.dock.getBerth();
			if (random.nextFloat() < LOOK_CHANCE)
			{
				golem.faceToward(water.getX() - at.getX(), water.getY() - at.getY());
				continue;
			}
			WorldPoint spot = golem.waitingSpot();
			WorldPoint to = spot == null ? null : planner.quayTileNear(spot, taken(muster, golem), random);
			// Never so far it no longer counts as waiting here.
			if (to != null && to.distanceTo2D(muster.dock.getShore()) <= QUAYSIDE)
			{
				golem.millTo(to, context);
			}
		}
	}

	/**
	 * Waves at a newcomer, or back at whoever waved first. Golems standing still only, and not again
	 * for a while, so a busy quay is not all waving.
	 *
	 * @return true if the golem waved
	 */
	private boolean welcome(Muster muster, Golem golem, int tick)
	{
		if (!golem.mayWaveAtGolem(tick, WAVE_COOLDOWN_TICKS))
		{
			return false;
		}
		Golem other = null;
		Newcomer self = muster.newcomers.get(golem);
		// In its place now, and somebody waved on its way in: it waves back, the once. Not the tick
		// they waved, which looks like two golems who happened to wave at the same moment.
		if (self != null && self.wavedBy != null && tick > self.wavedOn)
		{
			other = self.wavedBy;
			muster.newcomers.remove(golem);
		}
		else
		{
			// A chance a tick rather than all at once, so the quay's welcome comes a tick or two apart.
			for (Map.Entry<Golem, Newcomer> entry : muster.newcomers.entrySet())
			{
				Newcomer newcomer = entry.getValue();
				if (entry.getKey() != golem && tick - newcomer.came <= WELCOME_TICKS
					&& entry.getKey().getRenderer() != null && random.nextFloat() < WELCOME_CHANCE)
				{
					other = entry.getKey();
					if (newcomer.wavedBy == null)
					{
						newcomer.wavedBy = golem;
						newcomer.wavedOn = tick;
					}
					break;
				}
			}
		}
		if (other == null || !muster.waiting.contains(other))
		{
			return false;
		}
		WorldPoint at = golem.currentTile();
		WorldPoint there = other.currentTile();
		golem.waveAtGolem(tick + WAVE_TICKS, there.getX() - at.getX(), there.getY() - at.getY(), tick);
		return true;
	}

	/** The tiles golems waiting here stand on, and the others are walking to, for one to keep off. */
	private static Set<Long> taken(Muster muster, Golem golem)
	{
		Set<Long> taken = new HashSet<>();
		for (Golem other : muster.waiting)
		{
			WorldPoint tile = other.currentTile();
			taken.add(RoamContext.tileKey(tile.getX(), tile.getY(), tile.getPlane()));
			if (other != golem)
			{
				tile = other.goalTile();
				taken.add(RoamContext.tileKey(tile.getX(), tile.getY(), tile.getPlane()));
			}
		}
		return taken;
	}

	/**
	 * Lets golems waiting at a quay go, and not to be held again straight away. One that waited and
	 * nobody came sails alone, as it meant to before it stopped to wait; let go to choose again, it
	 * mostly chose not to. A crew that could not be given a crossing goes its separate ways on foot:
	 * sent off alone, a crew that had gathered and waved left on a raft apiece. More waiting than a
	 * boat holds are let go to do as they like.
	 */
	private void release(List<Golem> golems, int tick, RoamContext context, boolean mayGoAlone)
	{
		boolean alone = mayGoAlone && context != null && golems.size() < GolemCrew.LEAST;
		for (Golem golem : golems)
		{
			released.put(golem, tick);
			golem.endWait();
			if (!alone)
			{
				continue;
			}
			TransportMemory memory = golem.getTransportMemory();
			Itinerary crossing = planner.planVoyageAlone(golem.currentTile(), tick, random, memory, context);
			if (crossing != null && crossing.isVoyage())
			{
				golem.boardCrossing(crossing);
			}
			else
			{
				// Its crossing still being worked out, it goes on foot, and nothing in its memory says
				// it is waiting to sail from here: left pending, it walked off still waiting for a boat.
				memory.clearPending();
			}
		}
	}

	/**
	 * Picks the crew's port, plans the one crossing, and signs everyone on; or, if there is no port
	 * all of them would go to, lets them go.
	 *
	 * @return false if the crossing could not be planned this tick, so the crew keeps waiting
	 */
	private boolean cast(Muster muster, int tick, RoamContext context)
	{
		List<Golem> crew = muster.waiting.size() <= GolemBoat.SLOOP.getBerths()
			? new ArrayList<>(muster.waiting)
			: new ArrayList<>(muster.waiting.subList(0, GolemBoat.SLOOP.getBerths()));

		List<TransportMemory> memories = new ArrayList<>(crew.size());
		for (Golem golem : crew)
		{
			memories.add(golem.getTransportMemory());
		}

		if (muster.port == null)
		{
			muster.port = voyage.crewPort(muster.dock, memories, random, context);
			muster.portUntil = tick + TransportMemory.PENDING_WAIT_TICKS;
			// Nowhere they all agree on this time: the choice is a few rolls, so they roll again next
			// tick while the muster lasts. Given up on the first, a crew with one picky golem in it
			// gathered, waved, and walked off.
			if (muster.port == null && !isOver(tick, muster.since))
			{
				return false;
			}
		}
		// Nowhere all of them would go by the time the muster is up; or a crossing waited on as long
		// as a lone golem waits on its own. They go their separate ways now rather than stand there.
		if (muster.port == null || tick > muster.portUntil)
		{
			release(muster.waiting, tick, context, true);
			return true;
		}
		WorldPoint at = crew.get(0).currentTile();
		Itinerary crossing = voyage.crossTo(muster.dock, muster.port, at, tick, random, context);
		if (crossing == null)
		{
			// Waiting on its sea field: the port is kept. No crossing to be had there at all: another.
			if (!voyage.wasNotReady())
			{
				muster.port = null;
			}
			return false;
		}

		GolemBoat boat = GolemBoat.forCrew(crew.size());
		GolemCrew made = new GolemCrew(boat, crossing);
		for (Golem golem : crew)
		{
			if (!made.sign(golem))
			{
				break;
			}
			golem.boardCrossing(crossing);
			golem.getTransportMemory().beginShoreLeaveOnArrival(tick + crossing.getDuration(), tick, random);
			crews.put(golem, made);
			sailing.put(golem, true);
		}
		// More waiting than the boat has berths: the rest are let go rather than left standing at
		// a quayside whose crew has sailed.
		List<Golem> left = new ArrayList<>(muster.waiting);
		left.removeIf(golem -> crews.get(golem) == made);
		release(left, tick, context, false);
		log.debug("{} golems crewed a {} from {}", made.size(), boat, muster.dock.getName());
		return true;
	}

	/**
	 * Keeps a crew facing as one.
	 *
	 * <p>A berth is measured from the boat and turned to wherever the boat is pointing, and the
	 * only heading a golem has is its own. Left to themselves they each turn from whatever way
	 * they happened to face at the dock, at their own rate, so for the first seconds of a crossing
	 * the crew would be strewn around the boat rather than standing on it. The helm's heading is
	 * every member's; which way each one looks from there is {@link Golem#drawOrientation}.
	 */
	private void steer(Golem golem)
	{
		GolemCrew crew = crews.get(golem);
		Golem helm = crew == null ? null : crew.helm();
		if (helm != null && helm != golem)
		{
			golem.faceAs(helm.getOrientation());
		}
	}

	/** Puts a golem ashore, and its crew with it once the last of them has landed. */
	private void land(Golem golem)
	{
		GolemCrew crew = crews.remove(golem);
		if (crew == null)
		{
			return;
		}
		golem.disembark();
		// The crossing ends every one of them on the same tile; each steps off onto one of its own.
		WorldPoint at = golem.currentTile();
		WorldPoint own = planner.freeTileNear(at, crew.getAshore());
		if (!own.equals(at))
		{
			golem.relocate(own);
		}
		crew.getAshore().add(RoamContext.tileKey(own.getX(), own.getY(), own.getPlane()));
		if (crews.values().stream().noneMatch(other -> other == crew))
		{
			crew.payOff();
		}
	}

	/** The crew this golem is sailing with, or null. */
	GolemCrew crewOf(Golem golem)
	{
		return crews.get(golem);
	}

	/**
	 * Lets every crew still making up go, on a log out or a world hop: the golems waiting are put
	 * back to planning for themselves rather than kept standing on a wait that was timed by the
	 * session just left.
	 */
	void releaseMusters()
	{
		for (Muster muster : mustering.values())
		{
			for (Golem golem : muster.waiting)
			{
				golem.stopWaiting();
			}
		}
		mustering.clear();
		released.clear();
	}

	/** Forgets everything: the golems are being rebuilt. */
	void clear()
	{
		mustering.clear();
		crews.clear();
		sailing.clear();
		released.clear();
	}
}

package com.golemsdontdie;

import java.util.*;
import lombok.*;

/**
 * The emotes a golem dances, one picked per move.
 *
 * <p>All of them are the game's own human emotes, and the golem is rigged to the human framemap
 * (see {@link GolemContent#GOLEM_FRAMEMAP}), so they play against it untouched. Checked one by one
 * against the cache: an emote on another framemap would fold the golem through
 * itself rather than look slightly wrong.
 *
 * <p>Two of them carry something the golem has not got. The air guitar's guitar is a spot
 * animation the client plays on the actor, and golems are not actors, so it is drawn beside the
 * golem as scenery; see {@link #getSpotanim()} and GolemsDontDiePlugin.spawnDanceProp.
 *
 * <p>From the dancing contributed in
 * <a href="https://github.com/Varzeki/golems-dont-die/pull/1">pull request 1</a>, which took the
 * idea from dekvall's Dance Party.
 */
@Getter
@AllArgsConstructor
enum GolemDance
{
	/** EMOTE_CHEER. */
	CHEER(862, -1),
	/** EMOTE_DANCE. */
	DANCE(866, -1),
	/** EMOTE_DANCE_SCOTTISH, the jig. */
	JIG(2106, -1),
	/** EMOTE_DANCE_SPIN. */
	SPIN(2107, -1),
	/** EMOTE_DANCE_HEADBANG. */
	HEADBANG(2108, -1),
	/** ZOMBIE_DANCE. */
	ZOMBIE_DANCE(3543, -1),
	/** BDAY17_BLING, the smooth dance. */
	SMOOTH_DANCE(7533, -1),
	/** BDAY17_LASSO, the crazy dance. */
	CRAZY_DANCE(7537, -1),
	/** EMOTE_JUMP_WITH_JOY. */
	JUMP_FOR_JOY(2109, -1),
	/** HUMAN_CHICKEN_DANCE. */
	CHICKEN_DANCE(1835, -1),
	/** EMOTE_AIR_GUITAR, with the guitar it is played on. */
	AIR_GUITAR(4751, GolemContent.SPOTANIM_AIR_GUITAR),
	/** HUMAN_CAVE_GOBLIN_DANCE. */
	GOBLIN_DANCE(2128, -1),
	;

	private final int animationId;

	/** The spot animation that goes with the emote, or -1 where the golem needs no props. */
	private final int spotanim;

	private static final GolemDance[] ALL = values();

	/**
	 * A move at random.
	 *
	 * @param random the golem's own dancing generator, not the one its roaming comes out of: a
	 *               crowd dancing in lockstep looks wrong, and a golem whose walk changed because
	 *               it danced would be worse. See Golem.danceRandom.
	 */
	static GolemDance random(Random random)
	{
		return ALL[random.nextInt(ALL.length)];
	}
}

package com.golemsdontdie;

import java.util.*;
import javax.inject.*;
import net.runelite.api.*;

/**
 * Decides what counts as a golem, and when one is dying.
 *
 * <p>Both are hardcoded in {@link GolemContent}, not discovered at runtime: a name match
 * would sweep up the sixty-odd unrelated golems in the game, and learning the death
 * animation from the first death costs a visible crumble whenever the roster is empty.
 * Both stay overridable, as a content update can move them.
 */
@Singleton
class GolemDetector
{
	/** Live golems watched, by NPC index, with their latest snapshot. */
	private final Map<Integer, GolemSnapshot> tracked = new HashMap<>();

	/** Golems already replaced by a copy, so a despawn does not replace them twice. */
	private final Set<Integer> replaced = new HashSet<>();

	/**
	 * Golems seen playing the plinth animation. The copy takes over as it ends, the one
	 * moment a golem is reliably standing still.
	 */
	private final Set<Integer> leftPlinth = new HashSet<>();

	/** Golems replaced and then seen crumbling: the real thing is on its way out, and done with. */
	private final Set<Integer> crumbling = new HashSet<>();

	/**
	 * Replaced golems that went out of view still standing, by NPC index, with the tick until which
	 * one coming back is the same golem. Forgotten on the way out, one that walked back into view
	 * before crumbling was taken over a second time: two golems where there had been one.
	 */
	private final Map<Integer, Integer> away = new HashMap<>();

	/** Longer than a crafted golem lives: past this, an index seen again is a different golem. */
	private static final int AWAY_TICKS = 100;

	// ---- identity ----

	boolean isGolem(NPC npc)
	{
		return npc != null && GolemContent.isGolem(npc.getId());
	}

	/** True if this animation is the crumble. */
	boolean isDeathAnimation(int animationId)
	{
		return animationId != -1 && animationId == GolemContent.GOLEM_DEATH_ANIMATION;
	}

	// ---- tracking ----

	void track(NPC npc)
	{
		GolemSnapshot snapshot = GolemSnapshot.of(npc);
		if (snapshot != null)
		{
			tracked.put(npc.getIndex(), snapshot);
		}
	}

	/** Last snapshot of a golem, or null if never tracked. */
	GolemSnapshot snapshotOf(NPC npc)
	{
		return tracked.get(npc.getIndex());
	}

	void noteLeftPlinth(NPC npc)
	{
		leftPlinth.add(npc.getIndex());
	}

	boolean hasLeftPlinth(NPC npc)
	{
		return leftPlinth.contains(npc.getIndex());
	}

	/** Marks a golem as already replaced, so its despawn is ignored. */
	void markReplaced(NPC npc)
	{
		replaced.add(npc.getIndex());
	}

	boolean wasReplaced(NPC npc)
	{
		return replaced.contains(npc.getIndex());
	}

	/** Drops all state for an NPC that has left the scene. */
	void forget(NPC npc, int tick)
	{
		int index = npc.getIndex();
		if (replaced.contains(index) && !crumbling.contains(index))
		{
			away.put(index, tick + AWAY_TICKS);
		}
		tracked.remove(index);
		replaced.remove(index);
		leftPlinth.remove(index);
		crumbling.remove(index);
	}

	/** Notes a replaced golem playing its crumble, so its despawn is taken as its end. */
	void noteCrumbling(NPC npc)
	{
		crumbling.add(npc.getIndex());
	}

	/**
	 * True if a golem just in view is one already replaced, back from out of view, and marks it
	 * replaced again. A golem newly crafted onto the same index is told apart by stepping off the
	 * plinth; see {@link #crafted}.
	 */
	boolean returned(NPC npc, int tick)
	{
		Integer until = away.remove(npc.getIndex());
		if (until == null || tick > until || tick < until - AWAY_TICKS)
		{
			return false;
		}
		replaced.add(npc.getIndex());
		return true;
	}

	/** A golem stepping off the plinth is new, whatever held its index before. */
	void crafted(NPC npc)
	{
		replaced.remove(npc.getIndex());
		away.remove(npc.getIndex());
	}

	/** Drops everything; on logout and plugin stop. */
	void reset()
	{
		tracked.clear();
		replaced.clear();
		leftPlinth.clear();
		crumbling.clear();
		away.clear();
	}
}

package com.golemsdontdie;

import java.awt.*;
import java.awt.image.*;
import net.runelite.api.*;
import net.runelite.client.plugins.*;
import net.runelite.client.ui.overlay.*;
import net.runelite.client.ui.overlay.infobox.*;

/**
 * The golem being looked for, as an infobox: how far off it is, and who and where on hover.
 *
 * <p>The arrow and the map face both need the player to be looking somewhere in particular. This
 * sits with the rest of the infoboxes, so the answer to "how far now?" is always in the corner of
 * the eye, and a right-click on it is the way to stop looking without opening the sidebar.
 *
 * <p>Client thread: it is told what to say by the plugin once a tick, and only reads it back.
 */
class GolemFindBox extends InfoBox
{
	/** The right-click entry that stops the looking. */
	static final String STOP = "Stop";

	/** Whose infobox a click on {@link #STOP} is about: this one's target line. */
	static final String TARGET = "finding golem";

	/** The distance, or blank while it cannot be said. */
	private String text = "";

	GolemFindBox(BufferedImage icon, Plugin plugin)
	{
		super(icon, plugin);
		getMenuEntries().add(new OverlayMenuEntry(MenuAction.RUNELITE_INFOBOX, STOP, TARGET));
	}

	/**
	 * Says where the golem is.
	 *
	 * @param name  what the golem is called
	 * @param where where it is, in words
	 * @param tiles how far off it is, or -1 where that cannot be said, such as a golem on another
	 *              floor or the player not yet placed
	 */
	void show(String name, String where, int tiles)
	{
		text = tiles < 0 ? "" : tiles < 1000 ? Integer.toString(tiles) : tiles / 1000 + "k";
		String away = tiles < 0 ? "" : "</br>" + String.format("%,d", tiles) + " tiles away";
		setTooltip("Finding " + name + "</br>" + where + away);
	}

	@Override
	public String getText()
	{
		return text;
	}

	@Override
	public Color getTextColor()
	{
		return Color.WHITE;
	}
}

package com.golemsdontdie;

import java.io.*;
import java.util.*;
import lombok.*;
import net.runelite.api.coords.*;
import static com.golemsdontdie.RouteGeometry.span;

/**
 * What one golem has done, in six numbers and a short journal: enough for its own page, and little
 * enough to save beside a roster of ten thousand.
 *
 * <p>Distance is sampled rather than counted. Nothing watches a far golem walk - it is moved along
 * a route by the tick - so this takes the ground between one census and the next, a few seconds
 * apart, and throws away any step too long to have been walked: that was a shortcut or a crossing,
 * and they are counted on their own.
 */
class GolemHistory
{
	/** Tiles between two samples beyond which the golem cannot have walked there. */
	private static final int WALKED_AT_MOST = 24;

	/** When the golem was first known, in epoch milliseconds; 0 if it was made before this was kept. */
	@Getter
	private long firstSeen;

	/** Shortcuts used: see GolemTransport#isShortcut. */
	@Getter
	private int transports;

	/** Counted without an obstacle to name: a restored golem, or a hop with no row behind it. */
	void tookTransport()
	{
		tookTransport(null);
	}

	@Getter
	private int voyages;

	/** Tiles walked, to the nearest sample. */
	@Getter
	private int walked;

	/** The furthest tile from home the golem has stood on, and how far that is. */
	@Getter
	private int furthestX;
	@Getter
	private int furthestY;
	@Getter
	private int furthest;

	/** Where the golem was at the last sample; 0 before the first. */
	private int lastX;
	private int lastY;

	GolemHistory()
	{
		firstSeen = System.currentTimeMillis();
	}

	/** Puts back what was saved. The furthest distance is worked out again from home. */
	void restore(long firstSeen, int transports, int voyages, int walked, int furthestX, int furthestY,
		WorldPoint home)
	{
		this.firstSeen = firstSeen;
		this.transports = transports;
		this.voyages = voyages;
		this.walked = walked;
		this.furthestX = furthestX;
		this.furthestY = furthestY;
		this.furthest = furthestX == 0 && furthestY == 0 ? 0 : away(furthestX, furthestY, home);
	}

	void sailed()
	{
		voyages++;
	}

	/**
	 * The last twenty places the golem arrived in, and how it got to each.
	 *
	 * <p>One int apiece - region, plane and manner packed together - and the array is not made
	 * until a golem goes somewhere, because ten thousand golems pay for anything kept per golem.
	 * The names are looked up when the page is opened rather than stored: they are the same
	 * strings for every golem that has been to the same place.
	 */
	private static final int KEPT = 20;

	private int[] journal;

	/** When each entry was written, in minutes since the epoch: what "an hour ago" is worked out from. */
	private int[] when;

	/** The name of the place the last entry was written for, so walking about inside it writes nothing. */
	private String lastPlace;

	/** The place the golem left for the last entry: going back there the same way is no journey. */
	private String cameFrom;

	/** How the golem reached the last entry's place. */
	private GolemTravel lastWay;

	/** The named place the golem is in now, written or not: where the next entry leaves from. */
	private transient String here;

	/** Where the last entry went, so the ring can be read back in order. */
	private int written;

	/** The region the last entry was for, so standing still writes nothing. */
	private int lastRegion = -1;

	/** How the golem got where it is going, set as it arrives and spent on the next entry. */
	private transient GolemTravel manner = GolemTravel.WALKED;

	/**
	 * The region that manner took it to. Only an entry for that region is written that way: a
	 * gangplank crossed inside one region was kept until the golem next walked somewhere new, and
	 * the journal said it took a gangplank to Shilo Village.
	 */
	private transient int mannerRegion = -1;

	/** Notes an obstacle as the golem steps off it. */
	void tookTransport(GolemTransport transport)
	{
		if (transport == null || transport.isShortcut())
		{
			transports++;
		}
		if (transport != null)
		{
			manner = GolemTravel.of(transport);
			mannerRegion = regionOf(transport.getToX(), transport.getToY());
		}
	}

	/** Notes a crossing as the golem steps ashore, where it stepped ashore. */
	void cameAshore(WorldPoint ashore)
	{
		manner = GolemTravel.SAILED;
		mannerRegion = ashore == null ? -1 : regionOf(ashore.getX(), ashore.getY());
	}

	private static int regionOf(int x, int y)
	{
		return (x >> 6) << 8 | (y >> 6);
	}

	/**
	 * Writes the golem's arrival somewhere new, if it is somewhere new.
	 *
	 * <p>Called from the census pass with everything else that is counted per golem, so an entry
	 * costs a comparison for the golems that have not moved region, which is nearly all of them
	 * nearly always.
	 */
	private void note(int x, int y, int plane, PlaceNames names)
	{
		int region = (x >> 6) << 8 | (y >> 6);
		if (region == lastRegion)
		{
			return;
		}
		boolean first = lastRegion == -1;
		lastRegion = region;
		if (first)
		{
			// Where it was standing when the plugin first looked is not a journey, but it is where
			// the first one leaves from.
			here = names == null ? null : names.nameFor((region >> 8) * 64 + 32, (region & 0xff) * 64 + 32, plane);
			return;
		}

		// Walked off the surface - into a cave, or somewhere laid out apart from the map, such as
		// God Wars or Zanaris: that is exploring, and reads better than walking.
		GolemTravel arrived = mannerRegion == -1 || mannerRegion == region ? manner : GolemTravel.WALKED;
		GolemTravel how = arrived == GolemTravel.WALKED && !WorldLayout.isSurface(y)
			? GolemTravel.EXPLORED : arrived;
		manner = GolemTravel.WALKED;
		mannerRegion = -1;

		// By name, as the page shows it: a place is several regions, and walking from one into the
		// next wrote "Walked to Wyrmscraig" over and over. A walk to where the last entry already
		// is, or to somewhere with no name to write, is not a journey; a climb or a crossing is.
		if (names != null)
		{
			if (lastPlace == null && written > 0)
			{
				// A journal read back from the save knows its last two places by region only, and
				// takes the older for where the newer was left from.
				int newest = journal[Math.floorMod(written - 1, KEPT)];
				lastPlace = placeOf(newest, names);
				lastWay = GolemTravel.byOrdinal(newest & 0xf);
				cameFrom = written > 1 ? placeOf(journal[Math.floorMod(written - 2, KEPT)], names) : null;
			}
			String place = names.nameFor((region >> 8) * 64 + 32, (region & 0xff) * 64 + 32, plane);
			if (place == null)
			{
				return;
			}
			String from = here;
			here = place;
			boolean walked = how == GolemTravel.WALKED || how == GolemTravel.EXPLORED;
			if (walked && (place.equals(lastPlace) || place.equals(from)))
			{
				return;
			}
			// Back the way it came, and out again, is no journey either: a golem pacing between
			// Wyrmscraig and Ardeglais wrote the pair over and over until the journal was nothing
			// else. The last entry stands until the golem goes somewhere else, or another way.
			if (sameWay(how, lastWay) && (place.equals(cameFrom) || place.equals(lastPlace)))
			{
				return;
			}
			cameFrom = from;
			lastPlace = place;
			lastWay = how;
		}

		if (journal == null)
		{
			journal = new int[KEPT];
			when = new int[KEPT];
			Arrays.fill(journal, -1);
		}
		journal[written % KEPT] = region << 6 | (plane & 3) << 4 | how.ordinal();
		when[written % KEPT] = (int) (System.currentTimeMillis() / 60_000L);
		written++;
	}

	/** The name of the place a packed journal entry is for. */
	private static String placeOf(int packed, PlaceNames names)
	{
		int region = packed >>> 6;
		return names.nameFor((region >> 8) * 64 + 32, (region & 0xff) * 64 + 32, packed >> 4 & 3);
	}

	/**
	 * Whether two journeys went the same way, one of them perhaps backwards: a walk and a walk, a
	 * climb and a climb down, a squeeze and a squeeze. Never a voyage: each one is worth a line.
	 */
	private static boolean sameWay(GolemTravel a, GolemTravel b)
	{
		if (a == null || b == null || a == GolemTravel.SAILED || b == GolemTravel.SAILED)
		{
			return false;
		}
		return kind(a) == kind(b);
	}

	private static GolemTravel kind(GolemTravel way)
	{
		switch (way)
		{
			case EXPLORED:
				return GolemTravel.WALKED;
			case DESCENDED:
				return GolemTravel.CLIMBED;
			default:
				return way;
		}
	}

	/**
	 * The journal, newest first: region, plane, manner and the minute it was written, four to an
	 * entry. Empty for a golem that has not been anywhere yet.
	 */
	int[][] travels()
	{
		if (journal == null)
		{
			return new int[0][];
		}
		java.util.List<int[]> out = new ArrayList<>(KEPT);
		for (int i = 1; i <= KEPT; i++)
		{
			int packed = journal[Math.floorMod(written - i, KEPT)];
			if (packed >= 0)
			{
				out.add(new int[]{packed >>> 6, packed >>> 4 & 3, packed & 15,
					when[Math.floorMod(written - i, KEPT)]});
			}
		}
		return out.toArray(new int[0][]);
	}

	/**
	 * The journal for the save file, oldest first: each entry's packed region, plane and manner in
	 * three bytes, then its minute - the first in full, the rest as minutes since the one before,
	 * which are small - in base 64. About six characters an entry rather than the twenty the
	 * numbers written out would take, over a roster of thousands. Empty for no journal.
	 */
	String journalCode()
	{
		if (journal == null)
		{
			return "";
		}
		ByteArrayOutputStream out = new ByteArrayOutputStream();
		int before = 0;
		for (int i = Math.min(written, KEPT); i >= 1; i--)
		{
			int at = Math.floorMod(written - i, KEPT);
			int packed = journal[at];
			if (packed < 0)
			{
				continue;
			}
			out.write(packed >>> 16);
			out.write(packed >>> 8);
			out.write(packed);
			writeVarint(out, out.size() == 3 ? when[at] : Math.max(0, when[at] - before));
			before = when[at];
		}
		return Base64.getUrlEncoder().withoutPadding().encodeToString(out.toByteArray());
	}

	/** Puts back a journal written by {@link #journalCode()}; anything unreadable is dropped. */
	void restoreJournal(String code)
	{
		if (code == null || code.isEmpty())
		{
			return;
		}
		try
		{
			ByteArrayInputStream in = new ByteArrayInputStream(Base64.getUrlDecoder().decode(code));
			int minute = 0;
			boolean first = true;
			while (in.available() >= 4)
			{
				int packed = in.read() << 16 | in.read() << 8 | in.read();
				int time = readVarint(in);
				minute = first ? time : minute + time;
				first = false;
				if (journal == null)
				{
					journal = new int[KEPT];
					when = new int[KEPT];
					Arrays.fill(journal, -1);
				}
				journal[written % KEPT] = packed;
				when[written % KEPT] = minute;
				written++;
			}
		}
		catch (IllegalArgumentException e)
		{
			journal = null;
			when = null;
			written = 0;
		}
	}

	private static void writeVarint(ByteArrayOutputStream out, int value)
	{
		while ((value & ~0x7F) != 0)
		{
			out.write(value & 0x7F | 0x80);
			value >>>= 7;
		}
		out.write(value);
	}

	private static int readVarint(ByteArrayInputStream in)
	{
		int value = 0;
		for (int shift = 0; shift < 35; shift += 7)
		{
			int b = in.read();
			if (b < 0)
			{
				throw new IllegalArgumentException("journal ends mid-entry");
			}
			value |= (b & 0x7F) << shift;
			if ((b & 0x80) == 0)
			{
				return value;
			}
		}
		throw new IllegalArgumentException("journal time too long");
	}

	/**
	 * Takes a crossing back off the tally: a golem held at the quayside to wait for a crew had
	 * already been counted out, and will be counted again when it really goes.
	 */
	void unsailed()
	{
		voyages = Math.max(0, voyages - 1);
	}

	/**
	 * Notes ground covered by a golem out of view partway along a route, whose position is only an
	 * estimate: the distance counts, but nowhere is arrived at and nothing is the furthest from home.
	 * See Golem.isEstimated.
	 */
	void passing(int x, int y)
	{
		if (lastX != 0)
		{
			int step = span(x - lastX, y - lastY);
			if (step <= WALKED_AT_MOST)
			{
				walked += step;
			}
		}
		lastX = x;
		lastY = y;
	}

	/**
	 * Notes where the golem is now. Called for every golem on the census pass, so it is a handful
	 * of comparisons and nothing else.
	 */
	void sample(int x, int y, int plane, WorldPoint home)
	{
		sample(x, y, plane, home, null);
	}

	/** @param names what places are called, to keep walks about one place out of the journal */
	void sample(int x, int y, int plane, WorldPoint home, PlaceNames names)
	{
		note(x, y, plane, names);
		if (lastX != 0)
		{
			int step = span(x - lastX, y - lastY);
			if (step <= WALKED_AT_MOST)
			{
				walked += step;
			}
		}
		lastX = x;
		lastY = y;

		// -1 for somewhere with no ground above it to measure from: not far, just unmeasurable.
		int away = away(x, y, home);
		if (away > furthest)
		{
			furthest = away;
			furthestX = x;
			furthestY = y;
		}
	}

	/**
	 * How far a tile is from home, or -1 where that cannot be said.
	 *
	 * <p>A cave counts as the ground above it: it is laid out a hundred regions north of what it runs
	 * under, and a golem in the cave under the island is not six thousand tiles from home, it is
	 * under it. Somewhere laid out apart from the map - God Wars, TzHaar - is under nowhere that can
	 * be named, and a number measured to it would be a number about the layout, not the golem.
	 */
	private static int away(int x, int y, WorldPoint home)
	{
		if (home == null)
		{
			return 0;
		}
		int above = WorldLayout.groundAbove(y);
		if (above < 0)
		{
			return -1;
		}
		return span(x - home.getX(), above - WorldLayout.groundAbove(home.getY()));
	}
}

package com.golemsdontdie;

import java.awt.*;
import java.awt.event.MouseAdapter;
