			this.component = component;
			this.name = name;
		}
	}

	GolemListPanel(GolemNames names, Consumer<Golem> onRemove,
		BiConsumer<Golem, String> onRename, Runnable onRevive,
		Consumer<Golem> onFind, Consumer<Golem> onStar, Consumer<Golem> onOpen)
