	/**
	 * As {@link #refresh(List, int, boolean)}, leaving the names on rows already shown alone.
	 *
	 * @param missing how many fewer golems are roaming than crafted; the revive button shows
	 *                only when this is positive
	 */
	void refresh(List<Golem> golems, int missing)
	{
		refresh(golems, missing, false);
	}

	/**
	 * Builds every row again, for when the name pack changes: the name a row shows for a golem
	 * nobody has named is a prompt set when the row was made.
	 */
	void namesChanged()
	{
		SwingUtilities.invokeLater(() ->
		{
			shown.clear();
			rows.removeAll();
			relist();
		});
	}

	/**
	 * Puts the list back in order, unless the player is typing in it or has the mouse over it.
	 *
	 * <p>Reordering moves rows, and a text field taken out of the list and put back loses the keyboard:
	 * a name half typed carried on into the game. So while a name or the search box has the caret the
	 * order waits, and the next reorder after the player stops typing puts it right.
	 */
	void reorder(List<Golem> golems, int missing)
	{
		SwingUtilities.invokeLater(() ->
		{
			if (typing())
			{
				return;
			}
			// Nor under the mouse: a row moved out from under the pointer gives the click meant for it
			// to another golem. Golems still come and go; the order waits for the mouse to leave.
			roster = pointedAt() ? inPlace(golems) : golems;
			updateRevive(missing);
			updateSummary(golems.size());
			relist();
		});
	}

	/** Whether the keyboard is in one of this panel's text fields: a name, or the search. */
	private boolean typing()
	{
		if (search.isFocusOwner())
		{
			return true;
		}
		for (Row row : shown.values())
		{
			if (row.name.isFocusOwner())
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Whether the mouse is anywhere over this panel. Asked of where the pointer is on the screen
	 * rather than kept from enter and exit events, which each row, button and field has its own of,
	 * so that moving from one to the next inside the panel is not taken for leaving it.
	 */
	private boolean pointedAt()
	{
		if (!isShowing())
		{
			return false;
		}
		PointerInfo pointer = MouseInfo.getPointerInfo();
		if (pointer == null)
		{
			return false;
		}
		Point at = pointer.getLocation();
		SwingUtilities.convertPointFromScreen(at, this);
		return contains(at);
	}

	/**
	 * Takes the roster as it now stands, in the order the client thread put it: nearest first.
	 *
	 * <p>Only a page of it is ever built. One row is half a dozen Swing components, and a player who
	 * has crafted for months has thousands of golems - sixty thousand components in one scroll pane
	 * is minutes of laying out and megabytes held for a list nobody can read anyway.
	 *
	 * @param missing how many fewer golems are roaming than crafted; the revive button shows
	 *                only when this is positive
	 * @param names   also take names given in game, which leave the roster otherwise unchanged
	 */
	void refresh(List<Golem> golems, int missing, boolean names)
	{
		SwingUtilities.invokeLater(() ->
		{
			// While a name is being typed the order stands, as it does for reorder: a row moved is a
			// field that loses the keyboard. So too while the mouse is over the list. Golems still
			// come and go.
			roster = typing() || pointedAt() ? inPlace(golems) : golems;
			updateRevive(missing);
			updateSummary(golems.size());
			relist();
			if (names)
			{
				for (Map.Entry<Golem, Row> entry : shown.entrySet())
				{
					showName(entry.getValue(), entry.getKey());
				}
			}
		});
	}

	/** The golems given, in the order the list has them now, and any new ones after. */
	private List<Golem> inPlace(List<Golem> golems)
	{
		Set<Golem> fresh = Collections.newSetFromMap(new IdentityHashMap<>());
		fresh.addAll(golems);
		List<Golem> kept = new ArrayList<>(golems.size());
		for (Golem golem : roster)
		{
			if (fresh.remove(golem))
			{
				kept.add(golem);
			}
		}
		for (Golem golem : golems)
		{
			if (fresh.contains(golem))
			{
				kept.add(golem);
			}
		}
		return kept;
	}

	/** Works out who is on the page now, and builds the rows for them. */
	private void relist()
	{
		String wanted = search.getText() == null ? "" : search.getText().trim().toLowerCase();
		List<Golem> found = new ArrayList<>();
		for (Golem golem : roster)
		{
			// Searched by whatever the row says, which for a golem nobody has named is the name
			// the plugin gives it: a player looking for Pebblesworth means the one called that.
			String name = golem.getNickname() == null ? names.suggested(golem) : golem.getNickname();
			if (wanted.isEmpty() || name != null && name.toLowerCase().contains(wanted))
			{
				found.add(golem);
			}
		}
		matching = found;

		int pages = Math.max(1, (matching.size() + PER_PAGE - 1) / PER_PAGE);
		page = Math.max(0, Math.min(page, pages - 1));
		int from = page * PER_PAGE;
		int to = Math.min(matching.size(), from + PER_PAGE);
		List<Golem> wantedRows = matching.subList(from, to);
		onScreen = new ArrayList<>(wantedRows);

		// Rows belong to golems, not to places in the list: a row kept is a name still being typed.
		Set<Golem> keep = Collections.newSetFromMap(new IdentityHashMap<>());
		keep.addAll(wantedRows);
		Iterator<Map.Entry<Golem, Row>> it = shown.entrySet().iterator();
		while (it.hasNext())
		{
			Map.Entry<Golem, Row> entry = it.next();
			if (!keep.contains(entry.getKey()))
			{
				rows.remove(entry.getValue().component);
				it.remove();
			}
		}

		boolean built = false;
		for (int i = 0; i < wantedRows.size(); i++)
		{
			Golem golem = wantedRows.get(i);
			Row row = shown.get(golem);
			if (row == null)
			{
				row = row(golem);
				shown.put(golem, row);
				built = true;
				rows.add(row.component, Math.min(i, rows.getComponentCount()));
			}
			else if (i >= rows.getComponentCount() || rows.getComponent(i) != row.component)
			{
				rows.remove(row.component);
				rows.add(row.component, Math.min(i, rows.getComponentCount()));
			}
		}

		if (built)
		{
			onPlacesWanted.run();
		}

		paging.setVisible(pages > 1);
		previous.setEnabled(page > 0);
		next.setEnabled(page < pages - 1);
		pageLabel.setText("Page " + (page + 1) + " of " + pages + "  (" + matching.size() + ")");
		// Only for a search: an empty roster is already said, as "No golems yet", above.
		nothingFound.setVisible(matching.isEmpty() && !wanted.isEmpty());
		rows.revalidate();
		rows.repaint();
	}

	private void turnTo(int wanted)
	{
		page = wanted;
		relist();
	}

	/** The golems listed on the page now. Read from the client thread, which updates their places. */
	List<Golem> onScreenGolems()
	{
		return onScreen;
	}

	/**
	 * Says where each golem on the page is and how far off, under its name.
	 *
	 * <p>Given as lists in step with the golems rather than read from them here: they belong to the
	 * client thread, and this is Swing's.
	 *
	 * @param places   where each golem is, in words
	 * @param distance how many tiles away each one is, or -1 where that cannot be said
	 */
	void showPlaces(List<Golem> golems, List<String> places, List<Integer> distance)
	{
		SwingUtilities.invokeLater(() ->
		{
			for (int i = 0; i < golems.size() && i < places.size(); i++)
			{
				Row row = shown.get(golems.get(i));
				if (row == null || row.place == null)
				{
					continue;
				}
				// How far off first, then where: a row is two hundred pixels wide and "Sailing to
				// Port Khazard" fills most of it, so whichever goes second is the one that clips.
				int away = i < distance.size() ? distance.get(i) : -1;
				String said = away < 0 ? places.get(i)
					: TILES.format(away) + " tiles away · " + places.get(i);
				lastSaid.put(golems.get(i), said);
				if (!row.place.getText().equals(said))
				{
					row.place.setText(said);
					// The row is 200 pixels wide and a place can be "Sailing to Port Khazard", so
					// what will not fit is still readable by hovering it.
					row.place.setToolTipText(said);
				}
			}
		});
	}

	private static final NumberFormat TILES = NumberFormat.getIntegerInstance();

	/**
	 * What each golem's place line last said, so a row built again, on turning the page or
	 * searching, says it at once rather than standing blank until the next update.
	 */
	private final Map<Golem, String> lastSaid = new WeakHashMap<>();

	/** Asked for when new rows appear, so their places are worked out on the next tick. */
	@lombok.Setter
	private Runnable onPlacesWanted = () -> { };

	/** Shows or hides the bar offering to stop pointing at a golem. */
	void setFinding(String name)
	{
		SwingUtilities.invokeLater(() ->
		{
			boolean show = name != null;
			if (show)
			{
				finding.setText("Stop finding " + name);
			}
			if (finding.isVisible() != show)
			{
				finding.setVisible(show);
				revalidate();
				repaint();
			}
		});
	}

	/** True while the panel is on screen: nothing else is worth updating. */
	boolean isOnScreen()
	{
		return isShowing();
	}

	/** How fast a hovered name too long for its field scrolls, in pixels a second. */
	private static final int MARQUEE_SPEED = 30;

	/** How long it rests at each end, in milliseconds, so the ends can be read. */
	private static final int MARQUEE_REST = 1200;

	/**
	 * Scrolls the hovered name back and forth when it is too long for its field, so the whole of it
	 * can be read without widening the field into the buttons' room. One timer for the panel, and
	 * running only while a name is hovered.
	 */
	private final Timer marquee = new Timer(40, e -> scrollHovered());

	/** The name field under the mouse, and when the mouse came onto it. */
	private PlaceholderField hovered;
	private long hoveredSince;

	private void hover(PlaceholderField field)
	{
		hovered = field;
		hoveredSince = System.currentTimeMillis();
		marquee.start();
	}

	private void leave(PlaceholderField field)
	{
		if (hovered != field)
		{
			return;
		}
		hovered = null;
		marquee.stop();
		// Back to the beginning of the name, unless the caret is in it: then it is the caret's to place.
		if (!field.isFocusOwner() || field.getText().isEmpty())
		{
			field.scrollTo(0);
		}
	}

	private void scrollHovered()
	{
		PlaceholderField field = hovered;
		if (field == null || !field.isShowing())
		{
			// The row went, rebuilt or turned off the page, without the mouse ever leaving it.
			hovered = null;
			marquee.stop();
			return;
		}
		if (field.isFocusOwner())
		{
			// A name being typed stays where the caret put it: text moving under the caret would
			// fight every keypress. Started over from the beginning once the caret has gone.
			hoveredSince = System.currentTimeMillis();
			if (field.getText().isEmpty())
			{
				field.scrollTo(0);
			}
			return;
		}
		field.scrollTo(marqueeOffset(field.overflow(), System.currentTimeMillis() - hoveredSince));
	}

	/**
	 * How far along a name should be shown this long into the hover: resting at the beginning,
	 * scrolled to the end, resting there, scrolled back, and round again.
	 */
	private static int marqueeOffset(int overflow, long elapsed)
	{
		if (overflow <= 0)
		{
			return 0;
		}
		long travel = overflow * 1000L / MARQUEE_SPEED;
		long at = elapsed % (2 * (MARQUEE_REST + travel));
		if (at < MARQUEE_REST)
		{
			return 0;
		}
		at -= MARQUEE_REST;
		if (at < travel)
		{
			return (int) (overflow * at / travel);
		}
		at -= travel;
		if (at < MARQUEE_REST)
		{
			return overflow;
		}
		at -= MARQUEE_REST;
		return (int) (overflow - overflow * at / travel);
	}

	/** Puts a golem's name into its field, if it differs, without that counting as typing. */
	private static void showName(Row row, Golem golem)
	{
		String name = golem.getNickname() == null ? "" : golem.getNickname();
		if (!row.name.getText().trim().equals(name))
		{
			row.settingName = true;
			try
			{
				row.name.setText(name);
				// A field longer than the box scrolls to wherever the caret is, and setText leaves
				// it at the end: a golem called something long showed the last of its name with the
				// first of it off the left edge. Wound back so a name reads from its beginning.
				row.name.setCaretPosition(0);
			}
			finally
			{
				row.settingName = false;
			}
		}
	}

	/**
	 * Shows or hides the revive button: only present when there is something to revive, since a
	 * button that does nothing most of the time is worse than no button.
	 */
	private void updateRevive(int missing)
	{
		boolean show = missing > 0;
		if (show)
		{
			revive.setText("Revive missing golems (" + missing + ")");
		}
		if (revive.isVisible() != show)
		{
			revive.setVisible(show);
			revalidate();
			repaint();
		}
	}

	private void updateSummary(int count)
	{
		summary.setText(count == 0
			? "No golems yet"
			: count + (count == 1 ? " golem" : " golems") + " unleashed");
	}

	private Row row(Golem golem)
	{
		JPanel panel = new JPanel(new BorderLayout(6, 0));
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		panel.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 6));
		panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 56));

		// Where the golem is, under its name: what it last said, or blank until the first update,
		// so a row does not jump in height the moment the panel is opened.
		String before = lastSaid.get(golem);
		JLabel place = new JLabel(before == null ? " " : before);
		place.setFont(FontManager.getRunescapeSmallFont());
		place.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		place.setBorder(BorderFactory.createEmptyBorder(2, 2, 0, 0));
		place.setMinimumSize(SQUEEZED);

		// The dimmed prompt is the name the plugin would call it, so an unnamed golem still reads
		// as somebody. Left as a prompt rather than put in the field: it is not a name until it
		// is typed, and a field holding it would save it as one.
		String suggested = names.suggested(golem);
		PlaceholderField name = new PlaceholderField(golem.getNickname(),
			suggested == null ? "Unnamed golem" : suggested);
		name.setMinimumSize(SQUEEZED);
		// A field holding more than it can show scrolls to the caret, and a fresh one leaves that
		// at the end: a golem with a long name showed the last of it with the first off the left
		// edge. The row is built with the name already in it, so this is where it is wound back.
		name.setCaretPosition(0);
		Row[] self = new Row[1];
		name.nameTip();
		name.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover(name);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				leave(name);
			}
		});
		name.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				rename();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				rename();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				rename();
			}

			private void rename()
			{
				// Typed or put in from the game, the tip says the name the field now holds.
				name.nameTip();
				if (self[0] != null && self[0].settingName)
				{
					return;
				}
				// Not set here: golems belong to the client thread, and this is Swing's.
				String text = name.getText().trim();
				onRename.accept(golem, text.isEmpty() ? null : text);
			}
		});
		// Name across the top, place beneath it.
		JButton find = new JButton(TARGET);
		find.setToolTipText("Point at this golem until you reach it");
		find.setFocusPainted(false);
		find.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		find.setBorder(BorderFactory.createEmptyBorder(2, 5, 2, 5));
		find.addActionListener(e -> onFind.accept(golem));

		JButton page = new JButton(INFO);
		page.setToolTipText("This golem's page");
		page.setFocusPainted(false);
		page.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		page.setBorder(BorderFactory.createEmptyBorder(2, 5, 2, 5));
		page.addActionListener(e -> onOpen.accept(golem));

		JButton remove = new JButton(REMOVE);
		remove.setToolTipText("Remove this golem");
		remove.setFocusPainted(false);
		remove.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		remove.setBorder(BorderFactory.createEmptyBorder(2, 5, 2, 5));
		remove.addActionListener(e -> onRemove.accept(golem));
		JPanel buttons = new JPanel(new BorderLayout(2, 0));
		buttons.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		buttons.add(page, BorderLayout.WEST);
		buttons.add(find, BorderLayout.CENTER);
		buttons.add(remove, BorderLayout.EAST);

		// In front of the name, where a star is looked for. Painted from the golem each time, so it
		// is right however the golem was starred.
		JButton star = new JButton(new Star(golem));
		star.setToolTipText("Star this golem to keep it at the top of the list");
		star.setFocusPainted(false);
		star.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		star.setBorder(BorderFactory.createEmptyBorder(2, 0, 2, 2));
		star.addActionListener(e -> onStar.accept(golem));

		// The name shares the top of the row with the buttons; the place has the whole width of
		// the row underneath, which is what it needs to say "Sailing to Port Khazard".
		JPanel top = new JPanel(new BorderLayout(4, 0));
		top.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		top.setMinimumSize(SQUEEZED);
		top.add(star, BorderLayout.WEST);
		top.add(name, BorderLayout.CENTER);
		top.add(buttons, BorderLayout.EAST);

		JPanel text = new JPanel(new BorderLayout());
		text.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		text.setMinimumSize(SQUEEZED);
		text.add(top, BorderLayout.CENTER);
		text.add(place, BorderLayout.SOUTH);
		panel.add(text, BorderLayout.CENTER);

		// Spacing between rows, which a BoxLayout will not do on its own.
		JPanel spaced = new JPanel(new BorderLayout());
		spaced.setBackground(ColorScheme.DARK_GRAY_COLOR);
		spaced.setBorder(BorderFactory.createEmptyBorder(0, 0, 6, 0));
		spaced.setMaximumSize(new Dimension(Integer.MAX_VALUE, 62));
		spaced.add(panel, BorderLayout.CENTER);
		self[0] = new Row(spaced, name);
		self[0].place = place;
		return self[0];
	}

	/** A star, filled in gold for a starred golem and drawn in outline for the rest. */
	private static final class Star implements Icon
	{
		private static final int SIZE = 14;
		private static final Color GOLD = new Color(0xFFB83F);

		private final Golem golem;

		private Star(Golem golem)
		{
			this.golem = golem;
		}

		@Override
		public int getIconWidth()
		{
			return SIZE;
		}

		@Override
		public int getIconHeight()
		{
			return SIZE;
		}

		@Override
		public void paintIcon(Component on, Graphics g, int x, int y)
		{
			Graphics2D drawing = (Graphics2D) g.create();
			drawing.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			drawing.translate(x, y);
			Path2D.Float shape = new Path2D.Float();
			float middle = SIZE / 2f;
			for (int point = 0; point < 10; point++)
			{
				// Five points out and five in, from straight up.
				double angle = Math.PI * point / 5 - Math.PI / 2;
				float reach = point % 2 == 0 ? middle - 0.5f : middle * 0.42f;
				float px = middle + (float) Math.cos(angle) * reach;
				float py = middle + 0.6f + (float) Math.sin(angle) * reach;
				if (point == 0)
				{
					shape.moveTo(px, py);
				}
				else
				{
					shape.lineTo(px, py);
				}
			}
			shape.closePath();
			if (golem.isFavourite())
			{
				drawing.setColor(GOLD);
				drawing.fill(shape);
			}
			else
			{
				drawing.setColor(ColorScheme.MEDIUM_GRAY_COLOR);
				drawing.setStroke(new BasicStroke(1.2f));
				drawing.draw(shape);
			}
			drawing.dispose();
		}
	}

	/**
	 * The list, kept to the width of what it is scrolled in.
	 *
	 * <p>A panel in a scroll pane is laid out at whatever width its contents ask for, and a row
	 * asks for room enough for a long name and a long place. The list then ran on past the right
	 * edge of the viewport, taking the buttons at the end of each row with it and leaving them
	 * under the scrollbar. Tracking the viewport's width squeezes the text instead, which is what
	 * a text field and a label are for.
	 */
	private static final class Tracking extends JPanel implements Scrollable
	{
		private Tracking()
		{
			super(new BorderLayout());
		}

		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visible, int orientation, int direction)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visible, int orientation, int direction)
		{
			return visible.height;
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}

	/**
	 * A text field that shows dimmed italic prompt text while it is empty. Swing has no
	 * placeholder, and the obvious workaround - real text cleared on focus - is wrong here:
	 * that text is indistinguishable from a name and would be saved as one.
	 */
	private static final class PlaceholderField extends JTextField
	{
		private final String prompt;

		/** How far the prompt is scrolled to the left, while a prompt too long for the field is hovered. */
		private int promptOffset;

		PlaceholderField(String initial)
		{
			this(initial, "Unnamed golem");
		}

		PlaceholderField(String initial, String prompt)
		{
			super(initial == null ? "" : initial);
			this.prompt = prompt;
			setFont(ROW);
			setBackground(ColorScheme.DARKER_GRAY_COLOR);
			setForeground(Color.WHITE);
			setCaretColor(Color.WHITE);
			setBorder(BorderFactory.createEmptyBorder(4, 4, 4, 4));
		}

		/**
		 * Says the whole name, typed or prompted, when a golem's name field is hovered. The field is
		 * kept narrow so the buttons beside it have their room, and a long name is cut off in it.
		 */
		void nameTip()
		{
			String typed = getText().trim();
			String shown = (typed.isEmpty() ? prompt : typed)
				.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
			setToolTipText("<html>" + shown + "<br>" + (typed.isEmpty() ? "Click to name" : "Click to rename")
				+ "</html>");
		}

		/** How many pixels of what the field shows, its text or else its prompt, do not fit in it. */
		int overflow()
		{
			if (getText().isEmpty())
			{
				Insets edges = getInsets();
				return getFontMetrics(PLACEHOLDER).stringWidth(prompt) - (getWidth() - edges.left - edges.right);
			}
			BoundedRangeModel visible = getHorizontalVisibility();
			return visible.getMaximum() - visible.getExtent();
		}

		/**
		 * Shows what the field holds from this many pixels in. Text is scrolled the way the field
		 * scrolls it for the caret; the prompt is painted here and not by the field, so it is moved
		 * along by hand.
		 */
		void scrollTo(int offset)
		{
			if (!getText().isEmpty())
			{
				setScrollOffset(offset);
			}
			else if (promptOffset != offset)
			{
				promptOffset = offset;
				repaint();
			}
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			super.paintComponent(g);

			if (!getText().isEmpty())
			{
				return;
			}

			Graphics2D g2 = (Graphics2D) g.create();
			try
			{
				g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
					RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
				g2.setFont(PLACEHOLDER);
				g2.setColor(PLACEHOLDER_COLOUR);

				// On the same baseline as the real text, so the prompt does not jump
				// when the player types over it.
				Insets edges = getInsets();
				int x = edges.left - promptOffset;
				int y = (getHeight() - g2.getFontMetrics().getHeight()) / 2
					+ g2.getFontMetrics().getAscent();
				// Kept inside the border, as the field keeps its own text, so a prompt scrolled
				// left does not run out over the edge.
				g2.clipRect(edges.left, 0, getWidth() - edges.left - edges.right, getHeight());
				g2.drawString(prompt, x, y);
			}
			finally
			{
				g2.dispose();
			}
		}
	}
}

package com.golemsdontdie;

import java.awt.*;
import java.awt.image.*;
import java.util.*;
import java.util.List;
import javax.inject.*;
import lombok.extern.slf4j.*;
import net.runelite.api.*;
import net.runelite.api.Point;
import net.runelite.api.coords.*;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.*;
import net.runelite.api.worldmap.*;
import net.runelite.api.worldmap.WorldMapData;
import net.runelite.client.ui.*;
import net.runelite.client.ui.overlay.worldmap.*;
import net.runelite.client.util.*;
import static com.golemsdontdie.RouteGeometry.span;

/**
 * Golems on the world map: all of them, as faces that say who is there when hovered.
 *
 * <p>A face per golem does not scale - a player who has crafted for months has ten thousand, and the
 * map overlay looks up a widget and measures it for every point it holds, on every frame the map is
 * open. So golems are gathered by where they would be drawn: the map is cut into cells the size of
 * one face at the current zoom, and each cell holding golems gets one point saying how many. Zoom in
 * and the cells shrink until each golem has a face of its own; zoom out and a crowd becomes one face
 * with a number. Either way the map holds about as many points as there are places to put them.
 *
 * <p>Only while the map is open, and only for the stretch on screen. Any map: a golem in a dungeon
 * goes where that dungeon's map draws its tile and floor (see WorldMapLayers), so golems appear on a
 * dungeon map as readily as on the surface. Closed, the map holds nothing and this costs one widget
 * lookup a tick.
 */
@Slf4j
@Singleton
class GolemMapPoints
{
	/** Points held at most. The screen has nowhere to put more faces than this without overlap. */
	private static final int MOST_POINTS = 600;

	/** Tiles kept beyond the edge of the map, so a golem walking into view is already there. */
	private static final int MARGIN = 16;

	/** The face's size on screen, in pixels, which sets how far apart two faces must be. */
	private static final int FACE_PIXELS = 15;

	/** How far north of the ground above it a cave is laid out. See WorldLayout. */
	private static final int UNDERGROUND = WorldLayout.CAVE_OFFSET;

	/**
	 * The map being looked at, which is what decides where a golem belongs on it.
	 *
	 * <p>The client draws each map - the surface, every dungeon - in its own coordinate space, and
	 * refuses a point whose coordinates are not in the one on screen. This is the client's own
	 * answer to "is this tile on this map", so it is the one asked, rather than the plugin working
	 * it out from where the player happens to be standing.
	 */
	private WorldMapData showing;

	/** Whether the map was shut last time this ran: the frame it opens is refreshed at once. */
	private boolean wasShut = true;

	/**
	 * Whether the map wants a refresh before the next game tick: on the frame it opens, and on the
	 * frame another map is picked. A tick is 600ms, and asked only once a tick, the golems came onto
	 * a map a second or more after everything else on it.
	 */
	boolean wantsFrame()
	{
		Widget window = client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER);
		if (window == null || window.isHidden())
		{
			return false;
		}
		WorldMap map = client.getWorldMap();
		return wasShut || map != null && map.getWorldMapData() != showing;
	}

	/** Named faces kept before the oldest are dropped: renaming in the sidebar makes one a keystroke. */
	private static final int MOST_LABELS = 256;

	@Inject
	private Client client;

	@Inject
	private WorldMapPointManager mapPoints;

	@Inject
	private Whereabouts whereabouts;

	/** What a golem is called, auto name and all, for the tooltip. See GolemNames. */
	@Inject
	private GolemNames names;

	/** Where each map other than the surface draws the game's tiles. */
	@Inject
	private WorldMapLayers layers;

	/** Where the map draws a golem, reused for every golem. */
	private final int[] spot = new int[2];

	/**
	 * For a map newer than the shipped table, how far it draws its ground from where it really is,
	 * measured from the player, on whom the map centres as it opens; and the map it was measured for.
	 * A map the table knows never needs it.
	 */
	private int offsetX;
	private int offsetY;
	private WorldMapData measuredFor;

	/**
	 * Translations further than this are not believed: a player on the grass looking at a dungeon
	 * map is not on it, a hundred regions off, against the few that separate a dungeon from its place.
	 */
	private static final int MOST_OFFSET = 4096;

	/** Read only to tell sea from land, when the golem being found is shown over the ground above it. */
	@Inject
	private WorldMesh mesh;

	@Inject
	private GolemsDontDieConfig config;

	/** Faces with a name written over them, by the name. A player names a few dozen golems at most. */
	private final Map<String, BufferedImage> labelled = new HashMap<>();

	private BufferedImage face;

	/** Cell key to its place in {@link #cellList}. Reused between refreshes rather than rebuilt. */
	private final TileMap cells = new TileMap(256);
	private final List<Cell> cellList = new ArrayList<>();

	/** The points on the map, one per filled cell, in step with the first {@link #used} cells. */
	private final List<CellPoint> shown = new ArrayList<>();

	private int used;
	private int tick;

	/** True while one golem is being looked for, which is drawn stuck to the map's edge. */
	private boolean pinned;

	void startUp()
	{
		face = ImageUtil.loadImageResource(GolemsDontDiePlugin.class, "/golem-map-icon.png");
		layers.load();
	}

	/** Takes every golem off the map. */
	void clear()
	{
		// Called every tick the map is shut, and nearly always there is nothing to take off.
		if (wasShut && shown.isEmpty())
		{
			return;
		}
		// Nothing on the map, so the next refresh that finds one open is a fresh one to measure.
		wasShut = true;
		for (CellPoint point : shown)
		{
			mapPoints.remove(point);
		}
		shown.clear();
		used = 0;
		cells.clear();
		labelled.clear();
		measuredFor = null;
	}

	/**
	 * Brings the map up to date with where the golems are.
	 *
	 * @param golems the whole roster, crumbling golems and all: they are passed over here, so the
	 *               caller need not copy the roster every tick to leave them out
	 * @param named  true to show only golems with names
	 */
	void refresh(List<Golem> golems, boolean named, int tick)
	{
		refresh(golems, named, tick, null);
	}

	/**
	 * As {@link #refresh(List, boolean, int)}, but showing one golem alone.
	 *
	 * <p>While a golem is being looked for it is the only thing on the map, and its face sticks to
	 * the edge when the map is panned away from it, the way a clue scroll's marker does - the point
	 * of looking for a golem is to be told which way it lies.
	 */
	void refresh(List<Golem> golems, boolean named, int tick, Golem only)
	{
		this.tick = tick;
		if (face == null)
		{
			return;
		}
		if (only != null)
		{
			golems = Collections.singletonList(only);
			named = false;
		}
		this.pinned = only != null;

		WorldMap map = client.getWorldMap();
		Widget window = client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER);
		if (map == null || window == null || window.isHidden() || map.getWorldMapZoom() <= 0)
		{
			clear();
			return;
		}
		wasShut = false;

		// How near two golems have to be to share a face, in tiles: half a face's width at this
		// zoom, so two faces touching is what merges them rather than two faces near each other.
		// Zoomed all the way in that is a tile, and every golem has a face of its own.
		float zoom = map.getWorldMapZoom();
		int cellTiles = Math.max(1, Math.round(FACE_PIXELS / zoom / 2f));
		Point centre = map.getWorldMapPosition();
		showing = map.getWorldMapData();
		if (showing != measuredFor)
		{
			measuredFor = showing;
			offsetX = 0;
			offsetY = 0;
			if (layers.layerOf(showing) == null)
			{
				measure(map.getWorldMapPosition());
			}
		}
		int halfWidth = (int) Math.ceil(window.getBounds().getWidth() / zoom / 2) + MARGIN;
		int halfHeight = (int) Math.ceil(window.getBounds().getHeight() / zoom / 2) + MARGIN;

		gather(golems, named, cellTiles, centre.getX() - halfWidth, centre.getX() + halfWidth,
			centre.getY() - halfHeight, centre.getY() + halfHeight);
		// Zoomed all the way in, a cell is a tile and every golem keeps its own face, so there is
		// nothing to join: two golems standing next to each other are two golems, and drawing them
		// as one is what zooming in was meant to undo.
		if (cellTiles > 1)
		{
			join(cellTiles);
		}
		draw();
	}

	/**
	 * Works out where a map the table does not know draws the ground the player is on: on the frame
	 * it opens it is centred on the player, so the centre, in the map's coordinates, against the
	 * player's own tile is the translation. Only believed if it is whole map squares and lands on the
	 * map, so a map of somewhere else is left unmeasured.
	 */
	private void measure(Point centre)
	{
		WorldPoint at = PlayerPosition.of(client);
		if (showing == null || at == null || centre == null || showing.surfaceContainsPosition(at.getX(), at.getY()))
		{
			return;
		}
		int dx = centre.getX() - at.getX();
		int dy = centre.getY() - at.getY();
		if ((dx & 63) == 0 && (dy & 63) == 0 && Math.abs(dx) <= MOST_OFFSET && Math.abs(dy) <= MOST_OFFSET
			&& showing.surfaceContainsPosition(at.getX() + dx, at.getY() + dy))
		{
			offsetX = dx;
			offsetY = dy;
			log.debug("A map newer than the table draws its ground {},{} from where it is", dx, dy);
		}
	}

	/** Sorts the golems on screen into cells, counting each and keeping a few names. */
	private void gather(List<Golem> golems, boolean named, int cellTiles, int minX, int maxX, int minY, int maxY)
	{
		cells.clear();
		used = 0;
		WorldMapLayers.Layer layer = layers.layerOf(showing);

		for (Golem golem : golems)
		{
			// "Named" means the golems a player has marked out: named or starred.
			if (golem.isDying() || named && !isNamed(golem) && !golem.isFavourite())
			{
				continue;
			}

			// Read from the golem's own numbers rather than a WorldPoint: ten thousand golems is ten
			// thousand objects a tick otherwise, and most of them are off screen.
			int x = golem.getFineX() / Golem.TILE;
			int y = golem.getFineY() / Golem.TILE;
			if (golem.isSailing(tick))
			{
				// Where the raft is now, which on a map is where you would look for it. The golem's
				// own tile is the port it is bound for - that is what a crossing saves - so the
				// crossing itself is asked where it has got to.
				WorldPoint at = golem.seaPosition(tick);
				if (at != null)
				{
					x = at.getX();
					y = at.getY();
				}
			}
			// Where this golem goes on the map that is open, and only that map, as the game shows the
			// player: on a dungeon's map, where that map draws the golem's own tile and floor, which may
			// be far from where it is (see WorldMapLayers); on the surface, where it is. A golem
			// underground is not on the surface map, and one on the surface is not on a dungeon's,
			// unless it is the one being looked for.
			if (layer != null)
			{
				if (!layer.place(x, y, golem.getPlane(), spot))
				{
					continue;
				}
				x = spot[0];
				y = spot[1];
			}
			else if (showing != null && !showing.surfaceContainsPosition(x, y))
			{
				// A map newer than the table, drawn away from its own coordinates by the offset measured
				// for it; anything it does not draw is somewhere else. Except the golem being looked for,
				// underground, on the surface: over the ground above it, so the map still says which way
				// it lies. Most caves are dug at their ground's coordinates plus this; where the fold lands
				// in the sea, as the Observatory's does, it is no place at all.
				if ((offsetX != 0 || offsetY != 0) && showing.surfaceContainsPosition(x + offsetX, y + offsetY))
				{
					x += offsetX;
					y += offsetY;
				}
				else if (pinned && y >= UNDERGROUND && showing.surfaceContainsPosition(x, y - UNDERGROUND)
					&& !mesh.isOcean(x, y - UNDERGROUND, 0))
				{
					y -= UNDERGROUND;
				}
				else
				{
					continue;
				}
			}
			// The golem being looked for is kept whether or not the map is looking at it: its face
			// snaps to the edge to say which way it lies.
			if (!pinned && (x < minX || x > maxX || y < minY || y > maxY))
			{
				continue;
			}

			// The nearest group close enough to take it, looked for in the nine cells around the
			// golem: a group is only ever a cell or so across, so nothing further can reach.
			int index = -1;
			long nearest = Long.MAX_VALUE;
			boolean alone = pinned || cellTiles <= 1;
			for (int dx = -1; dx <= 1 && !alone; dx++)
			{
				for (int dy = -1; dy <= 1; dy++)
				{
					int at = (int) cells.getOrDefault(bucket(x / cellTiles + dx, y / cellTiles + dy, golem.getPlane()), -1);
					if (at < 0)
					{
						continue;
					}
					Cell group = cellList.get(at);
					if (group.plane != golem.getPlane())
					{
						continue;
					}
					// A group of twenty is drawn with a head twice the size, and reaches as far.
					long reach = (long) (cellTiles * CROWD_SIZES[sizeFor(group.count)]);
					long away = span(group.x - x, group.y - y);
					if (away <= reach && away < nearest)
					{
						nearest = away;
						index = at;
					}
				}
			}

			if (index < 0)
			{
				if (used >= MOST_POINTS)
				{
					continue;
				}
				if (used >= cellList.size())
				{
					cellList.add(new Cell());
				}
				index = used++;
				Cell fresh = cellList.get(index);
				fresh.x = x;
				fresh.y = y;
				fresh.sumX = 0;
				fresh.sumY = 0;
				fresh.plane = golem.getPlane();
				fresh.count = 0;
				fresh.first = golem;
				// Bucketed where it started, so the golems after it can find it. Once: a second
				// cell in a bucket, its group grown out of reach, was a second entry for one key.
				long key = bucket(x / cellTiles, y / cellTiles, golem.getPlane());
				if (!cells.containsKey(key))
				{
					cells.add(key, index);
				}
			}
			Cell cell = cellList.get(index);
			cell.count++;
			cell.sumX += x;
			cell.sumY += y;
			// A group sits at the middle of the golems in it, which is where a player would say
			// they are. Laid out on the cells instead, a crowd came out as a lattice of heads.
			cell.x = (int) (cell.sumX / cell.count);
			cell.y = (int) (cell.sumY / cell.count);
		}
	}

	/**
	 * Joins up groups whose faces would still overlap.
	 *
	 * <p>Gathering takes each golem into the nearest group it can reach, which leaves groups that
	 * grew towards each other afterwards: two faces a few pixels apart, which is what a player
	 * sees as two heads on top of one another. This is the pass that puts those together, run a
	 * few times over because a joined group is larger and reaches further than either half did.
	 */
	private void join(int cellTiles)
	{
		for (int pass = 0; pass < JOIN_PASSES; pass++)
		{
			boolean joined = false;
			for (int i = 0; i < used; i++)
			{
				Cell one = cellList.get(i);
				if (one.count == 0)
				{
					continue;
				}
				for (int j = i + 1; j < used; j++)
				{
					Cell other = cellList.get(j);
					if (other.count == 0 || other.plane != one.plane)
					{
						continue;
					}
					// Two heads overlap when they are nearer than the two half-widths together.
					int reach = (int) (cellTiles * (CROWD_SIZES[sizeFor(one.count)]
						+ CROWD_SIZES[sizeFor(other.count)]));
					if (span(one.x - other.x, one.y - other.y) > reach)
					{
						continue;
					}
					one.count += other.count;
					one.sumX += other.sumX;
					one.sumY += other.sumY;
					one.x = (int) (one.sumX / one.count);
					one.y = (int) (one.sumY / one.count);
					other.count = 0;
					joined = true;
				}
			}
			if (!joined)
			{
				break;
			}
		}

		// Close the gaps the joining left, so draw() can walk the first `used` of them.
		int kept = 0;
		for (int i = 0; i < used; i++)
		{
			Cell cell = cellList.get(i);
			if (cell.count > 0)
			{
				cellList.set(i, cellList.get(kept));
				cellList.set(kept, cell);
				kept++;
			}
		}
		used = kept;
	}

	/** How many times the joining is run over. A joined group reaches further than its halves. */
	private static final int JOIN_PASSES = 3;

	/** A cell's key, by floor too: a group upstairs shared its bucket with one below, and each golem
	 * up there that found the downstairs group in its bucket made a cell of its own. */
	private static long bucket(int x, int y, int plane)
	{
		return ((long) plane << 60) | ((long) x << 32) | y & 0xFFFFFFFFL;
	}

	/** Puts a point on each filled cell, keeping the ones already on the map. */
	private void draw()
	{
		while (shown.size() > used)
		{
			mapPoints.remove(shown.remove(shown.size() - 1));
		}
		for (int i = 0; i < used; i++)
		{
			Cell cell = cellList.get(i);
			WorldPoint at = new WorldPoint(cell.x, cell.y, cell.plane);
			CellPoint point;
			if (i < shown.size())
			{
				point = shown.get(i);
				point.cell = cell;
				if (!at.equals(point.getWorldPoint()))
				{
					point.setWorldPoint(at);
				}
			}
			else
			{
				point = new CellPoint(cell, at, face);
				shown.add(point);
				mapPoints.add(point);
			}
			point.setSnapToEdge(pinned);
			dress(point, cell);
		}
	}

	/**
	 * Gives a point its picture: a plain face, or the face with the golem's name written over it.
	 *
	 * <p>The name is part of the image because the map overlay draws images and nothing else. The
	 * image is anchored on the face rather than its middle, so the name sits above the golem's tile
	 * rather than pushing the face off it.
	 */
	private void dress(CellPoint point, Cell cell)
	{
		String name = cell.count == 1 && isNamed(cell.first) ? cell.first.getNickname().trim() : null;
		if (name == null)
		{
			BufferedImage head = faceFor(cell.count);
			if (point.getImage() != head)
			{
				point.setImage(head);
				point.setImagePoint(null);
			}
			return;
		}
		if (labelled.size() > MOST_LABELS)
		{
			labelled.clear();
		}
		BufferedImage withName = labelled.computeIfAbsent(name, this::label);
		if (point.getImage() != withName)
		{
			point.setImage(withName);
			point.setImagePoint(new Point(withName.getWidth() / 2,
				withName.getHeight() - face.getHeight() / 2));
		}
	}

	/**
	 * How many golems a face has to stand for before it is drawn larger, and how much larger.
	 *
	 * <p>Zooming out puts more golems in a cell, which is what makes the heads grow as the map
	 * pulls back and split again as it comes in.
	 */
	private static final int[] CROWDS = {1, 3, 10, 40};
	private static final float[] CROWD_SIZES = {1f, 1.35f, 1.8f, 2.3f};

	/** The faces, one per size, drawn from the shipped one the first time each is wanted. */
	private final BufferedImage[] faces = new BufferedImage[CROWDS.length];

	/** Which of the face sizes a group of this many golems is drawn at. */
	private static int sizeFor(int count)
	{
		int size = 0;
		for (int i = 1; i < CROWDS.length; i++)
		{
			if (count >= CROWDS[i])
			{
				size = i;
			}
		}
		return size;
	}

	/** The face to draw for a cell holding this many golems. */
	private BufferedImage faceFor(int count)
	{
		int size = sizeFor(count);
		if (faces[size] == null)
		{
			faces[size] = size == 0 ? face
				: ImageUtil.resizeImage(face, Math.round(face.getWidth() * CROWD_SIZES[size]),
					Math.round(face.getHeight() * CROWD_SIZES[size]), true);
		}
		return faces[size];
	}

	/** The face with a name above it, drawn once per name and kept. */
	private BufferedImage label(String name)
	{
		Font font = FontManager.getRunescapeSmallFont();
		BufferedImage measuring = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
		Graphics2D measure = measuring.createGraphics();
		measure.setFont(font);
		FontMetrics metrics = measure.getFontMetrics();
		int textWidth = metrics.stringWidth(name);
		int textHeight = metrics.getHeight();
		measure.dispose();

		int width = Math.max(face.getWidth(), textWidth + 2);
		BufferedImage image = new BufferedImage(width, textHeight + face.getHeight(),
			BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
		graphics.setFont(font);
		int textX = (width - textWidth) / 2;
		int baseline = metrics.getAscent();
		// The game's own shadow, a pixel down and right, so the name reads over any map colour.
		graphics.setColor(Color.BLACK);
		graphics.drawString(name, textX + 1, baseline + 1);
		// The colour without its see-through: a name on the map is written on, as the map's own are.
		graphics.setColor(new Color(config.nameplateColour().getRGB() & 0xFFFFFF));
		graphics.drawString(name, textX, baseline);
		graphics.drawImage(face, (width - face.getWidth()) / 2, textHeight, null);
		graphics.dispose();
		return image;
	}

	private static boolean isNamed(Golem golem)
	{
		return golem.getNickname() != null && !golem.getNickname().isEmpty();
	}

	/** The golems drawn as one face: where they are, how many, and a few of their names. */
	private static final class Cell
	{
		/** Where the face goes: the middle of the golems in it. */
		int x;
		int y;

		/** Their positions added up, which is how the middle is kept as each one joins. */
		long sumX;
		long sumY;

		int plane;
		int count;
		Golem first;
	}

	/** One face on the map, which says who is under it only when asked. */
	private final class CellPoint extends WorldMapPoint
	{
		private Cell cell;

		private CellPoint(Cell cell, WorldPoint at, BufferedImage face)
		{
			super(at, face);
			this.cell = cell;
			// No "Focus on" entry: it is a second thing to read beside the tooltip, in a menu the
			// map puts up whether or not anything was asked of it.
			setJumpOnClick(false);
		}

		/**
		 * Only ever itself. RuneLite's point is a value, equal to any other at the same tile with the
		 * same picture and tooltip, and the map takes points off by equality: two unnamed golems on
		 * one tile, and taking one face off took the other's, leaving a face on the map that nothing
		 * held any more, through closing the map and turning the plugin off.
		 */
		@Override
		public boolean equals(Object other)
		{
			return this == other;
		}

		@Override
		public int hashCode()
		{
			return System.identityHashCode(this);
		}

		/** What this face is of: a golem's name, or how many golems are standing together. */
		private String title()
		{
			if (cell == null || cell.count == 0)
			{
				return "Golems";
			}
			if (cell.count == 1)
			{
				String name = names.of(cell.first);
				return name != null ? name : "A golem";
			}
			return cell.count + " golems";
		}

		/**
		 * Asked by the map overlay for the point under the mouse, and only that one, so naming a
		 * place happens once rather than hundreds of times a frame.
		 */
		@Override
		public String getTooltip()
		{
			// Never nothing while the face is on the map: with no tooltip of ours the map falls
			// back on its own, which is the game's white one over whatever is underneath.
			if (cell == null || cell.count == 0 || cell.first == null)
			{
				return "Golems";
			}
			String place = whereabouts.of(cell.first, tick);
			// What it is called, then where: its own name, or the one auto naming gives it. Only a
			// name the player gave is drawn on the map itself - auto named, every face on the map
			// would carry a label - but the tooltip is for one golem, and says who it is.
			if (cell.count == 1)
			{
				String name = names.of(cell.first);
				return name == null ? place : name + " · " + place;
			}
			return title() + " · " + place;
		}
	}
}

package com.golemsdontdie;

import java.awt.*;
import java.util.*;
import java.util.List;
import java.util.function.*;
import javax.inject.*;
import net.runelite.api.*;
import net.runelite.api.Point;
import net.runelite.api.coords.*;
import net.runelite.client.callback.*;
import net.runelite.client.game.chatbox.*;

/**
 * Gives the copies the right-click menu the real golems have.
 *
 * <p>A {@link net.runelite.api.RuneLiteObjectController} is drawn by the client but is not
 * an entity it builds a menu from, so hovering a copy would otherwise produce nothing. The
 * hit test is done by hand each tick, as the game picks a model (FakeGolem.isUnder). Entries use
 * {@link MenuAction#RUNELITE} with their own handlers, so nothing reaches the server.
 */
@Singleton
class GolemMenu
{
	/** Target colour the client uses for an NPC with no combat level. */
	private static final String NPC_COLOUR = "<col=ffff00>";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ChatboxPanelManager chatboxPanelManager;

	@Inject
	private GolemNames names;

	/** Told when a golem is named here, so the roster is saved and the sidebar shows it. */
	private Consumer<Golem> onRenamed = golem ->
	{
	};

	void setOnRenamed(Consumer<Golem> onRenamed)
	{
		this.onRenamed = onRenamed;
	}

	/** Opens a golem's page. Set by the plugin, which owns the window. */
	private Consumer<Golem> onInfo = golem ->
	{
	};

	void setOnInfo(Consumer<Golem> onInfo)
	{
		this.onInfo = onInfo;
	}

	/**
	 * Adds entries for every golem under the cursor, as the game lists every NPC under it: nearest
	 * the camera highest. Called once per client tick, after the client has built its menu.
	 */
	void addEntries(List<Golem> golems)
	{
		if (client.isMenuOpen() || golems.isEmpty())
		{
			return;
		}

		Point mouse = client.getMouseCanvasPosition();
		if (mouse == null || mouse.getX() < 0 || mouse.getY() < 0)
		{
			return;
		}

		// Over the scene, by the client's own word: it offers entries for the scene only there - Walk
		// here, Set heading at sea, or something in it. Over an interface, the chatbox or the minimap,
		// the game picks nothing in the scene behind, and nor do golems.
		MenuEntry[] entries = client.getMenu().getMenuEntries();
		boolean overScene = false;
		for (MenuEntry entry : entries)
		{
			overScene |= SCENE_ENTRIES.contains(entry.getType());
		}
		if (!overScene)
		{
			return;
		}

		int room = MENU_LIMIT - entries.length;
		boolean shift = client.isKeyPressed(KeyCode.KC_SHIFT);
		for (Golem hovered : golemsAt(golems, mouse))
		{
			if (room < (shift ? 3 : 1))
			{
				break;
			}
			room -= shift ? 3 : 1;
			addEntries(hovered, shift);
		}
	}

	/** The entries the client offers only with the mouse over the scene. */
	private static final Set<MenuAction> SCENE_ENTRIES = EnumSet.of(MenuAction.WALK, MenuAction.SET_HEADING,
		MenuAction.GAME_OBJECT_FIRST_OPTION, MenuAction.GAME_OBJECT_SECOND_OPTION, MenuAction.GAME_OBJECT_THIRD_OPTION,
		MenuAction.GAME_OBJECT_FOURTH_OPTION, MenuAction.GAME_OBJECT_FIFTH_OPTION,
		MenuAction.WIDGET_TARGET_ON_GAME_OBJECT, MenuAction.NPC_FIRST_OPTION, MenuAction.NPC_SECOND_OPTION,
		MenuAction.NPC_THIRD_OPTION, MenuAction.NPC_FOURTH_OPTION, MenuAction.NPC_FIFTH_OPTION,
		MenuAction.WIDGET_TARGET_ON_NPC, MenuAction.PLAYER_FIRST_OPTION, MenuAction.PLAYER_SECOND_OPTION,
		MenuAction.PLAYER_THIRD_OPTION, MenuAction.PLAYER_FOURTH_OPTION, MenuAction.PLAYER_FIFTH_OPTION,
		MenuAction.PLAYER_SIXTH_OPTION, MenuAction.PLAYER_SEVENTH_OPTION, MenuAction.PLAYER_EIGHTH_OPTION,
		MenuAction.WIDGET_TARGET_ON_PLAYER, MenuAction.GROUND_ITEM_FIRST_OPTION,
		MenuAction.GROUND_ITEM_SECOND_OPTION, MenuAction.GROUND_ITEM_THIRD_OPTION, MenuAction.GROUND_ITEM_FOURTH_OPTION,
		MenuAction.GROUND_ITEM_FIFTH_OPTION, MenuAction.WIDGET_TARGET_ON_GROUND_ITEM,
		MenuAction.WORLD_ENTITY_FIRST_OPTION, MenuAction.WORLD_ENTITY_SECOND_OPTION, MenuAction.WORLD_ENTITY_THIRD_OPTION,
		MenuAction.WORLD_ENTITY_FOURTH_OPTION, MenuAction.WORLD_ENTITY_FIFTH_OPTION, MenuAction.EXAMINE_OBJECT,
		MenuAction.EXAMINE_NPC, MenuAction.EXAMINE_ITEM_GROUND, MenuAction.EXAMINE_WORLD_ENTITY);

	/** The most entries the game's menu holds. */
	private static final int MENU_LIMIT = 500;

	/**
	 * One golem's entries, just above Cancel and below any golem nearer the camera: Examine, and with
	 * shift held, as NPC Indicators offers its tag, naming and its page.
	 */
	private void addEntries(Golem hovered, boolean shift)
	{
		// Shown by its name, typed or given by auto naming. Every real golem is called "Golem", so
		// this costs some of the disguise; with auto naming off, only a typed name shows.
		String name = names.of(hovered);
		if (name == null || name.isEmpty())
		{
			name = hovered.getSnapshot().getName();
		}
		String target = NPC_COLOUR + name + "</col>";

		// Index 1, immediately above Cancel, which the client keeps at index 0. The menu array is
		// drawn bottom-up, so each entry put here goes beneath the ones before it.
		client.getMenu().createMenuEntry(1)
			.setOption("Examine")
			.setTarget(target)
			.setType(MenuAction.RUNELITE)
			.onClick(e -> message(GolemContent.GOLEM_EXAMINE));
		if (shift)
		{
			client.getMenu().createMenuEntry(1)
				.setOption("Set Name")
				.setTarget(target)
				.setType(MenuAction.RUNELITE)
				.onClick(e -> askForName(hovered));

			client.getMenu().createMenuEntry(1)
				.setOption("Show Info")
				.setTarget(target)
				.setType(MenuAction.RUNELITE)
				.onClick(e -> onInfo.accept(hovered));
		}
	}

	/**
	 * Adds the plinth's revive entry, above Cancel as the golems' own entries are.
	 *
	 * <p>Shown on a golem plinth while golems are missing and not otherwise, which is why it needs
	 * no shift to reach. The count is in the option, so a player knows what they are asking for
	 * before they ask.
	 */
	void addReviveEntry(int missing, String target, Runnable revive)
	{
		client.getMenu().createMenuEntry(1)
			.setOption("Revive missing golems (" + missing + ")")
			.setTarget(target == null ? "" : target)
			.setType(MenuAction.RUNELITE)
			.onClick(e -> revive.run());
	}

	/** Opens the chatbox prompt for a golem's name. Left empty, it goes back to its auto name, or "Golem". */
	private void askForName(Golem golem)
	{
		String current = golem.getNickname();
		chatboxPanelManager.openTextInput("Name this golem")
			.value(current == null ? "" : current)
			// Enter arrives on the AWT thread; golems are only touched on the client's.
			.onDone((String text) -> clientThread.invoke(() ->
			{
				String name = text.trim();
				golem.setNickname(name.isEmpty() ? null : name);
				onRenamed.accept(golem);
			}))
			.build();
	}

	/** Lower on screen first - that is nearer the camera, the camera never rolling. */
	private static final Comparator<Candidate> BY_DEPTH =
		(a, b) -> Integer.compare(b.screenY, a.screenY);

	/** Reused between ticks so hovering the scene does not allocate every frame. */
	private final List<Candidate> candidates = new ArrayList<>();
	private final List<Golem> under = new ArrayList<>();

	/** Every golem drawn under the mouse, nearest the camera first. See FakeGolem.isUnder. */
	private List<Golem> golemsAt(List<Golem> golems, Point mouse)
	{
		under.clear();
		WorldView wv = client.getTopLevelWorldView();
		if (wv == null)
		{
			return under;
		}
		candidates.clear();
		for (Golem golem : golems)
		{
			FakeGolem renderer = golem.getRenderer();
			if (renderer == null || !renderer.isUnder(mouse.getX(), mouse.getY()))
			{
				continue;
			}
			// In the world the golem is drawn in, which aboard the player's ship is the ship's.
			LocalPoint drawnAt = golem.isAboard() ? golem.drawnPoint(client)
				: new LocalPoint(renderer.getX(), renderer.getY(), wv);
			Point ground = drawnAt == null ? null
				: Perspective.localToCanvas(client, drawnAt, golem.isAboard() ? golem.drawnLevel() : golem.getPlane());
			candidates.add(new Candidate(golem, ground == null ? Integer.MIN_VALUE : ground.getY()));
		}
		candidates.sort(BY_DEPTH);
		for (Candidate candidate : candidates)
		{
			under.add(candidate.golem);
		}
		return under;
	}

	/** A golem under the cursor, with how far down the screen it stands. */
	private static final class Candidate
	{
		final Golem golem;
		final int screenY;

		Candidate(Golem golem, int screenY)
		{
			this.golem = golem;
			this.screenY = screenY;
		}
	}

	/** Sent as the game sends a real NPC's examine, so chat filters and colours treat it as one. */
	private void message(String text)
	{
		client.addChatMessage(ChatMessageType.NPC_EXAMINE, "", text, null);
	}
}

package com.golemsdontdie;

import java.awt.*;
import java.awt.image.*;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.*;
import net.runelite.api.Point;
import net.runelite.api.coords.*;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.widgets.*;
import net.runelite.client.game.*;
import net.runelite.client.ui.overlay.*;

/**
 * Draws the copies onto the minimap, the way a real golem is drawn.
 *
 * <p>The client dots every NPC whose composition asks for one, and the golem's does; a
 * {@link net.runelite.api.RuneLiteObject} is not an NPC, so the copies showed as bare minimap
 * beside real golems. The dot is the game's own sprite, not an approximation: the real one is a
 * shaded circle, and two subtly different yellow dots draw the eye to the fakes. Drawing is
 * clipped to the minimap widget so a golem at the edge slides under the frame.
 */
class GolemMinimapOverlay extends Overlay
{
	/**
	 * Candidate minimap widgets, one per interface layout. Only one exists at a time, and which
	 * depends on settings this plugin does not read, so all four are tried.
	 */
	private static final int[] MINIMAP_WIDGETS = {
		InterfaceID.Toplevel.MINIMAP,
		InterfaceID.ToplevelOsrsStretch.MINIMAP,
		InterfaceID.ToplevelPreEoc.MINIMAP,
		InterfaceID.ToplevelOsm.MINIMAP,
	};

	/**
	 * How far the minimap reaches, in tiles, zoomed all the way out. Beyond this, skip the
	 * projection; within it, the projection says whether the dot is on the minimap at this zoom.
	 */
	private static final int MINIMAP_RANGE_TILES = 40;

	private final Client client;
	private final GolemsDontDiePlugin plugin;
	private final SpriteManager spriteManager;

	/** The game's yellow NPC dot, fetched once the sprite cache can supply it. */
	private BufferedImage dot;

	@Inject
	GolemMinimapOverlay(Client client, GolemsDontDiePlugin plugin, SpriteManager spriteManager)
	{
		this.client = client;
		this.plugin = plugin;
		this.spriteManager = spriteManager;
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(PRIORITY_LOW);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		List<Golem> golems = plugin.drawnGolems();
		if (golems.isEmpty())
		{
			return null;
		}

		WorldView wv = client.getTopLevelWorldView();
		if (wv == null)
		{
			return null;
		}

		if (dot == null)
		{
			// Lazily: the sprite cache may not be ready at start-up, and null means
			// trying again next frame.
			dot = spriteManager.getSprite(SpriteID.MapdotsInterface.YELLOW_NPC, 0);
			if (dot == null)
			{
				return null;
			}
		}

		Rectangle minimap = minimapBounds();
		if (minimap == null)
		{
			return null;
		}

		// Beyond the minimap's reach no projection can yield a dot, and a tile-distance test is
		// two subtractions against a matrix transform - this runs every frame with hundreds of
		// golems. Measured in the main world, aboard a boat too; see PlayerPosition.
		WorldPoint me = PlayerPosition.of(client);
		if (me == null)
		{
			return null;
		}
		int playerX = me.getX();
		int playerY = me.getY();

		Shape original = graphics.getClip();
		graphics.setClip(minimap);
		try
		{
			for (Golem golem : golems)
			{
				// Only golems in the scene: one that has wandered out is off the minimap
				// anyway, and its local coordinates would be meaningless. Where it is drawn, not
				// where it is simulated: inside an instance the two are rooms apart, and a crew's
				// golems stand about the deck rather than all on the helm.
				if (golem.getRenderer() == null || golem.getDrawPlane() != wv.getPlane())
				{
					continue;
				}
				int fineX = golem.getDrawFineX();
				int fineY = golem.getDrawFineY();

				if (Math.abs(fineX / Golem.TILE - playerX) > MINIMAP_RANGE_TILES
					|| Math.abs(fineY / Golem.TILE - playerY) > MINIMAP_RANGE_TILES)
				{
					continue;
				}

				int localX = fineX - wv.getBaseX() * Golem.TILE;
				int localY = fineY - wv.getBaseY() * Golem.TILE;
				if (!Golem.isInScene(wv, localX, localY))
				{
					continue;
				}

				Point at = Perspective.localToMinimap(client, new LocalPoint(localX, localY, wv));
				if (at == null)
				{
					continue;
				}

				// Centred on the point, matching how the client places its own dots.
				graphics.drawImage(dot,
					at.getX() - dot.getWidth() / 2,
					at.getY() - dot.getHeight() / 2,
					null);
			}
		}
		finally
		{
			graphics.setClip(original);
		}

		return null;
	}

	/**
	 * The on-screen rectangle of whichever minimap widget is live.
	 *
	 * @return the bounds, or null if no minimap is showing
	 */
	private Rectangle minimapBounds()
	{
		for (int id : MINIMAP_WIDGETS)
		{
			Widget widget = client.getWidget(id);
			if (widget != null && !widget.isHidden())
			{
				return widget.getBounds();
			}
		}
		return null;
	}
}

package com.golemsdontdie;

import java.util.*;
import javax.inject.*;
import lombok.extern.slf4j.*;
import net.runelite.api.*;

/**
 * Rebuilds a golem's model from the cache, unposed.
 *
 * <p>{@link net.runelite.api.Renderable#getModel()} on the live NPC returns a model already
 * posed for the current frame, in a client-owned buffer. This copy outlives the golem and
 * animates on its own, so it needs the <i>rest</i> pose the animation frames are defined
 * against; posing a posed model compounds the two transforms and folds the golem through itself.
 */
@Slf4j
@Singleton
class GolemModelFactory
{
	/**
	 * The client's base lighting for actors; an NPC's own ambient and contrast add to these. Bare
	 * defaults look flatter and the wrong brightness beside the real thing.
	 */
	private static final int BASE_AMBIENT = 64;
	private static final int BASE_CONTRAST = 850;
	private static final int LIGHT_X = -30;
	private static final int LIGHT_Y = -50;
	private static final int LIGHT_Z = -30;

	/** Composition scales are in 128ths; 128 means "as authored". */
	private static final int UNSCALED = 128;

	@Inject
	private Client client;

	/**
	 * One built model per NPC ID, shared by every golem wearing it. Every golem is the same NPC,
	 * so building one each meant a cache load, merge, vertex clone and lighting pass per golem -
	 * seconds of stall as a few hundred arrive with the scene. Safe because
	 * {@link Client#applyTransformations} clones its source's vertices rather than writing to it.
	 */
	private final Map<Integer, Model> cache = new HashMap<>();

	/** The lit rest-pose model for a snapshot, built once and shared; null if a part is missing. */
	Model modelFor(GolemSnapshot snapshot)
	{
		Model cached = cache.get(snapshot.getNpcId());
		if (cached != null)
		{
			return cached;
		}

		Model built = build(snapshot);
		if (built != null)
		{
			cache.put(snapshot.getNpcId(), built);
		}
		return built;
	}

	/**
	 * Animation definitions, shared the same way the models are: there are exactly two across the
	 * whole population, and an {@link Animation} is immutable frame data - mutable playback state
	 * lives in each golem's own controller - so one copy of each serves every golem.
	 */
	private final Map<Integer, Animation> animations = new HashMap<>();

	/** The animation for an ID, loaded once. Null for -1, or if the cache lacks it. */
	Animation animationFor(int animationId)
	{
		if (animationId == -1)
		{
			return null;
		}
		// computeIfAbsent is avoided: loadAnimation can return null, which would mean
		// re-asking for a missing animation on every switch.
		if (animations.containsKey(animationId))
		{
			return animations.get(animationId);
		}
		Animation loaded = client.loadAnimation(animationId);
		animations.put(animationId, loaded);
		return loaded;
	}

	/**
	 * True if this animation is built to repeat.
	 *
	 * <p>{@code frameStep} is how many frames the client winds back at a clip's end: positive
	 * loops, -1 runs once. It cannot be guessed from the name - {@code human_climbing} (737) does
	 * not loop, {@code human_climbing_loop} (4435) does. Only a loop may be stretched to fill a
	 * duration; a stretched one-shot restarts partway and drifts.
	 */
	boolean loops(int animationId)
	{
		Animation animation = animationFor(animationId);
		return animation != null && animation.getFrameStep() > 0;
	}

	/**
	 * How long a clip runs for, in client cycles, or 0 if unknown: the sum of its frame lengths,
	 * asked of the client so it stays right if Jagex retimes one. Paces a golem through a
	 * shortcut; guessing had golems scaling a cliff in two thirds of a second.
	 */
	int animationCycles(int animationId)
	{
		Animation animation = animationFor(animationId);
		if (animation == null)
		{
			return 0;
		}

		// Frame lengths, summed, not getDuration(): that is a frame *count*, and reading it as
		// cycles made every clip four or five times shorter - a hop came out at 8 cycles against
		// its real 38. Frame lengths are in client cycles.
		int[] frames = animation.getFrameLengths();
		if (frames == null || frames.length == 0)
		{
			return 0;
		}

		int total = 0;
		for (int length : frames)
		{
			total += length;
		}
		return Math.min(total, MAX_CLIP_CYCLES);
	}

	/**
	 * The longest a clip is allowed to claim to be, in client cycles.
	 *
	 * <p>Some sequences end on a frame held absurdly long, meaning "stay like this until told
	 * otherwise": {@code agilityarena_handholds_middle} reports 20,056 cycles and
	 * {@code agilty_shortcut_enter_hole} 2,060, which taken at face value freeze a golem in the
	 * obstacle for minutes. Twenty ticks is longer than any real traversal.
	 */
	private static final int MAX_CLIP_CYCLES = 600;

	/**
	 * Drops the shared models and animations when the plugin stops, so a disable/enable cycle
	 * does not hand out resources built against a client that has moved on.
	 */
	void clear()
	{
		cache.clear();
		animations.clear();
	}

	/** Builds the rest-pose model a snapshot describes; null if the cache lacks a part. */
	private Model build(GolemSnapshot snapshot)
	{
		try
		{
			int[] ids = snapshot.getModelIds();
			ModelData[] parts = new ModelData[ids.length];
			int found = 0;

			for (int id : ids)
			{
				ModelData part = client.loadModelData(id);
				if (part == null)
				{
					// A missing part would leave a golem with no head; better to fail the
					// whole build and let the real death play out.
					log.debug("Golem model part {} not in cache for npc {}", id, snapshot.getNpcId());
					return null;
				}
				parts[found++] = part;
			}

			if (found == 0)
			{
				return null;
			}

			ModelData merged = client.mergeModels(parts, found);
			if (merged == null)
			{
				return null;
			}

			// Recolour and resize write into the vertex and colour arrays, shared with the
			// cache's copy until cloned. Skipping this repaints every other model in the
			// game that shares the source.
			merged.cloneColors().cloneVertices();

			short[] from = snapshot.getRecolourFrom();
			short[] to = snapshot.getRecolourTo();
			for (int i = 0; i < Math.min(from.length, to.length); i++)
			{
				merged.recolor(from[i], to[i]);
			}

			int width = snapshot.getWidthScale() <= 0 ? UNSCALED : snapshot.getWidthScale();
			int height = snapshot.getHeightScale() <= 0 ? UNSCALED : snapshot.getHeightScale();
			if (width != UNSCALED || height != UNSCALED)
			{
				// Y is the vertical axis, and it is the one the height scale drives.
				merged.scale(width, height, width);
			}

			Model model = merged.light(
				BASE_AMBIENT + GolemContent.GOLEM_AMBIENT,
				BASE_CONTRAST + GolemContent.GOLEM_CONTRAST,
				LIGHT_X, LIGHT_Y, LIGHT_Z);
			if (model == null)
			{
				return null;
			}
			model.calculateBoundsCylinder();
			return model;
		}
		catch (RuntimeException e)
		{
			log.debug("Could not build golem model for npc {}", snapshot.getNpcId(), e);
			return null;
		}
	}
}

package com.golemsdontdie;

import java.awt.*;
import javax.inject.Inject;
import net.runelite.api.*;
import net.runelite.api.Point;
import net.runelite.api.coords.*;
import net.runelite.client.ui.overlay.*;

/**
 * Draws a named golem's name above its head, the way NPC highlighting names an NPC.
 *
 * <p>Only golems actually being drawn, so inside an instance the name follows where the golem
 * is drawn rather than where it is simulated. The name rises with the golem mid-hop.
 */
class GolemNameplateOverlay extends Overlay
{
	/** Space between the top of the golem and the bottom of its name, in height units. */
	private static final int NAME_GAP = 40;

	private final Client client;
	private final GolemsDontDiePlugin plugin;
	private final GolemsDontDieConfig config;

	/** What a golem is called: its own name, or the one the setting gives it. */
	private final GolemNames names;

	@Inject
	GolemNameplateOverlay(Client client, GolemsDontDiePlugin plugin, GolemsDontDieConfig config,
		GolemNames names)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.names = names;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showNameplates())
		{
			return null;
		}
		WorldView wv = client.getTopLevelWorldView();
		if (wv == null)
		{
			return null;
		}

		// Read once for the frame, not through the config proxy for every named golem. The shadow fades
		// with the name: an opaque shadow under a faint name read as a black name.
		Color colour = config.nameplateColour();
		Color shadow = new Color(0, 0, 0, colour.getAlpha());
		for (Golem golem : plugin.drawnGolems())
		{
			String name = names.of(golem);
			FakeGolem drawn = golem.getRenderer();
			if (name == null || name.trim().isEmpty() || drawn == null
				|| !golem.isAboard() && golem.getDrawPlane() != wv.getPlane())
			{
				continue;
			}

			// Where it is drawn, which for a golem aboard the player's ship is on the ship's deck.
			LocalPoint drawnAt = golem.drawnPoint(client);
			if (drawnAt == null)
			{
				continue;
			}

			Point at = Perspective.getCanvasTextLocation(client, graphics, drawnAt, name,
				drawn.getModelHeight() + NAME_GAP + golem.jumpArc() + golem.deckLift());
			if (at != null)
			{
				// Drawn here rather than by OverlayUtil, which makes every name opaque whatever its colour.
				graphics.setColor(shadow);
				graphics.drawString(name, at.getX() + 1, at.getY() + 1);
				graphics.setColor(colour);
				graphics.drawString(name, at.getX(), at.getY());
			}
		}

		pointAtFound(graphics, wv);
		return null;
	}

	/** How far above a golem's head the arrow floats, and how far it bobs. */
	private static final int ARROW_GAP = 80;
	private static final int ARROW_BOB = 6;

	/** How wide and tall the arrow is drawn, in pixels. The game's own is about this size. */
	private static final int ARROW_WIDE = 30;
	private static final int ARROW_TALL = 26;

	/**
	 * Draws an arrow over the golem being looked for.
	 *
	 * <p>Drawn here rather than left to the game's hint arrow, which points at a tile and moves
	 * once a tick: over a walking golem that reads as an arrow trailing along behind it. This one
	 * is drawn at wherever the golem is this frame, which is where the golem looks.
	 */
	private void pointAtFound(Graphics2D graphics, WorldView wv)
	{
		Golem golem = plugin.getFinding();
		FakeGolem drawn = golem == null ? null : golem.getRenderer();
		if (drawn == null || !golem.isAboard() && golem.getDrawPlane() != wv.getPlane())
		{
			return;
		}
		LocalPoint drawnAt = golem.drawnPoint(client);
		if (drawnAt == null)
		{
			return;
		}

		int bob = (int) (Math.sin(System.currentTimeMillis() / 220.0) * ARROW_BOB);
		Point at = Perspective.localToCanvas(client, drawnAt,
			golem.drawnLevel(), drawn.getModelHeight() + ARROW_GAP + golem.jumpArc() + golem.deckLift());
		if (at == null)
		{
			return;
		}

		int x = at.getX();
		int y = at.getY() + bob;
		Polygon arrow = new Polygon(
			new int[]{x - ARROW_WIDE / 2, x + ARROW_WIDE / 2, x},
			new int[]{y - ARROW_TALL, y - ARROW_TALL, y}, 3);
		graphics.setColor(Color.BLACK);
		graphics.setStroke(new BasicStroke(4f));
		graphics.drawPolygon(arrow);
		graphics.setColor(ARROW_COLOUR);
		graphics.fillPolygon(arrow);
	}

	/** The game's own hint arrow yellow. */
	private static final Color ARROW_COLOUR = new Color(0xFFE700);
}

package com.golemsdontdie;

import java.io.*;
import java.nio.charset.*;
import java.util.*;
import java.util.zip.*;
import javax.inject.*;
import lombok.*;
import lombok.extern.slf4j.*;

/**
 * What to call a golem the player has not named: one of the names of Gielinor, and a surname off
 * the rocks - Akrisae Flint, Doris Millstone, Veos Greystone - or, in the ordinal style, the order
 * it was crafted in, in Latin: Primus, Vicesimus Septimus, Bis Millesimus Quingentesimus.
 *
 * <p>No name is written down. It is worked out from the golem's own number, and the older golems'
 * where two would share one, or its craft number for an ordinal, so the same golem is always
 * called the same thing, no two unnamed golems answer to the same name, four hundred golems cost
 * nothing to name, and turning the setting off leaves nothing behind. A name the player types is a name; this is only what the
 * plugin calls a golem until then, and it gives way the moment one is typed.
 *
 * <p>Shown wherever a golem's name is: the list, its page, the map, its nameplate and its menu
 * entries. Turning auto naming off leaves only the names a player typed, and the rest go back to
 * being golems.
 */
@Slf4j
@Singleton
class GolemNames
{
	private static final String FILE = "/names.gz";

	/**
	 * The ordinals, one to a line: 1 to 999 each spelled out, then each thousand to fifty thousand,
	 * then "Last", for anything past the end of the list. Contributed by Hjaldr in issue 2, to ten
	 * thousand; the thousands past that follow the same pattern.
	 */
	private static final String ORDINALS = "/ordinals.txt";

	/** Place in a thousand, 1 to 999, spelled out; index 0 unused. */
	private final String[] ordinals = new String[1000];

	/** Each thousand, 1 to 50, as the words before the rest; index 0 unused. */
	private final String[] thousands = new String[51];

	/** For a golem numbered past the end of the list. */
	private String last;

	/**
	 * Surnames, all of them something a rock is or is made of. The first names do the work of
	 * telling golems apart; these do the work of making them golems.
	 */
	private static final String[] ROCKS = ("Pebble Boulder Granite Flint Slate Marble Gravel Quartz Basalt "
		+ "Cobble Shale Chalk Clay Grit Rubble Cairn Crag Scree Moss Lime Ochre Onyx Jasper Opal Amber "
		+ "Obsidian Pumice Sable Tuff Geode Mica Schist Gneiss Flagstone Kerb Cinder Ash Ember Soot Dolomite "
		+ "Lode Seam Quarry Millstone Keystone Cobblestone Bedrock Gritstone Whetstone Ironstone Limestone "
		+ "Sandstone Greystone Blackstone Brownstone Fieldstone Riverstone Rubblehead Stonewall Chippings "
		+ "Boulderfoot Flintlock Gravelly Marblewell Slatebottom Quarryman").split(" ");

	@Inject
	private GolemsDontDieConfig config;

	/** The people of Gielinor, harvested offline from the cache; null where one is struck out. */
	@Getter
	private String[] gielinor = new String[0];

	/**
	 * Each unnamed golem's name as of the last {@link #assign}, by id. Replaced whole rather than
	 * changed, as the panel reads it from the Swing thread while the client thread assigns.
	 */
	private volatile Map<Long, String> assigned = Collections.emptyMap();

	/**
	 * How many further names a golem tries before settling for a name it shares. A roster of fifty
	 * thousand fills well over half the names there are, and the last golem made still finds a free
	 * one within a few tries; this is only so a roster larger than the names can never hang.
	 */
	private static final int MOST_TRIES = 64;

	/** Reads the harvested names. Called once at start-up, beside the other data files. */
	void load()
	{
		try (InputStream in = GolemNames.class.getResourceAsStream(FILE))
		{
			if (in == null)
			{
				log.warn("No names on the classpath; golems will go unnamed");
				// The ordinals are their own file, and need not go with them.
				loadOrdinals();
				return;
			}
			List<String> names = new ArrayList<>();
			try (BufferedReader reader = new BufferedReader(
				new InputStreamReader(new GZIPInputStream(in), StandardCharsets.UTF_8)))
			{
				for (String line = reader.readLine(); line != null; line = reader.readLine())
				{
					String name = line.trim();
					if (!name.isEmpty())
					{
						// A line struck out with # is a job or a creature rather than a name. It keeps
						// its place, empty, so the names after it do not move: taken out, every golem
						// the plugin had named would have come back called something else.
						names.add(name.startsWith("#") ? null : name);
					}
				}
			}
			gielinor = names.toArray(new String[0]);
			log.debug("Loaded {} names", gielinor.length);
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Names unreadable", e);
		}
		loadOrdinals();
	}

	private void loadOrdinals()
	{
		try (InputStream in = GolemNames.class.getResourceAsStream(ORDINALS))
		{
			if (in == null)
			{
				log.warn("No ordinals on the classpath; ordinal names are off");
				return;
			}
			try (BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
			{
				for (String line = reader.readLine(); line != null; line = reader.readLine())
				{
					int split = line.indexOf(';');
					if (line.startsWith("#") || split < 0)
					{
						continue;
					}
					String key = line.substring(0, split).trim();
					String name = line.substring(split + 1).trim();
					if (key.equals("Last"))
					{
						last = name;
						continue;
					}
					int n = Integer.parseInt(key);
					if (n < 1000)
					{
						ordinals[n] = name;
					}
					else if (n % 1000 == 0 && n / 1000 < thousands.length)
					{
						thousands[n / 1000] = name;
					}
				}
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Ordinals unreadable", e);
		}
	}

	/**
	 * What to call this golem: the name the player gave it, the one the setting gives it, or null
	 * if it has neither. What a nameplate says, and what the right-click menu calls it.
	 */
	String of(Golem golem)
	{
		if (golem == null)
		{
			return null;
		}
		String nickname = golem.getNickname();
		return nickname != null && !nickname.isEmpty() ? nickname : suggested(golem);
	}

	/**
	 * What to call this golem, or null if the player has named it or the setting is off.
	 *
	 * <p>Cheap enough to ask every time a row is drawn: one map lookup, the work being done in
	 * {@link #assign} when the roster changes.
	 */
	String suggested(Golem golem)
	{
		if (golem == null || golem.getNickname() != null && !golem.getNickname().isEmpty()
			|| config != null && !config.autoName())
		{
			return null;
		}
		if (config != null && config.nameStyle() == GolemsDontDieConfig.NameStyle.ORDINAL)
		{
			return ordinal(golem.getCraftNumber());
		}
		// A golem made since the last assignment has not been checked against the others yet, and
		// goes by its own name until it is.
		String name = assigned.get(golem.getId());
		return name != null ? name : nameFor(golem.getId());
	}

	/**
	 * Settles who answers to what, so no two unnamed golems in the roster share a name. Called on
	 * the client thread whenever the roster changes or a golem is named, never per frame.
	 *
	 * <p>Oldest first, by craft number, each golem takes the first name its own number gives it that
	 * nobody older has taken, so a name two golems would share stays with the older and the newer
	 * moves on to its next. Nothing is written down: the same roster always comes out the same, and
	 * a golem made later never changes the name of one made before it. A golem the player has named
	 * holds no name here, and one that went without because of it takes it back.
	 *
	 * @return whether any golem already assigned a name now has a different one
	 */
	boolean assign(List<Golem> roster)
	{
		if (gielinor.length == 0)
		{
			return false;
		}
		List<Golem> unnamed = new ArrayList<>(roster.size());
		for (Golem golem : roster)
		{
			if (golem.getNickname() == null || golem.getNickname().isEmpty())
			{
				unnamed.add(golem);
			}
		}
		// Not yet numbered counts as newest: it is a golem restored or made a moment ago.
		unnamed.sort(Comparator.comparingInt((Golem golem) ->
				golem.getCraftNumber() > 0 ? golem.getCraftNumber() : Integer.MAX_VALUE)
			.thenComparingLong(Golem::getId));

		Map<Long, String> before = assigned;
		Map<Long, String> after = new HashMap<>(unnamed.size() * 2);
		Set<String> taken = new HashSet<>(unnamed.size() * 2);
		boolean changed = false;
		for (Golem golem : unnamed)
		{
			Random random = generator(golem.getId());
			String name = draw(random);
			for (int tries = 0; taken.contains(name) && tries < MOST_TRIES; tries++)
			{
				name = draw(random);
			}
			taken.add(name);
			after.put(golem.getId(), name);
			String was = before.get(golem.getId());
			changed |= was != null && !was.equals(name);
		}
		assigned = after;
		return changed;
	}

	/**
	 * The Latin ordinal of a craft number: 27 is Vicesimus Septimus, 2596 Bis Millesimus
	 * Quingentesimus Nonagesimus Sextus. Past the thousands the list has, the last. Null for a golem
	 * not numbered yet, which is one not yet restored.
	 */
	String ordinal(int n)
	{
		if (n <= 0)
		{
			return null;
		}
		if (n < 1000)
		{
			return ordinals[n];
		}
		int thousand = n / 1000;
		int rest = n % 1000;
		if (thousand >= thousands.length || thousands[thousand] == null)
		{
			return last;
		}
		return rest == 0 ? thousands[thousand] : thousands[thousand] + " " + ordinals[rest];
	}

	/**
	 * The name a golem's own number gives it, or null if there are no names to give. The first of
	 * the names that number gives, and the one it goes by unless an older golem has it: see assign.
	 */
	String nameFor(long id)
	{
		return gielinor.length == 0 ? null : draw(generator(id));
	}

	/**
	 * Its own generator, so asking a golem its name never disturbs where it walks or what it is
	 * like: those come out of generators of their own. See GolemTrait.of.
	 */
	private static Random generator(long id)
	{
		return new Random(id * 0x9E3779B97F4A7C15L ^ 0x27D4EB2F165667C5L);
	}

	/** The next name out of a golem's generator, drawing again past a struck-out one. */
	private String draw(Random random)
	{
		String first = gielinor[random.nextInt(gielinor.length)];
		while (first == null)
		{
			first = gielinor[random.nextInt(gielinor.length)];
		}
		return first + " " + ROCKS[random.nextInt(ROCKS.length)];
	}
}

package com.golemsdontdie;

import java.awt.*;
import java.awt.event.*;
import java.awt.image.*;
import java.text.*;
import java.util.*;
import java.util.List;
import java.util.function.*;
import javax.swing.*;
import net.runelite.client.ui.*;
import net.runelite.client.util.*;

/**
 * One golem's own page: what it is called, where it is, and what it is like.
 *
 * <p>A window rather than another sidebar page. A player reading about one golem wants the list
 * still beside it, and a trait and its line do not fit in 225 pixels.
 *
 * <p>Swing thread throughout, and the golem it holds is only ever read: its name and traits, and a
 * whereabouts line the plugin works out on the client thread and hands over. One window, reused -
 * opening a second golem's page replaces what is in it, rather than filling the desktop with
 * windows a player then has to close.
 */
class GolemPage
{
	private static final Font TITLE = FontManager.getRunescapeBoldFont().deriveFont(20f);
	private static final Font BODY = FontManager.getRunescapeFont().deriveFont(16f);

	/**
	 * The page's window, made the first time it is opened. A dialog owned by the client's own window,
	 * so it stays above the client without being put above everything else on the screen, and goes
	 * where the client goes.
	 */
	private JDialog frame;

	/** What the window shows, built once. */
	private final JPanel body = new JPanel(new BorderLayout());
	private final JLabel title = new JLabel();
	private final JLabel place = new JLabel();
	private final JPanel traits = traitList();

	/** Where the golem has been lately, one line each, newest first. */
	private final JPanel journal = new JPanel();
	private final JButton find = new JButton("Find");

	/** The golem the plugin is pointing at, if any: its page's button stops rather than starts. */
	private Golem finding;

	/** The scrolling part, so a page opened on another golem starts at the top of it. */
	private final JScrollPane scroll;

	/** The journal's own scrolling part, and the tabs the two of them sit in. */
	private final JScrollPane travels;
	private final JTabbedPane tabs = new JTabbedPane();

	/** The golem's own picture, in its frame. Empty until the client thread has drawn one. */
	private final JLabel picture = new JLabel();

	/** What the golem has done, filled in beside the picture. */
	private final JPanel record = new JPanel();

	/** Points the arrow at the golem, on the client thread. */
	private final Consumer<Golem> onFind;

	/** What to call a golem nobody has named; see GolemNames. */
	private final GolemNames names;

	/** Names the regions the journal is a list of. */
	private final PlaceNames places;

	/**
	 * The golem the page is showing, or null when it has never been opened. Set on the Swing
	 * thread and read on the client thread, which works out where the golem is.
	 */
	private volatile Golem showing;

	GolemPage(Consumer<Golem> onFind, GolemNames names, PlaceNames places)
	{
		this.onFind = onFind;
		this.names = names;
		this.places = places;

		title.setFont(TITLE);
		title.setForeground(Color.WHITE);
		place.setFont(BODY);
		place.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		// The picture in a frame, as a picture should be: a dark mount and a line around it.
		picture.setPreferredSize(new Dimension(GolemPortrait.WIDTH, GolemPortrait.HEIGHT));
		picture.setHorizontalAlignment(JLabel.CENTER);
		picture.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		picture.setOpaque(true);
		JPanel framed = new JPanel(new BorderLayout());
		framed.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		framed.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR),
			BorderFactory.createEmptyBorder(3, 3, 3, 3)));
		framed.add(picture, BorderLayout.CENTER);
		JPanel mount = new JPanel(new BorderLayout());
		mount.setBackground(ColorScheme.DARK_GRAY_COLOR);
		mount.add(framed, BorderLayout.NORTH);

		record.setLayout(new BoxLayout(record, BoxLayout.Y_AXIS));
		record.setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel words = new JPanel();
		words.setLayout(new BoxLayout(words, BoxLayout.Y_AXIS));
		words.setBackground(ColorScheme.DARK_GRAY_COLOR);
		words.setBorder(BorderFactory.createEmptyBorder(0, 10, 0, 0));
		title.setAlignmentX(Component.LEFT_ALIGNMENT);
		place.setAlignmentX(Component.LEFT_ALIGNMENT);
		record.setAlignmentX(Component.LEFT_ALIGNMENT);
		words.add(title);
		words.add(Box.createVerticalStrut(4));
		words.add(place);
		words.add(Box.createVerticalStrut(10));
		words.add(record);

		JPanel heading = new JPanel(new BorderLayout());
		heading.setBackground(ColorScheme.DARK_GRAY_COLOR);
		heading.setBorder(BorderFactory.createEmptyBorder(10, 12, 10, 12));
		heading.add(mount, BorderLayout.WEST);
		heading.add(words, BorderLayout.CENTER);

		// The traits are pinned to the top of a panel of their own. In the scroll pane directly,
		// the list is given the whole height of the window and shares the slack out between the
		// traits, which put half a window between two of them.
		JPanel pinned = new JPanel(new BorderLayout())
		{
			@Override
			public Dimension getMaximumSize()
			{
				return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
			}
		};
		pinned.setBackground(ColorScheme.DARK_GRAY_COLOR);
		pinned.add(traits, BorderLayout.NORTH);

		// Both tabs as tall as five traits, whatever is in them: the window is the same height for
		// every golem, where it had grown to the longest journal it had been shown and stayed there.
		int tabHeight = fullTraitsHeight();
		scroll = new FixedHeight(pinned, tabHeight);
		scroll.setBorder(BorderFactory.createEmptyBorder());
		// Never sideways: the lines wrap to the window, so there is nothing off to the right.
		scroll.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		scroll.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);

		journal.setLayout(new BoxLayout(journal, BoxLayout.Y_AXIS));
		journal.setBackground(ColorScheme.DARK_GRAY_COLOR);
		journal.setBorder(BorderFactory.createEmptyBorder(8, 12, 10, 12));
		JPanel journalPinned = new JPanel(new BorderLayout());
		journalPinned.setBackground(ColorScheme.DARK_GRAY_COLOR);
		journalPinned.add(journal, BorderLayout.NORTH);
		travels = new FixedHeight(journalPinned, tabHeight);
		travels.setBorder(BorderFactory.createEmptyBorder());
		travels.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		travels.getVerticalScrollBar().setUnitIncrement(16);
		travels.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);

		// One row of tabs whatever the width: wrapping, the tabs asked for a second row when measured
		// before the window had a width, and the first page opened came out a row taller.
		tabs.setTabLayoutPolicy(JTabbedPane.SCROLL_TAB_LAYOUT);
		tabs.setFont(BODY);
		tabs.setBackground(ColorScheme.DARK_GRAY_COLOR);
		tabs.setForeground(Color.WHITE);
		tabs.addTab("Traits", scroll);
		tabs.addTab("Journal", travels);

		find.setFont(BODY);
		find.setFocusPainted(false);
		find.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		find.setForeground(Color.WHITE);
		find.setToolTipText("Point at this golem until you reach it");
		find.addActionListener(e ->
		{
			if (showing != null)
			{
				onFind.accept(showing);
			}
		});
		JButton close = new JButton("Close");
		close.setFont(BODY);
		close.setFocusPainted(false);
		close.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		close.setForeground(Color.WHITE);
		close.addActionListener(e -> hide());

		JPanel buttons = new JPanel(new BorderLayout(6, 0));
		buttons.setBackground(ColorScheme.DARK_GRAY_COLOR);
		buttons.setBorder(BorderFactory.createEmptyBorder(0, 12, 12, 12));
		buttons.add(find, BorderLayout.CENTER);
		buttons.add(close, BorderLayout.EAST);

		body.setBackground(ColorScheme.DARK_GRAY_COLOR);
		body.add(heading, BorderLayout.NORTH);
		body.add(tabs, BorderLayout.CENTER);
		body.add(buttons, BorderLayout.SOUTH);

	}

	/**
	 * Makes the page's window, owned by the client's: the window the sidebar is in, or failing that
	 * the client's own frame.
	 */
	private JDialog window(Component beside)
	{
		Window owner = beside == null ? null : SwingUtilities.getWindowAncestor(beside);
		if (owner == null)
		{
			for (Frame open : Frame.getFrames())
			{
				if (open.isVisible())
				{
					owner = open;
					break;
				}
			}
		}
		JDialog window = new JDialog(owner, "Golem Info");

		// The client's own chrome, the way the client asks for it: undecorated, and the root pane
		// told to draw a frame. Asking the look and feel first whether it supports decorations
		// said no and left the page in the desktop's chrome.
		try
		{
			window.setUndecorated(true);
			window.getRootPane().setWindowDecorationStyle(JRootPane.FRAME);
		}
		catch (RuntimeException e)
		{
			// A look and feel that will not draw a frame leaves us with the desktop's, which is
			// not what we wanted but is a window a player can still move and close.
			window.dispose();
			window.setUndecorated(false);
		}
		BufferedImage icon = ImageUtil.loadImageResource(
			GolemPage.class, "/golem-icon.png");
		if (icon != null)
		{
			window.setIconImage(icon);
		}

		window.setContentPane(body);
		window.setMinimumSize(new Dimension(320, 260));
		window.setSize(new Dimension(380, 420));
		// Closing the window keeps the golem: a page is a thing a player glances at and dismisses.
		window.setDefaultCloseOperation(WindowConstants.DO_NOTHING_ON_CLOSE);
		window.addWindowListener(new WindowAdapter()
		{
			@Override
			public void windowClosing(WindowEvent e)
			{
				hide();
			}
		});
		return window;
	}

	/** Puts the page away, keeping it for next time. */
	private void hide()
	{
		if (frame != null)
		{
			frame.setVisible(false);
		}
	}

	/** Opens the page on a golem, or turns it to that golem if it is already open. */
	void show(Golem golem, Component beside)
	{
		showing = golem;
		// Named once the client thread has had a look, a frame from now; until then, nothing, and
		// certainly not the last golem's.
		furthest = null;
		title.setText(nameOf(golem));
		place.setText(" ");
		find.setEnabled(true);
		labelFind();
		picture.setIcon(null);
		listRecord(golem);
		listTraits(golem);
		listTravels(golem);
		// Every page opens on the golem itself; the journal is there for whoever wants it.
		tabs.setSelectedIndex(0);
		// From the top: the page a player left scrolled halfway is not where the next one starts.
		SwingUtilities.invokeLater(() -> scroll.getViewport().setViewPosition(new java.awt.Point(0, 0)));

		if (frame == null)
		{
			frame = window(beside);
		}
		fitHeight();
		if (!frame.isVisible())
		{
			frame.setLocationRelativeTo(frame.getOwner());
		}
		frame.setVisible(true);
	}

	/** The golem's own name, the one auto naming gives it, or failing both that it has none. */
	private String nameOf(Golem golem)
	{
		String suggested = names == null ? null : names.suggested(golem);
		return golem.getNickname() != null ? golem.getNickname()
			: suggested != null ? suggested : "Unnamed golem";
	}

	/**
	 * Names the golem again at the top of the page, if it is the one showing. The title is otherwise
	 * only set on opening, and a golem renamed from the sidebar or the game, or given another name by
	 * a change of name style, kept its old one here until the page was opened again. Safe from any
	 * thread: the title is put right on Swing's.
	 */
	void renamed(Golem golem)
	{
		SwingUtilities.invokeLater(() ->
		{
			if (golem != null && golem == showing)
			{
				title.setText(nameOf(golem));
			}
		});
	}

	/**
	 * Makes the window tall enough for a golem with every trait it could have, as far as the screen
	 * allows, and the same height for every golem. The tabs ask for that height whatever is in them,
	 * and the record for its longest, so this does not change from one golem to the next.
	 */
	private void fitHeight()
	{
		body.revalidate();
		java.awt.Insets edges = frame.getInsets();
		int wanted = Math.min(body.getPreferredSize().height + edges.top + edges.bottom, usableHeight());
		if (wanted != frame.getHeight())
		{
			frame.setSize(frame.getWidth(), wanted);
		}
	}

	/** A scroll pane that asks for the same height whatever it holds. */
	private static final class FixedHeight extends JScrollPane
	{
		private final int height;

		FixedHeight(Component view, int height)
		{
			super(view);
			this.height = height;
		}

		@Override
		public Dimension getPreferredSize()
		{
			return new Dimension(super.getPreferredSize().width, height);
		}
	}

	/** The panel the traits are listed in, the page's own or one only measured. */
	private static JPanel traitList()
	{
		JPanel list = new JPanel();
		list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
		list.setBackground(ColorScheme.DARK_GRAY_COLOR);
		list.setBorder(BorderFactory.createEmptyBorder(8, 12, 10, 12));
		return list;
	}

	/**
	 * How tall the traits tab is with as many traits as a golem can have, a line apiece, and a
	 * little over: laid out and measured, so it is the page's own fonts and spacing that decide it.
	 */
	private static int fullTraitsHeight()
	{
		JPanel sample = traitList();
		GolemTrait[] all = GolemTrait.values();
		fillTraits(sample, java.util.Arrays.asList(all).subList(0, Math.min(GolemTrait.MOST_TRAITS, all.length)), false);
		// With room for a couple of lines to wrap: exactly five, one line apiece, was a window that
		// looked a touch short, and any trait that wrapped at a narrower width tipped it into a scroll.
		int line = sample.getFontMetrics(FontManager.getRunescapeSmallFont()).getHeight();
		return sample.getPreferredSize().height + WRAP_ROOM_LINES * line;
	}

	/** Lines of room the traits tab keeps beyond five traits, for ones that wrap. */
	private static final int WRAP_ROOM_LINES = 2;

	private int usableHeight()
	{
		java.awt.GraphicsConfiguration screen = frame.getGraphicsConfiguration();
		if (screen == null)
		{
			return 700;
		}
		java.awt.Insets taskbar = java.awt.Toolkit.getDefaultToolkit().getScreenInsets(screen);
		return screen.getBounds().height - taskbar.top - taskbar.bottom - 40;
	}

	/** Tells the page which golem is being found, so its button reads Find or Stop finding. */
	void setFinding(Golem target)
	{
		finding = target;
		labelFind();
	}

	private void labelFind()
	{
		boolean stopping = finding != null && finding == showing;
		find.setText(stopping ? "Stop finding" : "Find");
		find.setToolTipText(stopping ? "Stop pointing at this golem" : "Point at this golem until you reach it");
	}

	/** Whether the page is open, so the plugin only works out a whereabouts line when it is. */
	boolean isOpen()
	{
		return frame != null && frame.isVisible();
	}

	Golem getShowing()
	{
		return showing;
	}

	/**
	 * Hangs the golem's picture, drawn on the client thread after the page was opened.
	 *
	 * @param of the golem it is of, ignored if the page has moved on to another
	 */
	void showPicture(Golem of, BufferedImage drawn)
	{
		if (of == showing && drawn != null)
		{
			picture.setIcon(new ImageIcon(drawn));
		}
	}

	/**
	 * The line under the name: where the golem is, or that it is gone.
	 *
	 * @param of the golem the place was worked out for: ignored if the page has moved on to another,
	 *           as a late picture is
	 */
	void showPlace(Golem of, String where, boolean living)
	{
		if (of != showing)
		{
			return;
		}
		place.setText(where == null || where.isEmpty() ? " " : where);
		find.setEnabled(living);
	}

	/** Puts the page away and lets the window go, when the plugin stops. */
	void close()
	{
		showing = null;
		if (frame != null)
		{
			frame.setVisible(false);
			frame.dispose();
			frame = null;
		}
	}

	/** What the golem has done, in the plainest words the numbers allow. */
	private void listRecord(Golem golem)
	{
		record.removeAll();
		GolemHistory history = golem.getHistory();

		if (history.getFirstSeen() > 0)
		{
			line(record, "Alive since " + DAY.format(new Date(history.getFirstSeen())));
		}
		line(record, "Walked about " + NUMBERS.format(history.getWalked()) + " tiles");
		line(record, history.getTransports() == 1 ? "Used one shortcut"
			: "Used " + NUMBERS.format(history.getTransports()) + " shortcuts");
		if (history.getVoyages() > 0)
		{
			line(record, history.getVoyages() == 1 ? "Sailed once"
				: "Sailed " + NUMBERS.format(history.getVoyages()) + " times");
		}
		if (history.getFurthest() > 0)
		{
			String where = furthest == null ? "" : " (" + furthest + ")";
			line(record, "Been " + NUMBERS.format(history.getFurthest()) + " tiles from home" + where);
		}
		// Blank lines to the most the record can have, so every golem's heading is the same height.
		while (record.getComponentCount() < RECORD_LINES)
		{
			line(record, " ");
		}
		record.revalidate();
		record.repaint();
	}

	/** The most lines the record can have: alive since, walked, shortcuts, sailed, furthest. */
	private static final int RECORD_LINES = 5;

	/** One line of the record. */
	private static void line(JPanel into, String text)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		into.add(label);
	}

	/** What to call the furthest place the golem has been, or null if nothing knows. */
	private String furthest;

	/**
	 * The furthest place the golem has been, told after the page is up because naming a place is
	 * the client thread's business.
	 *
	 * @param of the golem the place was worked out for: ignored if the page has moved on to another,
	 *           the way {@link #showPicture} ignores a late picture
	 */
	void setFurthest(Golem of, String place)
	{
		if (of == null || of != showing)
		{
			return;
		}
		furthest = place;
		listRecord(showing);
	}

	private static final NumberFormat NUMBERS = NumberFormat.getIntegerInstance();

	private static final SimpleDateFormat DAY = new SimpleDateFormat("d MMM yyyy");

	/**
	 * Where the golem has been lately: the last twenty places it arrived in, newest first, each
	 * with how it got there.
	 *
	 * <p>The regions are named here rather than as they happen - the same names serve
	 * every golem that has been to the same places, and a golem that is never looked at should
	 * cost nothing but twenty numbers.
	 */
	private void listTravels(Golem golem)
	{
		journal.removeAll();
		int[][] entries = golem.getHistory().travels();
		int named = 0;
		for (int[] entry : entries)
		{
			int region = entry[0];
			named += places != null
				&& places.nameFor((region >> 8) * 64 + 32, (region & 0xff) * 64 + 32, entry[1]) != null ? 1 : 0;
		}
		if (named == 0)
		{
			JLabel nothing = new JLabel("Nowhere yet.");
			nothing.setFont(BODY);
			nothing.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			nothing.setAlignmentX(Component.LEFT_ALIGNMENT);
			journal.add(nothing);
			journal.revalidate();
			journal.repaint();
			return;
		}

		JLabel order = new JLabel("Newest first");
		order.setFont(FontManager.getRunescapeSmallFont());
		order.setForeground(ColorScheme.LIGHT_GRAY_COLOR.darker());
		order.setAlignmentX(Component.LEFT_ALIGNMENT);
		order.setBorder(BorderFactory.createEmptyBorder(0, 0, 6, 0));
		journal.add(order);

		int now = (int) (System.currentTimeMillis() / 60_000L);
		for (int[] entry : entries)
		{
			int region = entry[0];
			int plane = entry[1];
			// The middle of the region, which is what names it.
			int x = (region >> 8) * 64 + 32;
			int y = (region & 0xff) * 64 + 32;
			String place = places == null ? null : places.nameFor(x, y, plane);
			if (place == null)
			{
				// Country with no name on it. A journal of "somewhere unmapped" says nothing
				// about where a golem has been, so the entry is passed over rather than written.
				continue;
			}

			JTextArea line = new JTextArea(GolemTravel.byOrdinal(entry[2]).line(place));
			line.setFont(BODY);
			line.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			line.setBackground(ColorScheme.DARK_GRAY_COLOR);
			line.setLineWrap(true);
			line.setWrapStyleWord(true);
			line.setEditable(false);
			line.setFocusable(false);
			line.setAlignmentX(Component.LEFT_ALIGNMENT);
			line.setBorder(BorderFactory.createEmptyBorder(0, 0, 4, 0));

			// A panel apiece, as the traits are: a list of text areas given the window's height
			// shares the slack out between them and leaves gaps.
			JPanel row = new JPanel(new BorderLayout())
			{
				@Override
				public Dimension getMaximumSize()
				{
					return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
				}
			};
			row.setBackground(ColorScheme.DARK_GRAY_COLOR);
			row.setAlignmentX(Component.LEFT_ALIGNMENT);
			row.add(line, BorderLayout.CENTER);
			JLabel ago = new JLabel(ago(now - entry[3]));
			ago.setFont(FontManager.getRunescapeSmallFont());
			ago.setForeground(ColorScheme.LIGHT_GRAY_COLOR.darker());
			ago.setVerticalAlignment(JLabel.TOP);
			ago.setBorder(BorderFactory.createEmptyBorder(2, 8, 0, 0));
			row.add(ago, BorderLayout.EAST);
			journal.add(row);
		}
		journal.revalidate();
		journal.repaint();
	}

	/** How long ago, for a journal entry, from minutes. */
	private static String ago(int minutes)
	{
		if (minutes < 1)
		{
			return "just now";
		}
		if (minutes < 60)
		{
			return minutes + "m ago";
		}
		if (minutes < 60 * 24)
		{
			return minutes / 60 + "h ago";
		}
		return minutes / (60 * 24) + "d ago";
	}

	private void listTraits(Golem golem)
	{
		fillTraits(traits, GolemTrait.list(golem.getTraits()), true);
	}

	/** Lists traits into a panel: a heading, then each trait's name over its line. */
	private static void fillTraits(JPanel into, List<GolemTrait> list, boolean wrap)
	{
		into.removeAll();
		JLabel heading = new JLabel("Traits");
		heading.setFont(FontManager.getRunescapeBoldFont().deriveFont(16f));
		heading.setForeground(Color.WHITE);
		heading.setAlignmentX(Component.LEFT_ALIGNMENT);
		heading.setBorder(BorderFactory.createEmptyBorder(0, 0, 6, 0));
		into.add(heading);

		for (GolemTrait trait : list)
		{
			JLabel label = new JLabel(trait.getLabel());
			label.setFont(BODY);
			label.setForeground(ColorScheme.BRAND_ORANGE);

			// A text area rather than a label, for the wrapping: a trait's line is a sentence, the
			// window is narrow, and it is resizable, so the width to wrap at is not ours to pick.
			JTextArea line = new JTextArea(trait.getDescription());
			line.setFont(FontManager.getRunescapeSmallFont());
			line.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			line.setBackground(ColorScheme.DARK_GRAY_COLOR);
			// Measured unwrapped: a wrapping text area not yet given a width has no height to go by.
			line.setLineWrap(wrap);
			line.setWrapStyleWord(true);
			line.setEditable(false);
			line.setFocusable(false);

			// Each trait in a panel of its own, so the list cannot stretch the text areas to fill
			// the window: a page with two traits on it had half a window between them.
			JPanel one = new JPanel(new BorderLayout());
			one.setBackground(ColorScheme.DARK_GRAY_COLOR);
			one.setBorder(BorderFactory.createEmptyBorder(0, 0, 8, 0));
			one.setAlignmentX(Component.LEFT_ALIGNMENT);
			one.add(label, BorderLayout.NORTH);
			one.add(line, BorderLayout.CENTER);
			into.add(one);
		}
		into.revalidate();
		into.repaint();
	}

}

package com.golemsdontdie;

import java.util.*;
import javax.inject.*;

/**
 * Picks somewhere for a golem to go, and works out how to walk there.
 *
 * <p>Everything is in world tiles, queried against {@link IslandMemory}, so a search works the
 * same whether the golem is on screen or three regions away: pathing cannot depend on the scene.
 * Paths are breadth-first over cardinal steps - distances are short, and BFS is exhaustive within
 * its budget, so a golem penned in by scenery finds out it is stuck rather than walking into it.
 */
@Singleton
class GolemPathfinder
{
	/** Ceiling on tiles per search. Reached when a golem is walled in, which recurs every plan. */
	private static final int NODE_BUDGET = 3000;

	/** Tries for a reachable destination before the golem gives up and idles. */
	private static final int DESTINATION_ATTEMPTS = 10;

	/**
	 * The eight steps a golem may take, cardinals first.
	 *
	 * <p>Uniform-cost BFS over eight neighbours is exact for this game: a diagonal step costs one
	 * game tick exactly as a cardinal does. Cardinals come first so that where two routes are the
	 * same length the straight one wins; whether a diagonal is legal is canStep's corner rule.
	 */
	private static final int[] DX = {1, -1, 0, 0, 1, -1, 1, -1};
	private static final int[] DY = {0, 0, 1, -1, 1, 1, -1, -1};

	@Inject
	private IslandMemory memory;

	/**
	 * A path to a random reachable destination inside {@code bounds}. Destinations are sampled and
	 * rejected rather than enumerated, which would bias the choice toward the densest part.
	 *
	 * @return world tiles to walk through, excluding the start; empty if nowhere goes
	 */
	Deque<int[]> wanderPath(int startX, int startY, int plane, RoamBounds bounds, Random random)
	{
		// Attempts are spent on searches, not on samples: a sample landing on a wall costs nothing to
		// reject, and counting it meant a golem in the cathedral, where most of the window is walls,
		// ran out of tries before it had searched once.
		int searched = 0;
		for (int sampled = 0; sampled < DESTINATION_ATTEMPTS * 8 && searched < DESTINATION_ATTEMPTS; sampled++)
		{
			int[] target = bounds.sample(random);
			if (target == null || (target[0] == startX && target[1] == startY))
			{
				continue;
			}
			if (!bounds.contains(target[0], target[1]) || !memory.isKnownWalkable(target[0], target[1], plane)
				|| bounds.avoids(target[0], target[1]))
			{
				continue;
			}
			searched++;

			Deque<int[]> path = findPath(startX, startY, plane, target[0], target[1], bounds);
			if (!path.isEmpty())
			{
				return path;
			}
		}
		return smallFloorPath(startX, startY, plane, bounds, random);
	}

	/** The most tiles a floor may have for its every tile to be worth listing when sampling misses. */
	private static final int SMALL_FLOOR = 200;

	/**
	 * A walk to somewhere on the floor the golem is standing on, chosen from the tiles it can
	 * actually reach. Sampling the window around a golem on a lookout of a dozen tiles mostly lands
	 * on walls, on other floors it cannot reach, and on tiles golems are standing on: every search
	 * failed, and after a dozen the watchdog carried the golem off to the plinth. Only when
	 * sampling has found nothing, so open ground keeps its unbiased choice.
	 */
	private Deque<int[]> smallFloorPath(int startX, int startY, int plane, RoamBounds bounds, Random random)
	{
		TileMap reach = flood(startX, startY, plane, SMALL_FLOOR);
		for (int tries = 0; tries < 8 && reach.size() > 1; tries++)
		{
			long pick = reach.keyAt(1 + random.nextInt(reach.size() - 1));
			int x = unpackX(pick);
			int y = unpackY(pick);
			if (bounds.contains(x, y) && !bounds.avoids(x, y))
			{
				return pathFrom(reach, startX, startY, x, y);
			}
		}
		return new ArrayDeque<>();
	}

	/**
	 * Breadth-first path between two world tiles, staying inside {@code bounds}.
	 *
	 * @return the tiles to walk through, excluding the start; empty if unreachable
	 */
	Deque<int[]> findPath(int startX, int startY, int plane, int goalX, int goalY, RoamBounds bounds)
	{
		Deque<int[]> result = new ArrayDeque<>();
		if (startX == goalX && startY == goalY)
		{
			return result;
		}

		// Keyed by packed world tile rather than indexed by scene position: in free roam there is no
		// fixed-size grid to index into. Every tile reached is queued exactly when it is recorded, so
		// the record's own order is the queue.
		TileMap cameFrom = new TileMap(1024);
		int head = 0;

		long start = pack(startX, startY);
		long goal = pack(goalX, goalY);
		cameFrom.add(start, start);

		int visited = 0;
		boolean found = false;

		while (head < cameFrom.size() && visited < NODE_BUDGET)
		{
			long current = cameFrom.keyAt(head++);
			visited++;

			if (current == goal)
			{
				found = true;
				break;
			}

			int cx = unpackX(current);
			int cy = unpackY(current);

			for (int d = 0; d < DX.length; d++)
			{
				int nx = cx + DX[d];
				int ny = cy + DY[d];
				long next = pack(nx, ny);

				if (cameFrom.containsKey(next)
					|| !bounds.contains(nx, ny)
					|| !memory.canStep(cx, cy, plane, DX[d], DY[d]))
				{
					continue;
				}

				cameFrom.add(next, current);
			}
		}

		if (!found)
		{
			return result;
		}

		// Walk the parent chain back, pushing onto the front to reverse it into start-to-goal order.
		for (long at = goal; at != start; at = cameFrom.get(at))
		{
			result.addFirst(new int[]{unpackX(at), unpackY(at)});
		}
		return result;
	}

	/**
	 * Every tile that can be walked to from a start, breadth first, up to a budget: each tile mapped
	 * to the one it was reached from, so {@link #pathFrom} reads back the walk without searching.
	 */
	TileMap flood(int startX, int startY, int plane, int budget)
	{
		// The record's order is the queue, as in findPath.
		TileMap cameFrom = new TileMap(budget + 8);
		int head = 0;
		long start = pack(startX, startY);
		cameFrom.add(start, start);

		while (head < cameFrom.size() && cameFrom.size() < budget)
		{
			long current = cameFrom.keyAt(head++);
			int cx = unpackX(current);
			int cy = unpackY(current);
			for (int d = 0; d < DX.length; d++)
			{
				int nx = cx + DX[d];
				int ny = cy + DY[d];
				long next = pack(nx, ny);
				if (cameFrom.containsKey(next)
					|| !memory.isKnownWalkable(nx, ny, plane)
					|| !memory.canStep(cx, cy, plane, DX[d], DY[d]))
				{
					continue;
				}
				cameFrom.add(next, current);
			}
		}
		return cameFrom;
	}

	/**
	 * The walk from a flood's start to a tile it reached, excluding the start.
	 *
	 * @return the tiles in order, empty if the goal is the start, null if it was not reached
	 */
	static Deque<int[]> pathFrom(TileMap cameFrom, int startX, int startY, int goalX, int goalY)
	{
		long start = pack(startX, startY);
		long goal = pack(goalX, goalY);
		if (!cameFrom.containsKey(goal))
		{
			return null;
		}
		Deque<int[]> result = new ArrayDeque<>();
		for (long at = goal; at != start; at = cameFrom.get(at))
		{
			result.addFirst(new int[]{unpackX(at), unpackY(at)});
		}
		return result;
	}

	/**
	 * How many tiles can be walked to from here, counting up to a limit. Stops there because only
	 * whether a space is small matters: an open field and a continent are the same to a golem.
	 */
	int areaSize(int x, int y, int plane, int limit)
	{
		TileMap seen = new TileMap(limit + 8);
		int head = 0;
		long start = pack(x, y);
		seen.add(start, 0);
		while (head < seen.size() && seen.size() < limit)
		{
			long current = seen.keyAt(head++);
			int cx = unpackX(current);
			int cy = unpackY(current);
			for (int d = 0; d < DX.length; d++)
			{
				long next = pack(cx + DX[d], cy + DY[d]);
				if (!seen.containsKey(next) && memory.canStep(cx, cy, plane, DX[d], DY[d]))
				{
					seen.add(next, 0);
				}
			}
		}
		return seen.size();
	}

	static long pack(int x, int y)
	{
		return ((long) x << 32) | (y & 0xFFFFFFFFL);
	}

	static int unpackX(long packed)
	{
		return (int) (packed >> 32);
	}

	static int unpackY(long packed)
	{
		return (int) packed;
	}
}

package com.golemsdontdie;

import java.awt.*;
import java.awt.image.*;
import java.util.*;
import javax.inject.*;
import net.runelite.api.*;

/**
 * A picture of one golem, drawn from its own model: the golem's page has a portrait of the golem
 * it is about rather than the same picture twenty thousand times.
 *
 * <p>The pose and the angle come out of the golem's seed, so each golem stands a little
 * differently and always the same way - one caught mid-idle, another square on, another half
 * turned away.
 *
 * <p>Drawn here rather than by the client. The scene renderer draws what is in the scene, and a
 * golem on the other side of the world is not; the model itself is all that is needed, so the
 * faces are sorted by depth and filled flat, which at this size reads as the low-poly figure it
 * is. Client thread only - the models and the animation frames belong to it.
 */
@Singleton
class GolemPortrait
{
	/** The picture's size, which is also what the page's frame is built around. */
	static final int WIDTH = 110;
	static final int HEIGHT = 140;

	/**
	 * Which way round the model has to be turned to face the viewer, in degrees. Found by drawing
	 * one golem the whole way round.
	 */
	private static final int FACING = 0;

	/** How far a golem may be turned off facing the viewer, either way, in degrees. */
	private static final int TURN = 12;

	/**
	 * The poses a golem may be caught in, one frame of each: standing mostly, since a portrait is
	 * a golem stood for its portrait, and now and then mid-stride, arms out, or one hand raised.
	 *
	 * <p>Picked from what the golem already plays in the world. Others were tried and left out:
	 * squeezing through a gap leans the whole model at the viewer, a climb turns its head away, and
	 * the beam-walking poses hold both arms straight out, which a picture cut at the waist loses.
	 * The listing is the weighting - a pose named twice comes up twice as often.
	 */
	private static final int[] POSES = {
		GolemContent.GOLEM_IDLE_ANIMATION,
		GolemContent.GOLEM_IDLE_ANIMATION,
		GolemContent.GOLEM_IDLE_ANIMATION,
		GolemContent.GOLEM_IDLE_ANIMATION,
		GolemContent.GOLEM_WALK_ANIMATION,
		GolemContent.GOLEM_WALK_ANIMATION,
		GolemContent.ANIM_LADDER_GRAB,
		GolemContent.ANIM_JUMP_STEPPINGSTONE,
	};

	/** What the life of the party is doing in its picture. The emote, as a player would dance it. */
	private static final int DANCING = 10031;

	/** How far it may lean, either way, in degrees: enough to tell two golems apart. */
	private static final int LEAN = 3;

	/** The closest and furthest a golem stands, as a share of the room in the frame. */
	private static final float NEAREST = 1f;
	private static final float FURTHEST = 0.86f;

	/** Room left around the golem, in pixels, so nothing touches the frame. */
	private static final int MARGIN = 10;

	/**
	 * How much of the golem the picture holds, from the top down: head, shoulders and chest, cut
	 * somewhere around the waist, as a portrait is.
	 */
	private static final float SHOWN = 0.52f;

	/** Gamma the client's own colour palette is built with, and so this one. */
	private static final double BRIGHTNESS = 0.8;

	@Inject
	private Client client;

	@Inject
	private GolemModelFactory models;

	/** A golem's portrait, or null if its model is not to hand. */
	BufferedImage of(Golem golem)
	{
		if (golem == null || client == null || models == null)
		{
			return null;
		}
		Model model = models.modelFor(golem.getSnapshot());
		if (model == null)
		{
			return null;
		}

		// Its own pose, out of its own number: one of the animations it plays, held at one frame.
		long seed = golem.getId();
		int pose = GolemTrait.LIFE_OF_THE_PARTY.in(golem.getTraits()) ? DANCING
			: POSES[(int) Math.floorMod(seed >> 3, POSES.length)];
		int turn = FACING + (int) Math.floorMod(seed >> 17, TURN * 2L) - TURN;
		return draw(posed(model, pose, (int) (seed >> 5)), model, turn, seed, SHOWN);
	}

	/**
	 * The same picture at an angle, a pose and a crop of the caller's choosing, for the developer
	 * export: which way the model faces, and what an animation does to a golem held still.
	 *
	 * @param shown how much of the golem to frame, from the top: {@link #SHOWN} for a portrait as
	 *              the page has it, 1 for the whole figure.
	 */
	BufferedImage of(Golem golem, int degrees, int animation, int frame, float shown)
	{
		Model model = golem == null || models == null ? null : models.modelFor(golem.getSnapshot());
		return model == null ? null : draw(posed(model, animation, frame), model, degrees, 0, shown);
	}

	/**
	 * Any model, posed by any animation, for the developer export: what the fireworks and the
	 * guitar look like is worth seeing before they are drawn over somebody's golems.
	 */
	BufferedImage of(Model model, int animation, int frame)
	{
		return model == null ? null : draw(posed(model, animation, frame), model, 0, 0, 1f);
	}

	/** The model held at one frame of an animation, or as it rests if there is no such animation. */
	private Model posed(Model model, int animation, int frame)
	{
		Animation loaded = animation < 0 ? null : client.loadAnimation(animation);
		if (loaded == null || loaded.getNumFrames() <= 0)
		{
			return model;
		}
		AnimationController controller = new AnimationController(client, loaded);
		controller.setFrame(Math.floorMod(frame, loaded.getNumFrames()));
		Model animated = controller.animate(model);
		return animated == null ? model : animated;
	}

	/**
	 * Draws the model turned to face the viewer, give or take, with the lean and the distance a
	 * golem's own number gives it.
	 */
	private static BufferedImage draw(Model model, Model standing, int degrees, long seed, float shown)
	{
		double turn = Math.toRadians(degrees);
		double lean = Math.toRadians(Math.floorMod(seed >> 29, LEAN * 2L) - LEAN);
		float zoom = NEAREST - (NEAREST - FURTHEST) * (Math.floorMod(seed >> 41, 16L) / 15f);
		return draw(model, standing, turn, lean, zoom, shown);
	}

	/**
	 * @param standing the same golem unposed, which sets both the size it is drawn at and where the
	 *                 picture is cut. Framed on the pose instead, a golem with a hand raised came
	 *                 out smaller and lower than the one beside it.
	 */
	private static BufferedImage draw(Model model, Model standing, double turn, double lean, float zoom,
		float shown)
	{
		int count = model.getVerticesCount();
		float[] modelX = model.getVerticesX();
		float[] modelY = model.getVerticesY();
		float[] modelZ = model.getVerticesZ();
		if (count == 0 || modelX == null || modelY == null || modelZ == null)
		{
			return null;
		}

		// Turned about the upright axis, which in a model is y and runs downwards.
		float[] x = new float[count];
		float[] y = new float[count];
		float[] depth = new float[count];
		float sin = (float) Math.sin(turn);
		float cos = (float) Math.cos(turn);
		float leftmost = Float.MAX_VALUE;
		float rightmost = -Float.MAX_VALUE;
		float top = Float.MAX_VALUE;
		float bottom = -Float.MAX_VALUE;
		float leanSin = (float) Math.sin(lean);
		float leanCos = (float) Math.cos(lean);
		for (int v = 0; v < count; v++)
		{
			float across = modelX[v] * cos - modelZ[v] * sin;
			depth[v] = modelX[v] * sin + modelZ[v] * cos;
			// And a lean, about the axis into the picture: a golem stood a little off true.
			x[v] = across * leanCos - modelY[v] * leanSin;
			y[v] = across * leanSin + modelY[v] * leanCos;
			leftmost = Math.min(leftmost, x[v]);
			rightmost = Math.max(rightmost, x[v]);
			top = Math.min(top, y[v]);
			bottom = Math.max(bottom, y[v]);
		}

		// Framed on the golem standing: its top half, at the size that fills the frame. Whatever
		// the pose puts outside that - a raised hand, the legs below the cut - falls off the edge.
		float[] framing = framing(standing, shown);
		float scale = zoom * framing[0];
		float offsetX = WIDTH / 2f;
		float offsetY = HEIGHT / 2f - framing[1] * scale;

		BufferedImage image = new BufferedImage(WIDTH, HEIGHT, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		// Something behind it, so the figure is stood in a place rather than cut out of the air.
		g.setPaint(new GradientPaint(0, 0, BEHIND_TOP, 0, HEIGHT, BEHIND_BOTTOM));
		g.fillRect(0, 0, WIDTH, HEIGHT);

		int faces = model.getFaceCount();
		int[] first = model.getFaceIndices1();
		int[] second = model.getFaceIndices2();
		int[] third = model.getFaceIndices3();
		int[] colour1 = model.getFaceColors1();
		int[] colour2 = model.getFaceColors2();
		int[] colour3 = model.getFaceColors3();
		byte[] clear = model.getFaceTransparencies();

		// Furthest first, so nearer faces cover them: a depth buffer for two hundred triangles at
		// this size would be the same picture and a great deal more of it.
		Integer[] order = new Integer[faces];
		float[] away = new float[faces];
		for (int f = 0; f < faces; f++)
		{
			order[f] = f;
			away[f] = depth[first[f]] + depth[second[f]] + depth[third[f]];
		}
		Arrays.sort(order, (one, other) -> Float.compare(away[other], away[one]));

		int[] pointsX = new int[3];
		int[] pointsY = new int[3];
		for (int index = 0; index < faces; index++)
		{
			int f = order[index];
			if (clear != null && (clear[f] & 0xFF) >= 254)
			{
				continue;
			}
			// The third colour is not always a colour: -1 means the face is one flat shade, and -2
			// that it is not drawn at all. Taken for colour, -1 came out white and washed a golden
			// golem out to sand.
			int shade = colour3[f];
			if (shade == -2)
			{
				continue;
			}
			int a = first[f];
			int b = second[f];
			int c = third[f];
			pointsX[0] = Math.round(x[a] * scale + offsetX);
			pointsX[1] = Math.round(x[b] * scale + offsetX);
			pointsX[2] = Math.round(x[c] * scale + offsetX);
			pointsY[0] = Math.round(y[a] * scale + offsetY);
			pointsY[1] = Math.round(y[b] * scale + offsetY);
			pointsY[2] = Math.round(y[c] * scale + offsetY);

			// One colour for the face, the mean of its three: the client shades across a triangle,
			// and a golem is small enough here that the difference is a pixel either way.
			g.setColor(new Color(shade == -1 ? rgb(colour1[f])
				: mean(colour1[f], colour2[f], shade)));
			g.fillPolygon(pointsX, pointsY, 3);
		}
		g.dispose();
		return image;
	}

	/**
	 * How the picture is framed on a golem standing: the scale to draw it at, and the height in the
	 * model to put in the middle of the frame.
	 *
	 * <p>Only the top {@code shown} of it is considered, which is what makes this a portrait and
	 * not a figure. Width is measured at any angle rather than as the model happens to face, so
	 * turning a golem does not change its size.
	 */
	private static float[] framing(Model standing, float shown)
	{
		float[] modelX = standing.getVerticesX();
		float[] modelY = standing.getVerticesY();
		float[] modelZ = standing.getVerticesZ();
		if (modelX == null || modelY == null || modelZ == null)
		{
			return new float[]{1f, 0f};
		}
		int count = standing.getVerticesCount();
		float top = Float.MAX_VALUE;
		float bottom = -Float.MAX_VALUE;
		for (int v = 0; v < count; v++)
		{
			top = Math.min(top, modelY[v]);
			bottom = Math.max(bottom, modelY[v]);
		}
		float cut = top + (bottom - top) * shown;

		float across = 1f;
		for (int v = 0; v < count; v++)
		{
			if (modelY[v] <= cut)
			{
				across = Math.max(across, (float) Math.hypot(modelX[v], modelZ[v]));
			}
		}
		float tall = Math.max(1f, cut - top);
		return new float[]{
			Math.min((WIDTH - 2f * MARGIN) / (2f * across), (HEIGHT - 2f * MARGIN) / tall),
			(top + cut) / 2f,
		};
	}

	/** Behind the golem: dark above, and the ground it stands on catching a little light. */
	private static final Color BEHIND_TOP = new Color(24, 23, 22);
	private static final Color BEHIND_BOTTOM = new Color(46, 44, 41);

	private static int mean(int one, int two, int three)
	{
		int first = rgb(one);
		int second = rgb(two);
		int third = rgb(three);
		int red = ((first >> 16 & 0xFF) + (second >> 16 & 0xFF) + (third >> 16 & 0xFF)) / 3;
		int green = ((first >> 8 & 0xFF) + (second >> 8 & 0xFF) + (third >> 8 & 0xFF)) / 3;
		int blue = ((first & 0xFF) + (second & 0xFF) + (third & 0xFF)) / 3;
		return red << 16 | green << 8 | blue;
	}

	/**
	 * A model's colour as RGB. Models carry the game's own packed HSL, and the client turns it into
	 * colour through a palette built once at startup; this is that conversion for one colour, with
	 * the game's offsets to hue and saturation and the same gamma.
	 */
	private static int rgb(int hsl)
	{
		double hue = (double) JagexColor.unpackHue((short) hsl) / 64.0 + 0.0078125;
		double saturation = (double) JagexColor.unpackSaturation((short) hsl) / 8.0 + 0.0625;
		double lightness = (double) JagexColor.unpackLuminance((short) hsl) / 128.0;

		double red = lightness;
		double green = lightness;
		double blue = lightness;
		if (saturation != 0)
		{
			double q = lightness < 0.5 ? lightness * (1.0 + saturation)
				: lightness + saturation - lightness * saturation;
			double p = 2.0 * lightness - q;
			red = component(p, q, hue + 1.0 / 3.0);
			green = component(p, q, hue);
			blue = component(p, q, hue - 1.0 / 3.0);
		}
		return byteOf(red) << 16 | byteOf(green) << 8 | byteOf(blue);
	}

	/** One channel, gamma-corrected and kept inside a byte: the palette's 256 rounds up to it. */
	private static int byteOf(double channel)
	{
		return Math.min(255, (int) (Math.pow(channel, BRIGHTNESS) * 256));
	}

	private static double component(double p, double q, double hue)
	{
		double at = hue < 0 ? hue + 1 : hue > 1 ? hue - 1 : hue;
		if (at < 1.0 / 6.0)
		{
			return p + (q - p) * 6.0 * at;
		}
		if (at < 0.5)
		{
			return q;
		}
		if (at < 2.0 / 3.0)
		{
			return p + (q - p) * (2.0 / 3.0 - at) * 6.0;
		}
		return p;
	}
}

package com.golemsdontdie;

import java.util.*;
import java.util.function.*;
import javax.inject.*;
import lombok.extern.slf4j.*;
import net.runelite.api.*;
import net.runelite.api.coords.*;
import static com.golemsdontdie.RouteGeometry.span;

/**
 * Golems that come aboard the player's own ship.
 *
 * <p>Golems standing near a boat when the player steps onto it come aboard with them, stand at the
 * rail for the voyage, and step off where the player does. The rest of the plugin sails golems on
 * boats of its own drawing; this is the one place a golem rides on something the game controls.
 *
 * <p>A ship is a world of its own: aboard, the player stands in the boat's own world view, which the
 * client moves and turns as the boat sails. A golem aboard is drawn in that same view, at a place on
 * the deck, so the client carries it with the boat exactly as it carries the player - nothing here
 * chases a moving hull frame by frame. Its simulated position is kept at the boat's place in the
 * main world, which is what the map, the sidebar and the distance to it want.
 *
 * <p>Client thread throughout.
 */
@Slf4j
@Singleton
class GolemShipmates
{
	/** How near where the player stepped aboard a golem must be to follow, in tiles. */
	private static final int BOARD_TILES = 8;

	/** Most golems aboard at once, however big the deck. */
	private static final int MOST_ABOARD = 8;

	/**
	 * How near where the ship was the player must step ashore for the golems to step ashore with
	 * them. Further, and the player left some other way - a teleport, a log out - and the golems go
	 * back to the quay they boarded at rather than appearing wherever the player landed.
	 */
	private static final int LANDING_TILES = 12;

	/** What stops a tile being deck to stand on: something on it, or no floor under it. */
	static final int NOT_DECK = CollisionDataFlag.BLOCK_MOVEMENT_FULL
		| CollisionDataFlag.BLOCK_MOVEMENT_OBJECT | CollisionDataFlag.BLOCK_MOVEMENT_FLOOR
		| CollisionDataFlag.BLOCK_MOVEMENT_FLOOR_DECORATION;

	/**
	 * The same over the hull, where "no floor" does not count: a skiff's deck carries it down one
	 * whole side that is open deck. What over the hull is not deck is marked blocked in the tile's
	 * settings instead; see deckFlags.
	 */
	private static final int NOT_DECK_ON_HULL = CollisionDataFlag.BLOCK_MOVEMENT_OBJECT
		| CollisionDataFlag.BLOCK_MOVEMENT_FLOOR_DECORATION;

	/** A tile setting: nothing may stand here. */
	private static final int TILE_BLOCKED = 1;

	/** The four ways off a deck tile, and the way a golem at that rail faces: 0 south, 512 west. */
	private static final int[][] OUTBOARD = {{-1, 0, 512}, {1, 0, 1536}, {0, 1, 1024}, {0, -1, 0}};

	@Inject
	private Client client;

	@Inject
	private GolemsDontDieConfig config;

	/** The world view of the ship the player is aboard, or -1 ashore. */
	private int ship = -1;

	/** Where the player last stood on land, which is where they stepped aboard from. */
	private WorldPoint lastAshore;

	/** Where the ship was last seen in the main world, for telling a landing from a teleport. */
	private WorldPoint shipAt;

	/** The golems aboard now. */
	private final List<Golem> aboard = new ArrayList<>();

	/**
	 * Told of a golem whenever it goes aboard or ashore, so its drawn object can be made again: one
	 * is registered with the world it is drawn in, and cannot simply be moved into another.
	 */
	private Consumer<Golem> onMoved = golem ->
	{
	};

	void setOnMoved(Consumer<Golem> onMoved)
	{
		this.onMoved = onMoved;
	}

	/**
	 * Once a tick: notices the player stepping aboard or ashore, and brings the golems along.
	 *
	 * @param snap puts a tile onto ground a golem can stand on; see RoamPlanner.snapToMesh
	 */
	void update(List<Golem> golems, int tick, BiFunction<WorldPoint, Set<Long>, WorldPoint> snap)
	{
		// A golem removed from the roster while aboard is not aboard any more.
		aboard.removeIf(golem -> !golems.contains(golem) || !golem.isAboard());

		Player me = client.getLocalPlayer();
		WorldView top = client.getTopLevelWorldView();
		if (me == null || top == null)
		{
			return;
		}
		WorldView view = me.getWorldView();
		boolean onOwnShip = view != null && !view.isTopLevel() && isOwnShip(top, view.getId());

		if (!onOwnShip)
		{
			if (ship >= 0)
			{
				landed(me.getWorldLocation(), tick, snap);
			}
			if (view == null || view.isTopLevel())
			{
				lastAshore = me.getWorldLocation();
			}
			return;
		}

		shipAt = PlayerPosition.of(client);
		if (ship == view.getId())
		{
			return;
		}
		if (ship >= 0)
		{
			// Onto another ship without touching land: the old one's crew goes home.
			abandon(tick);
		}
		ship = view.getId();
		if (config.golemsJoinShip() && !config.restrictGolemAmbition() && lastAshore != null)
		{
			board(golems, view, me, tick);
		}
	}

	/** Whether this world view is a boat that belongs to the player, rather than a ride or a rival's. */
	private static boolean isOwnShip(WorldView top, int viewId)
	{
		WorldEntity entity = top.worldEntities().byIndex(viewId);
		return entity != null && entity.getOwnerType() == WorldEntity.OWNER_TYPE_SELF_PLAYER;
	}

	/** The player has just stepped aboard: the golems nearby follow them onto the deck. */
	private void board(List<Golem> golems, WorldView deck, Player me, int tick)
	{
		LocalPoint standing = me.getLocalLocation();
		int plane = deckPlane(deck, standing);
		List<int[]> rails = rails(deck, plane, standing);
		if (rails.isEmpty() && plane != deck.getPlane())
		{
			plane = deck.getPlane();
			rails = rails(deck, plane, standing);
		}
		if (rails.isEmpty())
		{
			return;
		}

		List<Golem> coming = new ArrayList<>();
		for (Golem golem : golems)
		{
			if (golem.getRenderer() == null || golem.isDying() || golem.inTransition()
				|| golem.isSailing(tick) || golem.isCrewed() || golem.isAboard()
				|| golem.getPlane() != lastAshore.getPlane()
				|| golem.currentTile().distanceTo2D(lastAshore) > BOARD_TILES)
			{
				continue;
			}
			coming.add(golem);
		}
		// The golems a player cares about first: starred, then named, then whoever is nearest.
		coming.sort(Comparator.comparing((Golem golem) -> !golem.isFavourite())
			.thenComparing(golem -> golem.getNickname() == null || golem.getNickname().isEmpty())
			.thenComparingInt(golem -> golem.currentTile().distanceTo2D(lastAshore)));

		int berths = Math.min(MOST_ABOARD, rails.size());
		for (int i = 0; i < coming.size() && i < berths; i++)
		{
			Golem golem = coming.get(i);
			int[] rail = rails.get(i);
			golem.boardShip(deck.getId(), rail[0], rail[1], plane, rail[2]);
			aboard.add(golem);
			onMoved.accept(golem);
		}
		if (!aboard.isEmpty())
		{
			log.debug("{} golems came aboard", aboard.size());
		}
	}

	/**
	 * The floor the player is standing on: the highest plane of the ship's scene with a tile under
	 * them. Not the world view's own plane, which on a sloop is the hull's, a floor below the deck:
	 * golems were stood at the hull's level on tiles out beside it, in the sea, instead of on deck.
	 */
	static int deckPlane(WorldView deck, LocalPoint standing)
	{
		Tile[][][] tiles = deck.getScene() == null ? null : deck.getScene().getTiles();
		if (tiles == null || standing == null)
		{
			return deck.getPlane();
		}
		int x = standing.getSceneX();
		int y = standing.getSceneY();
		for (int plane = tiles.length - 1; plane >= 0; plane--)
		{
			if (x >= 0 && x < tiles[plane].length && y >= 0 && y < tiles[plane][x].length
				&& tiles[plane][x][y] != null)
			{
				return plane;
			}
		}
		return deck.getPlane();
	}

	/**
	 * Places at the ship's rail, spread around the deck: deck tiles beside open water, each with the
	 * way a golem standing there faces to look out over it, in the deck's own local units. The first
	 * is the rail furthest from the player, each next the one furthest from all those already taken,
	 * so a few golems stand around the ship rather than in a queue along one side.
	 */
	static List<int[]> rails(WorldView deck, int plane, LocalPoint player)
	{
		int[][] flags = deckFlags(deck, plane);
		if (flags == null)
		{
			return new ArrayList<>();
		}
		int sizeX = Math.min(deck.getSizeX(), flags.length);
		int sizeY = flags.length == 0 ? 0 : Math.min(deck.getSizeY(), flags[0].length);
		// A tile the ship's scene has nothing on is not deck, whatever its flags say: water inside
		// the square a ship's world is drawn in must not take a golem because nothing blocks it.
		Tile[][][] tiles = deck.getScene() == null ? null : deck.getScene().getTiles();
		Tile[][] floor = tiles == null || plane >= tiles.length ? null : tiles[plane];
		Tile[][] below = tiles == null || plane < 1 || plane > tiles.length ? null : tiles[plane - 1];

		// Only over the hull. A sloop's floor runs a tile out past the hull on each side, under the
		// trim round its edge, and nothing there blocks; golems took those tiles for the rail and
		// stood out beside the ship, over the sea.
		int[] hull = hullFootprint(deck);
		Set<Long> helm = helmTiles(deck, hull, plane);
		List<int[]> rail = new ArrayList<>();
		for (int x = 0; x < sizeX; x++)
		{
			for (int y = 0; y < sizeY; y++)
			{
				// Nor the bow's row, where the hull narrows to its point: not somewhere anyone stands.
				// The helm is at the other end, the high one, on every hull the game lays out.
				if (!onHull(hull, x, y) || hull != null && y == hull[1]
					|| helm.contains((long) x << 32 | y) || !isDeck(flags, hull, x, y, sizeX, sizeY)
					|| floor != null && !hasTile(floor, x, y) && !hasTile(below, x, y))
				{
					continue;
				}
				for (int[] way : OUTBOARD)
				{
					if (!onHull(hull, x + way[0], y + way[1]) || !isDeck(flags, hull, x + way[0], y + way[1], sizeX, sizeY))
					{
						rail.add(new int[]{x, y, way[2]});
						break;
					}
				}
			}
		}

		int playerX = player == null ? -1 : player.getSceneX();
		int playerY = player == null ? -1 : player.getSceneY();
		rail.removeIf(tile -> tile[0] == playerX && tile[1] == playerY);

		List<int[]> spread = new ArrayList<>(rail.size());
		List<int[]> taken = new ArrayList<>();
		if (player != null)
		{
			taken.add(new int[]{playerX, playerY});
		}
		while (!rail.isEmpty())
		{
			int best = 0;
			int bestGap = -1;
			for (int i = 0; i < rail.size(); i++)
			{
				int gap = Integer.MAX_VALUE;
				for (int[] other : taken)
				{
					gap = Math.min(gap, span(rail.get(i)[0] - other[0], rail.get(i)[1] - other[1]));
				}
				if (gap > bestGap)
				{
					bestGap = gap;
					best = i;
				}
			}
			int[] chosen = rail.remove(best);
			taken.add(chosen);
			// Tile to the middle of the tile, in local units.
			spread.add(new int[]{chosen[0] * Golem.TILE + Golem.TILE / 2, chosen[1] * Golem.TILE + Golem.TILE / 2, chosen[2]});
		}
		return spread;
	}

	/**
	 * What stands in the way on each tile of a deck. Off the hull, its collision. Over the hull, the
	 * ship itself says, and not in its collision, which on a skiff marks the mast's tile blocked and
	 * leaves the salvaging station's open: a tile is deck unless the deck's settings mark it blocked,
	 * as the bow and the helm's row are, or something that fills its tile stands on it - an object
	 * placed with bit 0x100 of its config, which the stations, the wind catcher and the flag are
	 * and the mast, the sail, the helm and the cleats are not. Read so, a skiff's deck is the five
	 * places a player can walk to, where the collision gave golems the stations to stand in.
	 */
	static int[][] deckFlags(WorldView deck, int plane)
	{
		CollisionData[] maps = deck.getCollisionMaps();
		if (maps == null || plane < 0 || plane >= maps.length || maps[plane] == null)
		{
			return null;
		}
		int[][] own = maps[plane].getFlags();
		int[] hull = hullFootprint(deck);
		if (hull == null)
		{
			return own;
		}
		byte[][][] settings = deck.getTileSettings();
		boolean[][] filled = filledTiles(deck, plane, own.length, own.length == 0 ? 0 : own[0].length);
		int[][] out = new int[own.length][];
		for (int x = 0; x < own.length; x++)
		{
			out[x] = own[x].clone();
			for (int y = 0; y < own[x].length; y++)
			{
				if (!onHull(hull, x, y))
				{
					continue;
				}
				boolean blocked = settings != null && plane < settings.length && x < settings[plane].length
					&& y < settings[plane][x].length && (settings[plane][x][y] & TILE_BLOCKED) != 0;
				out[x][y] = blocked || filled[x][y] ? CollisionDataFlag.BLOCK_MOVEMENT_OBJECT : 0;
			}
		}
		return out;
	}

	/**
	 * A placed object's config bit for "supports items", which the client sets from the object's
	 * own definition: unless the definition says otherwise, whether the object is solid. So it
	 * holds for any fitting a player builds onto any boat, wherever they put it. Checked over every
	 * Sailing object in the cache: stations, wind catchers, teleportation foci and the flag are
	 * solid and set; masts, sails, helms and salvaging hooks are walked through and clear.
	 */
	private static final int FILLS_TILE = 0x100;

	/** The tiles of one floor of a ship that an object filling its tile stands on. */
	private static boolean[][] filledTiles(WorldView deck, int plane, int sizeX, int sizeY)
	{
		boolean[][] out = new boolean[sizeX][sizeY];
		Tile[][][] tiles = deck.getScene() == null ? null : deck.getScene().getTiles();
		if (tiles == null || plane >= tiles.length || tiles[plane] == null)
		{
			return out;
		}
		for (Tile[] column : tiles[plane])
		{
			for (Tile tile : column == null ? new Tile[0] : column)
			{
				if (tile == null || tile.getGameObjects() == null)
				{
					continue;
				}
				for (GameObject object : tile.getGameObjects())
				{
					if (object == null || (object.getConfig() & FILLS_TILE) == 0 || isHull(object.getId()))
					{
						continue;
					}
					int x0 = object.getSceneMinLocation().getX();
					int y0 = object.getSceneMinLocation().getY();
					for (int x = x0; x < x0 + Math.max(1, object.sizeX()) && x < sizeX; x++)
					{
						for (int y = y0; y < y0 + Math.max(1, object.sizeY()) && y < sizeY; y++)
						{
							if (x >= 0 && y >= 0)
							{
								out[x][y] = true;
							}
						}
					}
				}
			}
		}
		return out;
	}

	private static boolean hasTile(Tile[][] floor, int x, int y)
	{
		return floor != null && x < floor.length && y < floor[x].length && floor[x][y] != null;
	}

	/**
	 * The tiles the hull covers, as {minX, minY, maxX, maxY} in the ship's scene, or null if no hull
	 * is found, when every tile counts. Found by the hull objects' own ids: the largest object on a
	 * ship is not its hull but the trim round the edge of it.
	 */
	static int[] hullFootprint(WorldView deck)
	{
		Tile[][][] tiles = deck.getScene() == null ? null : deck.getScene().getTiles();
		if (tiles == null)
		{
			return null;
		}
		for (Tile[][] plane : tiles)
		{
			for (Tile[] column : plane == null ? new Tile[0][] : plane)
			{
				for (Tile tile : column == null ? new Tile[0] : column)
				{
					if (tile == null || tile.getGameObjects() == null)
					{
						continue;
					}
					for (GameObject object : tile.getGameObjects())
					{
						if (object != null && isHull(object.getId()))
						{
							int x = object.getSceneMinLocation().getX();
							int y = object.getSceneMinLocation().getY();
							return new int[]{x, y, x + object.sizeX() - 1, y + object.sizeY() - 1};
						}
					}
				}
			}
		}
		return null;
	}

	/**
	 * Where the player stands to steer, as x << 32 | y. On the helm itself where it can be stood on,
	 * as a raft's can; otherwise the tile before it, toward the bow, which is the low end of every
	 * hull's own grid: a skiff's helm row is blocked, and a sloop's helm stands off the end of the
	 * hull. Kept clear for the player alone; golems were stood at the wheel.
	 */
	static Set<Long> helmTiles(WorldView deck, int[] hull, int plane)
	{
		Set<Long> out = new HashSet<>();
		Tile[][][] tiles = deck.getScene() == null ? null : deck.getScene().getTiles();
		if (tiles == null)
		{
			return out;
		}
		byte[][][] settings = deck.getTileSettings();
		for (Tile[][] floor : tiles)
		{
			for (Tile[] column : floor == null ? new Tile[0][] : floor)
			{
				for (Tile tile : column == null ? new Tile[0] : column)
				{
					if (tile == null || tile.getGameObjects() == null)
					{
						continue;
					}
					for (GameObject object : tile.getGameObjects())
					{
						if (object == null || !isHelm(object.getId()))
						{
							continue;
						}
						int x = object.getSceneMinLocation().getX();
						int y = object.getSceneMinLocation().getY();
						boolean blocked = settings != null && plane < settings.length && x < settings[plane].length
							&& y < settings[plane][x].length && (settings[plane][x][y] & TILE_BLOCKED) != 0;
						if (!onHull(hull, x, y) || blocked)
						{
							y -= 1;
						}
						if (hull != null)
						{
							x = Math.max(hull[0], Math.min(hull[2], x));
							y = Math.max(hull[1], Math.min(hull[3], y));
						}
						out.add((long) x << 32 | y);
					}
				}
			}
		}
		return out;
	}

	/** Every Kandarin helm, the wheel and the tutorial's, and the pirates'. */
	private static boolean isHelm(int objectId)
	{
		return objectId >= 59554 && objectId <= 59623 || objectId == 29536;
	}

	/** The Kandarin hulls in every wood, raft to sloop, the colossal one and the pirates'. */
	private static boolean isHull(int objectId)
	{
		return objectId >= 59494 && objectId <= 59515 || objectId == 29472;
	}

	private static boolean onHull(int[] hull, int x, int y)
	{
		return hull == null || x >= hull[0] && y >= hull[1] && x <= hull[2] && y <= hull[3];
	}

	private static boolean isDeck(int[][] flags, int[] hull, int x, int y, int sizeX, int sizeY)
	{
		int mask = hull != null && onHull(hull, x, y) ? NOT_DECK_ON_HULL : NOT_DECK;
		return x >= 0 && y >= 0 && x < sizeX && y < sizeY && (flags[x][y] & mask) == 0;
	}

	/**
	 * Keeps a golem aboard at the ship's place in the main world, for everything that asks where it
	 * is. Its drawn place is on the deck, and the client moves that with the boat.
	 */
	void carry(Golem golem)
	{
		WorldView top = client.getTopLevelWorldView();
		if (top == null)
		{
			return;
		}
		WorldEntity boat = top.worldEntities().byIndex(golem.getAboardView());
		if (boat == null)
		{
			return;
		}
		LocalPoint atSea = boat.transformToMainWorld(new LocalPoint(golem.getDeckX(), golem.getDeckY(), golem.getAboardView()));
		if (atSea != null)
		{
			golem.followShip(atSea.getX() + top.getBaseX() * Golem.TILE, atSea.getY() + top.getBaseY() * Golem.TILE,
				top.getPlane());
		}
	}

	/**
	 * The player is off the ship. Near where it was, and the golems step off around them, onto the
	 * player's own tile if there is no room; anywhere else, and each goes back to the quay it
	 * boarded from.
	 */
	private void landed(WorldPoint ashore, int tick, BiFunction<WorldPoint, Set<Long>, WorldPoint> place)
	{
		boolean withPlayer = ashore != null && shipAt != null && ashore.getPlane() == shipAt.getPlane()
			&& ashore.distanceTo2D(shipAt) <= LANDING_TILES;
		// A tile each, on land, around where the player stepped off; not the player's own.
		Set<Long> taken = new HashSet<>();
		if (ashore != null)
		{
			taken.add(RoamContext.tileKey(ashore.getX(), ashore.getY(), ashore.getPlane()));
		}
		for (Golem golem : aboard)
		{
			WorldPoint to = withPlayer ? stepOff(ashore, taken, place) : golem.getAboardFrom();
			golem.leaveShip(to, tick);
			onMoved.accept(golem);
		}
		aboard.clear();
		ship = -1;
		shipAt = null;
	}

	/**
	 * Where one golem steps off beside the player: a tile of its own around them if there is one,
	 * taken so the next golem finds another, and the player's own tile if there is not. A narrow
	 * quay with no room to spare sent golems back to the port they boarded at, which could be
	 * across the map from where they had just sailed with the player.
	 *
	 * @param taken tiles already stood on, the player's among them
	 */
	static WorldPoint stepOff(WorldPoint ashore, Set<Long> taken, BiFunction<WorldPoint, Set<Long>, WorldPoint> place)
	{
		WorldPoint ground = place == null ? null : place.apply(ashore, taken);
		if (ground == null || ground.equals(ashore))
		{
			return ashore;
		}
		taken.add(RoamContext.tileKey(ground.getX(), ground.getY(), ground.getPlane()));
		return ground;
	}

	/**
	 * Sends every golem aboard back to the quay it boarded from: the voyage is over for a reason the
	 * golems were not part of - a world hop, a log out, the plugin stopping.
	 */
	void abandon(int tick)
	{
		for (Golem golem : aboard)
		{
			golem.leaveShip(golem.getAboardFrom(), tick);
			onMoved.accept(golem);
		}
		aboard.clear();
		ship = -1;
		shipAt = null;
		// The next ship boarded is boarded from wherever the player next stands ashore, not from a
		// quay left before a hop or a log out.
		lastAshore = null;
	}
}

package com.golemsdontdie;

import lombok.*;
import net.runelite.api.*;
import net.runelite.api.coords.*;

/**
 * Everything about a live golem that a copy will need, recorded while the real one
 * is still standing.
 *
 * <p>None of it survives the NPC, so a snapshot is kept refreshed for every watched golem
 * and the copy built from the last one before the death animation. Models, recolours, scale
 * and size come from {@link NPCComposition} given only an NPC ID; the animation IDs do not,
 * only the live {@link net.runelite.api.Actor} having them, so those three go to disk.
 */
@Value
class GolemSnapshot
{
	int npcId;
	String name;

	/** Model IDs from the composition, merged and recoloured into the base model. */
	int[] modelIds;
	short[] recolourFrom;
	short[] recolourTo;

	/** Composition scaling, in 128ths. 128 = as authored. */
	int widthScale;
	int heightScale;

	/** Footprint in tiles; sizes the drawn object's tile-sorting radius. */
	int size;

	/** Pose animations from the actor. -1 where the golem has none. */
	int idlePoseAnimation;
	int walkAnimation;
	int runAnimation;

	/** Where it stood and which way it faced when taken. */
	WorldPoint worldLocation;
	int orientation;

	GolemSnapshot facing(int newOrientation)
	{
		return new GolemSnapshot(npcId, name, modelIds, recolourFrom, recolourTo,
			widthScale, heightScale, size, idlePoseAnimation, walkAnimation, runAnimation,
			worldLocation, newOrientation & 2047);
	}

	/** Reads the current state of a live golem; null if the NPC has no usable composition. */
	static GolemSnapshot of(NPC npc)
	{
		NPCComposition comp = npc.getTransformedComposition();
		if (comp == null)
		{
			comp = npc.getComposition();
		}
		if (comp == null)
		{
			return null;
		}

		return build(
			comp,
			npc.getName() == null ? comp.getName() : npc.getName(),
			npc.getIdlePoseAnimation(),
			npc.getWalkAnimation(),
			npc.getRunAnimation(),
			npc.getWorldLocation(),
			npc.getCurrentOrientation());
	}

	/**
	 * Rebuilds a snapshot for a saved golem: appearance from the cache, the rest from the save.
	 *
	 * @return the snapshot, or null if the NPC ID is no longer in the cache
	 */
	static GolemSnapshot restore(Client client, int npcId, int idlePose, int walk, int run,
		WorldPoint where, int orientation)
	{
		NPCComposition comp = client.getNpcDefinition(npcId);
		if (comp == null)
		{
			return null;
		}

		// A golem with no animation stands frozen, which is worse than one moving
		// slightly wrong; saves predating the recording, or catching a transition, carry -1.
		if (walk == -1)
		{
			walk = GolemContent.GOLEM_WALK_ANIMATION;
		}
		if (idlePose == -1)
		{
			idlePose = GolemContent.GOLEM_IDLE_ANIMATION;
		}

		return build(comp, comp.getName(), idlePose, walk, run, where, orientation);
	}

	private static GolemSnapshot build(NPCComposition comp, String name, int idlePose, int walk, int run,
		WorldPoint where, int orientation)
	{
		int[] models = comp.getModels();
		if (models == null || models.length == 0)
		{
			return null;
		}

		return new GolemSnapshot(
			comp.getId(),
			name == null ? "Golem" : name,
			models.clone(),
			comp.getColorToReplace() == null ? new short[0] : comp.getColorToReplace().clone(),
			comp.getColorToReplaceWith() == null ? new short[0] : comp.getColorToReplaceWith().clone(),
			comp.getWidthScale(),
			comp.getHeightScale(),
			Math.max(1, comp.getSize()),
			idlePose,
			walk,
			run,
			where,
			orientation & 2047);
	}
}

package com.golemsdontdie;

import java.util.*;
import javax.inject.*;
import lombok.extern.slf4j.*;
import net.runelite.api.*;
import net.runelite.api.coords.*;

/**
 * Reads and writes the saved golem roster.
 *
 * <p>Only what the cache cannot supply is written: the NPC ID, position, home tile, the three
 * animation IDs no composition exposes, and what the golem has been and done - its seed, traits,
 * history and journal. Everything visual is re-fetched on load, so the save stays a couple of
 * dozen numbers per golem. A flat delimited string rather than JSON: the record
 * is all numbers, and a save the player can read and edit is worth more than a schema.
 */
@Slf4j
@Singleton
class GolemStore
{
	private static final String GOLEM_SEPARATOR = ";";
	private static final String FIELD_SEPARATOR = ",";

	/**
	 * Ten numbers plus the nickname. The rest are optional: whether the golem is in an instance,
	 * when it may next sail, its seed, the six of its history, its traits, its star, its craft
	 * number and its journal.
	 *
	 * <p>The format only ever grows at the end, and a reader takes what it knows and ignores the
	 * rest. So a save written by a later version still loads here, less whatever was added since;
	 * refusing it, as 2.0 does anything past thirteen fields, costs a player every golem they have
	 * the first time two versions meet.
	 */
	private static final int FIELD_COUNT = 11;

	/** Where the history starts among the optional fields. */
	private static final int HISTORY_AT = FIELD_COUNT + 3;

	/** Where the traits are, after the six of the history. */
	private static final int TRAITS_AT = HISTORY_AT + 6;

	/** Whether the player starred the golem, after its traits. */
	private static final int FAVOURITE_AT = TRAITS_AT + 1;

	/** Its craft number, after the star. */
	private static final int CRAFT_AT = FAVOURITE_AT + 1;

	/** Its journal, after the craft number; see GolemHistory#journalCode. */
	private static final int JOURNAL_AT = CRAFT_AT + 1;

	/** Characters a nickname may not contain, because they are the separators. */
	private static final String ILLEGAL_IN_NICKNAME = "[;,]";

	@Inject
	private Client client;

	/** A golem as it sits in the save file, before the cache fills in its appearance. */
	static class SavedGolem
	{
		int npcId;
		int worldX;
		int worldY;
		int plane;
		int orientation;
		int homeX;
		int homeY;
		int idlePose;
		int walk;
		int run;
		String nickname;
		boolean inInstance;
		long shoreLeaveUntil;

		/** The golem's own number, or 0 for a save written before it was kept. See revive. */
		long seed;

		/**
		 * Its traits as dealt, or 0 for a save written before they were kept. Kept because they are
		 * drawn from the trait list as it stands, and the list will not stand still: re-dealt from
		 * the seed after the list changed, every golem would come back with somebody else's.
		 */
		int traits;

		/** Starred by the player; see Golem#isFavourite. */
		boolean favourite;

		/** See Golem#getCraftNumber; 0 for a save written before it was kept, numbered on restore. */
		int craftNumber;

		/** The journal as GolemHistory#journalCode wrote it; null for a save written before it was kept. */
		String journal;

		/** Its history, in the order GolemHistory.restore takes them; all zero if there was none. */
		long firstSeen;
		int transports;
		int voyages;
		int walked;
		int furthestX;
		int furthestY;
	}

	/** Encodes a live roster for the config store. */
	String serialise(List<Golem> golems)
	{
		StringBuilder out = new StringBuilder();
		for (Golem golem : golems)
		{
			GolemSnapshot snapshot = golem.getSnapshot();
			WorldPoint at = golem.saveTile();
			if (out.length() > 0)
			{
				out.append(GOLEM_SEPARATOR);
			}
			out.append(snapshot.getNpcId()).append(FIELD_SEPARATOR)
				.append(at.getX()).append(FIELD_SEPARATOR)
				.append(at.getY()).append(FIELD_SEPARATOR)
				.append(at.getPlane()).append(FIELD_SEPARATOR)
				.append(golem.getOrientation()).append(FIELD_SEPARATOR)
				.append(golem.getHome().getX()).append(FIELD_SEPARATOR)
				.append(golem.getHome().getY()).append(FIELD_SEPARATOR)
				.append(snapshot.getIdlePoseAnimation()).append(FIELD_SEPARATOR)
				.append(snapshot.getWalkAnimation()).append(FIELD_SEPARATOR)
				.append(snapshot.getRunAnimation()).append(FIELD_SEPARATOR)
				// Separators are stripped rather than escaped: losing a stray comma from
				// free text beats a save file that will not parse.
				.append(golem.getNickname() == null
					? ""
					: golem.getNickname().replaceAll(ILLEGAL_IN_NICKNAME, ""))
				.append(FIELD_SEPARATOR).append(golem.isInInstance() ? 1 : 0)
				// Real time, so a golem that landed just before logout is still ashore after it.
				.append(FIELD_SEPARATOR).append(golem.getShoreLeaveUntil())
				.append(FIELD_SEPARATOR).append(golem.getId());
			GolemHistory history = golem.getHistory();
			out.append(FIELD_SEPARATOR).append(history.getFirstSeen())
				.append(FIELD_SEPARATOR).append(history.getTransports())
				.append(FIELD_SEPARATOR).append(history.getVoyages())
				.append(FIELD_SEPARATOR).append(history.getWalked())
				.append(FIELD_SEPARATOR).append(history.getFurthestX())
				.append(FIELD_SEPARATOR).append(history.getFurthestY())
				.append(FIELD_SEPARATOR).append(golem.getTraits())
				.append(FIELD_SEPARATOR).append(golem.isFavourite() ? 1 : 0)
				.append(FIELD_SEPARATOR).append(golem.getCraftNumber())
				.append(FIELD_SEPARATOR).append(history.journalCode());
		}
		return out.toString();
	}

	/** Decodes a roster. Malformed entries are dropped rather than failing the load. */
	List<SavedGolem> deserialise(String encoded)
	{
		List<SavedGolem> result = new ArrayList<>();
		if (encoded == null || encoded.trim().isEmpty())
		{
			return result;
		}

		for (String entry : encoded.split(GOLEM_SEPARATOR))
		{
			if (entry.trim().isEmpty())
			{
				continue;
			}
			// -1 keeps a trailing empty nickname as a field rather than dropping it.
			String[] fields = entry.split(FIELD_SEPARATOR, -1);
			// A floor and no ceiling: fields past the ones this version knows are a later
			// version's, and are ignored rather than taken as damage.
			if (fields.length < FIELD_COUNT)
			{
				log.debug("Dropping malformed saved golem '{}'", entry);
				continue;
			}
			try
			{
				SavedGolem saved = new SavedGolem();
				saved.npcId = Integer.parseInt(fields[0].trim());
				saved.worldX = Integer.parseInt(fields[1].trim());
				saved.worldY = Integer.parseInt(fields[2].trim());
				saved.plane = Integer.parseInt(fields[3].trim());
				saved.orientation = Integer.parseInt(fields[4].trim());
				saved.homeX = Integer.parseInt(fields[5].trim());
				saved.homeY = Integer.parseInt(fields[6].trim());
				saved.idlePose = Integer.parseInt(fields[7].trim());
				saved.walk = Integer.parseInt(fields[8].trim());
				saved.run = Integer.parseInt(fields[9].trim());
				String nickname = fields[10].trim();
				saved.nickname = nickname.isEmpty() ? null : nickname;
				saved.inInstance = fields.length > FIELD_COUNT && "1".equals(fields[FIELD_COUNT].trim());
				saved.shoreLeaveUntil = fields.length > FIELD_COUNT + 1 ? Long.parseLong(fields[FIELD_COUNT + 1].trim()) : 0;
				saved.seed = fields.length > FIELD_COUNT + 2 ? Long.parseLong(fields[FIELD_COUNT + 2].trim()) : 0;
				if (fields.length >= HISTORY_AT + 6)
				{
					saved.firstSeen = Long.parseLong(fields[HISTORY_AT].trim());
					saved.transports = Integer.parseInt(fields[HISTORY_AT + 1].trim());
					saved.voyages = Integer.parseInt(fields[HISTORY_AT + 2].trim());
					saved.walked = Integer.parseInt(fields[HISTORY_AT + 3].trim());
					saved.furthestX = Integer.parseInt(fields[HISTORY_AT + 4].trim());
					saved.furthestY = Integer.parseInt(fields[HISTORY_AT + 5].trim());
				}
				saved.traits = fields.length > TRAITS_AT ? Integer.parseInt(fields[TRAITS_AT].trim()) : 0;
				saved.favourite = fields.length > FAVOURITE_AT && "1".equals(fields[FAVOURITE_AT].trim());
				saved.craftNumber = fields.length > CRAFT_AT ? Integer.parseInt(fields[CRAFT_AT].trim()) : 0;
				saved.journal = fields.length > JOURNAL_AT ? fields[JOURNAL_AT].trim() : null;
				result.add(saved);
			}
			catch (NumberFormatException e)
			{
				log.debug("Dropping unparseable saved golem '{}'", entry, e);
			}
		}
		return result;
	}

	/**
	 * Turns a saved record back into a golem, pulling its appearance from the cache.
	 *
	 * @param index position in the save file, which keeps each golem's seed distinct
	 * @return the golem, or null if the cache no longer knows that NPC ID
	 */
	Golem revive(SavedGolem saved, int index)
	{
		WorldPoint at = new WorldPoint(saved.worldX, saved.worldY, saved.plane);
		GolemSnapshot snapshot = GolemSnapshot.restore(
			client, saved.npcId, saved.idlePose, saved.walk, saved.run, at, saved.orientation);
		if (snapshot == null)
		{
			log.debug("Saved golem npc {} is no longer in the cache", saved.npcId);
			return null;
		}

		WorldPoint home = new WorldPoint(saved.homeX, saved.homeY, saved.plane);

		// A golem's seed is its character: its gait comes out of it, and so do its traits. It is
		// saved with the golem for that reason - worked out from where it stood, it changed every
		// time the golem moved, and a golem came back a different one.
		//
		// Saves written before it was kept have none, and one is made for them the old way: from
		// the position and the index, the index because two golems on one tile - which is what a
		// spawn tile gives you - would otherwise share a seed and a gait.
		long seed = saved.seed != 0 ? saved.seed
			: ((long) saved.worldX << 32) ^ ((long) saved.worldY << 8) ^ saved.npcId ^ (index * 0x9E3779B9L);
		Golem golem = Golem.onTile(snapshot, home, seed, at);
		// Every golem is dealt at least one trait, so none at all means none were saved: the golem
		// keeps the hand its seed deals today, which from now on is saved with it.
		if (saved.traits != 0)
		{
			golem.restoreTraits(saved.traits);
		}
		golem.setNickname(saved.nickname);
		golem.setFavourite(saved.favourite);
		golem.setCraftNumber(saved.craftNumber);
		if (saved.firstSeen != 0)
		{
			golem.getHistory().restore(saved.firstSeen, saved.transports, saved.voyages, saved.walked,
				saved.furthestX, saved.furthestY, home);
		}
		golem.getHistory().restoreJournal(saved.journal);
		golem.setInInstance(saved.inInstance);
		golem.setShoreLeaveUntil(saved.shoreLeaveUntil);
		return golem;
	}
}

package com.golemsdontdie;

import java.util.regex.*;
import javax.inject.*;
import lombok.*;
import lombok.extern.slf4j.*;
import net.runelite.client.config.*;

/**
 * How many golems the player has ever crafted, read from the game's own count.
 *
 * <p>The plugin's roster is not the player's history: golems made before it was installed were
 * never taken over, and ones culled or dismissed are gone. The gap is what the revive button
 * offers to close. The total only ever goes up, a lower figure being treated as a misread line,
 * because reading some other line as a smaller total would silently offer too few golems.
 *
 * <p>{@link GolemContent#GOLEM_COUNT_VARBIT} arrives with the player's variables at login, so
 * golems crafted on mobile or before the plugin was installed are counted by the next login
 * rather than staying wrong until the next craft. The chat line on every craft reports the same
 * number and is a backstop: it does not depend on the varbit meaning what it appears to, and is
 * not capped at 65,535. Counting golem spawns was dropped - on a shared island it would tally
 * other players' golems.
 */
@Slf4j
@Singleton
class GolemTally
{
	/** Config key for the running total. Plugin-written, so not a config item. */
	static final String TOTAL_KEY = "totalGolemsCrafted";

	/**
	 * The game's own tally line, sent each time a golem is finished:
	 * <pre>You have crafted 374 golems on Wyrmscraig.</pre>
	 *
	 * <p>Matched precisely, not by keywords: a loose test would read "You need 5 stone chunks to
	 * build a golem" as a total of five. The trailing "on Wyrmscraig" is not required.
	 */
	private static final Pattern TOTAL_MESSAGE =
		Pattern.compile("(?i)\\byou have crafted\\s+([\\d,]+)\\s+golems?\\b");

	@Inject
	private ConfigManager configManager;

	/** Golems crafted, ever. Zero until a message says otherwise. */
	@Getter
	private int total;

	/** The account the total is kept for, as a RuneScape profile key; null before login. */
	private String account;

	/**
	 * Takes up an account's total.
	 *
	 * @param stored the total as it was saved for that account, or null for none
	 */
	void load(String account, String stored)
	{
		this.account = account;
		total = 0;
		if (stored == null || stored.trim().isEmpty())
		{
			return;
		}
		try
		{
			total = Math.max(0, Integer.parseInt(stored.trim()));
		}
		catch (NumberFormatException e)
		{
			log.debug("Stored golem total '{}' unreadable", stored);
		}
	}

	/**
	 * Offers a chat line to the tally.
	 *
	 * @return true if the total changed, so the panel can be redrawn
	 */
	boolean observe(String message)
	{
		if (message == null || message.isEmpty())
		{
			return false;
		}

		Matcher matcher = TOTAL_MESSAGE.matcher(message);
		if (!matcher.find())
		{
			return false;
		}

		int found;
		try
		{
			found = Integer.parseInt(matcher.group(1).replace(",", ""));
		}
		catch (NumberFormatException e)
		{
			// A number too large for an int is not a golem count.
			return false;
		}

		return setTotal(found);
	}

	/**
	 * Offers the game's own count, read from {@link GolemContent#GOLEM_COUNT_VARBIT}. Refusing
	 * to go backwards covers every awkward case: a varbit read before the server sends it is 0,
	 * and a count past sixteen bits pins at 65,535 or wraps small, by which point the chat line
	 * carries the real figure.
	 *
	 * @return true if the total changed, so the panel can be redrawn
	 */
	boolean observeCount(int count)
	{
		return setTotal(count);
	}

	/**
	 * Raises the total. Ignores anything that would lower it.
	 *
	 * @return true if the total changed
	 */
	boolean setTotal(int candidate)
	{
		if (candidate <= total)
		{
			return false;
		}
		total = candidate;
		if (account != null)
		{
			configManager.setConfiguration(GolemsDontDieConfig.GROUP, account, TOTAL_KEY, String.valueOf(total));
		}
		log.debug("Golems crafted total is now {}", total);
		return true;
	}

}

package com.golemsdontdie;

import net.runelite.api.*;
import static com.golemsdontdie.RouteGeometry.span;

/**
 * How much of a golem needs simulating, decided by how close the player is to it.
 *
 * <p>A golem nobody can see costs <em>no tick</em> at all. The gate used to be whether the
 * player was near Wyrmscraig; once golems can be anywhere it is asked per golem. Tiers are
 * spatial, not scheduled: a golem is in whichever tier its distance puts it in each frame,
 * so crossing a boundary costs one action, not an ongoing one.
 */
enum GolemTier
{
	/** Inside the loaded scene, on the player's plane. Drawn, clickable, stepped each frame. */
	SCENE,

	/**
	 * Outside the scene but close enough to walk into view shortly. Simulated in full like
	 * {@link #SCENE}, just not drawn.
	 *
	 * <p>A coarse once-a-second step here was dropped: the previous version stepped every
	 * golem in full near Wyrmscraig and handled hundreds, so the saving is not needed, and
	 * a throttled golem would enter the scene up to a second out of place - precisely the
	 * boundary where that shows.
	 */
	NEAR,

	/** Everywhere else, land or sea. A route and a start time, resolved only when asked. */
	FAR;

	/**
	 * Tiles beyond the scene edge that still count as near: roughly two regions. Wide enough
	 * that a golem has somewhere to be as the player approaches, narrow enough to stay cheap.
	 */
	private static final int NEAR_RANGE = 128;

	/**
	 * Which tier a golem at these world coordinates falls into. Plane is part of the scene
	 * test: a golem two floors up is not in the player's scene, even though its tile is.
	 */
	static GolemTier of(WorldView wv, int worldX, int worldY, int plane,
		int playerX, int playerY, int playerPlane)
	{
		if (wv == null)
		{
			return FAR;
		}

		int localX = worldX - wv.getBaseX();
		int localY = worldY - wv.getBaseY();
		boolean inScene = localX >= 0 && localY >= 0
			&& localX < wv.getSizeX() && localY < wv.getSizeY();

		if (inScene && plane == playerPlane)
		{
			return SCENE;
		}

		// Chebyshev, not Euclidean: the scene and the ring around it are squares.
		int distance = span(worldX - playerX, worldY - playerY);
		return distance <= NEAR_RANGE ? NEAR : FAR;
	}
}

package com.golemsdontdie;

import java.util.*;
import lombok.*;

/**
 * What a golem is like: a handful of traits it keeps for life.
 *
 * <p>Drawn from the golem's own seed when it is made, and saved with it from then on, so they never
 * change. Most golems have one or two; five is rare.
 *
 * <p>Some lean on the chances the planner already rolls, which is what makes a golem that likes the
 * cold spend its life in the snow. The rest are only true of it, and wait for the golem's own page
 * to be read.
 *
 * <p>A golem's traits are saved as a mask of this list's order, so a trait is only ever added at the
 * end: reordering the list would give every saved golem somebody else's. Changing a weight or a
 * clash changes only the hands dealt to golems made after it.
 */
@Getter
@AllArgsConstructor
enum GolemTrait
{
	// ------------------------------------------------------------------ what a golem does

	LIKES_THE_COLD("Likes the cold", "Happiest in snow and ice.", 3),
	LIKES_THE_HEAT("Likes the heat", "Drawn to the desert.", 3),
	TEMPERATE("Temperate", "It keeps to the green places.", 3),
	HOMESICK("Homesick", "Never away from Wyrmscraig for long.", 3),
	SEAFARER("Seafarer", "Takes to the water every chance it gets.", 3),
	SPELUNKER("Spelunker", "Goes down whenever there is a down to go.", 3),
	CLIMBER("Climber", "Ladders, stairs and cliffs: anything that leads up.", 3),
	RESTLESS("Restless", "Can't stand still.", 3),
	CROWD_SHY("Shy", "Keeps away from other golems.", 3),
	SOCIABLE("Sociable", "Loves a crowd.", 3),
	CAUTIOUS("Cautious", "Will not risk danger.", 3),
	SURE_FOOTED("Sure-footed", "Actually likes Agility.", 3),

	// ------------------------------------------------------------------ what a golem is
	//
	// Mostly flavour for the golem's own page; Friendly and Life of the party also change what a
	// golem does, waving and dancing. Nothing here claims anything about how a golem looks: they are all carved from the same rock, and a page saying otherwise would
	// be contradicted by the golem standing in front of you.

	FRIENDLY("Friendly", "Will probably say hello.", 6),
	LIFE_OF_THE_PARTY("Life of the party", "Loves to boogie.", 4),
	PONDEROUS("Ponderous", "Thinks things over. At length.", 6),
	HUMS("Hums to itself", "Hmmmmm.", 5),
	OLD_SOUL("Old soul", "Just needs a nap.", 4),
	SUPERSTITIOUS("Superstitious", "Avoids black cats.", 4),
	STOIC("Stoic", "Never complains.", 5),
	CURIOUS("Curious", "Always looking for something new.", 5),
	LUCKY("Lucky", "Things just work out.", 4),
	PATIENT("Patient", "Whatever it is waiting for, it will wait.", 5),
	COUNTS_THINGS("Counts things", "Stones, steps, golems. Quietly.", 5),
	FOND_OF_GOATS("Fond of goats", "Has views on the Wyrmscraig goat, and holds them firmly.", 4),
	LOYAL("Loyal", "Would never betray you.", 5);

	/** What the golem's page calls this. */
	private final String label;

	/** A line for the golem's page. */
	private final String description;

	/**
	 * How often this comes up, against the others. Cosmetic traits are commoner than ones that
	 * change what a golem does: a golem with four habits pulling against each other has none.
	 */
	private final int weight;

	private static final GolemTrait[] ALL = values();

	/**
	 * For each trait, the traits it pulls against, as a mask, and a golem is never dealt both. A
	 * golem both homesick and fond of the cold wants to be in the snow on Wyrmscraig, which is
	 * nowhere, and it would simply stand about; one both shy and the life of the party is two
	 * golems. Kept as a table rather than a group apiece because a trait can pull against several
	 * that sit happily together: restless is against patient and against an old soul, and those two
	 * are the same golem.
	 */
	private static final int[] CLASHES = new int[ALL.length];

	static
	{
		// Somewhere it wants to be: the weather it likes, or home. Any two are two places at once.
		clash(LIKES_THE_COLD, LIKES_THE_HEAT, TEMPERATE, HOMESICK);
		clash(LIKES_THE_HEAT, TEMPERATE, HOMESICK);
		clash(TEMPERATE, HOMESICK);
		// A view on obstacles, and a direction in a stairwell.
		clash(CAUTIOUS, SURE_FOOTED);
		clash(SPELUNKER, CLIMBER);
		// Company: a shy golem keeps away from the ones that come looking for it. Friendly and the
		// life of the party are both sociable in their way, and sit with it and each other.
		clash(CROWD_SHY, SOCIABLE, FRIENDLY, LIFE_OF_THE_PARTY);
		// Pace: a golem that can't stand still is none of the ones that wait, nap or think it over.
		clash(RESTLESS, PATIENT, OLD_SOUL, PONDEROUS);
		// A golem that just needs a nap is not the one still dancing.
		clash(OLD_SOUL, LIFE_OF_THE_PARTY);
	}

	/** The first trait against each of the rest, both ways; the rest may still sit together. */
	private static void clash(GolemTrait trait, GolemTrait... against)
	{
		for (GolemTrait other : against)
		{
			CLASHES[trait.ordinal()] |= other.mask();
			CLASHES[other.ordinal()] |= trait.mask();
		}
	}

	/** Whether a golem may never be dealt both of these. */
	boolean clashesWith(GolemTrait other)
	{
		return (CLASHES[ordinal()] & other.mask()) != 0;
	}

	/** How many traits a golem may have. The draw leans hard on the low end. */
	static final int MOST_TRAITS = 5;

	/**
	 * The traits belonging to a seed, as a bitmask.
	 *
	 * <p>Drawn from a generator of its own rather than the golem's, so that asking a golem what it is
	 * like never disturbs where it walks: the two would otherwise share a sequence, and a golem's
	 * traits would change what it did next.
	 */
	static int of(long seed)
	{
		Random random = new Random(seed * 0x9E3779B97F4A7C15L ^ 0x5DEECE66DL);
		int count = 1;
		// Each further trait is less than half as likely as the one before: most golems have one or two.
		while (count < MOST_TRAITS && random.nextFloat() < 0.4f)
		{
			count++;
		}

		int total = 0;
		for (GolemTrait trait : ALL)
		{
			total += trait.weight;
		}

		int traits = 0;
		List<GolemTrait> left = new ArrayList<>(ALL.length);
		Collections.addAll(left, ALL);
		for (int i = 0; i < count && !left.isEmpty(); i++)
		{
			int roll = random.nextInt(total);
			GolemTrait drawn = left.get(left.size() - 1);
			for (GolemTrait trait : left)
			{
				roll -= trait.weight;
				if (roll < 0)
				{
					drawn = trait;
					break;
				}
			}
			traits |= drawn.mask();
			total -= drawn.weight;
			left.remove(drawn);
			// Nothing that pulls against what it just drew: see CLASHES.
			for (Iterator<GolemTrait> rest = left.iterator(); rest.hasNext(); )
			{
				GolemTrait trait = rest.next();
				if (drawn.clashesWith(trait))
				{
					total -= trait.weight;
					rest.remove();
				}
			}
		}
		return traits;
	}

	boolean in(int traits)
	{
		return (traits & mask()) != 0;
	}

	/** This trait alone, as a mask. */
	int mask()
	{
		return 1 << ordinal();
	}

	/** The traits in a mask, in the order they are declared. */
	static List<GolemTrait> list(int traits)
	{
		List<GolemTrait> found = new ArrayList<>();
		for (GolemTrait trait : ALL)
		{
			if (trait.in(traits))
			{
				found.add(trait);
			}
		}
		return found;
	}
}

package com.golemsdontdie;

import lombok.*;
import net.runelite.api.coords.*;

/**
 * One way of getting from one tile to another that is not walking: a door, a ladder, a stile,
 * a ferry.
 *
 * <p>From Shortest Path's tables, reduced offline to the rows a golem could use, which is most of them. Immutable and shared: ~13,000 rows, one set
 * for every golem, built once at startup. Requirements are parsed arrays, not strings, because a
 * golem tests them on every tile it enters near a transport.
 */
final class GolemTransport
{
	// Archetypes. Written into the shipped table; the numbering is a file format, so append only -
	// changing a value silently remaps every row in the shipped resource.
	static final int ARCHETYPE_NONE = 0;
	static final int ARCHETYPE_DOOR = 1;
	static final int ARCHETYPE_LADDER = 2;
	static final int ARCHETYPE_CLIMB = 3;
	static final int ARCHETYPE_DITCH = 4;
	static final int ARCHETYPE_JUMP = 5;
	static final int ARCHETYPE_GANGPLANK = 6;
	static final int ARCHETYPE_CLIMB_OVER = 7;
	static final int ARCHETYPE_SQUEEZE = 8;
	static final int ARCHETYPE_BALANCE = 9;
	static final int ARCHETYPE_STILE = 10;
	static final int ARCHETYPE_TIGHTROPE = 11;

	/**
	 * Stairs: walked up or down, nothing played. They were ladders before, so a golem reached up
	 * for a rung at the foot of every staircase in the game.
	 */
	static final int ARCHETYPE_STAIRS = 12;

	@Getter
	private final int fromX;
	@Getter
	private final int fromY;
	@Getter
	private final int fromPlane;
	@Getter
	private final int toX;
	@Getter
	private final int toY;
	@Getter
	private final int toPlane;

	/** Travel time in game ticks, as authored for a player. */
	@Getter
	private final int duration;

	/** Which animation set to play, decided offline from the menu text. */
	@Getter
	private final int archetype;

	/**
	 * The scene object this transport is, or -1, read from the menu column offline ("Cross
	 * Gangplank 12164"). It finds the object's model and animation, which
	 * {@code ObjectComposition} does not expose at runtime.
	 */
	@Getter
	private final int objectId;

	/** Pairs of (level, skill ordinal). Empty if ungated. */
	private final int[] skillRequirements;

	/** Quest ordinals that must be finished. Empty if ungated. */
	private final int[] questRequirements;

	/** Triples of (id, operator, value). See {@link GolemAbilities}. */
	private final int[] varbitRequirements;
	private final int[] varpRequirements;

	/**
	 * Index of the row that undoes this one, or -1. Resolved once when the network is built,
	 * because searching per decision would scan 13,000 rows per golem per tile.
	 */
	@Getter
	private int reverse = -1;

	/**
	 * This row's own index in the network, carried rather than looked up: cooldowns are keyed by
	 * index and tested for every candidate on every tile a golem enters, so a lookup would scan
	 * the whole table on the hottest path here.
	 */
	@Getter
	private int index = -1;

	GolemTransport(int fromX, int fromY, int fromPlane, int toX, int toY, int toPlane,
		int duration, int archetype, int objectId, int[] skills, int[] quests, int[] varbits,
		int[] varps)
	{
		this.objectId = objectId;
		this.fromX = fromX;
		this.fromY = fromY;
		this.fromPlane = fromPlane;
		this.toX = toX;
		this.toY = toY;
		this.toPlane = toPlane;
		this.duration = duration;
		this.archetype = archetype;
		this.skillRequirements = skills;
		this.questRequirements = quests;
		this.varbitRequirements = varbits;
		this.varpRequirements = varps;
	}

	/** A learned route that goes into an instance, or comes out of one. See {@link InstanceMap}. */
	static final int INTO_INSTANCE = 1;
	static final int OUT_OF_INSTANCE = 2;

	/**
	 * {@link #INTO_INSTANCE}, {@link #OUT_OF_INSTANCE}, or neither. A golem through the pew is
	 * where nobody outside can see it, and one in the instance's copy of the island is not in
	 * the instance at all - identical in coordinates, since an instance is its template's.
	 */
	@Getter
	private int instanceFlags;

	/**
	 * True for a row the tables infer rather than calculate - a pad's partner worked out by
	 * nearness, the far side of an agility object - shipped so the ground behind it is known, but
	 * not used until golems have seen a player use it. See {@link ObstacleKnowledge#isUnlocked}.
	 */
	@Getter
	private boolean learnFirst;

	/**
	 * Which way a climb goes, from its verb, decided offline: 1 up, -1 down, 0 not said. The plane
	 * alone cannot say: a ladder out of a dungeon is plane 0 to plane 0, and 617 of them played the
	 * descent.
	 */
	@Getter
	private int direction;

	void setDirection(int direction)
	{
		this.direction = direction;
	}

	/** True for a climb upward: by its verb where it has one, by the plane change otherwise. */
	boolean goesUp()
	{
		return direction != 0 ? direction > 0 : toPlane > fromPlane;
	}

	/** True for a climb downward, likewise. */
	boolean goesDown()
	{
		return direction != 0 ? direction < 0 : toPlane < fromPlane;
	}

	void setLearnFirst(boolean learnFirst)
	{
		this.learnFirst = learnFirst;
	}

	void setInstanceFlags(int flags)
	{
		this.instanceFlags = flags;
	}

	boolean entersInstance()
	{
		return (instanceFlags & INTO_INSTANCE) != 0;
	}

	boolean leavesInstance()
	{
		return (instanceFlags & OUT_OF_INSTANCE) != 0;
	}

	/**
	 * The same journey the other way, for a golem somewhere it knows no other way out of. Not a
	 * row in the network; only {@link RoamPlanner#wayHome} produces it. The player may have
	 * entered a cave and teleported out, so nothing leaving it was ever learned and golems that
	 * followed gathered underground for good. Not what the game does, but it beats never coming
	 * out.
	 */
	GolemTransport backThrough()
	{
		GolemTransport back = new GolemTransport(toX, toY, toPlane, fromX, fromY, fromPlane, duration, archetype,
			objectId, new int[0], new int[0], new int[0], new int[0]);
		back.instanceFlags = (entersInstance() ? OUT_OF_INSTANCE : 0) | (leavesInstance() ? INTO_INSTANCE : 0);
		back.learnFirst = learnFirst;
		back.direction = -direction;
		return back;
	}

	void setReverse(int index)
	{
		this.reverse = index;
	}

	void setIndex(int index)
	{
		this.index = index;
	}

	/** Both ends of this journey as one number. Rows with the same key go the same way. */
	long endpointKey()
	{
		return TransportNetwork.endpoints(getFromX(), getFromY(), getFromPlane(),
			getToX(), getToY(), getToPlane());
	}

	/** The key of the journey that undoes this one. */
	long reverseKey()
	{
		return TransportNetwork.endpoints(getToX(), getToY(), getToPlane(),
			getFromX(), getFromY(), getFromPlane());
	}

	WorldPoint destination()
	{
		return new WorldPoint(toX, toY, toPlane);
	}

	int[] skills()
	{
		return skillRequirements;
	}

	int[] quests()
	{
		return questRequirements;
	}

	int[] varbits()
	{
		return varbitRequirements;
	}

	int[] varps()
	{
		return varpRequirements;
	}

	/** True if this transport has no requirements at all - most of the network. */
	boolean isUnconditional()
	{
		return skillRequirements.length == 0 && questRequirements.length == 0
			&& varbitRequirements.length == 0 && varpRequirements.length == 0;
	}

	/**
	 * How far the golem is carried, in tiles, or -1 where the question is meaningless:
	 * underground maps sit ~6,400 tiles north of the surface above them, so a ladder down
	 * measures as a continent-wide journey.
	 */
	int travelDistance()
	{
		int d = Math.abs(fromX - toX) + Math.abs(fromY - toY);
		return d > 64 ? -1 : d;
	}

	/**
	 * The animation that plays while the golem uses this, or -1 for none. Doors are deliberately
	 * silent: the door animates, not the player. Teleport-like transports are -1 too.
	 */
	int animation()
	{
		int[] clips = animations();
		return clips.length == 0 ? -1 : clips[0];
	}

	/**
	 * The clips to play, in order, while the golem uses this. OSRS builds obstacle animations in
	 * threes - mount, loop, dismount - and using only the middle one left nine of twenty
	 * catalogued clips unused. The set comes from the plane change and the distance carried;
	 * clips are shared, so three cost as one.
	 */
	int[] animations()
	{
		// A shortcut somebody has watched beats a guess from menu text: the archetype below
		// was wrong for three of the first four obstacles tried.
		int measured = MeasuredShortcuts.animationFor(objectId);
		if (measured != -1)
		{
			return new int[]{measured};
		}

		switch (archetype)
		{
			case ARCHETYPE_LADDER:
				// Reaching up for a ladder and reaching down off the top are different
				// clips; the plane change says which.
				return new int[]{goesUp()
					? GolemContent.ANIM_LADDER_GRAB
					: GolemContent.ANIM_LADDER_GRAB_TOP};

			case ARCHETYPE_STAIRS:
				return new int[0];

			case ARCHETYPE_CLIMB:
				if (goesDown())
				{
					// Going down is its own clip, not the ascent reversed. Measured on
					// Wyrmscraig: the west approach (62265) plays 740, HUMAN_CLIMBING_DOWN,
					// the east (62267) the climbing loop; three server reimplementations
					// use 740 for a descent too. Only the plane says which way a climb
					// goes, so a cliff on flat ground gets the ascent both ways unless
					// measured - the better failure, as an ascent played descending reads
					// as effortful.
					return new int[]{GolemContent.ANIM_CLIMB_DOWN};
				}
				// Take hold, haul up, step off.
				return new int[]{
					GolemContent.ANIM_CLIMB_READY,
					GolemContent.ANIM_CLIMB_LOOP,
					GolemContent.ANIM_CLIMB_MERGE,
				};

			case ARCHETYPE_DITCH:
				return new int[]{GolemContent.ANIM_DITCH_VAULT};

			case ARCHETYPE_JUMP:
			{
				// A hop between stones and a running leap across a chasm are different
				// movements, and distance is the only thing here that separates them. The
				// thresholds are unverified: only the shortest rung is measured -
				// Wyrmscraig's basalt stones, two tiles, play 741 - and the longer clips
				// come from the catalogue by name. A 2019 server reimplementation plays 741
				// for every stepping stone regardless of span, so the split may not exist.
				int span = travelDistance();
				if (span < 0 || span <= 2)
				{
					// The short hop, measured on Wyrmscraig's basalt stones.
					return new int[]{GolemContent.ANIM_JUMP_STEPPINGSTONE};
				}
				if (span <= 4)
				{
					return new int[]{GolemContent.ANIM_JUMP_GAP};
				}
				return new int[]{span <= 8
					? GolemContent.ANIM_JUMP_STONES
					: GolemContent.ANIM_JUMP_LONG};
			}

			case ARCHETYPE_CLIMB_OVER:
				return new int[]{GolemContent.ANIM_WALL_JUMP};

			case ARCHETYPE_STILE:
				// Stepped over one leg at a time, where a broken wall is vaulted; told
				// apart offline from the menu text.
				return new int[]{GolemContent.ANIM_STILE};

			case ARCHETYPE_TIGHTROPE:
				return new int[]{
					GolemContent.ANIM_BALANCE_WALK,
					GolemContent.ANIM_TIGHTROPE,
					GolemContent.ANIM_BALANCE_WALK,
				};

			case ARCHETYPE_SQUEEZE:
				// Turn sideways, shuffle through, straighten up.
				return new int[]{
					GolemContent.ANIM_SQUEEZE_READY,
					GolemContent.ANIM_SQUEEZE_LOOP,
					GolemContent.ANIM_SQUEEZE_END,
				};

			case ARCHETYPE_BALANCE:
				// Step on, cross, step off.
				return new int[]{
					GolemContent.ANIM_BALANCE_WALK,
					GolemContent.ANIM_BALANCE_WALK_LOOP,
					GolemContent.ANIM_BALANCE_WALK,
				};

			case ARCHETYPE_GANGPLANK:
				// Walking the plank is walking: the golem keeps its gait and the boarding
				// reads from the geometry.
				return new int[]{GolemContent.GOLEM_WALK_ANIMATION};

			case ARCHETYPE_DOOR:
				// Through the door, not by opening it, as at Wyrmscraig's cathedral doors.
				return new int[]{GolemContent.ANIM_DOOR_THROUGH};

			default:
				return new int[0];
		}
	}

	/**
	 * True if this transport is worth drawing an animated copy of the object for. The object's
	 * animation comes from {@link PropFactory} at runtime, so nothing here names clips. Doors
	 * are excluded despite animating: the real object swings when a player opens it, and a
	 * second copy on top of a closed one is a ghost door.
	 */
	boolean wantsPropAnimation()
	{
		return objectId > 0 && archetype != ARCHETYPE_NONE && archetype != ARCHETYPE_DOOR;
	}

	/**
	 * True for what a golem's page counts as a shortcut: something climbed, jumped, squeezed
	 * through or balanced across. Not a door, a ladder or stairs, a gangplank or a teleport,
	 * which every golem uses to get anywhere and which made the count mostly doorways.
	 */
	boolean isShortcut()
	{
		return archetype != ARCHETYPE_NONE && archetype != ARCHETYPE_DOOR
			&& archetype != ARCHETYPE_LADDER && archetype != ARCHETYPE_STAIRS && archetype != ARCHETYPE_GANGPLANK;
	}

	@Override
	public String toString()
	{
		return "(" + fromX + "," + fromY + "," + fromPlane + ") -> ("
			+ toX + "," + toY + "," + toPlane + ") arch=" + archetype;
	}
}

package com.golemsdontdie;

/**
 * How a golem came to be somewhere, as the line in its journal reads.
 *
 * <p>Taken from the transport it used - the tables say what each obstacle is, and a ladder reads
 * differently from a gangplank - or from the crossing it was on. Walking is what is left, and is
 * much the commonest.
 */
enum GolemTravel
{
	WALKED("Walked to"),
	SAILED("Sailed to"),
	CLIMBED("Climbed to"),
	DESCENDED("Climbed down to"),
	SQUEEZED("Squeezed through to"),
	CROSSED("Crossed to"),
	JUMPED("Jumped across to"),
	BOARDED("Took a gangplank to"),
	/** Underground, arrived at on foot: a golem that walked into the dark went exploring. */
	EXPLORED("Explored");

	private final String verb;

	GolemTravel(String verb)
	{
		this.verb = verb;
	}

	/** The whole line, as the journal shows it. */
	String line(String place)
	{
		return verb + " " + place;
	}

	/**
	 * What an obstacle of this kind reads as. The plane says which way a climb went: the same
	 * ladder is climbed and climbed down.
	 */
	static GolemTravel of(GolemTransport transport)
	{
		switch (transport.getArchetype())
		{
			case GolemTransport.ARCHETYPE_LADDER:
			case GolemTransport.ARCHETYPE_STAIRS:
			case GolemTransport.ARCHETYPE_CLIMB:
				return transport.goesDown() ? DESCENDED : CLIMBED;
			default:
				return of(transport.getArchetype(), transport.getFromPlane(), transport.getToPlane());
		}
	}

	static GolemTravel of(int archetype, int fromPlane, int toPlane)
	{
		switch (archetype)
		{
			case GolemTransport.ARCHETYPE_LADDER:
			case GolemTransport.ARCHETYPE_STAIRS:
			case GolemTransport.ARCHETYPE_CLIMB:
				return toPlane < fromPlane ? DESCENDED : CLIMBED;
			case GolemTransport.ARCHETYPE_SQUEEZE:
				return SQUEEZED;
			case GolemTransport.ARCHETYPE_JUMP:
			case GolemTransport.ARCHETYPE_DITCH:
				return JUMPED;
			case GolemTransport.ARCHETYPE_BALANCE:
			case GolemTransport.ARCHETYPE_TIGHTROPE:
			case GolemTransport.ARCHETYPE_STILE:
				return CROSSED;
			case GolemTransport.ARCHETYPE_GANGPLANK:
				return BOARDED;
			default:
				// Doors and everything unnamed: a golem went through and carried on walking.
				return WALKED;
		}
	}

	private static final GolemTravel[] ALL = values();

	static GolemTravel byOrdinal(int ordinal)
	{
		return ordinal >= 0 && ordinal < ALL.length ? ALL[ordinal] : WALKED;
	}
}

package com.golemsdontdie;

import java.util.List;
import lombok.*;

/**
 * One crossing a golem made in view: the route it used, and where it actually was while using it.
 *
 * <p>The golem's half of the obstacle record, so a slanted crossing shows up as a number; see
 * ObstacleDataBridge. Positions are in 128ths of a tile, as golems are simulated. Only short,
 * same-floor crossings are traced: a ladder has no path across it to be wrong about.
 */
@AllArgsConstructor
final class GolemTraversal
{
	final GolemTransport route;

	/** Where the golem was when the crossing began and when it let go. */
	final int startX;
	final int startY;
	final int endX;
	final int endY;

	/** {cycles since the start, x, y}, a frame apart. */
	final List<int[]> samples;
}

