	private static final int MIMIC_TILES = 8;
	private static final float MIMIC_CHANCE = 0.5f;
	private static final int MIMIC_TICKS = 7;

	/**
	 * The emote the player has just begun, or -1. Read once a tick and held until it changes, so
	 * a four-second dance is one thing to copy rather than seven.
	 */
	private int playerEmote = -1;
	private int lastPlayerAnimation = -1;

	/** How near the player a friendly golem waves, the chance it does, and how long a wave takes. */
	private static final int GREET_TILES = 6;
	private static final float GREET_CHANCE = 0.05f;
	private static final int GREET_TICKS = 4;

	/**
	 * Ticks after a friendly golem's first wave before it may wave again: six seconds, doubling
	 * with each wave after it. At a steady six seconds a golem stood beside waved at the player
	 * every few seconds for as long as they stood there.
	 */
	private static final int GREET_GAP_TICKS = 10;

	/** The chance a friendly golem waves each tick when it first sees the player: likely, soon. */
	private static final float FIRST_GREET_CHANCE = 0.35f;

	/** How long the player must have been away before a friendly golem greets them afresh: 30s. */
	private static final int AWAY_TICKS = 50;

	/** The last tick the golems were asked whether they felt sociable. */
	private int lastSocialTick = -1;

	/** Whose fireworks go off and who feels like dancing: the golems' own generators are theirs. */
	private final Random moods = new Random();

	/** Models for the celebration, built once each: see GolemContent. */
	private final Map<Integer, Model> celebrationModels = new HashMap<>();

	/**
	 * Draws the fireworks over a golem. The client plays these on an actor, and a golem is a
	 * model of our own rather than an actor, so its model and sequence are drawn as scenery.
	 */
	private void spawnFirework(Golem golem, WorldView wv)
	{
		spawnAtGolem(golem, wv, GolemContent.FIREWORK_MODEL, GolemContent.FIREWORK_ANIMATION,
			GolemContent.FIREWORK_CYCLES);
	}

	/** Draws whatever the golem's dance move needs beside it: the air guitar's guitar. */
	private void spawnDanceProp(Golem golem, WorldView wv)
	{
		GolemDance move = golem.getDanceMove();
		if (move == null || move.getSpotanim() != GolemContent.SPOTANIM_AIR_GUITAR)
		{
			return;
		}
		spawnAtGolem(golem, wv, GolemContent.AIR_GUITAR_MODEL, GolemContent.AIR_GUITAR_ANIMATION,
			GolemContent.DANCE_PROP_CYCLES);
	}

	/**
	 * Draws a model on the golem's own tile, playing its own animation for a while. The golem
	 * stands still while it dances, so nothing has to follow it.
	 */
	private void spawnAtGolem(Golem golem, WorldView wv, int modelId, int animationId, int cycles)
	{
		if (wv == null)
		{
			return;
		}
		// Where the golem is drawn, which inside an instance is not where it is simulated.
		int localX = golem.getDrawFineX() - wv.getBaseX() * Golem.TILE;
		int localY = golem.getDrawFineY() - wv.getBaseY() * Golem.TILE;
		if (!Golem.isInScene(wv, localX, localY))
		{
			return;
		}
		Model model = celebrationModel(modelId);
		if (model == null)
		{
			return;
		}
		// And on the floor it is drawn on: inside an instance that is not the one it is simulated
		// on either, and fireworks went off a floor above or below it.
		int height = Perspective.getTileHeight(client,
			new LocalPoint(localX, localY, wv), golem.getDrawPlane());
		FakeProp drawn = new FakeProp(client, model, modelFactory.animationFor(animationId),
			animationId, golem.getDrawFineX(), golem.getDrawFineY(), golem.getDrawPlane(), height, cycles);
		drawn.setFacing(golem::drawOrientation);
		client.registerRuneLiteObject(drawn);
		props.add(drawn);
	}

	/** A celebration model, lit as the props are and kept: there are two of them and they repeat. */
	private Model celebrationModel(int modelId)
	{
		Model cached = celebrationModels.get(modelId);
		if (cached != null)
		{
			return cached;
		}
		try
		{
			ModelData data = client.loadModelData(modelId);
			if (data == null)
			{
				return null;
			}
			Model built = data.cloneVertices().light();
			celebrationModels.put(modelId, built);
			return built;
		}
		catch (RuntimeException e)
		{
			log.debug("Celebration model {} would not load", modelId, e);
			return null;
		}
	}

	/**
	 * Watches what the player is doing, so golems can copy it.
	 *
	 * <p>Only the emote tab's own clips, and only the moment one begins: an emote held for four
	 * seconds is one thing to copy, and a combat or skilling animation is not an emote at all.
	 */
	private void noteEmote()
	{
		Player me = client.getLocalPlayer();
		int animation = me == null ? -1 : me.getAnimation();
		playerEmote = animation != lastPlayerAnimation && GolemContent.isEmote(animation) ? animation : -1;
		lastPlayerAnimation = animation;
	}

	/**
	 * What a golem does because of what it is like: the life of the party dances when there is a
	 * crowd to dance in, and a friendly golem waves at the player.
	 *
	 * <p>Once a tick per golem in the scene, and only for the two traits that ask for it, so the
	 * count of who is nearby is paid for by the few golems that have them.
	 */
	private void beSociable(Golem golem, int tick, WorldPoint playerAt)
	{
		// Not mid-climb or at sea either: a golem turned to stare while crossing a log balance
		// stopped where it was, on nothing.
		if (!freeToWave(golem, tick))
		{
			return;
		}

		// Curiosity, which is about the player being a rarity rather than about the golem: one
		// golem in an empty field stares, one of thirty at the plinth has seen you before.
		if (playerAt != null && drawnGolems.size() <= WATCHING_CROWD)
		{
			WorldPoint at = golem.currentTile();
			int away = at.getPlane() == playerAt.getPlane() ? at.distanceTo2D(playerAt) : Integer.MAX_VALUE;
			int dx = playerAt.getX() - at.getX();
			int dy = playerAt.getY() - at.getY();
			if (playerEmote != -1 && away <= MIMIC_TILES && moods.nextFloat() < MIMIC_CHANCE)
			{
				golem.mimic(tick + MIMIC_TICKS, dx, dy, playerEmote);
				return;
			}
			if (away <= WATCH_TILES && moods.nextFloat() < WATCH_CHANCE)
			{
				golem.watch(tick + WATCH_TICKS, dx, dy);
				return;
			}
		}

		if (playerAt != null && GolemTrait.FRIENDLY.in(golem.getTraits()))
		{
			WorldPoint at = golem.currentTile();
			if (at.getPlane() == playerAt.getPlane() && at.distanceTo2D(playerAt) <= GREET_TILES)
			{
				// A wave soon after the player comes by, then fewer and fewer while they stay.
				int gap = golem.playerWaveGap(tick, GREET_GAP_TICKS, AWAY_TICKS);
				float chance = golem.hasWavedAtPlayer() ? GREET_CHANCE : FIRST_GREET_CHANCE;
				if (golem.mayGreetAgain(tick, gap) && moods.nextFloat() < chance)
				{
					// Turned to face the player: a wave over its shoulder is not a greeting.
					golem.greetPlayer(tick + GREET_TICKS, playerAt.getX() - at.getX(), playerAt.getY() - at.getY());
					return;
				}
			}
		}

		if (GolemTrait.LIFE_OF_THE_PARTY.in(golem.getTraits())
			&& moods.nextFloat() < PARTY_CHANCE && company(golem) >= COMPANY)
		{
			golem.startParty(tick + PARTY_TICKS);
		}
	}

	/**
	 * A golem aboard the player's ship copies the player's emote, as one near them ashore does,
	 * where it stands at the rail. Aboard it is never far from the player and never lost in a
	 * crowd, so only the chance is asked; it faces out over the water whatever it is doing.
	 */
	private void mimicAboard(Golem golem, int tick, WorldPoint playerAt)
	{
		if (playerEmote == -1 || golem.isGreeting(tick) || moods.nextFloat() >= MIMIC_CHANCE)
		{
			return;
		}
		WorldPoint at = golem.currentTile();
		golem.mimic(tick + MIMIC_TICKS, playerAt.getX() - at.getX(), playerAt.getY() - at.getY(), playerEmote);
	}

	/** How near two golems alone together must be to wave at each other, in tiles. */
	private static final int PAIR_TILES = 8;

	/** How long before a golem waves at another golem again, in ticks: five minutes. */
	private static final int PAIR_COOLDOWN_TICKS = 500;

	/**
	 * Two golems with nobody else about wave at each other, once.
	 *
	 * <p>Only when they are the only two golems in view: in a crowd a golem has others all round
	 * it and greeting each would be all it did, while two meeting on an empty road is exactly when
	 * people raise a hand. Once, and then not again for five minutes, so a pair walking the same
	 * way is not waving the whole length of it.
	 */
	private void greetEachOther(int tick)
	{
		if (drawnGolems.size() != 2)
		{
			return;
		}
		Golem one = drawnGolems.get(0);
		Golem other = drawnGolems.get(1);
		if (!freeToWave(one, tick) || !freeToWave(other, tick) || one.getPlane() != other.getPlane()
			|| !one.mayWaveAtGolem(tick, PAIR_COOLDOWN_TICKS) || !other.mayWaveAtGolem(tick, PAIR_COOLDOWN_TICKS))
		{
			return;
		}
		WorldPoint a = one.currentTile();
		WorldPoint b = other.currentTile();
		int apart = a.distanceTo2D(b);
		// Not two golems standing in one another either: there is no turning to face that.
		if (apart < 1 || apart > PAIR_TILES)
		{
			return;
		}
		one.waveAtGolem(tick + GREET_TICKS, b.getX() - a.getX(), b.getY() - a.getY(), tick);
		other.waveAtGolem(tick + GREET_TICKS, a.getX() - b.getX(), a.getY() - b.getY(), tick);
	}

	/** Whether a golem is doing nothing that a wave would interrupt. */
	private static boolean freeToWave(Golem golem, int tick)
	{
		return !golem.isDying() && !golem.isDancing() && !golem.isMidMove() && !golem.isGreeting(tick) && !golem.isPartying(tick)
			&& !golem.inTransition() && !golem.isSailing(tick) && !golem.isAboard();
	}

	/** How many other golems are within a few tiles of this one, counted up to what is asked. */
	private int company(Golem golem)
	{
		WorldPoint at = golem.currentTile();
		int near = 0;
		for (Golem other : drawnGolems)
		{
			if (other != golem && other.getPlane() == at.getPlane()
				&& other.currentTile().distanceTo2D(at) <= COMPANY_TILES && ++near >= COMPANY)
			{
				return near;
			}
		}
		return near;
	}

	/** Unregisters scenery whose animation has run out. */
	private void advanceProps()
	{
		for (Iterator<FakeProp> it = props.iterator(); it.hasNext(); )
		{
			FakeProp prop = it.next();
			if (prop.isFinished())
			{
				client.removeRuneLiteObject(prop);
				it.remove();
			}
		}
	}

	/** Drops every scenery copy, finished or not. */
	private void clearProps()
	{
		for (FakeProp prop : props)
		{
			client.removeRuneLiteObject(prop);
		}
		props.clear();
	}

	/**
	 * Drops golems whose crumble has finished. Separate from the loop above so the roster is
	 * not modified while being walked.
	 */
	private void reapCrumbled()
	{
		for (Iterator<Golem> it = golems.iterator(); it.hasNext(); )
		{
			Golem golem = it.next();
			if (golem.isCrumbled())
			{
				detachRenderer(golem);
				it.remove();
				rosterChanged = true;
			}
		}
	}

	/**
	 * Most golems drawn on one tile. The game draws only a few objects per tile, and with more
	 * than that on one it chose a different few each frame and they flashed; the roster is
	 * walked in a fixed order instead, so the first few keep their place and the rest wait.
	 */
	private static final int MAX_DRAWN_PER_TILE = 4;

	/**
	 * Which tier a golem is in, and where it is drawn. Inside an instance, a golem standing in a
	 * chunk it was built from is in the scene, drawn at the matching place on the instance's
	 * plane; every other golem is judged by its distance from the player in template terms,
	 * which puts the overworld out of range.
	 */
	private GolemTier tierFor(Golem golem, WorldView wv, WorldPoint playerAt, WorldPoint playerTemplate,
		Map<Long, List<int[]>> sceneChunks)
	{
		int tileX = golem.getFineX() / Golem.TILE;
		int tileY = golem.getFineY() / Golem.TILE;

		// Where a golem stands says whether it is in an instance, whatever it was told on the
		// way: the room exists only as a copy walked in template coordinates. Told wrongly, it
		// was drawn in the wrong world - golems that had climbed out of the Mad Angel's room
		// went on walking the instance's copy of the island. The flag was only set by the
		// crossing, and one performed as a walk, or cut short by going out of view, never set
		// it.
		if (!instanceRoomTiles.isEmpty())
		{
			boolean inRoom = instanceRoomTiles.contains(RoamContext.tileKey(tileX, tileY, golem.getPlane()));
			if (golem.isInInstance() != inRoom && !golem.inTransition())
			{
				golem.setInInstance(inRoom);
			}
		}
		if (sceneChunks == null)
		{
			golem.setDrawOffset(0, 0, -1);
			// A golem in an instance is somewhere the overworld cannot see, even though it
			// is simulated in the template room - a real, sealed room on the island.
			if (golem.isInInstance())
			{
				return GolemTier.FAR;
			}
			return playerAt == null ? GolemTier.FAR
				: GolemTier.of(wv, tileX, tileY, golem.getPlane(), playerAt.getX(), playerAt.getY(), playerAt.getPlane());
		}

		int[] drawn = placeInInstance(golem, wv, playerAt, sceneChunks);
		if (drawn != null)
		{
			return playerAt == null ? GolemTier.FAR
				: GolemTier.of(wv, drawn[0], drawn[1], drawn[2], playerAt.getX(), playerAt.getY(), playerAt.getPlane());
		}
		return GolemTier.FAR;
	}

	/** The template chunks of the instance whose floors were last admitted; see admitInstanceFloors. */
	private Set<Long> admittedInstance = Collections.emptySet();

	/**
	 * Counts the spaces of every template chunk the loaded instance is built from as ground golems
	 * may stand on, once per instance. See WorldMesh.admitInstanceFloors.
	 */
	private void admitInstanceFloors(Map<Long, List<int[]>> sceneChunks)
	{
		if (sceneChunks == null || sceneChunks.keySet().equals(admittedInstance))
		{
			return;
		}
		admittedInstance = new HashSet<>(sceneChunks.keySet());
		Set<Integer> floors = new HashSet<>();
		for (long chunk : admittedInstance)
		{
			int plane = (int) (chunk >> 40);
			int baseX = (int) (chunk >> 20 & 0xFFFFF) << 3;
			int baseY = (int) (chunk & 0xFFFFF) << 3;
			for (int dx = 0; dx < 8; dx++)
			{
				for (int dy = 0; dy < 8; dy++)
				{
					if (worldMesh.isWalkable(baseX + dx, baseY + dy, plane) && !worldMesh.isWater(baseX + dx, baseY + dy, plane))
					{
						floors.add(worldMesh.componentAt(baseX + dx, baseY + dy, plane));
					}
				}
			}
		}
		worldMesh.admitInstanceFloors(floors);
	}

	/**
	 * Where a golem in an instance is drawn, {x, y, plane} in the loaded scene, setting its draw
	 * offset and turn to match; null, with no offset, if it is not in a chunk the instance was built
	 * from. The instance is built from the chunks around the room as well as the room, and golems on
	 * the island in those chunks were drawn inside it; the rest wait out of range. Asked again after
	 * the golem moves: set only before, a golem crossing into the next chunk of a turned room was
	 * drawn for a frame with the old chunk's offset, up to eight tiles away.
	 */
	private int[] placeInInstance(Golem golem, WorldView wv, WorldPoint playerAt, Map<Long, List<int[]>> sceneChunks)
	{
		int tileX = golem.getFineX() / Golem.TILE;
		int tileY = golem.getFineY() / Golem.TILE;
		// A chunk the instance uses twice is drawn in the copy nearest the player.
		int[] scene = golem.isInInstance() && sceneChunks != null
			? InstanceMap.nearest(sceneChunks.get(InstanceMap.chunkKey(tileX >> 3, tileY >> 3, golem.getPlane())),
				playerAt == null ? 0 : (playerAt.getX() - wv.getBaseX()) >> 3,
				playerAt == null ? 0 : (playerAt.getY() - wv.getBaseY()) >> 3)
			: null;
		if (scene == null)
		{
			golem.setDrawOffset(0, 0, -1);
			return null;
		}
		// A turned chunk turns the golem's place in it with it. See InstanceMap.turn.
		int[] inChunk = InstanceMap.turn(tileX & 7, tileY & 7, scene[3]);
		// From the template chunk's corner to the scene chunk's; the turn within it is the golem's.
		golem.setDrawOffset((wv.getBaseX() + (scene[0] << 3) - (tileX & ~7)) * Golem.TILE,
			(wv.getBaseY() + (scene[1] << 3) - (tileY & ~7)) * Golem.TILE, scene[2], scene[3]);
		return new int[]{wv.getBaseX() + (scene[0] << 3) + inChunk[0], wv.getBaseY() + (scene[1] << 3) + inChunk[1], scene[2]};
	}

	/**
	 * Attaches or detaches a golem's drawn object as it crosses the scene boundary, which is
	 * what lets one wander off the edge of what is loaded and come back: leaving the scene
	 * costs it its renderer, not its existence.
	 */
	private void updateRenderer(Golem golem, WorldView wv, boolean inSceneTier, TileMap drawnPerTile)
	{
		boolean visible = inSceneTier
			&& wv != null
			&& wv.getPlane() == golem.getDrawPlane()
			&& inScene(wv, golem)
			// Aboard a boat, the player's or a crew's own, each golem has a place of its own on the
			// deck however many share the boat's tile: the cap is for golems heaped on one of land.
			&& (golem.isAboard() || golem.isCrewed() || drawnPerTile.addTo(RoamContext.tileKey(golem.getFineX() / Golem.TILE,
				golem.getFineY() / Golem.TILE, golem.getPlane()), 1) <= MAX_DRAWN_PER_TILE);

		if (!visible)
		{
			detachRenderer(golem);
			return;
		}

		if (golem.getRenderer() == null)
		{
			Model model = modelFactory.modelFor(golem.getSnapshot());
			if (model == null)
			{
				return;
			}
			FakeGolem renderer = new FakeGolem(client, golem, model, modelFactory);
			golem.setRenderer(renderer);
			client.registerRuneLiteObject(renderer);
		}
	}

	private boolean inScene(WorldView wv, Golem golem)
	{
		return Golem.isInScene(wv,
			golem.getDrawFineX() - wv.getBaseX() * Golem.TILE,
			golem.getDrawFineY() - wv.getBaseY() * Golem.TILE);
	}

	private void detachRenderer(Golem golem)
	{
		FakeGolem renderer = golem.getRenderer();
		if (renderer != null)
		{
			client.removeRuneLiteObject(renderer);
			golem.setRenderer(null);
		}
		// Its raft goes with it: a golem removed or crumbled at sea is never updated again,
		// so nothing else would take the raft away.
		FakeRaft raft = rafts.remove(golem);
		if (raft != null)
		{
			raft.detach();
		}
	}

	// ---- per-tick upkeep ----

	/**
	 * Puts the Golems tab in the sidebar, or takes it away.
	 *
	 * <p>The panel itself is built either way and keeps its state: the tab is a way in, not the
	 * roster. Off, the plinth's own menu is how missing golems are revived; see GolemMenu.
	 */
	private void showSidebar(boolean shown)
	{
		if (navButton == null)
		{
			return;
		}
		if (shown && !sidebarShown)
		{
			clientToolbar.addNavigation(navButton);
		}
		else if (!shown && sidebarShown)
		{
			clientToolbar.removeNavigation(navButton);
		}
		sidebarShown = shown;
	}

	/** Whether the tab is in the sidebar, so it is neither added twice nor removed twice. */
	private boolean sidebarShown;

	/** The menu entries that are about a game object, whose identifier is the object's id. */
	private static final Set<MenuAction> OBJECT_ENTRIES = EnumSet.of(MenuAction.GAME_OBJECT_FIRST_OPTION,
		MenuAction.GAME_OBJECT_SECOND_OPTION, MenuAction.GAME_OBJECT_THIRD_OPTION, MenuAction.GAME_OBJECT_FOURTH_OPTION,
		MenuAction.GAME_OBJECT_FIFTH_OPTION, MenuAction.EXAMINE_OBJECT);

	/**
	 * Offers to revive missing golems from the plinth they were carved on, for a player with the
	 * sidebar off - and for anyone standing at the plinth, which is where it would occur to them.
	 *
	 * <p>On a plain right-click and not behind shift: the entry is there only while golems are
	 * missing, so it is never in the way of carving another one.
	 */
	@Subscribe
	public void onMenuOpened(MenuOpened event)
	{
		if (!running)
		{
			return;
		}
		int missing = missingGolems(countLiving());
		if (missing <= 0)
		{
			return;
		}
		for (MenuEntry entry : event.getMenuEntries())
		{
			// On an object: an NPC's or an item's identifier is something else, and one that happened
			// to match a plinth offered a revive on it.
			if (OBJECT_ENTRIES.contains(entry.getType()) && GolemContent.isPlinth(entry.getIdentifier()))
			{
				// Named as the plinth the player is pointing at, which is one of six carvings.
				menu.addReviveEntry(missing, entry.getTarget(), this::reviveMissing);
				return;
			}
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		obstacleObserver.onMenuOptionClicked(event);
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		// A hit while using an obstacle means it failed; a fall is not the way across.
		if (event.getActor() == client.getLocalPlayer())
		{
			obstacleObserver.onPlayerHurt();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		tickStartCycle = client.getGameCycle();
		// Usually a comparison; the first tick a new account's count is known, its golems.
		loadAccount();
		announceUpdate();
		readDiaries();
		obstacleObserver.onGameTick();
		// Refreshed continuously rather than read once at spawn: a golem steps off its
		// plinth and starts walking, and its pose animations need not be the ones it had
		// while standing on it.
		WorldView topLevel = client.getTopLevelWorldView();
		if (topLevel != null)
		{
			for (NPC npc : topLevel.npcs())
			{
				if (detector.isGolem(npc) && !detector.wasReplaced(npc))
				{
					detector.track(npc);
				}
			}
		}

		// A new floor is ground to learn even though no scene was loaded: the harvest reads the
		// player's plane and only ran on a scene load, which a ladder does not trigger, so
		// golems that climbed arrived on unknown ground and were lifted back to the plinth -
		// 217 times in one session.
		WorldPoint me = PlayerPosition.of(client);
		int plane = me == null ? -1 : me.getPlane();
		if (plane != harvestedPlane)
		{
			harvestedPlane = plane;
			islandMemory.sceneChanged();
		}
		islandMemory.harvestLoadedRegions();
		// Ground just read, by a harvest or from the saved map at login, can join two spaces: a door
		// standing open, which golems in view walk through. Only the regions just read are looked
		// at, and home's reach is worked out again if anything was joined: the cut-off test asked an
		// old answer, and a golem that walked through a door opened this session was carried home.
		int[] read = islandMemory.takeFreshRegions();
		if (read.length > 0 && worldMesh.joinWhereWalked(islandMemory, read) > 0)
		{
			worldMesh.linkSpaces(GolemContent.PLINTH_X, GolemContent.PLINTH_Y, 0);
		}

		// Only when the roster has actually changed: copying five hundred golems every tick
		// to hand the panel an identical list is work for nothing.
		if (panel != null && rosterChanged)
		{
			rosterChanged = false;
			// Which of two golems keeps a name they would share is settled once per change, here;
			// rows already shown are only named again if one of them now answers to something else.
			boolean renamed = names.assign(golems);
			List<Golem> living = nearestFirst();
			panel.refresh(living, missingGolems(living.size()), renamed);
			if (renamed)
			{
				GolemPage open = page;
				pageRenamed(open == null ? null : open.getShowing());
			}
		}

		// At most once every few ticks: each application rebuilds the network, the floors it admits and
		// what golems can get back from, some sixty milliseconds, and on an agility course a sighting
		// comes every few ticks. What arrives meanwhile goes in with the next.
		// The tick count starts again at login, so a count gone backwards is time enough.
		int sinceApplied = client.getTickCount() - routesAppliedTick;
		if (routesChanged && (sinceApplied < 0 || sinceApplied >= ROUTE_APPLY_TICKS))
		{
			routesAppliedTick = client.getTickCount();
			applyLearnedRoutes();
			obstacleData.save();
		}

		// Who is waiting at a quayside, who has just cast off, and who has landed.
		crews.update(golems, roamContext.getTick(), roamContext);

		// Whether the player has just stepped aboard their ship, or off it, with golems following.
		shipmates.update(golems, client.getTickCount(), roamPlanner::landingTileNear);

		// A few golems a tick, asked whether the ground they are on joins up with home.
		sweepForCutOff();

		// Every tick, so a golem keeps up with the map as it is panned. Closed, this is one widget
		// lookup and nothing else.
		pointAtGolem();

		refreshMap();

		// Each read once: shutting down on the Swing thread clears them, and a check then a use of
		// the field could see it go in between.
		GolemListPanel list = panel;
		GolemPage open = page;
		boolean listing = list != null && list.isOnScreen();
		boolean pageOpen = open != null && open.isOpen();
		if ((listing || pageOpen) && (++ticksSincePlaces >= PLACES_TICKS || placesWanted))
		{
			ticksSincePlaces = 0;
			placesWanted = false;
			if (listing)
			{
				placeListed(list);
			}

			// And the page, if one is open, which is one golem and may not be among those listed:
			// kept up to date whether or not the list is showing, or even enabled.
			if (pageOpen)
			{
				Golem shown = open.getShowing();
				String where = whereabouts.of(shown, roamContext.getTick());
				boolean living = shown != null && golems.contains(shown) && !shown.isDying();
				SwingUtilities.invokeLater(() -> open.showPlace(shown, living ? where : "Gone", living));
			}
		}

		if (++ticksSinceCensus >= CENSUS_TICKS)
		{
			ticksSinceCensus = 0;
			census.recount(golems);

			// The same pass keeps each golem's own tally: where it has got to, and how much ground
			// it has covered since the last one. See GolemHistory.
			for (Golem golem : golems)
			{
				// At sea it has not walked anywhere, on the player's ship or a boat of its own: the
				// voyage is written down when it comes ashore, as sailed. Sampled mid-crossing, the
				// coast it passed was written down as walked to, and the landfall with it.
				if (golem.isAboard() || golem.isSailing(roamContext.getTick()))
				{
					continue;
				}
				WorldPoint at = golem.currentTile();
				if (golem.isEstimated(roamContext.getTick()))
				{
					golem.getHistory().passing(at.getX(), at.getY());
					continue;
				}
				golem.getHistory().sample(at.getX(), at.getY(), at.getPlane(), golem.getHome(), placeNames);
			}
		}

		if (saveGolemsAt >= 0 && client.getTickCount() >= saveGolemsAt)
		{
			saveGolemsAt = -1;
			saveGolems();
		}

		if (++ticksSinceSave >= SAVE_INTERVAL_TICKS)
		{
			ticksSinceSave = 0;
			saveGolems();
			saveIslandMemory();
			// Golems crossing obstacles add to the record constantly; written with the rest.
			obstacleData.save();
		}
	}

	private void refreshMap()
	{
		GolemsDontDieConfig.MapGolems onMap = config.mapGolems();
		if (onMap == GolemsDontDieConfig.MapGolems.NONE && finding == null)
		{
			mapPoints.clear();
		}
		else
		{
			// The roster itself, not a copy of the living: this runs every tick whether or not the
			// map is open, and the map skips the dying golems itself once it knows it is.
			mapPoints.refresh(golems, onMap == GolemsDontDieConfig.MapGolems.NAMED,
				roamContext.getTick(), finding);
		}
	}

	/**
	 * Offers the hovered golem's menu entries.
	 *
	 * <p>On client tick rather than game tick: this is when the client rebuilds its menu, and
	 * a golem waiting up to 600ms to become hoverable would feel broken beside a real NPC.
	 */
	@Subscribe
	public void onClientTick(ClientTick event)
	{
		obstacleObserver.onClientTick();

		// The map as soon as it opens, and as soon as another map is picked.
		if (mapPoints.wantsFrame())
		{
			refreshMap();
		}

		if (!golems.isEmpty())
		{
			menu.addEntries(drawnGolems);
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();

		if (state == GameState.LOADING)
		{
			// The scene is being rebuilt, so every registered object is about to refer to
			// coordinates that no longer mean what they did. Drop the renderers; the golems
			// themselves are in world space.
			for (Golem golem : golems)
			{
				detachRenderer(golem);
			}
			// Scenery copies are registered objects too, holding scene-local coordinates
			// about to mean something else. A prop is short-lived, so drop them all.
			clearProps();
			clearRafts();
			lastGameCycle = -1;
			islandMemory.sceneChanged();
			return;
		}

		if (state == GameState.LOGGED_IN)
		{
			// The dock table is game data, not a bundled resource, so it needs a logged-in
			// client. Here rather than in startUp is what lets the plugin be enabled at the
			// login screen.
			sailingDocks.load();
			loadAccount();
			// Belt and braces next to onVarbitChanged: whichever of the two sees the
			// count first, the other is a no-op.
			syncTally();
			restorePending();
			return;
		}

		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			// Golems are permanent, so nothing is released here - only the renderers,
			// which belong to a scene that is going away. Any aboard the player's ship go back
			// to their quays first: the ship does not come with the player.
			shipmates.abandon(client.getTickCount());
			saveGolems();
			saveIslandMemory();
			// Quest progress is the account's, and the next login may be another account.
			// Not on every LOGGED_IN, which also follows each loading screen.
			sailingDocks.forgetQuests();
			abilities.forgetQuests();
			ticksLoggedIn = 0;
			// A pass half made belongs to the session just left, perhaps another account's.
			settledSinceLogin = false;
			sweptTo = 0;
			sweepSeen = 0;
			sweepCutOff.clear();
			sweepStranded.clear();
			obstacleObserver.resetSession();
			detector.reset();
			hiddenNpcs.clear();
			releaseShadows();
			lastGameCycle = -1;

			// The levels and the golem count are about to be sent again, and must not be taken for
			// news. And whatever the golems were doing for the player's benefit - a wave, a dance, a
			// crew making up at a quay - is over: those moments were timed against this session.
			celebration.reset();
			for (Golem golem : golems)
			{
				golem.forgetMoments();
			}
			crews.releaseMusters();

			for (Golem golem : golems)
			{
				detachRenderer(golem);
			}
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!GolemsDontDieConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		if ("showSidebar".equals(event.getKey()))
		{
			showSidebar(config.showSidebar());
		}

		if (("autoName".equals(event.getKey()) || "nameStyle".equals(event.getKey())) && panel != null)
		{
			panel.namesChanged();
			GolemPage open = page;
			pageRenamed(open == null ? null : open.getShowing());
		}

		if ("maxGolems".equals(event.getKey()) || "limitGolems".equals(event.getKey()))
		{
			clientThread.invoke(() ->
			{
				enforceGolemLimit();
				saveGolems();
				// The revive button offers only what the limit leaves room for.
				rosterChanged = true;
			});
		}
	}

	// ---- persistence ----

	/** Every tile of every instance room, from the last time routes changed. */
	private Set<Long> instanceRoomTiles = Collections.emptySet();

	/** Tiles flooded from an instance route's landing before it counts as open ground. */
	private static final int ROOM_FLOOD = 4000;

	/**
	 * Tiles only a transport into an instance reaches: the template rooms golems walk while
	 * inside one, as {@link RoamContext#tileKey} keys. For golems saved before the plugin
	 * tracked which were in an instance, and ones that walked into the Mad Angel's sealed room
	 * before the planner learned not to.
	 */
	private Set<Long> instanceRooms()
	{
		Set<Long> rooms = new HashSet<>();
		for (GolemTransport t : transports.all())
		{
			if (!t.entersInstance())
			{
				continue;
			}
			TileMap reached = pathfinder.flood(t.getToX(), t.getToY(), t.getToPlane(), ROOM_FLOOD);
			// A landing the golem could walk back from, or that opens onto a whole island,
			// is not a room.
			if (reached.size() >= ROOM_FLOOD || (t.getFromPlane() == t.getToPlane()
				&& reached.containsKey(GolemPathfinder.pack(t.getFromX(), t.getFromY()))))
			{
				continue;
			}
			for (int i = 0; i < reached.size(); i++)
			{
				long tile = reached.keyAt(i);
				rooms.add(RoamContext.tileKey(GolemPathfinder.unpackX(tile), GolemPathfinder.unpackY(tile), t.getToPlane()));
			}
		}
		return rooms;
	}

	/**
	 * Gives golems just made the next craft numbers, in the order they were made. Not before the save
	 * is restored: the restored golems take the numbers from one, and replace whatever is in memory.
	 */
	private void numberNewGolems()
	{
		if (pendingRestore.isEmpty())
		{
			CraftNumbers.number(golems, golem -> golem.getHistory().getFirstSeen());
		}
	}

	private void restorePending()
	{
		if (pendingRestore.isEmpty() || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		// The saved roster replaces whatever is in memory, never adding on top: golems already
		// here are left from a shutdown that did not finish, and are the same golems again.
		if (!golems.isEmpty())
		{
			log.warn("Restoring over {} golems left from before; replacing them", golems.size());
			for (Golem golem : golems)
			{
				detachRenderer(golem);
			}
			golems.clear();
		}

		List<GolemStore.SavedGolem> saved = new ArrayList<>(pendingRestore);
		Set<Long> rooms = instanceRooms();
		instanceRoomTiles = rooms;
		// When each golem was first known as saved, not as restored: a golem saved before that was
		// kept is given today's date on restore, which would number the oldest golems last.
		Map<Golem, Long> savedAge = new IdentityHashMap<>();
		for (int i = 0; i < saved.size(); i++)
		{
			Golem golem = store.revive(saved.get(i), i);
			if (golem != null)
			{
				savedAge.put(golem, saved.get(i).firstSeen);
				// A saved tile can have become unstandable, and a golem restored inside a new
				// wall would never path anywhere again. Moved while nothing is looking, and
				// moved rather than replaced: same name, same id.
				WorldPoint at = golem.currentTile();
				WorldPoint safe = roamPlanner.snapToMesh(at);
				if (!safe.equals(at))
				{
					log.debug("Relocated restored golem from {} to {}", at, safe);
					golem.relocate(safe);
				}
				WorldPoint restored = golem.currentTile();
				if (!golem.isInInstance()
					&& rooms.contains(RoamContext.tileKey(restored.getX(), restored.getY(), restored.getPlane())))
				{
					golem.setInInstance(true);
				}

				golems.add(golem);
				rosterChanged = true;
			}
		}
		pendingRestore.clear();
		int numbered = CraftNumbers.number(golems, golem -> savedAge.getOrDefault(golem, 0L));
		if (numbered > 0)
		{
			log.debug("Gave {} restored golems craft numbers", numbered);
		}
		enforceGolemLimit();
		// Now there is a whole roster to hold against the game's count.
		trimToGameCount();
		log.debug("Restored {} saved golems", golems.size());
	}

	/**
	 * Writes the roster out. Golems mid-crumble are excluded: they have been retired, and
	 * saving them would bring them back alive on the next login.
	 */
	private void saveGolems()
	{
		if (!running)
		{
			log.debug("Not saving golems: the plugin is not running");
			return;
		}
		// Nothing to write until the saved roster has been loaded: golems are restored at login,
		// and saving the empty roster before that replaced every saved golem with nothing -
		// launching the client and closing it without logging in was enough.
		if (!pendingRestore.isEmpty())
		{
			log.debug("Not saving golems: {} saved golems are not restored yet", pendingRestore.size());
			return;
		}
		// Named rather than the current account: a save can land after the account has changed.
		if (rosterAccount == null)
		{
			return;
		}
		configManager.setConfiguration(GolemsDontDieConfig.GROUP, rosterAccount,
			GolemsDontDieConfig.SAVED_GOLEMS_KEY, store.serialise(livingGolems()));
	}

	private void saveIslandMemory()
	{
		if (!islandMemory.isDirty())
		{
			return;
		}
		setSetting(IslandMemory.MAP_KEY, islandMemory.serialise());
	}

	// ---- hiding the original ----

	/**
	 * Hides a real golem once its copy has taken over: both exist for the rest of the
	 * original's short life, so without this there would visibly be two.
	 */
	private boolean shouldDraw(Renderable renderable)
	{
		if (hiddenNpcs.isEmpty() || !(renderable instanceof NPC))
		{
			return true;
		}
		return !hiddenNpcs.contains(((NPC) renderable).getIndex());
	}

	/** Golems with a model in the scene this frame. See the end of onBeforeRender. */
	private final List<Golem> drawnGolems = new ArrayList<>();

	/**
	 * The golems being drawn, for the overlays and the menu: everything else is off the scene
	 * and would only be looked at to be skipped, thousands of times a frame.
	 */
	List<Golem> drawnGolems()
	{
		return drawnGolems;
	}
}

package com.golemsdontdie;

import java.util.*;
import net.runelite.api.*;
import net.runelite.api.coords.*;

/**
 * Between an instance and the fixed place in the world it is copied from.
 *
 * <p>An instance - a boss room behind a church pew - is built fresh on every visit, in
 * coordinates that mean nothing next time. Its template, the static copy elsewhere assembled from
 * in eight-tile chunks, does stay put, so all a golem keeps about an instance is in template
 * coordinates: golems wander the template room and are drawn in whichever instance is loaded.
 *
 * <p>Rotated chunks are mapped too. A golem walks the template as it is, where the walls are
 * where the collision says, and only its drawing is turned: its place in the chunk and the way
 * it faces. The live harvest still reads only unrotated chunks, as a turned edge would be
 * recorded on the wrong side; the shipped mesh has every template.
 */
final class InstanceMap
{
	private static final int CHUNK = 8;

	private InstanceMap()
	{
	}

	/** The template of a loaded instance tile; the tile itself outside one; null where no chunk is. */
	static WorldPoint templateOf(WorldView wv, WorldPoint tile)
	{
		if (tile == null || wv == null || !wv.isInstance())
		{
			return tile;
		}
		int sceneX = tile.getX() - wv.getBaseX();
		int sceneY = tile.getY() - wv.getBaseY();
		int data = chunkAt(wv, tile.getPlane(), sceneX, sceneY);
		if (data <= 0)
		{
			return null;
		}
		// Turned back the way the chunk was turned, as the client's own WorldPoint.fromLocalInstance.
		int[] at = turn(sceneX & (CHUNK - 1), sceneY & (CHUNK - 1), 4 - rotation(data));
		return new WorldPoint(templateChunkX(data) * CHUNK + at[0], templateChunkY(data) * CHUNK + at[1],
			templatePlane(data));
	}

	/**
	 * A tile's place in its eight-tile chunk after a number of quarter turns, as the client turns
	 * an instance chunk: each turn takes (x, y) to (y, 7 - x), east to south. A template tile at
	 * (x, y) is drawn in a chunk of rotation r at turn(x, y, r).
	 */
	static int[] turn(int x, int y, int quarters)
	{
		switch (quarters & 3)
		{
			case 1:
				return new int[]{y, CHUNK - 1 - x};
			case 2:
				return new int[]{CHUNK - 1 - x, CHUNK - 1 - y};
			case 3:
				return new int[]{CHUNK - 1 - y, x};
			default:
				return new int[]{x, y};
		}
	}

	/** The raw chunk data under a scene tile, or -1 outside the scene. */
	static int chunkAt(WorldView wv, int plane, int sceneX, int sceneY)
	{
		int[][][] chunks = wv.getInstanceTemplateChunks();
		if (chunks == null || plane < 0 || plane >= chunks.length || sceneX < 0 || sceneY < 0)
		{
			return -1;
		}
		int cx = sceneX / CHUNK;
		int cy = sceneY / CHUNK;
		if (cx >= chunks[plane].length || cy >= chunks[plane][cx].length)
		{
			return -1;
		}
		return chunks[plane][cx][cy];
	}

	/**
	 * Where each template chunk sits in the loaded instance, as {sceneChunkX, sceneChunkY,
	 * scenePlane, rotation}, keyed by {@link #chunkKey} of the template chunk. Rotated chunks too:
	 * a golem walks the template as it is and is drawn turned. See turn. A template chunk the
	 * instance uses more than once has every copy listed; see nearest.
	 */
	static Map<Long, List<int[]>> sceneChunks(WorldView wv)
	{
		Map<Long, List<int[]>> out = new HashMap<>();
		int[][][] chunks = wv.getInstanceTemplateChunks();
		if (chunks == null)
		{
			return out;
		}
		for (int z = 0; z < chunks.length; z++)
		{
			for (int cx = 0; cx < chunks[z].length; cx++)
			{
				for (int cy = 0; cy < chunks[z][cx].length; cy++)
				{
					int data = chunks[z][cx][cy];
					if (data <= 0)
					{
						continue;
					}
					out.computeIfAbsent(chunkKey(templateChunkX(data), templateChunkY(data), templatePlane(data)),
						k -> new ArrayList<>(1)).add(new int[]{cx, cy, z, rotation(data)});
				}
			}
		}
		return out;
	}

	/**
	 * The copy of a template chunk nearest a scene chunk, for a golem drawn in an instance built
	 * from the same chunk twice or more: where the player is, so a golem is drawn where it can be
	 * seen. Null for no copies.
	 */
	static int[] nearest(List<int[]> copies, int sceneChunkX, int sceneChunkY)
	{
		if (copies == null || copies.isEmpty())
		{
			return null;
		}
		int[] best = copies.get(0);
		int bestSpan = Integer.MAX_VALUE;
		for (int[] copy : copies)
		{
			int span = Math.max(Math.abs(copy[0] - sceneChunkX), Math.abs(copy[1] - sceneChunkY));
			if (span < bestSpan)
			{
				best = copy;
				bestSpan = span;
			}
		}
		return best;
	}

	static long chunkKey(int chunkX, int chunkY, int plane)
	{
		return ((long) plane << 40) | ((long) chunkX << 20) | chunkY;
	}

	static int rotation(int data)
	{
		return data >> 1 & 0x3;
	}

	static int templateChunkX(int data)
	{
		return data >> 14 & 0x3FF;
	}

	static int templateChunkY(int data)
	{
		return data >> 3 & 0x7FF;
	}

	static int templatePlane(int data)
	{
		return data >> 24 & 0x3;
	}
}

package com.golemsdontdie;

import java.io.*;
import java.util.*;
import java.util.function.*;
import java.util.zip.*;
import javax.inject.*;
import lombok.*;
import lombok.extern.slf4j.*;
import net.runelite.api.*;
import net.runelite.api.coords.*;

/**
 * The plugin's memory of where a golem can walk on Wyrmscraig, in world coordinates,
 * learned by watching the scene and kept across logins.
 *
 * <p>Free roam needs passability for the whole island, but the scene only holds the
 * 104×104 tiles around the player, so every region's collision flags are copied out as it
 * loads and folded into a world-space record that outlives the scene.
 *
 * <p>Storage is the two-bit-per-tile north/east scheme Shortest Path uses. South and west
 * are not stored because they are the north and east of the neighbouring tile; halving the
 * data for free matters when it has to fit in a config value.
 *
 * <p>The <i>live</i> half of a pair: {@link WorldMesh} is the shipped read-only floor for
 * the whole reachable world, and this takes precedence wherever the two disagree, because
 * a harvest reflects the world as it is now - objects that come and go included, and the
 * window between a game update and the mesh being regenerated.
 *
 * <p>What is persisted is the island and everywhere golems have been found able to reach from
 * it: every instance the player loads, and the ground around the far end of every learned route.
 * That grows as the player plays, deliberately - the shipped data does not cover instances or
 * every shortcut yet, and until it does, what was learned is kept. The world the mesh covers
 * stays in the jar.
 */
@Slf4j
@Singleton
class IslandMemory
{
	/** Config key the serialised map is stored under. Plugin-written, so not a config item. */
	static final String MAP_KEY = "islandMap";

	/**
	 * The island map shipped with the plugin, covering the nine regions around the crafting
	 * site. Built from Shortest Path's world collision map - generated from the cache with XTEA
	 * keys the local key file lacks for these regions - and cross-checked tile by tile against
	 * live collision. Without it, free roam could only cover ground the player had walked.
	 *
	 * @see #loadBundled()
	 */
	private static final String BUNDLED_MAP = "/island-map.gz";

	private static final int REGION_SIZE = 64;
	private static final int REGION_MASK = REGION_SIZE - 1;
	private static final int FLAGS_PER_TILE = 2;
	private static final int FLAG_NORTH = 0;
	private static final int FLAG_EAST = 1;
	private static final int BITS_PER_REGION = REGION_SIZE * REGION_SIZE * FLAGS_PER_TILE;
	private static final int WORDS_PER_REGION = BITS_PER_REGION / Long.SIZE;

	/**
	 * Tiles at the edge of the loaded scene that are never harvested. The client fills a border
	 * of the scene's collision with "blocked" whatever is really there - harmless while
	 * harvesting only added open edges, but once a harvest cleared what it re-read it wrote a
	 * band of false walls, boxing the plinth into two hundred tiles.
	 */
	private static final int SCENE_MARGIN = 6;

	/**
	 * The client's flag for a tile in a map square that does not exist. RuneLite has no name for
	 * it. The client never walks onto one; read as open, whole squares of nothing were saved as
	 * ground, four of them beside Wyrmscraig's caves.
	 */
	private static final int NOT_LOADED = 0x1000000;

	/** Blocked for standing on: an object, a wall filling the tile, bad ground, or no square at all. */
	private static final int UNWALKABLE = CollisionDataFlag.BLOCK_MOVEMENT_FULL
		| CollisionDataFlag.BLOCK_MOVEMENT_OBJECT
		| CollisionDataFlag.BLOCK_MOVEMENT_FLOOR
		| CollisionDataFlag.BLOCK_MOVEMENT_FLOOR_DECORATION
		| NOT_LOADED;

	/**
	 * Passability per region-and-plane. The key packs both so that a multi-level
	 * island does not collapse its floors onto each other.
	 */
	private final Map<Long, long[]> regions = new HashMap<>();

	/**
	 * Region ids that may have an entry in {@link #regions}, on any plane. Nearly every tile a
	 * far golem asks about is somewhere the player has never been, and finding that out boxed a
	 * key several times a step; a clear bit answers with an array read. A set bit only means
	 * look, so it may outlive the entry.
	 */
	private final boolean[] mayHold = new boolean[1 << 16];

	/** Notes that {@link #regions} now holds this key. */
	private void held(long key)
	{
		int regionId = (int) (key >> 8);
		fresh.add(regionId);
		if (regionId >= 0 && regionId < mayHold.length)
		{
			mayHold[regionId] = true;
		}
	}

	/**
	 * Regions read into the map since {@link #takeFreshRegions} was last asked: where walks between
	 * spaces may have changed, and nowhere else.
	 */
	private final Set<Integer> fresh = new LinkedHashSet<>();

	/** The regions read since last asked, and forgets them. */
	int[] takeFreshRegions()
	{
		int[] out = fresh.stream().mapToInt(Integer::intValue).toArray();
		fresh.clear();
		return out;
	}

	/** True if the map holds anything of its own for this region and plane. */
	boolean holds(int regionId, int plane)
	{
		return regionId >= 0 && regionId < mayHold.length && mayHold[regionId] && regions.containsKey(key(regionId, plane));
	}

	/** Every region the map holds ground for, on any plane: the island and wherever else was read. */
	int[] knownRegions()
	{
		Set<Integer> ids = new TreeSet<>();
		for (long key : regions.keySet())
		{
			ids.add((int) (key >> 8));
		}
		for (int island : GolemContent.ISLAND_REGIONS)
		{
			ids.add(island);
		}
		return ids.stream().mapToInt(Integer::intValue).toArray();
	}

	/** Empties {@link #regions}, and what is known about what it holds. */
	private void clearRegions()
	{
		regions.clear();
		Arrays.fill(mayHold, false);
	}

	/** Regions harvested this session, so a reload is not redone every scene change. */
	private final Set<Long> harvested = new HashSet<>();

	/**
	 * Which tiles of a harvested region have actually been read from a scene, one bit a tile,
	 * keyed as {@link #regions}. No entry means fully known: the shipped island map, or a save
	 * from before this was kept.
	 *
	 * <p>A region is 64 tiles square and a scene rarely shows all of one. Unread tiles were
	 * zeros, zeros read as walls, and those walls stood in front of the shipped mesh for the
	 * whole region - golems were rescued off cave ground the mesh knows perfectly well.
	 */
	private final Map<Long, long[]> seen = new HashMap<>();

	private static final int TILE_WORDS = REGION_SIZE * REGION_SIZE / Long.SIZE;

	private static void markSeen(long[] mask, int rx, int ry)
	{
		int tile = ry * REGION_SIZE + rx;
		mask[tile >> 6] |= 1L << (tile & 63);
	}

	private static boolean isSeen(long[] mask, int rx, int ry)
	{
		int tile = ry * REGION_SIZE + rx;
		return (mask[tile >> 6] >>> (tile & 63) & 1L) != 0L;
	}

	/**
	 * The region the first golem was seen in; everything the island is taken to be is measured
	 * from here. Hardcoding Wyrmscraig's region IDs is not available: the content is newer than
	 * this plugin, and a wrong constant would silently disable free roam.
	 */
	@Getter
	private int anchorRegionId = -1;

	@Getter
	private boolean dirty = false;

	@Inject
	private Client client;

	@Inject
	private WorldMesh worldMesh;

	// ---- the shipped baseline ----

	/**
	 * Loads the bundled island map without disturbing anything already learned. Merged
	 * <i>under</i> what is there, because a live harvest reflects the island as it is now. Called
	 * at start-up, before the saved map is restored, so it is the floor free roam stands on when
	 * the player has never been to Wyrmscraig.
	 */
	void loadBundled()
	{
		try (InputStream raw = IslandMemory.class.getResourceAsStream(BUNDLED_MAP))
		{
			if (raw == null)
			{
				log.warn("Bundled island map missing from the jar");
				return;
			}

			try (GZIPInputStream gz = new GZIPInputStream(raw);
				 DataInputStream data = new DataInputStream(gz))
			{
				int count = data.readInt();
				for (int i = 0; i < count; i++)
				{
					int regionId = data.readInt();
					int plane = data.readInt();
					byte[] packed = new byte[BITS_PER_REGION / 8];
					data.readFully(packed);

					long key = key(regionId, plane);
					if (regions.containsKey(key))
					{
						// A live scene is the better source, but only for the tiles it showed;
						// the rest are filled from the shipped map to make the region whole.
						long[] mask = seen.remove(key);
						if (mask != null)
						{
							fillUnseen(regions.get(key), toWords(packed), mask);
						}
						continue;
					}
					regions.put(key, toWords(packed));
					held(key);
				}

				if (anchorRegionId == -1)
				{
					anchorRegionId = GolemContent.WYRMSCRAIG_REGION;
				}
				log.debug("Loaded bundled island map: {} region-planes", count);
			}
		}
		catch (IOException | RuntimeException e)
		{
			// Survivable: golems fall back to roaming only what the player has walked.
			log.warn("Bundled island map unreadable", e);
		}
	}

	/** Copies both edges of every tile the mask has not seen from {@code source} into {@code target}. */
	private static void fillUnseen(long[] target, long[] source, long[] mask)
	{
		for (int ry = 0; ry < REGION_SIZE; ry++)
		{
			for (int rx = 0; rx < REGION_SIZE; rx++)
			{
				if (isSeen(mask, rx, ry))
				{
					continue;
				}
				for (int flag = 0; flag < FLAGS_PER_TILE; flag++)
				{
					int bit = bitIndex(rx, ry, flag);
					long one = 1L << (bit & 63);
					target[bit >> 6] = (target[bit >> 6] & ~one) | (source[bit >> 6] & one);
				}
			}
		}
	}

	/** Repacks the bundled byte layout into the long words used at runtime. */
	private static long[] toWords(byte[] packed)
	{
		long[] words = new long[WORDS_PER_REGION];
		for (int i = 0; i < packed.length; i++)
		{
			words[i >> 3] |= (packed[i] & 0xFFL) << ((i & 7) * 8);
		}
		return words;
	}

	// ---- learning ----

	/**
	 * Records where the golems live, if it is not already known. Called the first
	 * time a golem is seen.
	 */
	void anchorAt(WorldPoint point)
	{
		if (anchorRegionId == -1)
		{
			anchorRegionId = point.getRegionID();
			dirty = true;
			log.debug("Island anchored at region {}", anchorRegionId);
		}
	}

	/**
	 * True once there is an anchor. With the bundled map loaded this is true from
	 * start-up, so golems can roam before the player has ever seen one made.
	 */
	boolean hasAnchor()
	{
		return anchorRegionId != -1;
	}

	/**
	 * True if a region is part of the island, or somewhere golems can get to from it. The nine are a
	 * fixed list rather than a radius, as the bundled map defines them; the rest are wherever the
	 * network says a transport leads, so walking the rest of Gielinor harvests nothing.
	 */
	private boolean withinIsland(int regionId)
	{
		for (int island : GolemContent.ISLAND_REGIONS)
		{
			if (island == regionId)
			{
				return true;
			}
		}
		return alsoIsland != null && alsoIsland.test(regionId);
	}

	/**
	 * Regions beyond the nine around the plinth that golems can reach and so need mapping:
	 * wherever a transport from the island leads. Set by the plugin, which has the network. The
	 * cathedral's basement is under the island but in another region, and golems that went down
	 * found nowhere to walk.
	 */
	private IntPredicate alsoIsland;

	void setAlsoIsland(IntPredicate alsoIsland)
	{
		this.alsoIsland = alsoIsland;
	}

	/**
	 * Asks for one more harvest pass. Called when the scene is rebuilt, because nothing about
	 * the scene changes between ticks: harvesting every tick re-scanned in full, sixty times a
	 * minute, every region clipped by the scene edge, which can never have all 4096 of its
	 * tiles in the scene at once.
	 */
	void sceneChanged()
	{
		pendingHarvest = true;
	}

	private boolean pendingHarvest = true;

	/**
	 * Copies passability for every island region currently loaded out of the scene. Bounded to
	 * regions near the anchor, so walking across the rest of Gielinor does not accumulate a
	 * world map in the player's config.
	 */
	void harvestLoadedRegions()
	{
		if (!pendingHarvest)
		{
			return;
		}
		pendingHarvest = false;

		WorldView wv = client.getTopLevelWorldView();
		if (wv == null || !hasAnchor())
		{
			return;
		}

		CollisionData[] maps = wv.getCollisionMaps();
		int plane = wv.getPlane();
		if (maps == null || plane < 0 || plane >= maps.length || maps[plane] == null)
		{
			return;
		}
		int[][] live = maps[plane].getFlags();
		if (live == null)
		{
			return;
		}
		// A copy, so the void can be marked in it without touching the client's own collision.
		int[][] flags = new int[live.length][];
		for (int x = 0; x < live.length; x++)
		{
			flags[x] = live[x] == null ? new int[0] : live[x].clone();
		}

		if (wv.isInstance())
		{
			markVoid(wv, plane, flags);
			harvestInstance(wv, plane, flags);
			return;
		}

		markVoid(wv, plane, flags);

		int baseX = wv.getBaseX();
		int baseY = wv.getBaseY();

		for (int regionId : wv.getMapRegions())
		{
			long key = key(regionId, plane);
			if (!withinIsland(regionId) || harvested.contains(key))
			{
				continue;
			}

			if (!regions.containsKey(key))
			{
				seen.put(key, new long[TILE_WORDS]);
			}
			long[] bits = regions.computeIfAbsent(key, k -> new long[WORDS_PER_REGION]);
			held(key);
			long[] seenHere = seen.get(key);
			int regionBaseX = (regionId >> 8) << 6;
			int regionBaseY = (regionId & 0xFF) << 6;
			int tilesSeen = 0;

			for (int rx = 0; rx < REGION_SIZE; rx++)
			{
				for (int ry = 0; ry < REGION_SIZE; ry++)
				{
					int sceneX = regionBaseX + rx - baseX;
					int sceneY = regionBaseY + ry - baseY;
					if (sceneX < SCENE_MARGIN || sceneY < SCENE_MARGIN
						|| sceneX >= Constants.SCENE_SIZE - SCENE_MARGIN
						|| sceneY >= Constants.SCENE_SIZE - SCENE_MARGIN
						|| sceneX >= flags.length || sceneY >= flags[sceneX].length)
					{
						continue;
					}

					tilesSeen++;

					// Cleared before being set: a harvest that only added open edges left a door
					// open in memory after it was shut. An edge is only rewritten where the
					// tile it leads to is inside the harvested area; beyond that the scene's
					// border would answer.
					boolean northKnown = sceneY + 1 < Constants.SCENE_SIZE - SCENE_MARGIN;
					boolean eastKnown = sceneX + 1 < Constants.SCENE_SIZE - SCENE_MARGIN;
					// A tile on the harvest's far edge has an edge nobody could read; counting
					// it seen would make that edge a wall, so the mesh answers instead.
					if (seenHere != null && northKnown && eastKnown)
					{
						markSeen(seenHere, rx, ry);
					}
					int here = flags[sceneX][sceneY];
					boolean blocked = (here & UNWALKABLE) != 0;
					if (northKnown || blocked)
					{
						clear(bits, rx, ry, FLAG_NORTH);
					}
					if (eastKnown || blocked)
					{
						clear(bits, rx, ry, FLAG_EAST);
					}
					if (blocked)
					{
						continue;
					}

					// North and east are blocked by a wall here or by the destination being
					// unstandable. At a region edge the destination may be outside the scene:
					// leave the bit clear for the neighbour's harvest.
					if (northKnown && (here & CollisionDataFlag.BLOCK_MOVEMENT_NORTH) == 0
						&& standable(flags, sceneX, sceneY + 1))
					{
						set(bits, rx, ry, FLAG_NORTH);
					}
					if (eastKnown && (here & CollisionDataFlag.BLOCK_MOVEMENT_EAST) == 0
						&& standable(flags, sceneX + 1, sceneY))
					{
						set(bits, rx, ry, FLAG_EAST);
					}
				}
			}

			if (tilesSeen > 0)
			{
				dirty = true;
			}

			// Only done when every tile was actually in the scene: the scene is 104 tiles
			// square and regions are 64, so edge regions are always clipped, and marking one
			// complete would freeze it half-scanned with holes that never fill.
			if (tilesSeen == REGION_SIZE * REGION_SIZE)
			{
				harvested.add(key);
				seen.remove(key);
				log.debug("Harvested island region {} plane {}", regionId, plane);
			}
		}
	}

	/**
	 * Records an instance's ground under its template's coordinates, which is where golems in an
	 * instance are simulated. The template room is sealed off - nothing leads into it on foot,
	 * which is why golems that wandered in were stuck - so its floor can only be learned from an
	 * instance built on it. An edge is only recorded where both tiles come from the same
	 * template, side by side: chunks are stitched together as the instance is built, so
	 * neighbours there need not be neighbours in the world.
	 */
	private void harvestInstance(WorldView wv, int plane, int[][] flags)
	{
		int edgeX = Math.min(flags.length, wv.getSizeX()) - SCENE_MARGIN;
		for (int sceneX = SCENE_MARGIN; sceneX < edgeX; sceneX++)
		{
			int edgeY = Math.min(flags[sceneX].length, wv.getSizeY()) - SCENE_MARGIN;
			for (int sceneY = SCENE_MARGIN; sceneY < edgeY; sceneY++)
			{
				int[] here = template(wv, plane, sceneX, sceneY);
				if (here == null)
				{
					continue;
				}
				long key = key(regionIdOf(here[0], here[1]), here[2]);
				if (!regions.containsKey(key))
				{
					seen.put(key, new long[TILE_WORDS]);
				}
				long[] bits = regions.computeIfAbsent(key, k -> new long[WORDS_PER_REGION]);
				held(key);
				int rx = here[0] & REGION_MASK;
				int ry = here[1] & REGION_MASK;
				long[] seenHere = seen.get(key);
				if (seenHere != null)
				{
					markSeen(seenHere, rx, ry);
				}
				boolean northKnown = sceneY + 1 < edgeY;
				boolean eastKnown = sceneX + 1 < edgeX;
				boolean blocked = (flags[sceneX][sceneY] & UNWALKABLE) != 0;
				if (northKnown || blocked)
				{
					clear(bits, rx, ry, FLAG_NORTH);
				}
				if (eastKnown || blocked)
				{
					clear(bits, rx, ry, FLAG_EAST);
				}
				if (blocked)
				{
					continue;
				}
				int[] north = template(wv, plane, sceneX, sceneY + 1);
				if (northKnown && (flags[sceneX][sceneY] & CollisionDataFlag.BLOCK_MOVEMENT_NORTH) == 0
					&& standable(flags, sceneX, sceneY + 1)
					&& north != null && north[0] == here[0] && north[1] == here[1] + 1 && north[2] == here[2])
				{
					set(bits, rx, ry, FLAG_NORTH);
				}
				int[] east = template(wv, plane, sceneX + 1, sceneY);
				if (eastKnown && (flags[sceneX][sceneY] & CollisionDataFlag.BLOCK_MOVEMENT_EAST) == 0
					&& standable(flags, sceneX + 1, sceneY)
					&& east != null && east[0] == here[0] + 1 && east[1] == here[1] && east[2] == here[2])
				{
					set(bits, rx, ry, FLAG_EAST);
				}
			}
		}
		dirty = true;
	}

	/**
	 * Flags every tile of this plane with no ground drawn as not loaded, in the copy being read.
	 * The client does not block the void beside an upper floor, where there is nothing to stand
	 * on, and read as it comes about seven thousand edges of Wyrmscraig's first floor were ground.
	 */
	private void markVoid(WorldView wv, int plane, int[][] flags)
	{
		Scene scene = wv.getScene();
		Tile[][][] tiles = scene == null ? null : scene.getTiles();
		if (tiles == null || plane >= tiles.length)
		{
			return;
		}
		for (int x = 0; x < flags.length && x < tiles[plane].length; x++)
		{
			for (int y = 0; y < flags[x].length && y < tiles[plane][x].length; y++)
			{
				Tile tile = tiles[plane][x][y];
				if (tile == null || tile.getSceneTilePaint() == null && tile.getSceneTileModel() == null)
				{
					flags[x][y] |= NOT_LOADED;
				}
			}
		}
	}

	/** {x, y, plane} of the template tile under a scene tile, or null. Unrotated chunks only. */
	private static int[] template(WorldView wv, int plane, int sceneX, int sceneY)
	{
		int data = InstanceMap.chunkAt(wv, plane, sceneX, sceneY);
		if (data <= 0 || InstanceMap.rotation(data) != 0)
		{
			return null;
		}
		return new int[]{InstanceMap.templateChunkX(data) * 8 + (sceneX & 7),
			InstanceMap.templateChunkY(data) * 8 + (sceneY & 7), InstanceMap.templatePlane(data)};
	}

	private static boolean standable(int[][] flags, int sceneX, int sceneY)
	{
		if (sceneX < 0 || sceneY < 0
			|| sceneX >= flags.length || flags[sceneX] == null || sceneY >= flags[sceneX].length)
		{
			return false;
		}
		return (flags[sceneX][sceneY] & UNWALKABLE) == 0;
	}

	// ---- querying ----

	/** True if the tile has been harvested and something may stand on it. */
	boolean isKnownWalkable(int worldX, int worldY, int plane)
	{
		// Walkable if it can be left in any direction; an isolated tile with no exits is
		// of no use to a wandering golem.
		return north(worldX, worldY, plane) || east(worldX, worldY, plane)
			|| north(worldX, worldY - 1, plane) || east(worldX - 1, worldY, plane);
	}

	boolean north(int x, int y, int plane)
	{
		return get(x, y, plane, FLAG_NORTH);
	}

	boolean east(int x, int y, int plane)
	{
		return get(x, y, plane, FLAG_EAST);
	}

	/** The four cardinals, named as the collision format stores them. */
	private boolean south(int x, int y, int plane)
	{
		return north(x, y - 1, plane);
	}

	private boolean west(int x, int y, int plane)
	{
		return east(x - 1, y, plane);
	}

	/**
	 * Can something step one tile from (x, y), cardinal or diagonal? A diagonal is a corner and
	 * the game will not cut one: both ways round must be clear, or a golem would slip between
	 * two walls meeting at a point. The four-term tests below are Shortest Path's; the client adds
	 * the corner of a wall standing at the point, which the edges cannot show, so that comes from
	 * the mesh, even where the edges are the live harvest's: walls do not move. Diagonals matter -
	 * Port Tasks' sailing routes are 854 perfect diagonals against 817 axis-aligned segments.
	 */
	boolean canStep(int x, int y, int plane, int dx, int dy)
	{
		if (dx == 0 && dy == 1)
		{
			return north(x, y, plane);
		}
		if (dx == 0 && dy == -1)
		{
			return south(x, y, plane);
		}
		if (dx == 1 && dy == 0)
		{
			return east(x, y, plane);
		}
		if (dx == -1 && dy == 0)
		{
			return west(x, y, plane);
		}
		if (dx == 1 && dy == 1)
		{
			return north(x, y, plane) && east(x, y + 1, plane)
				&& east(x, y, plane) && north(x + 1, y, plane)
				&& !worldMesh.cornerBlocks(x, y, plane, 1, 1);
		}
		if (dx == -1 && dy == 1)
		{
			return north(x, y, plane) && west(x, y + 1, plane)
				&& west(x, y, plane) && north(x - 1, y, plane)
				&& !worldMesh.cornerBlocks(x, y, plane, -1, 1);
		}
		if (dx == 1 && dy == -1)
		{
			return south(x, y, plane) && east(x, y - 1, plane)
				&& east(x, y, plane) && south(x + 1, y, plane)
				&& !worldMesh.cornerBlocks(x, y, plane, 1, -1);
		}
		if (dx == -1 && dy == -1)
		{
			return south(x, y, plane) && west(x, y - 1, plane)
				&& west(x, y, plane) && south(x - 1, y, plane)
				&& !worldMesh.cornerBlocks(x, y, plane, -1, -1);
		}
		return false;
	}

	/**
	 * Passability for one tile and direction, live harvest first: a harvest reflects the world
	 * as it is now where the mesh was only true when generated, which also covers the window
	 * between a game update and the mesh being rebuilt. The mesh below it is what lets a golem
	 * walk ground the player has never stood on.
	 */
	private boolean get(int x, int y, int plane, int flag)
	{
		// The client does not block the open sea - boats sail it - so a harvest reads it as
		// open ground, and the shipped island map lists the water off the cathedral as
		// walkable. The mesh's ocean bit marks exactly that sea, so it overrules every source.
		int toX = flag == FLAG_EAST ? x + 1 : x;
		int toY = flag == FLAG_NORTH ? y + 1 : y;
		if (worldMesh.isWater(x, y, plane) || worldMesh.isWater(toX, toY, plane))
		{
			return false;
		}

		int regionId = regionIdOf(x, y);
		long key = key(regionId, plane);
		long[] bits = regionId >= 0 && regionId < mayHold.length && !mayHold[regionId] ? null : regions.get(key);
		long[] mask = bits == null ? null : seen.get(key);
		if (bits != null && (mask == null || isSeen(mask, x & REGION_MASK, y & REGION_MASK)))
		{
			int bit = bitIndex(x & REGION_MASK, y & REGION_MASK, flag);
			return (bits[bit >> 6] >>> (bit & 63) & 1L) != 0L;
		}

		// The mesh says water is passable, because it is - to a boat. A step is refused unless
		// both ends are ground the land fill reached; both, because land beside water has a
		// perfectly open edge leading off the beach.
		//
		// The land mask, not the ocean bit: ocean marks only the one connected sea, so cave
		// water, lakes and enclosed basins passed the old check, most visibly inside
		// Wyrmscraig's caves. The live harvest needs no such check, except that the client
		// does not block water a boat can sail - which is why the sea and the underground lake
		// are refused first. See WorldMesh.isWater.
		if (flag == FLAG_NORTH)
		{
			return worldMesh.isLandWalkable(x, y, plane)
				&& worldMesh.isLandWalkable(x, y + 1, plane)
				&& worldMesh.north(x, y, plane);
		}
		return worldMesh.isLandWalkable(x, y, plane)
			&& worldMesh.isLandWalkable(x + 1, y, plane)
			&& worldMesh.east(x, y, plane);
	}

	private static void clear(long[] bits, int rx, int ry, int flag)
	{
		int bit = bitIndex(rx, ry, flag);
		bits[bit >> 6] &= ~(1L << (bit & 63));
	}

	/**
	 * Something that changes passability was added or removed - a door opening or shutting - so
	 * its region is read again on the next harvest. A region was harvested once a session and
	 * then trusted, which a door makes wrong: open when read, shut a minute later, and golems
	 * still walking through.
	 */
	void passabilityChanged(WorldPoint at)
	{
		if (at == null || !withinIsland(at.getRegionID()))
		{
			return;
		}
		harvested.remove(key(at.getRegionID(), at.getPlane()));
		pendingHarvest = true;
	}

	private static void set(long[] bits, int rx, int ry, int flag)
	{
		int bit = bitIndex(rx, ry, flag);
		bits[bit >> 6] |= 1L << (bit & 63);
	}

	private static int bitIndex(int rx, int ry, int flag)
	{
		return (ry * REGION_SIZE + rx) * FLAGS_PER_TILE + flag;
	}

	private static int regionIdOf(int worldX, int worldY)
	{
		return ((worldX >> 6) << 8) | (worldY >> 6);
	}

	/** Where instances begin, in x: coordinates past it are rebuilt each visit and name no square. */
	private static final int INSTANCE_X = 6400;

	private static long key(int regionId, int plane)
	{
		return ((long) regionId << 8) | (plane & 0xFF);
	}

	// ---- persistence ----

	/**
	 * Encodes the whole memory as one string: anchor, then each region-plane's bits, gzipped
	 * and base64'd. Compression is not a nicety - a region is 1KB of flags and a passability
	 * map is overwhelmingly long runs of "walkable", so it deflates to a fraction, which is the
	 * difference between a config value and an abuse of one.
	 */
	String serialise()
	{
		try
		{
			ByteArrayOutputStream out = new ByteArrayOutputStream();
			try (GZIPOutputStream gz = new GZIPOutputStream(out);
				 DataOutputStream data = new DataOutputStream(gz))
			{
				data.writeInt(anchorRegionId);
				data.writeInt(regions.size());
				for (Map.Entry<Long, long[]> entry : regions.entrySet())
				{
					data.writeLong(entry.getKey());
					for (long word : entry.getValue())
					{
						data.writeLong(word);
					}
				}
				// Which tiles of each partly harvested region were read; after the regions,
				// so a save without this section still loads.
				data.writeInt(seen.size());
				for (Map.Entry<Long, long[]> entry : seen.entrySet())
				{
					data.writeLong(entry.getKey());
					for (long word : entry.getValue())
					{
						data.writeLong(word);
					}
				}
			}
			dirty = false;
			return Base64.getEncoder().encodeToString(out.toByteArray());
		}
		catch (IOException e)
		{
			log.warn("Could not save island map", e);
			return "";
		}
	}

	/** Restores a memory previously written by {@link #serialise()}. */
	void deserialise(String encoded)
	{
		clearRegions();
		harvested.clear();
		seen.clear();
		anchorRegionId = -1;
		dirty = false;

		if (encoded == null || encoded.isEmpty())
		{
			return;
		}

		try (GZIPInputStream gz = new GZIPInputStream(new ByteArrayInputStream(Base64.getDecoder().decode(encoded)));
			 DataInputStream data = new DataInputStream(gz))
		{
			anchorRegionId = data.readInt();
			int count = data.readInt();
			for (int i = 0; i < count; i++)
			{
				long key = data.readLong();
				long[] words = new long[WORDS_PER_REGION];
				boolean everyEdgeOpen = true;
				for (int w = 0; w < WORDS_PER_REGION; w++)
				{
					words[w] = data.readLong();
					everyEdgeOpen &= words[w] == -1L;
				}
				// Open on every edge of every tile is no real square: it is one that does not exist,
				// saved as ground before the not-loaded flag was read. Dropped, to be read again.
				if (everyEdgeOpen)
				{
					continue;
				}
				// Nor is a square the game does not have. The mesh holds every square with anything to
				// stand on, so one it has never heard of is one read as ground from nothing, and a
				// square only partly read that way escaped the test above.
				int regionId = (int) (key >> 8);
				if (worldMesh != null && worldMesh.holdsAnySquare() && (regionId >> 8) << 6 < INSTANCE_X
					&& !worldMesh.hasSquare(regionId))
				{
					continue;
				}
				regions.put(key, words);
				held(key);
				// Deliberately not added to `harvested`: a restored region is re-scanned
				// once when it next loads, so map edits heal themselves.
			}

			boolean masked;
			try
			{
				int masks = data.readInt();
				for (int i = 0; i < masks; i++)
				{
					long key = data.readLong();
					long[] words = new long[TILE_WORDS];
					for (int w = 0; w < TILE_WORDS; w++)
					{
						words[w] = data.readLong();
					}
					if (regions.containsKey(key))
					{
						seen.put(key, words);
					}
				}
				masked = true;
			}
			catch (EOFException e)
			{
				masked = false;
			}

			// A save from before seen tiles were kept cannot tell a wall from a tile it never
			// read. Best guess: a tile with an open edge was read, one with none is left to
			// the mesh, which keeps ground only a harvest knows. Island regions have the
			// shipped map filled in under the guess.
			if (!masked)
			{
				for (Map.Entry<Long, long[]> entry : regions.entrySet())
				{
					long[] words = entry.getValue();
					long[] mask = new long[TILE_WORDS];
					for (int ry = 0; ry < REGION_SIZE; ry++)
					{
						for (int rx = 0; rx < REGION_SIZE; rx++)
						{
							for (int flag = 0; flag < FLAGS_PER_TILE; flag++)
							{
								int bit = bitIndex(rx, ry, flag);
								if ((words[bit >> 6] >>> (bit & 63) & 1L) != 0L)
								{
									markSeen(mask, rx, ry);
								}
							}
						}
					}
					seen.put(entry.getKey(), mask);
				}
				dirty = true;
			}
			log.debug("Loaded island map: anchor {}, {} region-planes, {} partly read", anchorRegionId,
				regions.size(), seen.size());
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Island map unreadable, starting fresh", e);
			clearRegions();
			anchorRegionId = -1;
		}
	}

	/** Throws away everything learned. */
	void forget()
	{
		clearRegions();
		harvested.clear();
		seen.clear();
		anchorRegionId = -1;
		dirty = true;
	}
}

package com.golemsdontdie;

import java.util.*;
import lombok.*;
import net.runelite.api.coords.*;
import static com.golemsdontdie.RouteGeometry.span;

/**
 * Where a golem will be, expressed so that knowing costs nothing until someone asks.
 *
 * <p>A golem out of view need only be somewhere plausible by the time anyone looks, so instead
 * of ticking it the plugin records its route and start tick; position is then a pure function of
 * elapsed time. More correct than a tick, not cheaper: no drift, nothing to catch up after an
 * hour tabbed out, no dependence on framerate.
 *
 * <p>Measured in <b>distance</b>, not waypoints: a straightened sea route can have waypoints
 * fifty tiles apart, and advancing one per tick made a three-hundred-tile crossing take twenty
 * ticks. Position is interpolated along the polyline, in 128ths of a tile.
 */
final class Itinerary
{
	/** Tiles of the route, in order. The first is where the golem set off from. */
	private final int[] xs;
	private final int[] ys;
	private final int plane;

	/** Distance from the start to each waypoint, in tiles. */
	private final int[] reached;

	/** Total length of the route in tiles. */
	private final int length;

	/** The tick the golem left the first waypoint. */
	@Getter
	private final int startTick;

	/** Ticks the whole route takes, so expiry is a comparison rather than a walk. */
	@Getter
	private final int duration;

	/**
	 * True if this route crosses water rather than walking. A roaming route is a straight line
	 * drawn without consulting the map, since at Tier 3 nothing observes it, so a golem promoted
	 * into view mid-route must be put back on walkable ground first. A voyage was searched
	 * across the ocean mesh, so it survives being watched.
	 */
	@Getter
	private final boolean voyage;

	/**
	 * Where a transport at the end of the walk puts the golem, or null for a plain route. Kept
	 * apart from the waypoints: as the last one, a ladder into a dungeon joins tiles some six
	 * thousand apart, and that distance was walked at a tick a tile - one ladder took an hour.
	 * Using the transport is a wait at the end of the walk.
	 */
	private final WorldPoint landing;

	/** The transport that ends the route, or null. Taken on arrival, not when planned. */
	private final GolemTransport transport;

	/**
	 * For a crossing, where the raft is at the end of every tick and which way it faces, in fine
	 * units and 2048ths of a turn; null otherwise. A boat turns a compass point a tick and moves
	 * the way it faces, so its path is decided when the crossing is planned and only read here.
	 */
	private final int[] fineXs;
	private final int[] fineYs;
	private final int[] facings;

	/**
	 * For a crossing, the dock it leaves, or -1. Whoever takes the crossing may not sail straight
	 * back there; set on the golem as it takes it, not as it is planned, since a crossing planned
	 * is not always sailed - a crew's muster can hold it at the quay instead.
	 */
	@Getter
	@Setter
	private int leftPort = -1;

	private Itinerary(int[] xs, int[] ys, int[] reached, int length, int plane,
		int startTick, int duration, boolean voyage, WorldPoint landing, GolemTransport transport,
		int[] fineXs, int[] fineYs, int[] facings)
	{
		this.fineXs = fineXs;
		this.fineYs = fineYs;
		this.facings = facings;
		this.transport = transport;
		this.xs = xs;
		this.ys = ys;
		this.reached = reached;
		this.length = length;
		this.plane = plane;
		this.startTick = startTick;
		this.duration = duration;
		this.voyage = voyage;
		this.landing = landing;
	}

	/** Plans a walking route, one tick per tile. */
	static Itinerary of(List<int[]> path, int plane, int startTick, int extra)
	{
		return of(path, plane, startTick, 1, extra, false);
	}

	/**
	 * Plans a route.
	 *
	 * @param path         tiles in order, as {@code {x, y}} pairs; the golem's tile first
	 * @param ticksPerTile pace - one for walking, more for something slower
	 * @param extra        ticks on top of the travel itself, for boarding and the like
	 * @param voyage       true if this crosses water
	 */
	static Itinerary of(List<int[]> path, int plane, int startTick, int ticksPerTile,
		int extra, boolean voyage)
	{
		if (path == null || path.isEmpty())
		{
			return null;
		}

		int[] xs = new int[path.size()];
		int[] ys = new int[path.size()];
		int[] reached = new int[path.size()];

		int travelled = 0;
		for (int i = 0; i < path.size(); i++)
		{
			xs[i] = path.get(i)[0];
			ys[i] = path.get(i)[1];
			if (i > 0)
			{
				// Chebyshev: a diagonal step costs one tick exactly as a cardinal one does.
				// Euclidean tiles would make diagonal legs take longer than the game does.
				travelled += span(xs[i] - xs[i - 1], ys[i] - ys[i - 1]);
			}
			reached[i] = travelled;
		}

		return new Itinerary(xs, ys, reached, travelled, plane, startTick,
			Math.max(1, travelled * ticksPerTile + extra), voyage, null, null, null, null, null);
	}

	/**
	 * Plans a walk to a transport's origin, then the transport. The walk takes a tick a tile, the
	 * golem then waits at the origin for as long as the transport takes.
	 *
	 * @param walk tiles to the transport's origin, the golem's own tile first
	 */
	static Itinerary thenTransport(List<int[]> walk, int plane, int startTick, GolemTransport transport)
	{
		Itinerary route = of(walk, plane, startTick, 1, 0, false);
		if (route == null)
		{
			return null;
		}
		return new Itinerary(route.xs, route.ys, route.reached, route.length, plane, startTick,
			route.length + Math.max(1, transport.getDuration()), false, transport.destination(), transport, null, null, null);
	}

	/**
	 * A crossing with no drawn route: the golem waits where it is, then is at the landing. A
	 * voyage, so it survives being watched.
	 */
	static Itinerary passage(WorldPoint from, WorldPoint landing, int startTick, int ticks)
	{
		int[] xs = {from.getX()};
		int[] ys = {from.getY()};
		return new Itinerary(xs, ys, new int[]{0}, 0, from.getPlane(), startTick, Math.max(1, ticks), true,
			landing, null, null, null, null);
	}

	/**
	 * A crossing by sea, sailed tick by tick: where the raft is and which way it faces at the end
	 * of each tick, then the golem stepping ashore. It starts on the water, at the mooring, so
	 * the golem is on the raft from its first frame.
	 *
	 * @param fineXs  position at the end of each tick, in fine units; the mooring first
	 * @param facings heading at the end of each tick, 0 south, 512 west, 1024 north, 1536 east
	 */
	static Itinerary steered(int[] fineXs, int[] fineYs, int[] facings, int plane, int startTick, WorldPoint landing)
	{
		int n = fineXs.length;
		int[] xs = new int[n];
		int[] ys = new int[n];
		int[] reached = new int[n];
		int travelled = 0;
		for (int i = 0; i < n; i++)
		{
			xs[i] = Math.floorDiv(fineXs[i], Golem.TILE);
			ys[i] = Math.floorDiv(fineYs[i], Golem.TILE);
			if (i > 0)
			{
				travelled += span(xs[i] - xs[i - 1], ys[i] - ys[i - 1]);
			}
			reached[i] = travelled;
		}
		return new Itinerary(xs, ys, reached, travelled, plane, startTick, Math.max(1, n - 1), true, landing,
			null, fineXs, fineYs, facings);
	}

	/** Where a crossing is this far in, in fine units: gliding from one tick's position to the next. */
	private int[] alongCrossing(double time)
	{
		int last = fineXs.length - 1;
		if (time >= last)
		{
			return new int[]{fineXs[last], fineYs[last]};
		}
		int i = (int) Math.floor(time);
		if (jumps(i))
		{
			// Through a cave mouth: out of one and straight in at the other, not sliding
			// the thousands of tiles between.
			return new int[]{fineXs[i], fineYs[i]};
		}
		double into = time - i;
		return new int[]{
			fineXs[i] + (int) Math.round((fineXs[i + 1] - fineXs[i]) * into),
			fineYs[i] + (int) Math.round((fineYs[i + 1] - fineYs[i]) * into),
		};
	}

	/** A move between two ticks longer than any boat makes: a raft put through from one cave mouth to the other. */
	private static final int JUMP = 16 * Golem.TILE;

	private boolean jumps(int tick)
	{
		return Math.abs(fineXs[tick + 1] - fineXs[tick]) > JUMP || Math.abs(fineYs[tick + 1] - fineYs[tick]) > JUMP;
	}

	/**
	 * Which way a crossing's raft faces part way through a tick, turning the short way from one
	 * tick's heading to the next; -1 for any other route.
	 */
	int facingAt(int tick, float fraction)
	{
		if (facings == null)
		{
			return -1;
		}
		int last = facings.length - 1;
		double time = Math.max(0, tick + (double) fraction - startTick);
		if (time >= last)
		{
			return facings[last];
		}
		int i = (int) Math.floor(time);
		if (jumps(i))
		{
			return facings[i];
		}
		int turn = ((facings[i + 1] - facings[i] + 1024) & 2047) - 1024;
		return (facings[i] + (int) Math.round(turn * (time - i))) & 2047;
	}

	/** The waypoint the golem is at or has most recently passed at this tick. */
	private int segmentAt(int tick)
	{
		return fineXs != null ? Math.min(fineXs.length - 1, Math.max(0, tick - startTick))
			: segmentFor((int) Math.floor(travelledAt(tick)));
	}

	/**
	 * Where the golem is at this tick, in 128ths of a tile. Interpolated by distance, so a golem
	 * on a long straight leg moves along it, and clamped at both ends: an expired route means it
	 * has arrived and waits, not that it has vanished.
	 */
	int[] fineAt(int tick)
	{
		return fineAt(tick, 0f);
	}

	/**
	 * As {@link #fineAt(int)}, part way through a tick. For a golem in view: read in whole ticks
	 * and tiles, a boat stepped across the sea instead of gliding.
	 *
	 * @param fraction how far through the tick, 0 to 1
	 */
	int[] fineAt(int tick, float fraction)
	{
		if (landing != null && isFinished(tick))
		{
			return fine(landing.getX(), landing.getY());
		}
		if (fineXs != null)
		{
			return alongCrossing(Math.max(0, tick + (double) fraction - startTick));
		}
		return along(travelledAt(tick + (double) fraction));
	}

	/** The tick {@link #memoX} and {@link #memoY} were worked out for. */
	private int memoTick = Integer.MIN_VALUE;
	private int memoX;
	private int memoY;

	/**
	 * {@link #fineAt(int)}'s x, kept for the tick it was asked for: a route never changes once
	 * planned, so a tick's answer is worked out once however many frames ask for it.
	 */
	int fineXAt(int tick)
	{
		memoise(tick);
		return memoX;
	}

	/** {@link #fineAt(int)}'s y; see {@link #fineXAt}. */
	int fineYAt(int tick)
	{
		memoise(tick);
		return memoY;
	}

	private void memoise(int tick)
	{
		if (tick != memoTick)
		{
			int[] at = fineAt(tick);
			memoX = at[0];
			memoY = at[1];
			memoTick = tick;
		}
	}

	/** Tiles along the waypoints the golem has covered by this time, in ticks. */
	private double travelledAt(double time)
	{
		double elapsed = Math.min(Math.max(0, time - startTick), duration);
		if (landing != null)
		{
			// A tick a tile, then standing at the transport until it is used.
			return Math.min(elapsed, length);
		}
		return length <= 0 || duration <= 0 ? 0 : elapsed * length / duration;
	}

	/** The position a given distance along the waypoints, in fine units. */
	private int[] along(double travelled)
	{
		int segment = segmentFor((int) Math.floor(travelled));
		if (segment >= xs.length - 1)
		{
			return fine(xs[xs.length - 1], ys[ys.length - 1]);
		}

		int from = reached[segment];
		int span = reached[segment + 1] - from;
		if (span <= 0)
		{
			return fine(xs[segment], ys[segment]);
		}

		// Sub-tile position along this leg, so movement is smooth rather than stepped.
		double into = travelled - from;
		int fromX = fine(xs[segment]);
		int fromY = fine(ys[segment]);
		int toX = fine(xs[segment + 1]);
		int toY = fine(ys[segment + 1]);

		return new int[]{
			fromX + (int) Math.round((toX - fromX) * into / span),
			fromY + (int) Math.round((toY - fromY) * into / span),
		};
	}

	/** The waypoint the golem has most recently passed. */
	private int segmentFor(int travelled)
	{
		int low = 0;
		int high = reached.length - 1;
		while (low < high)
		{
			int mid = (low + high + 1) >>> 1;
			if (reached[mid] <= travelled)
			{
				low = mid;
			}
			else
			{
				high = mid - 1;
			}
		}
		return low;
	}

	/** Where the golem is at this tick, to the nearest tile. */
	WorldPoint positionAt(int tick)
	{
		int[] at = fineAt(tick);
		return new WorldPoint(at[0] / Golem.TILE, at[1] / Golem.TILE, planeAt(tick));
	}

	/**
	 * The plane the golem is on at this tick: the walk's, until a transport has moved it.
	 * Reading the destination's plane had a golem walking to a ladder already upstairs.
	 */
	int planeAt(int tick)
	{
		return landing != null && isFinished(tick) ? landing.getPlane() : plane;
	}

	/**
	 * The direction the golem is travelling at this tick, as a fine-unit delta. Taken from the
	 * leg it is on, not from where it was last frame, so a stationary golem still faces the way
	 * it is going.
	 */
	int[] headingAt(int tick)
	{
		if (facings != null)
		{
			double angle = (facingAt(tick, 0f) - 1024) * Math.PI / 1024;
			return new int[]{(int) Math.round(Math.sin(angle) * Golem.TILE), (int) Math.round(Math.cos(angle) * Golem.TILE)};
		}
		if (length <= 0)
		{
			return new int[]{0, 0};
		}
		int segment = segmentAt(tick);
		if (segment >= xs.length - 1)
		{
			segment = Math.max(0, xs.length - 2);
		}
		return new int[]{
			(xs[segment + 1] - xs[segment]) * Golem.TILE,
			(ys[segment + 1] - ys[segment]) * Golem.TILE,
		};
	}

	/** True once the route has been fully travelled and a new one is needed. */
	boolean isFinished(int tick)
	{
		return tick - startTick >= duration;
	}

	/** Where the golem ends up: the landing of a transport, or the last waypoint. */
	WorldPoint destination()
	{
		return landing != null ? landing : walkEnd();
	}

	/** The last waypoint: the origin of a transport, or the destination of a plain route. */
	WorldPoint walkEnd()
	{
		// Made once: a golem out of view that has arrived asks for this every frame until
		// it gets a new route.
		if (walkEnd == null)
		{
			walkEnd = new WorldPoint(xs[xs.length - 1], ys[ys.length - 1], plane);
		}
		return walkEnd;
	}

	private WorldPoint walkEnd;

	/** True if the golem stays where it is for this route's length: a pause, not a journey. */
	boolean isStationary()
	{
		return xs.length == 1 && landing == null && transport == null && !voyage;
	}

	/** True if this is a crossing by sea with legs to sail, rather than a passage or a walk. */
	boolean isSailed()
	{
		return voyage && xs.length > 1;
	}

	/** The transport this route ends in, or null. */
	GolemTransport transport()
	{
		return transport;
	}

	/**
	 * The same route walked backwards from where the golem has got to: the second rung of the
	 * raft's unstick ladder, since a boat in a dead-end inlet got there along an open route.
	 *
	 * @return a route back toward the start, or null if there is nothing to back out of
	 */
	Itinerary reversed(int tick, int newStartTick)
	{
		int at = segmentAt(tick);
		if (at < 1)
		{
			return null;
		}

		List<int[]> back = new ArrayList<>();
		for (int i = at; i >= 0; i--)
		{
			back.add(new int[]{xs[i], ys[i]});
		}

		// Same pace it came in at, which the route's length over its duration already says; a
		// walk to a transport went at a tick a tile.
		int ticksPerTile = landing != null ? 1 : Math.max(1, duration / Math.max(1, length));
		return of(back, plane, newStartTick, ticksPerTile, 0, voyage);
	}

	private static int fine(int tile)
	{
		return tile * Golem.TILE + Golem.TILE / 2;
	}

	private static int[] fine(int tileX, int tileY)
	{
		return new int[]{fine(tileX), fine(tileY)};
	}
}

package com.golemsdontdie;

/**
 * Shortcuts whose real animation was watched in game, keyed by the object.
 *
 * <p>Which clip an obstacle plays is decided server-side and appears in no file - object
 * definitions carry the object's own animation, not the person's - so every entry below was
 * measured in game. Measurements beat the archetype mapping in {@link GolemTransport}, which
 * guesses from the menu text: it put the basalt stones on the 68-cycle
 * {@code HUMAN_STEPPINGSTONEJUMP} rather than the 38-cycle 741, doubling every hop. The
 * archetype still answers for the thirteen thousand nobody has measured.
 */
final class MeasuredShortcuts
{
	private MeasuredShortcuts()
	{
	}

	/**
	 * {objectId, animationId, ticks}. Ticks of zero mean the clip's own length is used, usually
	 * right: the cathedral door measured one tick against a 30-cycle clip, the cave three
	 * against 96.
	 */
	private static final int[][] MEASURED = {
		// Wyrmscraig basalt stepping stones; hops two ticks apart, the 38-cycle clip plus a breath.
		{62260, 741, 0},
		{62261, 741, 0},
		{62262, 741, 0},

		// Wyrmscraig's rock climb: two co-located objects, one per approach, east being the top.
		// West (2550, 2209) uses 62267, the 4435 climbing loop; east (2554, 2209) uses 62265,
		// HUMAN_CLIMBING_DOWN 740. Climbs are directional; the rows once used 62267 both ways
		// and the golem climbed the wrong way down.
		{62267, 4435, 0},
		{62265, 740, 0},

		// The cave mouth, both ends: three ticks, and a 96-cycle clip that agrees.
		{62219, 2796, 3},
		{62220, 2796, 3},

		// A door, for calibration: one tick against a 30-cycle clip.
		{62368, 4282, 1},
		{62369, 4282, 1},
	};

	/** The measured animation for an object, or -1 if unmeasured. */
	static int animationFor(int objectId)
	{
		for (int[] row : MEASURED)
		{
			if (row[0] == objectId)
			{
				return row[1];
			}
		}
		return -1;
	}

	/** The measured duration in ticks, or 0 to use the clip's own length. */
	static int ticksFor(int objectId)
	{
		for (int[] row : MEASURED)
		{
			if (row[0] == objectId)
			{
				return row[2];
			}
		}
		return 0;
	}
}

package com.golemsdontdie;

import java.util.*;
import lombok.*;

/**
 * A traversal as it actually happened, cycle by cycle, ready to be performed again.
 *
 * <p>This replaces a parametric model of clip, delay and duration, which had to rebuild the
 * motion differently for every obstacle shape - a hop, a climb and a door all want something
 * else - so fitting it to one broke it on another. The position is already recorded every
 * 20ms, so the motion is kept and replayed instead; a teleport is a curve that does not move
 * and then does.
 *
 * <h2>Why it is stored rotated</h2>
 *
 * <p>Samples run along the traversal's own axis, <b>forward</b> toward the destination and
 * <b>sideways</b>, not north and east, so one recording serves every instance of that
 * obstacle whichever way it faces.
 */
@AllArgsConstructor
final class MotionCurve
{
	/**
	 * Client cycles between stored samples. Two: movement is interpolated between samples
	 * anyway, and at 40ms a hop is twenty numbers rather than forty, small enough to keep
	 * hundreds of these in a config value.
	 */
	static final int SAMPLE_EVERY = 2;

	/** Longest curve worth keeping, in cycles. Beyond this it is not a traversal. */
	static final int MAX_CYCLES = 600;

	/**
	 * Distance along the traversal axis at each sample, in 128ths of a tile, forward being
	 * toward the destination. Ending short is normal: the last part of some traversals is a
	 * teleport, so the final sample is nowhere near the end.
	 */
	private final short[] forward;

	/** Sideways offset at each sample. Nonzero for anything that swings or staggers. */
	private final short[] lateral;

	/**
	 * {cycle, animationId, startingFrame} at each point the animation changed. The frame
	 * matters because the client advances the clip at the render rate while position
	 * advances on cycle count; any disagreement reads as the animation skipping.
	 */
	private final int[][] animations;

	private final int cycles;

	/**
	 * Which way the player faced while traversing, relative to the direction of travel, in
	 * orientation units - 0 forwards, 1024 backwards - or -1 if not recorded. Not always
	 * forwards: on the rockslide they face the rock and move away from it, and a golem
	 * facing its travel climbs off the cliff.
	 */
	private final int facing;

	/**
	 * The keyframe the player's animation was on at each sample, -1 where none, or null for
	 * a recording predating keyframes. The clip does not run at authored speed: on a basalt
	 * stone it holds its first keyframe about twenty-five cycles, so played as authored a
	 * golem finished the hop before leaving the ground.
	 */
	private final short[] keyframes;

	boolean hasKeyframes()
	{
		return keyframes != null;
	}

	/** Facing relative to travel, or -1 if the recording predates it. */
	int facing()
	{
		return facing;
	}

	boolean hasFacing()
	{
		return facing >= 0;
	}

	int cycles()
	{
		return cycles;
	}

	/**
	 * The recording as plain numbers, one entry per sample: {cycle, forward, lateral}. For
	 * the obstacle data file, which depends on nothing in this class.
	 */
	int[][] samples()
	{
		int[][] out = new int[forward.length][];
		for (int i = 0; i < forward.length; i++)
		{
			out[i] = new int[]{i * SAMPLE_EVERY, forward[i], i < lateral.length ? lateral[i] : 0};
		}
		return out;
	}

	/** Each point the animation changed, as plain numbers: {cycle, animation}. */
	int[][] animationChanges()
	{
		int[][] out = new int[animations.length][];
		for (int i = 0; i < animations.length; i++)
		{
			out[i] = new int[]{animations[i][0], animations[i][1]};
		}
		return out;
	}

	boolean isEmpty()
	{
		return forward.length == 0;
	}

	/**
	 * The animation that should be playing at this point, or -1. Read from the recorded
	 * timeline rather than decided: an obstacle that plays three clips in sequence does so
	 * because the recording did.
	 */
	int animationAt(int cycle)
	{
		int playing = -1;
		for (int[] change : animations)
		{
			if (change[0] > cycle)
			{
				break;
			}
			playing = change[1];
		}
		return playing;
	}

	/** The frame the animation should be on at this point, or -1 if not recorded. */
	int frameAt(int cycle)
	{
		// Between clips there is no frame to drive: the golem's idle runs on the client's
		// clock, as does any recording made before keyframes were kept.
		if (keyframes == null || animationAt(cycle) == -1)
		{
			return -1;
		}
		return keyframes[Math.max(0, Math.min(cycle / SAMPLE_EVERY, keyframes.length - 1))];
	}

	/** How far along its axis the recording travelled in total, in fine units. */
	int reach()
	{
		return forward.length == 0 ? 0 : forward[forward.length - 1];
	}

	/** Movement smaller than this, in fine units, is sampling rather than going anywhere. */
	private static final int STILL = 8;

	/**
	 * Samples of stillness that separate two movements. Six is twelve cycles: the quantised
	 * source stalls a cycle or two mid-climb, which is sampling, while the pause between two
	 * basalt hops is over fifteen, which is a second step.
	 */
	private static final int HOLD_SAMPLES = 6;

	/** The furthest the recording strays from its own axis. */
	int maxLateral()
	{
		int most = 0;
		for (short value : lateral)
		{
			most = Math.max(most, Math.abs(value));
		}
		return most;
	}

	/**
	 * How many separate movements the recording holds. One for any single obstacle; more
	 * means a chained crossing was captured as one traversal, which a transport covering
	 * one step of it cannot replay.
	 */
	int bursts()
	{
		int count = 0;
		int still = HOLD_SAMPLES;
		for (int i = 1; i < forward.length; i++)
		{
			boolean moved = Math.abs(forward[i] - forward[i - 1])
				+ Math.abs(lateral[i] - lateral[i - 1]) > 1;
			if (moved)
			{
				if (still >= HOLD_SAMPLES)
				{
					count++;
				}
				still = 0;
			}
			else
			{
				still++;
			}
		}
		return count;
	}

	/** The cycle the first animation starts on, or 0 if there is none. */
	int firstAnimationCycle()
	{
		for (int[] change : animations)
		{
			if (change[1] != -1)
			{
				return change[0];
			}
		}
		return 0;
	}

	/**
	 * The cycle the recording first moves once its animation has begun, or -1 if it never
	 * does. From the animation, not the start, since a walk onto the obstacle may come
	 * first; the wind-up measured is the pause between the clip starting and the jump.
	 */
	int firstMoveCycle()
	{
		int from = Math.min(firstAnimationCycle() / SAMPLE_EVERY, forward.length - 1);
		for (int i = from; i < forward.length; i++)
		{
			if (Math.abs(forward[i] - forward[from]) + Math.abs(lateral[i] - lateral[from]) > STILL)
			{
				return i * SAMPLE_EVERY;
			}
		}
		return -1;
	}

	/** The cycle the recording arrives where it finishes, or -1 if it never moved. */
	int lastMoveCycle()
	{
		int end = forward.length - 1;
		for (int i = end; i >= 0; i--)
		{
			if (Math.abs(forward[i] - forward[end]) + Math.abs(lateral[i] - lateral[end]) > STILL)
			{
				return Math.min(cycles, (i + 1) * SAMPLE_EVERY);
			}
		}
		return -1;
	}

	/**
	 * Where the golem should be at this cycle, as an offset from where it started, into
	 * {@code out} in world fine units. {@code axisX, axisY} is the unit vector toward the
	 * destination, turning the stored forward-and-sideways pair back into a direction.
	 */
	void offsetAt(int cycle, float axisX, float axisY, int[] out)
	{
		offsetAt(cycle, axisX, axisY, 1f, out);
	}

	/**
	 * As {@link #offsetAt}, with the forward distance scaled. A golem may take an obstacle
	 * from a tile or two from where the player did, so scaling lands it where its own
	 * transport says, keeping the recording's timing and sideways movement.
	 */
	void offsetAt(int cycle, float axisX, float axisY, float scale, int[] out)
	{
		if (forward.length == 0)
		{
			out[0] = 0;
			out[1] = 0;
			return;
		}

		// Between samples, because the samples are every other cycle and a golem is drawn
		// every one of them.
		float at = Math.max(0, Math.min(cycle, cycles)) / (float) SAMPLE_EVERY;
		int i = Math.min((int) at, forward.length - 1);
		int j = Math.min(i + 1, forward.length - 1);
		float t = at - i;

		// Except across a teleport, which is not interpolated. A door moves the player a
		// whole tile in one cycle and samples are two cycles apart, so interpolating slid
		// the golem through the door instead of putting it on one side and then the other.
		if (Math.abs(forward[j] - forward[i]) + Math.abs(lateral[j] - lateral[i]) > NOISE_STEP)
		{
			t = 0f;
		}

		float f = (forward[i] + (forward[j] - forward[i]) * t) * scale;
		float l = lateral[i] + (lateral[j] - lateral[i]) * t;

		// Forward along the axis, sideways across it.
		out[0] = Math.round(f * axisX - l * axisY);
		out[1] = Math.round(f * axisY + l * axisX);
	}

	/**
	 * Builds a curve from positions sampled during a traversal.
	 *
	 * @param samples  {cycle, worldFineX, worldFineY} for each observation, in order
	 * @param anims    {cycle, animationId} for each animation change
	 * @param toFineX  the destination, for working out which way is forward
	 */
	static MotionCurve record(List<int[]> samples, List<int[]> anims,
		int fromFineX, int fromFineY, int toFineX, int toFineY)
	{
		if (samples.isEmpty())
		{
			return null;
		}

		int span = samples.get(samples.size() - 1)[0] - samples.get(0)[0];
		if (span <= 0 || span > MAX_CYCLES)
		{
			return null;
		}

		// The axis is the straight line to the destination. Where a traversal does not move
		// at all - a ladder, which animates and then teleports - north stands in; nothing is
		// projected onto it anyway.
		float dx = toFineX - fromFineX;
		float dy = toFineY - fromFineY;
		float length = (float) Math.sqrt(dx * dx + dy * dy);
		float axisX = length < 1 ? 0f : dx / length;
		float axisY = length < 1 ? 1f : dy / length;

		int base = samples.get(0)[0];
		int count = span / SAMPLE_EVERY + 1;
		short[] forward = new short[count];
		short[] lateral = new short[count];

		short[] keys = new short[count];
		boolean[] seen = new boolean[count];
		boolean anyKey = false;

		int next = 0;
		for (int[] sample : samples)
		{
			int slot = (sample[0] - base) / SAMPLE_EVERY;
			if (slot < next || slot >= count)
			{
				continue;
			}
			float ox = sample[1] - fromFineX;
			float oy = sample[2] - fromFineY;
			forward[slot] = (short) Math.round(ox * axisX + oy * axisY);
			lateral[slot] = (short) Math.round(-ox * axisY + oy * axisX);
			keys[slot] = (short) (sample.length > 5 ? sample[5] : -1);
			anyKey |= keys[slot] >= 0;
			seen[slot] = true;
			next = slot + 1;
		}
		for (int i = 0; i < count; i++)
		{
			if (!seen[i])
			{
				keys[i] = i == 0 ? -1 : keys[i - 1];
			}
		}

		// Any slot no sample landed in carries the one before it, so a gap in the
		// observations holds still rather than snapping back to the start.
		for (int i = 1; i < count; i++)
		{
			// By what was seen, not by zero: a real sample back at the start is somewhere to be.
			if (!seen[i])
			{
				forward[i] = forward[i - 1];
				lateral[i] = lateral[i - 1];
			}
		}

		smooth(forward);
		smooth(lateral);

		// Starting frames are stored as zero rather than left out. Leaving them out made a
		// curve recorded this session play on the client's clock and the same curve loaded
		// from config play on the recording's, so one obstacle behaved two ways.
		List<int[]> kept = new ArrayList<>();
		for (int i = 0; i < anims.size(); i++)
		{
			int[] change = anims.get(i);
			// A looping clip reports -1 for a cycle between repeats. Not the animation
			// ending; honouring it would flash the golem out of its climb.
			if (change[1] == -1 && i + 1 < anims.size() && anims.get(i + 1)[0] - change[0] <= 4)
			{
				continue;
			}
			kept.add(new int[]{Math.max(0, change[0] - base), change[1], 0});
		}
		int[][] timeline = kept.toArray(new int[0][]);

		// Facing relative to the way the traversal goes, from the moment it animates. The
		// most common of eight directions: the player turns once at the start and holds it.
		int facing = -1;
		if (length >= Golem.TILE / 2f)
		{
			int heading = (int) (1024 + Math.round(Math.atan2(dx, dy) / Math.PI * 1024)) & 2047;
			int from = anims.isEmpty() ? base : anims.get(0)[0];
			int[] bins = new int[8];
			int counted = 0;
			for (int[] sample : samples)
			{
				if (sample.length > 4 && sample[4] >= 0 && sample[0] >= from)
				{
					bins[((sample[4] - heading + 128) & 2047) / 256]++;
					counted++;
				}
			}
			if (counted > 0)
			{
				int best = 0;
				for (int b = 1; b < bins.length; b++)
				{
					if (bins[b] > bins[best])
					{
						best = b;
					}
				}
				facing = best * 256;
			}
		}

		return new MotionCurve(forward, lateral, timeline, span, facing, anyKey ? keys : null);
	}

	/**
	 * The largest step that can be sampling noise rather than real movement. Three quarters
	 * of a tile: climb artefacts came back as steps of forty to sixty units, a door's
	 * teleport is a whole tile in one sample, and nothing observed sits between.
	 */
	private static final int NOISE_STEP = Golem.TILE * 3 / 4;

	/**
	 * Evens out the sampling, which is coarser than the motion it samples, but only where
	 * the motion really is continuous.
	 *
	 * <p>{@code getLocalLocation} does not report the smooth position the client draws, so a
	 * recorded climb came back as plateaus of two or three samples and then a jump of forty
	 * to sixty, which a golem performed as holding still and lurching. Averaging all of it
	 * was wrong the other way, beginning a door's teleport before its animation finished, so
	 * a step larger than {@link #NOISE_STEP} is taken to be real and never averaged across.
	 */
	private static void smooth(short[] values)
	{
		if (values.length < 3)
		{
			return;
		}

		short[] source = values.clone();
		for (int i = 1; i < values.length - 1; i++)
		{
			if (Math.abs(source[i] - source[i - 1]) > NOISE_STEP
				|| Math.abs(source[i + 1] - source[i]) > NOISE_STEP)
			{
				// A real discontinuity on one side or the other. Leave it alone.
				continue;
			}
			values[i] = (short) Math.round((source[i - 1] + source[i] + source[i + 1]) / 3f);
		}
	}

	// ------------------------------------------------------------------ storage

	/** {@code cycles|f,f,f|l,l,l|cycle:anim:frame,...|facing|k,k,k} */
	String serialise()
	{
		StringBuilder sb = new StringBuilder().append(cycles).append('|');
		for (int i = 0; i < forward.length; i++)
		{
			sb.append(i == 0 ? "" : ",").append(forward[i]);
		}
		sb.append('|');
		for (int i = 0; i < lateral.length; i++)
		{
			sb.append(i == 0 ? "" : ",").append(lateral[i]);
		}
		sb.append('|');
		for (int i = 0; i < animations.length; i++)
		{
			sb.append(i == 0 ? "" : ",").append(animations[i][0]).append(':')
				.append(animations[i][1]).append(':')
				.append(animations[i].length > 2 ? animations[i][2] : 0);
		}
		sb.append('|').append(facing).append('|');
		if (keyframes != null)
		{
			for (int i = 0; i < keyframes.length; i++)
			{
				sb.append(i == 0 ? "" : ",").append(keyframes[i]);
			}
		}
		return sb.toString();
	}

	static MotionCurve parse(String text)
	{
		try
		{
			String[] parts = text.split("\\|", -1);
			if (parts.length < 4)
			{
				return null;
			}

			int cycles = Integer.parseInt(parts[0]);
			short[] forward = shorts(parts[1]);
			short[] lateral = shorts(parts[2]);
			if (forward.length != lateral.length || forward.length == 0)
			{
				return null;
			}

			List<int[]> anims = new ArrayList<>();
			if (!parts[3].isEmpty())
			{
				for (String change : parts[3].split(","))
				{
					String[] pair = change.split(":");
					anims.add(pair.length > 2
						? new int[]{Integer.parseInt(pair[0]), Integer.parseInt(pair[1]),
							Integer.parseInt(pair[2])}
						: new int[]{Integer.parseInt(pair[0]), Integer.parseInt(pair[1])});
				}
			}
			// Recordings made before facing was kept have four fields and load as unknown.
			int facing = parts.length > 4 && !parts[4].isEmpty() ? Integer.parseInt(parts[4]) : -1;
			short[] keyframes = parts.length > 5 && !parts[5].isEmpty() ? shorts(parts[5]) : null;
			if (keyframes != null && keyframes.length != forward.length)
			{
				keyframes = null;
			}
			return new MotionCurve(forward, lateral, anims.toArray(new int[0][]), cycles, facing,
				keyframes);
		}
		catch (RuntimeException e)
		{
			// One unreadable curve costs its own obstacle and nothing else.
			return null;
		}
	}

	private static short[] shorts(String csv)
	{
		if (csv.isEmpty())
		{
			return new short[0];
		}
		String[] parts = csv.split(",");
		short[] out = new short[parts.length];
		for (int i = 0; i < parts.length; i++)
		{
			out[i] = Short.parseShort(parts[i]);
		}
		return out;
	}

	@Override
	public String toString()
	{
		return "curve " + cycles + "c " + forward.length + " samples, "
			+ animations.length + " anim changes";
	}
}

package com.golemsdontdie;

import com.golemsdontdie.telemetry.*;
import java.io.*;
import javax.inject.*;
import net.runelite.client.util.*;

/**
 * The one place the plugin hands anything to the obstacle data file.
 *
 * <p>Copies numbers out of the plugin's own objects into the plain records of the
 * {@code telemetry} package, and nothing else: no decisions about what to keep are made here beyond
 * which fields to copy. See that package for what is kept and why.
 */
@Singleton
class ObstacleDataBridge
{
	@Inject
	private TransportNetwork transports;

	private ObstacleDataFile file;

	/**
	 * @param folder the plugin's own folder, or null if RuneLite could not give it one: then nothing
	 *               is kept, and play goes on without it
	 */
	void startUp(Filepath folder)
	{
		if (folder == null)
		{
			file = null;
			return;
		}
		Filepath path = folder.join(ObstacleDataFile.FILE_NAME);
		file = new ObstacleDataFile(new ObstacleDataFile.Store()
		{
			@Override
			public boolean exists()
			{
				return path.exists();
			}

			@Override
			public BufferedReader reader() throws IOException
			{
				return path.openBufferedReader();
			}

			@Override
			public void write(String text) throws IOException
			{
				folder.createDirectories();
				path.write(text);
			}
		}, GolemsDontDiePlugin.VERSION);
		file.load();
	}

	void save()
	{
		if (file != null)
		{
			file.save();
		}
	}

	/** A crossing the player made, already judged to be an obstacle. */
	void playerCrossed(ObstacleSighting s)
	{
		if (file == null)
		{
			return;
		}
		MotionCurve curve = s.curve;
		file.add(new PlayerCrossing(s.objectId, s.name, s.menu, s.clips, s.ticks, s.moveDelay, s.moveSpan,
			s.fromX, s.fromY, s.fromPlane, s.toX, s.toY, s.toPlane, s.lineX, s.lineY, s.instance,
			curve == null ? new int[0][] : curve.samples(),
			curve == null ? new int[0][] : curve.animationChanges(),
			curve == null ? -1 : curve.facing()));
	}

	/** A crossing a golem made in view. See GolemTraversal. */
	void golemCrossed(GolemTraversal t)
	{
		if (file == null)
		{
			return;
		}
		GolemTransport route = t.route;
		file.add(new GolemCrossing(route.getObjectId(),
			route.getFromX(), route.getFromY(), route.getFromPlane(),
			route.getToX(), route.getToY(), route.getToPlane(),
			t.samples.toArray(new int[0][]), passesOverStone(route)));
	}

	/**
	 * True if a route passes over a tile another short hop starts on, between its two ends: a
	 * stepping stone the golem did not land on.
	 */
	private boolean passesOverStone(GolemTransport route)
	{
		int dx = Integer.signum(route.getToX() - route.getFromX());
		int dy = Integer.signum(route.getToY() - route.getFromY());
		int x = route.getFromX() + dx;
		int y = route.getFromY() + dy;
		for (int step = 0; step < 16 && (x != route.getToX() || y != route.getToY()); step++)
		{
			if (transports.isStone(x, y, route.getFromPlane()))
			{
				return true;
			}
			x += dx;
			y += dy;
		}
		return false;
	}
}

package com.golemsdontdie;

import java.io.*;
import java.util.*;
import java.util.zip.*;
import javax.inject.*;
import lombok.extern.slf4j.*;

/**
 * Where every obstacle in the game is, read from the cache and shipped.
 *
 * <p>Separate from {@link TransportNetwork} because only one of the two questions is easy. Where
 * the obstacles are is a fact out of the map index; where each one leads is derived from collision
 * components, and was wrong by one to three tiles on every Wyrmscraig shortcut until somebody
 * measured them. So this index claims nothing about destinations: only which objects are
 * obstacles, where they stand, and how long the cache says each takes.
 *
 * <p>Doors and gates are not here, excluded on the game's own wall-versus-scenery split: a golem
 * cannot open a door, because that changes an object every other player can see.
 */
@Slf4j
@Singleton
class ObstacleIndex
{
	private static final String RESOURCE = "/obstacles.gz";

	/** Bumped when the format changes; an old file is refused rather than misread. */
	private static final int VERSION = 4;

	/**
	 * Obstacles by the region they stand in, because "what is near here" concerns a few regions and
	 * all but a handful of obstacles are hundreds of tiles off.
	 */
	private final Map<Integer, List<Obstacle> > byRegion = new HashMap<>();

	/** The most tiles any object reaches from its anchor, which is how far a search widens. */
	private int widest;

	/** Cache traversal time per object id: asked for on the hot path, so kept apart from places. */
	private final Map<Integer, Integer> ticksByObject = new HashMap<>();

	/**
	 * One obstacle, at one place. {@code x, y} is the south-west corner, as the cache records a
	 * placement; marking only that lit one half of every two-tile object.
	 */
	static final class Obstacle
	{
		final int objectId;
		final int x;
		final int y;
		final int plane;
		final int sizeX;
		final int sizeY;

		/**
		 * True if this is mounted in a wall - a door or a gate. Kept rather than dropped, because a
		 * handful are not doors at all: the Wyrmscraig cathedral door does not swing open, it puts you
		 * on the other side.
		 */
		final boolean wall;

		/**
		 * How many game ticks this obstacle takes, from the cache, or 0 if it does not say. Neither
		 * measured nor guessed: only about fifty obstacles carry it, and it lines up with Shortest
		 * Path's hand-measured table.
		 */
		final int ticks;

		Obstacle(int objectId, int x, int y, int plane, int sizeX, int sizeY, boolean wall,
			int ticks)
		{
			this.ticks = ticks;
			this.objectId = objectId;
			this.x = x;
			this.y = y;
			this.plane = plane;
			this.sizeX = sizeX;
			this.sizeY = sizeY;
			this.wall = wall;
		}
	}

	void load()
	{
		byRegion.clear();
		ticksByObject.clear();
		known.clear();

		try (InputStream raw = ObstacleIndex.class.getResourceAsStream(RESOURCE))
		{
			if (raw == null)
			{
				log.warn("No obstacle index on the classpath; obstacles are known from the transport tables alone");
				return;
			}

			try (DataInputStream in = new DataInputStream(new GZIPInputStream(raw)))
			{
				int version = in.readInt();
				if (version != VERSION)
				{
					log.warn("Obstacle index is version {}, expected {}; ignoring it",
						version, VERSION);
					return;
				}

				int count = in.readInt();
				for (int i = 0; i < count; i++)
				{
					int objectId = in.readInt();
					int x = in.readShort() & 0xffff;
					int y = in.readShort() & 0xffff;
					int plane = in.readByte();
					int sizeX = in.readByte() & 0xff;
					int sizeY = in.readByte() & 0xff;
					boolean wall = in.readByte() != 0;
					int ticks = in.readByte() & 0xff;

					// Bucketed by the anchor's region. An object straddling a boundary is still found,
					// because the search below widens by the largest footprint any object has.
					byRegion.computeIfAbsent(region(x, y), k -> new ArrayList<>())
						.add(new Obstacle(objectId, x, y, plane, sizeX, sizeY, wall, ticks));
					widest = Math.max(widest, Math.max(sizeX, sizeY));
					known.add(objectId);
					if (ticks > 0)
					{
						ticksByObject.put(objectId, ticks);
					}
				}

				log.debug("Loaded obstacle index: {} obstacles across {} regions",
					count, byRegion.size());
			}
		}
		catch (IOException e)
		{
			// Not fatal: obstacles are then known from the transport tables alone.
			log.warn("Could not read the obstacle index", e);
		}
	}

	/**
	 * Every obstacle within {@code radius} tiles, on the given plane. Searches only the regions the
	 * box touches: a radius of a hundred spans nine of the index's two and a half thousand.
	 */
	List<Obstacle> near(int x, int y, int plane, int radius)
	{
		List<Obstacle> found = new ArrayList<>();

		// Widened by the largest object on the westward and southward sides, where an object
		// anchored in the next region along can still reach into the radius.
		for (int rx = (x - radius - widest) >> 6; rx <= (x + radius) >> 6; rx++)
		{
			for (int ry = (y - radius - widest) >> 6; ry <= (y + radius) >> 6; ry++)
			{
				List<Obstacle> here = byRegion.get((rx << 8) | ry);
				if (here == null)
				{
					continue;
				}
				for (Obstacle o : here)
				{
					// Measured to the nearest part of the object rather than its corner,
					// so a long object half inside the radius is not dropped.
					if (o.plane == plane
						&& Math.abs(o.x + o.sizeX / 2 - x) <= radius + o.sizeX
						&& Math.abs(o.y + o.sizeY / 2 - y) <= radius + o.sizeY)
					{
						found.add(o);
					}
				}
			}
		}
		return found;
	}

	/**
	 * True if the cache lists this object as something you traverse: the first question asked of
	 * anything the player is seen using, watching alone not telling an obstacle from a tree. The
	 * index holds objects whose menu offers a way across - climb, cross, squeeze, jump.
	 */
	boolean knows(int objectId)
	{
		return known.contains(objectId);
	}

	private final Set<Integer> known = new HashSet<>();

	/** The cache's traversal time for an object, in ticks, or 0: the same wherever it stands. */
	int ticksFor(int objectId)
	{
		Integer found = ticksByObject.get(objectId);
		return found == null ? 0 : found;
	}

	int size()
	{
		int n = 0;
		for (List<Obstacle> bucket : byRegion.values())
		{
			n += bucket.size();
		}
		return n;
	}

	private static int region(int x, int y)
	{
		return ((x >> 6) << 8) | (y >> 6);
	}
}

package com.golemsdontdie;

import java.util.*;
import java.util.function.*;
import javax.inject.*;
import lombok.extern.slf4j.*;
import static com.golemsdontdie.RouteGeometry.span;

/**
 * What is actually known about how each obstacle is traversed, and what golems may use.
 *
 * <p>The shipped guess at each obstacle's animation comes from the menu text and is <b>often
 * wrong</b>: a basalt stepping stone is named "stepping stone" and there is a
 * {@code HUMAN_STEPPINGSTONEJUMP}, but the game plays {@code HUMAN_SPOT_JUMP}.
 *
 * <p>So two questions are kept apart: may a golem go through here, nearly always yes, and do we
 * know what it looks like, where a no means it plays nothing, as at a door. Locking one direction
 * of a two-way transport would strand golems upstairs.
 *
 * <p>{@link ObstacleObserver} watches the player, and two consistent sightings unlock an obstacle
 * permanently - two rather than one because a single animation after a click proves nothing.
 */
@Slf4j
@Singleton
class ObstacleKnowledge
{
	/** Consistent sightings before an obstacle is trusted enough for a golem to use. */
	private static final int SIGHTINGS_TO_UNLOCK = 2;

	/**
	 * Consistent sightings after which an obstacle is set in stone: its animation, timing, line and
	 * motion are kept as they are, and later sightings no longer change them.
	 */
	static final int SIGHTINGS_TO_SETTLE = 5;

	/** Where learned obstacles are kept between sessions. */
	static final String LEARNED_KEY = "learnedObstacles";

	/** Where the individual obstacles the player has personally used are kept. */
	static final String CONFIRMED_KEY = "confirmedObstacles";

	/** Where routes learned by watching the player are kept. */
	static final String ROUTES_KEY = "learnedRoutes";

	/** Where recorded motions are kept. */
	static final String CURVES_KEY = "learnedCurves";

	/** Where the line each obstacle moves the player along is kept. */
	static final String LINES_KEY = "learnedLines";

	/**
	 * Tiles either side of a transport's origin that still count as the same obstacle. A sighting
	 * records where the player <i>stood</i>, the index where the object <i>is</i>, and on
	 * Wyrmscraig's rocks those are three apart. Measured from the nearest tile of the object's
	 * footprint, not its south-west corner, which put a three-tile cave nowhere near itself.
	 */
	private static final int CONFIRM_TOLERANCE = 3;

	/**
	 * What the player has been seen doing, by object id. Outranks everything shipped: the live
	 * game on this client beats anything measured elsewhere months ago.
	 */
	private final Map<Integer, Learned> learned = new LinkedHashMap<>();

	/**
	 * The individual obstacles the player has personally used. Kept apart from {@link #learned}
	 * because what a <i>kind</i> of object does applies everywhere, while a <i>particular</i>
	 * ladder somebody stood on only gets coloured in.
	 */
	private final Map<Integer, List<int[]>> confirmed = new LinkedHashMap<>();

	/**
	 * Where an obstacle actually took the player, by the tile they used it from: the other half of
	 * learning, since an animation alone cannot make an obstacle usable and for most of the game
	 * nothing says where it comes out. Keyed by object <i>and</i> origin, one ladder id being two
	 * thousand obstacles that each come out somewhere different.
	 */
	//
	// Insertion-ordered, as every map here is: a HashMap's order shifts as keys are added, and
	// routes become transports in that order, so each sighting renumbered every learned transport.
	private final Map<String, List<int[]>> routes = new LinkedHashMap<>();

	/**
	 * The recent recordings of each kind of obstacle, by object rather than by place: what a
	 * traversal looks like is a property of the obstacle, so one recording serves every copy.
	 * Several are kept, since keeping only the latest let one bad traversal replace good ones; the
	 * one performed is the one the others most agree with, see {@link #consensus}.
	 */
	private final Map<Integer, List<MotionCurve>> curves = new LinkedHashMap<>();

	/**
	 * The line each obstacle moves the player along, as counts of each direction seen - "0,1" for
	 * a stile crossed north or south. Counted, not taken from the first sighting, so one odd
	 * traversal cannot fix a line for good; see {@link RouteGeometry}.
	 */
	private final Map<Integer, Map<String, Integer>> lines = new LinkedHashMap<>();

	/**
	 * Which saved routes may be offered at all, as {objectId, fromX, fromY, fromPlane, toX, toY,
	 * toPlane}. Set by the plugin, so that what was learned before a rule existed is held to it:
	 * trees recorded as obstacles, routes in the coordinates of a vanished instance.
	 */
	@lombok.Setter
	private Predicate<int[]> routeFilter;

	/** The recording performed for each object, chosen from {@link #curves}. */
	private final Map<Integer, MotionCurve> chosenCurves = new HashMap<>();

	/**
	 * Recent {ticks, delay, span} per object, for the same reason. Only in memory: the saved value
	 * is itself a previous session's consensus, and seeds the history when next added to.
	 */
	private final Map<Integer, List<int[]>> timings = new HashMap<>();

	/** Recordings kept per object. Odd, so there is always a middle. */
	private static final int CURVES_KEPT = 5;

	/**
	 * How far two arrivals can differ and still count as the same route. Small, because a stepping
	 * stone mid-line leads two ways and those must stay apart.
	 */
	private static final int DESTINATION_TOLERANCE = 2;

	/** One obstacle as observed here, and how sure of it we are. */
	static final class Learned
	{
		final int[] clips;
		final int ticks;

		/** Cycles of stillness before the movement, and how long the movement lasts. */
		final int moveDelay;
		final int moveSpan;

		int sightings;

		Learned(int[] clips, int ticks, int sightings, int moveDelay, int moveSpan)
		{
			this.clips = clips;
			this.ticks = ticks;
			this.sightings = sightings;
			this.moveDelay = moveDelay;
			this.moveSpan = moveSpan;
		}

		boolean unlocked()
		{
			return sightings >= SIGHTINGS_TO_UNLOCK;
		}
	}

	// ------------------------------------------------------------------- the policy

	/**
	 * True if a golem may use this transport. The shipped defaults below are the archetypes whose
	 * animation has been measured or corroborated well enough to act on; the rest stay locked.
	 */
	boolean isUnlocked(GolemTransport transport)
	{
		int id = transport.getObjectId();
		// A golem goes through a door its own way, pushed through and out the far side, not as a
		// player does, who opens it. So there is nothing to learn from the player: a door is known
		// from the start, whatever the table says, and nothing a player is seen doing changes it.
		// Its requirements (a quest, a lever) are still GolemAbilities'.
		if (transport.getArchetype() == GolemTransport.ARCHETYPE_DOOR)
		{
			return true;
		}
		if (transport.isLearnFirst())
		{
			// Inferred, not calculated: where it leads is the guess, so seeing the same object used
			// somewhere else proves nothing about this row, and nor does seeing this one lead
			// somewhere else. It waits for a player seen going this row's own way: a course's nets
			// unlocked every net-shaped guess before, including ones walking through a net a player
			// climbs.
			return isLearned(id) && routeSeen(transport);
		}
		if (isLearned(id))
		{
			return true;
		}
		if (MeasuredShortcuts.animationFor(id) != -1)
		{
			// Somebody stood in front of this exact object and watched it.
			return true;
		}
		return shippedConfidence(transport);
	}

	/**
	 * Whether a golem may traverse this at all, on the shipped data alone.
	 *
	 * <p>Locked means routing around the obstacle as though it were not there, reserved for cases
	 * where using it without the animation would look broken rather than plain: jumps over two
	 * tiles, only the short hop having been measured, and balances, tightropes, squeezes and
	 * stiles, which have plausible names and no measurements. Ladders going down are deliberately
	 * not locked despite the disputed animation, since blocking one direction of a two-way
	 * transport strands a golem upstairs; it traverses silently instead, see {@link #clipsFor}.
	 */
	private boolean shippedConfidence(GolemTransport transport)
	{
		switch (transport.getArchetype())
		{
			case GolemTransport.ARCHETYPE_JUMP:
			{
				int span = transport.travelDistance();
				return span >= 0 && span <= 2;
			}

			case GolemTransport.ARCHETYPE_BALANCE:
			case GolemTransport.ARCHETYPE_TIGHTROPE:
			case GolemTransport.ARCHETYPE_SQUEEZE:
			case GolemTransport.ARCHETYPE_STILE:
				return false;

			case GolemTransport.ARCHETYPE_DOOR:
				// A golem cannot open or shut a door: that changes a real object every other player
				// sees, and where a door stands decides where anyone can walk. It goes through a shut
				// one instead, as at Wyrmscraig's cathedral doors: pushed through, then out the far
				// side. An open one is only ground, and needs no row.
				return true;

			default:
				// Gangplanks, ditches, climbs, ladders and the great mass of unclassified rows:
				// measured, corroborated, or animating nothing.
				return true;
		}
	}

	/**
	 * True if the shipped archetype's animation is trustworthy enough to play. Separate from
	 * {@link #shippedConfidence}: not knowing what an obstacle looks like means playing nothing
	 * rather than inventing an animation.
	 */
	private boolean shippedAnimationKnown(GolemTransport transport)
	{
		switch (transport.getArchetype())
		{
			case GolemTransport.ARCHETYPE_NONE:
			case GolemTransport.ARCHETYPE_DOOR:
			case GolemTransport.ARCHETYPE_GANGPLANK:
				// Nothing is played on the golem, so nothing can be played wrongly.
				return true;

			case GolemTransport.ARCHETYPE_DITCH:
			case GolemTransport.ARCHETYPE_CLIMB_OVER:
			case GolemTransport.ARCHETYPE_CLIMB:
				return true;

			case GolemTransport.ARCHETYPE_LADDER:
				// Up is 828 and agreed everywhere. Down is 833 here, never measured, and three
				// server reimplementations say 827, so it plays silently until somebody is seen.
				return !transport.goesDown();

			case GolemTransport.ARCHETYPE_STAIRS:
				// Nothing is played on stairs, so nothing can be played wrongly.
				return true;

			case GolemTransport.ARCHETYPE_JUMP:
			{
				int span = transport.travelDistance();
				return span >= 0 && span <= 2;
			}

			default:
				return false;
		}
	}

	private boolean isConfirmedAt(int objectId, int x, int y, int plane,
		int sizeX, int sizeY)
	{
		List<int[]> places = confirmed.get(objectId);
		if (places == null)
		{
			return false;
		}
		for (int[] at : places)
		{
			if (at[2] != plane)
			{
				continue;
			}
			// Distance to the nearest tile the object occupies, not to its corner.
			int dx = Math.max(Math.max(x - at[0], at[0] - (x + sizeX - 1)), 0);
			int dy = Math.max(Math.max(y - at[1], at[1] - (y + sizeY - 1)), 0);
			if (dx <= CONFIRM_TOLERANCE && dy <= CONFIRM_TOLERANCE)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Records where an obstacle led, when that is worth anything. Instances are refused: rebuilt
	 * with fresh coordinates each time, so a destination inside one describes a vanished room.
	 */
	private void noteRoute(ObstacleSighting sighting)
	{
		if (sighting.instance || !sighting.moved())
		{
			return;
		}

		String key = routeKey(sighting.objectId, sighting.fromX, sighting.fromY,
			sighting.fromPlane);
		List<int[]> here = routes.computeIfAbsent(key, k -> new ArrayList<>());

		int flags = sighting.toInstance && !sighting.fromInstance ? GolemTransport.INTO_INSTANCE
			: sighting.fromInstance && !sighting.toInstance ? GolemTransport.OUT_OF_INSTANCE : 0;

		for (int[] seen : here)
		{
			// Near enough is the same route: a rock climb landed on 2555 one time and 2556 the next,
			// and demanding the same tile reset the count after every use.
			if (seen[2] == sighting.toPlane
				&& Math.abs(seen[0] - sighting.toX) <= DESTINATION_TOLERANCE
				&& Math.abs(seen[1] - sighting.toY) <= DESTINATION_TOLERANCE)
			{
				// The same route, and the newest sighting's end is kept: keeping the first left the
				// way out of the stile's pen saved ending on the stile itself, so golems went in and
				// never came out.
				seen[0] = sighting.toX;
				seen[1] = sighting.toY;
				seen[3]++;
				seen[4] = flags;
				return;
			}
		}

		// Genuinely somewhere else, so a second route from this tile rather than a contradiction
		// of the first: the middle of a line of stepping stones really does lead two ways.
		here.add(new int[]{sighting.toX, sighting.toY, sighting.toPlane, 1, flags});
	}

	/**
	 * True if a player has been seen using this transport's object from near its origin to near its
	 * destination: the start within {@link #CONFIRM_TOLERANCE}, the end within
	 * {@link #DESTINATION_TOLERANCE}, as learned routes are matched.
	 */
	private boolean routeSeen(GolemTransport transport)
	{
		for (int dx = -CONFIRM_TOLERANCE; dx <= CONFIRM_TOLERANCE; dx++)
		{
			for (int dy = -CONFIRM_TOLERANCE; dy <= CONFIRM_TOLERANCE; dy++)
			{
				List<int[]> seen = routes.get(routeKey(transport.getObjectId(), transport.getFromX() + dx,
					transport.getFromY() + dy, transport.getFromPlane()));
				if (seen == null)
				{
					continue;
				}
				for (int[] to : seen)
				{
					if (to[2] == transport.getToPlane()
						&& Math.abs(to[0] - transport.getToX()) <= DESTINATION_TOLERANCE
						&& Math.abs(to[1] - transport.getToY()) <= DESTINATION_TOLERANCE)
					{
						return true;
					}
				}
			}
		}
		return false;
	}

	/** Sightings of one route past which another teaches nothing, and it is no longer recorded. */
	static final int MOST_SIGHTINGS = 15;

	/**
	 * True if this route has been seen more than {@link #MOST_SIGHTINGS} times already. Past that a
	 * sighting only rewrote what was known, and on an agility course that was everything golems had
	 * learned, saved again at every obstacle.
	 */
	boolean wellKnown(ObstacleSighting sighting)
	{
		return sightingsFor(sighting.objectId, sighting.fromX, sighting.fromY, sighting.fromPlane,
			new int[]{sighting.toX, sighting.toY, sighting.toPlane}) > MOST_SIGHTINGS;
	}

	/** How far apart two origins of the same move can be and still be one obstacle. */
	private static final int NEIGHBOUR_ORIGIN = 2;

	/**
	 * Sightings behind a route, counting its neighbours. A church pew is climbed from whichever end
	 * is nearer, so its routes, the same hop a tile apart, were each seen once and never reached
	 * two.
	 *
	 * @param to {toX, toY, toPlane, count, flags}
	 */
	private int sightingsFor(int objectId, int fromX, int fromY, int fromPlane, int[] to)
	{
		int total = 0;
		for (Map.Entry<String, List<int[]>> e : routes.entrySet())
		{
			String[] key = e.getKey().split(",");
			int otherX = Integer.parseInt(key[1]);
			int otherY = Integer.parseInt(key[2]);
			if (Integer.parseInt(key[0]) != objectId || Integer.parseInt(key[3]) != fromPlane
				|| Math.abs(otherX - fromX) > NEIGHBOUR_ORIGIN || Math.abs(otherY - fromY) > NEIGHBOUR_ORIGIN)
			{
				continue;
			}
			for (int[] other : e.getValue())
			{
				if (other[2] == to[2] && other[0] - otherX == to[0] - fromX && other[1] - otherY == to[1] - fromY)
				{
					total += other[3];
				}
			}
		}
		return total;
	}

	/**
	 * A route's flags, taken with its neighbours' as its sightings are: the Mad Angel's pew was
	 * learned from two tiles a row apart, and the route that did not know it led into the instance
	 * was unlocked without the flag.
	 */
	private int flagsFor(int objectId, int fromX, int fromY, int fromPlane, int[] to)
	{
		int flags = to[4];
		for (Map.Entry<String, List<int[]>> e : routes.entrySet())
		{
			String[] key = e.getKey().split(",");
			int otherX = Integer.parseInt(key[1]);
			int otherY = Integer.parseInt(key[2]);
			if (Integer.parseInt(key[0]) != objectId || Integer.parseInt(key[3]) != fromPlane
				|| Math.abs(otherX - fromX) > NEIGHBOUR_ORIGIN || Math.abs(otherY - fromY) > NEIGHBOUR_ORIGIN)
			{
				continue;
			}
			for (int[] other : e.getValue())
			{
				if (other[2] == to[2] && other[0] - otherX == to[0] - fromX && other[1] - otherY == to[1] - fromY)
				{
					flags |= other[4];
				}
			}
		}
		return flags;
	}

	private static String routeKey(int objectId, int x, int y, int plane)
	{
		return objectId + "," + x + "," + y + "," + plane;
	}

	/**
	 * Every route seen often enough to act on, as {objectId, fromX, fromY, fromPlane, toX, toY,
	 * toPlane, ticks}. The ticks matter as much as the coordinates: a duration of one compressed
	 * a rockslide's four ticks into one tick of gliding.
	 */
	List<int[]> learnedRoutes()
	{
		// Every tile a learned route along its obstacle's line starts or ends on; see jumpsOver.
		// Routes off the line are no evidence, an old diagonal stile route ending beside the right
		// one.
		Set<Long> ends = new HashSet<>();
		// Each key read as numbers once, not once per use.
		List<int[]> keys = new ArrayList<>(routes.size());
		for (String key : routes.keySet())
		{
			String[] parts = key.split(",");
			keys.add(new int[]{Integer.parseInt(parts[0]), Integer.parseInt(parts[1]), Integer.parseInt(parts[2]),
				Integer.parseInt(parts[3])});
		}
		int entry = 0;
		for (Map.Entry<String, List<int[]>> e : routes.entrySet())
		{
			int[] from = keys.get(entry++);
			int objectId = from[0];
			int fromX = from[1];
			int fromY = from[2];
			int fromPlane = from[3];
			for (int[] to : e.getValue())
			{
				if (followsObjectLine(objectId, fromX, fromY, fromPlane, to))
				{
					ends.add(RoamContext.tileKey(fromX, fromY, fromPlane));
					ends.add(RoamContext.tileKey(to[0], to[1], to[2]));
				}
			}
		}

		List<int[]> out = new ArrayList<>();
		entry = 0;
		for (Map.Entry<String, List<int[]>> e : routes.entrySet())
		{
			int[] from = keys.get(entry++);
			for (int[] to : e.getValue())
			{
				if (jumpsOver(from[1], from[2], from[3], to, ends))
				{
					continue;
				}
				if (to[3] < SIGHTINGS_TO_UNLOCK && sightingsFor(from[0], from[1], from[2], from[3], to) < SIGHTINGS_TO_UNLOCK)
				{
					continue;
				}
				// A route saved before its obstacle's line was known is held to it now, so the
				// diagonal stile routes already in a profile stop being used once the stile is
				// crossed, without anybody deleting them.
				if (!followsObjectLine(from[0], from[1], from[2], from[3], to))
				{
					continue;
				}
				Learned known = learned.get(from[0]);
				int[] route = {
					from[0], from[1], from[2], from[3],
					to[0], to[1], to[2],
					known == null ? 1 : Math.max(1, known.ticks),
					flagsFor(from[0], from[1], from[2], from[3], to),
				};
				if (routeFilter == null || routeFilter.test(route))
				{
					out.add(route);
				}
			}
		}
		return out;
	}

	/**
	 * True if a route leaps over a tile some other learned route starts or ends on - a stepping
	 * stone. A hop recorded wrongly came out two tiles long, over the stone the true hops use;
	 * held out rather than deleted, the next correct crossing overwriting it in place.
	 */
	private static boolean jumpsOver(int fromX, int fromY, int plane, int[] to, Set<Long> ends)
	{
		int dx = to[0] - fromX;
		int dy = to[1] - fromY;
		int span = span(dx, dy);
		if (to[2] != plane || span < 2 || dx != 0 && dy != 0 && Math.abs(dx) != Math.abs(dy))
		{
			return false;
		}
		for (int step = 1; step < span; step++)
		{
			if (ends.contains(RoamContext.tileKey(fromX + Integer.signum(dx) * step, fromY + Integer.signum(dy) * step, plane)))
			{
				return true;
			}
		}
		return false;
	}

	private void noteLine(ObstacleSighting sighting)
	{
		if (sighting.fromPlane != sighting.toPlane || !RouteGeometry.local(sighting.lineX, sighting.lineY))
		{
			return;
		}
		int[] direction = RouteGeometry.canonical(sighting.lineX, sighting.lineY);
		lines.computeIfAbsent(sighting.objectId, k -> new LinkedHashMap<>())
			.merge(direction[0] + "," + direction[1], 1, Integer::sum);
	}

	/** The line this obstacle most often moves players along, or null if none is known. */
	int[] lineOf(int objectId)
	{
		Map<String, Integer> seen = lines.get(objectId);
		if (seen == null || seen.isEmpty())
		{
			return null;
		}
		String best = null;
		for (Map.Entry<String, Integer> e : seen.entrySet())
		{
			if (best == null || e.getValue() > seen.get(best))
			{
				best = e.getKey();
			}
		}
		String[] parts = best.split(",");
		return new int[]{Integer.parseInt(parts[0]), Integer.parseInt(parts[1])};
	}

	/** Whether this sighting's route lies along its own movement and its obstacle's line. */
	private boolean followsLine(ObstacleSighting sighting)
	{
		if (sighting.fromPlane != sighting.toPlane)
		{
			return true;
		}
		int routeX = sighting.toX - sighting.fromX;
		int routeY = sighting.toY - sighting.fromY;
		int[] line = lineOf(sighting.objectId);
		return RouteGeometry.follows(routeX, routeY, sighting.lineX, sighting.lineY)
			&& (line == null || RouteGeometry.follows(routeX, routeY, line[0], line[1]));
	}

	/** Whether a stored route, {toX, toY, toPlane, count}, lies along its obstacle's line. */
	private boolean followsObjectLine(int objectId, int fromX, int fromY, int fromPlane, int[] to)
	{
		int[] line = lineOf(objectId);
		return line == null || to[2] != fromPlane
			|| RouteGeometry.follows(to[0] - fromX, to[1] - fromY, line[0], line[1]);
	}

	/** {@code objectId=x,y,count|x,y,count;...} */
	String serialiseLines()
	{
		StringBuilder sb = new StringBuilder();
		for (Map.Entry<Integer, Map<String, Integer>> e : lines.entrySet())
		{
			if (sb.length() > 0)
			{
				sb.append(';');
			}
			sb.append(e.getKey()).append('=');
			boolean first = true;
			for (Map.Entry<String, Integer> direction : e.getValue().entrySet())
			{
				sb.append(first ? "" : "|").append(direction.getKey()).append(',')
					.append(direction.getValue());
				first = false;
			}
		}
		return sb.toString();
	}

	void deserialiseLines(String saved)
	{
		lines.clear();
		if (saved == null || saved.isEmpty())
		{
			return;
		}
		for (String entry : saved.split(";"))
		{
			try
			{
				int split = entry.indexOf('=');
				Map<String, Integer> seen = new LinkedHashMap<>();
				for (String direction : entry.substring(split + 1).split("\\|"))
				{
					String[] parts = direction.split(",");
					seen.put(parts[0] + "," + parts[1], Integer.parseInt(parts[2]));
				}
				lines.put(Integer.parseInt(entry.substring(0, split)), seen);
			}
			catch (RuntimeException e)
			{
				log.debug("Skipping unreadable line: {}", entry);
			}
		}
	}

	String serialiseCurves()
	{
		// One entry per recording, oldest first, so an object with several repeats its id. Files
		// written when only one was kept read back unchanged.
		StringBuilder sb = new StringBuilder();
		for (Map.Entry<Integer, List<MotionCurve>> e : curves.entrySet())
		{
			for (MotionCurve curve : e.getValue())
			{
				if (sb.length() > 0)
				{
					sb.append(';');
				}
				sb.append(e.getKey()).append('=').append(curve.serialise());
			}
		}
		return sb.toString();
	}

	void deserialiseCurves(String saved)
	{
		curves.clear();
		chosenCurves.clear();
		if (saved == null || saved.isEmpty())
		{
			return;
		}
		for (String entry : saved.split(";"))
		{
			int split = entry.indexOf('=');
			if (split <= 0)
			{
				continue;
			}
			try
			{
				MotionCurve curve = MotionCurve.parse(entry.substring(split + 1));
				if (curve != null)
				{
					addCurve(Integer.parseInt(entry.substring(0, split)), curve);
				}
			}
			catch (RuntimeException e)
			{
				log.debug("Skipping unreadable curve: {}", entry.substring(0, split));
			}
		}
		log.debug("Restored recorded motions for {} obstacles", curves.size());
	}

	private void addCurve(int objectId, MotionCurve curve)
	{
		List<MotionCurve> kept = curves.computeIfAbsent(objectId, k -> new ArrayList<>());
		// A recording that knows which way the player faced supersedes every one that does not,
		// or the older ones outvote it and the golem keeps facing forwards down the rockslide.
		if (curve.hasFacing())
		{
			kept.removeIf(old -> !old.hasFacing());
		}
		// Likewise keyframes: an older recording without them plays the clip at its authored
		// speed and hops before the jump.
		if (curve.hasKeyframes())
		{
			kept.removeIf(old -> !old.hasKeyframes());
		}
		kept.add(curve);
		while (kept.size() > CURVES_KEPT)
		{
			kept.remove(0);
		}
		chosenCurves.put(objectId, consensus(kept));
	}

	/**
	 * The recording the others most agree with: a medoid, not an average, since averaging two
	 * recordings of a door produces a glide neither contains. Compared on length, reach, lateral
	 * drift and number of movements; with two, the more ordinary wins.
	 */
	static MotionCurve consensus(List<MotionCurve> kept)
	{
		MotionCurve best = null;
		double bestScore = Double.MAX_VALUE;
		for (int i = kept.size() - 1; i >= 0; i--)
		{
			MotionCurve candidate = kept.get(i);
			double score = kept.size() < 3 ? oddness(candidate) : 0;
			for (MotionCurve other : kept)
			{
				if (other != candidate)
				{
					score += difference(candidate, other);
				}
			}
			if (score < bestScore - 1e-6)
			{
				best = candidate;
				bestScore = score;
			}
		}
		return best;
	}

	private static double difference(MotionCurve a, MotionCurve b)
	{
		return Math.abs(a.cycles() - b.cycles()) / (double) Math.max(1, Math.max(a.cycles(), b.cycles()))
			+ Math.abs(a.reach() - b.reach()) / (double) Golem.TILE
			+ Math.abs(a.maxLateral() - b.maxLateral()) / (double) Golem.TILE
			+ Math.abs(a.bursts() - b.bursts());
	}

	private static double oddness(MotionCurve curve)
	{
		return curve.maxLateral() / (double) Golem.TILE + Math.max(0, curve.bursts() - 1);
	}

	/** The middle value of one column of {@link #timings}. */
	private static int median(List<int[]> rows, int column)
	{
		int[] values = new int[rows.size()];
		for (int i = 0; i < values.length; i++)
		{
			values[i] = rows.get(i)[column];
		}
		Arrays.sort(values);
		return values[values.length / 2];
	}

	String serialiseRoutes()
	{
		StringBuilder sb = new StringBuilder();
		for (Map.Entry<String, List<int[]>> e : routes.entrySet())
		{
			for (int[] to : e.getValue())
			{
				if (sb.length() > 0)
				{
					sb.append(';');
				}
				sb.append(e.getKey()).append('>').append(to[0]).append(',').append(to[1])
					.append(',').append(to[2]).append(',').append(to[3]);
				// Only where there is one, so a profile without instances saves as it always did.
				if (to[4] != 0)
				{
					sb.append(',').append(to[4]);
				}
			}
		}
		return sb.toString();
	}

	void deserialiseRoutes(String saved)
	{
		routes.clear();
		if (saved == null || saved.isEmpty())
		{
			return;
		}
		for (String entry : saved.split(";"))
		{
			try
			{
				String[] halves = entry.split(">");
				String[] to = halves[1].split(",");
				// The key is read back as numbers whenever routes are listed, outside any try, so
				// one bad key saved here would stop the plugin starting.
				String[] from = halves[0].split(",");
				if (from.length != 4)
				{
					throw new IllegalArgumentException("route key " + halves[0]);
				}
				for (String part : from)
				{
					Integer.parseInt(part);
				}
				routes.computeIfAbsent(halves[0], k -> new ArrayList<>())
					.add(new int[]{Integer.parseInt(to[0]), Integer.parseInt(to[1]),
						Integer.parseInt(to[2]), Integer.parseInt(to[3]),
						to.length > 4 ? Integer.parseInt(to[4]) : 0});
			}
			catch (RuntimeException e)
			{
				log.debug("Skipping unreadable route: {}", entry);
			}
		}
	}

	private void noteConfirmed(ObstacleSighting sighting)
	{
		List<int[]> places = confirmed.computeIfAbsent(sighting.objectId, k -> new ArrayList<>());
		if (isConfirmedAt(sighting.objectId, sighting.fromX, sighting.fromY,
			sighting.fromPlane, 1, 1))
		{
			return;
		}
		places.add(new int[]{sighting.fromX, sighting.fromY, sighting.fromPlane});
	}

	// ------------------------------------------------------------- what to play

	/**
	 * True if the player has been watched using this obstacle, whatever the outcome. Tells "seen,
	 * and it plays nothing" from "never seen", which an empty clip set cannot do on its own.
	 */
	boolean isLearned(int objectId)
	{
		Learned known = learned.get(objectId);
		return known != null && known.unlocked();
	}

	/**
	 * The clips a golem should play for this transport, best source first: what the player was
	 * seen doing beats what was shipped, which beats the archetype's guess.
	 */
	int[] clipsFor(GolemTransport transport)
	{
		// A door is pushed through whatever the player was seen doing, which is nothing: a player
		// opens it, a golem cannot, so the golem's own way through is the one played.
		if (transport.getArchetype() == GolemTransport.ARCHETYPE_DOOR)
		{
			return transport.animations();
		}
		// Only once it has cleared the bar everything else clears: a single sighting can be a
		// player attacked between clicking a ladder and reaching it.
		Learned known = learned.get(transport.getObjectId());
		if (known != null && known.unlocked())
		{
			// Including when it is empty: that is a measured "plays nothing".
			return known.clips;
		}
		if (MeasuredShortcuts.animationFor(transport.getObjectId()) != -1
			|| shippedAnimationKnown(transport))
		{
			return transport.animations();
		}

		// Not known, so the golem goes through in its ordinary pose rather than performing
		// something invented, as it already does for a door: plain, not wrong.
		return NOTHING;
	}

	private static final int[] NOTHING = new int[0];

	/** The recorded motion for this obstacle, or null if nobody has been watched doing it. */
	MotionCurve curveFor(GolemTransport transport)
	{
		// A door is the golem's own push, never the player's recording. See isUnlocked.
		if (transport.getArchetype() == GolemTransport.ARCHETYPE_DOOR)
		{
			return null;
		}
		return chosenCurves.get(transport.getObjectId());
	}

	/** Cycles a golem should stand still before moving, or 0 if unknown. */
	int moveDelayFor(GolemTransport transport)
	{
		if (transport.getArchetype() == GolemTransport.ARCHETYPE_DOOR)
		{
			return 0;
		}
		Learned known = learned.get(transport.getObjectId());
		return known != null && known.unlocked() ? known.moveDelay : 0;
	}

	/** Cycles the movement itself should take, or 0 if unknown. */
	int moveSpanFor(GolemTransport transport)
	{
		if (transport.getArchetype() == GolemTransport.ARCHETYPE_DOOR)
		{
			return 0;
		}
		Learned known = learned.get(transport.getObjectId());
		return known != null && known.unlocked() ? known.moveSpan : 0;
	}


	/**
	 * How long the traversal should take, or 0 to fall back to the clip and the table. A learned
	 * duration runs from the first clip to the player standing still, which for a single clip
	 * includes the pause afterwards and stretched a 38-cycle hop over 60, so a single clip is left
	 * at its own length and only a motion built in parts takes it.
	 */
	int ticksFor(GolemTransport transport)
	{
		if (transport.getArchetype() == GolemTransport.ARCHETYPE_DOOR)
		{
			return 0;
		}
		Learned known = learned.get(transport.getObjectId());
		if (known != null && known.unlocked() && known.ticks > 0 && known.clips.length != 1)
		{
			return known.ticks;
		}
		return MeasuredShortcuts.ticksFor(transport.getObjectId());
	}

	// ---------------------------------------------------------------- learning

	/**
	 * Records one sighting, and reports whether it has just unlocked the obstacle. A sighting that
	 * disagrees with what was learned resets the count rather than averaging: averaging two
	 * animation ids produces a third that is not an animation.
	 */
	boolean record(ObstacleSighting sighting)
	{
		// An empty clip set is not a failed observation but the observation that this obstacle
		// animates nobody, as a staircase and fifteen hundred other rows do.
		noteConfirmed(sighting);

		// Well learned is set in stone: what it plays, how long, the line it moves along and the
		// motion are no longer touched. A new place for the same kind of object is still a new
		// route to learn, along the line already known.
		Learned settled = learned.get(sighting.objectId);
		if (settled != null && settled.sightings >= SIGHTINGS_TO_SETTLE)
		{
			// Only a sighting like the others: one that played something else ended who knows where.
			if (followsLine(sighting) && sameClips(settled.clips, collapseRepeats(sighting.clips)))
			{
				noteRoute(sighting);
			}
			return false;
		}
		// Once unlocked, a sighting that plays something else is the odd one out - a player hit between
		// the click and the obstacle, moved by a boss - not a correction, and nothing of it is kept: not
		// its route, which may end anywhere, nor its line or motion. It used to reset the count, locking
		// every row that waited on this object again, and golems beyond them read stranded.
		if (settled != null && settled.unlocked() && !sameClips(settled.clips, collapseRepeats(sighting.clips)))
		{
			log.debug("Ignored a sighting of {} unlike what is learned: {}", sighting.objectId, sighting);
			return false;
		}
		noteLine(sighting);

		// Only a route lying along the obstacle is learned - along this traversal's movement and the
		// line the obstacle is known to move players - since a route off the line is performed off
		// it, as with the stile crossed on a slant. The animation is still learned.
		if (followsLine(sighting))
		{
			noteRoute(sighting);
			if (sighting.curve != null && !sighting.curve.isEmpty())
			{
				addCurve(sighting.objectId, sighting.curve);
			}
		}
		else
		{
			log.debug("Refused route off the line of {}: {}", sighting.objectId, sighting);
		}

		// One crossing is not one use: a sighting covers click to arrival, so three stepping stones
		// came back as 741,741,741 over six ticks while the table stores one row per hop. A run of
		// the same clip collapses to that motion and its share of the time.
		int[] clips = collapseRepeats(sighting.clips);
		int ticks = clips.length == sighting.clips.length || clips.length == 0
			? sighting.ticks
			: Math.max(1, Math.round(sighting.ticks / (float) sighting.clips.length));

		Learned existing = learned.get(sighting.objectId);
		if (existing == null || !sameClips(existing.clips, clips))
		{
			List<int[]> fresh = new ArrayList<>();
			fresh.add(new int[]{ticks, sighting.moveDelay, sighting.moveSpan});
			timings.put(sighting.objectId, fresh);
			learned.put(sighting.objectId,
				new Learned(clips, ticks, 1, sighting.moveDelay, sighting.moveSpan));
			return false;
		}

		boolean wasUnlocked = existing.unlocked();
		existing.sightings++;

		// The middle of the recent sightings, not the latest: one unusual traversal otherwise
		// rewrites what every golem does, a two-tick door being stored as three. What is saved
		// seeds the history across a restart.
		List<int[]> history = timings.computeIfAbsent(sighting.objectId, k ->
		{
			List<int[]> seeded = new ArrayList<>();
			seeded.add(new int[]{existing.ticks, existing.moveDelay, existing.moveSpan});
			return seeded;
		});
		history.add(new int[]{ticks, sighting.moveDelay, sighting.moveSpan});
		while (history.size() > CURVES_KEPT)
		{
			history.remove(0);
		}

		Learned updated = new Learned(existing.clips, median(history, 0), existing.sightings,
			median(history, 1), median(history, 2));
		learned.put(sighting.objectId, updated);

		return !wasUnlocked && updated.unlocked();
	}

	/**
	 * Reduces a run of one repeated clip to a single instance. Only when every clip is the same:
	 * a mixed set is a motion with parts, and losing them leaves a golem playing a mount and
	 * standing still.
	 */
	private static int[] collapseRepeats(int[] clips)
	{
		if (clips.length < 2)
		{
			return clips;
		}
		for (int clip : clips)
		{
			if (clip != clips[0])
			{
				return clips;
			}
		}
		return new int[]{clips[0]};
	}

	private static boolean sameClips(int[] a, int[] b)
	{
		if (a.length != b.length)
		{
			return false;
		}
		for (int i = 0; i < a.length; i++)
		{
			if (a[i] != b[i])
			{
				return false;
			}
		}
		return true;
	}

	/** How many obstacles the player has taught the plugin so far. */
	int unlockedCount()
	{
		int n = 0;
		for (Learned l : learned.values())
		{
			if (l.unlocked())
			{
				n++;
			}
		}
		return n;
	}

	// -------------------------------------------------------------- persistence

	/**
	 * Everything learned, as one line: {@code objectId:clip|clip|clip:ticks:sightings},
	 * semicolon separated. Compact because it lives in the RuneLite config, which is not a
	 * database.
	 */
	String serialise()
	{
		StringBuilder sb = new StringBuilder();
		for (Map.Entry<Integer, Learned> e : learned.entrySet())
		{
			Learned l = e.getValue();
			if (sb.length() > 0)
			{
				sb.append(';');
			}
			sb.append(e.getKey()).append(':');
			for (int i = 0; i < l.clips.length; i++)
			{
				sb.append(i == 0 ? "" : "|").append(l.clips[i]);
			}
			sb.append(':').append(l.ticks).append(':').append(l.sightings)
				.append(':').append(l.moveDelay).append(':').append(l.moveSpan);
		}
		return sb.toString();
	}

	/**
	 * The obstacles the player has personally used, as one line: {@code objectId,x,y,plane}
	 * groups separated by semicolons. Purely cosmetic - losing it costs some green outlines.
	 */
	String serialiseConfirmed()
	{
		StringBuilder sb = new StringBuilder();
		for (Map.Entry<Integer, List<int[]>> e : confirmed.entrySet())
		{
			for (int[] at : e.getValue())
			{
				if (sb.length() > 0)
				{
					sb.append(';');
				}
				sb.append(e.getKey()).append(',').append(at[0]).append(',')
					.append(at[1]).append(',').append(at[2]);
			}
		}
		return sb.toString();
	}

	void deserialiseConfirmed(String saved)
	{
		confirmed.clear();
		if (saved == null || saved.isEmpty())
		{
			return;
		}

		for (String entry : saved.split(";"))
		{
			try
			{
				String[] parts = entry.split(",");
				if (parts.length != 4)
				{
					continue;
				}
				confirmed.computeIfAbsent(Integer.parseInt(parts[0]), k -> new ArrayList<>())
					.add(new int[]{Integer.parseInt(parts[1]), Integer.parseInt(parts[2]),
						Integer.parseInt(parts[3])});
			}
			catch (RuntimeException e)
			{
				log.debug("Skipping unreadable confirmed obstacle: {}", entry);
			}
		}
	}

	/** Restores what was learned in previous sessions. Bad rows are skipped, not fatal. */
	void deserialise(String saved)
	{
		learned.clear();
		if (saved == null || saved.isEmpty())
		{
			return;
		}

		for (String entry : saved.split(";"))
		{
			try
			{
				String[] parts = entry.split(":");
				if (parts.length < 4)
				{
					continue;
				}

				// An empty clip field is a learned "plays nothing", not a broken row: parsing it as a
				// number throws, and every silent obstacle taught was forgotten at the next login.
				int[] clips;
				if (parts[1].isEmpty())
				{
					clips = new int[0];
				}
				else
				{
					String[] clipText = parts[1].split("\\|");
					clips = new int[clipText.length];
					for (int i = 0; i < clips.length; i++)
					{
						clips[i] = Integer.parseInt(clipText[i]);
					}
				}

				// Repaired on the way in as well as out: entries written before the repeat collapse
				// existed hold a whole crossing where they should hold one hop.
				int ticks = Integer.parseInt(parts[2]);
				int[] collapsed = collapseRepeats(clips);
				if (collapsed.length != clips.length && clips.length > 0)
				{
					ticks = Math.max(1, Math.round(ticks / (float) clips.length));
				}

				// Rows written before the movement window was recorded have four fields; they load
				// with zeroes and are filled the next time anybody uses the obstacle.
				int delay = parts.length > 4 ? Integer.parseInt(parts[4]) : 0;
				int span = parts.length > 5 ? Integer.parseInt(parts[5]) : 0;
				learned.put(Integer.parseInt(parts[0]),
					new Learned(collapsed, ticks, Integer.parseInt(parts[3]), delay, span));
			}
			catch (RuntimeException e)
			{
				// One malformed entry must not cost everything else the player has taught.
				log.debug("Skipping unreadable learned obstacle: {}", entry);
			}
		}

		log.debug("Restored {} learned obstacles, {} unlocked", learned.size(), unlockedCount());
	}
}

package com.golemsdontdie;

import java.util.*;
import java.util.function.*;
import javax.inject.*;
import lombok.*;
import lombok.extern.slf4j.*;
import net.runelite.api.*;
import net.runelite.api.coords.*;
import net.runelite.api.events.*;

/**
 * Watches the player use obstacles, and teaches the plugin what it sees.
 *
 * <p>Which animation a shortcut plays, and how long it takes, is <b>not in the cache</b>:
 * agility obstacles are resolved server-side, object definitions carry the object's own
 * animation but not the person's, and of three open server reimplementations none is current
 * enough to trust. So it watches: every obstacle used becomes an {@link ObstacleSighting} for
 * {@link ObstacleKnowledge}, and two consistent sightings unlock it for golems permanently.
 */
@Slf4j
@Singleton
class ObstacleObserver
{
	/**
	 * Ticks after a click within which an animation is taken to belong to it. Generous because an
	 * earlier three-tick window expired during the walk to the obstacle, easily ten seconds.
	 */
	private static final int CLAIM_WINDOW = 60;

	/** Ticks to keep watching before giving up on a traversal ever finishing. */
	private static final int PATIENCE = 40;

	/**
	 * Tiles the player can cover in one tick before it must have been a transport. Running covers
	 * two a tick and a staircase several thousand, so the test is nowhere near the margin.
	 */
	private static final int TELEPORT_TILES = 3;

	@Inject
	private Client client;

	/** What golems can walk on, which decides where a traversal is learned to start and end. */
	@Inject
	private IslandMemory memory;

	/** Called when a sighting completes, so the plugin can persist and announce it. */
	@Setter
	private Consumer<ObstacleSighting> onSighting;

	// ------------------------------------------------------------- what was clicked

	private int clickedObject = -1;
	private String clickedName = "";
	private String clickedMenu = "";
	private int clickedTick = -1;

	/** An object clicked while another was still animating; see onMenuOptionClicked. */
	private int queuedObject = -1;
	private String queuedName = "";
	private String queuedMenu = "";
	private int queuedTick = -1;

	/** A golem walks a tile a tick, and so do the steps added on and off an obstacle. */
	private static final int WALK_CYCLES = 30;

	// --------------------------------------------------------- the traversal so far

	private final List<Integer> clips = new ArrayList<>();
	private WorldPoint startedAt;
	private int startedTick = -1;
	private int lastAnimTick = -1;

	/** Where the player was last tick, for spotting a move no walk could explain. */
	private WorldPoint previousTile;

	/**
	 * The client cycle the traversal's first clip began on, or -1. The movement window is measured
	 * from here: a golem's own transition starts there, so it is the only origin the two share.
	 */
	private int clipStartCycle = -1;

	/** Cycles from the first clip to the player first moving, and to them stopping. */
	private int moveDelay = -1;
	private int moveEnd = -1;

	/**
	 * When the last animation of the traversal ended, and where the player's tile was then. The
	 * traversal is over when the obstacle has finished with the player, not when the player next
	 * stands still: as one, that recorded the cathedral door plus the walk after it, two tiles off
	 * and three ticks instead of two.
	 */
	private int animEndCycle = -1;
	private WorldPoint animEndTile;

	/**
	 * Cycles of complete stillness on a tile centre that mark the end of one step: a crossing is
	 * one click, and basalt hops rest about fifteen cycles, where a climb's stalls last two.
	 */
	private static final int REST_CYCLES = 6;

	private static final int CYCLES_PER_TICK = 30;

	/**
	 * The traversal being recorded: {cycle, worldFineX, worldFineY} per client tick. World fine
	 * units, because a scene can shift underneath a recording and take local coordinates with it.
	 */
	private final List<int[]> samples = new ArrayList<>();

	/** {cycle, animationId} for each change during the traversal. */
	private final List<int[]> animTimeline = new ArrayList<>();

	/** Where the player was on the previous client tick, for spotting movement at all. */
	private LocalPoint previousFine;

	/**
	 * A move that looked like a silent traversal, held back one tick because the two events race:
	 * a ladder playing 828 can move first, so it was called animated sometimes and silent others,
	 * and every disagreement voided the count.
	 */
	private WorldPoint silentFrom;
	private WorldPoint silentTo;
	private int silentObject = -1;
	private String silentName = "";
	private String silentMenu = "";

	// ------------------------------------------------------------------ lifecycle

	void startUp()
	{
		resetSession();
	}

	void shutDown()
	{
		resetSession();
	}

	// --------------------------------------------------------------------- capture

	/** Remembers the object the player just clicked, so an animation can be attributed. */
	void onMenuOptionClicked(MenuOptionClicked event)
	{
		String option = event.getMenuOption();
		if (option == null || option.isEmpty())
		{
			return;
		}


		if (!isObjectAction(event.getMenuAction()))
		{
			// Only scene objects are obstacles: a definition looked up for a walk target returns
			// whatever object shares that number. A click on anything else drops the object being
			// walked to, as the game does - a door clicked and then a teleport cast was learned as a
			// door to the teleport's destination - but a traversal already started is left to finish.
			if (startedAt == null && clips.isEmpty() && posing == -1)
			{
				clickedObject = -1;
				clickedTick = -1;
				clearSilent();
			}
			return;
		}

		Player local = client.getLocalPlayer();
		WorldPoint at = local == null ? null : local.getWorldLocation();

		// A click while an obstacle is still animating is held, not acted on: players click ahead as
		// a matter of course, and ending the recording there cut it off mid-animation.
		if (startedAt != null && !clips.isEmpty() && local != null && local.getAnimation() != -1)
		{
			queuedObject = event.getId();
			queuedMenu = (option + " " + stripTags(event.getMenuTarget())).trim();
			queuedName = objectName(queuedObject);
			queuedTick = client.getTickCount();
			return;
		}

		// A traversal already under way is finished by the next click, not thrown away: chained
		// obstacles are one action per step, and discarding the one in flight merged both hops into
		// a four-tile route a golem cleared in a single jump.
		if (startedAt != null && !clips.isEmpty() && at != null && !at.equals(startedAt))
		{
			// The next stone of the same crossing ends the hop on the stone it landed on, and the
			// next starts there. Any other click is somewhere new, and the hop ends as usual.
			boolean sameObstacle = event.getId() == clickedObject
				|| objectName(event.getId()).equals(clickedName) && !clickedName.isEmpty();
			complete(at, client.getTickCount(), sameObstacle);
			if (sameObstacle)
			{
				chainTile = at;
			}
		}

		clickedObject = event.getId();
		clickedMenu = (option + " " + stripTags(event.getMenuTarget())).trim();
		clickedName = objectName(clickedObject);
		clickedTick = client.getTickCount();
		hurt = false;
		ordinaryPoses = local == null ? null : ordinaryPosesOf(local);

		clips.clear();
		startedAt = null;

	}

	/**
	 * Notes each clip the player begins, and the moment the traversal starts. Every clip is kept:
	 * OSRS builds a traversal in parts, and only the first would be a mount and then stillness.
	 */
	void onAnimationChanged(AnimationChanged event)
	{
		Player local = client.getLocalPlayer();
		if (local == null || event.getActor() != local)
		{
			return;
		}

		int playing = local.getAnimation();
		int tick = client.getTickCount();


		if (playing == -1 && startedAt != null)
		{
			animEndCycle = client.getGameCycle();
			animEndTile = local.getWorldLocation();
			animEndTileTemplate = templateOf(animEndTile);
			// Kept so a golem stops animating when the player did; without it the golem stepped
			// off a stile frozen in the last frame of the climb.
			animTimeline.add(new int[]{client.getGameCycle(), -1});
		}

		if (playing == -1 || clickedTick < 0 || tick - clickedTick > CLAIM_WINDOW)
		{
			// An emote, combat, a skill: not attributable to a click, so nothing to learn.
			return;
		}

		// An animation turned up after all, so the move was not silent.
		clearSilent();

		// The next step of a chained crossing, not more of the same one: one click crosses a whole
		// line of stones, and storing that as one traversal let golems cross without touching the
		// middle stone. The same clip again, while the player rests on a tile they did not start
		// from, is a new step; a multi-part obstacle pauses between *different* clips.
		WorldPoint splitAt = null;
		List<int[]> restRun = null;
		if (startedAt != null && !clips.isEmpty() && clips.get(clips.size() - 1) == playing)
		{
			restRun = restingRun();
			WorldPoint resting = restRun == null ? null : tileOf(restRun.get(restRun.size() - 1));
			if (resting != null && !resting.equals(startedAt))
			{
				int object = clickedObject;
				String name = clickedName;
				String menu = clickedMenu;
				int clicked = clickedTick;

				complete(resting, tick, true);
				chainTile = resting;

				clickedObject = object;
				clickedName = name;
				clickedMenu = menu;
				clickedTick = clicked;
				splitAt = resting;
			}
			else
			{
				restRun = null;
			}
		}

		beginClip(playing, splitAt, restRun, local, tick);
	}

	/**
	 * Notes a clip starting: the first of a traversal, which anchors it, or another part of the one
	 * under way. Played animations come here, and so does a pose that moves the player silently.
	 */
	private void beginClip(int playing, WorldPoint splitAt, List<int[]> restRun, Player local, int tick)
	{
		if (startedAt == null)
		{
			// Where the traversal began is where the player was a tick ago: movement and animation
			// arrive in either order, and a rock climb moves you first, so anchoring on the current
			// position recorded a traversal that never left its own tile.
			startedAt = splitAt != null ? splitAt
				: previousTile != null ? previousTile : local.getWorldLocation();
			startedAtTemplate = splitAt != null ? templateOf(splitAt)
				: previousTile != null ? previousTileTemplate : templateOf(local.getWorldLocation());
			startedTick = tick;
			clipStartCycle = client.getGameCycle();
			moveDelay = -1;
			moveEnd = -1;
			samples.clear();
			if (restRun != null)
			{
				// The rest before this step belongs to it: it is where the step starts from.
				samples.addAll(restRun);
			}
			animTimeline.clear();
			animEndCycle = -1;
			animEndTile = null;
		}


		clips.add(playing);
		animTimeline.add(new int[]{client.getGameCycle(), playing});
		lastAnimTick = tick;
	}

	/**
	 * Finishes a traversal once the player has stopped moving somewhere new. A looping clip hides
	 * its own length - a rock climb loops silently - so only the arrival gives it.
	 */
	void onGameTick()
	{
		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return;
		}

		int tick = client.getTickCount();
		WorldPoint at = local.getWorldLocation();

		WorldPoint was = previousTile;
		previousTile = at;
		WorldPoint wasTemplate = previousTileTemplate;
		previousTileTemplate = templateOf(at);

		// A pose the obstacle put the player in, playing nothing. See posedTraversal.
		if (posedTraversal(local, at, was, wasTemplate, tick))
		{
			return;
		}

		if (startedAt == null && clips.isEmpty())
		{
			// Nothing is animating, so watch for the traversal that plays no animation at all.
			// Staircases are the large case and were invisible here, capture having only ever begun
			// on an animation; "plays nothing" is itself a fact worth knowing.
			silentTraversal(was, at, tick, wasTemplate, previousTileTemplate);
			return;
		}

		if (startedAt == null || clips.isEmpty())
		{
			return;
		}

		// Finished means stopped, not merely between animations: a looping clip reports -1 between
		// repeats, and a rock climb was declared over on its first tile, recording 2550,2209 ->
		// 2550,2208. Or two ticks after the animation ended, moving or not, since a player who
		// clicks away the moment an obstacle lets go never stands still.
		boolean stillMoving = was == null || !was.equals(at);
		boolean released = animEndCycle >= 0
			&& client.getGameCycle() - animEndCycle >= 2 * CYCLES_PER_TICK;
		if (local.getAnimation() == -1 && at != null && (!stillMoving || released)
			&& !at.equals(startedAt))
		{
			complete(at, tick);
			return;
		}

		if (tick - lastAnimTick > PATIENCE)
		{
			// Whatever that was, it was not a traversal that finished.
			reset();
		}
	}

	private void complete(WorldPoint at, int tick)
	{
		complete(at, tick, false);
	}

	/**
	 * Turns the watched traversal into a sighting and hands it on.
	 *
	 * @param continues true if the same obstacle carries straight on, as the next hop of a line of
	 *                  stepping stones does, so the part ends on the stone it landed on.
	 */
	private void complete(WorldPoint at, int tick, boolean continues)
	{
		// A fall is not the way across: washed downstream off a stepping stone the player still
		// moves, and learned, that teaches golems to cross by swimming. So hurt means failed.
		if (hurt)
		{
			hurt = false;
			chainTile = null;
			reset();
			return;
		}

		// Started on the stone a previous hop of the same crossing landed on.
		boolean fromChain = chainTile != null && chainTile.equals(startedAt);
		chainTile = null;

		int[] played = new int[clips.size()];
		for (int i = 0; i < played.length; i++)
		{
			played[i] = clips.get(i);
		}

		// Where the obstacle put the player, not always where they came to rest; see animEndTile.
		// A tile equal to the start is a clip that ended before its own teleport - a ladder.
		WorldPoint to = at;
		if (animEndTile != null && !animEndTile.equals(startedAt) && !animEndTile.equals(at))
		{
			to = animEndTile;
		}

		// Where a golem gets on and off, which for some obstacles is not where the obstacle begins
		// and ends: the stile puts the player on its own blocked tile first. See wayIn, wayOut.
		WorldPoint landing = to;
		// The direction and line in lasting coordinates. Across an instance edge the raw tiles are
		// thousands apart - the pew to the Mad Angel's room recorded a line of 11486,5792.
		WorldPoint landingTemplate = landing.equals(animEndTile) ? animEndTileTemplate : templateOf(landing);
		WorldPoint lineFrom = startedAtTemplate != null ? startedAtTemplate : startedAt;
		WorldPoint lineTo = landingTemplate != null ? landingTemplate : landing;
		int dirX = Integer.signum(lineTo.getX() - lineFrom.getX());
		int dirY = Integer.signum(lineTo.getY() - lineFrom.getY());
		boolean level = landing.getPlane() == startedAt.getPlane();
		// Not in the middle of a crossing. Stepping back to walkable ground is right for a stile but
		// wrong for a stone mid-river, which was learned as a jump over the stone beside it.
		WorldPoint origin = level && !fromChain ? wayIn(startedAt, dirX, dirY) : startedAt;
		to = level && !continues ? wayOut(landing, dirX, dirY) : landing;

		// The recording is the obstacle and nothing else: from the player standing on the tile it
		// starts them from to the moment it puts them down. Everything either side is the player,
		// and was being replayed by golems. Where the route's ends lie a tile outside, the steps
		// between are added as ordinary walking.
		List<int[]> track = flattenTeleports(cutAtArrival(trimToStart(samples, startedAt), landing));
		if (level && !track.isEmpty())
		{
			track = withWalk(track, origin, startedAt, landing, to);
		}
		MotionCurve curve = MotionCurve.record(track, animTimeline,
			origin.getX() * Golem.TILE + Golem.TILE / 2,
			origin.getY() * Golem.TILE + Golem.TILE / 2,
			to.getX() * Golem.TILE + Golem.TILE / 2,
			to.getY() * Golem.TILE + Golem.TILE / 2);

		// Timings read off the recording, which is exactly one step long. Counted live they came back
		// as one cycle for nearly every obstacle, the position stalling every other cycle.
		int ticks = tick - startedTick;
		int delay = Math.max(0, moveDelay);
		int span = 0;
		if (curve != null)
		{
			ticks = Math.max(1, Math.round(curve.cycles() / (float) CYCLES_PER_TICK));
			if (curve.firstMoveCycle() >= 0)
			{
				delay = Math.max(0, curve.firstMoveCycle() - curve.firstAnimationCycle());
				span = Math.max(0, curve.lastMoveCycle() - curve.firstMoveCycle());
			}
		}

		// The route's ends in lasting coordinates: inside an instance that is its template, captured
		// when seen, since the instance may be gone by now. The same offset carries over.
		WorldPoint fromTemplate = shift(startedAtTemplate, origin, startedAt);
		WorldPoint toTemplate = shift(landingTemplate, to, landing);
		boolean placed = fromTemplate != null && toTemplate != null;
		WorldPoint from = placed ? fromTemplate : origin;
		WorldPoint end = placed ? toTemplate : to;

		ObstacleSighting sighting = new ObstacleSighting(
			clickedObject, clickedName, clickedMenu, played, ticks,
			from.getX(), from.getY(), from.getPlane(),
			end.getX(), end.getY(), end.getPlane(), !placed,
			delay, span, curve,
			level ? lineTo.getX() - lineFrom.getX() : 0,
			level ? lineTo.getY() - lineFrom.getY() : 0,
			// A tile inside an instance is not its own template; outside one it is.
			startedAtTemplate != null && !startedAtTemplate.equals(startedAt),
			landingTemplate != null && !landingTemplate.equals(landing));


		reset();

		// A traversal that did not move the player is not a traversal: the main guard against being
		// attacked between clicking a ladder and reaching it.
		if (!sighting.moved())
		{
			return;
		}

		if (onSighting != null)
		{
			onSighting.accept(sighting);
		}
	}

	/**
	 * Records a traversal that moved the player without animating them, judged by the move rather
	 * than the click: a plane change, or a jump no running could cover in one tick.
	 */
	private void silentTraversal(WorldPoint was, WorldPoint now, int tick, WorldPoint wasTemplate,
		WorldPoint nowTemplate)
	{
		// Last tick's candidate, now that an animation has had its chance to turn up.
		if (silentFrom != null)
		{
			WorldPoint from = silentFrom;
			WorldPoint to = silentTo;
			WorldPoint fromTemplate = silentFromTemplate;
			WorldPoint toTemplate = silentToTemplate;
			boolean placed = fromTemplate != null && toTemplate != null;
			int object = silentObject;
			String name = silentName;
			String menu = silentMenu;
			clearSilent();

			// Hurt since the click is a fall, a death or a boss's throw, not the way across: as in
			// complete, and learned it put a silent crossing in place of the obstacle's clip.
			if (hurt)
			{
				hurt = false;
				reset();
				return;
			}

			// A silent traversal has no clip to measure a window against but still has a shape:
			// without one a staircase appeared at the far end the tick the golem arrived. A silent
			// exit is reported a tick after the overworld loads, so its template is a tick older.
			MotionCurve curve = silentCurve(from, to);
			WorldPoint start = placed ? fromTemplate : from;
			WorldPoint end = placed ? toTemplate : to;
			ObstacleSighting sighting = new ObstacleSighting(object, name, menu,
				new int[0], 1, start.getX(), start.getY(), start.getPlane(),
				end.getX(), end.getY(), end.getPlane(), !placed, 0, 0,
				curve, 0, 0,
				fromTemplate != null && !fromTemplate.equals(from),
				toTemplate != null && !toTemplate.equals(to));

			reset();

			if (onSighting != null)
			{
				onSighting.accept(sighting);
			}
			return;
		}

		if (clickedObject < 0 || was == null || now == null
			|| clickedTick < 0 || tick - clickedTick > CLAIM_WINDOW)
		{
			return;
		}

		boolean jumped = was.getPlane() != now.getPlane()
			|| Math.abs(was.getX() - now.getX()) > TELEPORT_TILES
			|| Math.abs(was.getY() - now.getY()) > TELEPORT_TILES;
		if (!jumped)
		{
			return;
		}

		// Boarding or leaving a boat is not an obstacle: aboard, the player stands in the boat's own
		// world thousands of tiles off the map, and a gangplank was learned as a way there.
		boolean aboard = onBoat();
		if (aboard || boatChanged)
		{
			return;
		}

		// Held, not emitted. Next tick decides.
		silentFrom = was;
		silentTo = now;
		silentFromTemplate = wasTemplate;
		silentToTemplate = nowTemplate;
		silentObject = clickedObject;
		silentName = clickedName;
		silentMenu = clickedMenu;
	}

	/**
	 * Drops the walk up to the obstacle, keeping the traversal itself, which starts at the last
	 * moment the player stood on its origin tile. Recording begins at the click, well before.
	 */
	private List<int[]> trimToStart(List<int[]> all, WorldPoint from)
	{
		int start = startOfTraversal(all, from);
		if (start >= 0)
		{
			return all.subList(start, all.size());
		}
		// Never seen standing there: start at the animation rather than keep the approach,
		// which is the player's walk and not the obstacle.
		for (int i = 0; i < all.size(); i++)
		{
			if (all.get(i)[0] >= clipStartCycle)
			{
				return all.subList(i, all.size());
			}
		}
		return all;
	}

	/**
	 * The walk onto and off an obstacle, added where a route starts or ends a tile outside it:
	 * straight lines at walking pace playing no animation, so the golem's own walk shows.
	 */
	private static List<int[]> withWalk(List<int[]> track, WorldPoint origin, WorldPoint start,
		WorldPoint landing, WorldPoint dest)
	{
		List<int[]> out = new ArrayList<>();
		int[] first = track.get(0);
		if (!origin.equals(start))
		{
			for (int i = 0; i < WALK_CYCLES; i++)
			{
				out.add(walkSample(first[0] - WALK_CYCLES + i, origin, start, i / (float) WALK_CYCLES, first[3]));
			}
		}
		out.addAll(track);
		if (!dest.equals(landing))
		{
			int[] last = track.get(track.size() - 1);
			for (int i = 0; i < WALK_CYCLES; i++)
			{
				out.add(walkSample(last[0] + 1 + i, landing, dest, (i + 1) / (float) WALK_CYCLES, last[3]));
			}
		}
		return out;
	}

	private static int[] walkSample(int cycle, WorldPoint from, WorldPoint to, float t, int plane)
	{
		float fromX = from.getX() * Golem.TILE + Golem.TILE / 2f;
		float fromY = from.getY() * Golem.TILE + Golem.TILE / 2f;
		float toX = to.getX() * Golem.TILE + Golem.TILE / 2f;
		float toY = to.getY() * Golem.TILE + Golem.TILE / 2f;
		return new int[]{cycle, Math.round(fromX + (toX - fromX) * t), Math.round(fromY + (toY - fromY) * t),
			plane, -1, -1};
	}

	/** The index of the traversal's first sample, or -1 if the player never stood on its origin. */
	private static int startOfTraversal(List<int[]> all, WorldPoint from)
	{
		if (from == null || all.isEmpty())
		{
			return -1;
		}

		// Tile centres, because the samples are rendered and a player is drawn at a tile's middle.
		int originX = from.getX() * Golem.TILE + Golem.TILE / 2;
		int originY = from.getY() * Golem.TILE + Golem.TILE / 2;

		// The moment the player arrived on the origin tile, not the moment they left it: a door
		// stands still for thirty cycles and then teleports, all of it "at the origin", so taking the
		// last sample there began the recording at the teleport. Hence the walk back to the run.
		int last = -1;
		for (int i = 0; i < all.size(); i++)
		{
			int[] sample = all.get(i);
			if (Math.abs(sample[1] - originX) <= Golem.TILE / 4
				&& Math.abs(sample[2] - originY) <= Golem.TILE / 4)
			{
				last = i;
			}
		}

		if (last < 0)
		{
			return -1;
		}

		int start = last;
		while (start > 0)
		{
			int[] before = all.get(start - 1);
			if (Math.abs(before[1] - originX) > Golem.TILE / 4
				|| Math.abs(before[2] - originY) > Golem.TILE / 4)
			{
				break;
			}
			start--;
		}

		return start;
	}

	/**
	 * Drops whatever the player did after the obstacle finished: the first moment, at or after the
	 * last animation ended, that they are drawn on the destination. A door keeps its whole clip.
	 */
	private List<int[]> cutAtArrival(List<int[]> track, WorldPoint to)
	{
		// Without an end to the animation, the first arrival after it began will do.
		int after = animEndCycle >= 0 ? animEndCycle : clipStartCycle;
		if (after < 0)
		{
			return track;
		}
		int centreX = to.getX() * Golem.TILE + Golem.TILE / 2;
		int centreY = to.getY() * Golem.TILE + Golem.TILE / 2;
		for (int i = 0; i < track.size(); i++)
		{
			int[] sample = track.get(i);
			if (sample[0] >= after && sample[3] == to.getPlane()
				&& Math.abs(sample[1] - centreX) <= Golem.TILE / 4
				&& Math.abs(sample[2] - centreY) <= Golem.TILE / 4)
			{
				return track.subList(0, i + 1);
			}
		}
		return track;
	}

	/**
	 * Holds the recording still from the first teleport onward. A cave mouth puts the player six
	 * thousand tiles away while still animating, which a golem would glide across the world.
	 */
	private static List<int[]> flattenTeleports(List<int[]> track)
	{
		for (int i = 1; i < track.size(); i++)
		{
			int[] before = track.get(i - 1);
			int[] after = track.get(i);
			if (before[3] != after[3]
				|| Math.abs(after[1] - before[1]) > TELEPORT_TILES * Golem.TILE
				|| Math.abs(after[2] - before[2]) > TELEPORT_TILES * Golem.TILE)
			{
				List<int[]> held = new ArrayList<>(track.subList(0, i));
				for (int j = i; j < track.size(); j++)
				{
					int[] sample = track.get(j);
					held.add(new int[]{sample[0], before[1], before[2], before[3],
						sample.length > 4 ? sample[4] : -1, sample.length > 5 ? sample[5] : -1});
				}
				return held;
			}
		}
		return track;
	}

	/**
	 * The stillness on a silent obstacle before the player vanishes, as a recording. Only the part
	 * on the origin tile: the approach is not the obstacle, and the far side is elsewhere.
	 */
	private MotionCurve silentCurve(WorldPoint from, WorldPoint to)
	{
		int start = startOfTraversal(samples, from);
		if (start < 0)
		{
			return null;
		}
		int originX = from.getX() * Golem.TILE + Golem.TILE / 2;
		int originY = from.getY() * Golem.TILE + Golem.TILE / 2;
		int end = samples.size();
		for (int i = start; i < samples.size(); i++)
		{
			int[] sample = samples.get(i);
			if (sample[3] != from.getPlane()
				|| Math.abs(sample[1] - originX) > Golem.TILE / 4
				|| Math.abs(sample[2] - originY) > Golem.TILE / 4)
			{
				end = i;
				break;
			}
		}
		return MotionCurve.record(samples.subList(start, end), new ArrayList<>(),
			originX, originY,
			to.getX() * Golem.TILE + Golem.TILE / 2, to.getY() * Golem.TILE + Golem.TILE / 2);
	}

	/** The rest ending the recording, if long enough on a tile centre to end a step; else null. */
	private List<int[]> restingRun()
	{
		if (samples.isEmpty())
		{
			return null;
		}
		int[] last = samples.get(samples.size() - 1);
		int first = samples.size() - 1;
		while (first > 0)
		{
			int[] before = samples.get(first - 1);
			if (before[1] != last[1] || before[2] != last[2] || before[3] != last[3])
			{
				break;
			}
			first--;
		}
		if (last[0] - samples.get(first)[0] < REST_CYCLES)
		{
			return null;
		}
		int offX = Math.floorMod(last[1], Golem.TILE) - Golem.TILE / 2;
		int offY = Math.floorMod(last[2], Golem.TILE) - Golem.TILE / 2;
		if (Math.abs(offX) > Golem.TILE / 4 || Math.abs(offY) > Golem.TILE / 4)
		{
			return null;
		}
		return new ArrayList<>(samples.subList(first, samples.size()));
	}

	/**
	 * Where a traversal really starts, for a golem.
	 *
	 * <p>Some obstacles start the player on a tile no golem can walk onto: clicking the stile walks
	 * you onto its blocked tile, so a route learned from there started where no golem could stand
	 * and the stile went unused. The way in is the walkable tile behind the obstacle, along its
	 * line - from the obstacle alone, never from where the player was, since players come at a
	 * stile from the side. A stepping stone is blocked too, but behind it is water.
	 */
	private WorldPoint wayIn(WorldPoint origin, int dirX, int dirY)
	{
		if (origin == null || walkable(origin) || (dirX == 0 && dirY == 0))
		{
			return origin;
		}
		WorldPoint behind = new WorldPoint(origin.getX() - dirX, origin.getY() - dirY, origin.getPlane());
		return walkable(behind) ? behind : origin;
	}

	/** Where a traversal really ends: the landing, else the walkable tile past it, else itself. */
	private WorldPoint wayOut(WorldPoint landing, int dirX, int dirY)
	{
		if (walkable(landing) || (dirX == 0 && dirY == 0))
		{
			return landing;
		}
		WorldPoint beyond = new WorldPoint(landing.getX() + dirX, landing.getY() + dirY, landing.getPlane());
		return walkable(beyond) ? beyond : landing;
	}

	private boolean walkable(WorldPoint tile)
	{
		return tile != null && memory.isKnownWalkable(tile.getX(), tile.getY(), tile.getPlane());
	}

	private static WorldPoint tileOf(int[] sample)
	{
		return new WorldPoint(Math.floorDiv(sample[1], Golem.TILE),
			Math.floorDiv(sample[2], Golem.TILE), sample[3]);
	}

	/** The stone a hop of a crossing just landed on, where the crossing's next hop starts. */
	private WorldPoint chainTile;

	/** True if the player took damage since clicking the obstacle: they failed it. */
	private boolean hurt;

	/** The player's own standing, walking, running and turning poses, as they were at the click. */
	private Set<Integer> ordinaryPoses;

	/** A pose being recorded as the traversal's clip, or -1. */
	private int posing = -1;

	/** True if the player was aboard a boat last tick. */
	private boolean wasOnBoat;

	/**
	 * True if the player got on or off a boat this tick, kept apart from {@link #wasOnBoat} because
	 * {@link #posedTraversal} has moved that on before {@link #silentTraversal} looks: read there,
	 * stepping off a boat could be learned as a route.
	 */
	private boolean boatChanged;

	/**
	 * Forgets the player's last position and click for a new session - the plugin starting, a
	 * logout, a world hop - since otherwise a jump that never happened could be learned.
	 */
	void resetSession()
	{
		queuedObject = -1;
		reset();
		previousTile = null;
		previousTileTemplate = null;
		wasOnBoat = false;
		boatChanged = false;
		hurt = false;
		ordinaryPoses = null;
		clickedName = "";
		clickedMenu = "";
	}

	/** Marks the obstacle under way as failed. Called when the player takes a hit. */
	void onPlayerHurt()
	{
		if (clickedTick >= 0 || startedAt != null)
		{
			hurt = true;
		}
	}

	private boolean onBoat()
	{
		Player local = client.getLocalPlayer();
		return local != null && local.getWorldView() != null && !local.getWorldView().isTopLevel();
	}

	private static Set<Integer> ordinaryPosesOf(Player local)
	{
		Set<Integer> poses = new HashSet<>();
		poses.add(-1);
		poses.add(local.getIdlePoseAnimation());
		poses.add(local.getIdleRotateLeft());
		poses.add(local.getIdleRotateRight());
		poses.add(local.getWalkAnimation());
		poses.add(local.getWalkRotateLeft());
		poses.add(local.getWalkRotateRight());
		poses.add(local.getWalkRotate180());
		poses.add(local.getRunAnimation());
		return poses;
	}

	/**
	 * Watches for an obstacle that moves the player in a pose of its own, playing nothing.
	 *
	 * <p>Climbing down a vine is one: the game swaps the player's walk for a climbing pose and
	 * moves them a tile a tick with no animation, so this class, recording only on an animation or
	 * a jump, saw nothing and the vine could only be learned going up. A pose none of the player's
	 * own, soon after a click, is that obstacle's clip.
	 *
	 * @return true if this tick belonged to such a traversal
	 */
	private boolean posedTraversal(Player local, WorldPoint at, WorldPoint was, WorldPoint wasTemplate, int tick)
	{
		boolean aboard = onBoat();
		boatChanged = aboard != wasOnBoat;
		wasOnBoat = aboard;
		if (boatChanged || aboard)
		{
			return false;
		}

		int pose = local.getPoseAnimation();
		boolean special = ordinaryPoses != null && !ordinaryPoses.contains(pose) && local.getAnimation() == -1;

		if (posing != -1)
		{
			if (special && pose == posing)
			{
				return false;
			}
			// Back to the player's own poses: the obstacle has let go.
			posing = -1;
			if (startedAt != null)
			{
				animEndCycle = client.getGameCycle();
				animEndTile = at;
				animEndTileTemplate = templateOf(at);
				animTimeline.add(new int[]{client.getGameCycle(), -1});
			}
			return false;
		}

		if (!special || startedAt != null || !clips.isEmpty()
			|| clickedObject < 0 || clickedTick < 0 || tick - clickedTick > CLAIM_WINDOW)
		{
			return false;
		}

		clearSilent();
		posing = pose;
		beginClip(pose, null, null, local, tick);
		// From where the player was when the pose took them, a tick ago: by now they have
		// already been moved a tile.
		if (was != null)
		{
			startedAt = was;
			startedAtTemplate = wasTemplate;
		}
		return true;
	}

	private void clearSilent()
	{
		silentFrom = null;
		silentTo = null;
		silentFromTemplate = null;
		silentToTemplate = null;
		silentObject = -1;
	}

	private void reset()
	{
		clearSilent();
		posing = -1;
		chainTile = null;
		clipStartCycle = -1;
		moveDelay = -1;
		moveEnd = -1;
		animEndCycle = -1;
		animEndTile = null;
		animEndTileTemplate = null;
		startedAtTemplate = null;
		samples.clear();
		animTimeline.clear();
		clips.clear();
		startedAt = null;
		startedTick = -1;
		clickedTick = -1;
		clickedObject = -1;

		// A click held back while the obstacle finished is the one the next traversal belongs to.
		if (queuedObject >= 0)
		{
			clickedObject = queuedObject;
			clickedName = queuedName;
			clickedMenu = queuedMenu;
			clickedTick = queuedTick;
			queuedObject = -1;
		}
	}

	// ------------------------------------------------------------------- motion

	/**
	 * Samples the player's exact position while a traversal is in progress. A game tick is 600ms and
	 * movement is interpolated thirty times inside it, so tick resolution cannot tell a walk from a
	 * glide from a teleport. Local coordinates: 128ths of a tile, the golems' unit.
	 */
	void onClientTick()
	{
		// The samples below are the motion curves golems learn from, and a curve is what splits a
		// line of stepping stones into its hops.
		Player local = client.getLocalPlayer();
		LocalPoint fine = local == null ? null : local.getLocalLocation();

		// The motion itself, sample by sample: what a golem performs, the window below being a summary
		// for obstacles no curve was captured for. Sampled from the click onward, not the animation,
		// because the movement can happen *before* the clip - a rock climb puts you at the far side
		// first - so the approach is trimmed at the end. A rolling window; a cap left it unsampled.
		if (clickedTick >= 0 && local != null)
		{
			WorldView view = client.getTopLevelWorldView();
			LocalPoint fineNow = local.getLocalLocation();
			if (view != null && fineNow != null)
			{
				// The *rendered* position, and only that. A traversal moves the logical tile to the
				// destination at once and then slides the drawn position across, which is why
				// getWorldLocation() already reads the top of a rock climb; combining the two gave
				// the destination tile with the departure's sub-tile offset.
				if (samples.size() >= MotionCurve.MAX_CYCLES)
				{
					samples.remove(0);
				}
				samples.add(new int[]{
					client.getGameCycle(),
					view.getBaseX() * Golem.TILE + fineNow.getX(),
					view.getBaseY() * Golem.TILE + fineNow.getY(),
					local.getWorldLocation().getPlane(),
					local.getOrientation(),
					local.getAnimation() == -1 ? -1 : local.getAnimationFrame(),
				});
			}
		}

		// The movement window, measured against the clip rather than the tick. A traversal holds the
		// player still for part of its animation and then moves them quickly - 33 cycles of stillness
		// then 12 of movement, on the stones - and only the total made golems drift.
		if (clipStartCycle >= 0 && fine != null && previousFine != null)
		{
			boolean moving = fine.getX() != previousFine.getX()
				|| fine.getY() != previousFine.getY();
			if (moving)
			{
				int since = client.getGameCycle() - clipStartCycle;
				if (moveDelay < 0)
				{
					moveDelay = Math.max(0, since);
				}
			}
		}
		previousFine = fine;

	}

	private String objectName(int id)
	{
		try
		{
			ObjectComposition def = client.getObjectDefinition(id);
			return def == null || def.getName() == null ? "" : def.getName();
		}
		catch (RuntimeException e)
		{
			return "";
		}
	}

	private static boolean isObjectAction(MenuAction action)
	{
		switch (action)
		{
			case GAME_OBJECT_FIRST_OPTION:
			case GAME_OBJECT_SECOND_OPTION:
			case GAME_OBJECT_THIRD_OPTION:
			case GAME_OBJECT_FOURTH_OPTION:
			case GAME_OBJECT_FIFTH_OPTION:
				return true;
			default:
				return false;
		}
	}

	/**
	 * The sampled positions' templates, captured while that instance is still the loaded scene.
	 */
	private WorldPoint previousTileTemplate;
	private WorldPoint startedAtTemplate;
	private WorldPoint animEndTileTemplate;
	private WorldPoint silentFromTemplate;
	private WorldPoint silentToTemplate;

	private WorldPoint templateOf(WorldPoint tile)
	{
		return InstanceMap.templateOf(client.getTopLevelWorldView(), tile);
	}

	/** {@code base} moved by however far {@code moved} is from {@code reference}; null if base is. */
	private static WorldPoint shift(WorldPoint base, WorldPoint moved, WorldPoint reference)
	{
		if (base == null)
		{
			return null;
		}
		return new WorldPoint(base.getX() + moved.getX() - reference.getX(),
			base.getY() + moved.getY() - reference.getY(),
			base.getPlane() + moved.getPlane() - reference.getPlane());
	}

	private static String stripTags(String text)
	{
		return text == null ? "" : text.replaceAll("<[^>]*>", "");
	}
}

package com.golemsdontdie;

/**
 * One obstacle, watched being used, reduced to the facts worth keeping.
 *
 * <p>What {@link ObstacleObserver} produces once a traversal is judged real, and what telemetry
 * would send, so it deliberately holds nothing identifying who saw it.
 */
final class ObstacleSighting
{
	final int objectId;

	/** The object's name from the cache, for a human to read. */
	final String name;

	/** The menu text, e.g. "Climb-down Ladder". */
	final String menu;

	/** Every animation the player played, in order. */
	final int[] clips;

	/** Game ticks from the first clip to standing still somewhere new. */
	final int ticks;

	/**
	 * Client cycles from the first clip until the player actually moves: the wind-up, during which
	 * they hold still. Measured on the basalt stones at <b>33 cycles of stillness then 12 of
	 * movement</b>, identical across four hops. Without it a golem drifts from the first frame.
	 */
	final int moveDelay;

	/** Client cycles the movement lasts, once it starts. */
	final int moveSpan;

	/**
	 * The traversal as it happened, or null if it could not be recorded. Delay and span above
	 * remain for obstacles no curve was captured for.
	 */
	final MotionCurve curve;

	final int fromX;
	final int fromY;
	final int fromPlane;
	final int toX;
	final int toY;
	final int toPlane;

	/**
	 * True if this happened inside an instanced region: the animation is worth keeping, the
	 * destination is not. One church pew recorded three exits, (12105,4551) among them.
	 */
	final boolean instance;

	/**
	 * The way the obstacle itself moved the player, in tiles: from the tile they began on to where
	 * they finished. (0, 0) for no local movement - a ladder or a teleport. The route, where a golem
	 * gets on and off, may be a tile either side but must lie along this. See {@link RouteGeometry}.
	 */
	final int lineX;
	final int lineY;

	/**
	 * True if the traversal began inside an instance, and if it ended inside one: the route's ends
	 * are in template coordinates either way, so only these say which side is an instance.
	 */
	final boolean fromInstance;
	final boolean toInstance;

	ObstacleSighting(int objectId, String name, String menu, int[] clips, int ticks,
		int fromX, int fromY, int fromPlane, int toX, int toY, int toPlane, boolean instance,
		int moveDelay, int moveSpan, MotionCurve curve, int lineX, int lineY)
	{
		this(objectId, name, menu, clips, ticks, fromX, fromY, fromPlane, toX, toY, toPlane, instance,
			moveDelay, moveSpan, curve, lineX, lineY, false, false);
	}

	ObstacleSighting(int objectId, String name, String menu, int[] clips, int ticks,
		int fromX, int fromY, int fromPlane, int toX, int toY, int toPlane, boolean instance,
		int moveDelay, int moveSpan, MotionCurve curve, int lineX, int lineY,
		boolean fromInstance, boolean toInstance)
	{
		this.fromInstance = fromInstance;
		this.toInstance = toInstance;
		this.lineX = lineX;
		this.lineY = lineY;
		this.curve = curve;
		this.instance = instance;
		this.moveDelay = moveDelay;
		this.moveSpan = moveSpan;
		this.objectId = objectId;
		this.name = name;
		this.menu = menu;
		this.clips = clips;
		this.ticks = ticks;
		this.fromX = fromX;
		this.fromY = fromY;
		this.fromPlane = fromPlane;
		this.toX = toX;
		this.toY = toY;
		this.toPlane = toPlane;
	}

	/** True if the player went somewhere, which is what makes this a traversal. */
	boolean moved()
	{
		return fromX != toX || fromY != toY || fromPlane != toPlane;
	}

	@Override
	public String toString()
	{
		StringBuilder sb = new StringBuilder();
		sb.append(objectId).append(" \"").append(menu).append("\" clips=");
		for (int i = 0; i < clips.length; i++)
		{
			sb.append(i == 0 ? "" : ",").append(clips[i]);
		}
		return sb.append(" ticks=").append(ticks)
			.append(" delay=").append(moveDelay).append(" span=").append(moveSpan)
			.append(curve == null ? "" : " [" + curve + "]")
			.append(" ").append(fromX).append(",").append(fromY).append(",").append(fromPlane)
			.append(" -> ").append(toX).append(",").append(toY).append(",").append(toPlane)
			.append(" line=").append(lineX).append(",").append(lineY)
			.append(toInstance && !fromInstance ? " into-instance" : fromInstance && !toInstance ? " out-of-instance" : "")
			.toString();
	}
}

package com.golemsdontdie;

import java.io.*;
import java.util.*;
import java.util.zip.*;
import javax.inject.*;
import lombok.extern.slf4j.*;
import net.runelite.api.coords.*;
import static com.golemsdontdie.RouteGeometry.span;

/**
 * What a place is called, so a golem's whereabouts can be said in words.
 *
 * <p>Two sources, built offline into one file. A region's curated
 * name is used first: those name a whole 64-tile region and never name a monster. Where there is
 * none - anywhere added to the game since that list was written, Wyrmscraig included - the map's own
 * labels answer instead, the nearest one within a few dozen tiles, preferring the ones the game
 * draws largest so a region beats a monster standing in it.
 *
 * <p>Region names come from the Location Display plugin by trinhc2, BSD 2-Clause; see the README.
 */
@Slf4j
@Singleton
class PlaceNames
{
	private static final String FILE = "/places.gz";

	private static final int VERSION = 2;

	/** How far a label may be from a tile and still name it, in tiles. */
	private static final int LABEL_REACH = 48;

	/** How much a larger label is favoured over a nearer one, in tiles per size. */
	private static final int SIZE_WORTH = 24;

	/** Labels: {x, y, plane, size}, and their names, in step. */
	private int[][] labels = new int[0][];
	private String[] labelNames = new String[0];

	/** Curated region names, by region id. */
	private final Map<Integer, String> regions = new HashMap<>();

	void load()
	{
		try (InputStream in = PlaceNames.class.getResourceAsStream(FILE))
		{
			if (in == null)
			{
				log.warn("No place names on the classpath; golems will be located by region number");
				return;
			}
			try (DataInputStream data = new DataInputStream(new GZIPInputStream(in)))
			{
				int version = data.readInt();
				if (version != VERSION)
				{
					log.warn("Place names are version {}, expected {}; ignoring them", version, VERSION);
					return;
				}
				int count = data.readInt();
				labels = new int[count][];
				labelNames = new String[count];
				for (int i = 0; i < count; i++)
				{
					labelNames[i] = data.readUTF();
					labels[i] = new int[]{data.readUnsignedShort(), data.readUnsignedShort(), data.readByte(),
						data.readUnsignedByte()};
				}
				int named = data.readInt();
				for (int i = 0; i < named; i++)
				{
					String name = data.readUTF();
					regions.put(data.readUnsignedByte() << 8 | data.readUnsignedByte(), name);
				}
				log.debug("Loaded {} map labels and {} named regions", count, named);
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Place names unreadable", e);
		}
	}

	/**
	 * The regions any of the given names belong to, from both sources: a region the curated list
	 * calls one of them, and the region a map label of that name stands in. Nothing is matched
	 * loosely - the name must be the whole of it - and a name that matches nothing is logged, which
	 * is how a curated list is kept honest as the game changes under it.
	 */
	Set<Integer> regionsNamed(String[] names)
	{
		Set<Integer> found = new HashSet<>();
		for (String name : names)
		{
			boolean any = false;
			for (Map.Entry<Integer, String> region : regions.entrySet())
			{
				if (region.getValue().equalsIgnoreCase(name))
				{
					found.add(region.getKey());
					any = true;
				}
			}
			for (int i = 0; i < labels.length; i++)
			{
				if (labelNames[i].equalsIgnoreCase(name))
				{
					found.add((labels[i][0] >> 6) << 8 | labels[i][1] >> 6);
					any = true;
				}
			}
			if (!any)
			{
				log.debug("No place called {}", name);
			}
		}
		return found;
	}

	/** What to call this tile, or null if nothing is known nearby. */
	String nameFor(WorldPoint at)
	{
		return at == null ? null : nameFor(at.getX(), at.getY(), at.getPlane());
	}

	String nameFor(int x, int y, int plane)
	{
		String region = regions.get((x >> 6) << 8 | (y >> 6));
		if (region != null)
		{
			return region;
		}

		String nearest = null;
		int best = Integer.MAX_VALUE;
		for (int i = 0; i < labels.length; i++)
		{
			int[] label = labels[i];
			int distance = span(label[0] - x, label[1] - y);
			if (distance > LABEL_REACH)
			{
				continue;
			}
			// A big label a little further off is the better answer: "Ape Atoll" over "Scimitar
			// monkeys", "Wyrmscraig" over whatever stands on its shore.
			int score = distance - label[3] * SIZE_WORTH + (label[2] == plane ? 0 : LABEL_REACH);
			if (score < best)
			{
				best = score;
				nearest = labelNames[i];
			}
		}
		return nearest;
	}

	/**
	 * The nearest map label however far off, for somewhere nothing names: "near" it is still an
	 * answer, where "somewhere unmapped" was none. A label on the same floor is preferred.
	 */
	String nearest(int x, int y, int plane)
	{
		String nearest = null;
		int best = Integer.MAX_VALUE;
		for (int i = 0; i < labels.length; i++)
		{
			int[] label = labels[i];
			int score = span(label[0] - x, label[1] - y) + (label[2] == plane ? 0 : LABEL_REACH);
			if (score < best)
			{
				best = score;
				nearest = labelNames[i];
			}
		}
		return nearest;
	}
}

package com.golemsdontdie;

import net.runelite.api.*;
import net.runelite.api.coords.*;

/**
 * Where the player is in the world, including when they are aboard a boat.
 *
 * <p>A boat is a world of its own: aboard one, {@link Player#getWorldLocation()} answers in the
 * boat's coordinates, far off the map, which put every golem out of range the moment the player
 * boarded. So the deck position is carried out to the main world through the boat, found by world
 * view id as RuneLite's own overlays do.
 */
final class PlayerPosition
{
	private PlayerPosition()
	{
	}

	/** The player's tile in the main world, or null if there is no player. */
	static WorldPoint of(Client client)
	{
		Player me = client.getLocalPlayer();
		if (me == null)
		{
			return null;
		}
		WorldView view = me.getWorldView();
		WorldView top = client.getTopLevelWorldView();
		if (view == null || top == null || view.isTopLevel())
		{
			return me.getWorldLocation();
		}

		WorldEntity boat = top.worldEntities().byIndex(view.getId());
		LocalPoint onDeck = me.getLocalLocation();
		if (boat == null || onDeck == null)
		{
			return me.getWorldLocation();
		}
		LocalPoint atSea = boat.transformToMainWorld(onDeck);
		if (atSea == null)
		{
			return me.getWorldLocation();
		}
		return WorldPoint.fromLocal(top, atSea.getX(), atSea.getY(), top.getPlane());
	}
}

package com.golemsdontdie;

import java.io.*;
import java.util.*;
import java.util.zip.*;
import javax.inject.*;
import lombok.*;
import lombok.extern.slf4j.*;
import net.runelite.api.*;

/**
 * Builds the animated scenery drawn beside a golem that is using something.
 *
 * <p>{@code ObjectComposition} exposes an object's name, actions and size but <b>not its
 * model ids</b>, where {@code NPCComposition} does, so there is no runtime route from an
 * object id to its geometry. The ids are read offline from the game cache and shipped: 206
 * objects the transport network
 * references, in about a kilobyte. Each carries the animation the object itself plays, so a
 * gate, a portcullis and a fairy ring each get their own motion with nothing enumerating
 * which is which.
 *
 * <p>Models are cached and shared as the golems' are: a hundred golems boarding the same
 * ferry build one plank between them.
 */
@Slf4j
@Singleton
class PropFactory
{
	private static final String RESOURCE = "/props.gz";

	/** The client's own lighting for a scene object, before the object's own offsets. */
	private static final int BASE_AMBIENT = 64;
	private static final int BASE_CONTRAST = 768;
	private static final int LIGHT_X = -50;
	private static final int LIGHT_Y = -10;
	private static final int LIGHT_Z = -50;

	@Inject
	private Client client;

	/** What the cache says about one animated object. */
	@AllArgsConstructor
	static final class Prop
	{
		@Getter
		private final int objectId;
		@Getter
		private final int animation;
		private final int ambient;
		private final int contrast;
		@Getter
		private final int sizeX;
		@Getter
		private final int sizeY;
		private final int[] models;
	}

	private final Map<Integer, Prop> props = new HashMap<>();
	private final Map<Integer, Model> built = new HashMap<>();

	private boolean loaded;

	void load()
	{
		if (loaded)
		{
			return;
		}
		loaded = true;

		try (InputStream raw = PropFactory.class.getResourceAsStream(RESOURCE))
		{
			if (raw == null)
			{
				log.debug("No prop table in the jar; scenery will not be animated");
				return;
			}
			try (GZIPInputStream gz = new GZIPInputStream(raw);
				 DataInputStream data = new DataInputStream(gz))
			{
				int count = data.readInt();
				for (int i = 0; i < count; i++)
				{
					int objectId = data.readInt();
					int animation = data.readInt();
					int ambient = data.readShort();
					int contrast = data.readShort();
					int sizeX = data.readByte();
					int sizeY = data.readByte();
					int[] models = new int[data.readByte() & 0xFF];
					for (int m = 0; m < models.length; m++)
					{
						models[m] = data.readInt();
					}
					props.put(objectId, new Prop(objectId, animation, ambient, contrast,
						sizeX, sizeY, models));
				}
				log.debug("Loaded {} animated props", props.size());
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Prop table unreadable", e);
			props.clear();
		}
	}

	/** Null if the object has no animation worth drawing. */
	Prop propFor(int objectId)
	{
		return props.get(objectId);
	}

	/**
	 * The object's model, built once and shared. Sharing is safe because the client's
	 * transformation clones vertices out of its source, so the base is never written to.
	 *
	 * @return the lit model, or null if the cache would not give up the parts
	 */
	Model modelFor(Prop prop)
	{
		if (prop == null)
		{
			return null;
		}
		Model cached = built.get(prop.getObjectId());
		if (cached != null)
		{
			return cached;
		}

		try
		{
			ModelData merged = merge(prop.models);
			if (merged == null)
			{
				return null;
			}
			Model model = merged.light(BASE_AMBIENT + prop.ambient,
				BASE_CONTRAST + prop.contrast, LIGHT_X, LIGHT_Y, LIGHT_Z);
			built.put(prop.getObjectId(), model);
			return model;
		}
		catch (RuntimeException e)
		{
			log.debug("Could not build prop {}", prop.getObjectId(), e);
			return null;
		}
	}

	private ModelData merge(int[] modelIds)
	{
		if (modelIds.length == 1)
		{
			ModelData one = client.loadModelData(modelIds[0]);
			return one == null ? null : one.cloneVertices();
		}

		ModelData[] parts = new ModelData[modelIds.length];
		for (int i = 0; i < modelIds.length; i++)
		{
			parts[i] = client.loadModelData(modelIds[i]);
			if (parts[i] == null)
			{
				return null;
			}
		}
		return client.mergeModels(parts).cloneVertices();
	}

	void clear()
	{
		built.clear();
	}
}

package com.golemsdontdie;

import java.util.*;
import javax.inject.*;
import lombok.extern.slf4j.*;
import net.runelite.api.*;

/**
 * Builds the boats drawn under golems at sea, one of each kind: hull, mast, sail and helm, each
 * assembled once and shared by everyone sailing that size. See {@link GolemBoat}.
 */
@Slf4j
@Singleton
class RaftFactory
{
	/** The client's own lighting for an actor, matching {@link GolemModelFactory}. */
	private static final int BASE_AMBIENT = 64;
	private static final int BASE_CONTRAST = 850;
	private static final int LIGHT_X = -30;
	private static final int LIGHT_Y = -50;
	private static final int LIGHT_Z = -30;

	@Inject
	private Client client;

	/** One built model per kind of boat, and whether building it has been tried. */
	private final Map<GolemBoat, Model> models = new EnumMap<>(GolemBoat.class);
	private final Set<GolemBoat> searched = EnumSet.noneOf(GolemBoat.class);

	/**
	 * A boat's model, or null if it could not be built.
	 *
	 * <p>Built once per kind and shared by everyone sailing one; safe because the client's
	 * transformation clones vertices rather than writing to its source. Client thread only.
	 */
	Model boatModel(GolemBoat boat)
	{
		Model built = models.get(boat);
		if (built != null || !searched.add(boat))
		{
			return built;
		}

		try
		{
			ModelData hull = client.loadModelData(boat.getHullModel());
			ModelData mast = client.loadModelData(boat.getMastModel());
			ModelData cloth = client.loadModelData(boat.getClothModel());
			ModelData helm = client.loadModelData(boat.getHelmModel());
			if (hull == null || mast == null || cloth == null || helm == null)
			{
				log.debug("{} models not loaded yet", boat);
				searched.remove(boat);
				return null;
			}
			// Painted as the objects paint them; the raw models are place-holder purple.
			hull = recolour(hull.cloneVertices().cloneColors(), boat.getHullFrom(), boat.getHullTo());
			helm = recolour(helm.cloneVertices().cloneColors(), boat.getHelmFrom(), boat.getHelmTo());
			// The helm is its own tile at the stern. The rig is not in here: a sail plays an animation
			// of its own, which would fold a hull merged with it, so it is drawn apart; see rigModel.
			helm = helm.translate(0, 0, boat.getHelmOffset());
			List<ModelData> parts = new ArrayList<>();
			parts.add(hull);
			parts.add(helm);
			if (boat.getKeelModel() >= 0)
			{
				ModelData keel = client.loadModelData(boat.getKeelModel());
				if (keel == null)
				{
					log.debug("{} keel not loaded yet", boat);
					searched.remove(boat);
					return null;
				}
				parts.add(recolour(keel.cloneVertices().cloneColors(), GolemBoat.keelFrom(), GolemBoat.keelTo())
					.translate(boat.getKeelX(), 0, boat.getKeelZ()));
			}
			if (boat.getTrimModel() >= 0)
			{
				ModelData trim = client.loadModelData(boat.getTrimModel());
				if (trim == null)
				{
					log.debug("{} trim not loaded yet", boat);
					searched.remove(boat);
					return null;
				}
				parts.add(recolour(trim.cloneVertices().cloneColors(), GolemBoat.trimFrom(), GolemBoat.trimTo()));
			}
			ModelData merged = client.mergeModels(parts.toArray(new ModelData[0]));
			Model made = merged.light(BASE_AMBIENT, BASE_CONTRAST, LIGHT_X, LIGHT_Y, LIGHT_Z);
			models.put(boat, made);
			log.debug("{} built from hull, sail and helm", boat);
			return made;
		}
		catch (RuntimeException e)
		{
			log.debug("Could not build {}", boat, e);
			return null;
		}
	}

	/** Mast or cloth, lit and whole: drawn apart from the hull so its sail can play. See FakeRaft. */
	Model rigModel(GolemBoat boat, boolean cloth)
	{
		Map<GolemBoat, Model> cache = cloth ? cloths : masts;
		Model built = cache.get(boat);
		if (built != null)
		{
			return built;
		}
		ModelData data = client.loadModelData(cloth ? boat.getClothModel() : boat.getMastModel());
		if (data == null)
		{
			return null;
		}
		built = data.light(BASE_AMBIENT, BASE_CONTRAST, LIGHT_X, LIGHT_Y, LIGHT_Z);
		cache.put(boat, built);
		return built;
	}

	private final Map<GolemBoat, Model> masts = new EnumMap<>(GolemBoat.class);
	private final Map<GolemBoat, Model> cloths = new EnumMap<>(GolemBoat.class);

	private static ModelData recolour(ModelData model, short[] from, short[] to)
	{
		for (int i = 0; i < from.length; i++)
		{
			model.recolor(from[i], to[i]);
		}
		return model;
	}

	void clear()
	{
		models.clear();
		searched.clear();
		masts.clear();
		cloths.clear();
	}
}

package com.golemsdontdie;

import java.util.*;
import java.util.function.*;

/**
 * The area a golem is allowed to wander: everywhere the island map says is walkable.
 *
 * <p>A penned shape holding golems near their plinth used to exist too. No outer edge is needed:
 * {@link IslandMemory} only knows the island, so asking whether a tile is walkable asks that.
 */
class RoamBounds
{
	/**
	 * How far a golem looks for its next destination, in tiles. Sampling the whole island
	 * sends golems on island-long treks and runs every path search to its node budget; a
	 * window reaches the same coverage by random walk.
	 */
	private static final int WANDER_WINDOW = 12;

	private final IslandMemory memory;
	private final int plane;
	private final int centreX;
	private final int centreY;

	/** Destinations to pass over - a crowded tile - or null. Never blocks walking through. */
	private final BiPredicate<Integer, Integer> avoid;

	RoamBounds(IslandMemory memory, int plane, int centreX, int centreY)
	{
		this(memory, plane, centreX, centreY, null);
	}

	RoamBounds(IslandMemory memory, int plane, int centreX, int centreY,
		BiPredicate<Integer, Integer> avoid)
	{
		this.memory = memory;
		this.plane = plane;
		this.centreX = centreX;
		this.centreY = centreY;
		this.avoid = avoid;
	}

	boolean avoids(int worldX, int worldY)
	{
		return avoid != null && avoid.test(worldX, worldY);
	}

	/** True if a golem may enter this world tile. */
	boolean contains(int worldX, int worldY)
	{
		return memory.isKnownWalkable(worldX, worldY, plane);
	}

	/** A candidate destination. May be unwalkable - the caller rejects and retries. */
	int[] sample(Random random)
	{
		return new int[]{
			centreX - WANDER_WINDOW + random.nextInt(WANDER_WINDOW * 2 + 1),
			centreY - WANDER_WINDOW + random.nextInt(WANDER_WINDOW * 2 + 1),
		};
	}
}

package com.golemsdontdie;

import java.util.*;
import java.util.function.*;
import lombok.*;

/**
 * The world as one golem sees it while deciding what to do next: passability, pathfinder,
 * transports, unlocks and the current tick, rather than five collaborators in a signature
 * called once per golem per frame. One instance, reused for every golem in the frame; it holds
 * no per-golem state.
 */
@Getter
@RequiredArgsConstructor
final class RoamContext
{
	private final IslandMemory memory;
	private final GolemPathfinder pathfinder;
	private final TransportNetwork transports;
	private final GolemAbilities abilities;

	/** How each obstacle is traversed. Set, not injected, so a golem sees the latest unlocks. */
	@Setter
	private ObstacleKnowledge knowledge;

	/** Where every obstacle is; wanted here for its duration, the only per-obstacle traversal
	 * time neither measured nor inferred from a median. */
	@Setter
	private ObstacleIndex obstacles;

	/**
	 * Asked about a golem that is about to cast off alone: true if it has been kept at the quayside
	 * to wait for a crew instead. See GolemCrews.offer. Null in tools with no crews.
	 */
	@Setter
	private BiPredicate<Golem, RoamContext> muster;

	/** Where every golem is, by region, so golems spread out. Null in tools that do not count. */
	@Setter
	private GolemCensus census;

	/** Which places are cold, hot and home, for the golems that care. Null in tools that do not. */
	@Setter
	private GolemClimate climates;

	/** Where a golem in view reports each crossing, for the obstacle record; null if none. */
	@Setter
	private Consumer<GolemTraversal> traversals;

	/** How willing a golem is to enter this tile's region: 1 unless crowded. */
	float roominess(int x, int y, int plane)
	{
		return census == null ? 1f : census.roominess(x, y, plane);
	}

	/**
	 * As {@link #roominess}, as one golem sees it: a sociable golem does not mind a crowd at all, and
	 * a crowd-shy one minds it more than most.
	 */
	float roominess(int x, int y, int plane, TransportMemory memory)
	{
		if (memory == null)
		{
			return roominess(x, y, plane);
		}
		if (memory.is(GolemTrait.SOCIABLE))
		{
			return 1f;
		}
		float room = roominess(x, y, plane);
		return memory.is(GolemTrait.CROWD_SHY) ? room * room : room;
	}

	/** How little a shortcut that keeps a crowded golem in place appeals. */
	private static final float STAYING_PUT = 0.1f;

	/**
	 * How much a shortcut from one tile to another appeals, from 0 to 1, given where golems are.
	 *
	 * <p>With room, this is the room at the far end; crowded, a way out is wanted and staying in
	 * the same region hardly appeals, which a walled place needs: Meiyerditch's ladders all land
	 * inside its own walls, leaving golems nowhere roomier to prefer.
	 */
	float appeal(int fromX, int fromY, int fromPlane, int toX, int toY, int toPlane)
	{
		return appeal(fromX, fromY, fromPlane, toX, toY, toPlane, null);
	}

	/**
	 * As {@link #appeal}, for one golem: a crowd weighs differently on a sociable golem than on a
	 * crowd-shy one. Only crowds - what a golem makes of the place itself is {@link #desire}, kept
	 * apart because a golem hemmed in by others should still take a way out it does not care for.
	 */
	float appeal(int fromX, int fromY, int fromPlane, int toX, int toY, int toPlane, TransportMemory memory)
	{
		if (census == null)
		{
			return 1f;
		}
		float here = roominess(fromX, fromY, fromPlane, memory);
		float there = roominess(toX, toY, toPlane, memory);
		if (here >= 1f)
		{
			return there;
		}
		if (fromPlane == toPlane && fromX >> 6 == toX >> 6 && fromY >> 6 == toY >> 6)
		{
			return STAYING_PUT;
		}
		return Math.min(1f, there / here);
	}

	/** What a golem makes of going from one tile to another, given its taste in places. */
	float desire(TransportMemory memory, int fromX, int fromY, int toX, int toY)
	{
		return climates == null ? 1f : climates.desire(memory, fromX, fromY, toX, toY);
	}

	/** How ready a golem is to leave where it is at all, which is less where it likes being. */
	float wanderlust(TransportMemory memory, int x, int y)
	{
		return climates == null ? 1f : climates.wanderlust(memory, x, y);
	}

	boolean crowdedRegion(int x, int y, int plane)
	{
		return census != null && census.roominess(x, y, plane) < 1f;
	}

	/**
	 * The route planner, so a golem in view can consider sailing. Set after construction: it
	 * needs the same singletons this context holds, so injecting both ways would be a cycle.
	 */
	@Setter
	private RoamPlanner planner;

	/** True if a golem may take this transport by choice: it has a way back. See RoamPlanner.mayEnter. */
	boolean mayEnter(GolemTransport transport)
	{
		return planner == null || planner.mayEnter(transport, tick, this);
	}

	/** How much a golem wants this transport for where it leads. See RoamPlanner.wayOnAppeal. */
	float wayOnAppeal(GolemTransport transport)
	{
		return planner == null ? 1f : planner.wayOnAppeal(transport, tick, this);
	}

	/** The spaces a golem recently left, other than the one it is in. See RoamPlanner.spacesLeft. */
	Set<Integer> spacesLeft(int x, int y, int plane, TransportMemory memory)
	{
		return planner == null ? Collections.emptySet() : planner.spacesLeft(x, y, plane, tick, memory);
	}

	/** True if this transport lands in one of these spaces. See RoamPlanner.leadsInto. */
	boolean leadsInto(Set<Integer> spaces, GolemTransport transport)
	{
		return planner != null && planner.leadsInto(spaces, transport);
	}

	/** The shared model and animation cache, for clip lengths. Set after construction. */
	@Setter
	private GolemModelFactory models;

	/**
	 * The client's tick counter, used for cooldowns; set once per frame, and ticks rather than
	 * wall clock so cooldowns pause with the game.
	 */
	@Setter
	private int tick;

	/** How far through the tick this frame is, 0 to 1, so a golem in view glides along a route. */
	@Setter
	private float tickFraction;

	/** Whether this golem may spend one of the frame's path searches; set per golem as the plugin
	 * works down the roster, so the budget is shared rather than first-come. */
	@Setter
	private boolean mayPath;

	/**
	 * Whether an ocean search may still be run this frame. Crossings are cached per pair of ports,
	 * so almost every voyage is a lookup; the first golem to sail a route pays for an A* across a
	 * 2.4-million-tile sea.
	 */
	@Setter
	private boolean maySearchSea;

	/** "Restrict Golem ambition": golems stay on Wyrmscraig and never sail. Set each frame. */
	@Setter
	private boolean ambitionRestricted;

	void spendSeaSearch()
	{
		maySearchSea = false;
	}

	/** Golems standing on each tile this frame, keyed by {@link #tileKey}; null until filled. */
	@Setter
	private TileMap occupancy;

	/**
	 * Golems on a tile beyond which another should not go there: the game draws only so many
	 * things on one tile, and a pen of three hundred had them flashing in and out.
	 */
	static final int CROWD = 3;

	boolean crowded(int x, int y, int plane)
	{
		return occupancy != null && occupancy.getOrDefault(tileKey(x, y, plane), 0L) >= CROWD;
	}

	static long tileKey(int x, int y, int plane)
	{
		return ((long) plane << 40) | ((long) (x & 0xFFFFF) << 20) | (y & 0xFFFFF);
	}

	/** A space this many walkable tiles or larger is open ground. */
	static final int OPEN_AREA = 400;

	/** How long a measured area is trusted, in ticks, before doors may have changed it. */
	private static final int AREA_REFRESH_TICKS = 500;

	private final Map<Long, int[]> areas = new LinkedHashMap<Long, int[]>(1024, 0.75f, true)
	{
		/**
		 * Kept to the tiles asked about lately. Every tile a golem plans from is asked about, and over
		 * a long session with a big roster that was a map of most of the world, held for ever for
		 * answers that go stale in a minute anyway.
		 */
		@Override
		protected boolean removeEldestEntry(Map.Entry<Long, int[]> eldest)
		{
			return size() > MOST_AREAS;
		}
	};

	/** Tiles whose enclosed area is remembered at once; the least recently asked go first. */
	private static final int MOST_AREAS = 16384;

	/** Walkable tiles reachable from here, capped at {@link #OPEN_AREA}, cached for a while. */
	int enclosedArea(int x, int y, int plane)
	{
		long key = tileKey(x, y, plane);
		int[] cached = areas.get(key);
		if (cached != null && tick - cached[1] < AREA_REFRESH_TICKS)
		{
			return cached[0];
		}
		int size = pathfinder.areaSize(x, y, plane, OPEN_AREA);
		areas.put(key, new int[]{size, tick});
		return size;
	}
}

package com.golemsdontdie;

import java.util.*;
import javax.inject.*;
import lombok.*;
import lombok.extern.slf4j.*;
import net.runelite.api.coords.*;
import static com.golemsdontdie.RouteGeometry.span;

/**
 * Plans where a far-away golem goes next, without pathing on tiles.
 *
 * <p>A tile-accurate search is more than the answer is worth when nobody is watching: a far golem
 * aims at a transport or at open ground a few dozen tiles off, by a straight run. The inaccuracy
 * is invisible: the moment a player could see it, the golem is promoted and snapped onto ground.
 */
@Slf4j
@Singleton
class RoamPlanner
{
	/** How far a far-roaming golem will wander in one leg, in tiles. */
	private static final int LEG_MIN = 12;
	private static final int LEG_SPREAD = 40;

	/** Tries at finding a destination before the golem simply stays put for a while. */
	private static final int ATTEMPTS = 6;

	/** How far out to look for a transport worth heading to. */
	private static final int TRANSPORT_SEARCH = 48;

	@Inject
	private WorldMesh mesh;

	/** True if golems are kept on Wyrmscraig, which means no sailing at all. */
	private static boolean ambitionRestricted(RoamContext context)
	{
		return context != null && context.isAmbitionRestricted();
	}

	/**
	 * Collision harvested from the live scene, which outranks the shipped mesh: that mesh's fill
	 * spreads only through the transports shipped with it, so anywhere reached only by a taught
	 * obstacle is neither land nor reachable - Wyrmscraig's upper floors, where golems climbed a
	 * taught staircase and took it straight back down.
	 */
	@Inject
	private IslandMemory memory;

	@Inject
	private TransportNetwork transports;

	@Inject
	private GolemAbilities abilities;


	@Inject
	private Voyage voyage;

	@Inject
	private SailingDocks docks;

	/** Chance per plan that a golem at a port sets sail. Low: a golem plans every half-minute. */
	private static final float SAIL_CHANCE = 0.125f;

	/** How close to the quayside counts as being at the port, in tiles: at the dock, not near. */
	private static final int DOCK_REACH = 2;

	/** Plans the next leg for a golem that nobody can see; null if nowhere sensible was found. */
	Itinerary plan(WorldPoint from, int tick, Random random, TransportMemory memory,
		RoamContext context)
	{
		lastCandidates = 0;
		Itinerary crossing = planVoyage(from, tick, random, memory, context,
			AT_DOCK_SAIL_CHANCE * (memory != null && memory.is(GolemTrait.SEAFARER) ? 1.5f : 1f)
				* (context == null ? 1f : context.wanderlust(memory, from.getX(), from.getY())));
		if (crossing != null)
		{
			lastOutcome = Outcome.VOYAGE;
			return crossing;
		}
		if (memory != null && memory.getPendingPort() >= 0)
		{
			// Waiting at the dock for its crossing to be worked out: a golem that walked away here left
			// the field to be evicted before it came back, and never sailed.
			lastOutcome = Outcome.TO_DOCK;
			return Itinerary.of(single(from), from.getPlane(), tick, DOCK_WAIT_POLL);
		}

		// Standing where no walk starts - a stepping stone, a landing the map calls blocked - the
		// only way on is a transport from this very tile; sampling the area left the golem on it.
		if (!isSafe(from.getX(), from.getY(), from.getPlane()))
		{
			// Unless it can simply step off. A fairy ring puts you down on the ring, which no map calls
			// ground, beside ground that is: as a stone mid-river, golems rode the whole network in step.
			WorldPoint off = transports.isStone(from.getX(), from.getY(), from.getPlane()) ? null : safeNeighbour(from);
			if (off != null)
			{
				List<int[]> step = single(from);
				step.add(new int[]{off.getX(), off.getY()});
				lastOutcome = Outcome.WALK;
				return Itinerary.of(step, from.getPlane(), tick, 0);
			}
			GolemTransport onward = fromHere(from, tick, memory, random);
			if (onward != null)
			{
				noteTaken(onward, tick, memory);
				lastOutcome = Outcome.ONWARD;
				return Itinerary.thenTransport(single(from), from.getPlane(), tick, onward);
			}
		}

		boolean pressed = context != null && context.crowdedRegion(from.getX(), from.getY(), from.getPlane());
		Reach reach = new Reach(from, context, FAR_SEARCH_BUDGET);
		reach.memory = memory;

		// Somewhere it knows no way out of: now and then, back out the way it came in.
		if (random.nextFloat() < HOMEWARD_CHANCE)
		{
			GolemTransport home = wayHome(from.getX(), from.getY(), from.getPlane(), tick, memory, random);
			List<int[]> path = home == null ? null : walk(from, home.getFromX(), home.getFromY(), reach);
			if (path != null)
			{
				noteTaken(home, tick + path.size() - 1, memory);
				lastOutcome = Outcome.TRANSPORT;
				return Itinerary.thenTransport(path, from.getPlane(), tick, home);
			}
		}

		// Out of view a golem only sailed if a leg ended within two tiles of a quayside, which almost
		// never happens; now and then it goes to one on purpose.
		float seeking = DOCK_SEEK_CHANCE * (memory != null && memory.is(GolemTrait.SEAFARER) ? 3f : 1f)
			* (context == null ? 1f : context.wanderlust(memory, from.getX(), from.getY()));
		if (random.nextFloat() < seeking)
		{
			Itinerary toDock = toNearbyDock(from, tick, memory, reach);
			if (toDock != null)
			{
				lastOutcome = Outcome.TO_DOCK;
				return toDock;
			}
		}

		// A golem in a crowd is looking for the way out, so it neither rolls for this nor rests first.
		// Nor does one penned into a paddock, which has nowhere to walk its rest off. A golem where
		// it wanted to be looks for a shortcut far less often: turning each one down as it comes is
		// no use when a town offers a dozen, and one roll in ten will take it.
		boolean penned = context != null
			&& context.enclosedArea(from.getX(), from.getY(), from.getPlane()) < Golem.PENNED_TILES;
		float hopping = TRANSPORT_CHANCE
			* (context == null ? 1f : context.wanderlust(memory, from.getX(), from.getY()));
		if (pressed || penned
			|| random.nextFloat() < hopping && (memory == null || !memory.restingFromTransports(tick)))
		{
			Itinerary toTransport = toNearbyTransport(from, tick, random, memory, reach, penned || pressed);
			if (toTransport != null)
			{
				lastOutcome = Outcome.TRANSPORT;
				return toTransport;
			}
		}

		Itinerary leg = wander(from, tick, random, reach);
		lastOutcome = leg != null ? Outcome.WALK : Outcome.NOTHING;
		return leg;
	}

	/**
	 * Chance per decision that a golem with no known way out heads back out the way it came in. Not
	 * every time: it has only just arrived, and the way back is on the way in's cooldown anyway.
	 */
	static final float HOMEWARD_CHANCE = 0.25f;

	/** The network revision the component index below was built from; -1 before the first. */
	private int componentsRevision = -1;

	/** Per mesh component: transports starting in it that go somewhere else. */
	private final Map<Integer, List<GolemTransport>> exitsFrom = new HashMap<>();

	/** Per mesh component: the way back out through each transport that comes into it from elsewhere. */
	private final Map<Integer, List<GolemTransport>> waysBackFrom = new HashMap<>();

	/**
	 * The way back out through something that led here, for a golem somewhere with no known way out;
	 * or null if it knows one, or the mesh cannot say.
	 *
	 * <p>A player can learn the way into a place without the way out - in by cave, out by teleport -
	 * and golems gathered in Wyrmscraig's cave until taught the exit. Refusing to go in would bar
	 * every such dungeon, so a golem leaves the way it came; "somewhere" is the mesh's component.
	 */
	GolemTransport wayHome(int x, int y, int plane, int tick, TransportMemory memory, Random random)
	{
		if (mesh == null || transports == null || abilities == null)
		{
			return null;
		}
		indexComponents();
		// Worked out over what golems may use, which changes without the table changing.
		WaysBack back = waysBack(tick, null);
		if (waysHomeBuild != back.builds())
		{
			waysHome.clear();
			unmeshedWays.clear();
			waysHomeBuild = back.builds();
		}
		int component = componentNear(x, y, plane);
		List<GolemTransport> ways;
		if (component == 0)
		{
			ways = unmeshedWaysHome(x, y, plane);
		}
		else
		{
			ways = waysHome.get(component);
			if (ways == null)
			{
				ways = findWaysHome(component);
				waysHome.put(component, ways);
			}
		}
		if (ways.isEmpty())
		{
			return null;
		}
		GolemTransport way = ways.get(random.nextInt(ways.size()));
		return memory != null && memory.onCooldown(way, tick) ? null : way;
	}

	/** Tiles of unmeshed rooms remembered at once, before the memory is started afresh. */
	private static final int UNMESHED_REMEMBERED = 50_000;

	/** Ways home for ground the mesh has nothing on, by tile, worked out once per change to the network. */
	private final Map<Long, List<GolemTransport>> unmeshedWays = new HashMap<>();

	/**
	 * The ways back out of a room the mesh knows nothing about, for a golem in it with no known way
	 * out; otherwise none.
	 *
	 * <p>Content newer than the mesh has no components, and the rule above had nothing to say about
	 * it: the Doom of Mokhaiotl's arena is entered by jumping down a gap and left through a loot
	 * interface, a teleport or death, none of which is ever learned, and golems that followed the
	 * player in stayed for good. So the room is worked out from the island map's own collision - the
	 * unmeshed floor a golem can walk from where it stands, of any size - and if nothing offered
	 * leads out of it onto ground joined to home, it leaves the way it came in.
	 */
	private List<GolemTransport> unmeshedWaysHome(int x, int y, int plane)
	{
		List<GolemTransport> known = unmeshedWays.get(RoamContext.tileKey(x, y, plane));
		if (known != null)
		{
			return known;
		}
		// Kept to a size: each room remembers every tile of itself, and a session wandering new
		// content could otherwise hold hundreds of thousands until the network next changed.
		if (unmeshedWays.size() > UNMESHED_REMEMBERED)
		{
			unmeshedWays.clear();
		}
		// Not remembered for ground not yet read: asked again once the room's floor is known.
		boolean remember = memory.isKnownWalkable(x, y, plane);
		TileMap room = unmeshedRoom(x, y, plane);
		if (room == null)
		{
			if (remember)
			{
				unmeshedWays.put(RoamContext.tileKey(x, y, plane), Collections.emptyList());
			}
			return Collections.emptyList();
		}
		List<GolemTransport> ways = new ArrayList<>();
		List<GolemTransport> fromHome = new ArrayList<>();
		for (GolemTransport t : transports.all())
		{
			if (!transports.isOffered(t) || !abilities.canUse(t))
			{
				continue;
			}
			boolean fromIn = t.getFromPlane() == plane && inRoom(room, t.getFromX(), t.getFromY());
			boolean toIn = t.getToPlane() == plane && inRoom(room, t.getToX(), t.getToY());
			// A way out only if it lands on ground the mesh knows and home reaches. One into another
			// unmeshed room, as the Gap leads from the Doom lobby down into the arena, is deeper in,
			// not out: counted as a way out, it left the lobby with no way home, and golems led up out
			// of the arena jumped straight back down.
			if (fromIn && !toIn && joinedToHome(t.getToX(), t.getToY(), t.getToPlane()))
			{
				ways = Collections.emptyList();
				fromHome = ways;
				break;
			}
			// Only what leads in from outside: one part of the room to another, such as a learned
			// "delve deeper" into the same room again, is no way home; nor one back into ground cut
			// off from home. Best, what came in from ground home reaches, so a chain of rooms is left
			// the whole way out.
			if (toIn && !fromIn && !mesh.isCutOff(t.getFromX(), t.getFromY(), t.getFromPlane()))
			{
				ways.add(t.backThrough());
				if (joinedToHome(t.getFromX(), t.getFromY(), t.getFromPlane()))
				{
					fromHome.add(t.backThrough());
				}
			}
		}
		if (!fromHome.isEmpty())
		{
			ways = fromHome;
		}
		for (int i = 0; remember && i < room.size(); i++)
		{
			long tile = room.keyAt(i);
			unmeshedWays.put(RoamContext.tileKey(GolemPathfinder.unpackX(tile), GolemPathfinder.unpackY(tile), plane), ways);
		}
		return ways;
	}

	/** What golems can get back from, built on first use. See WaysBack. */
	private WaysBack waysBack;

	/** Transports turned down for having no way back, since start: the simulation reports it. */
	@lombok.Getter
	private int refusedNoWayBack;

	/**
	 * True if a golem may take this transport: from where it lands it could get back where it set
	 * off, or home. A golem goes nowhere it has no way back from; see WaysBack.
	 *
	 * <p>Only asked of a choice. A golem leaving a dead end, stepping off a stone mid-river or going
	 * home the way it came in takes what it must.
	 */
	boolean mayEnter(GolemTransport transport, int tick, RoamContext context)
	{
		if (mesh == null || transports == null || abilities == null)
		{
			return true;
		}
		waysBack(tick, context);
		List<Integer> from = waysBack.setOff(transport);
		if (from.isEmpty())
		{
			// Leaving ground the mesh does not know, which is where the unmeshed ways home lead from.
			return true;
		}
		List<Integer> to = waysBack.landing(transport);
		if (to.isEmpty())
		{
			to = unmeshedExits(transport);
			if (to == null)
			{
				// Its floor runs on into ground the mesh knows, by the island map: nothing to judge by.
				return true;
			}
		}
		if (waysBack.comesBack(from, to))
		{
			return true;
		}
		refusedNoWayBack++;
		return false;
	}

	/**
	 * How much less a golem wants a transport into a dead end: somewhere that leads nowhere but
	 * back. Still taken, as a player might look in; less often, as there is nothing beyond. At
	 * Castle Wars the lobby's portals lead into two waiting rooms whose only way out is back, and
	 * golems spent the day going in and out of them.
	 */
	static final float DEAD_END_APPEAL = 0.6f;

	/** How much a golem wants this transport for where it leads: less into a dead end. See WaysBack.isDeadEnd. */
	float wayOnAppeal(GolemTransport transport, int tick, RoamContext context)
	{
		if (mesh == null || transports == null || abilities == null)
		{
			return 1f;
		}
		waysBack(tick, context);
		return waysBack.isDeadEnd(waysBack.setOff(transport), waysBack.landing(transport)) ? DEAD_END_APPEAL : 1f;
	}

	/**
	 * True while "Restrict golem ambition" keeps golems off the sea. Set by the plugin each frame,
	 * and read here rather than from whichever golem's context asks: asked both ways, the graph
	 * flipped between no ports and every port depending on who asked first.
	 */
	@lombok.Setter
	private boolean keptAshore;

	/** The spaces of every dock a golem may sail from now; none while golems are kept ashore. */
	private Set<Integer> openPorts(RoamContext context)
	{
		if (docks == null || keptAshore)
		{
			return Collections.emptySet();
		}
		// Never back to the port a golem last left (see Voyage), so with two docks open a crossing is
		// one way: the sea is a way back only once there is a third to go round by.
		List<SailingDocks.Dock> open = docks.openDocks();
		if (open.size() < 3)
		{
			return Collections.emptySet();
		}
		Set<Integer> ports = new HashSet<>();
		for (SailingDocks.Dock dock : open)
		{
			WorldPoint shore = dock.getShore();
			int space = mesh.componentAt(shore.getX(), shore.getY(), shore.getPlane());
			if (space != 0)
			{
				ports.add(space);
			}
		}
		return ports;
	}

	/** Landings on ground the mesh has nothing on, by tile, to the spaces usable ways out lead to. */
	private final Map<Long, List<Integer>> unmeshedExits = new HashMap<>();

	/** The build of the graph the landings above were worked out on. */
	private int unmeshedExitsBuild = -1;

	/**
	 * For a transport landing where the mesh knows nothing - content newer than the mesh, an
	 * instance - the spaces a golem could go on to from the floor it lands on, by the usable ways
	 * out of it; or null if that floor runs on into ground the mesh knows. The floor is the island
	 * map's, as unmeshedRoom reads it, so ground never seen has only what starts beside the landing.
	 */
	private List<Integer> unmeshedExits(GolemTransport transport)
	{
		if (unmeshedExitsBuild != waysBack.builds() || unmeshedExits.size() > UNMESHED_REMEMBERED)
		{
			unmeshedExits.clear();
			unmeshedExitsBuild = waysBack.builds();
		}
		int plane = transport.getToPlane();
		long key = RoamContext.tileKey(transport.getToX(), transport.getToY(), plane);
		if (unmeshedExits.containsKey(key))
		{
			return unmeshedExits.get(key);
		}
		TileMap room = unmeshedRoom(transport.getToX(), transport.getToY(), plane);
		List<Integer> exits = null;
		if (room != null)
		{
			exits = new ArrayList<>();
			for (GolemTransport t : transports.all())
			{
				if (!waysBack.wasUsable(t) || t.getFromPlane() != plane || !inRoom(room, t.getFromX(), t.getFromY()))
				{
					continue;
				}
				for (int space : waysBack.landing(t))
				{
					if (!exits.contains(space))
					{
						exits.add(space);
					}
				}
			}
		}
		unmeshedExits.put(key, exits);
		return exits;
	}

	/**
	 * True if a golem here stands where it could not get home by anything golems may use: walking,
	 * climbing, sailing, over shipped and learned rows but never a locked one. Nowhere a golem goes
	 * by choice, so one found there was put there - a saved position, a lever pulled since, a route
	 * withdrawn - and is brought home. False where the mesh knows nothing.
	 */
	boolean isStranded(int x, int y, int plane, int tick)
	{
		if (mesh == null || transports == null || abilities == null)
		{
			return false;
		}
		int space = mesh.componentAt(x, y, plane);
		return space != 0 && !waysBack(tick, null).reachesHome(space);
	}

	/**
	 * Works out what golems can get back from afresh at the next question, whatever changed or not:
	 * after the minute following login, once quests and levels have been read.
	 */
	void forgetWaysBack()
	{
		if (waysBack != null)
		{
			waysBack.forget();
		}
	}

	/** The graph build the ways home above were worked out on. */
	private int waysHomeBuild = -1;

	/**
	 * What golems can get back from, brought up to date.
	 *
	 * @param context the asking golem's, for whether it may sail; null to take every open dock
	 */
	private WaysBack waysBack(int tick, RoamContext context)
	{
		if (waysBack == null)
		{
			waysBack = new WaysBack(mesh, transports, abilities::canUse);
		}
		waysBack.refresh(tick, () -> openPorts(context));
		return waysBack;
	}

	/**
	 * Whether a tile, or one beside it, is ground the mesh knows from which a golem could get home by
	 * what it may use: walking, climbing and sailing. Home "reaching" it over every row, locked ones
	 * too, was not enough: golems were led back through a door they had never seen opened into a
	 * cell they then could not leave.
	 */
	private boolean joinedToHome(int x, int y, int plane)
	{
		if (waysBack == null)
		{
			return componentNear(x, y, plane) != 0 && !mesh.isCutOff(x, y, plane);
		}
		for (int space : mesh.spacesAt(x, y, plane))
		{
			if (waysBack.reachesHome(space))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * The unmeshed floor a golem can walk from a tile, of any size, or null the moment it steps onto
	 * ground the mesh knows. Only unmeshed tiles are crossed, so it is as large as the room and no
	 * larger: ground walkable without the mesh is only what the client has loaded, never the world.
	 */
	private TileMap unmeshedRoom(int x, int y, int plane)
	{
		TileMap room = new TileMap(1024);
		room.add(GolemPathfinder.pack(x, y), 0);
		for (int head = 0; head < room.size(); head++)
		{
			long at = room.keyAt(head);
			int cx = GolemPathfinder.unpackX(at);
			int cy = GolemPathfinder.unpackY(at);
			for (int dx = -1; dx <= 1; dx++)
			{
				for (int dy = -1; dy <= 1; dy++)
				{
					long next = GolemPathfinder.pack(cx + dx, cy + dy);
					if (room.containsKey(next) || !memory.isKnownWalkable(cx + dx, cy + dy, plane)
						|| !memory.canStep(cx, cy, plane, dx, dy))
					{
						continue;
					}
					if (mesh.componentAt(cx + dx, cy + dy, plane) != 0)
					{
						return null;
					}
					room.add(next, 0);
				}
			}
		}
		return room;
	}

	/** Whether a transport's end is in a room, or beside it: an end can sit on its object. */
	private static boolean inRoom(TileMap room, int x, int y)
	{
		for (int dx = -1; dx <= 1; dx++)
		{
			for (int dy = -1; dy <= 1; dy++)
			{
				if (room.containsKey(GolemPathfinder.pack(x + dx, y + dy)))
				{
					return true;
				}
			}
		}
		return false;
	}

	/** Spaces reachable by shortcuts and still shut in: the open world reaches hundreds. */
	private static final int SHUT_IN = 8;

	/** Ways home by component, worked out once per change to the network; empty where there is no need. */
	private final Map<Integer, List<GolemTransport>> waysHome = new HashMap<>();

	/**
	 * The ways back out, for a golem in this component, if everywhere it can reach from here is shut
	 * in; otherwise none.
	 *
	 * <p>Shut in is not only one room: a courtyard whose only way out is a cave whose only way out
	 * is the courtyard is two spaces leading to each other, and a simulated year found golems dozens
	 * to a tile in just that. If usable shortcuts run out within a few spaces, the golem may leave.
	 */
	private List<GolemTransport> findWaysHome(int start)
	{
		// A golem that can get home by what it may use - walking, climbing, sailing - needs no way
		// back out. Counting shortcuts alone called a courtyard with a dock shut in, and the way back
		// it was given was a locked cell door: into a cell with no way out.
		if (waysBack != null)
		{
			if (waysBack.reachesHome(start))
			{
				return Collections.emptyList();
			}
			// Out by a way back that leads somewhere home can be reached from, where there is one.
			List<GolemTransport> homeward = new ArrayList<>();
			for (GolemTransport way : waysBackFrom.getOrDefault(start, Collections.emptyList()))
			{
				if (joinedToHome(way.getToX(), way.getToY(), way.getToPlane()))
				{
					homeward.add(way);
				}
			}
			if (!homeward.isEmpty())
			{
				return homeward;
			}
		}
		Set<Integer> reached = new HashSet<>();
		ArrayDeque<Integer> queue = new ArrayDeque<>();
		reached.add(start);
		queue.add(start);
		while (!queue.isEmpty())
		{
			List<GolemTransport> exits = exitsFrom.get(queue.poll());
			if (exits == null)
			{
				continue;
			}
			for (GolemTransport exit : exits)
			{
				if (!abilities.canUse(exit) || !landsSomewhereUseful(exit))
				{
					continue;
				}
				int to = componentNear(exit.getToX(), exit.getToY(), exit.getToPlane());
				// Somewhere the mesh knows nothing about is somewhere else entirely: not shut in.
				if (to == 0)
				{
					return Collections.emptyList();
				}
				if (reached.add(to))
				{
					if (reached.size() > SHUT_IN)
					{
						return Collections.emptyList();
					}
					queue.add(to);
				}
			}
		}

		List<GolemTransport> ways = new ArrayList<>();
		for (GolemTransport way : waysBackFrom.getOrDefault(start, Collections.emptyList()))
		{
			// Back to somewhere outside the trap, not to another room of it.
			int to = componentNear(way.getToX(), way.getToY(), way.getToPlane());
			// Nor into ground cut off from home: a one-way exit turned round leads nowhere a golem
			// could come back from, as the Castle Wars tunnels' ways up to the lobby did.
			if (!reached.contains(to) && !mesh.isCutOff(way.getToX(), way.getToY(), way.getToPlane()))
			{
				ways.add(way);
			}
		}
		return ways;
	}

	/** The component of a tile, or of a tile beside it: a transport's end can sit on its object. */
	private int componentNear(int x, int y, int plane)
	{
		int here = mesh.componentAt(x, y, plane);
		for (int dx = -1; dx <= 1 && here == 0; dx++)
		{
			for (int dy = -1; dy <= 1 && here == 0; dy++)
			{
				here = mesh.componentAt(x + dx, y + dy, plane);
			}
		}
		return here;
	}

	/** Sorts every transport into the components it leaves and enters, once per change to the network. */
	private void indexComponents()
	{
		if (componentsRevision == transports.revision())
		{
			return;
		}
		componentsRevision = transports.revision();
		exitsFrom.clear();
		waysBackFrom.clear();
		waysHome.clear();
		unmeshedWays.clear();
		for (GolemTransport t : transports.all())
		{
			if (!transports.isOffered(t))
			{
				continue;
			}
			int from = componentNear(t.getFromX(), t.getFromY(), t.getFromPlane());
			int to = componentNear(t.getToX(), t.getToY(), t.getToPlane());
			boolean elsewhere = from == 0 || to == 0 || from != to || t.getFromPlane() != t.getToPlane();
			if (!elsewhere)
			{
				continue;
			}
			if (from != 0)
			{
				exitsFrom.computeIfAbsent(from, k -> new ArrayList<>()).add(t);
			}
			if (to != 0)
			{
				waysBackFrom.computeIfAbsent(to, k -> new ArrayList<>()).add(t.backThrough());
			}
		}
	}

	/** Tiles a far golem's flood may visit: a third of a golem in view's, and the plan's only one. */
	private static final int FAR_SEARCH_BUDGET = 1000;

	// A longer flood for golems in a crowd cost two and a half times the planning and got no more of
	// them out of Meiyerditch, whose ways out are two tiles in a warren.

	/**
	 * Everywhere a golem can walk to from where it stands, within the budget - flooded at most once
	 * per plan, only after a straight line fails, and underground those almost never exist.
	 */
	@RequiredArgsConstructor
	private static final class Reach
	{
		private final WorldPoint from;
		private final RoamContext context;

		/** The golem's own memory, for the traits that change where it wants to go. */
		private TransportMemory memory;
		private final int budget;
		private TileMap cameFrom;

		/** The flood, made on first use; empty without a pathfinder. */
		TileMap tiles()
		{
			if (cameFrom == null)
			{
				cameFrom = context == null || context.getPathfinder() == null
					? new TileMap(4)
					: context.getPathfinder().flood(from.getX(), from.getY(), from.getPlane(), budget);
			}
			return cameFrom;
		}

		/** The walk to a tile the flood reached, the golem's own tile first; null if not reached. */
		List<int[]> pathTo(int x, int y)
		{
			java.util.Deque<int[]> found = GolemPathfinder.pathFrom(tiles(), from.getX(), from.getY(), x, y);
			if (found == null)
			{
				return null;
			}
			List<int[]> path = new ArrayList<>(found.size() + 1);
			path.add(new int[]{from.getX(), from.getY()});
			path.addAll(found);
			return path;
		}
	}

	/**
	 * A walk somewhere else, or null: a straight leg of a few dozen tiles where there is one, else
	 * somewhere in the far half of the flood, so a golem in a corridor still goes somewhere.
	 */
	private Itinerary wander(WorldPoint from, int tick, Random random, Reach reach)
	{
		boolean restless = reach.memory != null && reach.memory.is(GolemTrait.RESTLESS);

		// A golem that likes the cold, the heat, or home takes the leg that suits it best of the
		// several it finds, rather than the first that works. That is the whole of how it gets
		// there: a few dozen tiles the right way, a couple of times a minute, all year.
		GolemClimate climate = reach.context == null ? null : reach.context.getClimates();
		boolean picky = climate != null && climate.cares(reach.memory);
		List<int[]> wanted = picky ? new ArrayList<>(ATTEMPTS) : null;

		for (int attempt = 0; attempt < ATTEMPTS; attempt++)
		{
			int distance = LEG_MIN + random.nextInt(restless ? LEG_SPREAD * 2 : LEG_SPREAD);
			double angle = random.nextDouble() * Math.PI * 2;
			int toX = from.getX() + (int) Math.round(Math.cos(angle) * distance);
			int toY = from.getY() + (int) Math.round(Math.sin(angle) * distance);

			if (!isSafe(toX, toY, from.getPlane()))
			{
				continue;
			}

			// And in the same connected space: a destination inside a sealed courtyard can have a
			// perfectly walkable line to it and still be unreachable on foot.
			if (!mesh.sameComponent(from.getX(), from.getY(), toX, toY, from.getPlane()))
			{
				continue;
			}
			lastCandidates++;
			if (picky)
			{
				wanted.add(new int[]{toX, toY, (int) (climate.liking(reach.memory, toX, toY) * 10000)});
				continue;
			}
			List<int[]> leg = straightLine(from.getX(), from.getY(), toX, toY, from.getPlane());
			if (leg == null)
			{
				continue;
			}
			return Itinerary.of(leg, from.getPlane(), tick, 0);
		}

		if (picky)
		{
			// Best liked first, and the rest behind it: the pick still has to be walkable in a
			// straight line, and where nothing is liked more than anything else this is the order
			// they were found in, which is random.
			wanted.sort((one, other) -> other[2] - one[2]);
			for (int[] candidate : wanted)
			{
				List<int[]> leg = straightLine(from.getX(), from.getY(), candidate[0], candidate[1], from.getPlane());
				if (leg != null)
				{
					return Itinerary.of(leg, from.getPlane(), tick, 0);
				}
			}
		}

		TileMap tiles = reach.tiles();
		if (tiles.size() < 2)
		{
			return null;
		}
		int reached = tiles.size();
		int half = reached / 2;
		for (int attempt = 0; attempt < ATTEMPTS; attempt++)
		{
			long tile = tiles.keyAt(half + random.nextInt(reached - half));
			int x = GolemPathfinder.unpackX(tile);
			int y = GolemPathfinder.unpackY(tile);
			// In the same connected space as the straight lines above: a tile the walk reaches but
			// the mesh counts as another space is one the cut-off sweep would carry a golem home from.
			if ((x == from.getX() && y == from.getY()) || !isSafe(x, y, from.getPlane())
				|| !mesh.sameComponent(from.getX(), from.getY(), x, y, from.getPlane()))
			{
				continue;
			}
			lastCandidates++;
			List<int[]> path = reach.pathTo(x, y);
			if (path != null)
			{
				return Itinerary.of(path, from.getPlane(), tick, 0);
			}
		}
		return null;
	}

	/** Ticks a golem out of view stands before looking again, when nowhere was found. */
	private static final int IDLE_MIN = 8;
	private static final int IDLE_SPREAD = 16;

	/**
	 * A pause on the spot, for a golem that found nowhere to go.
	 *
	 * <p>Without it a golem with no plan asked again the next frame, and a golem with no plan is
	 * exactly one whose plans fail: a search and two dozen probes, sixty times a second.
	 *
	 * @param failures plans in a row that found nothing, before this one
	 */
	static Itinerary idle(WorldPoint at, int tick, Random random, int failures)
	{
		int ticks = (IDLE_MIN + random.nextInt(IDLE_SPREAD)) << Math.min(Math.max(0, failures), 3);
		return Itinerary.of(single(at), at.getPlane(), tick, ticks);
	}

	/** How far from a quayside or a landing golems spread out to find a tile each. */
	private static final int SPREAD_TILES = 3;

	/**
	 * The nearest tile to {@code at} a golem can stand on that is not in {@code taken}, joined to it
	 * on foot and at most a few tiles off; {@code at} itself if there is none. For a crew, which by
	 * its route's reckoning is all in one place: at the quayside waiting, and on landing.
	 */
	WorldPoint freeTileNear(WorldPoint at, Set<Long> taken)
	{
		return freeTileNear(at, taken, false);
	}

	/**
	 * As {@link #freeTileNear(WorldPoint, Set)}, for golems stepping off the player's ship: never
	 * the sea, and never the start of a transport. What the island memory has seen walked on reaches
	 * out along a pier and over its gangplank, and golems were set down on the water, afloat on
	 * rafts, and on the gangplank itself.
	 */
	WorldPoint landingTileNear(WorldPoint at, Set<Long> taken)
	{
		return freeTileNear(at, taken, true);
	}

	private WorldPoint freeTileNear(WorldPoint at, Set<Long> taken, boolean landing)
	{
		int plane = at.getPlane();
		for (int ring = 0; ring <= SPREAD_TILES; ring++)
		{
			for (int dx = -ring; dx <= ring; dx++)
			{
				for (int dy = -ring; dy <= ring; dy++)
				{
					if (Math.max(Math.abs(dx), Math.abs(dy)) != ring)
					{
						continue;
					}
					int x = at.getX() + dx;
					int y = at.getY() + dy;
					if (!taken.contains(RoamContext.tileKey(x, y, plane)) && isSafe(x, y, plane)
						&& (ring == 0 || mesh.sameComponent(at.getX(), at.getY(), x, y, plane))
						&& (!landing || !mesh.isOcean(x, y, plane) && !transports.hasOrigin(x, y)))
					{
						return new WorldPoint(x, y, plane);
					}
				}
			}
		}
		return at;
	}

	/** How far from its place at a quayside a golem waiting there wanders. */
	private static final int MILL_TILES = 2;

	/**
	 * Somewhere near its place at a quayside for a golem waiting there to wander to, or null if a
	 * few tries find nowhere: ground it can stand on, joined to its place on foot, and as a landing
	 * is, never the sea or the start of a transport. Not in {@code taken} either, one golem a tile.
	 */
	WorldPoint quayTileNear(WorldPoint spot, Set<Long> taken, Random random)
	{
		int plane = spot.getPlane();
		for (int attempt = 0; attempt < 4; attempt++)
		{
			int x = spot.getX() + random.nextInt(MILL_TILES * 2 + 1) - MILL_TILES;
			int y = spot.getY() + random.nextInt(MILL_TILES * 2 + 1) - MILL_TILES;
			if (!taken.contains(RoamContext.tileKey(x, y, plane)) && isSafe(x, y, plane)
				&& mesh.sameComponent(spot.getX(), spot.getY(), x, y, plane)
				&& !mesh.isOcean(x, y, plane) && !transports.hasOrigin(x, y))
			{
				return new WorldPoint(x, y, plane);
			}
		}
		return null;
	}

	/** Standing where it is for a while: a golem waiting at a quayside for a crew to make up. */
	static Itinerary stayPut(WorldPoint at, int tick, int ticks)
	{
		return Itinerary.of(single(at), at.getPlane(), tick, Math.max(1, ticks));
	}

	private static List<int[]> single(WorldPoint at)
	{
		List<int[]> path = new ArrayList<>(1);
		path.add(new int[]{at.getX(), at.getY()});
		return path;
	}

	/**
	 * A walk to the quayside of the nearest open dock in reach, or null. Not while on shore leave,
	 * and not to a dock the golem is already at - that is the voyage roll's business.
	 */
	private Itinerary toNearbyDock(WorldPoint from, int tick, TransportMemory memory, Reach reach)
	{
		if (docks == null || memory == null || ambitionRestricted(reach.context) || memory.onShoreLeave())
		{
			return null;
		}
		List<SailingDocks.Dock> near = new ArrayList<>();
		for (SailingDocks.Dock dock : docks.getDocks())
		{
			WorldPoint shore = dock.getShore();
			int distance = span(shore.getX() - from.getX(), shore.getY() - from.getY());
			if (shore.getPlane() == from.getPlane() && distance > DOCK_REACH && distance <= TRANSPORT_SEARCH
				&& docks.isOpen(dock))
			{
				near.add(dock);
			}
		}
		near.sort((a, b) -> Integer.compare(
			span(a.getShore().getX() - from.getX(), a.getShore().getY() - from.getY()),
			span(b.getShore().getX() - from.getX(), b.getShore().getY() - from.getY())));
		for (SailingDocks.Dock dock : near)
		{
			List<int[]> path = walk(from, dock.getShore().getX(), dock.getShore().getY(), reach);
			if (path != null)
			{
				return Itinerary.of(path, from.getPlane(), tick, 0);
			}
		}
		return null;
	}

	/**
	 * A walk to a tile - a straight line where there is one, otherwise through the flood - the
	 * golem's own tile first; null if there is no way within reach.
	 */
	private List<int[]> walk(WorldPoint from, int toX, int toY, Reach reach)
	{
		List<int[]> line = straightLine(from.getX(), from.getY(), toX, toY, from.getPlane());
		return line != null ? line : reach.pathTo(toX, toY);
	}

	/**
	 * Puts a transport a far golem has chosen on its cooldown, from when it will be used. Far golems
	 * never did, and at the foot of a ladder the nearest transport is the ladder: nine in ten climbs
	 * on Wyrmscraig were undone at once.
	 */
	private static void noteTaken(GolemTransport transport, int whenUsed, TransportMemory memory)
	{
		if (memory != null)
		{
			memory.used(transport, whenUsed);
		}
	}

	/**
	 * A transport starting on exactly this tile, for a golem that cannot walk off it. One not on
	 * cooldown if there is one; failing that the way back, since standing on a stone is worse.
	 */
	private GolemTransport fromHere(WorldPoint at, int tick, TransportMemory memory, Random random)
	{
		GolemTransport back = null;
		// Any of the ways on, not the first listed: always the first sent every golem the same way.
		List<GolemTransport> onward = new ArrayList<>();
		for (GolemTransport transport : transports.from(at.getX(), at.getY()))
		{
			if (transport.getFromPlane() != at.getPlane() || !abilities.canUse(transport)
				|| !landsSomewhereUseful(transport))
			{
				continue;
			}
			if (memory == null || !memory.onCooldown(transport, tick))
			{
				onward.add(transport);
			}
			else if (back == null)
			{
				back = transport;
			}
		}
		return onward.isEmpty() ? back : onward.get(random.nextInt(onward.size()));
	}

	private WorldPoint safeNeighbour(WorldPoint at)
	{
		for (int dx = -1; dx <= 1; dx++)
		{
			for (int dy = -1; dy <= 1; dy++)
			{
				if ((dx != 0 || dy != 0) && isSafe(at.getX() + dx, at.getY() + dy, at.getPlane()))
				{
					return new WorldPoint(at.getX() + dx, at.getY() + dy, at.getPlane());
				}
			}
		}
		return null;
	}

	/**
	 * True if a golem arriving by this transport has somewhere to go: walkable ground, or a chain of
	 * transports onward - not this one in reverse - ending on some. See leadsToGround.
	 */
	private boolean landsSomewhereUseful(GolemTransport transport)
	{
		return transports.leadsToGround(transport.getToX(), transport.getToY(), transport.getToPlane(),
			transport.getFromX(), transport.getFromY(), transport.getFromPlane(), TransportNetwork.CHAIN_HOPS,
			abilities::canUse, this::isSafe);
	}

	/**
	 * Rolls for a crossing, for a golem standing at a port.
	 *
	 * <p>Called from two places, which is the point: a far golem plans one when its route runs out,
	 * and a golem in view rolls as it steps onto a tile, sailing having once happened only out of
	 * range. Affordable in view because crossings are cached per pair of ports.
	 *
	 * @return a crossing, or null if the golem is not at a port, is on shore leave, lost the roll,
	 *         or the route is unknown and the frame's search is spent
	 */
	Itinerary planVoyage(WorldPoint from, int tick, Random random, TransportMemory memory,
		RoamContext context)
	{
		// A seafarer takes every chance it gets; the rest sail now and then, and a golem standing
		// where it wanted to be hardly at all.
		return planVoyage(from, tick, random, memory, context,
			SAIL_CHANCE * (memory != null && memory.is(GolemTrait.SEAFARER) ? 3f : 1f)
				* (context == null ? 1f : context.wanderlust(memory, from.getX(), from.getY())));
	}

	/**
	 * A voyage for a golem that decided to sail and waited at the quay for company that never made
	 * a crew: it sails alone, as it meant to, rather than rolling again and, as often as not, not.
	 */
	Itinerary planVoyageAlone(WorldPoint from, int tick, Random random, TransportMemory memory, RoamContext context)
	{
		return planVoyage(from, tick, random, memory, context, 1f);
	}

	/** Chance a far golem at a dock sets sail, per plan: higher, as it plans once per leg. */
	private static final float AT_DOCK_SAIL_CHANCE = 0.6f;

	/** Ticks a far golem at a dock waits before asking again whether its crossing is ready. */
	private static final int DOCK_WAIT_POLL = 4;

	/** Chance per plan that a far golem with a dock in reach heads for it. */
	private static final float DOCK_SEEK_CHANCE = 0.1f;

	/**
	 * How near a gangplank, in tiles, draws a golem in view toward it. A golem only rolled to sail
	 * on stepping within a couple of tiles of the quayside, which at random it almost never did.
	 */
	static final int DOCK_ATTRACTION = 15;

	/** Chance, each time a golem in view picks somewhere to walk, that a dock in range is where. */
	private static final float DOCK_ATTRACTION_CHANCE = 0.25f;

	/**
	 * A dock a golem in view has chosen to walk up to, or null: the nearest open one within
	 * {@link #DOCK_ATTRACTION} tiles, not one it is at, and not on shore leave.
	 */
	SailingDocks.Dock dockToVisit(WorldPoint from, TransportMemory memory, RoamContext context, Random random)
	{
		if (docks == null || memory == null || ambitionRestricted(context) || memory.onShoreLeave())
		{
			return null;
		}
		SailingDocks.Dock nearest = null;
		int nearestDistance = Integer.MAX_VALUE;
		for (SailingDocks.Dock dock : docks.getDocks())
		{
			WorldPoint shore = dock.getShore();
			if (shore.getPlane() != from.getPlane())
			{
				continue;
			}
			int distance = span(shore.getX() - from.getX(), shore.getY() - from.getY());
			if (distance > DOCK_REACH && distance <= DOCK_ATTRACTION && distance < nearestDistance && docks.isOpen(dock))
			{
				nearest = dock;
				nearestDistance = distance;
			}
		}
		if (nearest == null || random.nextFloat() >= DOCK_ATTRACTION_CHANCE)
		{
			return null;
		}
		return nearest;
	}

	SailingDocks.Dock dockAt(WorldPoint from)
	{
		return voyage == null ? null : voyage.dockAt(from, DOCK_REACH);
	}

	boolean atDock(WorldPoint from, SailingDocks.Dock dock)
	{
		WorldPoint shore = dock.getShore();
		return shore.getPlane() == from.getPlane()
			&& span(shore.getX() - from.getX(), shore.getY() - from.getY()) <= DOCK_REACH;
	}

	/** Rolls for a crossing for a golem that walked to a dock on purpose: the far golem's chance. */
	Itinerary planVoyageAtDock(WorldPoint from, int tick, Random random, TransportMemory memory, RoamContext context)
	{
		return planVoyage(from, tick, random, memory, context, AT_DOCK_SAIL_CHANCE
			* (context == null ? 1f : context.wanderlust(memory, from.getX(), from.getY())));
	}

	private Itinerary planVoyage(WorldPoint from, int tick, Random random, TransportMemory memory,
		RoamContext context, float chance)
	{
		// A golem already waiting to sail has made its decision and does not roll again, but only at
		// the dock it is waiting at. See TransportMemory.holdPending.
		boolean waiting = memory != null && memory.getPendingPort() >= 0;
		// Kept ashore now, or on shore leave: a golem waiting for its crossing gives up waiting. Left
		// pending, it stood at the plinth for good, each plan another pause for a boat that could not
		// come, and a pause counts as a route, so the watchdog never looked.
		if (waiting && (voyage == null || keptAshore || ambitionRestricted(context) || memory.onShoreLeave()))
		{
			memory.clearPending();
			waiting = false;
		}
		if (memory == null || voyage == null || keptAshore || ambitionRestricted(context) || memory.onShoreLeave()
			|| !waiting && random.nextFloat() >= chance)
		{
			return null;
		}

		SailingDocks.Dock dock = voyage.dockAt(from, DOCK_REACH);
		if (waiting && (dock == null || dock.getRowId() != memory.getPendingFrom()))
		{
			memory.clearPending();
			if (dock == null || random.nextFloat() >= chance)
			{
				return null;
			}
		}
		if (dock == null || !docks.isOpen(dock))
		{
			return null;
		}

		Itinerary crossing = voyage.depart(dock, from, memory, tick, random, context);
		if (crossing == null)
		{
			return null;
		}

		// Ashore at the far end, the golem walks inland a while before it may think about boats
		// again; otherwise a golem that arrives at a port simply leaves it again.
		memory.beginShoreLeaveOnArrival(tick + crossing.getDuration(), tick, random);
		return crossing;
	}

	/**
	 * Chance per plan that a golem heads for a transport rather than wandering. Finding one used to
	 * cap this by itself; now every transport in range is considered, and always taking one is hops.
	 */
	private static final float TRANSPORT_CHANCE = 0.5f;

	/** How a plan came out. */
	enum Outcome
	{
		VOYAGE,
		/** Walked toward a dock, to sail from it. */
		TO_DOCK,
		/** Took the only way off a tile that cannot be walked from. */
		ONWARD,
		TRANSPORT,
		WALK,
		NOTHING,
	}

	@lombok.Getter
	private Outcome lastOutcome = Outcome.NOTHING;

	/** Wander destinations the last plan found to be real ground in the golem's own space. */
	@lombok.Getter
	private int lastCandidates;

	/**
	 * The spaces a golem recently set off from, other than the one it stands in. Not straight back
	 * into one: at Castle Wars three portals from the lobby lead into two waiting rooms, and golems
	 * went lobby, room, lobby, room for good, each hop through a different portal, so no single
	 * cooldown caught it. By the space around a tile, since a journey often starts on its object,
	 * a tile no space holds, and asked by that tile alone it was never counted.
	 */
	Set<Integer> spacesLeft(int x, int y, int plane, int tick, TransportMemory memory)
	{
		if (memory == null)
		{
			return Collections.emptySet();
		}
		Set<Integer> left = new HashSet<>();
		List<Integer> here = mesh.spacesAt(x, y, plane);
		for (int[] origin : memory.recentOrigins(tick))
		{
			// Only a start in one space. One on an object set in a wall has a space on either side,
			// and the far one, never stood in, was barred with it.
			List<Integer> spaces = mesh.spacesAt(origin[0], origin[1], origin[2]);
			if (spaces.size() == 1 && !here.contains(spaces.get(0)))
			{
				left.add(spaces.get(0));
			}
		}
		return left;
	}

	/** True if this transport lands in one of these spaces. */
	boolean leadsInto(Set<Integer> spaces, GolemTransport transport)
	{
		if (spaces.isEmpty())
		{
			return false;
		}
		for (int space : mesh.spacesAt(transport.getToX(), transport.getToY(), transport.getToPlane()))
		{
			if (spaces.contains(space))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * A walk to a transport in range and the transport itself, or null. Every transport starting
	 * within reach is considered in a random order, which keeps the choice fair - except for a
	 * golem with a taste in places, which considers the ones that suit it first.
	 */
	private Itinerary toNearbyTransport(WorldPoint from, int tick, Random random, TransportMemory memory,
		Reach reach, boolean mayGoBack)
	{
		// A golem penned in may go back, since that is often the only way out. See spacesLeft.
		Set<Integer> cameFrom = mayGoBack ? Collections.emptySet()
			: spacesLeft(from.getX(), from.getY(), from.getPlane(), tick, memory);
		List<GolemTransport> near = new ArrayList<>();
		transports.near(from.getX(), from.getY(), TRANSPORT_SEARCH, near);
		Collections.shuffle(near, random);
		GolemClimate climate = reach.context == null ? null : reach.context.getClimates();
		if (climate != null && climate.cares(memory))
		{
			// Shortcuts and boats are how a golem covers real distance, so a golem that wants to be
			// somewhere in particular takes the one that gets it nearest. Shuffled first, so the
			// ones it has no opinion about - which is most of them - stay in a random order.
			near.sort((one, other) -> Float.compare(climate.liking(memory, other.getToX(), other.getToY()),
				climate.liking(memory, one.getToX(), one.getToY())));
		}

		int walksTried = 0;
		// The first one it passed over for being crowded, in case nothing roomier turns up.
		GolemTransport crowdedChoice = null;
		for (GolemTransport transport : near)
		{
			// Landing judged by the same test as everywhere else in the planner: this one alone asked
			// for the shipped land fill, so the cathedral's interior never counted as somewhere to be.
			if (transport.getFromPlane() != from.getPlane()
				|| (memory != null && memory.onCooldown(transport, tick))
				|| !mesh.sameComponent(from.getX(), from.getY(), transport.getFromX(), transport.getFromY(),
					from.getPlane())
				|| !abilities.canUse(transport)
				|| !landsSomewhereUseful(transport)
				|| leadsInto(cameFrom, transport))
			{
				continue;
			}
			// What the golem itself makes of this one: a taste in places, and a taste in obstacles.
			// Turned down here it is turned down for good - unlike a crowd, which a golem would
			// rather push through than stay put in.
			float wanted = reach.context == null ? 1f
				: reach.context.desire(memory, from.getX(), from.getY(), transport.getToX(), transport.getToY());
			if (memory != null)
			{
				wanted *= memory.tasteFor(transport);
			}
			if (wanted < 1f && random.nextFloat() >= wanted)
			{
				continue;
			}
			// Nowhere with no way back. After the rolls, which turn most down for less, and before the
			// crowded fallback is kept, which is taken without asking again.
			if (!mayEnter(transport, tick, reach.context))
			{
				continue;
			}
			// A dead end now and then, not as often as anywhere that leads on.
			float onward = wayOnAppeal(transport, tick, reach.context);
			if (onward < 1f && random.nextFloat() >= onward)
			{
				continue;
			}
			// Somewhere with room in it, by preference; see RoamContext.appeal. One that turns a
			// transport down falls back on the first it passed over rather than staying put.
			float appeal = reach.context == null ? 1f
				: reach.context.appeal(from.getX(), from.getY(), from.getPlane(),
					transport.getToX(), transport.getToY(), transport.getToPlane(), memory);
			if (appeal < 1f && random.nextFloat() >= appeal)
			{
				if (crowdedChoice == null)
				{
					crowdedChoice = transport;
				}
				continue;
			}
			List<int[]> path = walk(from, transport.getFromX(), transport.getFromY(), reach);
			if (path != null)
			{
				noteTaken(transport, tick + path.size() - 1, memory);
				return Itinerary.thenTransport(path, from.getPlane(), tick, transport);
			}
			// Past the first few, each try is a line and a lookup in the flood - cheap, but a town
			// can have a hundred rows in range.
			if (++walksTried >= ATTEMPTS * 4)
			{
				break;
			}
		}
		if (crowdedChoice != null)
		{
			List<int[]> path = walk(from, crowdedChoice.getFromX(), crowdedChoice.getFromY(), reach);
			if (path != null)
			{
				noteTaken(crowdedChoice, tick + path.size() - 1, memory);
				return Itinerary.thenTransport(path, from.getPlane(), tick, crowdedChoice);
			}
		}
		return null;
	}

	/**
	 * A straight run of tiles between two points, eight-directional. Deliberately not a search: at
	 * Tier 3 nothing observes the route, only where the golem ends up and roughly how long it took.
	 */
	private List<int[]> straightLine(int fromX, int fromY, int toX, int toY, int plane)
	{
		List<int[]> path = new ArrayList<>();
		int x = fromX;
		int y = fromY;
		path.add(new int[]{x, y});

		while (x != toX || y != toY)
		{
			int stepX = Integer.signum(toX - x);
			int stepY = Integer.signum(toY - y);

			// The step, not only the tile it lands on: two walkable tiles either side of a wall are
			// both fine ground, and a line checking tiles alone walked through the wall between them.
			if (!memory.canStep(x, y, plane, stepX, stepY))
			{
				return null;
			}
			x += stepX;
			y += stepY;

			// Every tile is checked, not just the destination, which left golems standing on water in
			// Wyrmscraig's caves. Harvested ground counts too, or golems upstairs went back down.
			if (!mesh.isLandWalkable(x, y, plane) && !memory.isKnownWalkable(x, y, plane))
			{
				return null;
			}

			path.add(new int[]{x, y});

			if (path.size() > 512)
			{
				// A leg this long means nonsense: most likely an underground coordinate against a
				// surface one.
				return null;
			}
		}
		return path;
	}

	/**
	 * The nearest tile a golem could actually stand on, spiralling outward.
	 *
	 * <p>Used when a golem is promoted into view, and when one is restored onto ground that has since
	 * changed. A golem is moved, never replaced - name, id and gait kept - since golems do not die.
	 *
	 * @return a safe tile, or the original if nothing better was found within range
	 */
	WorldPoint snapToMesh(WorldPoint at)
	{
		if (isSafe(at.getX(), at.getY(), at.getPlane()))
		{
			return at;
		}
		// Standing on water no golem can walk: the nearest ground, on whatever side of the shore.
		// Kept to the golem's own component, the search found only more water and left it there.
		if (mesh.isInlandWater(at.getX(), at.getY(), at.getPlane()))
		{
			WorldPoint shore = nearestSafe(at, false);
			return shore != null ? shore : at;
		}
		WorldPoint near = nearestSafe(at, true);
		return near != null ? near : at;
	}

	/**
	 * The nearest tile a golem can stand on, up to 32 tiles out, or null; {@code sameSpace} keeps it
	 * to the connected space the golem is in, as far as the mesh knows it.
	 */
	private WorldPoint nearestSafe(WorldPoint at, boolean sameSpace)
	{

		// Where the golem is now decides where it may be put: the nearest walkable tile to one in a
		// wall is often inside the building.
		// Off the shore of the cave's lake the golem's own space is the water, and keeping to it
		// would find nothing but more water; that call asks for any side of the shore.
		int origin = sameSpace ? mesh.componentAt(at.getX(), at.getY(), at.getPlane()) : 0;
		if (sameSpace && origin == 0)
		{
			// The mesh has nothing to say about the tile itself - it is in a wall, or off the
			// shipped map. Then the ground it was standing beside speaks for it, because a golem
			// being picked up belongs back where it came from. Without this the search was free to
			// take the nearest walkable tile in any direction for thirty-two tiles, which across a
			// channel is another island: golems turned up on shores no golem can walk to.
			origin = beside(at);
		}
		int reach = sameSpace && origin == 0 ? UNKNOWN_REACH : 32;

		for (int radius = 1; radius <= reach; radius++)
		{
			for (int dx = -radius; dx <= radius; dx++)
			{
				for (int dy = -radius; dy <= radius; dy++)
				{
					// Only the shell of the square, so each ring is tested once.
					if (Math.abs(dx) != radius && Math.abs(dy) != radius)
					{
						continue;
					}
					int x = at.getX() + dx;
					int y = at.getY() + dy;
					if (origin != 0)
					{
						int here = mesh.componentAt(x, y, at.getPlane());
						if (here != 0 && here != origin)
						{
							continue;
						}
					}
					if (isSafe(x, y, at.getPlane()))
					{
						return new WorldPoint(x, y, at.getPlane());
					}
				}
			}
		}
		return null;
	}

	/**
	 * How far a golem may be moved when nothing at all is known about where it is standing. A
	 * rescue is nearly always a tile or two; the long reach is for a golem in a wall, which has
	 * a component to be kept to.
	 */
	private static final int UNKNOWN_REACH = 4;

	/** The space the ground around this tile belongs to, or 0 if that ground says nothing either. */
	private int beside(WorldPoint at)
	{
		for (int dx = -1; dx <= 1; dx++)
		{
			for (int dy = -1; dy <= 1; dy++)
			{
				int space = mesh.componentAt(at.getX() + dx, at.getY() + dy, at.getPlane());
				if (space != 0)
				{
					return space;
				}
			}
		}
		return 0;
	}

	/**
	 * Walkable, and not in a pocket too small to wander out of. Ground the player has stood on
	 * counts whatever the shipped mesh says: the harvest is this client, this revision, this floor.
	 */
	private boolean isSafe(int x, int y, int plane)
	{
		if (memory.isKnownWalkable(x, y, plane))
		{
			return true;
		}
		return mesh.isLandWalkable(x, y, plane) && !mesh.isIsolated(x, y, plane);
	}
}

package com.golemsdontdie;

/**
 * Whether a learned route follows the obstacle it was learned from.
 *
 * <p>An obstacle moves the player along a fixed line: a stile from one of its tiles to the other.
 * A route is the two tiles a golem gets on and off at, travelled in a straight line, so off that
 * line is off the obstacle. That is how the stile came to be crossed diagonally - its ends came
 * from where the player happened to stand, eighteen degrees off. Such a route is refused when
 * learned and ignored if already saved.
 */
final class RouteGeometry
{
	/**
	 * How far off an obstacle's line a route may run. Both are whole tiles, so a real route is on
	 * the line or off by a whole tile's angle - the diagonal stile was eighteen - never between.
	 */
	static final double MAX_DEGREES_OFF = 10;

	/** Beyond this many tiles a traversal is a teleport (cave mouth, staircase) with no line. */
	static final int LOCAL_TILES = 8;

	private RouteGeometry()
	{
	}

	/** Tiles between two points as a golem walks them, a diagonal step counting as one. */
	static int span(int dx, int dy)
	{
		return Math.max(Math.abs(dx), Math.abs(dy));
	}

	/** True if a movement is short enough to have a line at all. */
	static boolean local(int dx, int dy)
	{
		return (dx != 0 || dy != 0) && Math.abs(dx) <= LOCAL_TILES && Math.abs(dy) <= LOCAL_TILES;
	}

	/**
	 * True if a route runs along a line, either direction. A line of (0, 0) is unknown and a
	 * non-local route has none, so both pass; only a short route beside a known line is refused.
	 */
	static boolean follows(int routeX, int routeY, int lineX, int lineY)
	{
		if (!local(lineX, lineY) || !local(routeX, routeY))
		{
			return true;
		}
		return degreesOff(routeX, routeY, lineX, lineY) <= MAX_DEGREES_OFF;
	}

	static double degreesOff(int routeX, int routeY, int lineX, int lineY)
	{
		double cos = Math.abs(routeX * lineX + routeY * lineY)
			/ (Math.hypot(routeX, routeY) * Math.hypot(lineX, lineY));
		return Math.toDegrees(Math.acos(Math.min(1, cos)));
	}

	/** A direction with length and sense removed: (0, 3), (0, -1) and (0, 2) are all (0, 1). */
	static int[] canonical(int dx, int dy)
	{
		int divisor = gcd(Math.abs(dx), Math.abs(dy));
		if (divisor == 0)
		{
			return new int[]{0, 0};
		}
		int x = dx / divisor;
		int y = dy / divisor;
		if (x < 0 || (x == 0 && y < 0))
		{
			x = -x;
			y = -y;
		}
		return new int[]{x, y};
	}

	private static int gcd(int a, int b)
	{
		return b == 0 ? a : gcd(b, a % b);
	}
}

package com.golemsdontdie;

import java.io.*;
import java.util.*;
import java.util.zip.*;
import javax.inject.*;
import lombok.*;
import lombok.extern.slf4j.*;
import net.runelite.api.*;
import net.runelite.api.coords.*;
import net.runelite.api.gameval.*;

/**
 * The game's own list of ports, read from its database at login.
 *
 * <p>Sailing ships a table of docks - sixty-odd, with a name, a level and sometimes a quest.
 * Reading it live means the plugin gains new ports when the game does.
 *
 * <p>Two things are defensive on purpose. The location sits in one of the table's unnamed
 * columns, so every column is probed and the one decoding to a plausible world coordinate wins.
 * And a dock's authored position is a marker, not necessarily a tile anything can float on - the
 * Summer Shore's is one fully blocked tile - so each dock is snapped onto open water at load.
 */
@Slf4j
@Singleton
class SailingDocks
{
	/** How far to look for open water around a dock's authored position. */
	private static final int SNAP_RADIUS = 24;

	@Inject
	private Client client;

	@Inject
	private WorldMesh mesh;

	@Getter
	private final List<Dock> docks = new ArrayList<>();

	private boolean loaded;

	/** One port: where it is, and what it takes to be allowed there. */
	@AllArgsConstructor
	static final class Dock
	{
		@Getter
		private final int rowId;
		@Getter
		private final String name;
		@Getter
		private final int levelRequired;
		@Getter
		private final int questId;

		/** Water beside the dock, snapped onto the mesh where there was any to snap to. */
		@Getter
		private final WorldPoint mooring;

		/**
		 * True if this dock sits on the one connected ocean. Not every dock does: Wyrmscraig has a
		 * second inside its caves, whose water is its own body. The flag decides how a voyage is
		 * expressed - an open-sea dock gets a drawn route, a cave dock a timed passage.
		 */
		@Getter
		private final boolean onOpenSea;

		/**
		 * The quayside: the land a golem stands on to board, and arrives on to leave. The gangplank is
		 * spawned with a vessel rather than built into the map, so there is no fixed plank tile to
		 * walk to. Boarding requires the golem to be here; arriving does not.
		 */
		@Getter
		private final WorldPoint shore;

		/**
		 * The open water nearest the gangplank: where a raft sets out from and comes in to. Not the
		 * buoy, which can sit well out in the harbour. Sea routes still run from the mooring.
		 */
		@Getter
		private final WorldPoint berth;

		Dock(int rowId, String name, int levelRequired, int questId, WorldPoint mooring,
			boolean onOpenSea, WorldPoint shore)
		{
			this(rowId, name, levelRequired, questId, mooring, onOpenSea, shore, mooring);
		}
	}

	/**
	 * True once the dock table has been asked for while logged in, read or not (a client older than
	 * Sailing has none). Until then no island reached only by sea joins up with home, and the
	 * cut-off sweep waits.
	 */
	@lombok.Getter
	private boolean tried;

	/** Reads the dock table, once, on the client thread. Safe to call repeatedly. */
	void load()
	{
		if (loaded)
		{
			return;
		}
		// Asked while logged in: whatever the answer, the ports are as known as they will be.
		tried |= client.getGameState() == GameState.LOGGED_IN;

		loadBuoys();

		List<Integer> rows;
		try
		{
			rows = client.getDBTableRows(DBTableID.SailingDock.ID);
		}
		catch (RuntimeException e)
		{
			// Absent on a client older than Sailing; golems then simply stay on land.
			log.debug("Sailing dock table unavailable", e);
			return;
		}

		if (rows == null || rows.isEmpty())
		{
			return;
		}
		loaded = true;

		for (int row : rows)
		{
			// Ask for the row's config before reading any of its fields: a row's data is fetched on
			// demand, and a field of a row the client has not pulled comes back empty rather than
			// failing, which reads exactly like a table with no columns in it.
			try
			{
				client.getDBRowConfig(row);
			}
			catch (RuntimeException e)
			{
				log.debug("Dock row {} would not load", row, e);
			}

			WorldPoint authored = findCoordinate(row);
			if (authored == null)
			{
				continue;
			}
			// A dock with no ocean nearby is kept at its authored position rather than dropped:
			// dropping it silently lost Wyrmscraig's cave dock, a port that simply is not on the sea.
			WorldPoint ocean = snapToWater(authored);
			WorldPoint mooring = ocean != null ? ocean : authored;

			WorldPoint shore = quayside(integer(row, DBTableID.SailingDock.COL_DOCK_ID, -1), authored, ocean != null);
			// On the sea, the sea nearest the gangplank. In a cave, the cave's own water beside it.
			WorldPoint berth = ocean != null ? snapToWater(shore) : snapToInlandWater(shore);
			docks.add(new Dock(row,
				string(row, DBTableID.SailingDock.COL_NICE_NAME),
				integer(row, DBTableID.SailingDock.COL_LEVEL_REQUIRED, 1),
				integer(row, DBTableID.SailingDock.COL_QUEST_REQUIRED, -1),
				mooring, ocean != null, shore, berth != null ? berth : mooring));
		}

		// A quayside on an island the land fill never reached is land from now on, or a golem that
		// sails there has nowhere to step off.
		for (Dock dock : docks)
		{
			// Every dock is a way out of the space it stands in, cave docks included: that is the
			// whole point of a port.
			WorldPoint shore = dock.getShore();
			mesh.admitDockExit(shore.getX(), shore.getY(), shore.getPlane());

			// Only docks on the sea: a cave dock stands on ground the fill knows, and admitting more
			// there admitted the cave's lake.
			if (!dock.isOnOpenSea())
			{
				continue;
			}
			mesh.admitDockFloor(shore.getX(), shore.getY(), shore.getPlane());
		}

		// Now the ports are known, which spaces join up with home can be settled: a dock is the
		// way in and out of every island that has one.
		mesh.linkSpaces(GolemContent.PLINTH_X, GolemContent.PLINTH_Y, 0);

		log.debug("Loaded {} sailing docks of {} rows; {} open to golems at Sailing level {}", docks.size(),
			rows.size(), openDocks().size(), client.getRealSkillLevel(Skill.SAILING));

		if (docks.isEmpty() && !rows.isEmpty() && !buoys.isEmpty())
		{
			// Every row rejected means the table's shape is not what this code expects, which is
			// worth saying loudly: silent no-sailing with a healthy row count takes an afternoon.
			// Not when the buoy table is missing, which has said so already and rejects every row.
			dumpTable(rows);
		}
	}

	/**
	 * Dumps what the dock table actually contains, when nothing could be read from it. The location
	 * is in an unnamed column and found by inspection, so if the packing ever changes this turns
	 * "no golems sail" into a five-line answer.
	 */
	private void dumpTable(List<Integer> rows)
	{
		log.warn("No sailing dock resolved a location. Dumping the first rows of table {}:",
			DBTableID.SailingDock.ID);

		for (int i = 0; i < Math.min(3, rows.size()); i++)
		{
			int row = rows.get(i);
			StringBuilder sb = new StringBuilder("  row ").append(row).append(':');

			try
			{
				sb.append(" config=").append(client.getDBRowConfig(row));
			}
			catch (RuntimeException e)
			{
				sb.append(" config threw ").append(e);
			}

			for (int column = 0; column < 24; column++)
			{
				Object[] values;
				try
				{
					values = client.getDBTableField(row, column, 0);
				}
				catch (RuntimeException e)
				{
					sb.append("\n    [").append(column).append("] threw ").append(e);
					continue;
				}
				if (values == null)
				{
					sb.append("\n    [").append(column).append("] null");
					continue;
				}
				if (values.length == 0)
				{
					sb.append("\n    [").append(column).append("] empty");
					continue;
				}
				sb.append("\n    [").append(column).append("] ");
				for (Object value : values)
				{
					sb.append(value == null ? "null" : value.getClass().getSimpleName()
						+ "=" + value).append(' ');
				}
			}
			log.warn(sb.toString());
		}
	}

	/**
	 * True if a golem is allowed to sail to this dock: the player's real Sailing level and the dock's
	 * quest, both applied. Never a boost - a port that opened only while boosted would strand golems.
	 */
	boolean isOpen(Dock dock)
	{
		if (client.getRealSkillLevel(Skill.SAILING) < dock.getLevelRequired())
		{
			return false;
		}
		if (dock.getQuestId() <= 0)
		{
			return true;
		}
		Quest quest = QUESTS_BY_ID.get(dock.getQuestId());
		return quest == null || questFinished(quest);
	}

	/** How long a quest's state is trusted. Asking runs a client script, once per dock considered. */
	private static final long QUEST_RECHECK_MILLIS = 5 * 60 * 1000L;

	/** Quest id to {finished ? 1 : 0, when it was asked}. */
	private final Map<Integer, long[]> questStates = new HashMap<>();

	private boolean questFinished(Quest quest)
	{
		long now = System.currentTimeMillis();
		long[] known = questStates.get(quest.getId());
		if (known == null || now - known[1] >= QUEST_RECHECK_MILLIS)
		{
			known = new long[]{quest.getState(client) == QuestState.FINISHED ? 1 : 0, now};
			questStates.put(quest.getId(), known);
		}
		return known[0] == 1;
	}

	/** Forgets every quest state, for a login that may be another account. */
	void forgetQuests()
	{
		questStates.clear();
	}

	/** Quests by id. Quest.values() copies the whole list each call, once per dock considered. */
	private static final Map<Integer, Quest> QUESTS_BY_ID = new HashMap<>();

	static
	{
		for (Quest quest : Quest.values())
		{
			QUESTS_BY_ID.putIfAbsent(quest.getId(), quest);
		}
	}

	/** Every dock currently open to a golem. */
	List<Dock> openDocks()
	{
		List<Dock> out = new ArrayList<>();
		for (Dock dock : docks)
		{
			if (isOpen(dock))
			{
				out.add(dock);
			}
		}
		return out;
	}

	// ---------------------------------------------------------------- reading

	/**
	 * Where a dock is, from the shipped table of docking buoys.
	 *
	 * <p>The dock table has no location in it - a dock's position is that of its <em>docking
	 * buoy</em>, a scene object with a {@code Dock} action, read offline from the cache. The
	 * link is {@link DBTableID.SailingDock#COL_DOCK_ID}, the index into that list in object-id
	 * order: Wyrmscraig's row reads dock id 59, the 60th buoy.
	 */
	private WorldPoint findCoordinate(int row)
	{
		int dockId = integer(row, DBTableID.SailingDock.COL_DOCK_ID, -1);
		if (dockId < 0 || dockId >= buoys.size())
		{
			return null;
		}
		return buoys.get(dockId);
	}

	/** Docking buoy positions, indexed by dock id. Read once from the jar. */
	private final List<WorldPoint> buoys = new ArrayList<>();

	/**
	 * Gangplank positions, indexed the same way; the buoy's own tile where none was found. The plank
	 * is where a person walks aboard, so it beats the nearest land to the buoy - across the water,
	 * or the wrong pier.
	 */
	private final List<WorldPoint> gangplanks = new ArrayList<>();

	/**
	 * Reads the shipped table: a count, then six shorts a dock - the buoy's tile then the
	 * gangplank's, each x, y and plane, in the order they were written. Reading
	 * {@code int, short, short, byte} put every dock at something like 0,3038 on plane 12.
	 */
	private void loadBuoys()
	{
		if (!buoys.isEmpty())
		{
			return;
		}

		try (InputStream raw = SailingDocks.class.getResourceAsStream(BUOYS))
		{
			if (raw == null)
			{
				log.warn("Docking buoy table missing from the jar; golems cannot sail");
				return;
			}
			try (GZIPInputStream gz = new GZIPInputStream(raw);
				 DataInputStream data = new DataInputStream(gz))
			{
				int count = data.readInt();
				for (int i = 0; i < count; i++)
				{
					int buoyX = data.readShort() & 0xFFFF;
					int buoyY = data.readShort() & 0xFFFF;
					int buoyPlane = data.readShort() & 0xFFFF;
					int plankX = data.readShort() & 0xFFFF;
					int plankY = data.readShort() & 0xFFFF;
					int plankPlane = data.readShort() & 0xFFFF;
					buoys.add(new WorldPoint(buoyX, buoyY, buoyPlane));
					gangplanks.add(new WorldPoint(plankX, plankY, plankPlane));
				}
				log.debug("Loaded {} docking buoys", buoys.size());
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Docking buoy table unreadable", e);
			buoys.clear();
			gangplanks.clear();
		}
	}

	/**
	 * Where a golem boards this dock: the gangplank if the harvest found one and a golem can stand on
	 * it, else the nearest land to the buoy. A plank equal to its buoy means none was found in range.
	 */
	private WorldPoint quayside(int dockId, WorldPoint buoy)
	{
		return quayside(dockId, buoy, true);
	}

	/**
	 * @param onOpenSea false for a dock on water that is not the sea - Wyrmscraig's cave, where
	 *                  every open tile near the buoy is the lake, passable but not ocean, so it was
	 *                  chosen as the quayside, admitted as floor, and golems walked on the water.
	 */
	private WorldPoint quayside(int dockId, WorldPoint buoy, boolean onOpenSea)
	{
		WorldPoint plank = dockId < gangplanks.size() ? gangplanks.get(dockId) : null;
		if (plank != null && !plank.equals(buoy)
			&& mesh.isLandWalkable(plank.getX(), plank.getY(), plank.getPlane()))
		{
			return plank;
		}
		return snapToShore(buoy, onOpenSea);
	}

	private static final String BUOYS = "/docks.gz";

	/**
	 * The nearest land a golem could stand on, spiralling out from the buoy, which sits on water.
	 * Falls back to the buoy, leaving the port usable by sea where the mesh has nothing ashore.
	 */
	private WorldPoint snapToShore(WorldPoint at)
	{
		return snapToShore(at, true);
	}

	/**
	 * @param piers false to take only ground the land fill reached. See quayside.
	 *
	 * <p>A pier is taken only if it is more than a pocket, by the same measure as land. Five docks
	 * had a pocket of two to thirteen tiles nearer the buoy than the shore it is walled off from (the
	 * end of a jetty, a nook behind a crate), and golems stepping ashore there were shut in. A pocket
	 * is the last resort, where nothing larger is in reach.
	 */
	private WorldPoint snapToShore(WorldPoint at, boolean piers)
	{
		WorldPoint pocket = null;
		for (int radius = 0; radius <= SNAP_RADIUS; radius++)
		{
			WorldPoint pier = null;
			for (int dx = -radius; dx <= radius; dx++)
			{
				for (int dy = -radius; dy <= radius; dy++)
				{
					if (radius > 0 && Math.abs(dx) != radius && Math.abs(dy) != radius)
					{
						continue;
					}
					int x = at.getX() + dx;
					int y = at.getY() + dy;
					if (mesh.isLandWalkable(x, y, at.getPlane())
						&& !mesh.isIsolated(x, y, at.getPlane()))
					{
						return new WorldPoint(x, y, at.getPlane());
					}
					// Ground the land fill never reached is still ground: most of Sailing's
					// islands are like that. Taken only if nothing the fill knows is as close.
					if (piers && pier == null && mesh.isWalkable(x, y, at.getPlane())
						&& !mesh.isOcean(x, y, at.getPlane()) && mesh.componentAt(x, y, at.getPlane()) != 0)
					{
						if (!mesh.isIsolated(x, y, at.getPlane()))
						{
							pier = new WorldPoint(x, y, at.getPlane());
						}
						else if (pocket == null)
						{
							pocket = new WorldPoint(x, y, at.getPlane());
						}
					}
				}
			}
			if (pier != null)
			{
				return pier;
			}
		}
		return pocket != null ? pocket : at;
	}

	/**
	 * The nearest water that is not the sea: open in the map, not land the fill reached, part of some
	 * connected space. Around the cave dock that is its lake.
	 */
	private WorldPoint snapToInlandWater(WorldPoint at)
	{
		for (int radius = 1; radius <= SNAP_RADIUS; radius++)
		{
			for (int dx = -radius; dx <= radius; dx++)
			{
				for (int dy = -radius; dy <= radius; dy++)
				{
					if (Math.abs(dx) != radius && Math.abs(dy) != radius)
					{
						continue;
					}
					int x = at.getX() + dx;
					int y = at.getY() + dy;
					if (mesh.isWalkable(x, y, at.getPlane()) && !mesh.isOcean(x, y, at.getPlane())
						&& !mesh.isLandWalkable(x, y, at.getPlane()) && mesh.componentAt(x, y, at.getPlane()) != 0)
					{
						return new WorldPoint(x, y, at.getPlane());
					}
				}
			}
		}
		return null;
	}

	/** The nearest tile of the connected ocean, spiralling outward. */
	private WorldPoint snapToWater(WorldPoint at)
	{
		if (mesh.isOcean(at.getX(), at.getY(), at.getPlane()))
		{
			return at;
		}
		for (int radius = 1; radius <= SNAP_RADIUS; radius++)
		{
			for (int dx = -radius; dx <= radius; dx++)
			{
				for (int dy = -radius; dy <= radius; dy++)
				{
					if (Math.abs(dx) != radius && Math.abs(dy) != radius)
					{
						continue;
					}
					int x = at.getX() + dx;
					int y = at.getY() + dy;
					if (mesh.isOcean(x, y, 0))
					{
						return new WorldPoint(x, y, 0);
					}
				}
			}
		}
		return null;
	}

	private String string(int row, int column)
	{
		try
		{
			Object[] values = client.getDBTableField(row, column, 0);
			return values != null && values.length > 0 && values[0] != null
				? String.valueOf(values[0]) : "";
		}
		catch (RuntimeException e)
		{
			return "";
		}
	}

	private int integer(int row, int column, int fallback)
	{
		try
		{
			Object[] values = client.getDBTableField(row, column, 0);
			return values != null && values.length > 0 && values[0] instanceof Integer
				? (Integer) values[0] : fallback;
		}
		catch (RuntimeException e)
		{
			return fallback;
		}
	}
}

package com.golemsdontdie;

import java.io.*;
import java.util.*;
import java.util.zip.*;
import javax.inject.*;
import lombok.*;
import lombok.extern.slf4j.*;
import net.runelite.api.coords.*;
import static com.golemsdontdie.RouteGeometry.span;

/**
 * Routes a raft across the ocean.
 *
 * <p>The collision map already marks open water as passable and shoreline edges as blocked,
 * which is why Wyrmscraig reads as a sealed 2,456-tile island <em>and</em> why 2,458,003 tiles
 * of connected sea sit in the same resource: golems path the ocean with the same flags and corner
 * rule they use in a corridor. Three differences, all because an ocean is enormous: A*, since
 * three thousand nodes does not cross one; an inflated heuristic, which expands far fewer nodes
 * and gives straighter routes; and straightening afterwards, sailing moving in long runs.
 */
@Slf4j
@Singleton
class SeaMesh
{
	/** Ceiling on tiles expanded for one crossing. Large: a crossing is planned once per pair. */
	private static final int NODE_BUDGET = 200_000;

	/** Heuristic inflation. Above 1 it is fast and straight, not optimal; a weaving boat reads badly. */
	private static final float HEURISTIC_WEIGHT = 1.4f;

	private static final int[] DX = {0, 0, 1, -1, 1, -1, 1, -1};
	private static final int[] DY = {1, -1, 0, 0, 1, 1, -1, -1};

	@Inject
	private WorldMesh mesh;

	/**
	 * True if two points sit on the same body of water. Always ask before pathing: the inland body
	 * on Karamja is 26,000 tiles connecting to nothing, and a search between basins burns the budget.
	 */
	boolean sameWater(WorldPoint a, WorldPoint b)
	{
		return mesh.isOcean(a.getX(), a.getY(), 0) && mesh.isOcean(b.getX(), b.getY(), 0);
	}

	/**
	 * Routes already computed, keyed by the pair of endpoints.
	 *
	 * <p>What makes the search affordable at all: there are only sixty-odd ports, so a real session
	 * sees a handful of crossings. Failures are cached too, as an empty list.
	 */
	private final Map<Long, List<int[]>> routes = new HashMap<>();

	/**
	 * Crossings between every pair of moorings, computed offline and shipped. The live search could
	 * not be
	 * relied on: sampling forty pairs of ports it found no route for twenty-one - the ocean being
	 * one body of water, every one was the budget running out, at a quarter to two fifths of a
	 * second each on the client thread. It remains for a pair the table does not have.
	 */
	private static final String SHIPPED = "/sea-routes.gz";

	private boolean shippedLoaded;

	private void loadShipped()
	{
		if (shippedLoaded)
		{
			return;
		}
		shippedLoaded = true;
		try (InputStream raw = SeaMesh.class.getResourceAsStream(SHIPPED))
		{
			if (raw == null)
			{
				log.warn("Shipped sea routes missing from the jar; crossings will be searched live");
				return;
			}
			try (GZIPInputStream gz = new GZIPInputStream(raw);
				 DataInputStream data = new DataInputStream(gz))
			{
				int count = data.readInt();
				for (int i = 0; i < count; i++)
				{
					int legs = data.readShort() & 0xFFFF;
					List<int[]> route = new ArrayList<>(legs);
					for (int j = 0; j < legs; j++)
					{
						route.add(new int[]{data.readShort() & 0xFFFF, data.readShort() & 0xFFFF});
					}
					int[] first = route.get(0);
					int[] last = route.get(route.size() - 1);
					routes.put(key(first[0], first[1], last[0], last[1]), route);
					List<int[]> back = new ArrayList<>(route);
					Collections.reverse(back);
					routes.put(key(last[0], last[1], first[0], first[1]), back);
				}
				log.debug("Loaded {} shipped sea routes", count);
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Shipped sea routes unreadable; crossings will be searched live", e);
		}
	}

	/** True if this pair has already been searched, successfully or not. */
	boolean isSearched(WorldPoint from, WorldPoint to)
	{
		loadShipped();
		return routes.containsKey(key(from, to));
	}

	/**
	 * A route between two moorings, as straightened legs. Cached, so this is expensive exactly once
	 * per pair of ports; every call after the first is a map lookup.
	 *
	 * @return waypoints including both ends, or null
	 */
	List<int[]> route(WorldPoint from, WorldPoint to)
	{
		loadShipped();
		long key = key(from, to);
		List<int[]> cached = routes.get(key);
		if (cached != null)
		{
			return cached.isEmpty() ? null : cached;
		}

		if (!sameWater(from, to))
		{
			routes.put(key, Collections.emptyList());
			return null;
		}

		Map<Long, Long> cameFrom = new HashMap<>();
		Map<Long, Integer> best = new HashMap<>();
		PriorityQueue<long[]> open = new PriorityQueue<>((p, q) -> Integer.compare(
			(int) p[1], (int) q[1]));

		long start = pack(from.getX(), from.getY());
		long goal = pack(to.getX(), to.getY());
		best.put(start, 0);
		open.add(new long[]{start, heuristic(from.getX(), from.getY(), to.getX(), to.getY())});

		int expanded = 0;
		boolean found = false;

		while (!open.isEmpty() && expanded < NODE_BUDGET)
		{
			long[] current = open.poll();
			long at = current[0];
			if (at == goal)
			{
				found = true;
				break;
			}
			expanded++;

			int cx = unpackX(at);
			int cy = unpackY(at);
			int cost = best.getOrDefault(at, Integer.MAX_VALUE);

			for (int d = 0; d < 8; d++)
			{
				int nx = cx + DX[d];
				int ny = cy + DY[d];
				if (!mesh.isOcean(nx, ny, 0) || !canStep(cx, cy, DX[d], DY[d]))
				{
					continue;
				}

				long next = pack(nx, ny);
				int tentative = cost + 1;
				if (tentative >= best.getOrDefault(next, Integer.MAX_VALUE))
				{
					continue;
				}
				best.put(next, tentative);
				cameFrom.put(next, at);
				open.add(new long[]{next,
					tentative + heuristic(nx, ny, to.getX(), to.getY())});
			}
		}

		if (!found)
		{
			log.debug("No sea route from {} to {} after {} nodes", from, to, expanded);
			routes.put(key, Collections.emptyList());
			return null;
		}

		List<int[]> path = new ArrayList<>();
		for (long at = goal; at != start; at = cameFrom.get(at))
		{
			path.add(0, new int[]{unpackX(at), unpackY(at)});
		}
		path.add(0, new int[]{from.getX(), from.getY()});

		List<int[]> straightened = straighten(path);
		routes.put(key, straightened);
		return straightened;
	}

	/**
	 * Collapses runs of tiles into legs. The tile path is only interesting where it turns; keeping
	 * every tile would mean the same motion at many times the storage.
	 */
	private static List<int[]> straighten(List<int[]> path)
	{
		if (path.size() < 3)
		{
			return path;
		}
		List<int[]> out = new ArrayList<>();
		out.add(path.get(0));

		int dx = Integer.signum(path.get(1)[0] - path.get(0)[0]);
		int dy = Integer.signum(path.get(1)[1] - path.get(0)[1]);

		for (int i = 1; i < path.size(); i++)
		{
			int ndx = Integer.signum(path.get(i)[0] - path.get(i - 1)[0]);
			int ndy = Integer.signum(path.get(i)[1] - path.get(i - 1)[1]);
			if (ndx != dx || ndy != dy)
			{
				out.add(path.get(i - 1));
				dx = ndx;
				dy = ndy;
			}
		}
		out.add(path.get(path.size() - 1));
		return out;
	}

	/** Octile distance, weighted. Admissible before the weight, deliberately not after. */
	private static int heuristic(int x, int y, int goalX, int goalY)
	{
		int dx = Math.abs(x - goalX);
		int dy = Math.abs(y - goalY);
		return (int) (Math.max(dx, dy) * HEURISTIC_WEIGHT);
	}

	/** Which tiles a raft may sail on: the ocean, or one enclosed body of water. */
	interface Water
	{
		boolean at(int x, int y);
	}

	/** The one connected sea. */
	final Water ocean = (x, y) -> mesh.isOcean(x, y, 0);

	/** Water that is not the sea, by component: a cave lake, passable and marked as nothing else. */
	Water lake(int component)
	{
		return (x, y) -> component != 0 && mesh.componentAt(x, y, 0) == component;
	}

	/** Which connected component a surface tile belongs to, 0 for none. */
	int componentAt(int x, int y)
	{
		return mesh.componentAt(x, y, 0);
	}

	@AllArgsConstructor
	static final class Field
	{
		private final TileMap distance;
		private final SeaMesh sea;
		private final Water water;

		/** True if a raft sailing this field may be on this tile. */
		boolean isWater(int x, int y)
		{
			return water.at(x, y);
		}

		/** Steps to the destination from this tile, or -1 if it is not in the field. */
		int distance(int x, int y)
		{
			return (int) distance.getOrDefault(pack(x, y), -1);
		}

		/** A neighbour one step nearer the destination, or null at the destination itself. */
		int[] downhill(int x, int y)
		{
			int here = distance(x, y);
			for (int d = 0; d < 8; d++)
			{
				int nx = x + DX[d];
				int ny = y + DY[d];
				int there = distance(nx, ny);
				if (there >= 0 && there < here && canStep(water, x, y, DX[d], DY[d]))
				{
					return new int[]{nx, ny};
				}
			}
			return null;
		}

		int size()
		{
			return distance.size();
		}
	}

	/** True if this tile of the surface is open sea. */
	boolean isWater(int x, int y)
	{
		return mesh.isOcean(x, y, 0);
	}

	/** The distance field to the last point of a route, over open water within {@code band} tiles of the route. */
	/**
	 * Distance to a destination by sea, for every tile of open water near a route to it. Travel
	 * distance, not straight-line: filled outward from the destination round every headland, so from
	 * any tile some neighbour is one step nearer. Only within {@code band} tiles of the route.
	 */
	Field fieldAlong(List<int[]> route, int band)
	{
		return fieldAlong(route, band, 0, 0);
	}

	/**
	 * As {@link #fieldAlong(List, int)}, over water with room around it. A raft is three tiles long
	 * and a tile wide, and a course plotted for the golem at its helm ran it through gaps its bow
	 * could not fit; {@code openNearEnds} tiles of either end are exempt, for coming in to a dock.
	 */
	Field fieldAlong(List<int[]> route, int band, int clearance, int openNearEnds)
	{
		return fieldAlong(route, band, clearance, openNearEnds, ocean);
	}

	/** As {@link #fieldAlong(List, int, int, int)}, over a given body of water. */
	Field fieldAlong(List<int[]> route, int band, int clearance, int openNearEnds, Water water)
	{
		int[] start = route.get(0);
		int[] goal = route.get(route.size() - 1);
		// Breadth first, and every tile is queued exactly when its distance is recorded, so the
		// record's own order is the queue.
		TileMap distance = new TileMap(1 << 14);
		distance.add(pack(goal[0], goal[1]), 0);
		// Water refused for itself: too far from the route, or too near a shore. Both are questions
		// about the tile alone, and each of its neighbours offers it again, so the answer is kept.
		TileMap tooFar = new TileMap(1 << 12);
		int head = 0;
		while (head < distance.size())
		{
			long at = distance.keyAt(head++);
			int x = (int) (at >> 32);
			int y = (int) at;
			long steps = distance.get(at);
			for (int d = 0; d < 8; d++)
			{
				int nx = x + DX[d];
				int ny = y + DY[d];
				long key = pack(nx, ny);
				if (distance.containsKey(key) || !water.at(nx, ny) || !canStep(water, x, y, DX[d], DY[d])
					|| tooFar.containsKey(key))
				{
					continue;
				}
				if (!near(route, nx, ny, band) || !roomy(water, nx, ny, clearance, start, goal, openNearEnds))
				{
					tooFar.add(key, 0);
					continue;
				}
				distance.add(key, steps + 1);
			}
		}
		return new Field(distance, this, water);
	}

	/** True if a tile has open sea for {@code clearance} tiles all round, or is near enough an end not to need it. */
	private static boolean roomy(Water water, int x, int y, int clearance, int[] start, int[] goal, int openNearEnds)
	{
		if (clearance <= 0
			|| span(x - start[0], y - start[1]) <= openNearEnds
			|| span(x - goal[0], y - goal[1]) <= openNearEnds)
		{
			return true;
		}
		for (int dx = -clearance; dx <= clearance; dx++)
		{
			for (int dy = -clearance; dy <= clearance; dy++)
			{
				if (!water.at(x + dx, y + dy))
				{
					return false;
				}
			}
		}
		return true;
	}

	/** True if a tile is within {@code band} tiles of any leg of a route. */
	private static boolean near(List<int[]> route, int x, int y, int band)
	{
		for (int i = 0; i + 1 < route.size(); i++)
		{
			int[] a = route.get(i);
			int[] b = route.get(i + 1);
			double dx = b[0] - a[0];
			double dy = b[1] - a[1];
			double lengthSquared = dx * dx + dy * dy;
			double t = lengthSquared == 0 ? 0 : Math.max(0, Math.min(1, ((x - a[0]) * dx + (y - a[1]) * dy) / lengthSquared));
			if (Math.hypot(x - (a[0] + dx * t), y - (a[1] + dy * t)) <= band)
			{
				return true;
			}
		}
		return route.size() == 1 && span(x - route.get(0)[0], y - route.get(0)[1]) <= band;
	}

	/** The game's corner rule, restricted to water. */
	boolean canStep(int x, int y, int dx, int dy)
	{
		return canStep(ocean, x, y, dx, dy);
	}

	static boolean canStep(Water water, int x, int y, int dx, int dy)
	{
		if (dx == 0 || dy == 0)
		{
			return true;
		}
		// A diagonal needs both ways round to be water, or the raft would cut a headland.
		return water.at(x + dx, y) && water.at(x, y + dy);
	}

	/** Endpoint pair key. Direction matters: a route is reversed, not reused. */
	private static long key(WorldPoint from, WorldPoint to)
	{
		return key(from.getX(), from.getY(), to.getX(), to.getY());
	}

	private static long key(int fromX, int fromY, int toX, int toY)
	{
		return ((long) fromX << 45) ^ ((long) fromY << 30) ^ ((long) toX << 15) ^ toY;
	}

	private static long pack(int x, int y)
	{
		return ((long) x << 32) | (y & 0xFFFFFFFFL);
	}

	private static int unpackX(long packed)
	{
		return (int) (packed >> 32);
	}

	private static int unpackY(long packed)
	{
		return (int) packed;
	}
}

package com.golemsdontdie;

import java.util.*;

/**
 * Packed tiles mapped to packed tiles, without boxing, remembering insertion order.
 *
 * <p>The searches ask constantly whether a tile has been reached and from where; as a
 * {@code HashMap<Long, Long>} each question boxed a key and each tile reached made a key, a
 * value and an entry.
 *
 * <p>Insertion order is kept because the flood's order is part of its answer: the far half of
 * what it reached is where a golem is sent, drawn by index.
 */
final class TileMap
{
	/** Marks an empty slot; a real key equal to it is held apart, so any long is valid. */
	private static final long EMPTY = Long.MIN_VALUE;

	private long[] keys;
	private long[] values;
	private int mask;

	/** Keys in the order added, which is also a search's queue. */
	private long[] order;
	private int size;

	private boolean hasEmptyKey;
	private long emptyKeyValue;

	TileMap(int expected)
	{
		int capacity = Integer.highestOneBit(Math.max(4, expected) * 2 - 1) * 2;
		keys = new long[capacity];
		values = new long[capacity];
		Arrays.fill(keys, EMPTY);
		mask = capacity - 1;
		order = new long[Math.max(4, expected)];
	}

	int size()
	{
		return size;
	}

	/** The key added {@code index}th, counting from zero. */
	long keyAt(int index)
	{
		return order[index];
	}

	boolean containsKey(long key)
	{
		if (key == EMPTY)
		{
			return hasEmptyKey;
		}
		for (int slot = slot(key); ; slot = (slot + 1) & mask)
		{
			long at = keys[slot];
			if (at == key)
			{
				return true;
			}
			if (at == EMPTY)
			{
				return false;
			}
		}
	}

	/** The value for a key, or {@code missing} if absent. */
	long getOrDefault(long key, long missing)
	{
		if (key == EMPTY)
		{
			return hasEmptyKey ? emptyKeyValue : missing;
		}
		for (int slot = slot(key); ; slot = (slot + 1) & mask)
		{
			long at = keys[slot];
			if (at == key)
			{
				return values[slot];
			}
			if (at == EMPTY)
			{
				return missing;
			}
		}
	}

	/** The value for a key the map holds; throws if it does not. */
	long get(long key)
	{
		if (key == EMPTY)
		{
			if (!hasEmptyKey)
			{
				throw new IllegalStateException("no such tile");
			}
			return emptyKeyValue;
		}
		for (int slot = slot(key); ; slot = (slot + 1) & mask)
		{
			long at = keys[slot];
			if (at == key)
			{
				return values[slot];
			}
			if (at == EMPTY)
			{
				throw new IllegalStateException("no such tile");
			}
		}
	}

	/** Adds a key the map does not hold yet; the searches only ever add a tile once. */
	void add(long key, long value)
	{
		if (size == order.length)
		{
			order = Arrays.copyOf(order, size * 2);
		}
		order[size++] = key;
		if (key == EMPTY)
		{
			hasEmptyKey = true;
			emptyKeyValue = value;
			return;
		}
		if (size * 2 > keys.length)
		{
			grow();
		}
		insert(key, value);
	}

	/**
	 * Adds to a key's value, from zero for a key the map does not hold yet.
	 *
	 * @return the value after adding
	 */
	long addTo(long key, long delta)
	{
		if (key == EMPTY)
		{
			if (!hasEmptyKey)
			{
				add(key, delta);
				return delta;
			}
			return emptyKeyValue += delta;
		}
		for (int slot = slot(key); ; slot = (slot + 1) & mask)
		{
			long at = keys[slot];
			if (at == key)
			{
				return values[slot] += delta;
			}
			if (at == EMPTY)
			{
				add(key, delta);
				return delta;
			}
		}
	}

	/** Empties the map, keeping its capacity. */
	void clear()
	{
		if (size == 0)
		{
			return;
		}
		Arrays.fill(keys, EMPTY);
		size = 0;
		hasEmptyKey = false;
	}

	private void insert(long key, long value)
	{
		int slot = slot(key);
		while (keys[slot] != EMPTY)
		{
			slot = (slot + 1) & mask;
		}
		keys[slot] = key;
		values[slot] = value;
	}

	private void grow()
	{
		long[] oldKeys = keys;
		long[] oldValues = values;
		keys = new long[oldKeys.length * 2];
		values = new long[oldKeys.length * 2];
		Arrays.fill(keys, EMPTY);
		mask = keys.length - 1;
		for (int i = 0; i < oldKeys.length; i++)
		{
			if (oldKeys[i] != EMPTY)
			{
				insert(oldKeys[i], oldValues[i]);
			}
		}
	}

	private int slot(long key)
	{
		long h = key * 0x9E3779B97F4A7C15L;
		return (int) (h ^ (h >>> 32)) & mask;
	}
}

package com.golemsdontdie;

import java.util.*;
import java.util.function.*;
import lombok.*;
import static com.golemsdontdie.RouteGeometry.span;

/**
 * What one golem has used recently, so it does not pace back and forth through a door.
 *
 * <p>Per golem, not global - two golems meeting at the same ladder should both be able to take
 * it. Transport cooldowns are not saved: they stop a golem visibly oscillating over the next
 * minute or two, and after a logout there is none left to interrupt. Shore leave is the exception
 * on both counts, saved and in real time, because a golem restored at a port it has just landed
 * at should not sail straight back out.
 *
 * <p>Endpoints, not row numbers: two rows can go the same way - the rockslide had a shipped row
 * and a learned route with identical ends under different object ids - and learned rows are
 * renumbered whenever what was learned changes. Going back the way it came is about tiles.
 */
final class TransportMemory
{
	/** How many recent journeys to remember. Small: this stops shuffling in a doorway, no more. */
	private static final int HISTORY = 8;

	/** Ticks a used transport, and its reverse, stay barred. Roughly two minutes. */
	static final int COOLDOWN_TICKS = 200;

	/** Least time ashore before a golem may sail again: three minutes, saved with the golem. */
	private static final long SHORE_LEAVE_MILLIS = 3 * 60_000L;

	/** Up to this much more, at random, so a boatload of golems landing together does not all leave together. */
	private static final long SHORE_LEAVE_SPREAD_MILLIS = 2 * 60_000L;

	private static final long MILLIS_PER_TICK = 600;

	/** The clock shore leave is measured on: real time, because it is saved with the golem. */
	static LongSupplier clock = System::currentTimeMillis;

	/** Ring of recently travelled endpoint pairs, and when each expires. */
	private final long[] recent = new long[HISTORY];
	private final int[] expiry = new int[HISTORY];
	private int next;

	/**
	 * Ring of recently used obstacles: {objectId, fromX, fromY, toX, toY, plane}, with expiry.
	 * Endpoints alone were not enough: over a broken cart one way was 2879,2950 to 2876,2952 and
	 * back was 2876,2952 to 2880,2952, so the way back was never barred.
	 */
	private final int[][] usedObstacles = new int[HISTORY][];
	private final int[] usedObstacleExpiry = new int[HISTORY];
	private int nextObstacle;

	/** How near a used obstacle's ends another use of the same object has to start to count as it. */
	private static final int SAME_OBSTACLE_TILES = 2;

	/**
	 * The longest move, in tiles, that counts as crossing one obstacle, and so barred by object and
	 * place. A glider or fairy ring is one object id with a dozen destinations from one spot, and
	 * barring the object stranded golems at a glider platform a thousand times.
	 */
	private static final int OBSTACLE_REACH = 8;

	private static boolean isCrossing(int fromX, int fromY, int toX, int toY)
	{
		return span(toX - fromX, toY - fromY) <= OBSTACLE_REACH;
	}

	/** The port this golem last sailed from, or -1: reachable again from the next, so it tours. */
	@Getter
	@Setter
	private int blockedPort = -1;

	/**
	 * The port this golem has decided to sail to and is waiting at a dock for, or -1. The distance
	 * field for a port not sailed to lately is built in the background, and deciding afresh each
	 * time meant golems walked to the end of the dock and away again.
	 */
	@Getter
	private int pendingPort = -1;

	/** The dock the golem is waiting at for {@link #pendingPort}, or -1. */
	@Getter
	private int pendingFrom = -1;

	/** The last tick it waits there. */
	@Getter
	private int pendingUntil;

	/** How long a golem waits at a dock for a crossing being worked out: about twenty seconds. */
	static final int PENDING_WAIT_TICKS = 32;

	/** Waits at this dock for a crossing to that port, from now if it was not already. */
	void holdPending(int fromDock, int port, int tick)
	{
		if (pendingPort != port || pendingFrom != fromDock)
		{
			pendingPort = port;
			pendingFrom = fromDock;
			pendingUntil = tick + PENDING_WAIT_TICKS;
		}
	}

	void clearPending()
	{
		pendingPort = -1;
		pendingFrom = -1;
	}

	/** When this golem may next sail, on {@link #clock}; 0 if it may now. Saved with the golem. */
	@Getter
	@Setter
	private long shoreLeaveUntil;

	/** Records a use, barring both this journey and the one that undoes it, which is the same. */
	void used(GolemTransport transport, int tick)
	{
		used(transport, tick, COOLDOWN_TICKS);
	}

	/**
	 * What the golem this belongs to is like, as a mask of {@link GolemTrait}.
	 *
	 * <p>Kept here because this is the one piece of a golem the planner is handed: it plans for a
	 * golem it cannot see, and a golem's habits belong to that planning as much as its cooldowns do.
	 */
	@Getter
	@Setter
	private int traits;

	boolean is(GolemTrait trait)
	{
		return trait.in(traits);
	}

	/**
	 * How much this golem likes the look of a shortcut, as a multiplier on the chance of taking it.
	 *
	 * <p>A cautious golem will not risk a jump or a stone; a sure-footed one goes out of its way for
	 * one. A climber prefers anything leading up and a spelunker anything leading down, which is what
	 * sends one to the rooftops and the other into the caves.
	 */
	float tasteFor(GolemTransport transport)
	{
		if (traits == 0)
		{
			return 1f;
		}
		boolean risky = transport.getArchetype() == GolemTransport.ARCHETYPE_JUMP
			|| transport.getArchetype() == GolemTransport.ARCHETYPE_BALANCE
			|| transport.getArchetype() == GolemTransport.ARCHETYPE_TIGHTROPE;
		if (risky && is(GolemTrait.CAUTIOUS))
		{
			return 0f;
		}

		float taste = is(GolemTrait.SURE_FOOTED) ? 1.6f : 1f;
		int rise = transport.getFromPlane() - transport.getToPlane();
		// Down is off the surface map, into a cave or somewhere below it; up is back onto it.
		boolean down = rise > 0
			|| WorldLayout.isSurface(transport.getFromY()) && !WorldLayout.isSurface(transport.getToY());
		boolean up = rise < 0
			|| !WorldLayout.isSurface(transport.getFromY()) && WorldLayout.isSurface(transport.getToY());
		if (down && is(GolemTrait.SPELUNKER) || up && is(GolemTrait.CLIMBER))
		{
			taste *= 2.5f;
		}
		if (up && is(GolemTrait.SPELUNKER) || down && is(GolemTrait.CLIMBER))
		{
			taste *= 0.4f;
		}
		return taste;
	}


	/**
	 * How long a golem walks after using a shortcut before it looks for another. Three minutes.
	 *
	 * <p>Not a cooldown on the shortcut but on the habit: Meiyerditch gave a golem a shortcut in
	 * reach on every decision, and a year of roaming left a third of all golems there. Stepping off
	 * somewhere it cannot walk is exempt.
	 */
	static final int TRANSPORT_REST_TICKS = 300;

	private int restUntil = Integer.MIN_VALUE;

	/** True if the golem has used a shortcut lately and is walking for a while. */
	boolean restingFromTransports(int tick)
	{
		if (is(GolemTrait.RESTLESS))
		{
			// Off again almost as soon as it lands. In longs: before its first shortcut the rest is
			// Integer.MIN_VALUE, and taking half a rest off that wrapped round to the largest int,
			// so a restless golem rested until it had used a shortcut, which it then seldom did.
			return tick < (long) restUntil - TRANSPORT_REST_TICKS / 2;
		}
		return tick < restUntil;
	}

	/**
	 * As {@link #used(GolemTransport, int)}, barred for a given number of ticks. Shorter where the
	 * far side is small: two minutes is sensible before a town, very long in a sheep pen.
	 */
	void used(GolemTransport transport, int tick, int cooldownTicks)
	{
		restUntil = tick + TRANSPORT_REST_TICKS;
		note(transport, tick, cooldownTicks);
	}

	/**
	 * A door walked through standing open: remembered as a use, so the golem is not turned straight
	 * back through it, but no rest from shortcuts after it. It was a step like any other.
	 */
	void walkedThrough(GolemTransport transport, int tick)
	{
		note(transport, tick, COOLDOWN_TICKS);
	}

	private void note(GolemTransport transport, int tick, int cooldownTicks)
	{
		remember(transport.endpointKey(), tick, cooldownTicks);
		remember(transport.reverseKey(), tick, cooldownTicks);
		journeys[nextJourney] = new int[]{transport.getFromX(), transport.getFromY(), transport.getFromPlane(),
			transport.getToX(), transport.getToY(), transport.getToPlane()};
		journeyExpiry[nextJourney] = tick + cooldownTicks;
		nextJourney = (nextJourney + 1) % HISTORY;
		if (transport.getFromPlane() == transport.getToPlane()
			&& isCrossing(transport.getFromX(), transport.getFromY(), transport.getToX(), transport.getToY()))
		{
			usedObstacles[nextObstacle] = new int[]{transport.getObjectId(), transport.getFromX(), transport.getFromY(),
				transport.getToX(), transport.getToY(), transport.getFromPlane()};
			usedObstacleExpiry[nextObstacle] = tick + cooldownTicks;
			nextObstacle = (nextObstacle + 1) % HISTORY;
		}
	}

	/**
	 * Recent journeys by their ends, {fromX, fromY, fromPlane, toX, toY, toPlane}, to recognise a way
	 * back that is not the exact reverse: down into a cave and back up are often two objects whose
	 * ends are a tile apart, and golems went down and up every few seconds.
	 */
	private final int[][] journeys = new int[HISTORY][];
	private final int[] journeyExpiry = new int[HISTORY];
	private int nextJourney;

	/**
	 * Where the golem set off from on each journey still remembered, {x, y, plane}: the planner, which
	 * knows the ground, keeps golems from going straight back into the space they just left.
	 */
	List<int[]> recentOrigins(int tick)
	{
		List<int[]> out = new ArrayList<>(HISTORY);
		for (int i = 0; i < HISTORY; i++)
		{
			int[] j = journeys[i];
			if (j != null && journeyExpiry[i] > tick)
			{
				out.add(new int[]{j[0], j[1], j[2]});
			}
		}
		return out;
	}

	/** True if this transport undoes a recent journey: starts where it ended and ends where it started. */
	private boolean undoesRecentJourney(GolemTransport transport, int tick)
	{
		for (int i = 0; i < HISTORY; i++)
		{
			int[] j = journeys[i];
			if (j != null && journeyExpiry[i] > tick
				&& transport.getFromPlane() == j[5] && transport.getToPlane() == j[2]
				&& near(transport.getFromX(), transport.getFromY(), j[3], j[4])
				&& near(transport.getToX(), transport.getToY(), j[0], j[1]))
			{
				return true;
			}
		}
		return false;
	}

	private void remember(long key, int tick, int cooldownTicks)
	{
		recent[next] = key;
		expiry[next] = tick + cooldownTicks;
		next = (next + 1) % HISTORY;
	}

	boolean onCooldown(GolemTransport transport, int tick)
	{
		long key = transport.endpointKey();
		for (int i = 0; i < HISTORY; i++)
		{
			// An empty slot has expiry 0, which has always passed.
			if (recent[i] == key && expiry[i] > tick)
			{
				return true;
			}
		}
		// A way back that is not the exact reverse. Short hops on one floor go to the rule below.
		if ((transport.getFromPlane() != transport.getToPlane()
			|| !isCrossing(transport.getFromX(), transport.getFromY(), transport.getToX(), transport.getToY()))
			&& undoesRecentJourney(transport, tick))
		{
			return true;
		}

		// The same obstacle, at or beside either end of a recent use: over the cart and back again.
		for (int i = 0; i < HISTORY; i++)
		{
			int[] used = usedObstacles[i];
			if (used == null || usedObstacleExpiry[i] <= tick || used[0] != transport.getObjectId()
				|| used[5] != transport.getFromPlane() || transport.getToPlane() != transport.getFromPlane()
				|| !isCrossing(transport.getFromX(), transport.getFromY(), transport.getToX(), transport.getToY()))
			{
				continue;
			}
			if (near(transport.getFromX(), transport.getFromY(), used[1], used[2])
				|| near(transport.getFromX(), transport.getFromY(), used[3], used[4]))
			{
				// Not the next stone of a crossing: a hop carrying on the same way is the same obstacle.
				int lastX = used[3] - used[1];
				int lastY = used[4] - used[2];
				int nextX = transport.getToX() - transport.getFromX();
				int nextY = transport.getToY() - transport.getFromY();
				if (lastX * nextX + lastY * nextY > 0)
				{
					continue;
				}
				return true;
			}
		}
		return false;
	}

	private static boolean near(int x, int y, int otherX, int otherY)
	{
		return span(x - otherX, y - otherY) <= SAME_OBSTACLE_TILES;
	}

	/**
	 * Bars sea travel for a while after the golem steps off a boat. Takes the tick the golem
	 * <em>arrives</em>, not the tick it sets out: a crossing is planned up front, so shore leave
	 * would otherwise be spent at sea.
	 */
	void beginShoreLeaveOnArrival(int arrivalTick, int nowTick, Random random)
	{
		long arrival = clock.getAsLong() + Math.max(0, arrivalTick - nowTick) * MILLIS_PER_TICK;
		long spread = random == null ? 0 : (long) (random.nextDouble() * SHORE_LEAVE_SPREAD_MILLIS);
		shoreLeaveUntil = arrival + SHORE_LEAVE_MILLIS + spread;
	}

	/**
	 * Takes back the shore leave a crossing booked. Shore leave is set when a voyage is planned
	 * rather than when it ends, so a golem whose crossing is given up - held at the quayside to
	 * wait for a crew - would sit out the leave for a voyage it never made, and by the time that
	 * ran out the crew would be long gone.
	 */
	void clearShoreLeave()
	{
		shoreLeaveUntil = 0;
	}

	boolean onShoreLeave()
	{
		return clock.getAsLong() < shoreLeaveUntil;
	}
}

package com.golemsdontdie;

import java.io.*;
import java.util.*;
import java.util.function.*;
import java.util.zip.*;
import javax.inject.*;
import lombok.extern.slf4j.*;
import net.runelite.api.*;
import static com.golemsdontdie.RouteGeometry.span;

/**
 * Every transport a golem could use, indexed by the tile you use it from.
 *
 * <p>Loaded once from {@code /transports.gz}, generated offline from Shortest Path's tables;
 * shipping it means golems can use a ladder the player
 * has never stood next to, as with the island map. Indexed by origin tile, the only question
 * asked of it.
 */
@Slf4j
@Singleton
class TransportNetwork
{
	private static final String RESOURCE = "/transports.gz";

	/** Operators in a varbit or varp condition, as encoded by the builder. */
	static final int OP_EQ = 0;
	static final int OP_GT = 1;
	static final int OP_AND = 2;
	static final int OP_AT = 3;
	static final int OP_LT = 4;

	/**
	 * A clause that could not be read. Never satisfied: a requirement the plugin does not
	 * understand is still a requirement, and dropping it made 506 gated rows free.
	 */
	static final int OP_UNKNOWN = 5;

	/** A quest the plugin has no entry for, kept so the row stays gated. */
	static final int QUEST_UNKNOWN = -2;

	/**
	 * Quest names as the tables spell them where RuneLite spells them otherwise. Shortest Path
	 * writes "Shadows of the Storm"; the quest is Shadow of the Storm.
	 */
	private static final Map<String, String> QUEST_ALIASES = Collections.singletonMap(
		"shadows of the storm", "shadow of the storm");

	private static final int[] NONE = new int[0];

	private final List<GolemTransport> transports = new ArrayList<>();

	/** Origin tile (x, y packed) to the transports starting there. Immutable once built. */
	private final Map<Long, List<GolemTransport>> byOrigin = new HashMap<>();

	/** Quest display name to enum, built once - the tables name quests as players do. */
	private static Map<String, Quest> questsByName;

	/** Marks the versioned table; must match BuildTransports. */
	private static final int MAGIC = -0x7472;

	/** 2 added a flags byte per row. */
	private static final int VERSION = 2;

	/** The row is an inference, locked until golems have seen it used. */
	private static final int FLAG_LEARN_FIRST = 1;

	/** Which way a climb goes, from its verb: up, or down. Neither set, the plane change says. */
	private static final int FLAG_UP = 2;
	private static final int FLAG_DOWN = 4;

	/**
	 * Reads the bundled table. A missing or corrupt resource is deliberately not fatal: golems
	 * fall back to walking rather than the plugin refusing to load.
	 */
	void load()
	{
		if (!transports.isEmpty())
		{
			return;
		}

		try (InputStream raw = TransportNetwork.class.getResourceAsStream(RESOURCE))
		{
			if (raw == null)
			{
				log.warn("Bundled transport table missing from the jar");
				return;
			}

			try (GZIPInputStream gz = new GZIPInputStream(raw);
				 DataInputStream data = new DataInputStream(gz))
			{
				// The versioned format opens with a marker no row count can be; the first one
				// opened with the count and had no flags.
				int first = data.readInt();
				boolean flagged = first == MAGIC;
				if (flagged && data.readInt() != VERSION)
				{
					log.warn("Bundled transport table is a newer format than this build reads");
					return;
				}
				int count = flagged ? data.readInt() : first;
				for (int i = 0; i < count; i++)
				{
					GolemTransport t = new GolemTransport(
						data.readShort() & 0xFFFF, data.readShort() & 0xFFFF, data.readByte(),
						data.readShort() & 0xFFFF, data.readShort() & 0xFFFF, data.readByte(),
						data.readShort() & 0xFFFF, data.readByte(), data.readInt(),
						parseSkills(data.readUTF()),
						parseQuests(data.readUTF()),
						parseConditions(data.readUTF()),
						parseConditions(data.readUTF()));
					if (flagged)
					{
						int flags = data.readByte();
						t.setLearnFirst((flags & FLAG_LEARN_FIRST) != 0);
						t.setDirection((flags & FLAG_UP) != 0 ? 1 : (flags & FLAG_DOWN) != 0 ? -1 : 0);
					}
					transports.add(t);
				}
			}

			index();
			shippedCount = transports.size();
			for (GolemTransport t : transports)
			{
				shippedByEndpoints.putIfAbsent(t.endpointKey(), t);
				if (t.getObjectId() > 0)
				{
					shippedObjects.add(t.getObjectId());
					if (t.getArchetype() == GolemTransport.ARCHETYPE_DOOR)
					{
						doorObjects.add(t.getObjectId());
					}
				}
			}
			link();
			log.debug("Loaded {} transports across {} origin tiles",
				transports.size(), byOrigin.size());
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Bundled transport table unreadable", e);
			transports.clear();
			byOrigin.clear();
		}
	}

	/**
	 * Transports usable from exactly this tile. Never null, never a copy: golems scan the tiles
	 * around them on every step, which near a town would be hundreds of lists a second. The lists
	 * are immutable and shared.
	 */
	List<GolemTransport> from(int x, int y)
	{
		List<GolemTransport> found = byOrigin.get(pack(x, y));
		return found == null ? Collections.emptyList() : found;
	}

	/**
	 * Adds routes the player has demonstrated, replacing any added before; they are kept apart
	 * only so re-learning replaces rather than accumulates. Archetype is {@code NONE} on purpose:
	 * what the golem plays comes from {@link ObstacleKnowledge} by object id.
	 */
	void setLearnedRoutes(java.util.List<int[]> routes)
	{
		if (!learned.isEmpty())
		{
			// Learned rows are always the tail, numbered from shippedCount. removeAll searched the
			// learned list for each of thirteen thousand rows, on every obstacle the player used.
			transports.subList(shippedCount, transports.size()).clear();
			learned.clear();
		}

		suppressed.clear();
		// One row per journey. Two saved routes can drift onto the same ends as they are merged.
		Set<Long> journeys = new HashSet<>();
		for (int[] r : routes)
		{
			if (!journeys.add(endpoints(r[1], r[2], r[3], r[4], r[5], r[6])))
			{
				continue;
			}
			// A learned route going exactly where a shipped row goes replaces it: two rows for one
			// journey can carry different object ids, as on the rockslide. What was watched is the
			// better authority on the object, the table on the journey's requirements.
			GolemTransport twin = shippedByEndpoints.get(
				endpoints(r[1], r[2], r[3], r[4], r[5], r[6]));
			GolemTransport route;
			if (twin == null)
			{
				// The observed duration, not a placeholder: a learned row claiming one tick
				// undercut the shipped row it was meant to improve on.
				route = new GolemTransport(r[1], r[2], r[3], r[4], r[5], r[6],
					r.length > 7 ? r[7] : 1, GolemTransport.ARCHETYPE_NONE, r[0],
					NO_REQUIREMENT, NO_REQUIREMENT, NO_REQUIREMENT, NO_REQUIREMENT);
			}
			else
			{
				route = new GolemTransport(r[1], r[2], r[3], r[4], r[5], r[6],
					r.length > 7 ? r[7] : 1,
					twin.getObjectId() == r[0] ? twin.getArchetype() : GolemTransport.ARCHETYPE_NONE,
					r[0], twin.skills(), twin.quests(), twin.varbits(), twin.varps());
				// And its way up or down, from the verb: without it a dungeon ladder, which changes no
				// floor, was told apart by the floor and played the wrong way.
				route.setDirection(twin.getDirection());
				suppressed.add(twin);
			}
			route.setInstanceFlags(r.length > 8 ? r[8] : 0);
			learned.add(route);
		}
		transports.addAll(learned);

		// Learned rows are numbered above the shipped ones. Nothing reads the number for cooldowns
		// any more - those are kept by a transport's two ends, which survive a rebuild - but it
		// still tells a learned row from a shipped one in a log.
		for (int i = 0; i < learned.size(); i++)
		{
			learned.get(i).setIndex(shippedCount + i);
		}

		byOrigin.clear();
		for (GolemTransport t : transports)
		{
			if (suppressed.contains(t))
			{
				continue;
			}
			byOrigin.computeIfAbsent(pack(t.getFromX(), t.getFromY()),
				k -> new ArrayList<>()).add(t);
		}
		byOrigin.replaceAll((k, v) -> Collections.unmodifiableList(v));
		indexChunks();

		// Learned rows need their reverse resolved like any other, or a golem has nothing to
		// put on cooldown coming back.
		link();

		log.debug("Transport network: {} rows including {} learned", transports.size(),
			learned.size());
	}

	/** How many rows shipped, fixed at load: the boundary between fixed and movable indices. */
	private int shippedCount;

	private final List<GolemTransport> learned = new ArrayList<>();

	/** The first shipped row for each pair of endpoints, for spotting a learned duplicate. */
	private final Map<Long, GolemTransport> shippedByEndpoints = new HashMap<>();

	/** Shipped rows a learned route has replaced. Kept in the table, never offered. */
	private final Set<GolemTransport> suppressed =
		Collections.newSetFromMap(new IdentityHashMap<>());

	private static final int[] NO_REQUIREMENT = new int[0];

	/**
	 * True if the shipped tables have a row for this object. Shipped rows only: counting learned
	 * rows too, a tree that slipped through once passed the obstacle test for good.
	 */
	boolean isShippedObstacle(int objectId)
	{
		return shippedObjects.contains(objectId);
	}

	private final Set<Integer> shippedObjects = new HashSet<>();

	/**
	 * True if a shipped row calls this object a door. A golem goes through a door its own way, so
	 * nothing the player is seen doing with one is learned. See ObstacleKnowledge.isUnlocked.
	 */
	boolean isDoorObject(int objectId)
	{
		return doorObjects.contains(objectId);
	}

	private final Set<Integer> doorObjects = new HashSet<>();

	/**
	 * Every transport, for callers that sweep the whole table. Immutable and shared, like
	 * {@link #from}: sweeping thirteen thousand rows beats the tile-by-tile lookup, which costs
	 * the square of the radius, from about sixty tiles out.
	 */
	List<GolemTransport> all()
	{
		return Collections.unmodifiableList(transports);
	}

	/** True unless a learned route has replaced this row; suppressed rows stay in {@link #all}. */
	boolean isOffered(GolemTransport transport)
	{
		return !suppressed.contains(transport);
	}

	/** How far a hop from a stepping stone can go, in tiles. */
	private static final int STONE_HOP = 4;

	/**
	 * True if a short hop on the same floor starts on this tile: a stepping stone or the like,
	 * which a golem leaves by the next hop rather than by stepping off.
	 */
	boolean isStone(int x, int y, int plane)
	{
		for (GolemTransport t : from(x, y))
		{
			if (t.getFromPlane() == plane && t.getToPlane() == plane
				&& span(t.getToX() - x, t.getToY() - y) <= STONE_HOP)
			{
				return true;
			}
		}
		return false;
	}

	/** True if any transport starts on this tile - the cheap test, and the common one. */
	boolean hasOrigin(int x, int y)
	{
		return byOrigin.containsKey(pack(x, y));
	}

	GolemTransport get(int index)
	{
		return index < 0 || index >= transports.size() ? null : transports.get(index);
	}

	int size()
	{
		return transports.size();
	}

	/** Goes up whenever the table changes, so anything built from it knows to build again. */
	private int revision;

	int revision()
	{
		return revision;
	}

	// ------------------------------------------------------------------ indexing

	private void index()
	{
		for (int i = 0; i < transports.size(); i++)
		{
			GolemTransport t = transports.get(i);
			t.setIndex(i);
			byOrigin.computeIfAbsent(pack(t.getFromX(), t.getFromY()),
				k -> new ArrayList<>()).add(t);
		}

		// Made immutable once built: these lists are handed straight out to every golem that
		// walks past.
		byOrigin.replaceAll((k, v) -> Collections.unmodifiableList(v));
		indexChunks();
	}

	/**
	 * Wyrmscraig and everywhere its own transports lead: the regions a golem stays in when its
	 * ambition is restricted.
	 *
	 * <p>The island's regions, then - repeatedly, until nothing new turns up - the region every
	 * transport starting in the area lands in, which picks up caves and the floors above ladders
	 * without a list. The region either side of each landing is allowed too, a floor rarely
	 * fitting one region, but does not seed further transports, which leaks along coasts.
	 */
	Set<Integer> homeRegions()
	{
		Set<Integer> seeds = new HashSet<>();
		for (int region : GolemContent.ISLAND_REGIONS)
		{
			seeds.add(region);
		}
		boolean grew = true;
		while (grew)
		{
			grew = false;
			for (GolemTransport t : transports)
			{
				if (!suppressed.contains(t) && t.getToX() < 6400
					&& seeds.contains(regionOf(t.getFromX(), t.getFromY()))
					&& seeds.add(regionOf(t.getToX(), t.getToY())))
				{
					grew = true;
				}
			}
		}
		// Not around the island itself: its nine regions cover it, and a margin reached the next
		// island's dock.
		Set<Integer> home = new HashSet<>(seeds);
		for (int region : seeds)
		{
			if (Arrays.stream(GolemContent.ISLAND_REGIONS).anyMatch(r -> r == region))
			{
				continue;
			}
			for (int dx = -1; dx <= 1; dx++)
			{
				for (int dy = -1; dy <= 1; dy++)
				{
					home.add((((region >> 8) + dx) << 8) | ((region & 0xFF) + dy));
				}
			}
		}
		return home;
	}

	/** Hops a chain of transports is followed looking for somewhere to stand. */
	static final int CHAIN_HOPS = 6;

	/** Where a golem may stand, as whoever is asking judges it. */
	interface Ground
	{
		boolean walkable(int x, int y, int plane);
	}

	/**
	 * True if a golem on this tile, having arrived from {@code came}, can reach walkable ground by
	 * transports without going straight back. Followed for several hops, because a crossing is a
	 * chain: looking one hop ahead passed on every stone of a crossing where none led to a bank.
	 */
	boolean leadsToGround(int x, int y, int plane, int cameX, int cameY, int camePlane, int hops,
		Predicate<GolemTransport> usable, Ground ground)
	{
		if (ground.walkable(x, y, plane))
		{
			return true;
		}
		if (hops <= 0)
		{
			return false;
		}
		for (GolemTransport onward : from(x, y))
		{
			if (onward.getFromPlane() != plane || !usable.test(onward)
				|| (onward.getToX() == cameX && onward.getToY() == cameY && onward.getToPlane() == camePlane))
			{
				continue;
			}
			if (leadsToGround(onward.getToX(), onward.getToY(), onward.getToPlane(), x, y, plane, hops - 1,
				usable, ground))
			{
				return true;
			}
		}
		return false;
	}

	/** Chunks are 16 tiles square: a 48-tile search is a seven-by-seven block of them. */
	private static final int CHUNK_SHIFT = 4;

	/** Origin chunk to the offered transports starting in it. */
	private final Map<Long, List<GolemTransport>> byChunk = new HashMap<>();

	private void indexChunks()
	{
		byChunk.clear();
		for (List<GolemTransport> here : byOrigin.values())
		{
			for (GolemTransport t : here)
			{
				byChunk.computeIfAbsent(pack(t.getFromX() >> CHUNK_SHIFT, t.getFromY() >> CHUNK_SHIFT),
					k -> new ArrayList<>()).add(t);
			}
		}
	}

	/**
	 * Adds every offered transport starting within {@code radius} tiles of a tile, on any plane.
	 * The planner used to probe random tiles for an origin: two dozen probes in nine thousand
	 * tiles find a town's cluster but almost never the one ladder at the end of a corridor.
	 */
	void near(int x, int y, int radius, List<GolemTransport> out)
	{
		for (int cx = (x - radius) >> CHUNK_SHIFT; cx <= (x + radius) >> CHUNK_SHIFT; cx++)
		{
			for (int cy = (y - radius) >> CHUNK_SHIFT; cy <= (y + radius) >> CHUNK_SHIFT; cy++)
			{
				List<GolemTransport> chunk = byChunk.get(pack(cx, cy));
				if (chunk == null)
				{
					continue;
				}
				for (GolemTransport t : chunk)
				{
					if (Math.abs(t.getFromX() - x) <= radius && Math.abs(t.getFromY() - y) <= radius)
					{
						out.add(t);
					}
				}
			}
		}
	}

	/**
	 * Pairs each transport with the one that undoes it: two-way connections are authored as two
	 * rows, so a row's reverse is the one with its endpoints swapped. Turns §11's
	 * no-immediate-reversal rule into an integer comparison.
	 */
	private void link()
	{
		revision++;
		rebuildReachedRegions();

		Map<Long, Integer> byEndpoints = new HashMap<>();
		for (GolemTransport t : transports)
		{
			if (!suppressed.contains(t))
			{
				byEndpoints.put(t.endpointKey(), t.getIndex());
			}
		}

		int linked = 0;
		for (GolemTransport t : transports)
		{
			Integer other = byEndpoints.get(endpoints(t.getToX(), t.getToY(), t.getToPlane(),
				t.getFromX(), t.getFromY(), t.getFromPlane()));
			if (other != null)
			{
				t.setReverse(other);
				linked++;
			}
		}
		log.debug("{} of {} transports have a reverse", linked, transports.size());
	}

	// ----------------------------------------------------------------- parsing

	/** {@code "25 Magic;30 Agility"} to pairs of (level, skill ordinal). */
	private static int[] parseSkills(String spec)
	{
		if (spec.isEmpty())
		{
			return NONE;
		}
		List<Integer> out = new ArrayList<>();
		for (String clause : spec.split(";"))
		{
			String[] parts = clause.trim().split("\\s+", 2);
			if (parts.length != 2)
			{
				continue;
			}
			try
			{
				int level = Integer.parseInt(parts[0]);
				Skill skill = Skill.valueOf(parts[1].trim().toUpperCase());
				out.add(level);
				out.add(skill.ordinal());
			}
			catch (IllegalArgumentException e)
			{
				// A skill this client does not know. Dropping the clause makes the transport easier,
				// never harder, the safe direction here.
				log.debug("Unknown skill requirement: {}", clause);
			}
		}
		return toArray(out);
	}

	/** {@code "Plague City;Song of the Elves"} to quest ordinals. */
	private static int[] parseQuests(String spec)
	{
		if (spec.isEmpty())
		{
			return NONE;
		}
		if (questsByName == null)
		{
			questsByName = new HashMap<>();
			for (Quest quest : Quest.values())
			{
				questsByName.put(quest.getName().toLowerCase(), quest);
			}
		}

		List<Integer> out = new ArrayList<>();
		for (String name : spec.split(";"))
		{
			String key = name.trim().toLowerCase();
			if (key.isEmpty())
			{
				continue;
			}
			Quest quest = questsByName.get(QUEST_ALIASES.getOrDefault(key, key));
			if (quest == null)
			{
				log.debug("Unknown quest requirement: {}", name);
				out.add(QUEST_UNKNOWN);
				continue;
			}
			out.add(quest.ordinal());
		}
		return toArray(out);
	}

	/**
	 * {@code "4070=0;10032>0;4560&2"} to triples of (id, operator, value). The {@code @} form is a
	 * real-time countdown in wall-clock minutes; a golem has nothing to count down, so those
	 * clauses are kept and never satisfied - see {@link GolemAbilities}.
	 */
	private static int[] parseConditions(String spec)
	{
		if (spec.isEmpty())
		{
			return NONE;
		}
		List<Integer> out = new ArrayList<>();
		for (String clause : spec.split(";"))
		{
			String c = clause.trim();
			if (c.isEmpty())
			{
				continue;
			}
			int op;
			int at = -1;
			if ((at = c.indexOf('>')) >= 0)
			{
				op = OP_GT;
			}
			else if ((at = c.indexOf('<')) >= 0)
			{
				op = OP_LT;
			}
			else if ((at = c.indexOf('&')) >= 0)
			{
				op = OP_AND;
			}
			else if ((at = c.indexOf('@')) >= 0)
			{
				op = OP_AT;
			}
			else if ((at = c.indexOf('=')) >= 0)
			{
				op = OP_EQ;
			}
			else
			{
				log.debug("Unparseable condition: {}", clause);
				out.add(-1);
				out.add(OP_UNKNOWN);
				out.add(0);
				continue;
			}

			try
			{
				int id = Integer.parseInt(c.substring(0, at).trim());
				int value = Integer.parseInt(c.substring(at + 1).trim());
				out.add(id);
				out.add(op);
				out.add(value);
			}
			catch (NumberFormatException e)
			{
				log.debug("Unparseable condition: {}", clause);
				out.add(-1);
				out.add(OP_UNKNOWN);
				out.add(0);
			}
		}
		return toArray(out);
	}

	private static int[] toArray(List<Integer> values)
	{
		if (values.isEmpty())
		{
			return NONE;
		}
		int[] out = new int[values.size()];
		for (int i = 0; i < out.length; i++)
		{
			out[i] = values.get(i);
		}
		return out;
	}

	/** Regions the island's transports and learned routes lead into, with the regions around
	 * each, since an arrival rarely stays in the region it lands in. */
	private final Set<Integer> reachedRegions = new HashSet<>();

	/** True if golems can get into this region by transport, so its ground is worth mapping. */
	boolean leadsToRegion(int regionId)
	{
		return reachedRegions.contains(regionId);
	}

	private void rebuildReachedRegions()
	{
		reachedRegions.clear();
		Set<Integer> island = new HashSet<>();
		for (int region : GolemContent.ISLAND_REGIONS)
		{
			island.add(region);
		}
		for (GolemTransport t : transports)
		{
			if (suppressed.contains(t))
			{
				continue;
			}
			if (!island.contains(regionOf(t.getFromX(), t.getFromY())) && t.getIndex() < shippedCount)
			{
				continue;
			}
			int rx = t.getToX() >> 6;
			int ry = t.getToY() >> 6;
			for (int dx = -1; dx <= 1; dx++)
			{
				for (int dy = -1; dy <= 1; dy++)
				{
					reachedRegions.add((rx + dx) << 8 | (ry + dy));
				}
			}
		}
	}

	private static int regionOf(int x, int y)
	{
		return (x >> 6) << 8 | (y >> 6);
	}

	private static long pack(int x, int y)
	{
		return ((long) x << 32) | (y & 0xFFFFFFFFL);
	}

	static long endpoints(int fx, int fy, int fz, int tx, int ty, int tz)
	{
		// 15 bits per coordinate and 2 per plane fits a world tile pair in a long.
		return ((long) (fx & 0x7FFF) << 49) | ((long) (fy & 0x7FFF) << 34)
			| ((long) (fz & 3) << 32) | ((long) (tx & 0x7FFF) << 17)
			| ((long) (ty & 0x7FFF) << 2) | (tz & 3);
	}
}

package com.golemsdontdie;

import java.util.*;
import java.util.concurrent.*;
import javax.inject.*;
import lombok.extern.slf4j.*;
import net.runelite.api.coords.*;
import static com.golemsdontdie.RouteGeometry.span;

/**
 * Decides where a golem sails, and plans the crossing.
 *
 * <p>Two rules, both chosen because they need no tuning. <b>Uniform dispersal:</b> the
 * destination is drawn evenly from every port the golem may reach, since weighting by distance
 * compounds - a golem near Catherby draws Catherby's neighbours forever. <b>One blocked port:</b>
 * a golem may not sail straight back where it came from, one field of state rather than a timer,
 * leaving home reachable again from the third hop. Wyrmscraig's population thins over a long
 * session as a result, but the island refills with every craft.
 */
@Slf4j
@Singleton
class Voyage
{
	@Inject
	private SailingDocks docks;

	@Inject
	private SeaMesh sea;

	/**
	 * Present in the client, null in the offline tools, which build fields in line. Only a marker:
	 * fields are built on {@link #builder}, a queue of sea searches here having delayed config
	 * saves.
	 */
	@Inject
	private ScheduledExecutorService executor;

	/** How many field builds may wait for the builder; beyond it a golem asks later. */
	private static final int BUILD_QUEUE = 8;

	/** One low-priority daemon thread of its own, made on first use; see {@link #shutDown}. */
	private ThreadPoolExecutor builder;

	private synchronized ThreadPoolExecutor builder()
	{
		if (builder == null)
		{
			builder = new ThreadPoolExecutor(1, 1, 30, TimeUnit.SECONDS,
				new ArrayBlockingQueue<>(BUILD_QUEUE), task ->
				{
					Thread thread = new Thread(task, "golems-sea-fields");
					thread.setDaemon(true);
					thread.setPriority(Thread.MIN_PRIORITY);
					return thread;
				});
			builder.allowCoreThreadTimeOut(true);
		}
		return builder;
	}

	/**
	 * Stops the builder and forgets every field, when the plugin stops.
	 *
	 * <p>Queued builds are dropped and the thread is left to finish the one in hand, which takes a
	 * fraction of a second and touches nothing but the mesh. It is a daemon thread and times out
	 * when idle, so nothing holds the client open.
	 */
	synchronized void shutDown()
	{
		if (builder != null)
		{
			builder.getQueue().clear();
			builder.shutdown();
			builder = null;
		}
		building.clear();
		synchronized (fields)
		{
			fields.clear();
			cachedTiles = 0;
		}
	}

	/**
	 * Plans a crossing from a dock, or returns null if the golem should stay ashore.
	 *
	 * @param from   the dock the golem is leaving
	 * @param memory the golem's own memory, consulted for the blocked port and the port it is waiting on
	 */
	Itinerary depart(SailingDocks.Dock from, WorldPoint at, TransportMemory memory, int tick, Random random,
		RoamContext context)
	{
		List<SailingDocks.Dock> open = docks.openDocks();
		if (open.size() < 2)
		{
			return null;
		}

		// Candidates: anywhere open, except here and except where we just came from.
		List<SailingDocks.Dock> candidates = new ArrayList<>(open);
		candidates.removeIf(d -> d.getRowId() == from.getRowId()
			|| d.getRowId() == memory.getBlockedPort());

		if (candidates.isEmpty())
		{
			// Deliberately not relaxed: if the only place left is where we came from, the golem
			// roams locally rather than bouncing between two docks.
			return null;
		}

		// The port it already chose, if still waiting at this dock to sail there; waited long
		// enough, it gives up.
		SailingDocks.Dock chosen = null;
		if (memory.getPendingPort() >= 0 && memory.getPendingFrom() != from.getRowId())
		{
			memory.clearPending();
		}
		if (memory.getPendingPort() >= 0 && tick > memory.getPendingUntil())
		{
			memory.clearPending();
			return null;
		}
		for (SailingDocks.Dock candidate : candidates)
		{
			if (candidate.getRowId() == memory.getPendingPort())
			{
				chosen = candidate;
			}
		}
		if (chosen == null)
		{
			// A few tries for a port with room ashore and weather to suit, then wherever the last
			// roll lands. Ports are how a golem crosses the world, so this is where a taste for the
			// cold or the heat takes it somewhere it could never have walked - and a golem with one
			// reads the whole board rather than sampling it, three ports out of ninety being no way
			// to find the one port in the snow.
			GolemClimate climate = context == null ? null : context.getClimates();
			boolean picky = climate != null && climate.cares(memory);
			if (picky)
			{
				candidates.sort((one, other) -> Float.compare(liking(climate, memory, other),
					liking(climate, memory, one)));
			}
			for (int attempt = 0; attempt < 3 && chosen == null; attempt++)
			{
				SailingDocks.Dock candidate = picky ? candidates.get(Math.min(attempt, candidates.size() - 1))
					: candidates.get(random.nextInt(candidates.size()));
				WorldPoint shore = candidate.getShore();
				float appeal = context == null || shore == null ? 1f
					: context.roominess(shore.getX(), shore.getY(), shore.getPlane(), memory)
					* (climate == null ? 1f : climate.liking(memory, shore.getX(), shore.getY()));
				if (appeal >= 1f || random.nextFloat() < appeal)
				{
					chosen = candidate;
				}
			}
			if (chosen == null)
			{
				// A golem with a taste in places stays ashore rather than sail somewhere it does not
				// want to be. Anyone else takes whatever the last roll offered.
				if (picky)
				{
					return null;
				}
				chosen = candidates.get(random.nextInt(candidates.size()));
			}
		}

		Itinerary crossing = crossTo(from, chosen, at, tick, random, context);
		// Waiting on this crossing's field, or its one search this frame: hold the choice.
		if (crossing == null && notReady)
		{
			memory.holdPending(from.getRowId(), chosen.getRowId(), tick);
		}
		else
		{
			memory.clearPending();
		}
		return crossing;
	}

	/**
	 * Chooses the port a crew will sail to, or null if there is none they would all go to.
	 *
	 * <p>The port is chosen after the crew is, and chosen for all of them: a candidate is worth no
	 * more than the least any of them thinks of it, and it is offered as a lone golem's pick is,
	 * best first and rolled against that worth. A crew with a golem among it that has a taste in
	 * places sails nowhere rather than somewhere that golem would have refused to go alone; one of
	 * golems that do not mind takes the best on offer. Ports any of them is blocked from are not
	 * offered at all.
	 *
	 * @param crew the memories of the golems sailing, the first of which is at the helm
	 */
	SailingDocks.Dock crewPort(SailingDocks.Dock from, List<TransportMemory> crew, Random random, RoamContext context)
	{
		List<SailingDocks.Dock> candidates = new ArrayList<>(docks.openDocks());
		candidates.removeIf(d -> d.getRowId() == from.getRowId() || d.getShore() == null);
		for (TransportMemory memory : crew)
		{
			candidates.removeIf(d -> d.getRowId() == memory.getBlockedPort());
		}
		if (crew.isEmpty() || candidates.isEmpty())
		{
			return null;
		}

		GolemClimate climate = context == null ? null : context.getClimates();
		boolean picky = false;
		for (TransportMemory memory : crew)
		{
			picky |= climate != null && climate.cares(memory);
		}
		float[] worth = new float[candidates.size()];
		float[] rank = new float[candidates.size()];
		Integer[] order = new Integer[candidates.size()];
		for (int i = 0; i < candidates.size(); i++)
		{
			WorldPoint shore = candidates.get(i).getShore();
			// The least anyone thinks of it, not the average: one golem dragged somewhere it hates
			// is the thing to avoid, and a crew is a compromise by nature.
			float least = 1f;
			for (TransportMemory memory : crew)
			{
				float appeal = context == null ? 1f
					: context.roominess(shore.getX(), shore.getY(), shore.getPlane(), memory);
				if (climate != null)
				{
					appeal *= climate.liking(memory, shore.getX(), shore.getY());
				}
				least = Math.min(least, appeal);
			}
			worth[i] = least;
			// A nudge apiece so equals do not always fall the same way.
			rank[i] = least * (0.75f + random.nextFloat() * 0.5f);
			order[i] = i;
		}
		Arrays.sort(order, (one, other) -> Float.compare(rank[other], rank[one]));
		for (int attempt = 0; attempt < 3 && attempt < order.length; attempt++)
		{
			int i = order[attempt];
			if (worth[i] >= 1f || random.nextFloat() < worth[i])
			{
				return candidates.get(i);
			}
		}
		return picky ? null : candidates.get(order[0]);
	}

	/** How much a golem likes the look of a dock's own shore; 0 for a dock with no shore. */
	private static float liking(GolemClimate climate, TransportMemory memory, SailingDocks.Dock dock)
	{
		WorldPoint shore = dock.getShore();
		return shore == null ? 0f : climate.liking(memory, shore.getX(), shore.getY());
	}

	/**
	 * Set when a crossing could not be planned only because something is not ready: a field being
	 * built, or this frame's sea search spent. Client thread only.
	 */
	private boolean notReady;

	/** Whether the last crossing asked for came back empty only because something is not ready. */
	boolean wasNotReady()
	{
		return notReady;
	}

	/**
	 * Plans the crossing from one dock to a chosen other, or null if it cannot be sailed now. The
	 * crossing carries the dock it leaves, for whoever takes it to be kept from sailing back to.
	 */
	Itinerary crossTo(SailingDocks.Dock from, SailingDocks.Dock to, WorldPoint at, int tick, Random random,
		RoamContext context)
	{
		notReady = false;
		Itinerary crossing = plotCrossing(from, to, at, tick, random, context);
		if (crossing != null)
		{
			crossing.setLeftPort(from.getRowId());
		}
		return crossing;
	}

	private Itinerary plotCrossing(SailingDocks.Dock from, SailingDocks.Dock to, WorldPoint at, int tick,
		Random random, RoamContext context)
	{
		// A crossing that starts or ends off the open sea cannot cross the ocean mesh, the two ends
		// not being on the same water: Wyrmscraig's cave dock sits on the underground map. That is
		// a passage, not a voyage.
		boolean fromCave = isCaveDock(from);
		boolean toCave = isCaveDock(to);
		if (fromCave != toCave)
		{
			// Wyrmscraig's cave: across its lake, out through its mouth onto the sea, and on.
			return throughCave(from, to, fromCave, tick, random, context);
		}
		if (!from.isOnOpenSea() || !to.isOnOpenSea())
		{
			log.debug("Golem taking the passage {} -> {}", from.getName(), to.getName());
			return passage(from, to, at, tick);
		}

		boolean searched = sea.isSearched(from.getMooring(), to.getMooring());

		if (!searched && (context == null || !context.isMaySearchSea()))
		{
			// Never computed, and the frame's one sea search is spent, so the golem tries again.
			notReady = true;
			return null;
		}

		List<int[]> route = sea.route(from.getMooring(), to.getMooring());
		if (!searched && context != null)
		{
			// Spend the budget on the attempt, not on success: a crossing with no route costs as
			// much to discover as one that has.
			context.spendSeaSearch();
		}
		if (route == null)
		{
			return null;
		}
		// From the water beside one gangplank to the other, by the shipped route between moorings.
		List<int[]> course = new ArrayList<>(route.size() + 2);
		WorldPoint setOut = from.getBerth();
		WorldPoint comeIn = to.getBerth();
		if (setOut.getX() != route.get(0)[0] || setOut.getY() != route.get(0)[1])
		{
			course.add(new int[]{setOut.getX(), setOut.getY()});
		}
		course.addAll(route);
		int[] last = route.get(route.size() - 1);
		if (comeIn.getX() != last[0] || comeIn.getY() != last[1])
		{
			course.add(new int[]{comeIn.getX(), comeIn.getY()});
		}

		SeaMesh.Field field = fieldFor(course);
		if (field == null)
		{
			// Being built. The golem waits for it.
			notReady = true;
			return null;
		}

		log.debug("Golem sailing {} -> {}", from.getName(), to.getName());

		// Gangplank to gangplank: the golem steps onto the raft on the water and off at the far
		// quayside. Beginning ashore had it gliding toward a raft not there yet.
		return steer(course, field, random, tick, to.getShore());
	}

	/** Crossings whose distance field is being built right now, so each is built once. */
	private final Set<Long> building = ConcurrentHashMap.newKeySet();

	/**
	 * The distance field for a route, or null while it is built in the background. Safe off the
	 * client thread: it reads only the shipped mesh, fixed after load, and its route.
	 */
	private SeaMesh.Field fieldFor(List<int[]> route)
	{
		return fieldFor(route, sea.ocean);
	}

	/** As {@link #fieldFor(List)}, over a given body of water. */
	private SeaMesh.Field fieldFor(List<int[]> route, SeaMesh.Water water)
	{
		int[] start = route.get(0);
		int[] goal = route.get(route.size() - 1);
		long key = ((long) start[0] << 45) ^ ((long) start[1] << 30) ^ ((long) goal[0] << 15) ^ goal[1]
			^ (water == sea.ocean ? 0L : 0x5A5A5AL << 40);
		synchronized (fields)
		{
			SeaMesh.Field known = fields.get(key);
			if (known != null)
			{
				return known;
			}
		}
		if (executor == null)
		{
			SeaMesh.Field built = buildField(route, water);
			remember(key, built);
			return built;
		}
		if (building.add(key))
		{
			try
			{
				builder().execute(() ->
				{
					try
					{
						remember(key, buildField(route, water));
					}
					finally
					{
						building.remove(key);
					}
				});
			}
			catch (RejectedExecutionException e)
			{
				// Queue full, or stopping. Nothing is building it, so the next golem to ask may try.
				building.remove(key);
			}
		}
		return null;
	}

	/** How far off the shortest route a golem may wander, in tiles. */
	private static final int BAND = 40;

	/** Tiles of open sea a raft keeps all round it where the water allows. */
	private static final int SHORE_CLEARANCE = 2;

	/** How near either gangplank's water a raft may hug the shore, to get in and out. */
	private static final int OPEN_NEAR_BERTH = 12;

	/**
	 * A route's field, kept off the shore where it can be: two tiles of sea all round, then one,
	 * then none, whichever first joins the two ends.
	 */
	private SeaMesh.Field buildField(List<int[]> route, SeaMesh.Water water)
	{
		int[] start = route.get(0);
		SeaMesh.Field field = null;
		for (int clearance = SHORE_CLEARANCE; clearance >= 0; clearance--)
		{
			field = sea.fieldAlong(route, BAND, clearance, OPEN_NEAR_BERTH, water);
			if (field.distance(start[0], start[1]) >= 0)
			{
				return field;
			}
		}
		return field;
	}

	/**
	 * How near the far gangplank, in tiles, a raft puts its golem ashore: a player can step off a
	 * boat this far out.
	 */
	private static final int DISEMBARK_RANGE = 10;

	/**
	 * How far the raft's bow reaches ahead of the golem, in 128ths of a tile: the golem is at the
	 * helm on the stern tile, the middle a tile ahead.
	 */
	private static final int BOW_REACH = 340;

	/** Half the raft's width, near the bow. */
	private static final int BOW_HALF_WIDTH = 80;

	/**
	 * Distance fields for the crossings most recently planned, least recently used first, so a
	 * busy port does not refill one per golem. Bounded by tiles held, not count: eight fields was
	 * far fewer than sixty ports make.
	 */
	private final LinkedHashMap<Long, SeaMesh.Field> fields = new LinkedHashMap<>(64, 0.75f, true);

	/** Tiles across every cached field. Guarded by {@link #fields}. */
	private long cachedTiles;

	/** Tiles the cache may hold, about fifty megabytes, beyond the {@link #MIN_FIELDS} kept. */
	private static final long FIELD_TILE_BUDGET = 1_250_000;

	/** Fields kept whatever their size. */
	private static final int MIN_FIELDS = 8;

	private void remember(long key, SeaMesh.Field field)
	{
		synchronized (fields)
		{
			SeaMesh.Field old = fields.put(key, field);
			cachedTiles += field.size() - (old == null ? 0 : old.size());
			Iterator<SeaMesh.Field> oldest = fields.values().iterator();
			while (fields.size() > MIN_FIELDS && cachedTiles > FIELD_TILE_BUDGET && oldest.hasNext())
			{
				cachedTiles -= oldest.next().size();
				oldest.remove();
			}
		}
	}

	/*
	 * How a boat moves, from the Turning Circles plugin; not measured against a raft here.
	 *
	 *  - It faces one of sixteen compass points and turns one point, 128 of 2048, per tick, moving
	 *    as it turns, which makes a turn an arc.
	 *  - It only moves the way it faces, speed changing toward the chosen speed by a fixed
	 *    acceleration each tick, each axis rounded to a quarter tile.
	 */

	/** One compass point, in the client's 2048ths of a turn: the most a boat turns in a tick. */
	private static final int TURN_PER_TICK = 128;

	/** A raft at full sail, 1.5 tiles a tick, and at half speed, 1 tile a tick, in 128ths of a tile. */
	private static final int FULL_SPEED = 192;
	private static final int HALF_SPEED = 128;

	/** Speed gained or lost in a tick. Not in the cache, and a guess until it is measured. */
	private static final int ACCELERATION = 64;

	/** Movement snaps to quarter tiles on each axis. */
	private static final int QUARTER_TILE = 32;

	/** How far ahead a golem looks when it picks a heading, in tiles. */
	private static final int LOOK_AHEAD = 6;

	/** Ticks a golem holds a chosen heading before choosing again. */
	private static final int HOLD_MIN = 4;
	private static final int HOLD_SPREAD = 7;

	/**
	 * How strongly a golem prefers getting closer, in tiles of progress over the look ahead;
	 * lower is more decided.
	 */
	private static final double TEMPERATURE = 1.6;

	/** How much a golem dislikes each compass point of turn from where it faces. */
	private static final double TURN_RELUCTANCE = 0.35;

	/** Steps from the mooring by sea at which a golem stops wandering and comes in. */
	private static final int ARRIVE = 8;

	/** Ticks without getting nearer before a wandering golem is taken in hand. */
	private static final int STALL_TICKS = 40;

	/** Ticks spent working a raft carefully out of a tight spot before wandering again. */
	private static final int CAREFUL_TICKS = 12;

	/** Chance a crossing stops along the way, and how long it sits, in ticks. */
	private static final float REST_CHANCE = 0.5f;
	private static final int REST_MIN = 8;
	private static final int REST_SPREAD = 20;

	/** Chance a golem takes the whole crossing at half speed. */
	private static final float HALF_SPEED_CHANCE = 0.15f;

	/**
	 * A golem's own way across, sailed as a raft sails: a heading, a speed and a turn of one
	 * compass point a tick, worked out when the crossing is planned and replayed afterward, so a
	 * golem nobody is watching costs nothing on the way.
	 *
	 * <p>Every few ticks it picks a heading at random from the compass, weighted toward getting
	 * nearer and away from turning hard - nearer by sea, the distance being filled outward from
	 * the destination round every headland, so the way out of a bay is the way closer. It turns
	 * toward that heading a point a tick while moving, and where its next move would ground it,
	 * edges out a tile at a time down the travel distance, which is also how it moors.
	 *
	 * @return a tick-by-tick recording, or null if the mooring is not in the field
	 */
	private Itinerary steer(List<int[]> route, SeaMesh.Field field, Random random, int tick, WorldPoint landing)
	{
		Wake wake = new Wake();
		if (!sailLeg(route, field, random, wake, landing, false))
		{
			return null;
		}
		return Itinerary.steered(wake.xs.toArray(), wake.ys.toArray(), wake.facings.toArray(), 0, tick, landing);
	}

	/** A crossing's track so far, and how the raft is moving at the end of it. */
	private static final class Wake
	{
		final IntList xs = new IntList();
		final IntList ys = new IntList();
		final IntList facings = new IntList();
		int speed;

		boolean isEmpty()
		{
			return xs.size() == 0;
		}
	}

	/**
	 * Sails one leg of a crossing onto the end of a wake. An empty wake sets out from the route's
	 * first tile at a standstill; otherwise the leg starts where the wake ends, heading and speed
	 * and all.
	 *
	 * @param landing  the gangplank to come in to and stop by, or null to end at the route's end
	 * @param throughMouth true to end the moment the raft reaches the route's end, still under way,
	 *                     because it goes through a cave mouth there
	 * @return false if the leg's start is not in the field
	 */
	private boolean sailLeg(List<int[]> route, SeaMesh.Field field, Random random, Wake wake, WorldPoint landing,
		boolean throughMouth)
	{
		int[] start = route.get(0);
		int[] goal = route.get(route.size() - 1);
		IntList xs = wake.xs;
		IntList ys = wake.ys;
		IntList facings = wake.facings;

		int x;
		int y;
		int facing;
		int speed;
		if (wake.isEmpty())
		{
			x = centre(start[0]);
			y = centre(start[1]);
			facing = pickHeading(field, x, y, -1, random, true);
			speed = 0;
		}
		else
		{
			x = xs.get(xs.size() - 1);
			y = ys.get(ys.size() - 1);
			facing = facings.get(facings.size() - 1);
			speed = wake.speed;
		}
		int startDistance = field.distance(Math.floorDiv(x, Golem.TILE), Math.floorDiv(y, Golem.TILE));
		if (startDistance < 0)
		{
			return false;
		}
		int cruise = random.nextFloat() < HALF_SPEED_CHANCE ? HALF_SPEED : FULL_SPEED;
		int turnSign = -1;
		int wanted = facing;
		int holdUntil = 0;

		int restAt = random.nextFloat() < REST_CHANCE && startDistance > ARRIVE * 4
			? ARRIVE * 2 + random.nextInt(startDistance - ARRIVE * 3) : -1;
		int restLeft = REST_MIN + random.nextInt(REST_SPREAD);
		boolean resting = false;

		boolean docking = false;
		boolean docked = false;

		int careful = 0;
		int best = startDistance;
		int bestAt = 0;
		int wanderBudget = startDistance * 8 + 300;
		int hardLimit = startDistance * 16 + 600;

		if (wake.isEmpty())
		{
			xs.add(x);
			ys.add(y);
			facings.add(facing);
		}
		for (int t = 1; t <= hardLimit; t++)
		{
			int tileX = Math.floorDiv(x, Golem.TILE);
			int tileY = Math.floorDiv(y, Golem.TILE);
			int here = field.distance(tileX, tileY);

			if (here == 0 && x == centre(goal[0]) && y == centre(goal[1]))
			{
				docked = true;
				break;
			}
			if (throughMouth && here >= 0 && here <= 1)
			{
				// At the cave mouth, and through it. Not off the field, whose distance is -1, which
				// put rafts through the mouth from mid-sea.
				docked = true;
				break;
			}
			if (docking && speed == 0)
			{
				docked = true;
				break;
			}
			if (!docking && t > 1 && landing != null
				&& span(tileX - landing.getX(), tileY - landing.getY()) <= DISEMBARK_RANGE)
			{
				// In range of the gangplank: bring the raft to a stop, and the golem steps ashore.
				docking = true;
			}
			if (here < best)
			{
				best = here;
				bestAt = t;
			}

			if (docking)
			{
				// Coasting to a stop, straight on; stopped short if the way ahead closes.
				speed = Math.max(0, speed - ACCELERATION);
				int[] v = velocity(facing, speed);
				if (speed > 0 && clear(field, x, y, x + v[0], y + v[1]) && bowClear(field, x + v[0], y + v[1], facing))
				{
					x += v[0];
					y += v[1];
				}
				else
				{
					speed = 0;
				}
			}
			else if (resting)
			{
				// Sails down and sitting. It comes to a stop first, then waits.
				if (speed > 0)
				{
					speed = Math.max(0, speed - ACCELERATION);
					int[] v = velocity(facing, speed);
					if (clear(field, x, y, x + v[0], y + v[1]) && bowClear(field, x + v[0], y + v[1], facing))
					{
						x += v[0];
						y += v[1];
					}
					else
					{
						speed = 0;
					}
				}
				else if (--restLeft <= 0)
				{
					resting = false;
					bestAt = t;
				}
			}
			else if (here < 0 || here <= ARRIVE && !throughMouth || careful > 0 || t > wanderBudget)
			{
				// Carefully: down the travel distance a tile at a time, turning on the spot when the
				// way on is over a point off the bow.
				careful = Math.max(0, careful - 1);
				if (here < 0)
				{
					// Off the field: halfway through a diagonal step, on the corner tile between two
					// in it. There is no way downhill from a tile with no distance.
					int[] back = nearestInField(field, tileX, tileY);
					if (back != null)
					{
						x = centre(back[0]);
						y = centre(back[1]);
						speed = 0;
					}
					xs.add(x);
					ys.add(y);
					facings.add(facing);
					continue;
				}
				int[] next = here == 0 ? goal : field.downhill(tileX, tileY);
				int targetX = next == null ? centre(tileX) : centre(next[0]);
				int targetY = next == null ? centre(tileY) : centre(next[1]);
				boolean centred = x == centre(tileX) && y == centre(tileY);
				if (!centred && !clear(field, x, y, targetX, targetY))
				{
					// Off the middle of the tile, and the corner is land: straighten up first. Only
					// when off the middle, the field already allowing the step from the middle.
					targetX = centre(tileX);
					targetY = centre(tileY);
				}
				int dx = targetX - x;
				int dy = targetY - y;
				int gap = span(dx, dy);
				if (gap > 0)
				{
					int toward = compassPoint(dx, dy);
					int off = offBy(facing, toward);
					facing = turn(facing, toward, turnSign);
					turnSign = turning(facing, toward, turnSign);
					if (Math.abs(off) <= TURN_PER_TICK)
					{
						speed = Math.min(speed + ACCELERATION, HALF_SPEED);
						if (speed >= gap)
						{
							x = targetX;
							y = targetY;
						}
						else
						{
							x += (int) Math.round(dx * (double) speed / gap);
							y += (int) Math.round(dy * (double) speed / gap);
						}
					}
					else
					{
						speed = 0;
					}
				}
				else
				{
					speed = 0;
				}
			}
			else
			{
				if (restAt >= 0 && here <= restAt)
				{
					restAt = -1;
					resting = true;
				}

				if (t - bestAt > STALL_TICKS)
				{
					careful = CAREFUL_TICKS;
					bestAt = t;
				}

				if (t >= holdUntil || !clearAhead(field, x, y, wanted, LOOK_AHEAD / 2))
				{
					wanted = pickHeading(field, x, y, facing, random, false);
					holdUntil = t + HOLD_MIN + random.nextInt(HOLD_SPREAD);
				}
				if (wanted < 0)
				{
					// Nowhere worth heading from here: work out of it carefully.
					wanted = facing;
					careful = CAREFUL_TICKS;
					speed = 0;
				}
				else
				{
					facing = turn(facing, wanted, turnSign);
					turnSign = turning(facing, wanted, turnSign);

					int lookTiles = Math.max(2, speed * 3 / Golem.TILE);
					int[] look = velocity(facing, lookTiles * Golem.TILE);
					int target = clearAhead(field, x, y, facing, lookTiles) && bowClear(field, x + look[0], y + look[1], facing)
						? cruise : HALF_SPEED;
					speed = speed < target ? Math.min(target, speed + ACCELERATION) : Math.max(target, speed - ACCELERATION);

					int[] v = velocity(facing, speed);
					if (!clear(field, x, y, x + v[0], y + v[1]) || !bowClear(field, x + v[0], y + v[1], facing))
					{
						speed = Math.min(speed, HALF_SPEED);
						v = velocity(facing, speed);
					}
					if (clear(field, x, y, x + v[0], y + v[1]) && bowClear(field, x + v[0], y + v[1], facing))
					{
						x += v[0];
						y += v[1];
					}
					else
					{
						// About to ground. Stop, and pick the way out.
						speed = 0;
						careful = CAREFUL_TICKS;
					}
				}
			}

			xs.add(x);
			ys.add(y);
			facings.add(facing);
		}

		int last = xs.size() - 1;
		if (!docked && (xs.get(last) != centre(goal[0]) || ys.get(last) != centre(goal[1])))
		{
			// Out of time, which careful sailing should never allow. Finish at the mooring rather
			// than not at all.
			log.debug("Crossing ran out of ticks {} tiles from its mooring", field.distance(
				Math.floorDiv(xs.get(last), Golem.TILE), Math.floorDiv(ys.get(last), Golem.TILE)));
			xs.add(centre(goal[0]));
			ys.add(centre(goal[1]));
			facings.add(facings.get(last));
			speed = 0;
		}
		wake.speed = speed;
		return true;
	}

	// ------------------------------------------------------------------ the cave

	/**
	 * True if a dock is on the sailable cave's lake: its berth is on the water joined to the
	 * cave mouth underground.
	 */
	private boolean isCaveDock(SailingDocks.Dock dock)
	{
		if (dock.isOnOpenSea())
		{
			return false;
		}
		int lake = sea.componentAt(GolemContent.CAVE_LAKE_MOUTH_X, GolemContent.CAVE_LAKE_MOUTH_Y);
		WorldPoint berth = dock.getBerth();
		return lake != 0 && berth.getPlane() == 0 && sea.componentAt(berth.getX(), berth.getY()) == lake;
	}

	/**
	 * A crossing to or from the cave dock, sailed as the game sails it: a boat there sails its
	 * lake to the cave mouth and is put out at the mouth on the island's coast, on the real sea.
	 * The sea leg joins the shipped routes at Wyrmscraig's own dock, the nearest port to the
	 * mouth; only the short way between the two is searched live, once.
	 */
	private Itinerary throughCave(SailingDocks.Dock from, SailingDocks.Dock to, boolean fromCave, int tick,
		Random random, RoamContext context)
	{
		SailingDocks.Dock caveDock = fromCave ? from : to;
		SailingDocks.Dock seaDock = fromCave ? to : from;
		SailingDocks.Dock gateway = nearestSeaDock(GolemContent.CAVE_SEA_MOUTH_X, GolemContent.CAVE_SEA_MOUTH_Y);
		if (gateway == null)
		{
			return null;
		}

		WorldPoint seaMouth = new WorldPoint(GolemContent.CAVE_SEA_MOUTH_X, GolemContent.CAVE_SEA_MOUTH_Y, 0);
		int[] lakeMouth = {GolemContent.CAVE_LAKE_MOUTH_X, GolemContent.CAVE_LAKE_MOUTH_Y};
		int[] caveBerth = {caveDock.getBerth().getX(), caveDock.getBerth().getY()};

		// The sea between the cave mouth and the sea dock, by way of the gateway.
		List<int[]> mouthToGateway = searchedRoute(seaMouth, gateway.getMooring(), context);
		if (mouthToGateway == null)
		{
			return null;
		}
		List<int[]> seaCourse = new ArrayList<>(mouthToGateway);
		if (seaDock.getRowId() != gateway.getRowId())
		{
			List<int[]> onward = searchedRoute(gateway.getMooring(), seaDock.getMooring(), context);
			if (onward == null)
			{
				return null;
			}
			seaCourse.addAll(onward.subList(1, onward.size()));
		}
		seaCourse.add(new int[]{seaDock.getBerth().getX(), seaDock.getBerth().getY()});
		if (!fromCave)
		{
			Collections.reverse(seaCourse);
		}

		List<int[]> lakeCourse = new ArrayList<>();
		lakeCourse.add(fromCave ? caveBerth : lakeMouth);
		lakeCourse.add(fromCave ? lakeMouth : caveBerth);

		SeaMesh.Water lake = sea.lake(sea.componentAt(lakeMouth[0], lakeMouth[1]));
		SeaMesh.Field lakeField = fieldFor(lakeCourse, lake);
		SeaMesh.Field seaField = fieldFor(seaCourse);
		if (lakeField == null || seaField == null)
		{
			// Being built. The golem waits for it.
			notReady = true;
			return null;
		}

		Wake wake = new Wake();
		if (fromCave)
		{
			if (!sailLeg(lakeCourse, lakeField, random, wake, null, true))
			{
				return null;
			}
			putThrough(wake, seaMouth.getX(), seaMouth.getY(), GolemContent.CAVE_SEA_MOUTH_OUTWARD);
			if (!sailLeg(seaCourse, seaField, random, wake, to.getShore(), false))
			{
				return null;
			}
		}
		else
		{
			if (!sailLeg(seaCourse, seaField, random, wake, null, true))
			{
				return null;
			}
			putThrough(wake, lakeMouth[0], lakeMouth[1], GolemContent.CAVE_LAKE_MOUTH_INWARD);
			if (!sailLeg(lakeCourse, lakeField, random, wake, to.getShore(), false))
			{
				return null;
			}
		}

		log.debug("Golem sailing {} -> {} through the cave", from.getName(), to.getName());
		return Itinerary.steered(wake.xs.toArray(), wake.ys.toArray(), wake.facings.toArray(), 0, tick, to.getShore());
	}

	/** Moves the raft through a cave mouth: next tick it is at the other, facing out, under way. */
	private static void putThrough(Wake wake, int tileX, int tileY, int facing)
	{
		wake.xs.add(centre(tileX));
		wake.ys.add(centre(tileY));
		wake.facings.add(facing);
	}

	/** The open-sea dock whose mooring is nearest a tile. */
	private SailingDocks.Dock nearestSeaDock(int x, int y)
	{
		SailingDocks.Dock nearest = null;
		int best = Integer.MAX_VALUE;
		for (SailingDocks.Dock dock : docks.getDocks())
		{
			if (!dock.isOnOpenSea())
			{
				continue;
			}
			int distance = span(dock.getMooring().getX() - x, dock.getMooring().getY() - y);
			if (distance < best)
			{
				best = distance;
				nearest = dock;
			}
		}
		return nearest;
	}

	/** A sea route, searched now if never before and this frame's search is free; else null. */
	private List<int[]> searchedRoute(WorldPoint from, WorldPoint to, RoamContext context)
	{
		boolean searched = sea.isSearched(from, to);
		if (!searched && context != null && !context.isMaySearchSea())
		{
			notReady = true;
			return null;
		}
		List<int[]> route = sea.route(from, to);
		if (!searched && context != null)
		{
			context.spendSeaSearch();
		}
		return route;
	}


	/**
	 * A compass point to steer for, weighted toward progress by sea and against turning.
	 *
	 * @param facing   the way the raft faces now, or -1 if it has not set off
	 * @param decisive take the best rather than drawing at random
	 * @return a compass point, or -1 if no direction is clear
	 */
	private int pickHeading(SeaMesh.Field field, int x, int y, int facing, Random random, boolean decisive)
	{
		int here = field.distance(Math.floorDiv(x, Golem.TILE), Math.floorDiv(y, Golem.TILE));
		double[] weights = new double[16];
		double sum = 0;
		int bestPoint = -1;
		for (int h = 0; h < 16; h++)
		{
			int point = h * TURN_PER_TICK;
			int[] ahead = velocity(point, LOOK_AHEAD * Golem.TILE);
			int tx = x + ahead[0];
			int ty = y + ahead[1];
			int there = field.distance(Math.floorDiv(tx, Golem.TILE), Math.floorDiv(ty, Golem.TILE));
			if (there < 0 || !clear(field, x, y, tx, ty) || !bowClear(field, tx, ty, point))
			{
				continue;
			}
			double turn = facing < 0 ? 0 : Math.abs(offBy(facing, point)) / (double) TURN_PER_TICK;
			weights[h] = Math.exp((here - there) / TEMPERATURE - turn * TURN_RELUCTANCE);
			sum += weights[h];
			if (bestPoint < 0 || weights[h] > weights[bestPoint / TURN_PER_TICK])
			{
				bestPoint = point;
			}
		}
		if (sum <= 0)
		{
			if (facing < 0)
			{
				// Setting off from a mooring with no open water in sight: face the way on.
				int[] next = field.downhill(Math.floorDiv(x, Golem.TILE), Math.floorDiv(y, Golem.TILE));
				return next == null ? 0 : compassPoint(centre(next[0]) - x, centre(next[1]) - y);
			}
			return -1;
		}
		if (decisive)
		{
			return bestPoint;
		}
		double pick = random.nextDouble() * sum;
		for (int h = 0; h < 16; h++)
		{
			pick -= weights[h];
			if (weights[h] > 0 && pick <= 0)
			{
				return h * TURN_PER_TICK;
			}
		}
		return bestPoint;
	}

	/**
	 * True if the raft's bow is over open water with the golem here, facing this way: the tip and
	 * both sides behind it.
	 */
	private static boolean bowClear(SeaMesh.Field field, int x, int y, int facing)
	{
		int[] tip = velocity(facing, BOW_REACH);
		int[] shoulder = velocity(facing, BOW_REACH * 3 / 4);
		int[] side = velocity((facing + 512) & 2047, BOW_HALF_WIDTH);
		return water(field, x + tip[0], y + tip[1])
			&& water(field, x + shoulder[0] + side[0], y + shoulder[1] + side[1])
			&& water(field, x + shoulder[0] - side[0], y + shoulder[1] - side[1]);
	}

	private static boolean water(SeaMesh.Field field, int fineX, int fineY)
	{
		return field.isWater(Math.floorDiv(fineX, Golem.TILE), Math.floorDiv(fineY, Golem.TILE));
	}

	/** The neighbouring tile in the field nearest the destination, or null if none is. */
	private static int[] nearestInField(SeaMesh.Field field, int tileX, int tileY)
	{
		int[] best = null;
		int bestDistance = Integer.MAX_VALUE;
		for (int dx = -1; dx <= 1; dx++)
		{
			for (int dy = -1; dy <= 1; dy++)
			{
				int distance = field.distance(tileX + dx, tileY + dy);
				if (distance >= 0 && distance < bestDistance)
				{
					bestDistance = distance;
					best = new int[]{tileX + dx, tileY + dy};
				}
			}
		}
		return best;
	}

	/** One tick's movement at this heading and speed, each axis on a quarter tile. */
	static int[] velocity(int facing, int speed)
	{
		// 0 south, 512 west, 1024 north, 1536 east.
		double angle = (facing - 1024) * Math.PI / 1024;
		return new int[]{
			quarter(Math.sin(angle) * speed),
			quarter(Math.cos(angle) * speed),
		};
	}

	private static int quarter(double fine)
	{
		return (int) (Math.signum(fine) * Math.round(Math.abs(fine) / QUARTER_TILE)) * QUARTER_TILE;
	}

	/** The compass point nearest a direction. */
	static int compassPoint(int dx, int dy)
	{
		int exact = (int) (1024 + Math.round(Math.atan2(dx, dy) / Math.PI * 1024)) & 2047;
		return ((exact + TURN_PER_TICK / 2) / TURN_PER_TICK * TURN_PER_TICK) & 2047;
	}

	/** Signed turn from one heading to another, the short way; exactly about is -1024. */
	private static int offBy(int from, int to)
	{
		return ((to - from + 1024) & 2047) - 1024;
	}

	/**
	 * A tick's turn toward a heading. A turn exactly about keeps going the way the raft was
	 * already turning, rather than flipping between the two ways.
	 */
	private static int turn(int facing, int toward, int turnSign)
	{
		int off = offBy(facing, toward);
		if (off == 0)
		{
			return facing;
		}
		int sign = off == -1024 ? turnSign : Integer.signum(off);
		return (facing + sign * Math.min(Math.abs(off), TURN_PER_TICK)) & 2047;
	}

	/** Which way the raft is turning after a tick's turn, kept when it is not turning. */
	private static int turning(int facing, int toward, int turnSign)
	{
		int off = offBy(facing, toward);
		return off == 0 || off == -1024 ? turnSign : Integer.signum(off);
	}

	/** True if the raft could move straight between these points without leaving the field. */
	private static boolean clear(SeaMesh.Field field, int fromX, int fromY, int toX, int toY)
	{
		int span = span(toX - fromX, toY - fromY);
		int samples = Math.max(1, span / (QUARTER_TILE / 2));
		for (int s = 0; s <= samples; s++)
		{
			int px = fromX + (int) Math.round((toX - fromX) * (double) s / samples);
			int py = fromY + (int) Math.round((toY - fromY) * (double) s / samples);
			if (field.distance(Math.floorDiv(px, Golem.TILE), Math.floorDiv(py, Golem.TILE)) < 0)
			{
				return false;
			}
		}
		return true;
	}

	/** True if the water is open for this many tiles along a heading. */
	private static boolean clearAhead(SeaMesh.Field field, int x, int y, int facing, int tiles)
	{
		if (facing < 0)
		{
			return false;
		}
		int[] ahead = velocity(facing, tiles * Golem.TILE);
		return clear(field, x, y, x + ahead[0], y + ahead[1]);
	}

	private static int centre(int tile)
	{
		return tile * Golem.TILE + Golem.TILE / 2;
	}

	/** A growable int array, so a few hundred ticks are not a few hundred boxes. */
	private static final class IntList
	{
		private int[] values = new int[256];
		private int size;

		void add(int value)
		{
			if (size == values.length)
			{
				values = Arrays.copyOf(values, size * 2);
			}
			values[size++] = value;
		}

		int get(int index)
		{
			return values[index];
		}

		int size()
		{
			return size;
		}

		int[] toArray()
		{
			return Arrays.copyOf(values, size);
		}
	}

	/**
	 * A crossing with no drawn route: the golem leaves one dock and arrives at the other, timed by
	 * straight-line distance, floored so a short one is not instant.
	 */
	private Itinerary passage(SailingDocks.Dock from, SailingDocks.Dock to, WorldPoint at, int tick)
	{
		WorldPoint a = from.getMooring();
		WorldPoint b = to.getMooring();

		// Underground maps sit thousands of tiles from the surface above them, so the separation
		// between a cave dock and a sea one is meaningless. Capped, not used directly.
		int spread = Math.min(400,
			Math.abs(a.getX() - b.getX()) + Math.abs(a.getY() - b.getY()));

		// Held at the quayside and then put ashore, not walked: as a two-point route the golem
		// slid six thousand tiles from the cave to the surface.
		return Itinerary.passage(at != null ? at : from.getShore(), to.getShore(), tick, Math.max(50, spread));
	}

	/**
	 * The dock a golem standing here could embark from, or null. Generous about distance, the
	 * mooring being water beside the dock and the golem on land.
	 */
	SailingDocks.Dock dockAt(WorldPoint at, int radius)
	{
		for (SailingDocks.Dock dock : docks.getDocks())
		{
			// Measured to the quayside, not the buoy out on the water, which had golems boarding
			// from wherever the radius caught them.
			WorldPoint shore = dock.getShore();
			if (shore.getPlane() == at.getPlane()
				&& Math.abs(shore.getX() - at.getX()) <= radius
				&& Math.abs(shore.getY() - at.getY()) <= radius)
			{
				return dock;
			}
		}
		return null;
	}
}

package com.golemsdontdie;

import java.util.*;
import java.util.function.*;

/**
 * Which spaces a golem can get back from, over only what golems may use right now.
 *
 * <p>A golem goes nowhere it has no way back from. A player can take a drop into a pocket with
 * no row out, or a door golems have not yet seen opened from the far side, and a golem that
 * followed was stuck until the watchdog carried it home. So before a golem takes a transport it
 * asks whether, from where that lands, it could get back where it set off or home.
 *
 * <p>The graph is the mesh's spaces joined by every transport a golem may use (learned, or
 * worked out from the cache and shipped), by the island map's own walks between spaces, and by
 * the sea between open docks. Spaces that can each reach every other are one group: a golem
 * taking a transport from one space of a group to another can always come back. The graph is
 * built again when the table changes or what golems may use does - a level, a quest, a lever.
 */
final class WaysBack
{
	/** Ticks between asking whether what golems may use has changed. */
	static final int RECHECK_TICKS = 50;

	/** Spaces the mesh can name: its component ids are 16 bits. */
	private static final int SPACES = 1 << 16;

	/** The sea, as a space of its own that every open dock leads into and out of. Components start at 1. */
	private static final int SEA = 0;

	private final WorldMesh mesh;
	private final TransportNetwork transports;
	private final Predicate<GolemTransport> usable;

	private int builtRevision = -1;
	private int builtLinks = -1;
	private int checkedTick;
	private boolean checked;
	private BitSet builtUsable = new BitSet();
	private Set<Integer> builtPorts = Collections.emptySet();

	/** How many times the graph was built, so anything cached from it knows to forget. */
	private int builds;

	/** Per space, its group: spaces that can each reach every other. 0 for a space no edge touches. */
	private final int[] group = new int[SPACES];

	/** Per space, whether home can be reached from it. */
	private final boolean[] reachesHome = new boolean[SPACES];

	private final Map<Integer, List<Integer>> edges = new HashMap<>();
	private Map<Long, List<GolemTransport>> starting = new HashMap<>();

	/**
	 * Per row, by index: the spaces it sets off from and lands in, worked out once per build. The
	 * landing follows chains of stepping stones, which fan out hop by hop; asked afresh for every
	 * candidate on every plan it doubled the simulation's running time.
	 */
	private List<Integer>[] fromSpaces = newLists(0);
	private List<Integer>[] toSpaces = newLists(0);

	@SuppressWarnings("unchecked")
	private static List<Integer>[] newLists(int size)
	{
		return (List<Integer>[]) new List[size];
	}

	/** Whether one space reaches another, asked across groups; forgotten on each build. */
	private final Map<Long, Boolean> reaches = new HashMap<>();

	WaysBack(WorldMesh mesh, TransportNetwork transports, Predicate<GolemTransport> usable)
	{
		this.mesh = mesh;
		this.transports = transports;
		this.usable = usable;
	}

	int builds()
	{
		return builds;
	}

	/** Builds again at the next refresh, whether anything changed or not. */
	void forget()
	{
		builtRevision = -1;
		checked = false;
	}

	/** True if this row was usable when the graph was last built. */
	boolean wasUsable(GolemTransport transport)
	{
		return transport.getIndex() >= 0 && builtUsable.get(transport.getIndex());
	}

	/**
	 * Builds the graph again if the table or the joins changed, or, every so often, if what golems
	 * may use has.
	 *
	 * @param ports the spaces of every dock a golem may sail from now; none while kept ashore
	 */
	void refresh(int tick, Supplier<Set<Integer>> ports)
	{
		boolean sameTable = transports.revision() == builtRevision && mesh.linkRevision() == builtLinks;
		if (sameTable && checked && tick >= checkedTick && tick - checkedTick < RECHECK_TICKS)
		{
			return;
		}
		checked = true;
		checkedTick = tick;
		List<GolemTransport> all = transports.all();
		BitSet now = new BitSet(all.size());
		for (int i = 0; i < all.size(); i++)
		{
			GolemTransport t = all.get(i);
			if (transports.isOffered(t) && usable.test(t))
			{
				now.set(i);
			}
		}
		Set<Integer> open = ports.get();
		if (sameTable && now.equals(builtUsable) && open.equals(builtPorts))
		{
			return;
		}
		builtRevision = transports.revision();
		builtLinks = mesh.linkRevision();
		builtUsable = now;
		builtPorts = open;
		build(all);
	}

	private void build(List<GolemTransport> all)
	{
		builds++;
		reaches.clear();
		deadEnds.clear();
		edges.clear();
		fromSpaces = newLists(all.size());
		toSpaces = newLists(all.size());
		starting = new HashMap<>();
		for (int i = builtUsable.nextSetBit(0); i >= 0; i = builtUsable.nextSetBit(i + 1))
		{
			GolemTransport t = all.get(i);
			starting.computeIfAbsent(WorldMesh.tileKey(t.getFromX(), t.getFromY(), t.getFromPlane()),
				k -> new ArrayList<>()).add(t);
		}
		for (int i = builtUsable.nextSetBit(0); i >= 0; i = builtUsable.nextSetBit(i + 1))
		{
			GolemTransport t = all.get(i);
			List<Integer> to = landing(t);
			for (int from : setOff(t))
			{
				for (int space : to)
				{
					edge(from, space);
				}
			}
		}
		for (Map.Entry<Integer, List<Integer>> walked : mesh.walkedTo().entrySet())
		{
			for (int to : walked.getValue())
			{
				edge(walked.getKey(), to);
			}
		}
		for (int port : builtPorts)
		{
			edge(port, SEA);
			edge(SEA, port);
		}
		groups();
		homeward();
	}

	private void edge(int from, int to)
	{
		if (from == to)
		{
			return;
		}
		List<Integer> out = edges.computeIfAbsent(from, k -> new ArrayList<>());
		if (!out.contains(to))
		{
			out.add(to);
		}
	}

	/**
	 * The spaces a transport lands a golem in: its own end's, or following a chain of usable hops
	 * on from an end with none, a stepping stone mid-river. Empty where the mesh knows nothing.
	 */
	List<Integer> landing(GolemTransport t)
	{
		int i = t.getIndex();
		if (i >= 0 && i < toSpaces.length && toSpaces[i] != null)
		{
			return toSpaces[i];
		}
		List<Integer> spaces = mesh.spacesOnward(t.getToX(), t.getToY(), t.getToPlane(),
			t.getFromX(), t.getFromY(), t.getFromPlane(), TransportNetwork.CHAIN_HOPS, starting);
		if (i >= 0 && i < toSpaces.length)
		{
			toSpaces[i] = spaces;
		}
		return spaces;
	}

	/** The spaces a transport sets off from. */
	List<Integer> setOff(GolemTransport t)
	{
		int i = t.getIndex();
		if (i >= 0 && i < fromSpaces.length && fromSpaces[i] != null)
		{
			return fromSpaces[i];
		}
		List<Integer> spaces = mesh.spacesAt(t.getFromX(), t.getFromY(), t.getFromPlane());
		if (i >= 0 && i < fromSpaces.length)
		{
			fromSpaces[i] = spaces;
		}
		return spaces;
	}

	/**
	 * True if a golem setting off from one of these spaces and landing in one of those could come
	 * back: from where it lands it reaches where it set off, or home.
	 */
	boolean comesBack(List<Integer> from, List<Integer> to)
	{
		for (int space : to)
		{
			if (reachesHome(space))
			{
				return true;
			}
			for (int origin : from)
			{
				if (reaches(space, origin))
				{
					return true;
				}
			}
		}
		return false;
	}

	/** Spaces a pocket may run to and still be a dead end: the escape's measure of shut in. */
	static final int DEAD_END_SPACES = 8;

	/** Whether a landing is a dead end from an origin, asked before; forgotten on each build. */
	private final Map<Long, Boolean> deadEnds = new HashMap<>();

	/**
	 * True if landing in these spaces from those leads nowhere but back: everything reachable from
	 * the landing without passing back through where the golem set off is a pocket of a few spaces,
	 * no dock among them. Castle Wars' waiting rooms, a tower top, a cellar.
	 */
	boolean isDeadEnd(List<Integer> from, List<Integer> to)
	{
		if (to.isEmpty() || from.isEmpty())
		{
			return false;
		}
		// Landing where it set off - a hop within one space - is no dead end: the whole space is
		// still there. Read as one, every such hop was taken less.
		for (int space : to)
		{
			if (from.contains(space))
			{
				return false;
			}
		}
		long key = (long) to.get(0) << 16 | from.get(0);
		Boolean known = deadEnds.get(key);
		if (known != null)
		{
			return known;
		}
		int stamp = ++searches;
		for (int origin : from)
		{
			seenBy[origin] = stamp;
		}
		ArrayDeque<Integer> queue = new ArrayDeque<>();
		int pocket = 0;
		for (int space : to)
		{
			if (seenBy[space] != stamp)
			{
				seenBy[space] = stamp;
				queue.add(space);
				pocket++;
			}
		}
		boolean dead = true;
		while (!queue.isEmpty() && dead)
		{
			for (int next : edges.getOrDefault(queue.poll(), Collections.emptyList()))
			{
				if (seenBy[next] == stamp)
				{
					continue;
				}
				seenBy[next] = stamp;
				// The sea goes everywhere a boat does; more than a few spaces is somewhere else.
				if (next == SEA || ++pocket > DEAD_END_SPACES)
				{
					dead = false;
					break;
				}
				queue.add(next);
			}
		}
		if (deadEnds.size() >= MOST_REMEMBERED)
		{
			deadEnds.clear();
		}
		deadEnds.put(key, dead);
		return dead;
	}

	/** True if a golem in this space could get home. */
	boolean reachesHome(int space)
	{
		return space >= 0 && space < SPACES && reachesHome[space];
	}

	/** True if a golem in one space could get to the other. */
	boolean reaches(int from, int to)
	{
		if (from == to || group[from] != 0 && group[from] == group[to])
		{
			return true;
		}
		long key = (long) from << 16 | to;
		Boolean known = reaches.get(key);
		if (known != null)
		{
			return known;
		}
		boolean found = search(from, to);
		if (reaches.size() >= MOST_REMEMBERED)
		{
			reaches.clear();
		}
		reaches.put(key, found);
		return found;
	}

	/** Answers remembered at once before they are started afresh. */
	private static final int MOST_REMEMBERED = 100_000;

	/** Per space, the search that last saw it: one array for every search, not one each. */
	private final int[] seenBy = new int[SPACES];
	private int searches;

	private boolean search(int from, int to)
	{
		int stamp = ++searches;
		ArrayDeque<Integer> queue = new ArrayDeque<>();
		seenBy[from] = stamp;
		queue.add(from);
		while (!queue.isEmpty())
		{
			for (int next : edges.getOrDefault(queue.poll(), Collections.emptyList()))
			{
				if (next == to)
				{
					return true;
				}
				if (seenBy[next] != stamp)
				{
					seenBy[next] = stamp;
					queue.add(next);
				}
			}
		}
		return false;
	}

	/** Every space that can reach home: a search backwards along the edges from home's space. */
	private void homeward()
	{
		Arrays.fill(reachesHome, false);
		int home = mesh.componentAt(GolemContent.PLINTH_X, GolemContent.PLINTH_Y, 0);
		if (home == 0)
		{
			return;
		}
		Map<Integer, List<Integer>> back = new HashMap<>();
		for (Map.Entry<Integer, List<Integer>> e : edges.entrySet())
		{
			for (int to : e.getValue())
			{
				back.computeIfAbsent(to, k -> new ArrayList<>()).add(e.getKey());
			}
		}
		ArrayDeque<Integer> queue = new ArrayDeque<>();
		reachesHome[home] = true;
		queue.add(home);
		while (!queue.isEmpty())
		{
			for (int prior : back.getOrDefault(queue.poll(), Collections.emptyList()))
			{
				if (!reachesHome[prior])
				{
					reachesHome[prior] = true;
					queue.add(prior);
				}
			}
		}
		// The sea is no place to stand.
		reachesHome[SEA] = false;
	}

	/**
	 * Tarjan's strongly connected components, without recursion: a chain of spaces can run to
	 * thousands, deeper than a thread's stack.
	 */
	private void groups()
	{
		Arrays.fill(group, 0);
		int[] index = new int[SPACES];
		Arrays.fill(index, -1);
		int[] low = new int[SPACES];
		boolean[] onStack = new boolean[SPACES];
		int[] stack = new int[SPACES];
		int[] callNode = new int[SPACES];
		int[] callEdge = new int[SPACES];
		int top = 0;
		int counter = 0;
		int groups = 0;
		for (int root : edges.keySet())
		{
			if (index[root] >= 0)
			{
				continue;
			}
			int depth = 0;
			callNode[0] = root;
			callEdge[0] = 0;
			index[root] = low[root] = counter++;
			stack[top++] = root;
			onStack[root] = true;
			while (depth >= 0)
			{
				int v = callNode[depth];
				List<Integer> out = edges.getOrDefault(v, Collections.emptyList());
				if (callEdge[depth] < out.size())
				{
					int w = out.get(callEdge[depth]++);
					if (index[w] < 0)
					{
						index[w] = low[w] = counter++;
						stack[top++] = w;
						onStack[w] = true;
						depth++;
						callNode[depth] = w;
						callEdge[depth] = 0;
					}
					else if (onStack[w])
					{
						low[v] = Math.min(low[v], index[w]);
					}
					continue;
				}
				if (low[v] == index[v])
				{
					groups++;
					int w;
					do
					{
						w = stack[--top];
						onStack[w] = false;
						group[w] = groups;
					}
					while (w != v);
				}
				depth--;
				if (depth >= 0)
				{
					int u = callNode[depth];
					low[u] = Math.min(low[u], low[v]);
				}
			}
		}
	}
}

package com.golemsdontdie;

import javax.inject.*;
import net.runelite.api.coords.*;

/**
 * Where a golem is, in words: "Catherby", "Taverley Dungeon", "Sailing to Port Khazard".
 *
 * <p>Said the way a player would say it, from what the golem is doing rather than from its
 * coordinates alone - a golem halfway across the sea is between two ports, and naming the water it
 * is over would tell nobody anything.
 */
@Singleton
class Whereabouts
{
	@Inject
	private PlaceNames places;

	@Inject
	private Voyage voyage;

	/** How near a dock a golem must be for the dock's own name to be worth saying, in tiles. */
	private static final int AT_THE_DOCK = 6;

	String of(Golem golem, int tick)
	{
		if (golem == null)
		{
			return "";
		}
		if (golem.isAboard())
		{
			return "Aboard your ship";
		}
		if (golem.isSailing(tick))
		{
			// Where it will land, which is the useful half of a crossing: the sea itself has no name
			// worth giving, and a raft is only ever between two ports.
			SailingDocks.Dock landing = voyage == null ? null : voyage.dockAt(golem.saveTile(), AT_THE_DOCK);
			String port = landing != null ? landing.getName() : places.nameFor(golem.saveTile());
			return port == null ? "At sea" : "Sailing to " + port;
		}

		WorldPoint at = golem.currentTile();
		String place = places.nameFor(at);
		if (place == null)
		{
			return unnamed(at);
		}
		if (golem.isInInstance())
		{
			return "Inside " + place;
		}
		return golem.getPlane() > 0 ? place + ", upstairs" : place;
	}

	/**
	 * Somewhere no place name reaches: near the nearest one, or beneath the ground above a cave.
	 * "Somewhere unmapped" said nothing a player could go looking with.
	 */
	private String unnamed(WorldPoint at)
	{
		String upstairs = at.getPlane() > 0 ? ", upstairs" : "";
		if (WorldLayout.isCave(at.getY()))
		{
			int above = WorldLayout.groundAbove(at.getY());
			String over = above < 0 ? null : places.nameFor(at.getX(), above, 0);
			if (over == null && above >= 0)
			{
				over = places.nearest(at.getX(), above, 0);
			}
			if (over != null)
			{
				return "Beneath " + over;
			}
		}
		String near = places.nearest(at.getX(), at.getY(), at.getPlane());
		return near != null ? "Near " + near + upstairs
			: at.getPlane() > 0 ? "Somewhere upstairs" : "Somewhere unmapped";
	}
}

package com.golemsdontdie;

/**
 * How the game lays the world out north to south, in one place.
 *
 * <p>Three layers, and the difference matters. The surface map runs up to {@link #SURFACE_TOP}:
 * the most northerly land on it, the Frozen Temple, is at 4121. Caves dug under that ground are laid
 * out {@link #CAVE_OFFSET} tiles north of what they run beneath, which is what lets the world map
 * draw a cave over its hill. And between the two is everything laid out apart from the map with no
 * ground above it that can be named - God Wars, TzHaar, Motherlode Mine and Zanaris, but also
 * Prifddinas, which is not underground at all. Nothing about a tile in that band says where it is.
 */
final class WorldLayout
{
	/** The north edge of the surface map, in tiles. */
	static final int SURFACE_TOP = 4160;

	/** How far north of the ground above it a cave is laid out, in tiles. */
	static final int CAVE_OFFSET = 6400;

	private WorldLayout()
	{
	}

	/** On the surface map. */
	static boolean isSurface(int y)
	{
		return y < SURFACE_TOP;
	}

	/** In a cave dug under the surface, whose ground above is {@link #groundAbove}. */
	static boolean isCave(int y)
	{
		return y >= CAVE_OFFSET;
	}

	/**
	 * The y of the ground this tile lies under, or of the tile itself on the surface: or -1 for
	 * somewhere laid out apart from the map, which lies under nowhere that can be said.
	 */
	static int groundAbove(int y)
	{
		return isSurface(y) ? y : isCave(y) ? y - CAVE_OFFSET : -1;
	}

	/**
	 * Whether two tiles are on the same layer, which is when the tiles between them are a walk:
	 * a cave and the ground over it are six thousand tiles apart by the numbers and one ladder by
	 * the world. Two places each laid out apart from the map are only near each other if their
	 * numbers say so and are close enough to be one place.
	 */
	static boolean sameLayer(int y1, int y2)
	{
		if (isSurface(y1) != isSurface(y2) || isCave(y1) != isCave(y2))
		{
			return false;
		}
		return isSurface(y1) || isCave(y1) || Math.abs(y1 - y2) < ELSEWHERE_REACH;
	}

	/** How near two tiles laid out apart from the map must be to count as the same place. */
	private static final int ELSEWHERE_REACH = 128;
}

package com.golemsdontdie;

import java.io.*;
import java.util.*;
import java.util.zip.*;
import javax.inject.*;
import lombok.extern.slf4j.*;
import net.runelite.api.worldmap.WorldMapData;

/**
 * Where each world map other than the surface draws the game's tiles, read from the cache once and
 * shipped as world-map.gz.
 *
 * <p>A map is pieces: a map square or one zone of one, taken from some floors and drawn somewhere on
 * the map. A dungeon is drawn away from its own coordinates, and not all in one piece: Waterbirth's
 * eight hundred pieces are moved by many different amounts. Some maps draw an upper floor as an inset
 * beside the floor below, and Cam Torum is a map of its own over Neypotzli. So where a golem goes is
 * worked out from its own tile and floor, piece by piece; the surface draws every tile where it is,
 * on every floor, and has no pieces here.
 *
 * <p>The client says which map is open only by whether it draws a tile, so each map has a test tile
 * and the list of test tiles it draws, and the open map is the one whose list matches.
 */
@Slf4j
@Singleton
class WorldMapLayers
{
	private static final String RESOURCE = "/world-map.gz";
	private static final int VERSION = 1;

	private final List<Layer> layers = new ArrayList<>();

	/** The map last asked about, and which layer it is; null for the surface or a map not known. */
	private WorldMapData identifiedFor;
	private Layer open;

	void load()
	{
		layers.clear();
		identifiedFor = null;
		try (InputStream raw = WorldMapLayers.class.getResourceAsStream(RESOURCE))
		{
			if (raw == null)
			{
				log.warn("No world map layers on the classpath; golems in dungeons stay off their maps");
				return;
			}
			try (DataInputStream in = new DataInputStream(new GZIPInputStream(raw)))
			{
				if (in.readInt() != VERSION)
				{
					log.warn("World map layers are another version; ignoring them");
					return;
				}
				for (int maps = in.readShort(); maps > 0; maps--)
				{
					Layer layer = new Layer();
					in.readShort();
					layer.name = in.readUTF();
					layer.testX = in.readInt();
					layer.testY = in.readInt();
					for (int tests = in.readShort(); tests > 0; tests--)
					{
						layer.tests.set(in.readShort());
					}
					int pieces = in.readInt();
					layer.pieces = new short[pieces * PIECE];
					Map<Integer, List<Integer>> bySquare = new HashMap<>();
					for (int i = 0; i < pieces; i++)
					{
						int at = i * PIECE;
						layer.pieces[at] = (short) in.readUnsignedByte();
						layer.pieces[at + 1] = (short) in.readUnsignedByte();
						layer.pieces[at + 2] = in.readShort();
						layer.pieces[at + 3] = in.readShort();
						layer.pieces[at + 4] = (short) in.readUnsignedByte();
						layer.pieces[at + 5] = in.readShort();
						layer.pieces[at + 6] = in.readShort();
						bySquare.computeIfAbsent(square(layer.pieces[at + 2] >> 3, layer.pieces[at + 3] >> 3),
							k -> new ArrayList<>()).add(at);
					}
					for (Map.Entry<Integer, List<Integer>> e : bySquare.entrySet())
					{
						layer.bySquare.put(e.getKey(), e.getValue().stream().mapToInt(Integer::intValue).toArray());
					}
					layers.add(layer);
				}
			}
			log.debug("Loaded {} world map layers", layers.size());
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("World map layers unreadable", e);
			layers.clear();
		}
	}

	/**
	 * The layer the open map is, or null for the surface, which draws every tile where it is, and for
	 * a map newer than the table. Worked out once per map: the client keeps one object per map.
	 */
	Layer layerOf(WorldMapData showing)
	{
		if (showing != identifiedFor)
		{
			identifiedFor = showing;
			open = identify(showing);
		}
		return open;
	}

	/** The layer of the map with this name, or null. */
	Layer named(String name)
	{
		for (Layer layer : layers)
		{
			if (layer.name.equals(name))
			{
				return layer;
			}
		}
		return null;
	}

	private Layer identify(WorldMapData showing)
	{
		if (showing == null || layers.isEmpty())
		{
			return null;
		}
		BitSet drawn = new BitSet(layers.size());
		for (int i = 0; i < layers.size(); i++)
		{
			Layer layer = layers.get(i);
			if (showing.surfaceContainsPosition(layer.testX, layer.testY))
			{
				drawn.set(i);
			}
		}
		for (Layer layer : layers)
		{
			if (layer.tests.equals(drawn))
			{
				log.debug("The world map open is {}", layer.name);
				return layer;
			}
		}
		return null;
	}

	/** Shorts per piece: lowest floor, floors, source zone x and y, size in zones, zones moved x and y. */
	private static final int PIECE = 7;

	private static int square(int x, int y)
	{
		return x << 16 | y;
	}

	/** One map: its pieces, found by the map square they are taken from. */
	static final class Layer
	{
		private String name;
		private int testX;
		private int testY;
		private final BitSet tests = new BitSet();
		private short[] pieces;
		private final Map<Integer, int[]> bySquare = new HashMap<>();

		/**
		 * Where this map draws a tile, as {x, y} in the map's own coordinates, into {@code out}; false
		 * if the map does not draw that tile on that floor, which means it is somewhere else.
		 */
		boolean place(int x, int y, int plane, int[] out)
		{
			int[] here = bySquare.get(square(x >> 6, y >> 6));
			if (here == null)
			{
				return false;
			}
			int zoneX = x >> 3;
			int zoneY = y >> 3;
			for (int at : here)
			{
				int lowest = pieces[at];
				int size = pieces[at + 4];
				if (plane < lowest || plane >= lowest + pieces[at + 1]
					|| zoneX < pieces[at + 2] || zoneX >= pieces[at + 2] + size
					|| zoneY < pieces[at + 3] || zoneY >= pieces[at + 3] + size)
				{
					continue;
				}
				out[0] = x + pieces[at + 5] * 8;
				out[1] = y + pieces[at + 6] * 8;
				return true;
			}
			return false;
		}
	}
}

package com.golemsdontdie;

import java.io.*;
import java.util.*;
import java.util.zip.*;
import javax.inject.*;
import lombok.*;
import lombok.extern.slf4j.*;
import net.runelite.api.*;

/**
 * Where a golem may walk, anywhere in the world. Read-only, shipped, never written to.
 *
 * <p>The island map this replaces covered nine regions and fitted in a config value; this
 * covers 2,424 region-planes, the ocean and every floor of the world the collision data holds,
 * and at about 1.5 MB belongs in the jar.
 *
 * <p>A byte per tile, from the game cache by the client's own rules: <b>north</b> and <b>east</b>
 * edges as {@code IslandMemory} keeps them (south and west are the neighbouring tile's), whether
 * the tile can be stood on and has ground under it, the two corners that can refuse a diagonal
 * step, and which shut edges are doors. Then a bit per tile for each derived map, and <b>water</b>
 * for every sea and lake the textures say is one.
 * <b>ocean</b> is the single connected sea: two ports are only sailable between if both sit
 * on it, and enclosed water exists - Karamja's inland body is 26,000 tiles leading nowhere.
 * <b>isolated</b> marks components under 50 tiles, computed offline rather than by a flood
 * fill the client cannot afford.
 *
 * @see IslandMemory the live harvest, which takes precedence over this everywhere
 */
@Slf4j
@Singleton
class WorldMesh
{
	private static final String RESOURCE = "/world-mesh.gz";

	private static final int REGION_SIZE = Constants.REGION_SIZE;
	private static final int REGION_MASK = REGION_SIZE - 1;
	private static final int TILES_PER_PLANE = REGION_SIZE * REGION_SIZE;

	/** A byte per tile for passability and what the tile is; a bit per tile for each derived map. */
	private static final int COLLISION_BYTES = TILES_PER_PLANE;
	private static final int DERIVED_BYTES = TILES_PER_PLANE / 8;

	/** Two bytes a tile: there are 18,634 components, which does not fit in one. */
	private static final int COMPONENT_BYTES = TILES_PER_PLANE * 2;

	/** Impossible as an entry count, so an old file is refused rather than misread. */
	private static final int MAGIC = -0x60137;

	/** 2 added the per-tile component map; 3 a byte a tile (standable, ground, corners, doors) and water. */
	private static final int VERSION = 4;

	static final int FLAG_NORTH = 0;
	static final int FLAG_EAST = 1;

	/** The tile can be stood on: nothing solid fills it. */
	static final int FLAG_STANDABLE = 2;

	/** The tile has ground under it: not the void round an upper floor. */
	static final int FLAG_GROUND = 3;

	/**
	 * A corner blocks the diagonal north-east out of the tile, or into it from the north-east:
	 * a wall's corner post, a diagonal wall. The two-bit map could not say so, and golems cut
	 * corners the game refuses.
	 */
	static final int FLAG_CORNER_NE = 4;

	/** The same for the diagonal north-west. */
	static final int FLAG_CORNER_NW = 5;

	/** The north edge is shut only by something that opens: a door or a gate. */
	static final int FLAG_DOOR_NORTH = 6;

	/** The same for the east edge. */
	static final int FLAG_DOOR_EAST = 7;

	/**
	 * Everything the mesh holds for one region and plane. One object rather than five maps
	 * keyed alike: a walkability check touches several, planning asks millions of times,
	 * and the boxed lookups were most of the cost.
	 */
	@AllArgsConstructor
	private static final class Region
	{
		/** A byte per tile: the FLAG_ bits. */
		final byte[] collision;

		/** The single connected sea. */
		final byte[] ocean;

		/** Components too small to wander. */
		final byte[] isolated;

		/**
		 * Which connected component each tile belongs to, 0 for none, as an index into
		 * {@link #palette}; null where the whole region-plane is one. Shipped as two bytes a tile
		 * (there are 18,630 components), held as one: no region-plane has more than 172, and the
		 * two bytes were more than half the mesh in memory.
		 * The one thing no per-tile flag can say: whether two tiles are connected <b>to each
		 * other</b>. Everything else answers "may a golem stand there", and a sealed room is
		 * good ground. {@code isolated} only caught components under fifty tiles.
		 */
		final byte[] components;

		/** The component ids a region-plane's tiles index into. */
		final int[] palette;

		/**
		 * Each tile's component id outright, for the rare region-plane with more than 256 of them,
		 * which no palette of a byte can index; null otherwise. None does today (the most is 172).
		 */
		final char[] wide;

		/**
		 * Tiles the land fill reached - ground a golem may stand on, on foot. The ocean bit
		 * marks only the one connected sea, so cave water, lakes and enclosed basins read as
		 * passable and golems walked out across them. Shoreline edges are blocked, so a fill
		 * starting on land cannot leak.
		 */
		final byte[] land;

		/**
		 * Water, by the cache's own textures: the ocean and every other sea and lake of a hundred
		 * tiles or more. Passable in the client, never ground.
		 */
		final byte[] water;
	}

	/** Region and plane to what the mesh holds for it. */
	private final Map<Long, Region> regions = new HashMap<>();

	/**
	 * The same regions by region id and plane for planes 0 to 3, so the common case is an
	 * array read with no key boxed. Anything else goes through {@link #regions}.
	 */
	private final Region[] byRegion = new Region[FAST_REGIONS << 2];

	private static final int FAST_REGIONS = 1 << 16;

	private boolean loaded;

	/**
	 * Reads the bundled mesh. A missing or corrupt resource leaves every query answering
	 * "unknown", which is survivable: the live harvest still works, so golems roam what the
	 * player has walked.
	 */
	void load()
	{
		if (loaded)
		{
			return;
		}
		loaded = true;

		try (InputStream raw = WorldMesh.class.getResourceAsStream(RESOURCE))
		{
			if (raw == null)
			{
				log.warn("Bundled world mesh missing from the jar");
				return;
			}

			try (GZIPInputStream gz = new GZIPInputStream(raw);
				 DataInputStream data = new DataInputStream(gz))
			{
				// A negative first field is the version marker. An entry count cannot be
				// negative, so a file without one is the old format and is refused rather
				// than read as though its component map were region ids.
				int first = data.readInt();
				if (first != MAGIC)
				{
					log.warn("World mesh is an old format; it needs rebuilding");
					return;
				}
				int version = data.readInt();
				if (version != VERSION)
				{
					log.warn("World mesh is version {}, expected {}", version, VERSION);
					return;
				}

				int entries = data.readInt();
				for (int i = 0; i < entries; i++)
				{
					int regionId = data.readInt();
					int plane = data.readByte();
					put(regionId, plane, readRecord(data));
				}

				// The rest of the world, packed: read the first time a golem asks about it.
				int packedEntries = data.readInt();
				for (int i = 0; i < packedEntries; i++)
				{
					int regionId = data.readInt();
					int plane = data.readByte();
					byte[] blob = new byte[data.readInt()];
					data.readFully(blob);
					packed.put(key(regionId, plane), blob);
					if (regionId >= 0 && regionId < FAST_REGIONS && (plane & 0xF) < 4)
					{
						packedAt[regionId << 2 | (plane & 0xF)] = true;
					}
				}
				log.debug("Loaded world mesh: {} region-planes, {} more packed", entries, packedEntries);
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Bundled world mesh unreadable", e);
			regions.clear();
			Arrays.fill(byRegion, null);
			packed.clear();
			Arrays.fill(packedAt, false);
		}
	}

	boolean north(int x, int y, int plane)
	{
		return flag(x, y, plane, FLAG_NORTH);
	}

	boolean east(int x, int y, int plane)
	{
		return flag(x, y, plane, FLAG_EAST);
	}

	/** True if this tile is part of the single connected sea. */
	boolean isOcean(int x, int y, int plane)
	{
		Region region = region(regionIdOf(x, y), plane);
		return region != null && bit(region.ocean, x, y);
	}

	/**
	 * True if this tile sits in a component too small to wander - the question stuck
	 * detection asks, as a bit lookup. A golem restored onto one is relocated rather than
	 * left walking into the same four walls forever.
	 */
	boolean isIsolated(int x, int y, int plane)
	{
		Region region = region(regionIdOf(x, y), plane);
		return region != null && bit(region.isolated, x, y);
	}

	/**
	 * Which connected space this tile belongs to, or 0 if the mesh does not know. Zero means
	 * "no answer", not "no component": refusing a tile outside the shipped regions would
	 * shrink the world to the shipped file.
	 */
	int componentAt(int x, int y, int plane)
	{
		Region region = region(regionIdOf(x, y), plane);
		if (region == null)
		{
			return 0;
		}
		return componentOf(region, x, y);
	}

	/**
	 * True if a golem standing at the first tile could walk to the second. Unknown counts as
	 * yes: the live harvest covers ground the mesh never will, so a silent answer must not
	 * be read as a refusal.
	 */
	boolean sameComponent(int fromX, int fromY, int toX, int toY, int plane)
	{
		int from = componentAt(fromX, fromY, plane);
		int to = componentAt(toX, toY, plane);
		return from == 0 || to == 0 || from == to;
	}

	/**
	 * True if this tile is water a boat sails but nobody walks, and is not the sea: Wyrmscraig's
	 * underground lake, and every other lake. Passable because boats cross it and the client does
	 * not block it, so the golems' map read it as ground and golems walked on the water. The lake
	 * used to be found by its component from a hard-coded mouth; the mesh now carries water.
	 */
	boolean isInlandWater(int x, int y, int plane)
	{
		return isWater(x, y, plane) && !isOcean(x, y, plane);
	}

	/** True if this tile is water by the cache's textures: the ocean, a sea, a lake. Never ground. */
	boolean isWater(int x, int y, int plane)
	{
		Region region = region(regionIdOf(x, y), plane);
		return region != null && bit(region.water, x, y);
	}

	/**
	 * True if a corner stops the diagonal step (dx, dy) from this tile, as the client's own corner
	 * test does: a wall's corner post, a diagonal wall. The step's four edges are the caller's.
	 */
	boolean cornerBlocks(int x, int y, int plane, int dx, int dy)
	{
		if (dy == 1)
		{
			return flag(x, y, plane, dx == 1 ? FLAG_CORNER_NE : FLAG_CORNER_NW);
		}
		// Southward, the same corner seen from the tile it arrives at.
		return flag(x + dx, y + dy, plane, dx == 1 ? FLAG_CORNER_NW : FLAG_CORNER_NE);
	}

	/** True if this tile's north (or east) edge is shut only by something that opens. */
	boolean isDoorEdge(int x, int y, int plane, boolean northEdge)
	{
		return flag(x, y, plane, northEdge ? FLAG_DOOR_NORTH : FLAG_DOOR_EAST);
	}

	/**
	 * True if something could walk here: nothing solid fills it, there is ground under it, and it
	 * can be left in some direction. All three: a tile walled on four sides - the one tile a
	 * ladder puts you on, atop a platform - is ground to stand on but nowhere to walk, and a golem
	 * put down there must take the next hop rather than plan a walk; the edges alone let the void
	 * round an upper floor through.
	 */
	boolean isWalkable(int x, int y, int plane)
	{
		return flag(x, y, plane, FLAG_STANDABLE) && flag(x, y, plane, FLAG_GROUND)
			&& (north(x, y, plane) || east(x, y, plane) || north(x, y - 1, plane) || east(x - 1, y, plane));
	}

	/**
	 * True if a golem could stand here <em>on foot</em>. Leaving this distinction out put
	 * golems on the open sea: water is <b>passable</b> in the source collision map, which is
	 * why sea navigation works, so the passability bits alone cannot tell walkable ground
	 * from crossable water. Only {@link SeaMesh}, routing a boat, may treat the sea as
	 * passable.
	 */
	boolean isLandWalkable(int x, int y, int plane)
	{
		if (isInlandWater(x, y, plane))
		{
			return false;
		}
		Region region = region(regionIdOf(x, y), plane);
		if (region == null)
		{
			// Nothing known here: no land bit and no component that could have been admitted.
			return false;
		}
		if (!bit(region.land, x, y))
		{
			// Only worth reading the component when some floor has been admitted at all.
			if (admittedFloors == 0)
			{
				return false;
			}
			int component = componentOf(region, x, y);
			if (!landComponents[component] && !dockFloors[component] && !instanceFloors[component])
			{
				return false;
			}
		}
		return isWalkable(x, y, plane);
	}

	/**
	 * Floors counted as land because a dock stands on them. Kept apart from the transport
	 * floors, which are replaced whenever a route is learned. Sailing added islands no
	 * transport table has a row on: twenty-two of the sixty-one docks had no land beside
	 * them, so a golem sailing there could not step off.
	 */
	private final boolean[] dockFloors = new boolean[1 << 16];

	/**
	 * Floors counted as land because the instance the player stands in is built from them: the
	 * template rooms golems in it walk, in template coordinates. Only the room a learned route led
	 * into was admitted before, and a golem that wandered further into the instance found nowhere
	 * to walk and was carried home in front of the player. Kept until the next instance.
	 */
	private final boolean[] instanceFloors = new boolean[1 << 16];

	/** The components admitted as {@link #instanceFloors}, to take back when the instance changes. */
	private final Set<Integer> instanceFloorList = new HashSet<>();

	/** Admits these components as the loaded instance's floors, in place of the last instance's. */
	void admitInstanceFloors(Set<Integer> components)
	{
		for (int component : instanceFloorList)
		{
			instanceFloors[component] = false;
			admittedFloors -= landComponents[component] || dockFloors[component] ? 0 : 1;
		}
		instanceFloorList.clear();
		for (int component : components)
		{
			if (component != 0 && !instanceFloors[component])
			{
				instanceFloors[component] = true;
				instanceFloorList.add(component);
				admittedFloors += landComponents[component] || dockFloors[component] ? 0 : 1;
			}
		}
	}

	/** How many floors either kind of admission holds, so a check can skip reading the component. */
	private int admittedFloors;

	/** How many of them came from transports, for the log. */
	private int transportFloors;

	/**
	 * Which spaces can be walked to from home, and which can be walked home from.
	 *
	 * <p>A golem walks only inside the space it is standing in; a transport or a crossing is the
	 * only way into another. So the spaces make a graph with the transports for edges, and a golem
	 * belongs in the part of it home can reach and that can reach home. Anywhere else is a trap
	 * whatever its size: a space of a million tiles with no route into it is a million tiles no
	 * golem can arrive at, and only matters at all because one was put there.
	 *
	 * <p>One direction only, deliberately. Asking for a way back as well looked right and was
	 * wrong: the tables hold one-way rows, and a pocket of Wyrmscraig entered by a drop with no
	 * row back out had golems carried to the plinth and walking straight back into it, twice in
	 * fifteen seconds. Ground a golem can reach is ground a golem may stand on; a golem that
	 * cannot get out again is the stuck watchdog's business, not this one's. Not walking into
	 * such a pocket in the first place is WaysBack's, over only what golems may use.
	 */
	private boolean[] fromHome;

	/** Every space a dock stands in. The sea joins them to each other. */
	private final Set<Integer> ports = new HashSet<>();

	/** Every space a transport touches, at either end. Rebuilt with the graph. */
	private final Set<Integer> touched = new HashSet<>();

	/** Space to the spaces a transport leads to. */
	private final Map<Integer, java.util.List<Integer>> leadsTo = new HashMap<>();

	/** Space to the spaces the island map walks into from it, both ways. See joinWhereWalked. */
	private final Map<Integer, java.util.List<Integer>> walkedTo = new HashMap<>();

	/** Goes up whenever the joins above are rebuilt, so anything built from them knows to build again. */
	private int linkRevision;

	int linkRevision()
	{
		return linkRevision;
	}

	/** Space to the spaces the island map walks into from it. */
	Map<Integer, java.util.List<Integer>> walkedTo()
	{
		return Collections.unmodifiableMap(walkedTo);
	}

	/**
	 * True if this tile is in a pocket too small to wander, that no route touches and no dock
	 * stands in.
	 *
	 * <p>The plainest trap there is, and the one answer here that barely leans on the tables: the
	 * pocket is under fifty tiles by the shipped mesh's own reckoning, so a golem in it is walking
	 * in circles, and with nothing starting or ending there it has neither a shortcut to take nor
	 * one to reverse back out of. Judged on its own so that it still holds when the wider question
	 * - does this ground join up with home - has been answered by a world the plugin has misread.
	 */
	boolean isSealedPocket(int x, int y, int plane)
	{
		int component = componentAt(x, y, plane);
		return component != 0 && isIsolated(x, y, plane)
			&& !touched.contains(component) && !ports.contains(component);
	}

	/**
	 * True if a golem here is somewhere it could not have walked to, or could not walk back from.
	 * A tile with no component is left alone, and so is everywhere until the spaces are linked.
	 */
	boolean isCutOff(int x, int y, int plane)
	{
		int component = componentAt(x, y, plane);
		if (component == 0 || fromHome == null)
		{
			return false;
		}
		return !fromHome[component];
	}

	/**
	 * Works out which spaces home can reach and which can reach home, over the transports and the
	 * docks known right now. Run once the tables are loaded, and again whenever a route is
	 * learned: a learned route is a way through that did not exist a moment ago.
	 */
	void linkSpaces(int homeX, int homeY, int homePlane)
	{
		int home = componentAt(homeX, homeY, homePlane);
		if (home == 0)
		{
			return;
		}

		boolean[] out = new boolean[1 << 16];
		walkSpaces(home, leadsTo, out);
		fromHome = out;

		int reached = 0;
		for (boolean space : out)
		{
			reached += space ? 1 : 0;
		}
		log.debug("{} spaces are home's own, of the {} the transports name", reached, leadsTo.size());
	}

	/** Spreads out from home over one direction of the graph, the sea counting as one hop. */
	private void walkSpaces(int home, Map<Integer, java.util.List<Integer>> edges, boolean[] seen)
	{
		java.util.Deque<Integer> queue = new ArrayDeque<>();
		seen[home] = true;
		queue.add(home);
		boolean sailed = false;

		while (!queue.isEmpty())
		{
			int at = queue.poll();

			// One port reached is every port reached: a golem that can board can land wherever a
			// boat goes, and the same backwards.
			if (!sailed && ports.contains(at))
			{
				sailed = true;
				for (int port : ports)
				{
					if (!seen[port])
					{
						seen[port] = true;
						queue.add(port);
					}
				}
			}

			java.util.List<Integer> next = edges.get(at);
			if (next == null)
			{
				continue;
			}
			for (int to : next)
			{
				if (!seen[to])
				{
					seen[to] = true;
					queue.add(to);
				}
			}
		}
	}

	/** Marks the space a dock's quayside stands in as a port, which the sea joins to every other. */
	void admitDockExit(int x, int y, int plane)
	{
		int component = componentAt(x, y, plane);
		if (component != 0)
		{
			ports.add(component);
		}
	}

	/** Admits the floor under a dock's quayside, if it is a floor at all. */
	void admitDockFloor(int x, int y, int plane)
	{
		if (x >= 6400 || isOcean(x, y, plane))
		{
			return;
		}
		int component = componentAt(x, y, plane);
		if (component != 0 && !dockFloors[component])
		{
			dockFloors[component] = true;
			admittedFloors += landComponents[component] ? 0 : 1;
		}
	}

	/**
	 * Floors counted as land because a transport starts or ends on them, beyond what the
	 * shipped land fill reached.
	 *
	 * <p>The fill was run offline from Lumbridge over the tables it was given, so a floor
	 * reachable only by a ladder no table lists has collision, a component and every wall
	 * but no land bit - Wyrmscraig's ladder tops, the cathedral basement, every place newer
	 * than the tables. A transport row is the same evidence the fill used. The exact end
	 * tile only: a stepping stone's tile is blocked, and snapping to the water beside it
	 * would admit a river as land.
	 */
	private final boolean[] landComponents = new boolean[1 << 16];

	/** Admits the floor under both ends of every transport. Replaces what was admitted before. */
	void admitTransportEnds(java.util.List<GolemTransport> transports)
	{
		Arrays.fill(landComponents, false);
		transportLeads.clear();
		transportTouched.clear();
		Map<Long, java.util.List<GolemTransport>> starting = new HashMap<>();
		for (GolemTransport t : transports)
		{
			starting.computeIfAbsent(tileKey(t.getFromX(), t.getFromY(), t.getFromPlane()),
				k -> new ArrayList<>()).add(t);
		}
		for (GolemTransport t : transports)
		{
			for (int from : spacesAt(t.getFromX(), t.getFromY(), t.getFromPlane()))
			{
				transportTouched.add(from);
				for (int to : spacesOnward(t.getToX(), t.getToY(), t.getToPlane(),
					t.getFromX(), t.getFromY(), t.getFromPlane(), TransportNetwork.CHAIN_HOPS, starting))
				{
					transportTouched.add(to);
					if (from != to)
					{
						transportLeads.computeIfAbsent(from, space -> new ArrayList<>()).add(to);
					}
				}
			}
		}
		transportFloors = 0;
		admittedFloors = 0;
		for (boolean dock : dockFloors)
		{
			admittedFloors += dock ? 1 : 0;
		}
		// Only ever asked whether it is nought, so an instance floor that is also a dock's counts twice.
		admittedFloors += instanceFloorList.size();
		for (GolemTransport t : transports)
		{
			admit(t.getFromX(), t.getFromY(), t.getFromPlane());
			admit(t.getToX(), t.getToY(), t.getToPlane());
		}
		// The walks between spaces are the island map's, not the tables': kept as they were, and laid
		// back over the rebuilt graph, so a route learned does not mean scanning the map again.
		composeLinks();
		log.debug("{} floors admitted as land from transport ends", transportFloors);
	}

	/** Space to the spaces a transport leads to, and every space one touches: the tables' half. */
	private final Map<Integer, java.util.List<Integer>> transportLeads = new HashMap<>();
	private final Set<Integer> transportTouched = new HashSet<>();

	/**
	 * The pairs of spaces each region's walks join, as {@link #pair} keys, and how many regions join
	 * each pair: a region read again replaces what it said, so a door found shut again un-joins its
	 * two spaces. Kept only in addition, a doorway seen open once stayed a way through all session.
	 */
	private final Map<Integer, Set<Long>> joinsByRegion = new HashMap<>();
	private final Map<Long, Integer> joinCount = new HashMap<>();

	private static long pair(int one, int other)
	{
		return (long) Math.min(one, other) << 16 | Math.max(one, other);
	}

	/**
	 * Lays the tables' links and the island map's walks together into {@link #leadsTo} and
	 * {@link #touched}, which linkSpaces reads, and {@link #walkedTo}, which WaysBack reads.
	 */
	private void composeLinks()
	{
		walkedTo.clear();
		for (long joined : joinCount.keySet())
		{
			int one = (int) (joined >> 16);
			int other = (int) (joined & 0xFFFF);
			walkedTo.computeIfAbsent(one, space -> new ArrayList<>()).add(other);
			walkedTo.computeIfAbsent(other, space -> new ArrayList<>()).add(one);
		}
		leadsTo.clear();
		for (Map.Entry<Integer, java.util.List<Integer>> e : transportLeads.entrySet())
		{
			leadsTo.put(e.getKey(), new ArrayList<>(e.getValue()));
		}
		touched.clear();
		touched.addAll(transportTouched);
		// Judged by the walks alone: a one-way transport already leading from one to the other says
		// nothing about the way back, which the walk does.
		for (Map.Entry<Integer, java.util.List<Integer>> walked : walkedTo.entrySet())
		{
			touched.add(walked.getKey());
			for (int to : walked.getValue())
			{
				addOnce(leadsTo.computeIfAbsent(walked.getKey(), space -> new ArrayList<>()), to);
			}
		}
		linkRevision++;
	}

	/**
	 * Joins spaces the island map walks between. Golems at home walk by the island map, which is
	 * live collision and has some doorways open that the shipped collision has shut; a golem walked
	 * through one into a room the mesh counts as a space of its own, and the cut-off sweep carried
	 * it home from a room beside the plinth. Wherever the island map steps from one space into
	 * another, the two are joined, both ways, as a transport would join them. Run over the regions
	 * just read, each of which replaces what it joined before.
	 *
	 * @return how many pairs of spaces were joined or parted
	 */
	int joinWhereWalked(IslandMemory memory, int[] regions)
	{
		int changed = 0;
		for (int region : regions)
		{
			int baseX = (region >> 8) << 6;
			int baseY = (region & 0xFF) << 6;
			Set<Long> now = new HashSet<>();
			for (int plane = 0; plane < 4; plane++)
			{
				// Where the island map holds nothing, it answers from this mesh, whose own edges made
				// the spaces: nothing there can join two.
				if (!memory.holds(region, plane))
				{
					continue;
				}
				for (int x = baseX; x < baseX + 64; x++)
				{
					for (int y = baseY; y < baseY + 64; y++)
					{
						int here = componentAt(x, y, plane);
						if (here == 0)
						{
							continue;
						}
						int north = memory.north(x, y, plane) ? componentAt(x, y + 1, plane) : 0;
						if (north != 0 && north != here)
						{
							now.add(pair(here, north));
						}
						int east = memory.east(x, y, plane) ? componentAt(x + 1, y, plane) : 0;
						if (east != 0 && east != here)
						{
							now.add(pair(here, east));
						}
					}
				}
			}
			Set<Long> before = joinsByRegion.getOrDefault(region, Collections.emptySet());
			for (long joined : now)
			{
				if (!before.contains(joined) && joinCount.merge(joined, 1, Integer::sum) == 1)
				{
					changed++;
				}
			}
			for (long joined : before)
			{
				if (!now.contains(joined) && joinCount.merge(joined, -1, Integer::sum) == 0)
				{
					joinCount.remove(joined);
					changed++;
				}
			}
			if (now.isEmpty())
			{
				joinsByRegion.remove(region);
			}
			else
			{
				joinsByRegion.put(region, now);
			}
		}
		// Only when something changed: run after every harvest, most runs change nothing, and each
		// change rebuilds what golems can get back from.
		if (changed > 0)
		{
			composeLinks();
		}
		log.debug("{} pairs of spaces joined or parted where the island map walks between them", changed);
		return changed;
	}

	/** Forgets every walk joined, for a fresh start from the whole island map. */
	void forgetWalks()
	{
		joinsByRegion.clear();
		joinCount.clear();
		composeLinks();
	}

	private static void addOnce(java.util.List<Integer> spaces, int space)
	{
		if (!spaces.contains(space))
		{
			spaces.add(space);
		}
	}

	/**
	 * The spaces a transport's end touches: its own, or - where it stands on blocked ground, as a
	 * door, a stile or a stepping stone does - the spaces around it. Nearly a third of the ends in
	 * the tables have no component of their own, and reading those as "leads nowhere" cut whole
	 * floors off from home.
	 *
	 * <p>Generous on purpose. Joining two spaces that a golem cannot really walk between leaves a
	 * golem where it stands; refusing to join two that it can carries one home from somewhere it
	 * belonged.
	 */
	/**
	 * The spaces a transport's end touches, following a chain on from an end that touches none -
	 * a stepping stone mid-river, all water round it - as TransportNetwork.leadsToGround does.
	 */
	java.util.List<Integer> spacesOnward(int x, int y, int plane, int cameX, int cameY, int camePlane,
		int hops, Map<Long, java.util.List<GolemTransport>> starting)
	{
		java.util.List<Integer> here = spacesAt(x, y, plane);
		if (!here.isEmpty() || hops <= 0)
		{
			return here;
		}
		java.util.List<Integer> found = new ArrayList<>(2);
		for (GolemTransport onward : starting.getOrDefault(tileKey(x, y, plane), Collections.emptyList()))
		{
			if (onward.getToX() == cameX && onward.getToY() == cameY && onward.getToPlane() == camePlane)
			{
				continue;
			}
			for (int space : spacesOnward(onward.getToX(), onward.getToY(), onward.getToPlane(), x, y, plane,
				hops - 1, starting))
			{
				if (!found.contains(space))
				{
					found.add(space);
				}
			}
		}
		return found;
	}

	static long tileKey(int x, int y, int plane)
	{
		return ((long) plane << 32) | ((long) x << 16) | y;
	}

	java.util.List<Integer> spacesAt(int x, int y, int plane)
	{
		int own = componentAt(x, y, plane);
		if (own != 0)
		{
			return Collections.singletonList(own);
		}
		java.util.List<Integer> around = new ArrayList<>(4);
		for (int dx = -1; dx <= 1; dx++)
		{
			for (int dy = -1; dy <= 1; dy++)
			{
				int space = componentAt(x + dx, y + dy, plane);
				if (space != 0 && !around.contains(space))
				{
					around.add(space);
				}
			}
		}
		return around;
	}

	private void admit(int x, int y, int plane)
	{
		// Instances are rebuilt each visit; their coordinates name no lasting floor.
		if (x >= 6400 || isLand(x, y, plane) || isOcean(x, y, plane))
		{
			return;
		}
		int component = componentAt(x, y, plane);
		if (component != 0 && !landComponents[component])
		{
			landComponents[component] = true;
			transportFloors++;
			admittedFloors += dockFloors[component] ? 0 : 1;
		}
	}

	private boolean flag(int x, int y, int plane, int which)
	{
		Region region = region(regionIdOf(x, y), plane);
		if (region == null)
		{
			return false;
		}
		return (region.collision[(y & REGION_MASK) * REGION_SIZE + (x & REGION_MASK)] >>> which & 1) != 0;
	}

	/** The land fill's bit for this tile. */
	private boolean isLand(int x, int y, int plane)
	{
		Region region = region(regionIdOf(x, y), plane);
		return region != null && bit(region.land, x, y);
	}

	private Region region(int regionId, int plane)
	{
		if (regionId >= 0 && regionId < FAST_REGIONS && (plane & 0xF) < 4)
		{
			int at = regionId << 2 | (plane & 0xF);
			Region region = byRegion[at];
			return region != null || !packedAt[at] ? region : unpack(regionId, plane);
		}
		Region region = regions.get(key(regionId, plane));
		return region != null || !packed.containsKey(key(regionId, plane)) ? region : unpack(regionId, plane);
	}

	/**
	 * Region-planes no fill reached, each deflated on its own, by key: most of the world, and
	 * nowhere a golem goes until a learned route leads there. Unpacked on first use and kept.
	 */
	private final Map<Long, byte[]> packed = new HashMap<>();

	/** Whether {@link #packed} holds a region-plane, indexed as {@link #byRegion}. */
	private final boolean[] packedAt = new boolean[FAST_REGIONS << 2];

	/** True once the mesh holds any square at all: a mesh that failed to load knows nothing. */
	boolean holdsAnySquare()
	{
		return !regions.isEmpty() || !packed.isEmpty();
	}

	/**
	 * True if the game has this map square on any floor: it is in the mesh, read or packed. Under the
	 * lock unpack holds, which moves a region-plane from packed to read: asked mid-move, a square
	 * was in neither, and the saved map dropped real ground as a square that does not exist.
	 */
	synchronized boolean hasSquare(int regionId)
	{
		for (int plane = 0; plane < 4; plane++)
		{
			long key = key(regionId, plane);
			if (regions.containsKey(key) || packed.containsKey(key))
			{
				return true;
			}
		}
		return false;
	}

	/** Unpacks a packed region-plane into the mesh, once; null if it will not read. */
	private synchronized Region unpack(int regionId, int plane)
	{
		long key = key(regionId, plane);
		Region region = regions.get(key);
		byte[] blob = packed.remove(key);
		if (region != null || blob == null)
		{
			return region;
		}
		try (DataInputStream data = new DataInputStream(new InflaterInputStream(new ByteArrayInputStream(blob))))
		{
			region = readRecord(data);
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("World mesh region {} plane {} unreadable", regionId, plane, e);
			region = null;
		}
		if (region != null)
		{
			put(regionId, plane, region);
		}
		if (regionId >= 0 && regionId < FAST_REGIONS && (plane & 0xF) < 4)
		{
			packedAt[regionId << 2 | (plane & 0xF)] = false;
		}
		return region;
	}

	/** One region-plane's record: the tile bytes, ocean, isolated, components, land, water. */
	private static Region readRecord(DataInputStream data) throws IOException
	{
		byte[] flags = new byte[COLLISION_BYTES];
		data.readFully(flags);
		byte[] sea = new byte[DERIVED_BYTES];
		data.readFully(sea);
		byte[] alone = new byte[DERIVED_BYTES];
		data.readFully(alone);
		byte[] parts = new byte[COMPONENT_BYTES];
		data.readFully(parts);
		byte[] ground = new byte[DERIVED_BYTES];
		data.readFully(ground);
		byte[] wet = new byte[DERIVED_BYTES];
		data.readFully(wet);
		int[] palette = palette(parts);
		if (palette == null)
		{
			char[] wide = new char[TILES_PER_PLANE];
			for (int tile = 0; tile < TILES_PER_PLANE; tile++)
			{
				wide[tile] = (char) (((parts[tile * 2] & 0xFF) << 8) | (parts[tile * 2 + 1] & 0xFF));
			}
			return new Region(flags, sea, alone, null, new int[1], wide, ground, wet);
		}
		return new Region(flags, sea, alone, indexInto(parts, palette), palette, null, ground, wet);
	}

	private void put(int regionId, int plane, Region region)
	{
		regions.put(key(regionId, plane), region);
		if (regionId >= 0 && regionId < FAST_REGIONS && (plane & 0xF) < 4)
		{
			byRegion[regionId << 2 | (plane & 0xF)] = region;
		}
	}

	private static boolean bit(byte[] bits, int x, int y)
	{
		int bit = (y & REGION_MASK) * REGION_SIZE + (x & REGION_MASK);
		return (bits[bit >> 3] >>> (bit & 7) & 1) != 0;
	}

	private static int componentOf(Region region, int x, int y)
	{
		int tile = (y & REGION_MASK) * REGION_SIZE + (x & REGION_MASK);
		if (region.wide != null)
		{
			return region.wide[tile];
		}
		return region.palette[region.components == null ? 0 : region.components[tile] & 0xFF];
	}

	/** The distinct component ids in a region-plane's two-byte map, in order of first use; null past 256. */
	private static int[] palette(byte[] parts)
	{
		int[] ids = new int[256];
		int count = 0;
		int last = -1;
		for (int tile = 0; tile < TILES_PER_PLANE; tile++)
		{
			int id = ((parts[tile * 2] & 0xFF) << 8) | (parts[tile * 2 + 1] & 0xFF);
			// Neighbours along a row are nearly always one space: the scan is for the change.
			if (id == last)
			{
				continue;
			}
			last = id;
			int i = 0;
			while (i < count && ids[i] != id)
			{
				i++;
			}
			if (i == count)
			{
				if (count == ids.length)
				{
					// More than a byte can index: this region-plane keeps its ids outright.
					return null;
				}
				ids[count++] = id;
			}
		}
		return Arrays.copyOf(ids, count);
	}

	/** Each tile's index into the palette; null when there is only one id. */
	private static byte[] indexInto(byte[] parts, int[] palette)
	{
		if (palette.length == 1)
		{
			return null;
		}
		byte[] index = new byte[TILES_PER_PLANE];
		int last = palette[0];
		int at = 0;
		for (int tile = 0; tile < TILES_PER_PLANE; tile++)
		{
			int id = ((parts[tile * 2] & 0xFF) << 8) | (parts[tile * 2 + 1] & 0xFF);
			if (id != last)
			{
				at = 0;
				while (palette[at] != id)
				{
					at++;
				}
				last = id;
			}
			index[tile] = (byte) at;
		}
		return index;
	}

	private static int regionIdOf(int x, int y)
	{
		return ((x >> 6) << 8) | (y >> 6);
	}

	private static long key(int regionId, int plane)
	{
		return ((long) regionId << 4) | (plane & 0xF);
	}
}

package com.golemsdontdie.telemetry;

import lombok.*;

/**
 * One crossing of an obstacle by a golem the player could see, as it is kept on disk.
 *
 * <p>The route is the pair of tiles the golem was meant to cross between; the positions are where it
 * actually was, frame by frame. {@link ObstacleDataFile} measures those against the route, the same
 * way a player's path is measured, so the two can be compared directly.
 *
 * <p>Positions are world coordinates in 128ths of a tile; times are client cycles (20 ms).
 */
@AllArgsConstructor
public final class GolemCrossing
{
	/** The scene object crossed. */
	public final int objectId;

	/** The tile the route starts from and the tile it ends on: x, y and floor. */
	public final int fromX;
	public final int fromY;
	public final int fromPlane;
	public final int toX;
	public final int toY;
	public final int toPlane;

	/** Where the golem was at each frame of the crossing: {cycle, x, y}. First and last included. */
	public final int[][] positions;

	/** True if the route passed over a tile another short hop starts on: a stepping stone skipped. */
	public final boolean overStone;
}

package com.golemsdontdie.telemetry;

import java.io.*;
import java.util.*;
import lombok.extern.slf4j.*;

/**
 * The obstacle data file: {@value #FILE_NAME} in the plugin's own folder.
 *
 * <p>Tab-separated text, readable in any spreadsheet. Lines starting {@code #} describe the file;
 * {@code P} lines are crossings by the player, {@code G} lines crossings by golems. Column names are
 * written into the file above each kind.
 *
 * <p>One line per distinct crossing. The same crossing again adds to its count instead of adding a
 * line; past {@link #MAX_LINES} of a kind, the one seen least recently is dropped. So the file stays
 * small however long the plugin is used.
 *
 * <p>Nothing here sends anything. See the package documentation for what is kept and why.
 */
@Slf4j
public final class ObstacleDataFile
{
	public static final String FILE_NAME = "golem-obstacle-data.tsv";

	/** Bumped whenever a column changes. A file from another schema is replaced, not misread. */
	static final int SCHEMA = 3;

	/** Lines kept of each kind. */
	static final int MAX_LINES = 2000;

	/** Points kept of any one path. A longer path is thinned evenly, keeping its first and last. */
	static final int PATH_POINTS = 60;

	/** 128ths of a tile in a tile. */
	private static final int TILE = 128;

	private static final String PLAYER_COLUMNS = "#P\tobject\tname\tmenu\tanimations\tticks\tmoveDelay\tmoveSpan"
		+ "\tfromX\tfromY\tfromPlane\ttoX\ttoY\ttoPlane\tlineX\tlineY\tinstance\tseen\tfacing"
		+ "\tanimationChanges\tpath";

	private static final String GOLEM_COLUMNS = "#G\tobject\tfromX\tfromY\tfromPlane\ttoX\ttoY\ttoPlane"
		+ "\tattempts\tworstSide\tworstLanding\tworstStart\toverStone\tpath";

	/** Where each counted column of a line is, looked up by its name in the headers above. */
	private static final int P_SEEN = column(PLAYER_COLUMNS, "seen");
	private static final int G_ATTEMPTS = column(GOLEM_COLUMNS, "attempts");
	private static final int G_WORST_SIDE = column(GOLEM_COLUMNS, "worstSide");
	private static final int G_WORST_LANDING = column(GOLEM_COLUMNS, "worstLanding");
	private static final int G_WORST_START = column(GOLEM_COLUMNS, "worstStart");
	private static final int G_OVER_STONE = column(GOLEM_COLUMNS, "overStone");

	/**
	 * Where the file is kept. In play, the plugin's own folder, through RuneLite's file utility, which
	 * is the only way a plugin touches the disk. In a test, a string in memory.
	 */
	public interface Store
	{
		boolean exists();

		BufferedReader reader() throws IOException;

		/** Replaces the whole file with this text. */
		void write(String text) throws IOException;
	}

	private final Store store;
	private final String pluginVersion;

	/** Lines by crossing, least recently seen first. The first column (P or G) is not stored. */
	private final Map<String, String[]> player = new LinkedHashMap<>(64, 0.75f, true);
	private final Map<String, String[]> golem = new LinkedHashMap<>(64, 0.75f, true);

	private boolean changed;

	public ObstacleDataFile(Store store, String pluginVersion)
	{
		this.store = store;
		this.pluginVersion = pluginVersion;
	}

	// ------------------------------------------------------------------ reading and writing

	/** Reads the file, if there is one. An unreadable file or another schema starts afresh. */
	public void load()
	{
		player.clear();
		golem.clear();
		changed = false;
		try
		{
			if (!store.exists())
			{
				return;
			}
		}
		catch (RuntimeException e)
		{
			log.warn("Could not look for the obstacle data file", e);
			return;
		}
		try (BufferedReader in = store.reader())
		{
			boolean sameSchema = false;
			String line;
			while ((line = in.readLine()) != null)
			{
				String[] columns = line.split("\t", -1);
				if (columns[0].equals("#schema"))
				{
					sameSchema = columns.length > 1 && columns[1].equals(String.valueOf(SCHEMA));
				}
				else if (sameSchema && columns[0].equals("P") && columns.length == columnCount(PLAYER_COLUMNS))
				{
					String[] row = withoutKind(columns);
					player.put(playerKey(row), row);
				}
				else if (sameSchema && columns[0].equals("G") && columns.length == columnCount(GOLEM_COLUMNS))
				{
					String[] row = withoutKind(columns);
					golem.put(golemKey(row), row);
				}
			}
		}
		catch (IOException | RuntimeException e)
		{
			player.clear();
			golem.clear();
			log.warn("Obstacle data unreadable; starting a fresh file", e);
		}
	}

	/** Writes the file, if anything has been added since it was last written. */
	public void save()
	{
		if (!changed)
		{
			return;
		}
		changed = false;
		StringBuilder out = new StringBuilder();
		out.append("# Golems Don't Die obstacle data. Kept on this computer; nothing in it is sent anywhere.\n");
		out.append("# P lines: crossings of obstacles by the player. G lines: crossings by golems.\n");
		out.append("# Distances in 128ths of a tile, times in 20 ms client cycles unless named otherwise.\n");
		out.append("# A path is cycle:along:side, measured from the start tile towards the end tile.\n");
		out.append("#schema\t").append(SCHEMA).append('\n');
		out.append("#plugin\t").append(pluginVersion).append('\n');
		out.append(PLAYER_COLUMNS).append('\n');
		for (String[] row : player.values())
		{
			out.append("P\t").append(String.join("\t", row)).append('\n');
		}
		out.append(GOLEM_COLUMNS).append('\n');
		for (String[] row : golem.values())
		{
			out.append("G\t").append(String.join("\t", row)).append('\n');
		}
		try
		{
			store.write(out.toString());
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Could not write the obstacle data file", e);
		}
	}

	// ------------------------------------------------------------------ adding crossings

	/** Adds a crossing by the player, or counts another of one already kept. */
	public void add(PlayerCrossing c)
	{
		String[] row = {
			String.valueOf(c.objectId), text(c.name), text(c.menu), list(c.animations),
			String.valueOf(c.ticks), String.valueOf(c.moveDelay), String.valueOf(c.moveSpan),
			String.valueOf(c.fromX), String.valueOf(c.fromY), String.valueOf(c.fromPlane),
			String.valueOf(c.toX), String.valueOf(c.toY), String.valueOf(c.toPlane),
			String.valueOf(c.lineX), String.valueOf(c.lineY), c.instance ? "1" : "0",
			"1", String.valueOf(c.facing), pairs(c.animationChanges), path(c.path),
		};
		// The newest recording of a crossing replaces the old one; only the count carries over.
		String[] kept = player.get(playerKey(row));
		if (kept != null)
		{
			row[P_SEEN] = String.valueOf(number(kept[P_SEEN]) + 1);
		}
		put(player, playerKey(row), row);
	}

	/** Adds a crossing by a golem, or counts another on a route already kept. */
	public void add(GolemCrossing c)
	{
		// The route is the straight line between the middles of its two tiles.
		int fromX = c.fromX * TILE + TILE / 2;
		int fromY = c.fromY * TILE + TILE / 2;
		int toX = c.toX * TILE + TILE / 2;
		int toY = c.toY * TILE + TILE / 2;

		int[][] measured = new int[c.positions.length][];
		int worstSide = 0;
		for (int i = 0; i < c.positions.length; i++)
		{
			int[] p = c.positions[i];
			int[] alongSide = alongAndSide(p[1] - fromX, p[2] - fromY, toX - fromX, toY - fromY);
			measured[i] = new int[]{p[0], alongSide[0], alongSide[1]};
			worstSide = Math.max(worstSide, Math.abs(alongSide[1]));
		}
		int[] first = c.positions.length > 0 ? c.positions[0] : new int[]{0, fromX, fromY};
		int[] last = c.positions.length > 0 ? c.positions[c.positions.length - 1] : first;
		int start = distance(first[1] - fromX, first[2] - fromY);
		int landing = distance(last[1] - toX, last[2] - toY);

		String[] row = {
			String.valueOf(c.objectId),
			String.valueOf(c.fromX), String.valueOf(c.fromY), String.valueOf(c.fromPlane),
			String.valueOf(c.toX), String.valueOf(c.toY), String.valueOf(c.toPlane),
			"1", String.valueOf(worstSide), String.valueOf(landing), String.valueOf(start),
			c.overStone ? "1" : "0", path(measured),
		};
		// The newest path replaces the old; counts add up, and the worst of each measure is kept,
		// because the worst crossing is the one that needs fixing.
		String[] kept = golem.get(golemKey(row));
		if (kept != null)
		{
			row[G_ATTEMPTS] = String.valueOf(number(kept[G_ATTEMPTS]) + 1);
			row[G_WORST_SIDE] = String.valueOf(Math.max(worstSide, number(kept[G_WORST_SIDE])));
			row[G_WORST_LANDING] = String.valueOf(Math.max(landing, number(kept[G_WORST_LANDING])));
			row[G_WORST_START] = String.valueOf(Math.max(start, number(kept[G_WORST_START])));
			row[G_OVER_STONE] = String.valueOf(number(kept[G_OVER_STONE]) + (c.overStone ? 1 : 0));
		}
		put(golem, golemKey(row), row);
	}

	public int playerLines()
	{
		return player.size();
	}

	public int golemLines()
	{
		return golem.size();
	}

	// ------------------------------------------------------------------ helpers

	private void put(Map<String, String[]> lines, String key, String[] row)
	{
		lines.put(key, row);
		while (lines.size() > MAX_LINES)
		{
			lines.remove(lines.keySet().iterator().next());
		}
		changed = true;
	}

	/** A player crossing is the object, what it played, and its two tiles. */
	private static String playerKey(String[] row)
	{
		return row[0] + "|" + row[3] + "|" + row[7] + "," + row[8] + "," + row[9] + ">" + row[10] + "," + row[11]
			+ "," + row[12];
	}

	/** A golem crossing is the object and its two tiles. */
	private static String golemKey(String[] row)
	{
		return row[0] + "|" + row[1] + "," + row[2] + "," + row[3] + ">" + row[4] + "," + row[5] + "," + row[6];
	}

	/**
	 * A point measured along a line and to its side: {along, side}. Along is the distance towards
	 * the line's end, side the distance off it, negative to the left.
	 */
	static int[] alongAndSide(int x, int y, int lineX, int lineY)
	{
		double length = Math.hypot(lineX, lineY);
		if (length == 0)
		{
			return new int[]{0, distance(x, y)};
		}
		double ux = lineX / length;
		double uy = lineY / length;
		return new int[]{(int) Math.round(x * ux + y * uy), (int) Math.round(x * uy - y * ux)};
	}

	private static int distance(int x, int y)
	{
		return (int) Math.round(Math.hypot(x, y));
	}

	/** A path as cycle:along:side entries, thinned evenly to {@link #PATH_POINTS}. */
	private static String path(int[][] points)
	{
		StringBuilder sb = new StringBuilder();
		if (points == null)
		{
			return "";
		}
		int step = Math.max(1, (points.length + PATH_POINTS - 1) / PATH_POINTS);
		for (int i = 0; i < points.length; i++)
		{
			if (i % step == 0 || i == points.length - 1)
			{
				sb.append(sb.length() == 0 ? "" : ",")
					.append(points[i][0]).append(':').append(points[i][1]).append(':').append(points[i][2]);
			}
		}
		return sb.toString();
	}

	/** {a, b} pairs as a:b entries. */
	private static String pairs(int[][] values)
	{
		StringBuilder sb = new StringBuilder();
		if (values != null)
		{
			for (int[] pair : values)
			{
				sb.append(sb.length() == 0 ? "" : ",").append(pair[0]).append(':').append(pair[1]);
			}
		}
		return sb.toString();
	}

	private static String list(int[] values)
	{
		StringBuilder sb = new StringBuilder();
		if (values != null)
		{
			for (int value : values)
			{
				sb.append(sb.length() == 0 ? "" : ",").append(value);
			}
		}
		return sb.toString();
	}

	/** Game text with anything that would break a line or a column taken out. */
	private static String text(String value)
	{
		return value == null ? "" : value.replace('\t', ' ').replace('\n', ' ').replace('\r', ' ');
	}

	private static int number(String value)
	{
		try
		{
			return Integer.parseInt(value);
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}

	/** A named column's place in a stored line, which leaves out the header's first column (#P or #G). */
	private static int column(String header, String name)
	{
		String[] names = header.split("	");
		for (int i = 1; i < names.length; i++)
		{
			if (names[i].equals(name))
			{
				return i - 1;
			}
		}
		throw new IllegalArgumentException("no column " + name);
	}

	private static int columnCount(String header)
	{
		return header.split("\t").length;
	}

	private static String[] withoutKind(String[] columns)
	{
		String[] row = new String[columns.length - 1];
		System.arraycopy(columns, 1, row, 0, row.length);
		return row;
	}
}

package com.golemsdontdie.telemetry;

import lombok.*;

/**
 * One crossing of an obstacle by the player, as it is kept on disk.
 *
 * <p>Plain numbers and the game's own text for the object. Positions are world tiles of the obstacle
 * itself; the path across it is measured relative to them, so it says how the obstacle moves a
 * player and nothing about where the player was otherwise.
 *
 * <p>Distances are in 128ths of a tile and times in client cycles (20 ms) unless a field says
 * otherwise - the units the game animates in.
 */
@AllArgsConstructor
public final class PlayerCrossing
{
	/** The scene object used. */
	public final int objectId;

	/** The object's name, from the game cache. */
	public final String name;

	/** The menu option and target, e.g. "Climb-over Stile". */
	public final String menu;

	/** Every animation played, in order. */
	public final int[] animations;

	/** Game ticks (600 ms) from the first animation starting to standing still somewhere new. */
	public final int ticks;

	/** Cycles from the first animation starting until the player first moved. */
	public final int moveDelay;

	/** Cycles the movement itself lasted. */
	public final int moveSpan;

	/** The tile the crossing starts from and the tile it ends on: x, y and floor. */
	public final int fromX;
	public final int fromY;
	public final int fromPlane;
	public final int toX;
	public final int toY;
	public final int toPlane;

	/** How far the obstacle itself moved the player, in whole tiles east and north. */
	public final int lineX;
	public final int lineY;

	/** True if it happened inside an instance, whose coordinates are not the world's. */
	public final boolean instance;

	/**
	 * The path across, one entry every two cycles: {cycle, along, side}. Along is the distance
	 * towards the far tile, side the distance off to the left (negative) or right of the straight
	 * line between the two tiles. Empty if it could not be recorded.
	 */
	public final int[][] path;

	/** Each point the animation changed: {cycle, animation}. */
	public final int[][] animationChanges;

	/** Which way the player faced relative to the way they moved, 0 to 2047 (1024 is backwards); -1 unknown. */
	public final int facing;
}

package com.golemsdontdie;

import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.assertEquals;

/** Which golem was crafted when: oldest first, given once and kept. */
public class CraftNumbersTest
{
	private static final WorldPoint PLINTH = new WorldPoint(2596, 2256, 0);

	private static Golem golem(long seed)
	{
		GolemSnapshot snapshot = new GolemSnapshot(1234, "Golem", new int[0], new short[0], new short[0],
			128, 128, 1, -1, -1, -1, PLINTH, 0);
		return Golem.onTile(snapshot, PLINTH, seed, PLINTH);
	}

	/**
	 * A roster restored for the first time: two with dates, out of order in the save, and two from
	 * before dates were kept, which are older than both and keep the save's order between them.
	 */
	@Test
	public void theOldestComeFirst()
	{
		Golem newer = golem(1);
		Golem undatedA = golem(2);
		Golem older = golem(3);
		Golem undatedB = golem(4);
		Map<Golem, Long> age = new HashMap<>();
		age.put(newer, 2_000L);
		age.put(undatedA, 0L);
		age.put(older, 1_000L);
		age.put(undatedB, 0L);

		assertEquals(4, CraftNumbers.number(Arrays.asList(newer, undatedA, older, undatedB), age::get));

		assertEquals(1, undatedA.getCraftNumber());
		assertEquals(2, undatedB.getCraftNumber());
		assertEquals(3, older.getCraftNumber());
		assertEquals(4, newer.getCraftNumber());
	}

	/** A number once given is kept; a new golem takes the one after the highest, gaps and all. */
	@Test
	public void aNewGolemComesNext()
	{
		Golem first = golem(1);
		first.setCraftNumber(1);
		Golem kept = golem(2);
		kept.setCraftNumber(453);
		Golem crafted = golem(3);
		List<Golem> roster = Arrays.asList(first, kept, crafted);

		assertEquals(1, CraftNumbers.number(roster, golem -> 0L));
		assertEquals(1, first.getCraftNumber());
		assertEquals(453, kept.getCraftNumber());
		assertEquals(454, crafted.getCraftNumber());
		assertEquals("nothing left to number", 0, CraftNumbers.number(roster, golem -> 0L));
	}
}

package com.golemsdontdie;

import java.lang.reflect.Field;
import java.util.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** A golem is not turned straight back into a space it just left, and a doorway is no shortcut. */
public class GoingBackTest
{
	/**
	 * A space per thousand tiles of x on the ground floor, with x = 2000 a wall between spaces 1
	 * and 2: a tile no space holds, as a ladder set in a wall is.
	 */
	private static final class Spaces extends WorldMesh
	{
		@Override
		int componentAt(int x, int y, int plane)
		{
			return plane == 0 && x > 0 && x != 2000 ? x / 1000 : 0;
		}
	}

	private TransportNetwork network;
	private RoamPlanner planner;

	@Before
	public void build() throws ReflectiveOperationException
	{
		network = new TransportNetwork();
		network.setLearnedRoutes(Arrays.asList(
			new int[]{1, 1500, 100, 0, 3500, 100, 0, 1},
			new int[]{2, 3500, 100, 0, 1500, 100, 0, 1},
			new int[]{3, 3500, 100, 0, 2500, 100, 0, 1},
			new int[]{4, 2000, 100, 0, 3600, 100, 0, 1}));
		planner = new RoamPlanner();
		Field mesh = RoamPlanner.class.getDeclaredField("mesh");
		mesh.setAccessible(true);
		mesh.set(planner, new Spaces());
	}

	private GolemTransport row(int fromX, int toX)
	{
		for (GolemTransport t : network.all())
		{
			if (t.getFromX() == fromX && t.getToX() == toX)
			{
				return t;
			}
		}
		throw new AssertionError("no row " + fromX + " to " + toX);
	}

	/** From space 1 into space 3, the way back into 1 is barred and the way on into 2 is not. */
	@Test
	public void notStraightBackIntoTheSpaceJustLeft()
	{
		TransportMemory memory = new TransportMemory();
		memory.used(row(1500, 3500), 0);
		Set<Integer> left = planner.spacesLeft(3500, 100, 0, 10, memory);
		assertEquals(Collections.singleton(1), left);
		assertTrue(planner.leadsInto(left, row(3500, 1500)));
		assertFalse(planner.leadsInto(left, row(3500, 2500)));
	}

	/** A start in a wall between two spaces bars neither: the golem stood in only one of them. */
	@Test
	public void aStartBetweenTwoSpacesBarsNeither()
	{
		TransportMemory memory = new TransportMemory();
		memory.used(row(2000, 3600), 0);
		assertTrue(planner.spacesLeft(3600, 100, 0, 10, memory).isEmpty());
	}

	/** A doorway walked through is remembered both ways, but is no shortcut to rest after. */
	@Test
	public void aDoorwayIsRememberedButNotRestedAfter()
	{
		TransportMemory memory = new TransportMemory();
		memory.walkedThrough(row(1500, 3500), 0);
		assertFalse(memory.restingFromTransports(1));
		assertTrue(memory.onCooldown(row(1500, 3500), 1));
		assertTrue(memory.onCooldown(row(3500, 1500), 1));

		memory.used(row(3500, 2500), 2);
		assertTrue(memory.restingFromTransports(3));
	}
}

package com.golemsdontdie;

import org.junit.Test;
import static org.junit.Assert.assertTrue;

/** Every golem on a boat stands on its deck. */
public class GolemBoatTest
{
	/**
	 * Berths are measured forward of the golem steering, which stands a tile before a tiller: each
	 * must land inside its own hull, the helmsman's included.
	 */
	@Test
	public void everyBerthIsOnItsHull()
	{
		for (GolemBoat boat : GolemBoat.values())
		{
			for (int[] berth : boat.getDeck())
			{
				// A starboard berth is model -x, measured from where the helmsman stands across.
				int across = boat.getSteerAcross() - berth[0];
				int along = boat.getSteerOffset() - berth[1];
				assertTrue(boat + " berth " + berth[0] + "," + berth[1] + " off the side",
					across >= boat.getHullMinX() && across <= boat.getHullMaxX());
				assertTrue(boat + " berth " + berth[0] + "," + berth[1] + " off the end",
					along >= boat.getHullMinZ() && along <= boat.getHullMaxZ());
			}
		}
	}
}

package com.golemsdontdie;

import java.lang.reflect.Field;
import net.runelite.api.Skill;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * What the golems dance about. The awkward half is what they must <em>not</em> dance about: every
 * level arrives at login, and the golem count arrives with it.
 */
public class GolemCelebrationTest
{
	/**
	 * Settings with every celebration on, so the tests are about the events and not the config.
	 * Golems crafted is the one that ships off.
	 */
	private static class AllOn implements GolemsDontDieConfig
	{
		@Override
		public boolean danceOnGolemCrafted()
		{
			return true;
		}

		@Override
		public boolean danceOnClue()
		{
			return true;
		}
	}

	private GolemCelebration celebration;

	@Before
	public void setUp() throws Exception
	{
		celebration = new GolemCelebration();
		setConfig(new AllOn());
	}

	private void setConfig(GolemsDontDieConfig config) throws Exception
	{
		Field field = GolemCelebration.class.getDeclaredField("config");
		field.setAccessible(true);
		field.set(celebration, config);
	}

	@Test
	public void aLevelGoingUpStartsTheDancing()
	{
		celebration.statChanged(Skill.MINING, 41, 100);
		assertFalse("the first sighting is not a level-up", celebration.isDancing(100));

		celebration.statChanged(Skill.MINING, 42, 100);
		assertTrue(celebration.isDancing(100));
		assertTrue("and it lasts a few seconds", celebration.isDancing(110));
		assertFalse("but not for ever", celebration.isDancing(200));
	}

	@Test
	public void experienceWithoutALevelIsNotWorthDancingAbout()
	{
		celebration.statChanged(Skill.MINING, 41, 100);
		celebration.statChanged(Skill.MINING, 41, 101);
		celebration.statChanged(Skill.MINING, 41, 102);
		assertFalse(celebration.isDancing(102));
	}

	/** Logging in reports every level and the golem count; none of that is news. */
	@Test
	public void loggingInIsNotACelebration()
	{
		for (Skill skill : Skill.values())
		{
			celebration.statChanged(skill, 70, 1);
		}
		celebration.golemCount(452, 1);
		assertFalse(celebration.isDancing(1));
	}

	@Test
	public void aGolemCraftedStartsTheDancing()
	{
		celebration.golemCount(452, 100);
		assertFalse(celebration.isDancing(100));
		celebration.golemCount(453, 100);
		assertTrue(celebration.isDancing(100));
	}

	@Test
	public void aCollectionLogEntryStartsTheDancing()
	{
		celebration.chatMessage("You have been awarded a pet!", 100);
		assertFalse(celebration.isDancing(100));
		celebration.chatMessage("New item added to your collection log: Abyssal whip", 100);
		assertTrue(celebration.isDancing(100));
	}

	/** Two things at once is one celebration, and the second does not cut the first short. */
	@Test
	public void aSecondCelebrationKeepsThemDancing()
	{
		celebration.statChanged(Skill.MINING, 41, 100);
		celebration.statChanged(Skill.MINING, 42, 100);
		celebration.statChanged(Skill.FISHING, 50, 108);
		celebration.statChanged(Skill.FISHING, 51, 108);
		assertTrue("still going at the first one's end", celebration.isDancing(117));
		assertTrue(celebration.isDancing(124));
	}

	@Test
	public void aSettingTurnedOffKeepsThemStill() throws Exception
	{
		setConfig(new GolemsDontDieConfig()
		{
			@Override
			public boolean danceOnLevelUp()
			{
				return false;
			}
		});
		celebration.statChanged(Skill.MINING, 41, 100);
		celebration.statChanged(Skill.MINING, 42, 100);
		assertFalse(celebration.isDancing(100));
	}

	/** A world hop restarts the tick counter, so a deadline in the old one must not be kept. */
	@Test
	public void hoppingWorldsForgetsEverything()
	{
		celebration.statChanged(Skill.MINING, 41, 5000);
		celebration.statChanged(Skill.MINING, 42, 5000);
		assertTrue(celebration.isDancing(5000));

		celebration.reset();
		assertFalse(celebration.isDancing(1));
		celebration.statChanged(Skill.MINING, 42, 1);
		assertFalse("and the level it already had is news to nobody", celebration.isDancing(1));
	}

	/** The game's own lines for the other occasions, colour tags and all. */
	@Test
	public void theOtherOccasionsAreRecognised()
	{
		String[] lines = {
			"Congratulations, you've completed a hard combat task: <col=06600c>Whack-a-Mole</col>.",
			"You have a funny feeling like you're being followed.",
			"Fight duration: <col=ff0000>1:23.40</col> (new personal best)",
			"You have completed <col=ef1020>12</col> medium Treasure Trails.",
		};
		int tick = 100;
		for (String line : lines)
		{
			tick += 100;
			celebration.chatMessage(line, tick);
			assertTrue(line, celebration.isDancing(tick));
		}
	}

	/** And an ordinary line is not an occasion. */
	@Test
	public void anOrdinaryLineIsNot()
	{
		celebration.chatMessage("You manage to mine some copper.", 100);
		celebration.chatMessage("Your Zulrah kill count is: <col=ff0000>12</col>.", 100);
		assertFalse(celebration.isDancing(100));
	}

	/** The pop-ups come whether or not the chat lines are on. */
	@Test
	public void aPopUpIsEnough()
	{
		celebration.popup("Collection log", 100);
		assertTrue(celebration.isDancing(100));
		celebration.popup("Combat Task Completed!", 300);
		assertTrue(celebration.isDancing(300));
		celebration.popup("Something else", 500);
		assertFalse(celebration.isDancing(500));
	}

	@Test
	public void aQuestIsWorthDancingAbout()
	{
		celebration.questCompleted(100);
		assertTrue(celebration.isDancing(100));
	}

	/**
	 * A diary tier already finished at login is not finished again: the first reads are where the
	 * player already stood, and only a tier that goes from not done to done afterwards counts.
	 */
	@Test
	public void aDiaryCountsOnlyWhenItIsFinished()
	{
		int[] atLogin = new int[GolemCelebration.DIARY_TIERS.length];
		atLogin[0] = 1;
		celebration.diaries(atLogin, 10);
		celebration.diaries(atLogin, 15);
		celebration.diaries(atLogin, 20);
		assertFalse("already done at login", celebration.isDancing(20));

		int[] later = atLogin.clone();
		later[5] = 1;
		celebration.diaries(later, 25);
		assertTrue(celebration.isDancing(25));
	}

	/** A tier that is set during the settling reads is the login arriving, not a finish. */
	@Test
	public void aDiaryArrivingWithLoginIsNot()
	{
		int[] empty = new int[GolemCelebration.DIARY_TIERS.length];
		int[] synced = empty.clone();
		synced[3] = 1;
		celebration.diaries(empty, 10);
		celebration.diaries(synced, 15);
		celebration.diaries(synced, 20);
		assertFalse(celebration.isDancing(20));
	}
}

package com.golemsdontdie;

import java.lang.reflect.Field;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The climate lists are curated by hand against the shipped place names, so the tests that matter
 * are that every name in them still names a place, and that a golem with a taste for one ends up
 * preferring it.
 */
public class GolemClimateTest
{
	private static final int WEISS_X = 2878;
	private static final int WEISS_Y = 3940;
	private static final int AL_KHARID_X = 3293;
	private static final int AL_KHARID_Y = 3184;
	private static final int VARROCK_X = 3213;
	private static final int VARROCK_Y = 3428;
	private static final int WYRMSCRAIG_X = GolemContent.PLINTH_X;
	private static final int WYRMSCRAIG_Y = GolemContent.PLINTH_Y;

	private PlaceNames places;
	private GolemClimate climate;

	@Before
	public void setUp()
	{
		places = new PlaceNames();
		places.load();
		climate = new GolemClimate();
		climate.learn(places);
	}

	/** Every curated name still names somewhere: the lists are only as good as the data under them. */
	@Test
	public void everyCuratedNameIsAPlace() throws Exception
	{
		for (String list : new String[]{"COLD", "HOT"})
		{
			Field field = GolemClimate.class.getDeclaredField(list);
			field.setAccessible(true);
			for (String name : (String[]) field.get(null))
			{
				assertFalse(list + " has no place called " + name,
					places.regionsNamed(new String[]{name}).isEmpty());
			}
		}
	}

	@Test
	public void coldPlacesAreColdAndHotPlacesHot()
	{
		assertTrue("Weiss is cold", climate.isCold(WEISS_X, WEISS_Y));
		assertFalse("Weiss is not hot", climate.isHot(WEISS_X, WEISS_Y));
		assertTrue("Al Kharid is hot", climate.isHot(AL_KHARID_X, AL_KHARID_Y));
		assertFalse("Al Kharid is not cold", climate.isCold(AL_KHARID_X, AL_KHARID_Y));
		assertFalse("Varrock is neither", climate.isCold(VARROCK_X, VARROCK_Y) || climate.isHot(VARROCK_X, VARROCK_Y));
	}

	/** A golem with no taste in places is untouched by any of it. */
	@Test
	public void aGolemWithoutTastesIsUnmoved()
	{
		TransportMemory plain = new TransportMemory();
		plain.setTraits(GolemTrait.FRIENDLY.mask());
		assertFalse(climate.cares(plain));
		assertEquals(1f, climate.liking(plain, WEISS_X, WEISS_Y), 0.0001f);
		assertEquals(1f, climate.desire(plain, WEISS_X, WEISS_Y, AL_KHARID_X, AL_KHARID_Y), 0.0001f);
		assertEquals(1f, climate.desire(null, WEISS_X, WEISS_Y, AL_KHARID_X, AL_KHARID_Y), 0.0001f);
	}

	@Test
	public void aColdGolemPrefersTheSnow()
	{
		TransportMemory cold = new TransportMemory();
		cold.setTraits(GolemTrait.LIKES_THE_COLD.mask());
		assertTrue(climate.cares(cold));
		assertEquals(1f, climate.liking(cold, WEISS_X, WEISS_Y), 0.0001f);
		assertTrue("the snow beats the desert",
			climate.liking(cold, WEISS_X, WEISS_Y) > climate.liking(cold, AL_KHARID_X, AL_KHARID_Y));
		// Under White Wolf Mountain, against Varrock: the slope is gentle, but it points.
		assertTrue("nearer the snow is better",
			climate.liking(cold, 2900, 3550) > climate.liking(cold, VARROCK_X, VARROCK_Y));

		// Leaving the snow is a discount on whatever offered; arriving at it never is.
		assertTrue(climate.desire(cold, WEISS_X, WEISS_Y, VARROCK_X, VARROCK_Y) < 0.7f);
		assertEquals(1f, climate.desire(cold, VARROCK_X, VARROCK_Y, WEISS_X, WEISS_Y), 0.0001f);
		assertEquals(1f, climate.desire(cold, AL_KHARID_X, AL_KHARID_Y, VARROCK_X, VARROCK_Y), 0.0001f);
	}

	@Test
	public void aHotGolemPrefersTheDesert()
	{
		TransportMemory hot = new TransportMemory();
		hot.setTraits(GolemTrait.LIKES_THE_HEAT.mask());
		assertEquals(1f, climate.liking(hot, AL_KHARID_X, AL_KHARID_Y), 0.0001f);
		assertTrue(climate.liking(hot, AL_KHARID_X, AL_KHARID_Y) > climate.liking(hot, WEISS_X, WEISS_Y));
		assertTrue(climate.desire(hot, AL_KHARID_X, AL_KHARID_Y, WEISS_X, WEISS_Y) < 0.7f);
	}

	/** The temperate golem wants neither extreme, and never settles anywhere in particular. */
	@Test
	public void aTemperateGolemAvoidsBothExtremes()
	{
		TransportMemory mild = new TransportMemory();
		mild.setTraits(GolemTrait.TEMPERATE.mask());
		assertTrue(climate.cares(mild));
		assertTrue("Varrock over the snow",
			climate.liking(mild, VARROCK_X, VARROCK_Y) > climate.liking(mild, WEISS_X, WEISS_Y));
		assertTrue("Varrock over the desert",
			climate.liking(mild, VARROCK_X, VARROCK_Y) > climate.liking(mild, AL_KHARID_X, AL_KHARID_Y));
		assertTrue("and it turns down the way into either",
			climate.desire(mild, VARROCK_X, VARROCK_Y, AL_KHARID_X, AL_KHARID_Y) < 0.5f);
		assertTrue("leaving the desert is never a discount",
			climate.desire(mild, AL_KHARID_X, AL_KHARID_Y, VARROCK_X, VARROCK_Y) >= 1f);

		// It is avoiding two places rather than looking for one, so it keeps moving.
		assertEquals(1f, climate.wanderlust(mild, VARROCK_X, VARROCK_Y), 0.0001f);
		TransportMemory cold = new TransportMemory();
		cold.setTraits(GolemTrait.LIKES_THE_COLD.mask());
		assertTrue("where a golem that came for the snow stays put",
			climate.wanderlust(cold, WEISS_X, WEISS_Y) < 1f);
		assertEquals(1f, climate.wanderlust(cold, VARROCK_X, VARROCK_Y), 0.0001f);
	}

	/** Home is the island, and the island's cave is part of it: a dungeon lies under its own ground. */
	@Test
	public void aHomesickGolemCountsTheCaveAsHome()
	{
		TransportMemory homesick = new TransportMemory();
		homesick.setTraits(GolemTrait.HOMESICK.mask());
		assertEquals(1f, climate.liking(homesick, WYRMSCRAIG_X, WYRMSCRAIG_Y), 0.0001f);
		assertEquals(1f, climate.liking(homesick, WYRMSCRAIG_X, WYRMSCRAIG_Y + 6400), 0.0001f);
		assertTrue(climate.liking(homesick, WYRMSCRAIG_X, WYRMSCRAIG_Y) > climate.liking(homesick, VARROCK_X, VARROCK_Y));
		assertTrue(climate.desire(homesick, WYRMSCRAIG_X, WYRMSCRAIG_Y, VARROCK_X, VARROCK_Y) < 0.5f);
		assertEquals("and coming back is never a discount", 1f,
			climate.desire(homesick, VARROCK_X, VARROCK_Y, WYRMSCRAIG_X, WYRMSCRAIG_Y), 0.0001f);
	}
}

