package com.golemsdontdie;

import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** A crew on its boat: one golem steers, and the rest are passengers. */
public class GolemCrewTest
{
	private static final WorldPoint QUAY = new WorldPoint(2803, 3421, 0);

	private static Golem golem(long seed)
	{
		GolemSnapshot snapshot = new GolemSnapshot(1234, "Golem", new int[0], new short[0], new short[0],
			128, 128, 1, -1, -1, -1, QUAY, 0);
		return Golem.onTile(snapshot, QUAY, seed, QUAY);
	}

	@Test
	public void onlyTheFirstSignedTakesTheHelm()
	{
		GolemCrew crew = new GolemCrew(GolemBoat.SLOOP, null);
		Golem first = golem(1L);
		Golem second = golem(2L);
		Golem third = golem(3L);
		crew.sign(first);
		crew.sign(second);
		crew.sign(third);
		assertTrue(first.isAtHelm());
		assertFalse(second.isAtHelm());
		assertFalse(third.isAtHelm());
	}

	/** A golem on a raft of its own is its own helmsman, and so is one whose crew has been paid off. */
	@Test
	public void aGolemAloneSteersItself()
	{
		Golem alone = golem(4L);
		assertTrue(alone.isAtHelm());
		GolemCrew crew = new GolemCrew(GolemBoat.SKIFF, null);
		crew.sign(golem(5L));
		crew.sign(alone);
		assertFalse(alone.isAtHelm());
		crew.payOff();
		assertTrue(alone.isAtHelm());
	}

	private static final WorldPoint FAR_QUAY = new WorldPoint(3029, 3217, 0);

	private static Itinerary crossingFrom(int dock)
	{
		Itinerary crossing = Itinerary.passage(QUAY, FAR_QUAY, 100, 50);
		crossing.setLeftPort(dock);
		return crossing;
	}

	/** Every one of a crew is kept from sailing straight back, not only the one at the helm. */
	@Test
	public void everyMemberIsKeptFromSailingBack()
	{
		Itinerary crossing = crossingFrom(3);
		GolemCrew crew = new GolemCrew(GolemBoat.SKIFF, crossing);
		for (long seed = 1; seed <= 3; seed++)
		{
			Golem golem = golem(seed);
			crew.sign(golem);
			golem.boardCrossing(crossing);
			assertEquals(3, golem.getTransportMemory().getBlockedPort());
		}
	}

	/** A crossing given up at the quay to wait for a crew leaves the golem blocked as it was. */
	@Test
	public void aCrossingGivenUpLeavesTheBlockAsItWas()
	{
		Golem golem = golem(6L);
		golem.getTransportMemory().setBlockedPort(7);
		golem.boardCrossing(crossingFrom(3));
		assertEquals(3, golem.getTransportMemory().getBlockedPort());
		golem.waitAshore(101, 30, QUAY);
		assertEquals(7, golem.getTransportMemory().getBlockedPort());
	}
}

package com.golemsdontdie;

import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * What a golem's page says about where it has been, and the world layout that decides it: the
 * surface, the caves under it, and the places laid out apart from both.
 */
public class GolemHistoryTest
{
	private static final WorldPoint HOME = new WorldPoint(2596, 2256, 0);

	@Test
	public void theWorldHasThreeLayers()
	{
		assertTrue("the Frozen Temple is on the surface", WorldLayout.isSurface(4121));
		assertTrue("the cave under Wyrmscraig", WorldLayout.isCave(2256 + 6400));
		assertFalse("God Wars is neither", WorldLayout.isSurface(5300) || WorldLayout.isCave(5300));

		assertEquals(2256, WorldLayout.groundAbove(2256));
		assertEquals(2256, WorldLayout.groundAbove(2256 + 6400));
		assertEquals(-1, WorldLayout.groundAbove(5300));

		assertTrue(WorldLayout.sameLayer(2256, 3200));
		assertFalse("a cave and its hill are not a walk apart", WorldLayout.sameLayer(2256, 2256 + 6400));
		assertFalse("God Wars and TzHaar are not one place", WorldLayout.sameLayer(5300, 5100));
	}

	/**
	 * A golem in God Wars is not fourteen hundred tiles from home: God Wars has no ground above it
	 * to measure from, so it sets no record at all.
	 */
	@Test
	public void somewhereWithNoGroundAboveSetsNoRecord()
	{
		GolemHistory history = new GolemHistory();
		history.sample(2600, 2256, 0, HOME);
		history.sample(2880, 5300, 2, HOME);
		assertEquals(4, history.getFurthest());

		// But a cave under somewhere far away counts as the far away place.
		history.sample(3200, 3400 + 6400, 0, HOME);
		assertEquals(3400 - 2256, history.getFurthest());
	}

	/** Walking off the surface is exploring, whichever layer it walks onto. */
	@Test
	public void walkingOffTheSurfaceIsExploring()
	{
		GolemHistory history = new GolemHistory();
		history.sample(2596, 2256, 0, HOME);
		history.sample(2880, 5300, 2, HOME);
		int[][] travels = history.travels();
		assertEquals(1, travels.length);
		assertEquals(GolemTravel.EXPLORED.ordinal(), travels[0][2]);
	}

	/** A crossing ends in a line saying the golem sailed there, not walked. */
	@Test
	public void comingAshoreIsSailing()
	{
		GolemHistory history = new GolemHistory();
		history.sample(2596, 2256, 0, HOME);
		history.cameAshore(null);
		history.sample(2800, 3430, 0, HOME);
		assertEquals(GolemTravel.SAILED.ordinal(), history.travels()[0][2]);
	}

	/**
	 * Pacing between two places writes the first trip only; going somewhere else, or another way,
	 * writes again. A voyage is always a line.
	 */
	@Test
	public void backTheWayItCameIsNoJourney()
	{
		PlaceNames names = new PlaceNames();
		names.load();
		GolemHistory history = new GolemHistory();
		history.sample(2592, 2272, 0, HOME, names);
		history.sample(2528, 2208, 0, HOME, names);
		history.sample(2592, 2272, 0, HOME, names);
		history.sample(2528, 2208, 0, HOME, names);
		history.sample(2592, 2272, 0, HOME, names);
		assertEquals("only the walk to Ardeaglais", 1, history.travels().length);

		history.sample(2592, 2272 + 6400, 0, HOME, names);
		history.tookTransport(ladder(2592, 2272 + 6400, 0, 2592, 2272, 0));
		history.sample(2592, 2272, 0, HOME, names);
		history.tookTransport(ladder(2592, 2272, 1, 2592, 2272 + 6400, 0));
		history.sample(2592, 2272 + 6400, 0, HOME, names);
		history.tookTransport(ladder(2592, 2272 + 6400, 0, 2592, 2272, 1));
		history.sample(2592, 2272, 0, HOME, names);
		int[][] travels = history.travels();
		assertEquals("explored the cavern and climbed out, then no more", 3, travels.length);
		assertEquals(GolemTravel.CLIMBED.ordinal(), travels[0][2]);
		assertEquals(GolemTravel.EXPLORED.ordinal(), travels[1][2]);

		history.cameAshore(null);
		history.sample(2528, 2208, 0, HOME, names);
		history.cameAshore(null);
		history.sample(2592, 2272, 0, HOME, names);
		assertEquals("both voyages", 5, history.travels().length);
	}

	private static GolemTransport ladder(int fromX, int fromY, int fromPlane, int toX, int toY, int toPlane)
	{
		return new GolemTransport(fromX, fromY, fromPlane, toX, toY, toPlane, 1,
			GolemTransport.ARCHETYPE_LADDER, 1, new int[0], new int[0], new int[0], new int[0]);
	}

	/**
	 * A gangplank crossed without leaving the region is not how the golem reached the next one it
	 * walks into: the journal said it took a gangplank to Shilo Village.
	 */
	@Test
	public void aGangplankInPlaceIsNotTheNextJourney()
	{
		GolemHistory history = new GolemHistory();
		history.sample(2596, 2256, 0, HOME);
		history.tookTransport(new GolemTransport(2600, 2260, 0, 2602, 2260, 1, 1,
			GolemTransport.ARCHETYPE_GANGPLANK, 1, new int[0], new int[0], new int[0], new int[0]));
		history.sample(2602, 2260, 1, HOME);
		history.sample(2800, 3430, 0, HOME);
		assertEquals(GolemTravel.WALKED.ordinal(), history.travels()[0][2]);

		// And one that did land somewhere new is written as a gangplank.
		GolemHistory boarded = new GolemHistory();
		boarded.sample(2596, 2256, 0, HOME);
		boarded.tookTransport(new GolemTransport(2600, 2260, 0, 2800, 3430, 0, 1,
			GolemTransport.ARCHETYPE_GANGPLANK, 1, new int[0], new int[0], new int[0], new int[0]));
		boarded.sample(2800, 3430, 0, HOME);
		assertEquals(GolemTravel.BOARDED.ordinal(), boarded.travels()[0][2]);
	}
}

package com.golemsdontdie;

import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * A wave or a dance lasts seconds, whatever happens to the clock it was timed against: a golem must
 * never be held still for hours because the tick count went backwards under it.
 */
public class GolemMomentsTest
{
	private static final WorldPoint PLINTH = new WorldPoint(2596, 2256, 0);

	private static Golem golem()
	{
		GolemSnapshot snapshot = new GolemSnapshot(1234, "Golem", new int[0], new short[0], new short[0],
			128, 128, 1, -1, -1, -1, PLINTH, 0);
		return Golem.onTile(snapshot, PLINTH, 42L, PLINTH);
	}

	@Test
	public void aWaveLastsAWave()
	{
		Golem golem = golem();
		golem.greet(104, 1, 0);
		assertTrue(golem.isGreeting(100));
		assertFalse(golem.isGreeting(104));
	}

	/** Timed three hours into a session, then the clock starts again from nothing. */
	@Test
	public void aClockThatWentBackwardsDoesNotHoldItStill()
	{
		Golem golem = golem();
		golem.greet(18004, 1, 0);
		golem.startParty(18017);
		assertFalse("waving for three hours", golem.isGreeting(5));
		assertFalse("dancing for three hours", golem.isPartying(5));
	}

	@Test
	public void aHopForgetsTheMoment()
	{
		Golem golem = golem();
		golem.greet(104, 1, 0);
		golem.startParty(117);
		golem.forgetMoments();
		assertFalse(golem.isGreeting(100));
		assertFalse(golem.isPartying(100));
	}
}

package com.golemsdontdie;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.coords.WorldPoint;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/** The name a golem answers to when nobody has named it. */
public class GolemNamesTest
{
	private static final WorldPoint PLINTH = new WorldPoint(2596, 2256, 0);

	private GolemNames names;

	@Before
	public void setUp()
	{
		names = new GolemNames();
		names.load();
	}

	private static Golem golem(long seed, String nickname)
	{
		GolemSnapshot snapshot = new GolemSnapshot(1234, "Golem", new int[0], new short[0], new short[0],
			128, 128, 1, -1, -1, -1, PLINTH, 0);
		Golem golem = Golem.onTile(snapshot, PLINTH, seed, PLINTH);
		golem.setNickname(nickname);
		return golem;
	}

	private void setAutoName(boolean on) throws Exception
	{
		setConfig(on, GolemsDontDieConfig.NameStyle.DEFAULT);
	}

	private void setConfig(boolean on, GolemsDontDieConfig.NameStyle style) throws Exception
	{
		Field field = GolemNames.class.getDeclaredField("config");
		field.setAccessible(true);
		field.set(names, new GolemsDontDieConfig()
		{
			@Override
			public boolean autoName()
			{
				return on;
			}

			@Override
			public NameStyle nameStyle()
			{
				return style;
			}
		});
	}

	@Test
	public void theHarvestedNamesAreThere()
	{
		assertTrue("names.gz should hold the people of Gielinor", names.getGielinor().length > 500);
	}

	/** People, not what they do or what they are: nobody is called Taxidermist Flint. */
	@Test
	public void theNamesAreNamesAndNotJobs()
	{
		Set<String> gielinor = new HashSet<>(Arrays.asList(names.getGielinor()));
		for (String job : new String[]{"Taxidermist", "Receptionist", "Oneiromancer", "Sergeant", "Fishmonger",
			"Gatekeeper", "Dockmaster", "Chemist", "Genie", "Sorceress"})
		{
			assertFalse(job + " is not a name", gielinor.contains(job));
		}
	}

	/** A name from Gielinor and a surname off the rocks: two words, both of them names. */
	@Test
	public void everyGolemIsCalledSomething()
	{
		for (long id = -200; id < 200; id++)
		{
			String name = names.nameFor(id);
			assertNotNull("golem " + id + " went unnamed", name);
			assertTrue("'" + name + "' is not a first name and a surname",
				name.matches("[A-Z][A-Za-z]+ [A-Z][a-z]+"));
		}
	}

	@Test
	public void aGolemIsAlwaysCalledTheSameThing()
	{
		for (long id = 0; id < 100; id++)
		{
			assertEquals(names.nameFor(id), names.nameFor(id));
		}
	}

	/** A roster of a thousand should be a thousand names, not sixty Dorises. */
	@Test
	public void thereAreEnoughNamesToGoRound()
	{
		Set<String> seen = new HashSet<>();
		for (long id = 0; id < 1000; id++)
		{
			seen.add(names.nameFor(id * 7919));
		}
		assertTrue("only " + seen.size() + " names for a thousand golems", seen.size() > 980);
	}

	private static Golem crafted(long seed, int craftNumber)
	{
		Golem golem = golem(seed, null);
		golem.setCraftNumber(craftNumber);
		return golem;
	}

	/**
	 * Two golems whose numbers give them the same name: the older by craft number keeps it, whatever
	 * their ids, and the newer goes by another. The same roster in any order comes out the same, a
	 * golem made later changes neither, and naming the older hands the name back.
	 */
	@Test
	public void twoGolemsNeverShareAName() throws Exception
	{
		setAutoName(true);
		long[] pair = twoIdsOneName();
		String shared = names.nameFor(pair[0]);
		Golem older = crafted(pair[1], 1);
		Golem newer = crafted(pair[0], 2);

		names.assign(Arrays.asList(newer, older));
		assertEquals("the older keeps it", shared, names.suggested(older));
		String other = names.suggested(newer);
		assertNotNull(other);
		assertNotEquals("the newer takes another", shared, other);

		assertFalse("the same roster, reordered, changes nobody", names.assign(Arrays.asList(older, newer)));
		assertEquals(shared, names.suggested(older));
		assertEquals(other, names.suggested(newer));

		Golem later = crafted(pair[1] + 1, 3);
		assertFalse("a golem made later renames nobody", names.assign(Arrays.asList(older, newer, later)));
		assertEquals(other, names.suggested(newer));

		older.setNickname("Kevin");
		assertTrue(names.assign(Arrays.asList(older, newer, later)));
		assertEquals("a named golem holds no name, and the newer takes it back", shared, names.suggested(newer));
	}

	/** Not yet numbered is newest: a golem just restored gives way to the ones already counted. */
	@Test
	public void anUnnumberedGolemGivesWay() throws Exception
	{
		setAutoName(true);
		long[] pair = twoIdsOneName();
		Golem unnumbered = crafted(pair[0], 0);
		Golem counted = crafted(pair[1], 5);
		names.assign(Arrays.asList(unnumbered, counted));
		assertEquals(names.nameFor(pair[0]), names.suggested(counted));
		assertNotEquals(names.nameFor(pair[0]), names.suggested(unnumbered));
	}

	/** The first two ids whose own numbers give them the same name, lower first. */
	private long[] twoIdsOneName()
	{
		Map<String, Long> first = new HashMap<>();
		for (long id = 0; ; id++)
		{
			Long seen = first.putIfAbsent(names.nameFor(id), id);
			if (seen != null)
			{
				return new long[]{seen, id};
			}
		}
	}

	/** Fifty thousand golems, fifty thousand names, and settled in one go. */
	@Test
	public void aWholeRosterIsNamedOnce()
	{
		List<Golem> roster = new ArrayList<>();
		for (int i = 0; i < 50_000; i++)
		{
			roster.add(crafted(i * 7919L, i + 1));
		}
		names.assign(roster);
		Set<String> seen = new HashSet<>();
		for (Golem golem : roster)
		{
			assertTrue("two golems called " + names.suggested(golem), seen.add(names.suggested(golem)));
		}
	}

	/** A golem the player has named keeps that name, whatever the setting says. */
	@Test
	public void aNamedGolemIsLeftAlone() throws Exception
	{
		setAutoName(true);
		assertNotNull("an unnamed golem is given one", names.suggested(golem(7, null)));
		assertNull("a named golem keeps its name", names.suggested(golem(7, "Kevin")));
		assertNotNull("a name cleared back to nothing is not a name", names.suggested(golem(7, "")));
	}

	/** Off, nobody is called anything, and the golems are golems again. */
	@Test
	public void offMeansOff() throws Exception
	{
		setAutoName(false);
		assertNull(names.suggested(golem(7, null)));

		setAutoName(true);
		String named = names.suggested(golem(7, null));
		setAutoName(false);
		assertNull("turning it off takes the name away", names.suggested(golem(7, null)));
		setAutoName(true);
		assertEquals("and turning it on gives the same one back", named, names.suggested(golem(7, null)));
	}

	/** The examples from issue 2, and the ends of the list. */
	@Test
	public void ordinalsReadAsTheIssueAskedForThem()
	{
		assertEquals("Primus", names.ordinal(1));
		assertEquals("Vicesimus Septimus", names.ordinal(27));
		assertEquals("Undeseptuagesimus", names.ordinal(69));
		assertEquals("Octogesimus Primus", names.ordinal(81));
		assertEquals("Sescentesimus Tricesimus Quintus", names.ordinal(635));
		assertEquals("Octingentesimus Quinquagesimus Sextus", names.ordinal(856));
		assertEquals("Nongentesimus Octavus", names.ordinal(908));
		assertEquals("Millesimus", names.ordinal(1000));
		assertEquals("Bis Millesimus Quingentesimus Nonagesimus Sextus", names.ordinal(2596));
		assertEquals("Septies Millesimus Trecentesimus Duodenonagesimus", names.ordinal(7388));
		assertEquals("Vicies Septies Millesimus", names.ordinal(27000));
		assertEquals("Quinquagies Millesimus", names.ordinal(50000));
		assertEquals("Quinquagies Millesimus Nongentesimus Undecentesimus", names.ordinal(50999));
		assertEquals("Ultimus", names.ordinal(51000));
		assertNull("a golem not yet numbered has no ordinal", names.ordinal(0));
	}

	/**
	 * Eights and nines count down from the next ten, 98 and 99 from the hundred, and the hundreds
	 * and thousands in front of them are added unchanged.
	 */
	@Test
	public void ninetyEightCountsDownLikeEighteen()
	{
		assertEquals("Duodevicesimus", names.ordinal(18));
		assertEquals("Duodecentesimus", names.ordinal(98));
		assertEquals("Undecentesimus", names.ordinal(99));
		assertEquals("Centesimus Duodecentesimus", names.ordinal(198));
		assertEquals("Millesimus Duodecentesimus", names.ordinal(1098));
		assertEquals("Bis Millesimus Quingentesimus Undecentesimus", names.ordinal(2599));
	}

	/** The teens of thousands are each one word, from Undecies to Undevicies. */
	@Test
	public void theTeensOfThousandsAreOneWordEach()
	{
		String[] teens = {"Undecies", "Duodecies", "Terdecies", "Quaterdecies", "Quinquiesdecies",
			"Sexiesdecies", "Septiesdecies", "Duodevicies", "Undevicies"};
		for (int i = 0; i < teens.length; i++)
		{
			assertEquals(teens[i] + " Millesimus", names.ordinal((11 + i) * 1000));
		}
	}

	/** Every golem to fifty thousand has an ordinal of its own. */
	@Test
	public void everyOrdinalToFiftyThousandIsDifferent()
	{
		Set<String> seen = new HashSet<>();
		for (int n = 1; n <= 50_000; n++)
		{
			String name = names.ordinal(n);
			assertNotNull("no ordinal for " + n, name);
			assertTrue("the ordinal for " + n + " was taken already: " + name, seen.add(name));
		}
	}

	/** In the ordinal style an unnamed golem is called by its craft number; a named one keeps its name. */
	@Test
	public void theOrdinalStyleCountsCrafts() throws Exception
	{
		setConfig(true, GolemsDontDieConfig.NameStyle.ORDINAL);
		Golem golem = golem(7, null);
		golem.setCraftNumber(3);
		assertEquals("Tertius", names.suggested(golem));
		assertNull(names.suggested(golem(7, "Kevin")));

		setConfig(true, GolemsDontDieConfig.NameStyle.DEFAULT);
		assertEquals(names.nameFor(golem.getId()), names.suggested(golem));
	}
}

package com.golemsdontdie;

import java.lang.reflect.Proxy;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.function.BiFunction;
import net.runelite.api.CollisionData;
import net.runelite.api.CollisionDataFlag;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Where golems stand on the player's ship. A ship's world is a small square with the deck in the
 * middle and water round it; golems belong at the rail, looking out, and never in the water.
 */
public class GolemShipmatesTest
{
	/** The ship's world: seven by nine, water everywhere but a deck three wide and five long. */
	private static final int SIZE_X = 7;
	private static final int SIZE_Y = 9;
	private static final int DECK_WEST = 2;
	private static final int DECK_EAST = 4;
	private static final int DECK_SOUTH = 2;
	private static final int DECK_NORTH = 6;

	private static boolean onDeck(int x, int y)
	{
		return x >= DECK_WEST && x <= DECK_EAST && y >= DECK_SOUTH && y <= DECK_NORTH;
	}

	/** Stands in for the few parts of a world view the rail finder reads. */
	private static WorldView ship()
	{
		int[][] flags = new int[SIZE_X][SIZE_Y];
		Tile[][][] tiles = new Tile[1][SIZE_X][SIZE_Y];
		Tile somewhere = (Tile) Proxy.newProxyInstance(Tile.class.getClassLoader(), new Class<?>[]{Tile.class},
			(proxy, method, args) -> null);
		for (int x = 0; x < SIZE_X; x++)
		{
			for (int y = 0; y < SIZE_Y; y++)
			{
				flags[x][y] = onDeck(x, y) ? 0 : CollisionDataFlag.BLOCK_MOVEMENT_FLOOR;
				tiles[0][x][y] = somewhere;
			}
		}
		CollisionData collision = (CollisionData) Proxy.newProxyInstance(CollisionData.class.getClassLoader(),
			new Class<?>[]{CollisionData.class}, (proxy, method, args) ->
				"getFlags".equals(method.getName()) ? flags : null);
		Scene scene = (Scene) Proxy.newProxyInstance(Scene.class.getClassLoader(), new Class<?>[]{Scene.class},
			(proxy, method, args) -> "getTiles".equals(method.getName()) ? tiles : null);
		return (WorldView) Proxy.newProxyInstance(WorldView.class.getClassLoader(), new Class<?>[]{WorldView.class},
			(proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getCollisionMaps":
						return new CollisionData[]{collision};
					case "getSizeX":
						return SIZE_X;
					case "getSizeY":
						return SIZE_Y;
					case "getScene":
						return scene;
					case "getId":
						return 7;
					default:
						return null;
				}
			});
	}

	private static LocalPoint at(int x, int y)
	{
		return new LocalPoint(x * Golem.TILE + Golem.TILE / 2, y * Golem.TILE + Golem.TILE / 2, 7);
	}

	@Test
	public void everyPlaceIsOnTheRailAndNoneIsInTheWater()
	{
		List<int[]> rails = GolemShipmates.rails(ship(), 0, at(3, 4));
		// The deck's edge: three by five has twelve tiles round it, and the player is in the middle.
		assertEquals(12, rails.size());
		for (int[] rail : rails)
		{
			int x = rail[0] / Golem.TILE;
			int y = rail[1] / Golem.TILE;
			assertTrue("on the deck: " + x + "," + y, onDeck(x, y));
			assertTrue("at its edge: " + x + "," + y,
				x == DECK_WEST || x == DECK_EAST || y == DECK_SOUTH || y == DECK_NORTH);
		}
	}

	@Test
	public void eachLooksOutOverTheWaterBesideIt()
	{
		for (int[] rail : GolemShipmates.rails(ship(), 0, at(3, 4)))
		{
			int x = rail[0] / Golem.TILE;
			int y = rail[1] / Golem.TILE;
			// 0 south, 512 west, 1024 north, 1536 east: the way it faces is off the deck.
			int dx = rail[2] == 512 ? -1 : rail[2] == 1536 ? 1 : 0;
			int dy = rail[2] == 1024 ? 1 : rail[2] == 0 ? -1 : 0;
			assertFalse("faces the water at " + x + "," + y, onDeck(x + dx, y + dy));
		}
	}

	@Test
	public void thePlayersOwnPlaceIsNotTaken()
	{
		for (int[] rail : GolemShipmates.rails(ship(), 0, at(DECK_WEST, 4)))
		{
			assertFalse(rail[0] / Golem.TILE == DECK_WEST && rail[1] / Golem.TILE == 4);
		}
	}

	private static final WorldPoint QUAY = new WorldPoint(3029, 3217, 0);

	/** Golems step off onto tiles of their own around the player while there are any. */
	@Test
	public void eachStepsOffOntoATileOfItsOwn()
	{
		Set<Long> taken = new HashSet<>();
		taken.add(RoamContext.tileKey(QUAY.getX(), QUAY.getY(), QUAY.getPlane()));
		// Room for one beside the player, then none.
		BiFunction<WorldPoint, Set<Long>, WorldPoint> place = (at, stood) ->
		{
			WorldPoint beside = at.dx(1);
			return stood.contains(RoamContext.tileKey(beside.getX(), beside.getY(), beside.getPlane())) ? at : beside;
		};
		assertEquals(QUAY.dx(1), GolemShipmates.stepOff(QUAY, taken, place));
		// A narrow quay: the next shares the player's tile, not the port it boarded at.
		assertEquals(QUAY, GolemShipmates.stepOff(QUAY, taken, place));
		assertEquals(QUAY, GolemShipmates.stepOff(QUAY, taken, (at, stood) -> null));
	}

	/** A golem told to go while aboard crumbles on deck and is done, rather than sailing on for good. */
	@Test
	public void aGolemToldToGoAboardCrumblesThere()
	{
		GolemSnapshot snapshot = new GolemSnapshot(1234, "Golem", new int[0], new short[0], new short[0],
			128, 128, 1, -1, -1, -1, QUAY, 0);
		Golem golem = Golem.onTile(snapshot, QUAY, 42L, QUAY);
		golem.boardShip(7, 3 * Golem.TILE, 4 * Golem.TILE, 1, 512);
		golem.startDying();
		assertFalse(golem.isCrumbled());
		golem.advance(GolemContent.GOLEM_DEATH_CYCLES, null);
		assertTrue(golem.isAboard());
		assertTrue(golem.isCrumbled());
	}

	/** A few golems stand round the ship, not in a queue down one side of it. */
	@Test
	public void theFirstFewAreSpreadOut()
	{
		List<int[]> rails = GolemShipmates.rails(ship(), 0, at(3, 4));
		for (int i = 0; i < 4; i++)
		{
			for (int j = i + 1; j < 4; j++)
			{
				int apart = Math.max(Math.abs(rails.get(i)[0] - rails.get(j)[0]),
					Math.abs(rails.get(i)[1] - rails.get(j)[1])) / Golem.TILE;
				assertTrue("places " + i + " and " + j + " are " + apart + " apart", apart >= 2);
			}
		}
	}
}

package com.golemsdontdie;

import java.lang.reflect.Proxy;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.CollisionData;
import net.runelite.api.GameObject;
import net.runelite.api.Point;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import org.junit.Test;
import static org.junit.Assert.assertEquals;

/**
 * A real skiff's deck, as ::gdeck and ::gparts read it off one at sea: where golems may stand. A
 * skiff has eight places to stand, one of them where its helmsman stands; this one has a salvaging
 * station and a wind catcher on two, so five are left for golems. Its collision says otherwise -
 * the mast's tile blocked, the stations' open - which is why the deck is read from its objects.
 */
public class GolemSkiffDeckTest
{
	private static final int SIZE = 8;

	/** Hull 59505, 2x6 from 3,1; helm 59585 on 4,6; the player steering from 4,5. */
	private static final int HULL_ID = 59505;
	private static final int HELM_ID = 59585;

	/** Collision on the hull's floor and the deck's, by x then y, as read. */
	private static final int[][] FLOOR_0 = new int[SIZE][SIZE];
	private static final int[][] FLOOR_1 = new int[SIZE][SIZE];
	private static final byte[][][] SETTINGS = new byte[4][SIZE][SIZE];

	static
	{
		int[] ys = {6, 5, 4, 3, 2, 1};
		int[] west0 = {0, 0, 0, 0, 0x20100, 0};
		int[] east0 = {0x20100, 0x20100, 0x20100, 0x20100, 0x20100, 0};
		int[] west1 = {0x200000, 0x200000, 0x200000, 0x200000, 0x200000, 0};
		int[] east1 = {0x100, 0, 0x100, 0, 0x200100, 0};
		for (int i = 0; i < ys.length; i++)
		{
			FLOOR_0[3][ys[i]] = west0[i];
			FLOOR_0[4][ys[i]] = east0[i];
			FLOOR_1[3][ys[i]] = west1[i];
			FLOOR_1[4][ys[i]] = east1[i];
		}
		// The bow row and the helm row are no place to stand.
		SETTINGS[1][3][1] = 1;
		SETTINGS[1][4][1] = 1;
		SETTINGS[1][3][6] = 1;
		SETTINGS[1][4][6] = 1;
	}

	private static GameObject object(int id, int x, int y, int sizeX, int sizeY)
	{
		return object(id, x, y, sizeX, sizeY, 10);
	}

	private static GameObject object(int id, int x, int y, int sizeX, int sizeY, int config)
	{
		return (GameObject) Proxy.newProxyInstance(GameObject.class.getClassLoader(), new Class<?>[]{GameObject.class},
			(proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getId":
						return id;
					case "getSceneMinLocation":
						return new Point(x, y);
					case "sizeX":
						return sizeX;
					case "sizeY":
						return sizeY;
					case "getConfig":
						return config;
					default:
						return null;
				}
			});
	}

	private static Tile tile(GameObject... objects)
	{
		return (Tile) Proxy.newProxyInstance(Tile.class.getClassLoader(), new Class<?>[]{Tile.class},
			(proxy, method, args) -> "getGameObjects".equals(method.getName()) ? objects : null);
	}

	private static CollisionData collision(int[][] flags)
	{
		return (CollisionData) Proxy.newProxyInstance(CollisionData.class.getClassLoader(),
			new Class<?>[]{CollisionData.class}, (proxy, method, args) ->
				"getFlags".equals(method.getName()) ? flags : null);
	}

	private static WorldView skiff()
	{
		Tile[][][] tiles = new Tile[4][SIZE][SIZE];
		for (int x = 3; x <= 4; x++)
		{
			for (int y = 1; y <= 6; y++)
			{
				tiles[0][x][y] = tile();
				tiles[1][x][y] = tile();
			}
		}
		tiles[0][3][1] = tile(object(HULL_ID, 3, 1, 2, 6, 266));
		// The deck's own things, with their configs as read: 0x100 set on what fills a tile.
		tiles[1][3][1] = tile(object(59704, 3, 1, 1, 1, 266));
		tiles[1][4][1] = tile(object(60263, 4, 1, 1, 1, 266));
		tiles[1][3][2] = tile(object(60493, 3, 2, 1, 1, 74));
		tiles[1][3][3] = tile(object(59700, 3, 3, 1, 1, 458));
		tiles[1][4][4] = tile(object(59541, 4, 4, 1, 1, 10));
		tiles[1][3][5] = tile(object(59683, 3, 5, 1, 1, 266));
		tiles[1][4][5] = tile(object(29525, 4, 5, 1, 1, 10));
		tiles[1][3][6] = tile(object(59488, 3, 6, 1, 1, 266));
		tiles[1][4][6] = tile(object(HELM_ID, 4, 6, 1, 1, 10));
		CollisionData[] maps = {collision(FLOOR_0), collision(FLOOR_1), collision(new int[SIZE][SIZE]),
			collision(new int[SIZE][SIZE])};
		Scene scene = (Scene) Proxy.newProxyInstance(Scene.class.getClassLoader(), new Class<?>[]{Scene.class},
			(proxy, method, args) -> "getTiles".equals(method.getName()) ? tiles : null);
		return (WorldView) Proxy.newProxyInstance(WorldView.class.getClassLoader(), new Class<?>[]{WorldView.class},
			(proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getCollisionMaps":
						return maps;
					case "getTileSettings":
						return SETTINGS;
					case "getSizeX":
					case "getSizeY":
						return SIZE;
					case "getScene":
						return scene;
					case "getId":
						return 316;
					case "getPlane":
						return 1;
					default:
						return null;
				}
			});
	}

	@Test
	public void fiveGolemsFitOnThisSkiff()
	{
		LocalPoint steering = new LocalPoint(4 * Golem.TILE + Golem.TILE / 2, 5 * Golem.TILE + Golem.TILE / 2, 316);
		List<int[]> rails = GolemShipmates.rails(skiff(), 1, steering);
		Set<String> places = new HashSet<>();
		for (int[] rail : rails)
		{
			places.add(rail[0] / Golem.TILE + "," + rail[1] / Golem.TILE);
		}
		// Down the helm's side, and the two either side of the salvaging station.
		assertEquals(new HashSet<>(java.util.Arrays.asList("4,2", "4,3", "4,4", "3,2", "3,4")), places);
	}

	/**
	 * A raft as ::gdeck read one: 1x3, a chest at the bow, the mast in the middle, the helm at the
	 * stern with the player standing on it to steer. One golem, in the middle.
	 */
	private static WorldView raft()
	{
		int[][] floor0 = new int[SIZE][SIZE];
		int[][] floor1 = new int[SIZE][SIZE];
		for (int y = 2; y <= 4; y++)
		{
			floor1[3][y] = 0x200000;
		}
		Tile[][][] tiles = new Tile[4][SIZE][SIZE];
		for (int y = 2; y <= 4; y++)
		{
			tiles[0][3][y] = tile();
		}
		tiles[0][3][2] = tile(object(59494, 3, 2, 1, 3, 266));
		tiles[1][3][2] = tile(object(60245, 3, 2, 1, 1, 266));
		tiles[1][3][3] = tile(object(59530, 3, 3, 1, 1, 10));
		tiles[1][3][4] = tile(object(59554, 3, 4, 1, 1, 10));
		tiles[1][3][5] = tile(object(29506, 3, 5, 1, 1, 10));
		byte[][][] settings = new byte[4][SIZE][SIZE];
		CollisionData[] maps = {collision(floor0), collision(floor1), collision(new int[SIZE][SIZE]),
			collision(new int[SIZE][SIZE])};
		Scene scene = (Scene) Proxy.newProxyInstance(Scene.class.getClassLoader(), new Class<?>[]{Scene.class},
			(proxy, method, args) -> "getTiles".equals(method.getName()) ? tiles : null);
		return (WorldView) Proxy.newProxyInstance(WorldView.class.getClassLoader(), new Class<?>[]{WorldView.class},
			(proxy, method, args) ->
			{
				switch (method.getName())
				{
					case "getCollisionMaps":
						return maps;
					case "getTileSettings":
						return settings;
					case "getSizeX":
					case "getSizeY":
						return SIZE;
					case "getScene":
						return scene;
					case "getId":
						return 321;
					case "getPlane":
						return 1;
					default:
						return null;
				}
			});
	}

	@Test
	public void oneGolemFitsOnARaftInTheMiddle()
	{
		LocalPoint steering = new LocalPoint(3 * Golem.TILE + Golem.TILE / 2, 4 * Golem.TILE + Golem.TILE / 2, 321);
		List<int[]> rails = GolemShipmates.rails(raft(), 1, steering);
		assertEquals(1, rails.size());
		assertEquals(3, rails.get(0)[0] / Golem.TILE);
		assertEquals(3, rails.get(0)[1] / Golem.TILE);
	}
}

package com.golemsdontdie;

import java.util.Arrays;
import java.util.List;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * What the save file has to keep. A golem's seed above all: its gait and its traits come out of
 * that one number, so a golem that comes back with a different seed comes back a different golem.
 */
public class GolemStoreTest
{
	private static final WorldPoint PLINTH = new WorldPoint(2596, 2256, 0);

	private static Golem golem(long seed, String nickname)
	{
		GolemSnapshot snapshot = new GolemSnapshot(1234, "Golem", new int[0], new short[0], new short[0],
			128, 128, 1, -1, -1, -1, PLINTH, 0);
		Golem golem = Golem.onTile(snapshot, PLINTH, seed, PLINTH);
		golem.setNickname(nickname);
		return golem;
	}

	@Test
	public void aSeedSurvivesTheSaveFile()
	{
		GolemStore store = new GolemStore();
		List<Golem> roster = Arrays.asList(golem(1234567890123L, "Pebble"), golem(-42L, null));

		List<GolemStore.SavedGolem> read = store.deserialise(store.serialise(roster));

		assertEquals(2, read.size());
		assertEquals(1234567890123L, read.get(0).seed);
		assertEquals("Pebble", read.get(0).nickname);
		assertEquals(-42L, read.get(1).seed);
		assertNull(read.get(1).nickname);
	}

	/** A save from before seeds were kept still loads, and says it has none. */
	@Test
	public void anOlderSaveStillLoads()
	{
		GolemStore store = new GolemStore();
		String eleven = "1234,2596,2256,0,0,2596,2256,-1,-1,-1,Pebble";
		String thirteen = eleven + ",1,600";

		for (String encoded : new String[]{eleven, thirteen})
		{
			List<GolemStore.SavedGolem> read = store.deserialise(encoded);
			assertEquals(encoded, 1, read.size());
			assertEquals(encoded, 0L, read.get(0).seed);
			assertEquals(encoded, "Pebble", read.get(0).nickname);
			assertEquals(encoded, 2596, read.get(0).worldX);
		}
	}

	/**
	 * A save from a later version, with fields this one has never heard of, still loads: the
	 * format only grows at the end, and what is not understood is left rather than taken as damage.
	 */
	@Test
	public void aLaterSaveStillLoads()
	{
		GolemStore store = new GolemStore();
		StringBuilder later = new StringBuilder(store.serialise(
			java.util.Collections.singletonList(golem(77L, "Flint"))));
		for (int extra = 0; extra < 11; extra++)
		{
			later.append(",1");
		}
		List<GolemStore.SavedGolem> read = store.deserialise(later.toString());
		assertEquals(1, read.size());
		assertEquals(77L, read.get(0).seed);
		assertEquals("Flint", read.get(0).nickname);
	}

	/** A record too short to be a golem is dropped rather than half-read. */
	@Test
	public void aTruncatedRecordIsDropped()
	{
		assertEquals(0, new GolemStore().deserialise("1234,2596,2256").size());
	}

	/**
	 * Traits come back as they were dealt, not as the seed would deal them today: the list they are
	 * drawn from will change, and a golem's page must not change with it.
	 */
	@Test
	public void traitsSurviveTheSaveFile()
	{
		GolemStore store = new GolemStore();
		Golem golem = golem(5L, "Slate");
		int dealt = golem.getTraits();
		golem.restoreTraits(GolemTrait.LOYAL.mask() | GolemTrait.FOND_OF_GOATS.mask());

		GolemStore.SavedGolem saved = store.deserialise(store.serialise(
			java.util.Collections.singletonList(golem))).get(0);

		assertEquals(GolemTrait.LOYAL.mask() | GolemTrait.FOND_OF_GOATS.mask(), saved.traits);
		// And a save from before traits were kept says so, leaving the seed's hand in place.
		String older = "1234,2596,2256,0,0,2596,2256,-1,-1,-1,Pebble,0,0,5";
		assertEquals(0, store.deserialise(older).get(0).traits);
		assertEquals(dealt, GolemTrait.of(5L));
	}

	/** A golem's history goes with it, and comes back as it was. */
	@Test
	public void aHistorySurvivesTheSaveFile()
	{
		GolemStore store = new GolemStore();
		Golem golem = golem(99L, "Chip");
		golem.getHistory().tookTransport();
		golem.getHistory().tookTransport();
		golem.getHistory().sailed();
		// Two samples: the first only says where it is, the second is the ground between them.
		golem.getHistory().sample(2596, 2256, 0, PLINTH);
		golem.getHistory().sample(2600, 2256, 0, PLINTH);

		GolemStore.SavedGolem saved = store.deserialise(store.serialise(
			java.util.Collections.singletonList(golem))).get(0);

		assertEquals(2, saved.transports);
		assertEquals(1, saved.voyages);
		assertEquals(4, saved.walked);
		assertEquals(2600, saved.furthestX);
		assertEquals(golem.getHistory().getFirstSeen(), saved.firstSeen);
	}

	/** A star stays on the golem it was given to, and a golem saved before stars has none. */
	@Test
	public void aStarSurvivesTheSaveFile()
	{
		GolemStore store = new GolemStore();
		Golem starred = golem(8L, "Quartz");
		starred.setFavourite(true);
		List<GolemStore.SavedGolem> read = store.deserialise(store.serialise(
			Arrays.asList(starred, golem(9L, null))));
		assertEquals(true, read.get(0).favourite);
		assertEquals(false, read.get(1).favourite);
		assertEquals(false, store.deserialise("1234,2596,2256,0,0,2596,2256,-1,-1,-1,Pebble").get(0).favourite);
	}

	/**
	 * The journal goes with the golem, the newest twenty entries in order with their times, and a
	 * save from before it was kept reads as no journal.
	 */
	@Test
	public void aJournalSurvivesTheSaveFile()
	{
		GolemStore store = new GolemStore();
		Golem golem = golem(11L, "Wanderer");
		GolemHistory history = golem.getHistory();
		// Twenty-five regions in a row along the map: more than are kept, so the oldest go.
		for (int i = 0; i <= 25; i++)
		{
			if (i % 5 == 3)
			{
				history.cameAshore(null);
			}
			history.sample(2596 + i * 64, 2256, 0, PLINTH);
		}
		int[][] before = history.travels();
		assertEquals(20, before.length);

		GolemStore.SavedGolem saved = store.deserialise(store.serialise(
			java.util.Collections.singletonList(golem))).get(0);
		GolemHistory back = new GolemHistory();
		back.restoreJournal(saved.journal);
		int[][] after = back.travels();
		assertEquals(before.length, after.length);
		for (int i = 0; i < before.length; i++)
		{
			assertEquals(Arrays.toString(before[i]), Arrays.toString(after[i]));
		}
		assertNull(store.deserialise("1234,2596,2256,0,0,2596,2256,-1,-1,-1,Pebble").get(0).journal);
		assertEquals(0, new GolemHistory().travels().length);
	}

	/** The day a golem was crafted is saved with it, and comes back as that day. */
	@Test
	public void aCraftDateSurvivesTheSaveFile()
	{
		GolemStore store = new GolemStore();
		Golem golem = golem(12L, null);
		long crafted = golem.getHistory().getFirstSeen();
		GolemStore.SavedGolem saved = store.deserialise(store.serialise(
			java.util.Collections.singletonList(golem))).get(0);
		assertEquals(crafted, saved.firstSeen);
	}

	/** A craft number is kept, and a golem saved before they were kept has none until restored. */
	@Test
	public void aCraftNumberSurvivesTheSaveFile()
	{
		GolemStore store = new GolemStore();
		Golem numbered = golem(10L, null);
		numbered.setCraftNumber(2596);
		List<GolemStore.SavedGolem> read = store.deserialise(store.serialise(Arrays.asList(numbered)));
		assertEquals(2596, read.get(0).craftNumber);
		assertEquals(0, store.deserialise("1234,2596,2256,0,0,2596,2256,-1,-1,-1,Pebble").get(0).craftNumber);
	}
}

package com.golemsdontdie;

import java.util.List;
import org.junit.Assert;
import org.junit.Test;

/** The traits a seed draws: always some, never many, and always the same ones. */
public class GolemTraitTest
{
	@Test
	public void everyGolemHasBetweenOneAndFiveTraits()
	{
		int[] counts = new int[8];
		for (long seed = 0; seed < 20_000; seed++)
		{
			int traits = GolemTrait.of(seed);
			int count = GolemTrait.list(traits).size();
			Assert.assertTrue("at least one trait for seed " + seed, count >= 1);
			Assert.assertTrue("at most five traits for seed " + seed, count <= 5);
			counts[count]++;
		}
		// Leaning on the low end: most golems are one or two things, not five.
		Assert.assertTrue("one or two traits is the common case, was " + counts[1] + "/" + counts[2],
			counts[1] + counts[2] > 15_000);
		Assert.assertTrue("five traits happens at all", counts[5] > 0);
		Assert.assertTrue("five traits is rare", counts[5] < 1_000);
	}

	@Test
	public void aSeedAlwaysDrawsTheSameTraits()
	{
		for (long seed = 1; seed < 200; seed++)
		{
			Assert.assertEquals(GolemTrait.of(seed), GolemTrait.of(seed));
		}
		Assert.assertNotEquals("different golems are not all alike",
			GolemTrait.of(12345), GolemTrait.of(12346));
	}

	/**
	 * Every pair that contradicts itself, written out here rather than read back from the enum, so
	 * a clash dropped from the table is caught.
	 */
	private static final GolemTrait[][] CONTRADICTIONS = {
		{GolemTrait.LIKES_THE_COLD, GolemTrait.LIKES_THE_HEAT},
		{GolemTrait.LIKES_THE_COLD, GolemTrait.TEMPERATE},
		{GolemTrait.LIKES_THE_COLD, GolemTrait.HOMESICK},
		{GolemTrait.LIKES_THE_HEAT, GolemTrait.TEMPERATE},
		{GolemTrait.LIKES_THE_HEAT, GolemTrait.HOMESICK},
		{GolemTrait.TEMPERATE, GolemTrait.HOMESICK},
		{GolemTrait.CAUTIOUS, GolemTrait.SURE_FOOTED},
		{GolemTrait.SPELUNKER, GolemTrait.CLIMBER},
		{GolemTrait.CROWD_SHY, GolemTrait.SOCIABLE},
		{GolemTrait.CROWD_SHY, GolemTrait.FRIENDLY},
		{GolemTrait.CROWD_SHY, GolemTrait.LIFE_OF_THE_PARTY},
		{GolemTrait.RESTLESS, GolemTrait.PATIENT},
		{GolemTrait.RESTLESS, GolemTrait.OLD_SOUL},
		{GolemTrait.RESTLESS, GolemTrait.PONDEROUS},
		{GolemTrait.OLD_SOUL, GolemTrait.LIFE_OF_THE_PARTY},
	};

	/** A golem is never dealt two traits that pull against each other. See GolemTrait.CLASHES. */
	@Test
	public void nothingIsDrawnAgainstItself()
	{
		for (long seed = 0; seed < 200_000; seed++)
		{
			int traits = GolemTrait.of(seed);
			for (GolemTrait[] pair : CONTRADICTIONS)
			{
				Assert.assertFalse("seed " + seed + " drew " + GolemTrait.list(traits),
					pair[0].in(traits) && pair[1].in(traits));
			}
		}
	}

	/** The table and the list above agree, both ways round, and nothing else is kept apart. */
	@Test
	public void theClashesAreExactlyTheContradictions()
	{
		int pairs = 0;
		for (GolemTrait a : GolemTrait.values())
		{
			for (GolemTrait b : GolemTrait.values())
			{
				Assert.assertEquals(a + " and " + b + " clash one way only", a.clashesWith(b), b.clashesWith(a));
				pairs += a.ordinal() < b.ordinal() && a.clashesWith(b) ? 1 : 0;
			}
		}
		Assert.assertEquals(CONTRADICTIONS.length, pairs);
		for (GolemTrait[] pair : CONTRADICTIONS)
		{
			Assert.assertTrue(pair[0] + " and " + pair[1], pair[0].clashesWith(pair[1]));
		}
	}

	/** Not over-constrained: the ones that only look alike still turn up together. */
	@Test
	public void kindredTraitsStillMeet()
	{
		GolemTrait[][] kindred = {
			{GolemTrait.FRIENDLY, GolemTrait.SOCIABLE},
			{GolemTrait.FRIENDLY, GolemTrait.LIFE_OF_THE_PARTY},
			{GolemTrait.PATIENT, GolemTrait.OLD_SOUL},
			{GolemTrait.PONDEROUS, GolemTrait.OLD_SOUL},
		};
		for (GolemTrait[] pair : kindred)
		{
			boolean met = false;
			for (long seed = 0; seed < 20_000 && !met; seed++)
			{
				int traits = GolemTrait.of(seed);
				met = pair[0].in(traits) && pair[1].in(traits);
			}
			Assert.assertTrue(pair[0] + " and " + pair[1] + " never met", met);
		}
	}

	@Test
	public void everyTraitIsDrawnSometimesAndNoneTwice()
	{
		boolean[] seen = new boolean[GolemTrait.values().length];
		for (long seed = 0; seed < 20_000; seed++)
		{
			List<GolemTrait> drawn = GolemTrait.list(GolemTrait.of(seed));
			Assert.assertEquals("no trait twice", drawn.size(), new java.util.HashSet<>(drawn).size());
			for (GolemTrait trait : drawn)
			{
				seen[trait.ordinal()] = true;
			}
		}
		for (GolemTrait trait : GolemTrait.values())
		{
			Assert.assertTrue(trait + " is drawn sometimes", seen[trait.ordinal()]);
		}
	}
}

