package com.golemsdontdie;

import java.lang.reflect.Field;
import java.lang.reflect.Proxy;
import java.util.Arrays;
import java.util.List;
import java.util.Random;
import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;

/**
 * Where a crew sails: somewhere every one of them would go, or nowhere. A crew that took the best
 * of a bad lot sailed a golem that loves the snow off to the desert.
 */
public class VoyageCrewTest
{
	private static final SailingDocks.Dock HOME = dock(1, 2803, 3421);
	private static final SailingDocks.Dock SNOW = dock(2, 2878, 3940);
	private static final SailingDocks.Dock DESERT = dock(3, 3293, 3184);

	/** Every roll comes up short: only a port somebody wants for certain is taken. */
	private static final Random UNLUCKY = new Random()
	{
		@Override
		public float nextFloat()
		{
			return 0.99f;
		}
	};

	private Voyage voyage;
	private RoamContext context;

	private static SailingDocks.Dock dock(int row, int x, int y)
	{
		WorldPoint at = new WorldPoint(x, y, 0);
		return new SailingDocks.Dock(row, "Dock " + row, 0, 0, at, true, at);
	}

	private static void inject(Object into, String name, Object value) throws Exception
	{
		Field field = into.getClass().getDeclaredField(name);
		field.setAccessible(true);
		field.set(into, value);
	}

	@Before
	public void setUp() throws Exception
	{
		Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
			(proxy, method, args) -> "getRealSkillLevel".equals(method.getName()) ? 99 : null);
		SailingDocks docks = new SailingDocks();
		inject(docks, "client", client);
		docks.getDocks().addAll(Arrays.asList(HOME, SNOW, DESERT));
		voyage = new Voyage();
		inject(voyage, "docks", docks);

		PlaceNames places = new PlaceNames();
		places.load();
		GolemClimate climate = new GolemClimate();
		climate.learn(places);
		context = new RoamContext(null, null, null, null);
		context.setClimates(climate);
	}

	private static TransportMemory golem(GolemTrait... traits)
	{
		TransportMemory memory = new TransportMemory();
		int mask = 0;
		for (GolemTrait trait : traits)
		{
			mask |= trait.mask();
		}
		memory.setTraits(mask);
		return memory;
	}

	@Test
	public void aCrewThatLovesTheSnowSailsToIt()
	{
		List<TransportMemory> crew = Arrays.asList(golem(GolemTrait.LIKES_THE_COLD), golem(GolemTrait.LIKES_THE_COLD),
			golem());
		assertSame(SNOW, voyage.crewPort(HOME, crew, UNLUCKY, context));
	}

	/** One wants the snow and one the desert: neither port is one both would go to, so neither. */
	@Test
	public void aCrewThatCannotAgreeStaysAshore()
	{
		List<TransportMemory> crew = Arrays.asList(golem(GolemTrait.LIKES_THE_COLD), golem(GolemTrait.LIKES_THE_HEAT),
			golem());
		assertNull(voyage.crewPort(HOME, crew, UNLUCKY, context));
	}

	/** Golems that do not mind where they go always go somewhere. */
	@Test
	public void aCrewThatDoesNotMindGoesAnywhere()
	{
		List<TransportMemory> crew = Arrays.asList(golem(), golem(), golem());
		assertNotNull(voyage.crewPort(HOME, crew, UNLUCKY, context));
	}

	/** A port one of them has just come from is not offered, even to a crew that would like it. */
	@Test
	public void noneOfThemSailsStraightBack()
	{
		TransportMemory back = golem();
		back.setBlockedPort(SNOW.getRowId());
		List<TransportMemory> crew = Arrays.asList(golem(GolemTrait.LIKES_THE_COLD), back, golem());
		assertNull(voyage.crewPort(HOME, crew, UNLUCKY, context));
	}
}

package com.golemsdontdie;

import java.util.*;
import java.util.function.*;
import org.junit.Test;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** A golem goes nowhere it has no way back from. */
public class WaysBackTest
{
	/** Home's space and four others, one per thousand tiles of x; everything on the ground floor. */
	private static final int HOME = GolemContent.PLINTH_X / 1000;

	private static final class Spaces extends WorldMesh
	{
		@Override
		int componentAt(int x, int y, int plane)
		{
			return plane == 0 && x > 0 ? x / 1000 : 0;
		}
	}

	/** A tile in a space. */
	private static int[] in(int space)
	{
		return space == HOME
			? new int[]{GolemContent.PLINTH_X, GolemContent.PLINTH_Y}
			: new int[]{space * 1000 + 500, 100};
	}

	/** Learned routes, the one kind of row a table not loaded from the jar can be given. */
	private static TransportNetwork network(int[]... hops)
	{
		List<int[]> routes = new ArrayList<>();
		int id = 1;
		for (int[] hop : hops)
		{
			int[] from = in(hop[0]);
			int[] to = in(hop[1]);
			routes.add(new int[]{id++, from[0], from[1], 0, to[0], to[1], 0, 1});
		}
		TransportNetwork network = new TransportNetwork();
		network.setLearnedRoutes(routes);
		return network;
	}

	private static GolemTransport row(TransportNetwork network, int from, int to)
	{
		for (GolemTransport t : network.all())
		{
			if (t.getFromX() == in(from)[0] && t.getToX() == in(to)[0])
			{
				return t;
			}
		}
		throw new AssertionError("no row " + from + " to " + to);
	}

	private static boolean comesBack(WaysBack back, WorldMesh mesh, GolemTransport t)
	{
		return back.comesBack(mesh.spacesAt(t.getFromX(), t.getFromY(), t.getFromPlane()), back.landing(t));
	}

	@Test
	public void throughADoorAndBack()
	{
		WorldMesh mesh = new Spaces();
		TransportNetwork network = network(new int[]{HOME, 5}, new int[]{5, HOME});
		WaysBack back = new WaysBack(mesh, network, t -> true);
		back.refresh(0, Collections::emptySet);
		assertTrue(comesBack(back, mesh, row(network, HOME, 5)));
	}

	/**
	 * A drop with no way back up is refused until one is usable, and taken from then on. A drop
	 * whose far side leads home some other way is no trap at all.
	 */
	@Test
	public void notDownADropWithNoWayBack()
	{
		WorldMesh mesh = new Spaces();
		TransportNetwork network = network(new int[]{HOME, 6}, new int[]{6, HOME}, new int[]{HOME, 7},
			new int[]{7, 8}, new int[]{8, HOME});
		GolemTransport climbOut = row(network, 6, HOME);
		boolean[] learned = {false};
		WaysBack back = new WaysBack(mesh, network, t -> t != climbOut || learned[0]);
		back.refresh(0, Collections::emptySet);
		assertFalse("down a drop with no way back", comesBack(back, mesh, row(network, HOME, 6)));
		assertTrue("down a drop into a cave that comes out elsewhere", comesBack(back, mesh, row(network, HOME, 7)));

		learned[0] = true;
		back.refresh(WaysBack.RECHECK_TICKS, Collections::emptySet);
		assertTrue("the way out was learned", comesBack(back, mesh, row(network, HOME, 6)));
	}

	/**
	 * A room whose only way out is back is a dead end; one that leads on through more than a few
	 * spaces is not, nor one with a dock.
	 */
	@Test
	public void aRoomWithOnlyTheWayBackIsADeadEnd()
	{
		WorldMesh mesh = new Spaces();
		TransportNetwork network = network(new int[]{HOME, 5}, new int[]{5, HOME}, new int[]{HOME, 6},
			new int[]{6, HOME}, new int[]{6, 7}, new int[]{7, 6}, new int[]{7, 8}, new int[]{8, 7},
			new int[]{8, 9}, new int[]{9, 8}, new int[]{9, 10}, new int[]{10, 9}, new int[]{10, 11},
			new int[]{11, 10}, new int[]{11, 12}, new int[]{12, 11}, new int[]{12, 13}, new int[]{13, 12},
			new int[]{13, 14}, new int[]{14, 13}, new int[]{14, 15}, new int[]{15, 14}, new int[]{HOME, 16},
			new int[]{16, HOME});
		WaysBack back = new WaysBack(mesh, network, t -> true);
		Set<Integer> ports = new HashSet<>(Arrays.asList(16, 3));
		back.refresh(0, () -> ports);
		assertTrue("a waiting room", deadEnd(back, row(network, HOME, 5)));
		assertFalse("a passage on through ten spaces", deadEnd(back, row(network, HOME, 6)));
		assertFalse("a quay", deadEnd(back, row(network, HOME, 16)));
		assertFalse("a hop within one space", back.isDeadEnd(Collections.singletonList(HOME), Collections.singletonList(HOME)));
	}

	private static boolean deadEnd(WaysBack back, GolemTransport t)
	{
		return back.isDeadEnd(back.setOff(t), back.landing(t));
	}

	/** An island with a dock is no trap while the golem may sail; kept ashore, it is. */
	@Test
	public void anIslandWithADockIsAWayBack()
	{
		WorldMesh mesh = new Spaces();
		TransportNetwork network = network(new int[]{HOME, 9});
		WaysBack back = new WaysBack(mesh, network, t -> true);
		Set<Integer> ports = new HashSet<>(Arrays.asList(HOME, 9));
		back.refresh(0, () -> ports);
		assertTrue("the boat home", comesBack(back, mesh, row(network, HOME, 9)));

		back.refresh(WaysBack.RECHECK_TICKS, Collections::emptySet);
		assertFalse("kept ashore", comesBack(back, mesh, row(network, HOME, 9)));
	}
}

package com.golemsdontdie;

import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/** Golems placed on the world maps as the shipped table says each map draws the game. */
public class WorldMapLayersTest
{
	private final WorldMapLayers layers = new WorldMapLayers();
	private final int[] spot = new int[2];

	@Before
	public void load()
	{
		layers.load();
	}

	/** Taverley Underground draws its upper floor as an inset south of the floor below. */
	@Test
	public void anUpperFloorGoesToItsInset()
	{
		WorldMapLayers.Layer taverley = layers.named("Taverley Underground");
		assertTrue(taverley.place(2944, 9800, 1, spot));
		assertArrayEquals(new int[]{2944, 9608}, spot);
		assertTrue(taverley.place(2944, 9792, 0, spot));
		assertArrayEquals(new int[]{2944, 9792}, spot);
	}

	/** Cam Torum is a map of its own over Neypotzli: one tile, two maps, by floor. */
	@Test
	public void oneTileIsTwoMapsByFloor()
	{
		WorldMapLayers.Layer camTorum = layers.named("Cam Torum");
		WorldMapLayers.Layer neypotzli = layers.named("Neypotzli");
		assertTrue(camTorum.place(1384, 9536, 1, spot));
		assertFalse(neypotzli.place(1384, 9536, 1, spot));
		assertTrue(neypotzli.place(1344, 9536, 0, spot));
		assertFalse(camTorum.place(1344, 9536, 0, spot));
	}

	/** A map that draws none of the test tiles is the surface, which has no layer. */
	@Test
	public void theSurfaceHasNoLayer()
	{
		assertNull(layers.layerOf((x, y) -> false));
	}
}

package com.golemsdontdie;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** The shipped world mesh, format 3: a byte a tile, and water. */
public class WorldMeshTest
{
	private static final WorldMesh MESH = new WorldMesh();

	static
	{
		MESH.load();
	}

	/**
	 * A post standing where four tiles meet refuses all four diagonals across it, though every
	 * edge round it is open. The two-bit map could not say so, and golems cut through it.
	 */
	@Test
	public void aCornerPostRefusesTheDiagonal()
	{
		assertTrue("the edges round the post are open", MESH.north(1235, 3637, 0) && MESH.east(1235, 3637, 0));
		assertTrue(MESH.cornerBlocks(1235, 3637, 0, 1, 1));
		assertTrue(MESH.cornerBlocks(1236, 3638, 0, -1, -1));
		assertTrue(MESH.cornerBlocks(1236, 3637, 0, -1, 1));
		assertTrue(MESH.cornerBlocks(1235, 3638, 0, 1, -1));
		assertFalse("the step beside it is free", MESH.cornerBlocks(1234, 3637, 0, 1, 1));
	}

	/** Wyrmscraig's cave lake is water, not the sea, and none of it is ground. */
	@Test
	public void theCaveLakeIsWater()
	{
		int water = 0;
		for (int x = 2567; x <= 2587; x++)
		{
			for (int y = 8590; y <= 8617; y++)
			{
				if (MESH.isInlandWater(x, y, 0))
				{
					water++;
					assertFalse("lake at " + x + "," + y + " read as ground", MESH.isLandWalkable(x, y, 0));
					assertFalse(MESH.isOcean(x, y, 0));
				}
			}
		}
		assertEquals("the lake's tiles", 276, water);
	}

	/** Home stands on ground: something solid-free with a floor, not the void. */
	@Test
	public void homeIsGround()
	{
		assertTrue(MESH.isWalkable(GolemContent.PLINTH_X, GolemContent.PLINTH_Y, 0));
		assertFalse(MESH.isWater(GolemContent.PLINTH_X, GolemContent.PLINTH_Y, 0));
	}
}

package com.golemsdontdie.telemetry;

import java.io.BufferedReader;
import java.io.StringReader;
import org.junit.Assert;
import org.junit.Test;

/**
 * The obstacle data file on its own, with nothing from the rest of the plugin: what a line holds,
 * how repeats are counted, and that it reads back as it was written.
 */
public class ObstacleDataFileTest
{
	/** The file's contents, or null before it is first written: the plugin's folder, in memory. */
	private String contents;

	private ObstacleDataFile.Store store()
	{
		return new ObstacleDataFile.Store()
		{
			@Override
			public boolean exists()
			{
				return contents != null;
			}

			@Override
			public BufferedReader reader()
			{
				return new BufferedReader(new StringReader(contents));
			}

			@Override
			public void write(String text)
			{
				contents = text;
			}
		};
	}

	@Test
	public void keepsOneLinePerPlayerCrossingAndCountsRepeats() throws Exception
	{
		ObstacleDataFile data = new ObstacleDataFile(store(), "test");
		data.load();
		data.add(stile(3300, 3300, 3300, 3302));
		data.add(stile(3300, 3300, 3300, 3302));
		data.add(stile(3400, 3400, 3400, 3402));
		Assert.assertEquals("the same crossing twice is one line", 2, data.playerLines());
		data.save();

		String[] line = line("P\t12345");
		Assert.assertEquals("the name, with the tab taken out", "Stile here", value("P", line, "name"));
		Assert.assertEquals("seen twice", "2", value("P", line, "seen"));
		Assert.assertEquals("the path, as cycle:along:side", "0:0:0,2:64:0,4:256:0", value("P", line, "path"));

		ObstacleDataFile reloaded = new ObstacleDataFile(store(), "test");
		reloaded.load();
		Assert.assertEquals("both lines survive a restart", 2, reloaded.playerLines());
		reloaded.add(stile(3300, 3300, 3300, 3302));
		reloaded.save();
		Assert.assertEquals("and counting carries on", "3", value("P", line("P\t12345\tStile here\tClimb-over Stile\t839,839\t3\t33\t12\t3300\t3300"), "seen"));
	}

	@Test
	public void measuresHowFarAGolemStrayedFromItsRoute() throws Exception
	{
		ObstacleDataFile data = new ObstacleDataFile(store(), "test");
		data.load();

		// A route two tiles north. From the middle of the start tile the golem drifts half a tile to
		// the east (its right), then lands a quarter of a tile short of the middle of the end tile.
		int x = 3300 * 128 + 64;
		int y = 3300 * 128 + 64;
		int[][] drifted = {{0, x, y}, {10, x + 64, y + 128}, {20, x, y + 224}};
		data.add(new GolemCrossing(12345, 3300, 3300, 0, 3300, 3302, 0, drifted, false));
		int[][] straight = {{0, x, y}, {20, x, y + 256}};
		data.add(new GolemCrossing(12345, 3300, 3300, 0, 3300, 3302, 0, straight, true));
		Assert.assertEquals("one route, one line", 1, data.golemLines());
		data.save();

		String[] line = line("G\t12345");
		Assert.assertEquals("attempts", "2", value("G", line, "attempts"));
		Assert.assertEquals("worst distance off the line: half a tile", "64", value("G", line, "worstSide"));
		Assert.assertEquals("worst landing: a quarter of a tile short", "32", value("G", line, "worstLanding"));
		Assert.assertEquals("started on the start tile", "0", value("G", line, "worstStart"));
		Assert.assertEquals("one attempt hopped over a stone", "1", value("G", line, "overStone"));
		Assert.assertEquals("the latest path, measured along the route", "0:0:0,20:256:0", value("G", line, "path"));
	}

	@Test
	public void sideIsNegativeToTheLeft()
	{
		// Facing north, east is to the right and west to the left.
		Assert.assertArrayEquals(new int[]{0, 64}, ObstacleDataFile.alongAndSide(64, 0, 0, 256));
		Assert.assertArrayEquals(new int[]{0, -64}, ObstacleDataFile.alongAndSide(-64, 0, 0, 256));
		Assert.assertArrayEquals(new int[]{128, 0}, ObstacleDataFile.alongAndSide(0, 128, 0, 256));
	}

	@Test
	public void aFileFromAnotherSchemaIsReplacedNotMisread() throws Exception
	{
		contents = "#schema\t1\nP\t1\t2\t3\n";
		ObstacleDataFile data = new ObstacleDataFile(store(), "test");
		data.load();
		Assert.assertEquals(0, data.playerLines());
	}

	/** A column of a line, by the name the file's own header gives it. */
	private String value(String kind, String[] line, String name) throws Exception
	{
		String[] names = line("#" + kind + "\t");
		for (int i = 0; i < names.length; i++)
		{
			if (names[i].equals(name))
			{
				return line[i];
			}
		}
		throw new AssertionError("no column " + name);
	}

	private String[] line(String startingWith) throws Exception
	{
		for (String line : contents.split("\n"))
		{
			if (line.startsWith(startingWith))
			{
				return line.trim().split("\t", -1);
			}
		}
		throw new AssertionError("no line starting " + startingWith);
	}

	private static PlayerCrossing stile(int fromX, int fromY, int toX, int toY)
	{
		return new PlayerCrossing(12345, "Stile\there", "Climb-over Stile", new int[]{839, 839}, 3, 33, 12,
			fromX, fromY, 0, toX, toY, 0, 0, 2, false,
			new int[][]{{0, 0, 0}, {2, 64, 0}, {4, 256, 0}}, new int[][]{{0, 839}}, 0);
	}
}
